let certWallData   = [];
let certWallFilter = 'all';
let certWallSearch = '';
let certWallSort   = 'tier';
/* Every sort runs both ways, and each one starts in the direction it is
   naturally read in: rarest plaque first for Tier, A→Z for Artist and Title,
   oldest award first for Date. Clicking the sort already in force turns it
   around, so `certWallSortAsc` is what that click flips.

   `asc` below is that starting direction, written as the answer to "is the
   default ascending?" — Tier's is not, because a wall that opened on a screen
   of Gold plaques would bury every Diamond in the library. */
const CWALL_SORTS = [
  // `up`/`down` name what each direction actually does, for the button's tooltip
  // — "ascending" says nothing useful about a wall of plaques.
  { key: 'tier',   label: 'Tier',   asc: false, up: 'Gold → Diamond', down: 'Diamond → Gold' },
  { key: 'artist', label: 'Artist', asc: true,  up: 'A → Z',          down: 'Z → A' },
  { key: 'title',  label: 'Title',  asc: true,  up: 'A → Z',          down: 'Z → A' },
  { key: 'date',   label: 'Date',   asc: true,  up: 'oldest first',   down: 'newest first' },
];
const cwallSortDefaultAsc = k => (CWALL_SORTS.find(s => s.key === k) || { asc: true }).asc;
let certWallSortAsc = cwallSortDefaultAsc(certWallSort);

// ─── THEME SWITCHER ────────────────────────────────────────────
const themeLabel = document.getElementById('themeLabel');
const themeBtns = document.querySelectorAll('.theme-btn');

const THEME_CLASSES = ['navy-light', 'purple', 'purple-light', 'red', 'red-light', 'yellow', 'yellow-light', 'pink', 'pink-light'];

const THEME_DOT_COLORS = {
  'navy-dark': '#1a6eb5', 'navy-light': '#90c4f4',
  'purple': '#7c6af7', 'purple-light': '#c4b8ff',
  'red': '#cc2020', 'red-light': '#ff9999',
  'yellow': '#c8a800', 'yellow-light': '#ffe040',
  'pink': '#cc2090', 'pink-light': '#ffaadd'
};

function applyTheme(theme, preview = false) {
  document.body.classList.remove(...THEME_CLASSES);
  if (theme !== 'navy-dark') document.body.classList.add(theme);
  const normalizedTheme = theme.includes('-') ? theme : theme + '-dark';
  const labelKey = 'tooltip_theme_' + normalizedTheme.replace('-', '_');
  themeLabel.textContent = t(labelKey) || t('tooltip_theme_navy_dark');
  themeBtns.forEach(b => b.classList.toggle('active', b.dataset.theme === theme));
  const dotColor = THEME_DOT_COLORS[theme] || '#1a6eb5';
  document.querySelectorAll('.ctrl-theme-dot').forEach(d => { d.style.background = dotColor; });
  if (!preview) {
    try { localStorage.setItem('dankcharts-theme', theme); } catch (e) { }
  }
}

themeBtns.forEach(btn => {
  btn.addEventListener('click', () => applyTheme(btn.dataset.theme));
  btn.addEventListener('mouseenter', () => applyTheme(btn.dataset.theme, true));
  btn.addEventListener('mouseleave', () => {
    const saved = localStorage.getItem('dankcharts-theme') || 'navy-dark';
    applyTheme(saved, true);
  });
});

// Restore saved preference, defaulting to navy-dark
try {
  const saved = localStorage.getItem('dankcharts-theme') || 'navy-dark';
  applyTheme(saved);
} catch (e) { applyTheme('navy-dark'); }

