// ─── SOURCE BUTTON TOGGLE ──────────────────────────────────────
// Source toggle is now per-section via toggleSectionDisplay('src', section)
// No global initSrcToggle needed — initSectionDisplayToggles handles all sections including src

// ─── CHART ANIMATION ───────────────────────────────────────────
// Opt-in, not opt-out: '1' enables it, anything else (including an unset key)
// leaves charts static on load. Only the automatic replay is gated here — the
// ▶ Animate Chart button above each section works either way.
let chartAnimEnabled = localStorage.getItem('dc_chart_anim') === '1';

// ─── ARTIST SPLITTING ──────────────────────────────────────────
let noArtistSplit = localStorage.getItem('dc_no_artist_split') === '1';

// Artists whose names contain commas — add entries here to prevent incorrect splitting
const ARTIST_COMMA_EXCEPTIONS = [
  "Tyler, The Creator",
  "Earth, Wind & Fire",
];

// Pre-compiled once — avoids recreating RegExp on every splitArtists call
const _ARTIST_EXCEPTION_RES = ARTIST_COMMA_EXCEPTIONS.map((name, i) => ({
  re: new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'),
  token: `__ARTIST_${i}__`,
  name,
}));

// Memo cache for splitArtists — the same artist string repeats across thousands of
// plays, so large libraries (700k+ plays) collapse to one split per unique string.
// Only comma-containing strings are cached (the no-comma fast path is cheaper than a
// Map lookup), so the cache stays valid when noArtistSplit is toggled: that flag is
// checked before the cache is ever consulted. Cached arrays are shared between plays —
// callers must treat p.artists as read-only (they already do).
const _splitArtistsCache = new Map();

// Splits multiple artists using comma as the separator.
// Names listed in ARTIST_COMMA_EXCEPTIONS are protected from splitting.
function splitArtists(artistStr) {
  if (!artistStr) return [];
  if (noArtistSplit || artistStr.indexOf(',') === -1) return [artistStr];
  const cached = _splitArtistsCache.get(artistStr);
  if (cached) return cached;
  let str = artistStr;
  const activeTokens = {};
  for (const { re, token, name } of _ARTIST_EXCEPTION_RES) {
    if (str.toLowerCase().indexOf(name.toLowerCase().slice(0, 5)) !== -1) {
      str = str.replace(re, token);
      activeTokens[token] = name;
    }
  }
  const result = str
    .split(',')
    .map(a => {
      let part = a.trim();
      for (const [tok, orig] of Object.entries(activeTokens)) part = part.replace(tok, orig);
      return part;
    })
    .filter(a => a.length > 0);
  _splitArtistsCache.set(artistStr, result);
  return result;
}

// ─── COMPILATION ALBUMS ────────────────────────────────────────
/* A compilation is one album whose tracks are each credited to a different
   singer — an EFY record, a film soundtrack, a label sampler. Grouping albums
   by their first artist shatters such a record into one album per singer, so
   every album chart, record and certification counts the same album a dozen
   times over, each at a twelfth of its plays.

   Listing an album here merges it back into one, and it does so without
   touching a single play: p.artist and p.artists stay the singer's, so the
   artist charts, the song charts and the song certifications are exactly as
   they were. Only the *album's* credit changes, to Various Artists — and
   because every album key in the app is built from albumArtist(), that one
   substitution merges the album everywhere at once.

   The credit is deliberately the literal English "Various Artists" in every
   language: it is a data value that album keys, image-source preferences and
   Firestore-synced settings are all built from, so it has to stay stable when
   the interface language changes. */
const COMPILATIONS_KEY = 'dc_compilation_albums';
const VARIOUS_ARTISTS  = 'Various Artists';

// Lowercased titles, parsed once. null = not read from localStorage yet.
let _compilationSet = null;
// Called by the Firestore sync when the compilations list arrives from another
// device — album credits change, so the per-play album stamps must retire too.
window.dcResetCompilationsCache = () => { _compilationSet = null; dcInvalidatePlayStamps(); };

// The saved list in the casing the user typed it — what the manager modal lists.
function getCompilationAlbums() {
  try { return JSON.parse(localStorage.getItem(COMPILATIONS_KEY) || '[]'); } catch { return []; }
}

function _compSet() {
  if (_compilationSet === null) {
    _compilationSet = new Set(getCompilationAlbums().map(a => String(a).toLowerCase().trim()));
  }
  return _compilationSet;
}

/* Called once per play inside the chart-building loops, so the empty-set
   fast path matters: users with no compilations pay one .size read. */
function isCompilationAlbum(album) {
  if (!album || album === '—') return false;
  const s = _compSet();
  return s.size > 0 && s.has(album.toLowerCase().trim());
}

// Writes the list and pushes it straight to Firestore with the in-memory value.
// Not dcSaveUserConfig() — that re-reads localStorage and can race the auth
// callback into saving a stale value, which is how the autocorrect rules were
// once lost.
function _saveCompilationAlbums(list) {
  const json = JSON.stringify(list);
  localStorage.setItem(COMPILATIONS_KEY, json);
  _compilationSet = null;
  dcInvalidatePlayStamps();  // albumArtist() moved — _aa/_ak on every play are stale
  if (typeof dcSaveCompilationsToFirestore === 'function') dcSaveCompilationsToFirestore(json);
}

function addCompilationAlbum(title) {
  const name = String(title || '').trim();
  if (!name) return false;
  const list = getCompilationAlbums();
  if (list.some(a => a.toLowerCase() === name.toLowerCase())) return false;
  list.push(name);
  _saveCompilationAlbums(list);
  return true;
}

function removeCompilationAlbum(title) {
  const lc = String(title || '').toLowerCase();
  _saveCompilationAlbums(getCompilationAlbums().filter(a => a.toLowerCase() !== lc));
}

// Primary artist for album grouping — always the first artist so that feat. tracks
// don't split into a separate album entry. Compilations are the exception: they
// are credited to Various Artists so all their singers fold into one album.
// The uncached computation — stampPlays() calls this to fill _aa, so it must
// not read the stamp back or it would recurse.
function _albumArtistRaw(p) {
  if (p.album && isCompilationAlbum(p.album)) return VARIOUS_ARTISTS;
  return (p.artists && p.artists[0]) || p.artist;
}

function albumArtist(p) {
  return p._se === _stampEpoch ? p._aa : _albumArtistRaw(p);
}

// Strips featured/collaboration artists from an artist string and returns just the
// primary artist. Used for Last.fm albumArtist and track.getInfo lookups so that
// "Artist1 feat. Artist2" or "Artist1, Artist2" resolves to "Artist1".
function _primaryArtist(artist) {
  return artist.split(/\s*,\s*|\s+(?:feat\.?|ft\.?|featuring)\s+/i)[0].trim();
}

// Looks up the album for a track from the site's own play data.
// Returns the album name string, or '' if not found.
function _lookupAlbumFromData(title, artist) {
  const tLc = title.toLowerCase();
  const aLc = artist.toLowerCase();
  const match = allPlays.find(p =>
    p.album && p.album !== '—' &&
    p.title  && p.title.toLowerCase()  === tLc &&
    p.artist && p.artist.toLowerCase() === aLc
  );
  return match ? match.album : '';
}

// Key songs by title + artist only (album excluded) so the same song played as a
// single or from an album is counted as one entry in the songs chart.
function songKey(p) {
  if (p._se === _stampEpoch) return p._sk;
  return p.title.toLowerCase().trim() + '|||' + p.artist.toLowerCase().trim();
}

// Returns the best album label for a song: prefers a non-self-titled album
// (i.e. album name !== song title) by play count, falling back to the most common.
function bestAlbum(title, albumCounts) {
  const entries = Object.entries(albumCounts).sort((a, b) => b[1] - a[1]);
  const nonSingle = entries.filter(([a]) => a.toLowerCase().trim() !== title.toLowerCase().trim());
  return nonSingle.length > 0 ? nonSingle[0][0] : entries[0][0];
}

