// ─── LAST.FM SCROBBLE / AUTH ──────────────────────────────────
const SCROBBLE_DEFAULT_KEY    = '16bf00f19c64398611d93beed16c3ab7';
const SCROBBLE_DEFAULT_SECRET = 'cfb0cff4971d817bb8461b7e7c44e67e';

function getScrobbleKey()     { return localStorage.getItem('dc_lfm_api_key')     || SCROBBLE_DEFAULT_KEY; }
function getScrobbleSecret()  { return localStorage.getItem('dc_lfm_api_secret')  || SCROBBLE_DEFAULT_SECRET; }
function getScrobbleSession() { return localStorage.getItem('dc_lfm_session_key') || ''; }
function getScrobbleUser()    { return localStorage.getItem('dc_lfm_session_user')|| ''; }
function getSheetWriteUrl()   { return localStorage.getItem('dc_sheet_write_url') || ''; }

function lfmSig(params, secret) {
  return md5(Object.keys(params).sort().map(k => k + params[k]).join('') + secret);
}

async function lfmPost(params) {
  const key    = getScrobbleKey();
  const secret = getScrobbleSecret();
  if (!key || !secret) throw new Error('API credentials not configured');
  const p = { ...params, api_key: key };
  p.api_sig = lfmSig(p, secret);
  p.format  = 'json';
  const res  = await fetch('https://ws.audioscrobbler.com/2.0/', { method: 'POST', body: new URLSearchParams(p) });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const data = await res.json();
  if (data.error) {
    const err = new Error(data.message || 'Last.fm error ' + data.error);
    err.code = data.error; // 14 = token not authorized, 15 = token expired, 4 = invalid token
    throw err;
  }
  return data;
}

function updateScrobbleBtn() {
  const scrobBtn = document.getElementById('scrobbleBtn');
  if (!scrobBtn) return;
  const hasLfm   = !!(getScrobbleSession() && getScrobbleUser());
  const hasSheet = !!(getSheetWriteUrl() && getDataSource() === 'sheets');
  scrobBtn.style.display = (currentPeriod === 'rawdata' && (hasLfm || hasSheet)) ? '' : 'none';
}

/* ── Connection state ──────────────────────────────────────────
   There are three real states, and the UI used to collapse them into two.
   Opening the Last.fm authorize page proves nothing: the button flipped to
   "I've authorized ✓" the moment the popup opened, whether or not the user
   ever clicked Allow. Only auth.getSession returning a session key proves the
   connection, so nothing here claims "connected" until that call succeeds.

     not connected  → no pending token, no session
     awaiting       → token issued, Last.fm hasn't approved it yet
     connected      → session key in hand (verified)                          */

const LFM_TOKEN_TTL_MS  = 55 * 60 * 1000; // Last.fm tokens die after ~60 min
const LFM_POLL_EVERY_MS = 3000;
const LFM_POLL_MAX      = 60;             // give up watching after ~3 minutes
const LFM_HINT_IDLE     = 'Lets you add and edit plays from this site.';

let _lfmPollTimer = null;
let _lfmPollTries = 0;

// A pending token only counts while it's still young enough to be redeemable.
function getLfmPendingToken() {
  const token = localStorage.getItem('dc_lfm_pending_token');
  if (!token) return '';
  const ts = parseInt(localStorage.getItem('dc_lfm_pending_ts') || '0', 10);
  if (ts && Date.now() - ts > LFM_TOKEN_TTL_MS) { clearLfmPendingToken(); return ''; }
  return token;
}

function clearLfmPendingToken() {
  localStorage.removeItem('dc_lfm_pending_token');
  localStorage.removeItem('dc_lfm_pending_ts');
}

function setLfmHint(text, tone) {
  const hint = document.getElementById('lfmConnectHint');
  if (!hint) return;
  hint.textContent = text;
  hint.style.color = tone === 'err' ? 'var(--rose)' : (tone === 'ok' ? 'var(--green)' : '');
}

function updateLfmAuthStatus() {
  const user      = getScrobbleUser();
  const sess      = getScrobbleSession();
  const pending   = getLfmPendingToken();
  const statusEl  = document.getElementById('lfmAuthStatus');
  const connectBtn= document.getElementById('lfmConnectBtn');
  const disconnBtn= document.getElementById('lfmDisconnectBtn');
  if (sess && user) {
    if (statusEl)   statusEl.innerHTML = `<span class="lfm-auth-dot connected"></span> Connected as <strong>${esc(user)}</strong>`;
    if (connectBtn) connectBtn.style.display = 'none';
    if (disconnBtn) { disconnBtn.style.display = ''; disconnBtn.textContent = 'Disconnect'; }
  } else if (pending) {
    // Honest middle state: we asked, Last.fm hasn't said yes yet.
    if (statusEl)   statusEl.innerHTML = '<span class="lfm-auth-dot pending"></span> Waiting for your approval on Last.fm';
    if (connectBtn) { connectBtn.style.display = ''; connectBtn.textContent = 'Check now'; connectBtn.disabled = false; }
    if (disconnBtn) { disconnBtn.style.display = ''; disconnBtn.textContent = 'Cancel'; }
  } else {
    if (statusEl)   statusEl.innerHTML = '<span class="lfm-auth-dot"></span> Not connected';
    if (connectBtn) { connectBtn.style.display = ''; connectBtn.textContent = 'Connect to Last.fm'; connectBtn.disabled = false; }
    if (disconnBtn) disconnBtn.style.display = 'none';
  }
  updateScrobbleBtn();
}

function lfmAuthBtnClick() {
  if (getLfmPendingToken()) lfmAuthVerify(false);
  else lfmAuthConnect();
}

async function lfmAuthConnect() {
  const keyEl    = document.getElementById('srcLfmApiKey');
  const secretEl = document.getElementById('srcLfmApiSecret');
  if (keyEl?.value.trim())    localStorage.setItem('dc_lfm_api_key',    keyEl.value.trim());
  if (secretEl?.value.trim()) localStorage.setItem('dc_lfm_api_secret', secretEl.value.trim());

  const key    = getScrobbleKey();
  const secret = getScrobbleSecret();
  if (!key || !secret) {
    setLfmHint('Enter your API key and secret above first.', 'err');
    return;
  }
  const btn = document.getElementById('lfmConnectBtn');
  btn.disabled = true;
  btn.textContent = 'Getting token…';
  try {
    const data = await lfmPost({ method: 'auth.getToken' });
    localStorage.setItem('dc_lfm_pending_token', data.token);
    localStorage.setItem('dc_lfm_pending_ts', String(Date.now()));
    window.open(`https://www.last.fm/api/auth/?api_key=${encodeURIComponent(key)}&token=${encodeURIComponent(data.token)}`, '_blank');
    updateLfmAuthStatus();
    setLfmHint('Click Allow on the Last.fm tab that just opened. This page checks on its own and switches to Connected once it goes through.');
    lfmAuthStartPolling();
  } catch (e) {
    clearLfmPendingToken();
    updateLfmAuthStatus();
    setLfmHint('Could not reach Last.fm: ' + e.message, 'err');
  }
}

/* The only place a connection is ever confirmed. `silent` is true for the
   background poll, which shouldn't shout on every unauthorized answer. */
async function lfmAuthVerify(silent) {
  const token = getLfmPendingToken();
  if (!token) { updateLfmAuthStatus(); return false; }
  const btn = document.getElementById('lfmConnectBtn');
  if (!silent && btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
  try {
    const data = await lfmPost({ method: 'auth.getSession', token });
    if (!data?.session?.key) throw new Error('No session returned');
    localStorage.setItem('dc_lfm_session_key',  data.session.key);
    localStorage.setItem('dc_lfm_session_user', data.session.name);
    clearLfmPendingToken();
    lfmAuthStopPolling();
    updateLfmAuthStatus();
    setLfmHint(`Verified. Scrobbling as ${data.session.name}.`, 'ok');
    // On Sheets/CSV this connection is the only thing standing between the user and
    // the live bar — light it up now rather than waiting for the next sync.
    startNowPlaying();
    return true;
  } catch (e) {
    // 14 = token issued but not authorized yet — the normal "still waiting" answer.
    const notYet = e.code === 14;
    if (!notYet) clearLfmPendingToken(); // expired/invalid token: start over
    if (!notYet) lfmAuthStopPolling();
    updateLfmAuthStatus();
    if (!silent) {
      setLfmHint(notYet
        ? 'Not authorized yet. Finish the Allow step on the Last.fm tab, then check again.'
        : 'That authorization expired. Hit Connect to Last.fm to start again.', 'err');
    }
    return false;
  }
}

// Poll while the user is off approving in the other tab, so they come back to
// a status that already says Connected instead of another button to press.
function lfmAuthStartPolling() {
  lfmAuthStopPolling();
  _lfmPollTries = 0;
  _lfmPollTimer = setInterval(async () => {
    const modal = document.getElementById('sourceModal');
    if (!modal || !modal.classList.contains('open')) { lfmAuthStopPolling(); return; }
    if (++_lfmPollTries > LFM_POLL_MAX) {
      lfmAuthStopPolling();
      setLfmHint('Still waiting on Last.fm. Once you have clicked Allow, press Check now.');
      return;
    }
    await lfmAuthVerify(true);
  }, LFM_POLL_EVERY_MS);
}

function lfmAuthStopPolling() {
  if (_lfmPollTimer) { clearInterval(_lfmPollTimer); _lfmPollTimer = null; }
}

function lfmAuthDisconnect() {
  localStorage.removeItem('dc_lfm_session_key');
  localStorage.removeItem('dc_lfm_session_user');
  clearLfmPendingToken();
  lfmAuthStopPolling();
  setLfmHint(LFM_HINT_IDLE);
  updateLfmAuthStatus();
  // Drops the live bar for Sheets/CSV users; a Last.fm-source user keeps theirs,
  // since getNowPlayingUser() still resolves via their charting username.
  startNowPlaying();
}

// ─── SCROBBLE MODAL ────────────────────────────────────────────
function scrobbleDatetimeLocal(d) {
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 19);
}

function openScrobbleModal() {
  document.getElementById('scrobbleModal').classList.add('open');
  document.getElementById('scrobbleArtist').value = '';
  document.getElementById('scrobbleTrack').value  = '';
  document.getElementById('scrobbleAlbum').value  = '';
  document.getElementById('scrobbleStatus').textContent = '';
  document.getElementById('scrobbleStatus').className   = 'scrobble-status';
  setScrobbleNow();

  const hasLfm   = !!(getScrobbleSession() && getScrobbleUser());
  const hasSheet = !!(getSheetWriteUrl() && getDataSource() === 'sheets');
  document.getElementById('scrobbleSubmitBtn').style.display = hasLfm   ? '' : 'none';
  document.getElementById('scrobbleSheetBtn').style.display  = hasSheet ? '' : 'none';
  document.getElementById('scrobbleNoTarget').style.display  = (!hasLfm && !hasSheet) ? '' : 'none';
}

function closeScrobbleModal() {
  document.getElementById('scrobbleModal').classList.remove('open');
}

function setScrobbleNow() {
  const now = new Date();
  now.setMilliseconds(0);
  document.getElementById('scrobbleTime').value = scrobbleDatetimeLocal(now);
}

function setEditScrobbleNow() {
  const now = new Date();
  now.setMilliseconds(0);
  document.getElementById('editScrobbleTime').value = scrobbleDatetimeLocal(now);
}

async function submitScrobble() {
  const artist  = document.getElementById('scrobbleArtist').value.trim();
  const track   = document.getElementById('scrobbleTrack').value.trim();
  const album   = document.getElementById('scrobbleAlbum').value.trim();
  const timeVal = document.getElementById('scrobbleTime').value;
  const statusEl= document.getElementById('scrobbleStatus');

  if (!artist || !track) {
    statusEl.textContent = 'Artist and Track are required.';
    statusEl.className   = 'scrobble-status err';
    return;
  }
  const timestamp = Math.floor(new Date(timeVal).getTime() / 1000);
  if (isNaN(timestamp)) {
    statusEl.textContent = 'Invalid date/time.';
    statusEl.className   = 'scrobble-status err';
    return;
  }

  const btn = document.getElementById('scrobbleSubmitBtn');
  btn.disabled = true;
  statusEl.textContent = 'Scrobbling…';
  statusEl.className   = 'scrobble-status loading';

  try {
    const params = { method: 'track.scrobble', artist, track, timestamp: String(timestamp), sk: getScrobbleSession() };
    if (album) params.album = album;
    const primaryArt = _primaryArtist(artist);
    if (primaryArt !== artist) params.albumArtist = primaryArt;
    await lfmPost(params);
    statusEl.textContent = '✓ Scrobbled successfully!';
    statusEl.className   = 'scrobble-status ok';
    setTimeout(closeScrobbleModal, 1500);
  } catch (e) {
    statusEl.textContent = 'Error: ' + e.message;
    statusEl.className   = 'scrobble-status err';
  }
  btn.disabled = false;
}

async function submitToSheet() {
  const artist  = document.getElementById('scrobbleArtist').value.trim();
  const track   = document.getElementById('scrobbleTrack').value.trim();
  const album   = document.getElementById('scrobbleAlbum').value.trim();
  const timeVal = document.getElementById('scrobbleTime').value;
  const statusEl= document.getElementById('scrobbleStatus');

  if (!artist || !track) {
    statusEl.textContent = 'Artist and Track are required.';
    statusEl.className   = 'scrobble-status err';
    return;
  }
  const timestamp = Math.floor(new Date(timeVal).getTime() / 1000);
  if (isNaN(timestamp)) {
    statusEl.textContent = 'Invalid date/time.';
    statusEl.className   = 'scrobble-status err';
    return;
  }

  const writeUrl = getSheetWriteUrl();
  if (!writeUrl) {
    statusEl.textContent = 'No Apps Script URL configured.';
    statusEl.className   = 'scrobble-status err';
    return;
  }

  const btn = document.getElementById('scrobbleSheetBtn');
  btn.disabled = true;
  statusEl.textContent = 'Adding to sheet…';
  statusEl.className   = 'scrobble-status loading';

  try {
    const res  = await fetch(writeUrl, {
      method: 'POST',
      body: JSON.stringify({ artist, track, album, timestamp }),
    });
    const data = await res.json();
    if (data.status === 'error') throw new Error(data.message || 'Script error');
    statusEl.textContent = '✓ Added to sheet!';
    statusEl.className   = 'scrobble-status ok';
    setTimeout(closeScrobbleModal, 1500);
  } catch (e) {
    const msg = e.message === 'Failed to fetch'
      ? 'Could not reach the Apps Script. Check that it is deployed as a Web App with access set to "Anyone".'
      : e.message;
    statusEl.textContent = 'Error: ' + msg;
    statusEl.className   = 'scrobble-status err';
  }
  btn.disabled = false;
}

function copyAppsScript() {
  const code = document.getElementById('appsScriptCode').textContent;
  navigator.clipboard.writeText(code).then(() => {
    const btn = document.getElementById('copyAppsScriptBtn');
    btn.textContent = '✓ Copied';
    setTimeout(() => { btn.textContent = 'Copy the script'; }, 2000);
  });
}

// The script slab is ~200 lines and only a handful of people ever read it, so
// it stays collapsed and copying is the primary action. Reading it is opt-in.
function toggleAppsScript(btn) {
  const pre = document.getElementById('appsScriptCode');
  if (!pre) return;
  const show = pre.hidden;
  pre.hidden = !show;
  btn.textContent = show ? 'Hide it' : 'View it';
  btn.setAttribute('aria-expanded', show ? 'true' : 'false');
}

// ─── AUTO-CORRECT RULES ───────────────────────────────────────

const RULES_KEY = 'dc_autocorrect_rules';

let _rulesCache = null;
window.dcResetRulesCache = () => { _rulesCache = null; };

async function initRulesCache() {
  const idbData = await loadFromIDB(IDB_RULES_KEY).catch(() => null);
  const idbRules = (idbData && Array.isArray(idbData.rules)) ? idbData.rules : null;
  const localRules = (() => { try { return JSON.parse(localStorage.getItem(RULES_KEY) || '[]'); } catch { return []; } })();
  if (idbRules) {
    _rulesCache = [...idbRules];
    for (const r of localRules) {
      const key = r.match.artist + '|' + r.match.title + '|' + r.match.album;
      if (!_rulesCache.some(s => s.match.artist + '|' + s.match.title + '|' + s.match.album === key)) {
        _rulesCache.push(r);
      }
    }
  } else {
    _rulesCache = localRules;
  }
  if (_rulesCache.length > 0) {
    localStorage.setItem(RULES_KEY, JSON.stringify(_rulesCache));
    saveToIDB(IDB_RULES_KEY, { rules: _rulesCache }).catch(() => {});
  }
}

function getAutocorrectRules() {
  if (_rulesCache !== null) return _rulesCache;
  // Cache the parse — this runs on every sync/poll/parse pass, and re-parsing a large
  // rules JSON from localStorage each time is wasted work. Safe to pre-populate here:
  // initRulesCache() unconditionally overwrites _rulesCache once the IDB merge lands,
  // and dcResetRulesCache() still forces a fresh read by nulling it.
  try { _rulesCache = JSON.parse(localStorage.getItem(RULES_KEY) || '[]'); } catch { _rulesCache = []; }
  return _rulesCache;
}

function saveAutocorrectRule(origArtist, origTitle, origAlbum, newArtist, newTitle, newAlbum, { skipSheetSync = false } = {}) {
  const rules = getAutocorrectRules().filter(r =>
    !(r.match.artist === origArtist && r.match.title === origTitle && r.match.album === origAlbum)
  );
  rules.push({
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 5),
    match:   { artist: origArtist, title: origTitle, album: origAlbum },
    replace: { artist: newArtist,  title: newTitle,  album: newAlbum  },
    createdAt: Date.now()
  });
  _rulesCache = rules;
  const rulesJson = JSON.stringify(rules);
  localStorage.setItem(RULES_KEY, rulesJson);
  saveToIDB(IDB_RULES_KEY, { rules }).catch(() => {});
  if (!skipSheetSync) syncRulesToSheet();
  if (typeof dcSaveRulesToFirestore === 'function') dcSaveRulesToFirestore(rulesJson);
}

function deleteAutocorrectRule(id) {
  const rules = getAutocorrectRules().filter(r => r.id !== id);
  _rulesCache = rules;
  const rulesJson = JSON.stringify(rules);
  localStorage.setItem(RULES_KEY, rulesJson);
  saveToIDB(IDB_RULES_KEY, { rules }).catch(() => {});
  syncRulesToSheet();
  renderRulesList();
  if (typeof dcSaveRulesToFirestore === 'function') dcSaveRulesToFirestore(rulesJson);
}

function findSimilarRules(origArtist, origTitle, origAlbum) {
  const aLow = origArtist.toLowerCase();
  const tLow = origTitle.toLowerCase();
  return getAutocorrectRules().filter(r =>
    r.match.artist.toLowerCase() === aLow &&
    r.match.title.toLowerCase()  === tLow
  );
}

function overrideSimilarRules(similar) {
  if (!similar.length) return;
  const ids  = new Set(similar.map(r => r.id));
  const rules = getAutocorrectRules().filter(r => !ids.has(r.id));
  _rulesCache  = rules;
  const json   = JSON.stringify(rules);
  localStorage.setItem(RULES_KEY, json);
  saveToIDB(IDB_RULES_KEY, { rules }).catch(() => {});
  if (typeof dcSaveRulesToFirestore === 'function') dcSaveRulesToFirestore(json);
}

function closeSimilarRuleModal() {
  document.getElementById('similarRuleModal').classList.remove('open');
}

async function applyRuleToSheet(matchArtist, matchTitle, matchAlbum, newArtist, newTitle, newAlbum) {
  const writeUrl = getSheetWriteUrl();
  if (!writeUrl) return { updated: 0, error: 'No sheet URL' };
  try {
    const res = await fetch(writeUrl, {
      method: 'POST',
      body: JSON.stringify({
        action: 'batchUpdate',
        matchArtist,
        matchTitle,
        matchAlbum: matchAlbum === '—' ? '' : matchAlbum,
        artist: newArtist,
        track:  newTitle,
        album:  newAlbum === '—' ? '' : newAlbum,
      }),
    });
    const data = await res.json();
    return { updated: data.updated || 0, error: data.status === 'error' ? (data.message || 'Script error') : null };
  } catch (e) {
    return { updated: 0, error: e.message };
  }
}

function checkSimilarRules(origArtist, origTitle, origAlbum, newArtist, newTitle, newAlbum) {
  const similar = findSimilarRules(origArtist, origTitle, origAlbum);
  if (!similar.length) return Promise.resolve({ choice: 'add', idsToRemove: [] });
  return new Promise(resolve => {
    const details = document.getElementById('similarRuleDetails');
    const hasSheet = !!(getSheetWriteUrl() && getDataSource() === 'sheets');
    details.innerHTML =
      `<div style="font-size:0.72rem;color:var(--text3);margin-bottom:0.5rem">Check the rules below to remove them when saving. Uncheck any you want to keep.</div>` +
      similar.map((r, i) => `
        <div data-rule-row="${i}" style="padding-bottom:0.5rem;margin-bottom:0.5rem;border-bottom:1px solid var(--border)">
          <div style="display:flex;align-items:flex-start;gap:0.5rem">
            <label style="display:flex;align-items:flex-start;gap:0.55rem;cursor:pointer;flex:1">
              <input type="checkbox" class="similar-rule-cb" data-idx="${i}" checked style="margin-top:0.25rem;flex-shrink:0;cursor:pointer">
              <div style="line-height:1.6">
                <div>Match: <span style="color:var(--text2)">${esc(r.match.artist)} &mdash; ${esc(r.match.title)} &mdash; ${esc(r.match.album)}</span></div>
                <div>&rarr; Replace: <span style="color:var(--accent)">${esc(r.replace.artist)} &mdash; ${esc(r.replace.title)} &mdash; ${esc(r.replace.album)}</span></div>
              </div>
            </label>
            ${hasSheet ? `<button class="similar-rule-run-btn" data-idx="${i}" style="flex-shrink:0;font-size:0.7rem;padding:0.2rem 0.5rem;border:1px solid var(--border);border-radius:3px;background:var(--bg2);color:var(--text2);cursor:pointer;align-self:center">Run</button>` : ''}
            <button class="similar-rule-del-btn" data-idx="${i}" title="Delete this rule" style="flex-shrink:0;padding:0.15rem 0.4rem;border:1px solid var(--border);border-radius:3px;background:var(--bg2);color:#ef4444;cursor:pointer;align-self:center;font-size:0.9rem;line-height:1">🗑</button>
          </div>
          <div class="similar-rule-run-status" data-idx="${i}" style="font-size:0.7rem;margin-top:0.25rem;display:none"></div>
        </div>
      `).join('') +
      `<div style="margin-top:0.3rem;line-height:1.6">
        <div style="color:var(--text3);font-size:0.72rem;margin-bottom:0.1rem">New rule being saved:</div>
        <div>Match: <span style="color:var(--text2)">${esc(origArtist)} &mdash; ${esc(origTitle)} &mdash; ${esc(origAlbum || '&mdash;')}</span></div>
        <div>&rarr; Replace: <span style="color:var(--accent)">${esc(newArtist)} &mdash; ${esc(newTitle)} &mdash; ${esc(newAlbum || '&mdash;')}</span></div>
      </div>`;

    details.querySelectorAll('.similar-rule-run-btn').forEach(btn => {
      btn.addEventListener('click', async () => {
        const r = similar[parseInt(btn.dataset.idx)];
        const statusEl = details.querySelector(`.similar-rule-run-status[data-idx="${btn.dataset.idx}"]`);
        btn.disabled = true;
        btn.textContent = '…';
        if (statusEl) { statusEl.style.display = ''; statusEl.textContent = 'Running…'; statusEl.style.color = 'var(--text3)'; }
        const result = await applyRuleToSheet(r.match.artist, r.match.title, r.match.album, r.replace.artist, r.replace.title, r.replace.album);
        btn.disabled = false;
        btn.textContent = 'Run';
        if (statusEl) {
          if (result.error) {
            statusEl.textContent = 'Failed: ' + result.error;
            statusEl.style.color = 'var(--err, #ef4444)';
          } else {
            statusEl.textContent = `✓ ${result.updated} entr${result.updated === 1 ? 'y' : 'ies'} updated in sheet`;
            statusEl.style.color = 'var(--accent)';
          }
        }
      });
    });

    details.querySelectorAll('.similar-rule-del-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const r = similar[parseInt(btn.dataset.idx)];
        deleteAutocorrectRule(r.id);
        details.querySelector(`[data-rule-row="${btn.dataset.idx}"]`).remove();
      });
    });

    function getSelectedToRemove() {
      return [...document.querySelectorAll('.similar-rule-cb:checked')]
        .map(el => similar[parseInt(el.dataset.idx)]);
    }

    const runBtn = document.getElementById('similarRuleRunBtn');
    runBtn.style.display = hasSheet ? '' : 'none';
    document.getElementById('similarRuleCancelBtn').onclick   = () => { closeSimilarRuleModal(); resolve({ choice: 'cancel',   idsToRemove: [] }); };
    document.getElementById('similarRuleAddBtn').onclick      = () => { closeSimilarRuleModal(); resolve({ choice: 'add',      idsToRemove: [] }); };
    document.getElementById('similarRuleOverrideBtn').onclick = () => { closeSimilarRuleModal(); resolve({ choice: 'override', idsToRemove: getSelectedToRemove() }); };
    runBtn.onclick                                            = () => { closeSimilarRuleModal(); resolve({ choice: 'run',      idsToRemove: getSelectedToRemove() }); };
    document.getElementById('similarRuleModal').classList.add('open');
  });
}

function applyAutocorrectRules(plays) {
  const rules = getAutocorrectRules();
  if (!rules.length) return plays;
  // Index rules by their exact match key for O(1) lookup per play. The old
  // rules.find() scan was O(plays × rules) — with large libraries (700k+ plays)
  // that meant hundreds of millions of string comparisons blocking the main
  // thread on every load. JSON.stringify (not a plain join) avoids field-collision
  // false matches — e.g. artist:"Taylor"+title:"Swift Song" must not collide with
  // artist:"Taylor Swift"+title:"Song", which a space- or comma-joined key would.
  const ruleKey = (artist, title, album) => JSON.stringify([artist, title, album]);
  const ruleMap = new Map();
  for (const r of rules) {
    const key = ruleKey(r.match.artist, r.match.title, r.match.album);
    if (!ruleMap.has(key)) ruleMap.set(key, r); // first rule wins, same as rules.find()
  }
  return plays.map(p => {
    const rule = ruleMap.get(ruleKey(p.artist, p.title, p.album));
    if (!rule) return p;
    const artist = rule.replace.artist;
    const title  = rule.replace.title;
    const album  = rule.replace.album;
    // _se: 0 drops any derived-key stamp the spread copied over. The rule just
    // rewrote the title/artist/album those keys were built from, so an inherited
    // stamp would look current while describing the pre-correction song.
    return { ...p, artist, title, album, artists: splitArtists(artist),
      _se: 0, _corrected: true, _orig: { artist: p.artist, title: p.title, album: p.album } };
  });
}

async function autoCorrectEntries(plays, writeUrl) {
  const rules = getAutocorrectRules();
  if (!rules.length) return;
  // Build the full rule map without filtering by local plays. The local plays may already
  // have corrected values (e.g. after a batchUpdate saves corrected CSV to IDB), which would
  // cause the filter to skip rules that still have uncorrected entries in the actual sheet.
  const activeRulesMap = {};
  for (const rule of rules) {
    const matchAlbum = rule.match.album === '—' ? '' : rule.match.album;
    const key = rule.match.artist + '|' + rule.match.title + '|' + matchAlbum;
    activeRulesMap[key] = {
      artist: rule.replace.artist,
      track:  rule.replace.title,
      album:  rule.replace.album === '—' ? '' : rule.replace.album,
    };
  }
  if (!Object.keys(activeRulesMap).length) return;
  try {
    const res = await fetch(writeUrl, {
      method: 'POST',
      body: JSON.stringify({ action: 'applyRules', rules: activeRulesMap })
    });
    const data = await res.json();
    if (data.status !== 'error' && data.updated > 0) {
      const prevMsg = _lastSyncStatusMsg;
      const prevCls = _lastSyncStatusCls;
      setSyncStatus(`✓ Auto-corrected ${data.updated} entr${data.updated === 1 ? 'y' : 'ies'} in sheet.`, 'ok');
      const dismissBtn = document.getElementById('syncDismissBtn');
      dismissBtn.style.display = '';
      dismissBtn.onclick = () => {
        setSyncStatus(prevMsg, prevCls);
        dismissBtn.style.display = 'none';
      };
    } else if (data.status === 'error')
      console.warn('Auto-correct: sheet update failed:', data.message);
  } catch (e) {
    console.warn('Auto-correct: sheet update failed:', e.message);
  }
}

async function syncRulesToSheet() {
  const writeUrl = getSheetWriteUrl();
  if (!writeUrl) return;
  try {
    await fetch(writeUrl, {
      method: 'POST',
      body: JSON.stringify({ action: 'saveRules', rules: JSON.stringify(getAutocorrectRules()) }),
    });
  } catch { /* silently skip if sheet unreachable */ }
}

// Returns true when the merged rule set differs from what was cached locally —
// callers use this to know whether already-loaded plays need the rules re-applied.
async function loadRulesFromSheet() {
  const writeUrl = getSheetWriteUrl();
  if (!writeUrl) return false;
  try {
    const res = await fetch(writeUrl, { method: 'POST', body: JSON.stringify({ action: 'loadRules' }) });
    if (!res.ok) return false;
    const data = await res.json();
    if (data.status !== 'ok' || !data.rules) return false;
    const sheetRules = JSON.parse(data.rules);
    if (!Array.isArray(sheetRules)) return false;
    const local = getAutocorrectRules();
    const localJsonBefore = JSON.stringify(local);
    const merged = [...sheetRules];
    let addedFromLocal = 0;
    for (const r of local) {
      const key = r.match.artist + '|' + r.match.title + '|' + r.match.album;
      if (!merged.some(s => s.match.artist + '|' + s.match.title + '|' + s.match.album === key)) {
        merged.push(r);
        addedFromLocal++;
      }
    }
    _rulesCache = merged;
    const mergedJson = JSON.stringify(merged);
    localStorage.setItem(RULES_KEY, mergedJson);
    saveToIDB(IDB_RULES_KEY, { rules: merged }).catch(() => {});
    if (addedFromLocal > 0) syncRulesToSheet();
    if (typeof dcSaveRulesToFirestore === 'function') dcSaveRulesToFirestore(mergedJson);
    return mergedJson !== localJsonBefore;
  } catch { /* silently skip if sheet unreachable */ }
  return false;
}

function exportRules() {
  const rules = getAutocorrectRules();
  if (!rules.length) { alert('No rules to export.'); return; }
  const blob = new Blob([JSON.stringify(rules, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'autocorrect-rules.json';
  a.click();
  URL.revokeObjectURL(url);
}

function importRules() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = '.json,application/json';
  input.onchange = async e => {
    const file = e.target.files[0];
    if (!file) return;
    try {
      const imported = JSON.parse(await file.text());
      if (!Array.isArray(imported)) throw new Error('invalid format');
      const existing = getAutocorrectRules();
      let added = 0;
      for (const r of imported) {
        const key = r.match?.artist + '|' + r.match?.title + '|' + r.match?.album;
        if (!existing.some(x => x.match.artist + '|' + x.match.title + '|' + x.match.album === key)) {
          existing.push(r);
          added++;
        }
      }
      _rulesCache = existing;
      const rulesJson = JSON.stringify(existing);
      localStorage.setItem(RULES_KEY, rulesJson);
      saveToIDB(IDB_RULES_KEY, { rules: existing }).catch(() => {});
      renderRulesList();
      syncRulesToSheet();
      if (typeof dcSaveRulesToFirestore === 'function') dcSaveRulesToFirestore(rulesJson);
      const skipped = imported.length - added;
      alert(`Imported ${added} new rule${added !== 1 ? 's' : ''}${skipped ? ` (${skipped} duplicate${skipped !== 1 ? 's' : ''} skipped)` : ''}.`);
    } catch { alert('Could not import: invalid JSON file.'); }
  };
  input.click();
}

function openRulesModal() {
  const search = document.getElementById('rulesSearch');
  if (search) search.value = '';
  renderRulesList();
  document.getElementById('rulesModal').classList.add('open');
}

function closeRulesModal() {
  document.getElementById('rulesModal').classList.remove('open');
}

function renderRulesList() {
  const allRules = getAutocorrectRules();
  const el = document.getElementById('rulesList');
  const q = (document.getElementById('rulesSearch')?.value || '').trim().toLowerCase();
  const rules = q
    ? allRules.filter(r => [r.match.artist, r.match.title, r.match.album, r.replace.artist, r.replace.title, r.replace.album].some(s => s.toLowerCase().includes(q)))
    : allRules;
  if (!allRules.length) {
    el.innerHTML = '<p style="font-size:0.8rem;color:var(--text3);text-align:center;padding:1rem 0">No rules saved yet.</p>';
    return;
  }
  if (!rules.length) {
    el.innerHTML = '<p style="font-size:0.8rem;color:var(--text3);text-align:center;padding:1rem 0">No rules match your search.</p>';
    return;
  }
  el.innerHTML = rules.map(r => `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;padding:0.5rem 0;border-bottom:1px solid var(--border);gap:0.7rem">
      <div style="font-size:0.75rem;flex:1;min-width:0;line-height:1.5">
        <div style="color:var(--text3)">Match: <span style="color:var(--text2)">${esc(r.match.artist)} &mdash; ${esc(r.match.title)} &mdash; ${esc(r.match.album)}</span></div>
        <div style="color:var(--text3)">&rarr; Replace: <span style="color:var(--accent)">${esc(r.replace.artist)} &mdash; ${esc(r.replace.title)} &mdash; ${esc(r.replace.album)}</span></div>
      </div>
      <button onclick="deleteAutocorrectRule('${esc(r.id)}')" style="flex-shrink:0;font-size:0.72rem;padding:0.2rem 0.5rem;border:1px solid var(--border);border-radius:3px;background:var(--bg2);color:var(--text2);cursor:pointer">Delete</button>
    </div>
  `).join('');
}

// ─── COMPILATION ALBUMS MANAGER ───────────────────────────────
/* The list lives in Settings, but the switch that matters is on the album
   itself — see the toggle openAlbumModal() writes. Both land here, and both
   end in a full rebuild: albumArtist() feeds every chart key in the app, so a
   change to it cannot be repainted, only recomputed. */

function openCompilationsModal() {
  /* Typing an album title by hand invites a near-miss that silently matches
     nothing, so the field suggests from the titles actually in the data. Albums
     that are already listed are left out of the suggestions. */
  const dl = document.getElementById('compilationsDatalist');
  if (dl) {
    const listed = new Set(getCompilationAlbums().map(a => a.toLowerCase()));
    const titles = new Set();
    for (const p of allPlays) {
      if (p.album && p.album !== '—' && !listed.has(p.album.toLowerCase())) titles.add(p.album);
    }
    dl.innerHTML = '';
    for (const title of [...titles].sort((a, b) => a.localeCompare(b))) {
      const opt = document.createElement('option');
      opt.value = title;
      dl.appendChild(opt);
    }
  }
  renderCompilationsList();
  document.getElementById('compilationsModal').classList.add('open');
}

function closeCompilationsModal() {
  document.getElementById('compilationsModal').classList.remove('open');
}

function renderCompilationsList() {
  const el = document.getElementById('compilationsList');
  if (!el) return;
  const list = getCompilationAlbums().slice().sort((a, b) => a.localeCompare(b));
  if (!list.length) {
    el.innerHTML = `<p style="font-size:0.8rem;color:var(--text3);text-align:center;padding:1rem 0">${t('comp_none')}</p>`;
    return;
  }
  el.innerHTML = list.map(function (name) {
    // How many singers this album actually merges — the number is the whole
    // reason the entry exists, so it is worth showing next to it.
    const singers = new Set();
    for (const p of allPlays) {
      if (p.album && p.album.toLowerCase().trim() === name.toLowerCase().trim()) {
        for (const a of (p.artists && p.artists.length ? p.artists : [p.artist])) singers.add(a);
      }
    }
    const note = singers.size ? t('comp_merges', { n: singers.size }) : t('comp_no_plays');
    return `<div style="display:flex;justify-content:space-between;align-items:center;padding:0.5rem 0;border-bottom:1px solid var(--border);gap:0.7rem">
      <div style="font-size:0.78rem;flex:1;min-width:0;line-height:1.4">
        <div style="color:var(--text2)">${esc(name)}</div>
        <div style="color:var(--text3);font-size:0.7rem">${esc(note)}</div>
      </div>
      <button onclick="removeCompilation(${esc(JSON.stringify(name))})" style="flex-shrink:0;font-size:0.72rem;padding:0.2rem 0.5rem;border:1px solid var(--border);border-radius:3px;background:var(--bg2);color:var(--text2);cursor:pointer">${t('comp_remove')}</button>
    </div>`;
  }).join('');
}

// Rebuilds every chart from scratch. albumArtist() decides album identity, so
// nothing short of a full pass can reflect a change to the list.
function _compilationsChanged() {
  // Merging an album rewrites its key, which rewrites when it crossed each
  // threshold — the certification timeline is built from those keys.
  _certTimeline = null;
  // _saveCompilationAlbums() has already retired the old stamps; write the new
  // credits back in before anything reads them.
  stampPlays(allPlays);
  if (typeof renderAll === 'function' && allPlays.length) renderAll();
}

function addCompilationFromInput() {
  const input = document.getElementById('compilationsInput');
  if (!input) return;
  if (addCompilationAlbum(input.value)) {
    input.value = '';
    renderCompilationsList();
    _compilationsChanged();
  }
}

function removeCompilation(name) {
  removeCompilationAlbum(name);
  renderCompilationsList();
  _compilationsChanged();
}

/* The album modal's switch. The album keeps its modal either way — it just
   moves to a different key, because the key carries the credit. Merging sends
   "Efy 2013|||Jenessa Buttars" to "Efy 2013|||Various Artists"; unmerging sends
   it back to whoever sang the first play. So rather than close the window on a
   record that still exists, this reopens it on the key the album now has, which
   is also the clearest possible confirmation that the merge worked: the same
   album, one modal, every play accounted for. */
function toggleAlbumCompilation(albumName, on) {
  if (on) addCompilationAlbum(albumName);
  else removeCompilationAlbum(albumName);
  renderCompilationsList();
  _compilationsChanged();

  // The new key has to be read back from the data, not assumed: unmerging
  // restores the first-played artist, which only the plays know.
  const play = allPlays.find(p => p.album && p.album.toLowerCase() === albumName.toLowerCase());
  const modal = document.getElementById('albumModal');
  if (!play) { if (modal) modal.classList.remove('open'); return; }
  openAlbumModal(albumName + '|||' + albumArtist(play));
}

// ─── EDIT SCROBBLE ────────────────────────────────────────────

let _editPlay    = null;
let _editOrigTs  = 0;
let _editOrigMatch = null;

// Populate artist/track/album datalists from allPlays for autocomplete suggestions
function _populateEditSuggestions() {
  const artists = new Set(), tracks = new Set(), albums = new Set();
  for (const p of allPlays) {
    if (p.artist) artists.add(p.artist);
    if (p.title)  tracks.add(p.title);
    if (p.album && p.album !== '—') albums.add(p.album);
  }
  const fill = (id, vals) => {
    const dl = document.getElementById(id);
    if (!dl) return;
    dl.innerHTML = '';
    for (const v of vals) {
      const opt = document.createElement('option');
      opt.value = v;
      dl.appendChild(opt);
    }
  };
  fill('editArtistList', artists);
  fill('editTrackList',  tracks);
  fill('editAlbumList',  albums);
}

function openEditScrobbleModal(rawIdx) {
  const p = rawFiltered[rawIdx];
  if (!p) return;
  _populateEditSuggestions();
  _editPlay      = p;
  _editOrigTs    = p.date.getTime();
  _editOrigMatch = { artist: p.artist, title: p.title, album: p.album };
  document.getElementById('editScrobbleArtist').value = p.artist;
  document.getElementById('editScrobbleTrack').value  = p.title;
  document.getElementById('editScrobbleAlbum').value  = p.album === '—' ? '' : p.album;
  document.getElementById('editScrobbleTime').value   = scrobbleDatetimeLocal(p.date);
  document.getElementById('editScrobbleStatus').textContent = '';
  document.getElementById('editScrobbleStatus').className   = 'scrobble-status';
  document.getElementById('editApplyAll').checked  = false;
  document.getElementById('editSaveRule').checked  = false;
  const hasLfm   = !!(getScrobbleSession() && getScrobbleUser());
  const hasSheet = !!(getSheetWriteUrl() && getDataSource() === 'sheets');
  document.getElementById('editPushLfmBtn').style.display   = hasLfm   ? '' : 'none';
  document.getElementById('editPushSheetBtn').style.display = hasSheet ? '' : 'none';
  document.getElementById('editScrobbleHint').style.display = hasLfm   ? '' : 'none';
  document.getElementById('editScrobbleModal').classList.add('open');
}

function closeEditScrobbleModal() {
  document.getElementById('editScrobbleModal').classList.remove('open');
  _editPlay      = null;
  _editOrigMatch = null;
}

function _readEditFields() {
  const artist   = document.getElementById('editScrobbleArtist').value.trim();
  const title    = document.getElementById('editScrobbleTrack').value.trim();
  const album    = document.getElementById('editScrobbleAlbum').value.trim();
  const timeVal  = document.getElementById('editScrobbleTime').value;
  const statusEl = document.getElementById('editScrobbleStatus');
  if (!artist || !title) {
    statusEl.textContent = 'Artist and Track are required.';
    statusEl.className   = 'scrobble-status err';
    return null;
  }
  const ts = Math.floor(new Date(timeVal).getTime() / 1000);
  if (isNaN(ts)) {
    statusEl.textContent = 'Invalid date/time.';
    statusEl.className   = 'scrobble-status err';
    return null;
  }
  return { artist, title, album, ts, date: new Date(ts * 1000), statusEl };
}

async function saveEditLocally() {
  const f = _readEditFields();
  if (!f || !_editPlay) return;
  const applyAll = document.getElementById('editApplyAll').checked;
  const saveRule = document.getElementById('editSaveRule').checked;
  const orig     = _editOrigMatch;
  const newAlbum = f.album || '—';
  if (saveRule && orig) {
    const { choice, idsToRemove } = await checkSimilarRules(orig.artist, orig.title, orig.album, f.artist, f.title, newAlbum);
    if (choice === 'cancel') return;
    if ((choice === 'override' || choice === 'run') && idsToRemove.length) overrideSimilarRules(idsToRemove);
    saveAutocorrectRule(orig.artist, orig.title, orig.album, f.artist, f.title, newAlbum);
    if (choice === 'run') {
      applyRuleToSheet(orig.artist, orig.title, orig.album, f.artist, f.title, newAlbum).then(r => {
        const prevMsg = _lastSyncStatusMsg;
        const prevCls = _lastSyncStatusCls;
        if (!r.error) {
          setSyncStatus(`✓ Applied rule: corrected ${r.updated} entr${r.updated === 1 ? 'y' : 'ies'} in sheet.`, 'ok');
          const dismissBtn = document.getElementById('syncDismissBtn');
          if (dismissBtn) {
            dismissBtn.style.display = '';
            dismissBtn.onclick = () => { setSyncStatus(prevMsg, prevCls); dismissBtn.style.display = 'none'; };
          }
        } else {
          setSyncStatus('Rule saved, but sheet apply failed: ' + r.error, 'err');
        }
      });
    }
  }
  if (applyAll && orig) {
    allPlays.forEach(p => {
      if (p.artist === orig.artist && p.title === orig.title && p.album === orig.album) {
        p.title   = f.title;
        p.artist  = f.artist;
        p.artists = splitArtists(f.artist);
        p.album   = newAlbum;
      }
    });
    _editPlay.date = f.date;
  } else {
    _editPlay.title   = f.title;
    _editPlay.artist  = f.artist;
    _editPlay.artists = splitArtists(f.artist);
    _editPlay.album   = newAlbum;
    _editPlay.date    = f.date;
  }
  firstSeenMaps = null;
  _certTimeline = null;   // plays changed — the certification dates move with them
  // Titles, artists, albums and dates were just rewritten in place on live play
  // objects, so their derived keys no longer describe them.
  stampPlays(allPlays);
  if (allPlays.length) {
    window.firstScrobbleDate = _earliestPlayDate();
  }
  renderAll();
  closeEditScrobbleModal();
}

async function pushEditToLastfm() {
  const f = _readEditFields();
  if (!f) return;
  const btn      = document.getElementById('editPushLfmBtn');
  const statusEl = f.statusEl;
  btn.disabled = true;
  statusEl.textContent = 'Pushing to Last.fm…';
  statusEl.className   = 'scrobble-status loading';
  try {
    const params = { method: 'track.scrobble', artist: f.artist, track: f.title, timestamp: String(f.ts), sk: getScrobbleSession() };
    if (f.album) params.album = f.album;
    const primaryArt = _primaryArtist(f.artist);
    if (primaryArt !== f.artist) params.albumArtist = primaryArt;
    await lfmPost(params);
    statusEl.textContent = '✓ Pushed to Last.fm! Remove the original scrobble manually on the Last.fm website.';
    statusEl.className   = 'scrobble-status ok';
  } catch (e) {
    statusEl.textContent = 'Error: ' + e.message;
    statusEl.className   = 'scrobble-status err';
  }
  btn.disabled = false;
}

function _serializePlaysCsv() {
  const pad = n => String(n).padStart(2, '0');
  const esc = v => (v.includes(',') || v.includes('"') || v.includes('\n'))
    ? '"' + v.replace(/"/g, '""') + '"' : v;
  const fmtDate = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  const rows = ['Song Title,Artist,Album,Date and Time'];
  for (const p of allPlays) {
    rows.push([esc(p.title), esc(p.artist), esc(p.album === '—' ? '' : p.album), fmtDate(p.date)].join(','));
  }
  return rows.join('\n');
}

async function pushEditToSheet() {
  const f = _readEditFields();
  if (!f) return;
  const writeUrl = getSheetWriteUrl();
  if (!writeUrl) {
    f.statusEl.textContent = 'No Apps Script URL configured.';
    f.statusEl.className   = 'scrobble-status err';
    return;
  }
  const applyAll = document.getElementById('editApplyAll').checked;
  const saveRule = document.getElementById('editSaveRule').checked;
  const orig     = _editOrigMatch;
  const newAlbum = f.album || '—';
  let _runRuleOnSheet = false;
  if (saveRule && orig) {
    const { choice, idsToRemove } = await checkSimilarRules(orig.artist, orig.title, orig.album, f.artist, f.title, newAlbum);
    if (choice === 'cancel') return;
    if ((choice === 'override' || choice === 'run') && idsToRemove.length) overrideSimilarRules(idsToRemove);
    // skipSheetSync=true so we don't fire a concurrent saveRules request alongside batchUpdate.
    // Apps Script serializes write requests; firing both at once just makes batchUpdate wait in queue.
    // We sync rules after the batchUpdate completes instead.
    saveAutocorrectRule(orig.artist, orig.title, orig.album, f.artist, f.title, newAlbum, { skipSheetSync: true });
    if (choice === 'run') _runRuleOnSheet = true;
  }
  const btn      = document.getElementById('editPushSheetBtn');
  const statusEl = f.statusEl;
  btn.disabled = true;
  let isBatchUpdate = false;
  let _batchDone = 0;
  let _batchTotal = 0;
  try {
    if (applyAll && orig) {
      isBatchUpdate = true;
      const matching = allPlays.filter(p =>
        p.artist === orig.artist && p.title === orig.title && p.album === orig.album
      );
      _batchTotal = matching.length;
      const t0 = Date.now();
      statusEl.textContent = `Updating ${_batchTotal} entr${_batchTotal === 1 ? 'y' : 'ies'} in sheet…`;
      statusEl.className   = 'scrobble-status loading';
      // allPlays has autocorrected values; the sheet has the originals.
      // Reverse-look up the autocorrect rule to find the original artist/title/album
      // that is actually stored in the sheet, so batchUpdate can match on it.
      const acRules = getAutocorrectRules();
      const revRule = acRules.find(r =>
        r.replace.artist === orig.artist &&
        r.replace.title  === orig.title  &&
        r.replace.album  === orig.album
      );
      const matchArtist = revRule ? revRule.match.artist : orig.artist;
      const matchTitle  = revRule ? revRule.match.title  : orig.title;
      const matchAlbum  = (revRule ? revRule.match.album : orig.album).replace(/^—$/, '');
      const batchRes  = await fetch(writeUrl, {
        method: 'POST',
        body: JSON.stringify({
          action: 'batchUpdate',
          matchArtist, matchTitle, matchAlbum,
          artist: f.artist,
          track:  f.title,
          album:  f.album,
        }),
      });
      const batchData = await batchRes.json();
      if (batchData.status === 'error') throw new Error(batchData.message || 'Script error');
      _batchDone = batchData.updated || 0;
      allPlays.forEach(p => {
        if (p.artist === orig.artist && p.title === orig.title && p.album === orig.album) {
          p.title   = f.title;
          p.artist  = f.artist;
          p.artists = splitArtists(f.artist);
          p.album   = newAlbum;
        }
      });
      firstSeenMaps = null;
      _certTimeline = null;   // plays changed — the certification dates move with them
      stampPlays(allPlays);   // rewritten in place — refresh their derived keys
      if (allPlays.length) {
        window.firstScrobbleDate = _earliestPlayDate();
      }
      renderAll();
      saveToIDB(IDB_SHEETS_KEY, { ts: Date.now(), csv: _serializePlaysCsv() }).catch(() => {});
      if (saveRule) syncRulesToSheet();
      const elapsed = ((Date.now() - t0) / 1000).toFixed(1);
      statusEl.textContent = `✓ Updated ${_batchDone} entr${_batchDone === 1 ? 'y' : 'ies'} in sheet! (${elapsed}s)`;
      statusEl.className   = 'scrobble-status ok';
    } else {
      statusEl.textContent = 'Updating sheet…';
      statusEl.className   = 'scrobble-status loading';
      const res  = await fetch(writeUrl, {
        method: 'POST',
        body: JSON.stringify({
          action: 'update',
          originalTimestamp: Math.floor(_editOrigTs / 1000),
          rowNumber: _editPlay._sheetRow,
          artist: f.artist,
          track:  f.title,
          album:  f.album,
          timestamp: f.ts,
        }),
      });
      const data = await res.json();
      if (data.status === 'error') throw new Error(data.message || 'Script error');
      if (!data.updated) throw new Error('Apps Script is outdated — please redeploy the latest version from the setup guide to enable editing.');
      _editPlay.title   = f.title;
      _editPlay.artist  = f.artist;
      _editPlay.artists = splitArtists(f.artist);
      _editPlay.album   = newAlbum;
      _editPlay.date    = f.date;
      firstSeenMaps = null;
      _certTimeline = null;   // plays changed — the certification dates move with them
      stampPlays(allPlays);   // rewritten in place — refresh their derived keys
      if (allPlays.length) {
        window.firstScrobbleDate = _earliestPlayDate();
      }
      renderAll();
      saveToIDB(IDB_SHEETS_KEY, { ts: Date.now(), csv: _serializePlaysCsv() }).catch(() => {});
      if (saveRule) syncRulesToSheet(); // fire-and-forget after update, not before
      if (_runRuleOnSheet) {
        statusEl.textContent = 'Applying rule to all matching entries…';
        statusEl.className   = 'scrobble-status loading';
        const r = await applyRuleToSheet(orig.artist, orig.title, orig.album, f.artist, f.title, newAlbum);
        statusEl.textContent = r.error
          ? `✓ Sheet updated! (Rule apply failed: ${r.error})`
          : `✓ Sheet updated! Rule applied to ${r.updated} entr${r.updated === 1 ? 'y' : 'ies'}.`;
        statusEl.className = 'scrobble-status ok';
      } else {
        statusEl.textContent = '✓ Sheet updated!';
        statusEl.className   = 'scrobble-status ok';
      }
    }
  } catch (e) {
    const isFetchError = e.message === 'Failed to fetch' || e.name === 'TypeError';
    if (isBatchUpdate && isFetchError) {
      allPlays.forEach(p => {
        if (p.artist === orig.artist && p.title === orig.title && p.album === orig.album) {
          p.title   = f.title;
          p.artist  = f.artist;
          p.artists = splitArtists(f.artist);
          p.album   = newAlbum;
        }
      });
      firstSeenMaps = null;
      _certTimeline = null;   // plays changed — the certification dates move with them
      stampPlays(allPlays);   // rewritten in place — refresh their derived keys
      if (allPlays.length) {
        window.firstScrobbleDate = _earliestPlayDate();
      }
      renderAll();
      saveToIDB(IDB_SHEETS_KEY, { ts: Date.now(), csv: _serializePlaysCsv() }).catch(() => {});
      const partial = _batchDone > 0 ? ` (${_batchDone}/${_batchTotal} written)` : '';
      statusEl.textContent = `⚠ Sheet update interrupted${partial}. Local view updated. Reload from sheet to confirm.`;
      statusEl.className   = 'scrobble-status ok';
    } else {
      const msg = isFetchError
        ? 'Could not reach the Apps Script. Check that it is deployed as a Web App with access set to "Anyone".'
        : e.message;
      statusEl.textContent = 'Error: ' + msg;
      statusEl.className   = 'scrobble-status err';
    }
  }
  btn.disabled = false;
}

function bestImage(images) {
  if (!images || !images.length) return null;
  const order = ['extralarge', 'large', 'medium', 'small'];
  for (const size of order) {
    const found = images.find(i => i.size === size && i['#text'] && i['#text'].trim());
    if (found) return found['#text'];
  }
  return null;
}

// Deezer placeholder URLs contain '//' after the image type (no real hash), e.g. /images/artist//500x500-...
// Deezer also serves fixed generic placeholder graphics instead of an empty
// segment — filter those known ids too, or they render as "valid" but
// meaningless stock photos. Two known sentinels seen in the wild:
//   - add318a54acd1985a9f0d38b23b4cee1 — generic silhouette graphic
//   - d41d8cd98f00b204e9800998ecf8427e — literally md5("") — Deezer's search
//     results frequently include a duplicate stub entry (same name, no art)
//     ahead of the real artist/album/track entry, and this hash marks it.
const DEEZER_BLANK_IMAGE_HASHES = ['add318a54acd1985a9f0d38b23b4cee1', 'd41d8cd98f00b204e9800998ecf8427e'];
function deezerValidUrl(url) {
  if (!url) return null;
  if (/\/images\/[^/]+\/\//.test(url)) return null;
  if (DEEZER_BLANK_IMAGE_HASHES.some(h => url.includes(h))) return null;
  return url;
}

// Deezer's picture_xl/big/medium fields on a single search result, first
// non-blank one wins.
function deezerPickImage(entity, prefix) {
  return deezerValidUrl(entity?.[prefix + '_xl']) || deezerValidUrl(entity?.[prefix + '_big']) || deezerValidUrl(entity?.[prefix + '_medium']) || null;
}

function deezerFetch(endpoint) {
  const isLocal = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  const base = isLocal ? 'https://dankcharts.fm/deezer-proxy' : '/deezer-proxy';
  return fetch(base + '?url=' + encodeURIComponent(endpoint));
}

// Common artist names (Panda, Kesha, Jade, Raye…) collide with several
// unrelated Deezer artist profiles of the same name, and Deezer's search
// order doesn't reliably put the famous one first — e.g. "Kesha" can come
// back with the real pop star (4M+ fans) several slots behind an obscure
// same-named artist with a dozen. Ranking exact-name matches by fan count
// picks the one the user actually means; a photo-less stub (nb_fan≈0 and
// filtered by deezerValidUrl anyway) naturally sorts last.
// Returns the *full* ranked, de-duped list (not just the top pick) so the
// click-to-cycle UI can step to the next same-named candidate if the top
// guess is still wrong, instead of jumping straight to a different source.
// Memoized on the artist name so stepping through candidates and the normal
// image-load path share one search request.
const deezerArtistCandidateCache = {};
function deezerArtistImageCandidates(artist) {
  const k = artist.toLowerCase();
  if (k in deezerArtistCandidateCache) return deezerArtistCandidateCache[k];
  const p = (async () => {
    try {
      const r = await deezerFetch(`search/artist?q=${encodeURIComponent(artist)}&limit=10`);
      if (!r.ok) return [];
      const d = await r.json();
      const items = d?.data || [];
      const exact = items
        .filter(x => x.name?.toLowerCase() === artist.toLowerCase())
        .sort((a, b) => (b.nb_fan || 0) - (a.nb_fan || 0));
      const urls = [];
      for (const c of (exact.length ? exact : items)) {
        const url = deezerPickImage(c, 'picture');
        if (url && !urls.includes(url)) urls.push(url);
      }
      return urls;
    } catch (e) { return []; }
  })();
  deezerArtistCandidateCache[k] = p;
  return p;
}

async function deezerArtistImage(artist) {
  const candidates = await deezerArtistImageCandidates(artist);
  return candidates[0] || null;
}

// Album/track candidate lists mirror deezerArtistImageCandidates: name-matched
// results first, then the rest, de-duped — so the picker popover can offer
// every plausible cover, not just the auto-picked top one. Memoized so the
// picker and the normal load path share one search request.
const deezerAlbumCandidateCache = {};
function deezerAlbumImageCandidates(album, artist) {
  const k = artist.toLowerCase() + '|||' + album.toLowerCase();
  if (k in deezerAlbumCandidateCache) return deezerAlbumCandidateCache[k];
  /* No cover art is filed under "Various Artists" — a compilation is listed by
     its title, and matching the credit against the search result would reject
     every real hit. So the title carries the search alone. */
  const comp = artist === VARIOUS_ARTISTS;
  const p = (async () => {
    try {
      const q = comp ? album : artist + ' ' + album;
      const r = await deezerFetch(`search/album?q=${encodeURIComponent(q)}&limit=10`);
      if (!r.ok) return [];
      const d = await r.json();
      const items = d?.data || [];
      const matches = items.filter(x =>
        x.title?.toLowerCase().includes(album.toLowerCase()) &&
        (comp || x.artist?.name?.toLowerCase().includes(artist.toLowerCase().split(/[\s,&]/)[0]))
      );
      const urls = [];
      for (const c of (matches.length ? matches : items)) {
        const url = deezerPickImage(c, 'cover');
        if (url && !urls.includes(url)) urls.push(url);
      }
      return urls;
    } catch (e) { return []; }
  })();
  deezerAlbumCandidateCache[k] = p;
  return p;
}

async function deezerAlbumImage(album, artist) {
  const candidates = await deezerAlbumImageCandidates(album, artist);
  return candidates[0] || null;
}

const deezerTrackCandidateCache = {};
function deezerTrackImageCandidates(track, artist) {
  const k = artist.toLowerCase() + '|||' + track.toLowerCase();
  if (k in deezerTrackCandidateCache) return deezerTrackCandidateCache[k];
  const p = (async () => {
    try {
      const r = await deezerFetch(`search/track?q=${encodeURIComponent(artist + ' ' + track)}&limit=10`);
      if (!r.ok) return [];
      const d = await r.json();
      const items = d?.data || [];
      const matches = items.filter(x =>
        x.title?.toLowerCase().includes(track.toLowerCase()) &&
        x.artist?.name?.toLowerCase().includes(artist.toLowerCase().split(/[\s,&]/)[0])
      );
      const urls = [];
      for (const c of (matches.length ? matches : items)) {
        const url = deezerPickImage(c.album, 'cover');
        if (url && !urls.includes(url)) urls.push(url);
      }
      return urls;
    } catch (e) { return []; }
  })();
  deezerTrackCandidateCache[k] = p;
  return p;
}

async function deezerTrackImage(track, artist) {
  const candidates = await deezerTrackImageCandidates(track, artist);
  return candidates[0] || null;
}

// iTunes returns several results per search; surface each distinct artwork
// as a picker candidate (the single-image getters only take the best match).
async function itunesImageCandidates(type, name, artist, album) {
  try {
    let endpoint;
    if (type === 'artist') {
      endpoint = `https://itunes.apple.com/search?term=${encodeURIComponent(name)}&entity=musicTrack&limit=8&attribute=artistTerm`;
    } else if (type === 'album') {
      endpoint = `https://itunes.apple.com/search?term=${encodeURIComponent(artist + ' ' + album)}&entity=album&limit=8`;
    } else {
      endpoint = `https://itunes.apple.com/search?term=${encodeURIComponent(artist + ' ' + name)}&entity=musicTrack&limit=8`;
    }
    const r = await fetch(endpoint);
    const d = await r.json();
    const size = type === 'album' ? '600x600bb' : '300x300bb';
    const urls = [];
    for (const x of (d?.results || [])) {
      const u = x.artworkUrl100 && x.artworkUrl100.replace('100x100bb', size);
      if (u && !urls.includes(u)) urls.push(u);
    }
    return urls;
  } catch (e) { return []; }
}

// The YouTube key is a shared public quota — once it's exhausted (429/403)
// every remaining image on the page would otherwise keep hitting a dead API
// one at a time, each failing and spamming the console. Trip this breaker on
// the first quota error so the rest of the session skips youtube entirely.
let _ytQuotaExceeded = false;
async function ytSearch(query) {
  if (!YOUTUBE_KEY || _ytQuotaExceeded) return null;
  const q = encodeURIComponent(query);
  const r = await fetch(`https://www.googleapis.com/youtube/v3/search?part=snippet&q=${q}&type=video&maxResults=1&key=${YOUTUBE_KEY}`);
  if (r.status === 429 || r.status === 403) { _ytQuotaExceeded = true; return null; }
  if (!r.ok) return null;
  const d = await r.json();
  const item = d?.items?.[0];
  if (!item) return null;
  const videoId = item.id?.videoId;
  // Try maxresdefault first, fall back to hqdefault (always exists)
  if (videoId) {
    const maxres = `https://img.youtube.com/vi/${videoId}/maxresdefault.jpg`;
    const hq = `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`;
    // maxresdefault returns a grey placeholder for videos without it — use hqdefault as safe fallback
    return item.snippet?.thumbnails?.maxres?.url || item.snippet?.thumbnails?.high?.url || hq;
  }
  return item.snippet?.thumbnails?.high?.url || null;
}

async function getArtistImage(artist, source) {
  source = source || 'deezer';
  const k = 'artist:' + artist.toLowerCase() + ':' + source;
  if (k in imgCache) return imgCache[k];
  imgCache[k] = null;
  if (source === 'off') return null;
  try {
    if (source === 'itunes') {
      const q = encodeURIComponent(artist);
      const r = await fetch(`https://itunes.apple.com/search?term=${q}&entity=musicTrack&limit=5&attribute=artistTerm`);
      const d = await r.json();
      const results = (d?.results || []).filter(x => x.kind === 'song');
      const match = results.find(x => x.artistName?.toLowerCase() === artist.toLowerCase()) || results[0];
      if (match?.artworkUrl100) {
        imgCache[k] = match.artworkUrl100.replace('100x100bb', '300x300bb');
      }
    } else if (source === 'lastfm') {
      const r = await fetch(lfmUrl('artist.getinfo', { artist, autocorrect: 1 }));
      const d = await r.json();
      imgCache[k] = bestImage(d?.artist?.image) || null;
    } else if (source === 'deezer') {
      imgCache[k] = await deezerArtistImage(artist);
    } else if (source === 'youtube') {
      imgCache[k] = await ytSearch(artist + ' official');
    }
  } catch (e) { imgCache[k] = null; }
  return imgCache[k];
}

async function getAlbumImage(album, artist, source) {
  source = source || 'deezer';
  const k = 'album:' + artist.toLowerCase() + '|||' + album.toLowerCase() + ':' + source;
  if (k in imgCache) return imgCache[k];
  imgCache[k] = null;
  if (source === 'off') return null;
  try {
    // Same reasoning as deezerAlbumImageCandidates: a compilation searches on
    // its title alone, since nothing is credited to "Various Artists".
    const comp = artist === VARIOUS_ARTISTS;
    if (source === 'itunes') {
      const q = encodeURIComponent(comp ? album : artist + ' ' + album);
      const r = await fetch(`https://itunes.apple.com/search?term=${q}&entity=album&limit=5`);
      const d = await r.json();
      const results = d?.results || [];
      const match = results.find(x =>
        x.collectionName?.toLowerCase().includes(album.toLowerCase()) &&
        (comp || x.artistName?.toLowerCase().includes(artist.toLowerCase().split(/[\s,&]/)[0]))
      ) || results[0];
      if (match?.artworkUrl100) {
        imgCache[k] = match.artworkUrl100.replace('100x100bb', '600x600bb');
      }
    } else if (source === 'lastfm') {
      const r = await fetch(lfmUrl('album.getinfo', { album, artist, autocorrect: 1 }));
      const d = await r.json();
      imgCache[k] = bestImage(d?.album?.image) || null;
    } else if (source === 'deezer') {
      imgCache[k] = await deezerAlbumImage(album, artist);
    } else if (source === 'youtube') {
      imgCache[k] = await ytSearch((comp ? album : artist + ' ' + album) + ' album');
    }
  } catch (e) { imgCache[k] = null; }
  return imgCache[k];
}

async function getTrackImage(track, artist, source) {
  source = source || 'deezer';
  const k = 'track:' + artist.toLowerCase() + '|||' + track.toLowerCase() + ':' + source;
  if (k in imgCache) return imgCache[k];
  imgCache[k] = null;
  if (source === 'off') return null;
  try {
    if (source === 'itunes') {
      const q = encodeURIComponent(artist + ' ' + track);
      const r = await fetch(`https://itunes.apple.com/search?term=${q}&entity=musicTrack&limit=5`);
      const d = await r.json();
      const results = (d?.results || []).filter(x => x.kind === 'song');
      const match = results.find(x =>
        x.trackName?.toLowerCase().includes(track.toLowerCase()) &&
        x.artistName?.toLowerCase().includes(artist.toLowerCase().split(/[\s,&]/)[0])
      ) || results[0];
      if (match?.artworkUrl100) {
        imgCache[k] = match.artworkUrl100.replace('100x100bb', '300x300bb');
      }
    } else if (source === 'lastfm') {
      const r = await fetch(lfmUrl('track.getInfo', { track, artist, autocorrect: 1 }));
      const d = await r.json();
      imgCache[k] = bestImage(d?.track?.album?.image) || null;
    } else if (source === 'deezer') {
      imgCache[k] = await deezerTrackImage(track, artist);
    } else if (source === 'youtube') {
      imgCache[k] = await ytSearch(artist + ' ' + track);
    }
  } catch (e) { imgCache[k] = null; }
  return imgCache[k];
}

function initials(str) {
  return str.split(/\s+/).slice(0, 2).map(w => w[0]?.toUpperCase() || '').join('');
}

function thumbHtml(url, fallbackStr, isRank1) {
  if (url) return `<img class="thumb" src="${esc(url)}" alt="" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="thumb-initials" style="display:none">${esc(initials(fallbackStr))}</div>`;
  return `<div class="thumb-initials">${esc(initials(fallbackStr))}</div>`;
}

// Called when a browser fails to render an image URL — cycles through remaining sources automatically.
// Tracks tried sources via data-tried-src to prevent repeating and stops once all are exhausted.
async function _imgFallback(img) {
  const FALLBACK_SOURCES = ['deezer', 'itunes', 'lastfm', 'youtube'];
  const tried = new Set(img.dataset.triedSrc ? img.dataset.triedSrc.split(',') : []);
  const type = img.dataset.type || '';
  const prefKey = img.dataset.prefkey || '';
  const name = img.dataset.name || '';
  const artist = img.dataset.artist || '';
  const album = img.dataset.album || '';
  const imgId = img.dataset.imgid || '';
  const fallback = name || album || artist || '';
  img.onerror = null; // prevent re-entry while async fetch is in flight
  for (const source of FALLBACK_SOURCES) {
    if (tried.has(source)) continue;
    tried.add(source);
    img.dataset.triedSrc = [...tried].join(',');
    let url = null;
    try {
      if (type === 'artist') url = await getArtistImage(name, source);
      else if (type === 'album') url = await getAlbumImage(album, artist, source);
      else url = await getTrackImage(name, artist, source);
    } catch (e) {}
    if (!img.isConnected) return;
    if (url) {
      img.onerror = function() { _imgFallback(this); };
      img.src = url;
      if (imgId) {
        const btn = document.getElementById('srcbtn-' + imgId);
        if (btn) btn.textContent = srcLabel(source);
      }
      if (prefKey) {
        itemSourcePrefs[prefKey] = source;
        localStorage.setItem('itemSourcePrefs', JSON.stringify(itemSourcePrefs));
      }
      return;
    }
  }
  // All sources exhausted — stay on initials, leave source button as-is (Deezer)
  if (img.isConnected) img.outerHTML = `<div class="thumb-initials">${esc(initials(fallback))}</div>`;
}

// Fetch and inject a single image into its container element
async function fetchAndInjectImage(el, item, type) {
  // A picker-pinned choice wins over the automatic source cascade.
  const choice = item.prefKey && imgChoicePrefs[item.prefKey];
  if (choice) {
    if (!document.getElementById(item.imgId)) return;
    const pinFallback = item.name || item.title || item.album || '';
    if (choice.source === 'off' || !choice.url) {
      el.innerHTML = `<div class="thumb-initials">${esc(initials(pinFallback))}</div>`;
    } else {
      el.innerHTML = `<img class="thumb" alt="" loading="lazy" data-imgid="${esc(item.imgId || '')}" data-type="${esc(type)}" data-prefkey="${esc(item.prefKey || '')}" data-name="${esc(item.name || item.title || '')}" data-artist="${esc(item.artist || '')}" data-album="${esc(item.album || '')}">`;
      const pinImg = el.querySelector('img');
      pinImg.onerror = function() {
        // The pinned URL died (CDN rotation, deleted upload) — unpin it and
        // fall back to the automatic cascade instead of a broken image.
        delete imgChoicePrefs[item.prefKey];
        saveImgChoicePrefs();
        fetchAndInjectImage(el, item, type);
      };
      pinImg.src = choice.url;
      const _pinMosTile = el.closest && el.closest('.wv-mos-item');
      if (_pinMosTile && !_pinMosTile.classList.contains('wv-r1') && !_pinMosTile.classList.contains('wv-r2') && !_pinMosTile.classList.contains('wv-r3')) {
        _mosDominantGlow(choice.url, _pinMosTile);
      }
    }
    const pinBtn = document.getElementById('srcbtn-' + item.imgId);
    if (pinBtn) pinBtn.textContent = srcLabel(choice.source);
    return;
  }

  const FALLBACK_SOURCES = ['deezer', 'itunes', 'lastfm', 'youtube'];
  const preferredSource = (item.prefKey && itemSourcePrefs[item.prefKey]) || 'deezer';
  let url = null;
  let usedSource = preferredSource;

  if (preferredSource !== 'off') {
    const startIdx = Math.max(0, FALLBACK_SOURCES.indexOf(preferredSource));
    for (let i = 0; i < FALLBACK_SOURCES.length; i++) {
      const source = FALLBACK_SOURCES[(startIdx + i) % FALLBACK_SOURCES.length];
      if (i > 0 && source === 'deezer') break;
      try {
        if (type === 'artist' && source === 'deezer' && item.prefKey && deezerCandidateIdxPrefs[item.prefKey]) {
          // User previously stepped past the top fan-count pick for this
          // artist (see cycleImgSrc) — honor that choice on reload instead
          // of resetting to the auto-picked candidate every time.
          const candidates = await deezerArtistImageCandidates(item.name);
          const idx = Math.min(deezerCandidateIdxPrefs[item.prefKey], Math.max(0, candidates.length - 1));
          url = candidates[idx] || null;
        } else if (type === 'artist') url = await getArtistImage(item.name, source);
        else if (type === 'album') url = await getAlbumImage(item.album, item.artist, source);
        else url = await getTrackImage(item.title, item.artist, source);
      } catch (e) { url = null; }
      if (source === 'deezer') await new Promise(r => setTimeout(r, 120));
      if (url) { usedSource = source; break; }
    }
    if (!url) usedSource = 'deezer';
  }

  if (!document.getElementById(item.imgId)) return;
  const fallback = item.name || item.title || item.album || '';
  if (url) {
    el.innerHTML = `<img class="thumb" alt="" loading="lazy" data-imgid="${esc(item.imgId || '')}" data-type="${esc(type)}" data-prefkey="${esc(item.prefKey || '')}" data-name="${esc(item.name || item.title || '')}" data-artist="${esc(item.artist || '')}" data-album="${esc(item.album || '')}" data-tried-src="${esc(usedSource)}">`;
    const newImg = el.querySelector('img');
    newImg.onerror = function() { _imgFallback(this); };
    newImg.src = url;
    const _mosTile = el.closest && el.closest('.wv-mos-item');
    if (_mosTile && !_mosTile.classList.contains('wv-r1') && !_mosTile.classList.contains('wv-r2') && !_mosTile.classList.contains('wv-r3')) {
      _mosDominantGlow(url, _mosTile);
    }
  } else {
    el.innerHTML = `<div class="thumb-initials">${esc(initials(fallback))}</div>`;
  }
  if (item.prefKey) {
    if (usedSource !== preferredSource) {
      itemSourcePrefs[item.prefKey] = usedSource;
      localStorage.setItem('itemSourcePrefs', JSON.stringify(itemSourcePrefs));
    }
    const btn = document.getElementById('srcbtn-' + item.imgId);
    if (btn) btn.textContent = srcLabel(usedSource);
  }
}

function clearImageObservers() {
  imgObservers.forEach(o => o.disconnect());
  imgObservers = [];
  imgQueue = Promise.resolve();
}

// Set up IntersectionObserver so images only load when scrolled into view
function loadImages(items, type) {
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (!entry.isIntersecting) continue;
      observer.unobserve(entry.target);
      const item = entry.target._imgItem;
      if (item) imgQueue = imgQueue.then(() => fetchAndInjectImage(entry.target, item, type));
    }
  }, { rootMargin: '300px' });
  imgObservers.push(observer);

  for (const item of items) {
    const el = document.getElementById(item.imgId);
    if (!el) continue;
    el._imgItem = item;
    el._imgType = type;   // kept so _recReattachImageObservers can regroup by type
    observer.observe(el);
    if (el.closest('#recordsView')) attachRecImgPicker(el, item, type);
  }
  // Returned so callers that re-render (the certifications wall re-renders on
  // every filter, sort and search change) can retire the previous observer
  // instead of stacking a new one on top of it each time.
  return observer;
}

/* Records artwork gets the ✎ picker attached here rather than in each section's
   markup. The tab draws artwork from eight separate builders — All #1s and
   Appearances wrote the button by hand, while PAK, Debuts, New Charts,
   Milestones and the certifications wall had no control at all — and this is
   the one place every one of them already passes through. Doing it here also
   means a new Records section cannot gain artwork without gaining the control.

   The button is a *sibling* of the artwork element, never a child:
   fetchAndInjectImage() replaces the target's innerHTML when the image lands,
   which would wipe a button placed inside it. */
function attachRecImgPicker(el, item, type) {
  let wrap = el.parentElement;
  if (!wrap || !wrap.classList.contains('thumb-wrap')) {
    // .rec-thumb-wrap keeps the inserted wrapper layout-neutral — the sections
    // it lands in are grid and flex children with their own sizing.
    wrap = document.createElement('div');
    wrap.className = 'thumb-wrap rec-thumb-wrap';
    el.parentNode.insertBefore(wrap, el);
    wrap.appendChild(el);
  }
  if (wrap.querySelector('.img-src-btn')) return;
  const label = item.name || item.title || item.album || '';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'img-src-btn';
  btn.id = 'srcbtn-' + item.imgId;
  btn.dataset.imgid = item.imgId;
  btn.dataset.type = type;
  btn.dataset.prefkey = item.prefKey || '';
  btn.dataset.name = label;
  btn.dataset.artist = item.artist || '';
  btn.dataset.album = item.album || '';
  btn.title = t('img_picker_change');
  btn.setAttribute('aria-label', t('img_picker_change_for', { name: label }));
  wrap.appendChild(btn);
}

// ─── IMAGE PICKER POPOVER ─────────────────────────────────────
// Replaces the old click-to-cycle source button: clicking the ✎ overlay on
// any artwork opens a popover with candidate images from every source at
// once. The chosen image is pinned in imgChoicePrefs and wins on every
// future render of that item, in every view.

let _imgPickerEl = null;
function closeImgPicker() {
  if (!_imgPickerEl) return;
  _imgPickerEl.remove();
  _imgPickerEl = null;
  document.removeEventListener('keydown', _imgPickerEscHandler);
}
function _imgPickerEscHandler(e) { if (e.key === 'Escape') closeImgPicker(); }

// All candidate URLs one source can offer for an item (picker tiles).
async function imgPickerCandidates(source, type, name, artist, album) {
  if (source === 'deezer') {
    if (type === 'artist') return deezerArtistImageCandidates(name);
    if (type === 'album') return deezerAlbumImageCandidates(album, artist);
    return deezerTrackImageCandidates(name, artist);
  }
  if (source === 'itunes') return itunesImageCandidates(type, name, artist, album);
  // Last.fm / YouTube only ever produce one image per item.
  let url = null;
  if (type === 'artist') url = await getArtistImage(name, source);
  else if (type === 'album') url = await getAlbumImage(album, artist, source);
  else url = await getTrackImage(name, artist, source);
  return url ? [url] : [];
}

function applyImgChoice(o, url, source) {
  if (source === 'auto') {
    delete imgChoicePrefs[o.prefkey];
    delete itemSourcePrefs[o.prefkey];
    delete deezerCandidateIdxPrefs[o.prefkey];
    localStorage.setItem('itemSourcePrefs', JSON.stringify(itemSourcePrefs));
    localStorage.setItem('deezerCandidateIdxPrefs', JSON.stringify(deezerCandidateIdxPrefs));
  } else {
    imgChoicePrefs[o.prefkey] = { url: url || '', source };
  }
  saveImgChoicePrefs();
  closeImgPicker();
  // Refresh every rendered instance of this item (same prefKey can appear in
  // several tables/views at once — each has its own srcbtn to find it by).
  document.querySelectorAll('.img-src-btn[data-prefkey]').forEach(btn => {
    if (btn.dataset.prefkey !== o.prefkey) return;
    const el = document.getElementById(btn.dataset.imgid);
    if (!el) return;
    const item = {
      imgId: btn.dataset.imgid,
      name: btn.dataset.name, title: btn.dataset.name,
      artist: btn.dataset.artist || '', album: btn.dataset.album || '',
      prefKey: o.prefkey
    };
    imgQueue = imgQueue.then(() => fetchAndInjectImage(el, item, btn.dataset.type || 'song'));
  });
}

function openImgPicker(o) {
  closeImgPicker();
  const title = o.type === 'album' ? (o.album || o.name) : o.name;
  const sub = o.type === 'artist' ? '' : (o.artist || '');
  const currentUrl = (imgChoicePrefs[o.prefkey] && imgChoicePrefs[o.prefkey].url) ||
    (document.getElementById(o.imgid)?.querySelector('img')?.src || '');

  const overlay = document.createElement('div');
  overlay.className = 'imgpk-overlay';
  overlay.addEventListener('click', e => { if (e.target === overlay) closeImgPicker(); });

  const sources = ['deezer', 'itunes', 'lastfm', 'youtube'].filter(s => s !== 'youtube' || YOUTUBE_KEY);
  overlay.innerHTML = `<div class="imgpk-panel" role="dialog" aria-modal="true">
    <div class="imgpk-head">
      <div class="imgpk-titles">
        <div class="imgpk-title">${t('imgpk_title')}</div>
        <div class="imgpk-item">${esc(title)}${sub ? `<span class="imgpk-item-sub"> — ${esc(sub)}</span>` : ''}</div>
      </div>
      <button class="imgpk-close" onclick="closeImgPicker()" aria-label="Close">✕</button>
    </div>
    <div class="imgpk-body">
      ${sources.map(s => `<div class="imgpk-section" data-src="${s}">
        <div class="imgpk-src-label">${srcLabel(s)}</div>
        <div class="imgpk-tiles"><div class="imgpk-loading">${t('imgpk_loading')}</div></div>
      </div>`).join('')}
    </div>
    <div class="imgpk-foot">
      <button class="imgpk-foot-btn" data-act="auto">${t('imgpk_auto')}</button>
      <button class="imgpk-foot-btn" data-act="off">${t('imgpk_none')}</button>
      <input class="imgpk-url-input" type="url" placeholder="${t('imgpk_url_ph')}" spellcheck="false">
      <button class="imgpk-foot-btn imgpk-url-apply" data-act="custom">${t('imgpk_apply')}</button>
    </div>
  </div>`;

  overlay.querySelector('[data-act="auto"]').onclick = () => applyImgChoice(o, null, 'auto');
  overlay.querySelector('[data-act="off"]').onclick = () => applyImgChoice(o, null, 'off');
  const urlInput = overlay.querySelector('.imgpk-url-input');
  const applyCustom = () => {
    const u = urlInput.value.trim();
    if (u) applyImgChoice(o, u, 'custom');
  };
  overlay.querySelector('[data-act="custom"]').onclick = applyCustom;
  urlInput.addEventListener('keydown', e => { if (e.key === 'Enter') applyCustom(); });

  document.body.appendChild(overlay);
  _imgPickerEl = overlay;
  document.addEventListener('keydown', _imgPickerEscHandler);

  // Load each source's candidates in parallel; sections fill in as they land.
  for (const s of sources) {
    imgPickerCandidates(s, o.type === 'song' ? 'track' : o.type, o.name, o.artist || '', o.album || '')
      .then(urls => {
        if (_imgPickerEl !== overlay) return; // picker was closed/reopened
        const tiles = overlay.querySelector(`.imgpk-section[data-src="${s}"] .imgpk-tiles`);
        if (!tiles) return;
        if (!urls.length) {
          tiles.innerHTML = `<div class="imgpk-empty">${t('imgpk_empty')}</div>`;
          return;
        }
        tiles.innerHTML = urls.map(u =>
          `<button class="imgpk-tile${u === currentUrl ? ' imgpk-tile--current' : ''}" data-url="${esc(u)}" title="${srcLabel(s)}"><img alt="" loading="lazy" src="${esc(u)}" onerror="this.closest('.imgpk-tile').remove()"></button>`
        ).join('');
        tiles.querySelectorAll('.imgpk-tile').forEach(tile => {
          tile.onclick = () => applyImgChoice(o, tile.dataset.url, s);
        });
      });
  }
}

function _mosDominantGlow(url, tile) {
  const probe = new Image();
  probe.crossOrigin = 'anonymous';
  probe.onload = function() {
    try {
      const sz = 20;
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = sz;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(this, 0, 0, sz, sz);
      const data = ctx.getImageData(0, 0, sz, sz).data;
      let bestR = 0, bestG = 0, bestB = 0, bestSat = -1;
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i], g = data[i+1], b = data[i+2], a = data[i+3];
        if (a < 128) continue;
        const max = Math.max(r, g, b), min = Math.min(r, g, b);
        const l = (max + min) / 510;
        if (l < 0.1 || l > 0.92) continue;
        const sat = max === 0 ? 0 : (max - min) / max;
        if (sat > bestSat) { bestSat = sat; bestR = r; bestG = g; bestB = b; }
      }
      if (bestSat < 0.2 || !tile.isConnected) return;
      const inner = tile.querySelector('.wv-mos-item-inner');
      if (inner) inner.style.boxShadow = `0 0 0 2px rgba(${bestR},${bestG},${bestB},0.8), 0 0 14px rgba(${bestR},${bestG},${bestB},0.3)`;
    } catch(e) {}
  };
  probe.src = url;
}

// Handle artwork ✎ overlay clicks (capture phase so it beats artist-row handler)
document.addEventListener('click', e => {
  const btn = e.target.closest('.img-src-btn');
  if (!btn) return;
  e.stopPropagation();
  e.preventDefault();
  const { imgid, type, prefkey, name, artist, album } = btn.dataset;
  openImgPicker({ imgid, type, prefkey, name, artist, album });
}, true);

// ─── TOUCH: PRESS-AND-HOLD OPENS THE PICKER ───────────────────
// On touch devices the ✎ badge is hidden entirely (style.css hides it under
// @media (hover: none) — on small thumbs it covered the very artwork it
// belongs to). Instead, pressing and holding any artwork that carries a
// picker for half a second opens it. A plain tap keeps doing whatever it
// did before (some artwork opens detail modals, most does nothing), because
// the hold only fires after the tap window has passed and the ghost click
// that follows a fired hold is swallowed below.
const IMG_LONGPRESS_MS = 500;
let _imgLpTimer = null;              // pending hold timer, null when idle
let _imgLpStartX = 0, _imgLpStartY = 0; // press origin, to tell a hold from a scroll
let _imgLpFired = false;             // true between picker-open and the ghost click

function _imgLpCancel() {
  if (_imgLpTimer) { clearTimeout(_imgLpTimer); _imgLpTimer = null; }
}

document.addEventListener('pointerdown', e => {
  // Mouse users keep the hover badge; only touch/pen presses arm the hold.
  if (e.pointerType === 'mouse') return;
  const wrap = e.target.closest('.thumb-wrap');
  if (!wrap || !wrap.querySelector('.img-src-btn')) return;
  _imgLpCancel();
  _imgLpFired = false;
  _imgLpStartX = e.clientX;
  _imgLpStartY = e.clientY;
  _imgLpTimer = setTimeout(() => {
    _imgLpTimer = null;
    const btn = wrap.querySelector('.img-src-btn');
    if (!btn) return;
    _imgLpFired = true;
    // Small haptic nudge where supported (Android; iOS ignores vibrate()).
    if (navigator.vibrate) navigator.vibrate(15);
    const { imgid, type, prefkey, name, artist, album } = btn.dataset;
    openImgPicker({ imgid, type, prefkey, name, artist, album });
    // Safety: if no ghost click ever arrives (browser quirk), disarm anyway
    // so the *next* real tap isn't eaten.
    setTimeout(() => { _imgLpFired = false; }, 700);
  }, IMG_LONGPRESS_MS);
}, true);

// Any movement beyond a finger-wobble means the user is scrolling, not holding.
document.addEventListener('pointermove', e => {
  if (!_imgLpTimer) return;
  if (Math.abs(e.clientX - _imgLpStartX) > 10 || Math.abs(e.clientY - _imgLpStartY) > 10) _imgLpCancel();
}, true);
document.addEventListener('pointerup', _imgLpCancel, true);
document.addEventListener('pointercancel', _imgLpCancel, true);

// Swallow the ghost click that follows a fired hold (the finger was still down
// when the picker opened, so its lift lands a click wherever it happens to be —
// possibly on the artwork's own tap action, possibly on the fresh overlay,
// which would close it on the spot). Capture phase so it wins over both.
document.addEventListener('click', e => {
  if (!_imgLpFired) return;
  _imgLpFired = false;
  e.stopPropagation();
  e.preventDefault();
}, true);

// Android turns a long-press on an image into a native context menu; ours
// replaces it on artwork that has a picker. (iOS needs -webkit-touch-callout
// instead, which the stylesheet sets on .thumb-wrap for touch devices.)
document.addEventListener('contextmenu', e => {
  if ((_imgLpTimer || _imgLpFired) && e.target.closest('.thumb-wrap')) e.preventDefault();
}, true);



// ─── GOOGLE SHEETS SYNC ────────────────────────────────────────
// Empty on purpose: there is no shared fallback sheet, every user brings their
// own. It exists so `localStorage.getItem('dc_sheet_id') || DEFAULT_SHEET_ID`
// resolves instead of throwing — that ReferenceError used to abort
// openSourceModal() halfway on any browser with no sheet saved yet, which left
// the Last.fm username blank and the Sheets fields showing over the wrong source.
const DEFAULT_SHEET_ID  = '';
const DEFAULT_SHEET_TAB = 'Full Raw Listening History';
function getSheetUrl() {
  const rawId = localStorage.getItem('dc_sheet_id') || '';
  const tab   = localStorage.getItem('dc_sheet_tab') || DEFAULT_SHEET_TAB;
  // Support stored full URLs (e.g. from the deployed modal's URL input field)
  const urlMatch = rawId.match(/spreadsheets\/d\/([^\/\?#]+)/);
  const id = urlMatch ? urlMatch[1] : rawId;
  const gidFromStored = rawId.match(/[#&?]gid=(\d+)/);
  const gid = (gidFromStored && gidFromStored[1]) || localStorage.getItem('dc_sheet_gid') || '';
  // export?format=csv has no response size limit (unlike gviz/tq which truncates large sheets)
  if (gid) {
    return `https://docs.google.com/spreadsheets/d/${id}/export?format=csv&gid=${gid}`;
  }
  return `https://docs.google.com/spreadsheets/d/${id}/export?format=csv&sheet=${encodeURIComponent(tab)}`;
}
function getDataSource()  { return localStorage.getItem('dc_source')      || 'sheets'; }
function getLastFmUser()  { return localStorage.getItem('dc_lastfm_user') || ''; }
const SYNC_INTERVAL_MS = 6 * 60 * 60 * 1000; // auto-refresh every 6 hours
const POLL_INTERVAL_MS = 30 * 60 * 1000;     // background poll every 30 minutes
// Last.fm syncs are incremental (only scrobbles newer than the cache), so a periodic
// full re-download is kept as a safety net: it picks up edits/deletions made on
// Last.fm itself, which an incremental fetch can never see.
const LASTFM_FULL_RESYNC_MS = 7 * 24 * 60 * 60 * 1000; // full history re-download every 7 days
let syncTimer = null;
let pollTimer = null;
let lastSyncTime = null;

// ─── INDEXEDDB CACHE (survives page refresh) ───────────────────
const IDB_NAME = 'dankcharts';
const IDB_STORE = 'cache';
const IDB_LASTFM_KEY = 'lastfm';
const IDB_SHEETS_KEY = 'sheets';
const IDB_FILE_KEY   = 'file_upload';
const IDB_RULES_KEY  = 'autocorrect_rules';
const BACKEND_API    = 'https://dankcharts-api.onrender.com';

function openIDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = e => e.target.result.createObjectStore(IDB_STORE);
    req.onsuccess = e => resolve(e.target.result);
    req.onerror = e => reject(e.target.error);
  });
}
async function loadFromIDB(key) {
  try {
    const db = await openIDB();
    return new Promise((resolve, reject) => {
      const req = db.transaction(IDB_STORE, 'readonly').objectStore(IDB_STORE).get(key);
      req.onsuccess = e => resolve(e.target.result ?? null);
      req.onerror = e => reject(e.target.error);
    });
  } catch (e) { return null; }
}
async function saveToIDB(key, value) {
  try {
    const db = await openIDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(IDB_STORE, 'readwrite');
      tx.objectStore(IDB_STORE).put(value, key);
      tx.oncomplete = resolve;
      tx.onerror = e => reject(e.target.error);
    });
  } catch (e) { /* ignore */ }
}
async function deleteFromIDB(key) {
  try {
    const db = await openIDB();
    return new Promise((resolve) => {
      const tx = db.transaction(IDB_STORE, 'readwrite');
      tx.objectStore(IDB_STORE).delete(key);
      tx.oncomplete = resolve;
      tx.onerror = resolve;
    });
  } catch (e) { /* ignore */ }
}

// Remembers the last rendered play count (digits only) so the odometer
// knows which direction/distance to roll when the count changes.
let _prevSyncCountDigits = null;

// Raw (msg, cls) most recently passed to setSyncStatus. The odometer markup
// makes #syncStatus.textContent unreliable (it concatenates every stacked
// digit in every reel), so callers that need to snapshot/restore the status
// (e.g. the auto-correct dismiss button) must read these instead.
let _lastSyncStatusMsg = '';
let _lastSyncStatusCls = '';

function setSyncStatus(msg, cls) {
  const el = document.getElementById('syncStatus');
  el.className = cls || '';
  _lastSyncStatusMsg = msg;
  _lastSyncStatusCls = cls || '';
  // sync_ok / sync_ok_cached wrap the play count in ⟦…⟧ (see translations.js) —
  // split on that marker so the count can render as an animated digit reel
  // while everything else stays a plain text node (no innerHTML of msg, which
  // may contain interpolated filenames).
  const m = /^([\s\S]*)⟦([\d.,\s]+)⟧([\s\S]*)$/.exec(msg);
  if (!m) { el.textContent = msg; _prevSyncCountDigits = null; return; }
  el.textContent = '';
  el.appendChild(document.createTextNode(m[1]));
  el.appendChild(buildSyncCountOdometer(m[2]));
  el.appendChild(document.createTextNode(m[3]));
}

// Renders a play-count string (e.g. "200,998") as a cassette-counter style
// digit odometer, rolling each changed digit from its previous value.
function buildSyncCountOdometer(numStr) {
  const digits = numStr.replace(/\D/g, '');
  let prev = _prevSyncCountDigits;
  let animate = true;
  if (prev === null) prev = '0'.repeat(digits.length); // first paint: count up from 0
  else if (prev.length > digits.length) { animate = false; prev = digits; } // count shrank — no reel
  else if (prev.length < digits.length) prev = prev.padStart(digits.length, '0'); // gained a digit

  const wrap = document.createElement('span');
  wrap.className = 'sync-count';
  let di = 0;
  for (const ch of numStr) {
    if (ch >= '0' && ch <= '9') {
      const digit = document.createElement('span');
      digit.className = 'odo-digit';
      const strip = document.createElement('span');
      strip.className = 'odo-strip';
      strip.style.setProperty('--val', prev[di]);
      for (let d = 0; d <= 9; d++) {
        const row = document.createElement('span');
        row.className = 'odo-num';
        row.textContent = d;
        strip.appendChild(row);
      }
      digit.appendChild(strip);
      wrap.appendChild(digit);
      di++;
    } else {
      const sep = document.createElement('span');
      sep.className = 'odo-sep';
      sep.textContent = ch;
      wrap.appendChild(sep);
    }
  }
  _prevSyncCountDigits = digits;
  if (animate) {
    // Force the initial --val to paint before animating to the target,
    // otherwise the browser may coalesce both style changes into one frame.
    requestAnimationFrame(() => {
      wrap.querySelectorAll('.odo-strip').forEach((strip, i) => strip.style.setProperty('--val', digits[i]));
    });
  }
  return wrap;
}

function getSheetUrlFallback() {
  const rawId = localStorage.getItem('dc_sheet_id') || DEFAULT_SHEET_ID;
  const tab   = localStorage.getItem('dc_sheet_tab') || DEFAULT_SHEET_TAB;
  const urlMatch = rawId.match(/spreadsheets\/d\/([^\/\?#]+)/);
  const id = urlMatch ? urlMatch[1] : rawId;
  return `https://docs.google.com/spreadsheets/d/${id}/gviz/tq?tqx=out:csv;charset:UTF-8&sheet=${encodeURIComponent(tab)}`;
}

// Fetches the sheet as CSV text with the full 3-tier fallback chain:
// 1) export?format=csv (no row/size limit)
// 2) backend proxy (handles CORS, serves full file regardless of size)
// 3) gviz/tq (may truncate very large sheets)
// Returns the decoded text, or throws the last fallback's error.
async function fetchSheetCsv() {
  // Explicitly decode as UTF-8 to preserve special characters
  // (Spanish, Korean, accented names etc.) — never let the browser guess
  const decode = async res => {
    if (!res.ok) throw new Error('HTTP ' + res.status);
    return new TextDecoder('utf-8').decode(await res.arrayBuffer());
  };
  try {
    return await decode(await fetch(getSheetUrl() + '&t=' + Date.now()));
  } catch (e) {
    try {
      const rawId = localStorage.getItem('dc_sheet_id') || DEFAULT_SHEET_ID;
      const urlMatch = rawId.match(/spreadsheets\/d\/([^\/\?#]+)/);
      const sheetId = urlMatch ? urlMatch[1] : rawId;
      const gid = localStorage.getItem('dc_sheet_gid');
      let proxyUrl = `${BACKEND_API}/api/sync/sheets-proxy?sheetId=${encodeURIComponent(sheetId)}`;
      if (gid) proxyUrl += `&gid=${encodeURIComponent(gid)}`;
      return await decode(await fetch(proxyUrl));
    } catch (e2) {
      return await decode(await fetch(getSheetUrlFallback() + '&t=' + Date.now()));
    }
  }
}

async function syncFromSheets() {
  if (!localStorage.getItem('dc_sheet_id')) {
    setSyncStatus('No Google Sheet configured — click ⚙ Settings to set one up.', 'err');
    document.getElementById('syncNowBtn').disabled = false;
    return;
  }
  const btn = document.getElementById('syncNowBtn');
  btn.disabled = true;
  // Covers the landing-connect path, which calls this directly rather than via syncNow()
  startNowPlaying();
  setSyncStatus(t('sync_connecting'), 'loading');
  try {
    const text = await fetchSheetCsv();
    parseCsv(text, true); // true = from sheets (skip hide upload zone)
    lastSyncTime = new Date();
    localStorage.setItem('dc_sync_ts', lastSyncTime.getTime().toString());
    await saveToIDB(IDB_SHEETS_KEY, { ts: lastSyncTime.getTime(), csv: text });
    setSyncStatus(t('sync_ok', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString() }), 'ok');
  } catch (e) {
    setSyncStatus(t('sync_failed', { error: e.message }), 'err');
  }
  btn.disabled = false;
  // Schedule next auto-sync and background poll
  clearTimeout(syncTimer);
  syncTimer = setTimeout(syncFromSheets, SYNC_INTERVAL_MS);
  clearTimeout(pollTimer);
  pollTimer = setTimeout(pollSheets, POLL_INTERVAL_MS);
}

// fromUts > 0 turns the request incremental: Last.fm only returns scrobbles after
// that unix timestamp, so totalPages shrinks to just the new listens.
async function fetchLastFmPage(username, page, fromUts = 0) {
  const url = `https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks`
    + `&user=${encodeURIComponent(username)}&api_key=${LASTFM_KEY}`
    + `&format=json&limit=200&page=${page}`
    + (fromUts > 0 ? `&from=${fromUts}` : '');
  for (let attempt = 0; attempt < 3; attempt++) {
    if (attempt > 0) await new Promise(r => setTimeout(r, 1000 * Math.pow(2, attempt - 1)));
    const res = await fetch(url);
    if (!res.ok) { if (attempt === 2) throw new Error('HTTP ' + res.status); continue; }
    const data = await res.json();
    if (data.error) throw new Error(data.message);
    return data;
  }
}

async function syncFromLastFm() {
  const username = getLastFmUser();
  if (!username) {
    setSyncStatus('No Last.fm username set — click ⚙ Settings to get started.', 'err');
    return;
  }
  const btn = document.getElementById('syncNowBtn');
  btn.disabled = true;

  // Kick the ON AIR bar off up front, not after the download: a first-time full
  // history fetch can take a minute, and the live track is a one-request lookup.
  startNowPlaying();

  // Serve from IndexedDB cache first (survives page refresh) — stale-while-revalidate:
  // render whatever we have immediately, and only hit the network in the background.
  const cached = await loadFromIDB(IDB_LASTFM_KEY);
  const age = cached ? Date.now() - cached.ts : Infinity;
  let renderedFromCache = false;
  if (cached) {
    try {
      allPlays = applyAutocorrectRules(cached.data.map(([title, artist, album, uts]) => {
        const ar = artist || '';
        return { title, artist: ar, artists: splitArtists(ar), album: album || '—', date: new Date(uts * 1000) };
      }));
      lastSyncTime = new Date(cached.ts);
      const minsAgo = Math.round(age / 60000);
      setSyncStatus(t('sync_ok_cached', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString(), mins: minsAgo }), 'ok');
      finalizeLoad();
      renderedFromCache = true;
      // Fall through to the fetch below — with usable cached history it is incremental
      // (only scrobbles newer than the cache, usually a single page), so the cached
      // charts stay on screen and get quietly topped up.
    } catch (e) { renderedFromCache = false; /* cache corrupt — fall through to fresh fetch */ }
  }

  // Incremental vs full: with a usable cache, fetch only scrobbles newer than the newest
  // cached one via the `from` param. The full history download only happens on first
  // connect, after a cache clear, or every LASTFM_FULL_RESYNC_MS as an edit/deletion
  // safety net.
  const cacheUsable = renderedFromCache && Array.isArray(cached?.data) && cached.data.length > 0;
  const incremental = cacheUsable && age < LASTFM_FULL_RESYNC_MS;
  let sinceUts = 0;
  // Newest cached uts — scan instead of trusting row 0, since concurrently fetched
  // pages can land slightly out of order in older caches.
  if (incremental) for (const row of cached.data) { if (row[3] > sinceUts) sinceUts = row[3]; }

  let rawTracks = [];
  // Progressive first paint: set once the partial early render (below) has happened,
  // so the final render downgrades to a quiet refresh instead of a second full paint.
  let earlyRendered = false;
  // Builds allPlays from the pages downloaded so far and paints the charts. Used for
  // the one early render during a long first-time download — recent periods are
  // already accurate because pages arrive newest-first.
  const renderPartial = () => {
    allPlays = applyAutocorrectRules(rawTracks.map(tr => {
      const ar = (tr.artist && tr.artist['#text']) || '';
      return { title: tr.name || '', artist: ar, artists: splitArtists(ar), album: (tr.album && tr.album['#text']) || '—', date: new Date(parseInt(tr.date.uts) * 1000) };
    })).sort((a, b) => b.date - a.date);
    finalizeLoad();
  };
  try {
    // Fetch page 1 to discover totalPages
    setSyncStatus(incremental ? 'Checking Last.fm for new scrobbles…' : 'Loading Last.fm history… page 1', 'loading');
    const firstData = await fetchLastFmPage(username, 1, sinceUts);
    const totalPages = parseInt(firstData.recenttracks['@attr'].totalPages) || 1;
    let tracks = firstData.recenttracks.track;
    if (!Array.isArray(tracks)) tracks = tracks ? [tracks] : [];
    // The > sinceUts filter also dedupes the boundary scrobble if Last.fm treats `from` inclusively
    for (const tr of tracks) { if (tr.date && tr.date.uts && parseInt(tr.date.uts) > sinceUts) rawTracks.push(tr); }

    if (totalPages > 1) {
      // Rolling concurrency pool: always keep up to CONCURRENCY requests in-flight.
      // Unlike fixed batches, this never idles waiting for the slowest request in a group.
      // CONCURRENCY=10 keeps us within Last.fm's ~5 req/s limit for large accounts.
      const CONCURRENCY = 10;
      // Progressive first paint: on a first-time full download (nothing on screen yet),
      // render the charts once the newest EARLY_RENDER_PAGES pages are all in, instead of
      // making the user watch the page counter until the entire history arrives. Only
      // worth doing when the history is big enough that the full download takes a while.
      // Contiguity is tracked because concurrent requests complete out of order — a hole
      // in the newest pages would briefly render misleading recent-period charts.
      const EARLY_RENDER_PAGES = 20; // ≈ 4,000 scrobbles
      const doEarlyRender = !renderedFromCache && totalPages >= EARLY_RENDER_PAGES * 2;
      const donePages = new Set([1]);
      let contigDone = 1; // pages 1..contigDone are all downloaded
      let nextPage = 2;
      let completedPages = 1;
      await new Promise((resolve) => {
        let inFlight = 0;
        function fill() {
          while (inFlight < CONCURRENCY && nextPage <= totalPages) {
            const p = nextPage++;
            inFlight++;
            fetchLastFmPage(username, p, sinceUts).then(data => {
              let t = data.recenttracks.track;
              if (!Array.isArray(t)) t = t ? [t] : [];
              for (const tr of t) { if (tr.date && tr.date.uts && parseInt(tr.date.uts) > sinceUts) rawTracks.push(tr); }
              donePages.add(p); // success only — a failed page would leave a data hole
            }).catch(e => {
              console.warn(`Last.fm: page ${p} failed (${e.message}), skipping`);
            }).finally(() => {
              completedPages++;
              if (completedPages % 20 === 0 || completedPages === totalPages) {
                setSyncStatus(`Loading Last.fm history… ${completedPages} / ${totalPages} pages`, 'loading');
              }
              if (doEarlyRender && !earlyRendered) {
                while (donePages.has(contigDone + 1)) contigDone++;
                if (contigDone >= EARLY_RENDER_PAGES) {
                  earlyRendered = true;
                  renderPartial(); // one-time partial paint; the download continues behind it
                }
              }
              inFlight--;
              if (nextPage > totalPages && inFlight === 0) resolve();
              else fill();
            });
          }
          if (nextPage > totalPages && inFlight === 0) resolve();
        }
        fill();
      });
    }
  } catch (e) {
    setSyncStatus('Last.fm error: ' + e.message, 'err');
    btn.disabled = false;
    if (renderedFromCache) {
      // Cached charts are still on screen — keep them and retry on the normal schedule
      clearTimeout(syncTimer);
      syncTimer = setTimeout(syncFromLastFm, SYNC_INTERVAL_MS);
      clearTimeout(pollTimer);
      pollTimer = setTimeout(pollLastFm, POLL_INTERVAL_MS);
    }
    return;
  }

  // Compact rows [title, artist, album, uts]. Sort newest-first explicitly —
  // concurrently fetched pages complete (and push) in arbitrary order.
  let compact = rawTracks.map(tr => [
    tr.name || '',
    (tr.artist && tr.artist['#text']) || '',
    (tr.album  && tr.album['#text'])  || '',
    parseInt(tr.date.uts)
  ]);
  compact.sort((a, b) => b[3] - a[3]);

  if (incremental && compact.length === 0) {
    // No new scrobbles — the cached charts on screen are already correct; just freshen
    // the cache timestamp so the 7-day full-resync clock keeps counting from now.
    lastSyncTime = new Date();
    await saveToIDB(IDB_LASTFM_KEY, { data: cached.data, ts: lastSyncTime.getTime() });
    setSyncStatus(t('sync_ok', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString() }), 'ok');
    btn.disabled = false;
    clearTimeout(syncTimer);
    syncTimer = setTimeout(syncFromLastFm, SYNC_INTERVAL_MS);
    clearTimeout(pollTimer);
    pollTimer = setTimeout(pollLastFm, POLL_INTERVAL_MS);
    return;
  }
  const rowToPlay = ([title, artist, album, uts]) => {
    const ar = artist || '';
    return { title, artist: ar, artists: splitArtists(ar), album: album || '—', date: new Date(uts * 1000) };
  };
  if (incremental) {
    // allPlays already holds the corrected play objects built from cached.data above —
    // only build objects for the new scrobbles and prepend them (same as pollLastFm).
    // Rebuilding the entire history here used to block the main thread for seconds on
    // large libraries every time a few new scrobbles arrived.
    allPlays = [...applyAutocorrectRules(compact.map(rowToPlay)), ...allPlays];
    compact = [...compact, ...cached.data]; // new scrobbles on top of cached history (for the IDB save below)
  } else {
    allPlays = applyAutocorrectRules(compact.map(rowToPlay));
  }

  await saveToIDB(IDB_LASTFM_KEY, { data: compact, ts: Date.now() });
  lastSyncTime = new Date();

  setSyncStatus(t('sync_ok', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString() }), 'ok');
  // If charts were already painted (from cache, or by the progressive early render
  // during a first-time download), refresh quietly — keeps the user's current view
  // instead of re-running the full settings-restoring first paint.
  if (renderedFromCache || earlyRendered) refreshAfterPoll(); else finalizeLoad();
  btn.disabled = false;
  clearTimeout(syncTimer);
  syncTimer = setTimeout(syncFromLastFm, SYNC_INTERVAL_MS);
  clearTimeout(pollTimer);
  pollTimer = setTimeout(pollLastFm, POLL_INTERVAL_MS);
}

function syncNow() {
  if (getDataSource() === 'lastfm') syncFromLastFm();
  // Sheets/CSV keep the ON AIR bar as long as a Last.fm account is connected —
  // startNowPlaying() tears it down by itself when there's no username to poll.
  else { startNowPlaying(); syncFromSheets(); }
}

// ─── BACKGROUND POLL (every 30 min) ───────────────────────────

// Pure CSV parser — returns sorted plays array or null, no UI side effects.
function parsePlaysCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) return null;
  const headers = lines[0].split(',').map(h => h.replace(/^"|"$/g, '').trim().toLowerCase());
  const colMap = {};
  const aliases = {
    title:    ['song title', 'title', 'track', 'track name', 'song name'],
    artist:   ['artist', 'artist name', 'performer'],
    album:    ['album', 'album name', 'release'],
    // 'uts'/'utc_time' come from the ghan.nl Last.fm exporter
    // (mainstream.ghan.nl/export.html), whose header row is
    //   uts,utc_time,artist,artist_mbid,album,album_mbid,track,track_mbid
    // — artist/album/track already matched above, so the date column was the
    // only thing standing between a 95% compatible export and a hard "missing
    // required columns" failure. Appended last on purpose: any header a file
    // could already match still wins, so this is purely an added fallback.
    // 'uts' before 'utc_time' because it is an unambiguous unix instant, while
    // utc_time is a formatted local-time string.
    datetime: ['date and time', 'date', 'datetime', 'timestamp', 'time', 'played at', 'scrobble time', 'uts', 'utc_time']
  };
  for (const [key, names] of Object.entries(aliases)) {
    for (const n of names) {
      const idx = headers.indexOf(n);
      if (idx !== -1) { colMap[key] = idx; break; }
    }
  }
  if (colMap.title === undefined || colMap.artist === undefined || colMap.datetime === undefined) return null;
  let fastDateParse = null;
  for (let i = 1; i < lines.length && !fastDateParse; i++) {
    const r = splitCsvRow(lines[i]);
    if (r.length < 2) continue;
    const sample = r[colMap.datetime] !== undefined ? r[colMap.datetime].replace(/^"|"$/g, '').trim() : '';
    if (sample) fastDateParse = makeFastDateParser(sample) || parseDate;
  }
  if (!fastDateParse) fastDateParse = parseDate;
  const plays = [];
  for (let i = 1; i < lines.length; i++) {
    const row = splitCsvRow(lines[i]);
    if (row.length < 2) continue;
    const get = idx => (idx !== undefined && row[idx] !== undefined) ? row[idx].replace(/^"|"$/g, '').trim() : '';
    const rawDate = get(colMap.datetime);
    let dt = fastDateParse(rawDate);
    if (!dt && fastDateParse !== parseDate) dt = parseDate(rawDate);
    if (!dt || dt.getFullYear() < 2000) continue;
    const artistRaw = get(colMap.artist);
    plays.push({ title: get(colMap.title), artist: artistRaw, artists: splitArtists(artistRaw), album: get(colMap.album) || '—', date: dt });
  }
  if (!plays.length) return null;
  plays.sort((a, b) => b.date - a.date);
  return applyAutocorrectRules(plays);
}

// Lightweight re-render after a background poll — does NOT restore settings or click period buttons.
function refreshAfterPoll() {
  if (!allPlays.length) return;
  firstSeenMaps = null;
  _certTimeline = null;   // plays changed — the certification dates move with them
  stampPlays(allPlays);   // polled-in plays arrive unstamped; re-stamp the array
  window.firstScrobbleDate = _earliestPlayDate();
  updateMastheadDynamic();
  populateYearPicker();
  // New data arrived via poll — flag unvisited tabs with badge (features 9/17)
  dcNavMarkDataLoaded();
  if (currentPeriod === 'rawdata') applyRawFilters();
  else if (currentPeriod === 'graphs') renderGraphs();
  else if (currentPeriod === 'records') buildRecords();
  else renderAll();
  // Hero box (total plays, days listened, top artist, streak) is otherwise only
  // painted by finalizeLoad() — without this it stays frozen at the early-render
  // or cached counts even after the full history (or a poll top-up) lands.
  renderHeroStats();
  renderStreakBanner();
  // A poll top-up can include the scrobble for the song still on air — restat so its
  // "43rd play" chip doesn't sit one behind.
  refreshNowPlayingStats();
}

async function pollLastFm() {
  const username = getLastFmUser();
  if (username && allPlays.length) {
    try {
      const data = await fetchLastFmPage(username, 1);
      let tracks = data.recenttracks.track;
      if (!Array.isArray(tracks)) tracks = tracks ? [tracks] : [];
      const newestKnown = allPlays[0].date;
      const newTracks = tracks.filter(tr => tr.date?.uts && new Date(parseInt(tr.date.uts) * 1000) > newestKnown);
      if (newTracks.length > 0) {
        const newPlays = applyAutocorrectRules(newTracks.map(tr => {
          const ar = (tr.artist?.['#text']) || '';
          return { title: tr.name || '', artist: ar, artists: splitArtists(ar), album: tr.album?.['#text'] || '—', date: new Date(parseInt(tr.date.uts) * 1000) };
        }));
        allPlays = [...newPlays, ...allPlays];
        // Update IDB cache data while preserving the original ts so the 6-hour full sync still fires on schedule
        const cached = await loadFromIDB(IDB_LASTFM_KEY);
        if (cached) {
          const newCompact = newTracks.map(tr => [tr.name || '', tr.artist?.['#text'] || '', tr.album?.['#text'] || '', parseInt(tr.date.uts)]);
          await saveToIDB(IDB_LASTFM_KEY, { data: [...newCompact, ...cached.data], ts: cached.ts });
        }
        lastSyncTime = new Date();
        setSyncStatus(t('sync_ok', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString() }), 'ok');
        refreshAfterPoll();
      }
    } catch (e) { /* silent — full sync will catch up */ }
  }
  clearTimeout(pollTimer);
  pollTimer = setTimeout(pollLastFm, POLL_INTERVAL_MS);
}

// ─── NOW PLAYING · "ON AIR" BAR ───────────────────────────────
//
// Last.fm marks the in-progress track in user.getRecentTracks with
// @attr.nowplaying="true" and *no* date — it isn't a scrobble yet, which is
// exactly why the history sync above skips it (`if (tr.date && tr.date.uts)`).
// So the live track already arrives with every sync; it just gets discarded.
// This polls for it on its own short interval, because the song changes every
// few minutes while the history poll only needs to run every 30.
//
// Spotify listeners are covered by this too: Spotify scrobbles to Last.fm, so a
// Spotify play shows up here within seconds. There is no direct Spotify path —
// see the note on startNowPlaying() for what that would take.
//
// The bar's source is deliberately decoupled from the charts' source. A Sheets or
// CSV user with a connected Last.fm account gets the live bar over their own
// charts — see getNowPlayingUser().
const NOW_PLAYING_POLL_MS = 45 * 1000;
// Last.fm's "no artwork" star placeholder — served as a real image, so it has to
// be filtered by hash or every art-less track gets a grey star instead of initials.
const LASTFM_ART_PLACEHOLDER = '2a96cbd8b46e442fc41c2b86b821562f';

let npTimer      = null;
let npKeyShowing = null;  // identity of the track currently painted, so we only repaint on change
let npTrack      = null;  // last track we painted, kept so stats can be recomputed in place
let npSince      = 0;     // when we first saw it — drives the elapsed clock
let npTickTimer  = null;
let npArtToken   = 0;     // guards against a slow art fetch landing after the track changed
let npGen        = 0;     // poll generation — see pollNowPlaying()
let npUser       = null;  // account the running chain is polling, for idempotent starts

function _npKey(title, artist) { return `${title}|||${artist}`.toLowerCase(); }

// Whose live track to show. On Last.fm that's the charting username; on Sheets or
// CSV it falls back to the account connected for scrobbling, which the app already
// keeps regardless of data source (see saveSourceConfig — those credentials are
// "for scrobbling rather than reading"). A spreadsheet can never carry a
// now-playing signal of its own: a row only appears once the song has finished.
function getNowPlayingUser() {
  return getDataSource() === 'lastfm'
    ? (getLastFmUser() || getScrobbleUser())
    : getScrobbleUser();
}

async function fetchNowPlaying(username) {
  const url = `https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks`
    + `&user=${encodeURIComponent(username)}&api_key=${LASTFM_KEY}`
    + `&format=json&limit=1`;
  const res = await fetch(url);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const data = await res.json();
  if (data.error) throw new Error(data.message);
  let tracks = data.recenttracks?.track;
  if (!Array.isArray(tracks)) tracks = tracks ? [tracks] : [];
  const tr = tracks[0];
  if (!tr || tr['@attr']?.nowplaying !== 'true') return null;

  const lfmArt = (tr.image || [])
    .map(i => i['#text'])
    .filter(u => u && !u.includes(LASTFM_ART_PLACEHOLDER))
    .pop() || '';

  // Run it through the user's autocorrect rules so a renamed artist/title matches
  // the same entry in allPlays that the charts show — otherwise the play count
  // below reads 0 for anything the user has corrected.
  const [play] = applyAutocorrectRules([{
    title:  tr.name || '',
    artist: tr.artist?.['#text'] || '',
    album:  tr.album?.['#text'] || '—',
    artists: splitArtists(tr.artist?.['#text'] || ''),
    date: new Date(),
  }]);
  return { ...play, lfmArt };
}

// How many times this exact song already appears in the loaded history, plus the
// artist's total. Cheap enough to run per track change; not per poll.
// Returns null before any history has loaded — the bar shows within a second of
// page load, long before a large Last.fm download finishes, and 0 plays there
// would read as a false "First time" flag rather than "not counted yet".
function _npHistory(track) {
  if (!allPlays.length) return null;
  let song = 0, artist = 0;
  const norm = s => (s || '').toLowerCase().trim();
  const tKey = norm(track.title);
  const aRaw = norm(track.artist);
  // Artist counting follows p.artists — the comma-split list — because that is how
  // every artist chart in the app credits a play: "Calvin Harris, Dua Lipa" counts
  // toward both. Matching the raw p.artist string instead silently under-reported
  // every collaboration, so this chip disagreed with the Artists chart.
  const aKeys = new Set((track.artists?.length ? track.artists : [track.artist || '']).map(norm));
  for (const p of allPlays) {
    // Song identity mirrors songKey() (title + the raw artist string) so this chip
    // agrees with the Songs chart entry for the same play. Counted independently of
    // the artist match below — the two charts key on deliberately different things.
    if (norm(p.title) === tKey && norm(p.artist) === aRaw) song++;
    const pArtists = (p.artists && p.artists.length) ? p.artists : [p.artist || ''];
    for (const a of pArtists) {
      if (aKeys.has(norm(a))) { artist++; break; } // break: one play, counted once
    }
  }
  return { song, artist };
}

function _npOrdinal(n) {
  const rem100 = n % 100;
  // 11th/12th/13th are the exceptions to the last-digit rule
  const suffix = (rem100 >= 11 && rem100 <= 13) ? 'th'
    : (['th', 'st', 'nd', 'rd'][n % 10] || 'th');
  return n.toLocaleString() + suffix;
}

function _npElapsed() {
  const secs = Math.max(0, Math.floor((Date.now() - npSince) / 1000));
  const m = Math.floor(secs / 60);
  return `${m}:${String(secs % 60).padStart(2, '0')}`;
}

function _npTick() {
  const el = document.getElementById('npElapsed');
  if (el) el.textContent = _npElapsed();
}

function hideNowPlaying() {
  const el = document.getElementById('nowPlayingBar');
  if (el) { el.style.display = 'none'; el.innerHTML = ''; }
  npKeyShowing = null;
  npTrack      = null;
  clearInterval(npTickTimer);
  npTickTimer = null;
}

// Repaint the play-count chips for the track already on air, without restarting its
// elapsed clock. Called once history lands (or gets topped up), since the bar can
// appear well before a large Last.fm download finishes.
function refreshNowPlayingStats() {
  if (npTrack && allPlays.length) renderNowPlaying(npTrack, { restat: true });
}

function renderNowPlaying(track, opts) {
  const el = document.getElementById('nowPlayingBar');
  if (!el) return;
  if (!track) { hideNowPlaying(); return; }

  const key = _npKey(track.title, track.artist);
  // Same song still spinning — leave the bar (and its running clock) alone, unless
  // this is an explicit restat after history finished loading.
  if (key === npKeyShowing && !opts?.restat) return;
  npKeyShowing = key;
  npTrack      = track;
  if (!opts?.restat) npSince = Date.now();
  const token  = ++npArtToken;

  const stats    = _npHistory(track);
  const hasAlbum = track.album && track.album !== '—';
  const fallback = initials(hasAlbum ? track.album : track.title);

  // "your 43rd play" is only meaningful once there's history behind it; a track the
  // user has never played before gets the more interesting FIRST TIME flag instead.
  // Both are withheld until the history is actually loaded (stats === null).
  const countChip = !stats ? ''
    : stats.song > 0
      ? `<span class="np-chip np-chip-count">${esc(t('np_nth_play', { n: _npOrdinal(stats.song + 1) }))}</span>`
      : `<span class="np-chip np-chip-first">${esc(t('np_first_time'))}</span>`;
  const artistChip = (stats && stats.artist > 0)
    ? `<span class="np-chip">${esc(t('np_by_artist', { n: stats.artist.toLocaleString() }))}</span>`
    : '';

  el.className = 'np-bar';
  el.innerHTML = `
    <div class="np-art-wrap">
      <div class="np-art-init" id="npArtInit">${esc(fallback)}</div>
    </div>
    <div class="np-main" aria-live="polite">
      <div class="np-label">
        <span class="np-eq" aria-hidden="true"><i></i><i></i><i></i><i></i></span>
        <span class="np-onair">${esc(t('np_onair'))}</span>
        <span class="np-source">${esc(t('np_via_lastfm'))}</span>
      </div>
      <div class="np-title">${esc(track.title)}</div>
      <div class="np-artist">${esc(track.artist)}${hasAlbum ? ` · <em>${esc(track.album)}</em>` : ''}</div>
      <div class="np-chips">${countChip}${artistChip}</div>
    </div>
    <div class="np-right" aria-hidden="true">
      <span class="np-elapsed-label">${esc(t('np_listening'))}</span>
      <span class="np-elapsed" id="npElapsed">0:00</span>
    </div>
  `;
  el.style.display = '';

  clearInterval(npTickTimer);
  npTickTimer = setInterval(_npTick, 1000);
  _npTick();

  // Art resolves after paint so the bar appears instantly. The <img> is only created
  // once a URL exists, so an unresolved lookup just leaves the initials tile.
  (async () => {
    let url = '';
    try {
      url = (hasAlbum ? await getAlbumImage(track.album, track.artist)
                      : await getTrackImage(track.title, track.artist)) || '';
    } catch (e) { /* fall through to the Last.fm image */ }
    if (!url) url = track.lfmArt;
    if (!url || token !== npArtToken) return; // track changed while we were fetching
    const wrap = el.querySelector('.np-art-wrap');
    const init = document.getElementById('npArtInit');
    if (!wrap || !init) return;
    const img = document.createElement('img');
    img.className = 'np-art';
    img.alt = '';
    img.onload  = () => { init.style.display = 'none'; };
    img.onerror = () => { img.remove(); };
    img.src = url;
    wrap.appendChild(img);
  })();
}

async function pollNowPlaying(gen) {
  const username = getNowPlayingUser();
  if (!username) { hideNowPlaying(); return; }
  // Skip the request entirely while the tab is backgrounded — nobody is looking at
  // the bar, and this poll is 40x more frequent than the history one.
  if (!document.hidden) {
    try {
      renderNowPlaying(await fetchNowPlaying(username));
    } catch (e) { /* silent — transient Last.fm hiccup, next tick retries */ }
  }
  // A restart during the await above (tab refocus while the fetch was still open)
  // bumps npGen. clearTimeout can't cancel an already-running async call, so the
  // superseded one has to bow out here or we'd end up with two polling chains.
  if (gen !== npGen) return;
  clearTimeout(npTimer);
  npTimer = setTimeout(() => pollNowPlaying(gen), NOW_PLAYING_POLL_MS);
}

// Direct Spotify would need more than a new fetch here: backend/spotify.py still
// has the OAuth callback TODO (tokens are never stored or refreshed), its SCOPES
// lack user-read-currently-playing, and the app sits under Spotify's 5-user
// development-mode cap until an extended-quota application is approved.
// force:true restarts an already-running chain to fetch immediately — used on tab
// refocus, where the point is to skip the rest of the current 45s wait.
function startNowPlaying({ force = false } = {}) {
  const user = getNowPlayingUser();
  if (!user) { stopNowPlaying(); return; }
  // Several boot paths legitimately reach this (init, sync, auth connect). Without
  // this guard each would stack another immediate fetch onto a live chain.
  if (!force && npUser === user) return;
  npUser = user;
  clearTimeout(npTimer);
  pollNowPlaying(++npGen);
}

function stopNowPlaying() {
  clearTimeout(npTimer);
  npTimer = null;
  npUser  = null;
  npGen++;               // orphans any poll currently awaiting a response
  hideNowPlaying();
}

// Coming back to the tab: refresh immediately rather than waiting out the
// remainder of a 45s tick that ran against a stale, possibly long-finished song.
document.addEventListener('visibilitychange', () => {
  if (!document.hidden && getNowPlayingUser()) startNowPlaying({ force: true });
});

async function pollSheets() {
  try {
    const res = await fetch(getSheetUrl() + '&t=' + Date.now());
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const buffer = await res.arrayBuffer();
    const text = new TextDecoder('utf-8').decode(buffer);
    const newPlays = parsePlaysCsv(text);
    if (newPlays) {
      const changed = newPlays.length !== allPlays.length ||
        (newPlays.length > 0 && allPlays.length > 0 && newPlays[0].date.getTime() !== allPlays[0].date.getTime());
      if (changed) {
        allPlays = newPlays;
        // Preserve original ts so the 6-hour full sync still fires on schedule
        const cached = await loadFromIDB(IDB_SHEETS_KEY);
        await saveToIDB(IDB_SHEETS_KEY, { ts: cached ? cached.ts : Date.now(), csv: text });
        lastSyncTime = new Date();
        setSyncStatus(t('sync_ok', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString() }), 'ok');
        refreshAfterPoll();
      }
    }
  } catch (e) { /* silent — full sync will catch up */ }
  clearTimeout(pollTimer);
  pollTimer = setTimeout(pollSheets, POLL_INTERVAL_MS);
}

// Stale-while-revalidate: the cached CSV is already parsed and on screen — fetch a fresh
// copy in the background and quietly swap it in via refreshAfterPoll (no skeleton, no
// settings restore). Unlike pollSheets this refreshes the cache timestamp, since it is a
// complete fetch equivalent to a full sync.
async function revalidateSheetsCache() {
  setSyncStatus(t('sync_connecting'), 'loading');
  try {
    const text = await fetchSheetCsv();
    const newPlays = parsePlaysCsv(text);
    if (newPlays) {
      allPlays = newPlays;
      lastSyncTime = new Date();
      localStorage.setItem('dc_sync_ts', lastSyncTime.getTime().toString());
      await saveToIDB(IDB_SHEETS_KEY, { ts: lastSyncTime.getTime(), csv: text });
      setSyncStatus(t('sync_ok', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString() }), 'ok');
      refreshAfterPoll();
    }
  } catch (e) { /* cached charts stay on screen — the scheduled sync/poll will retry */ }
  clearTimeout(syncTimer);
  syncTimer = setTimeout(syncFromSheets, SYNC_INTERVAL_MS);
  clearTimeout(pollTimer);
  pollTimer = setTimeout(pollSheets, POLL_INTERVAL_MS);
}

// ─── DATA SOURCE MODAL ─────────────────────────────────────────
function populateTzSelect() {
  const sel = document.getElementById('srcTimezone');
  if (sel.dataset.populated) return;
  sel.dataset.populated = '1';
  let zones;
  try { zones = Intl.supportedValuesOf('timeZone'); }
  catch(e) {
    zones = ['UTC','America/Anchorage','America/Los_Angeles','America/Denver','America/Chicago',
             'America/New_York','America/Sao_Paulo','Atlantic/Azores','Europe/London','Europe/Paris',
             'Europe/Berlin','Europe/Helsinki','Asia/Dubai','Asia/Karachi','Asia/Kolkata',
             'Asia/Dhaka','Asia/Bangkok','Asia/Singapore','Asia/Manila','Asia/Tokyo',
             'Australia/Sydney','Pacific/Auckland','Pacific/Honolulu'];
  }
  const now = new Date();
  function getTzOffset(tz) {
    try {
      const parts = new Intl.DateTimeFormat('en', { timeZoneName: 'shortOffset', timeZone: tz }).formatToParts(now);
      return parts.find(p => p.type === 'timeZoneName')?.value || '';
    } catch(e) { return ''; }
  }
  const groups = {};
  for (const tz of zones) {
    const slash = tz.indexOf('/');
    const region = slash >= 0 ? tz.slice(0, slash) : 'Etc';
    (groups[region] || (groups[region] = [])).push(tz);
  }
  for (const [region, tzs] of Object.entries(groups).sort(([a], [b]) => a.localeCompare(b))) {
    const grp = document.createElement('optgroup');
    grp.label = region;
    for (const tz of tzs) {
      const opt = document.createElement('option');
      opt.value = tz;
      const offset = getTzOffset(tz);
      opt.textContent = tz.replace(/_/g, ' ') + (offset ? ' (' + offset + ')' : '');
      grp.appendChild(opt);
    }
    sel.appendChild(grp);
  }
}

// Settings modal tabs. Panels are plain sections toggled with [hidden]; the
// underline slides via --tab-i so no layout measuring is involved.
const SETTINGS_TABS = ['source', 'charts', 'profile'];

function switchSettingsTab(name) {
  const i = SETTINGS_TABS.indexOf(name);
  if (i === -1) return;
  const strip = document.querySelector('#sourceModal .set-tabs');
  if (strip) strip.style.setProperty('--tab-i', i);
  SETTINGS_TABS.forEach((t, idx) => {
    const cap  = t.charAt(0).toUpperCase() + t.slice(1);
    const btn  = document.getElementById('setTab' + cap);
    const pane = document.getElementById('setPanel' + cap);
    if (btn) {
      btn.classList.toggle('is-active', idx === i);
      btn.setAttribute('aria-selected', idx === i ? 'true' : 'false');
    }
    if (pane) pane.hidden = idx !== i;
  });
  // Scroll back to the top of the box — panels differ wildly in height and
  // landing mid-form after a tab switch is disorienting.
  document.querySelector('#sourceModal .set-box')?.scrollIntoView({ block: 'start' });
}

function openSourceModal() {
  document.getElementById('configureSourceBtn').classList.remove('configure-attention');
  const modal = document.getElementById('sourceModal');
  modal.classList.add('open');
  switchSettingsTab('source'); // always land on the data source tab
  const src = getDataSource();
  document.getElementById('srcRadioSheets').checked = src === 'sheets';
  document.getElementById('srcRadioLastfm').checked = src === 'lastfm';
  const fileRadio = document.getElementById('srcRadioFile');
  if (fileRadio) fileRadio.checked = src === 'file';
  document.getElementById('srcDisplayName').value  = localStorage.getItem('dc_display_name') || '';
  populateTzSelect();
  document.getElementById('srcTimezone').value = userTimezone;
  document.getElementById('srcSheetId').value       = localStorage.getItem('dc_sheet_id')        || DEFAULT_SHEET_ID;
  document.getElementById('srcSheetTab').value      = localStorage.getItem('dc_sheet_tab')       || DEFAULT_SHEET_TAB;
  document.getElementById('srcSheetWriteUrl').value = localStorage.getItem('dc_sheet_write_url') || '';
  document.getElementById('srcLastfmUser').value   = getLastFmUser();
  // Only show credentials the user actually supplied. Echoing the app's own
  // default key/secret into these boxes made every save persist them as
  // "custom", and made it look like custom creds were already configured.
  document.getElementById('srcLfmApiKey').value    = localStorage.getItem('dc_lfm_api_key')    || '';
  document.getElementById('srcLfmApiSecret').value = localStorage.getItem('dc_lfm_api_secret') || '';
  document.getElementById('certAlbumGold').value    = CERT.album.gold;
  document.getElementById('certAlbumPlat').value    = CERT.album.plat;
  document.getElementById('certAlbumDiamond').value = CERT.album.diamond;
  document.getElementById('certSongGold').value    = CERT.song.gold;
  document.getElementById('certSongPlat').value    = CERT.song.plat;
  document.getElementById('certSongDiamond').value = CERT.song.diamond;
  document.getElementById('eventsArtistLimitSelect').value = eventsArtistLimit;
  document.getElementById('srcNoArtistSplit').checked = noArtistSplit;
  document.getElementById('srcChartAnim').checked = chartAnimEnabled;
  updateSourceModalFields();
  initSrcFileUpload();
}

function closeSourceModal() {
  document.getElementById('sourceModal').classList.remove('open');
  lfmAuthStopPolling(); // nothing to watch for once the panel is gone
}

function resetCertDefaults() {
  document.getElementById('certAlbumGold').value    = CERT_DEFAULTS.album.gold;
  document.getElementById('certAlbumPlat').value    = CERT_DEFAULTS.album.plat;
  document.getElementById('certAlbumDiamond').value = CERT_DEFAULTS.album.diamond;
  document.getElementById('certSongGold').value    = CERT_DEFAULTS.song.gold;
  document.getElementById('certSongPlat').value    = CERT_DEFAULTS.song.plat;
  document.getElementById('certSongDiamond').value = CERT_DEFAULTS.song.diamond;
}

function updateSourceModalFields() {
  const isSheets = document.getElementById('srcRadioSheets').checked;
  const isFile   = document.getElementById('srcRadioFile')?.checked;
  document.getElementById('srcSheetsFields').style.display  = isSheets ? '' : 'none';
  document.getElementById('srcLastfmFields').style.display  = (!isSheets && !isFile) ? '' : 'none';
  const fileEl = document.getElementById('srcFileFields');
  if (fileEl) fileEl.style.display = isFile ? '' : 'none';
  // The Last.fm account row now sits outside the three source panels and stays on
  // screen for all of them — a Sheets or CSV user needs it for scrobbling and for
  // the live ON AIR bar — so its status is refreshed unconditionally.
  updateLfmAuthStatus();
  // Reopened mid-authorization: pick the watch back up instead of leaving
  // the user staring at a stale "waiting" line.
  if (getLfmPendingToken()) lfmAuthStartPolling();
}

function saveSourceConfig() {
  const displayName = document.getElementById('srcDisplayName').value.trim();
  if (displayName) localStorage.setItem('dc_display_name', displayName);
  else localStorage.removeItem('dc_display_name');
  const selTz = document.getElementById('srcTimezone').value;
  if (selTz) {
    userTimezone = selTz;
    _tzFmt = null;
    // Every period key on every play was computed in the old zone — retire them.
    dcInvalidatePlayStamps();
    stampPlays(allPlays);
    try { localStorage.setItem('dc_timezone', selTz); } catch(e) {}
  }
  updateMastheadDynamic();
  const isFile   = document.getElementById('srcRadioFile')?.checked;
  const src = document.getElementById('srcRadioSheets').checked ? 'sheets' : (isFile ? 'file' : 'lastfm');
  localStorage.setItem('dc_source', src);
  if (src === 'file') {
    deleteFromIDB(IDB_LASTFM_KEY);
    deleteFromIDB(IDB_SHEETS_KEY);
    localStorage.removeItem('dc_sync_ts');
    localStorage.removeItem('dc_lastfm_ts');
    // Clean up sheet config left over from a prior Sheets setup — otherwise code that
    // checks for a configured sheet by key presence alone (without also checking
    // getDataSource()==='sheets') can still see a stale write URL after switching away.
    localStorage.removeItem('dc_sheet_id');
    localStorage.removeItem('dc_sheet_tab');
    localStorage.removeItem('dc_sheet_gid');
    localStorage.removeItem('dc_sheet_write_url');
    closeSourceModal();
    document.getElementById('srcFileInput')?.click();
    return;
  }
  if (src === 'sheets') {
    const rawInput = document.getElementById('srcSheetId').value.trim();
    const urlMatch = rawInput.match(/spreadsheets\/d\/([^\/\?#]+)/);
    const sheetId  = urlMatch ? urlMatch[1] : rawInput;
    const gidMatch = rawInput.match(/[#&?]gid=(\d+)/);
    localStorage.setItem('dc_sheet_id', sheetId);
    if (gidMatch) localStorage.setItem('dc_sheet_gid', gidMatch[1]);
    else localStorage.removeItem('dc_sheet_gid');
    localStorage.setItem('dc_sheet_tab', document.getElementById('srcSheetTab').value.trim());
    const writeUrl = document.getElementById('srcSheetWriteUrl').value.trim();
    if (writeUrl) localStorage.setItem('dc_sheet_write_url', writeUrl);
    else localStorage.removeItem('dc_sheet_write_url');
    updateScrobbleBtn();
    deleteFromIDB(IDB_LASTFM_KEY);
    localStorage.removeItem('dc_lastfm_ts'); // clean up old key
  } else {
    localStorage.setItem('dc_lastfm_user', document.getElementById('srcLastfmUser').value.trim());
    deleteFromIDB(IDB_SHEETS_KEY);
    localStorage.removeItem('dc_sync_ts');
    // Same cleanup as the file branch above — a prior Sheets setup shouldn't outlive
    // switching to Last.fm (see comment there).
    localStorage.removeItem('dc_sheet_id');
    localStorage.removeItem('dc_sheet_tab');
    localStorage.removeItem('dc_sheet_gid');
    localStorage.removeItem('dc_sheet_write_url');
  }
  // Custom LFM API credentials are kept whatever the data source is, since
  // they're for scrobbling rather than reading. Clearing a field now clears the
  // stored value too, so there's a way back to the app's built-in credentials.
  const apiKey    = document.getElementById('srcLfmApiKey').value.trim();
  const apiSecret = document.getElementById('srcLfmApiSecret').value.trim();
  if (apiKey) localStorage.setItem('dc_lfm_api_key', apiKey);
  else localStorage.removeItem('dc_lfm_api_key');
  if (apiSecret) localStorage.setItem('dc_lfm_api_secret', apiSecret);
  else localStorage.removeItem('dc_lfm_api_secret');
  const ag = parseInt(document.getElementById('certAlbumGold').value)    || CERT_DEFAULTS.album.gold;
  const ap = parseInt(document.getElementById('certAlbumPlat').value)    || CERT_DEFAULTS.album.plat;
  const ad = parseInt(document.getElementById('certAlbumDiamond').value) || CERT_DEFAULTS.album.diamond;
  const sg = parseInt(document.getElementById('certSongGold').value)    || CERT_DEFAULTS.song.gold;
  const sp = parseInt(document.getElementById('certSongPlat').value)    || CERT_DEFAULTS.song.plat;
  const sd = parseInt(document.getElementById('certSongDiamond').value) || CERT_DEFAULTS.song.diamond;
  CERT.album.gold = ag; CERT.album.plat = ap; CERT.album.diamond = ad;
  CERT.song.gold  = sg; CERT.song.plat  = sp; CERT.song.diamond  = sd;
  localStorage.setItem('dc_cert_config', JSON.stringify({ ag, ap, ad, sg, sp, sd }));
  // New thresholds mean new crossing plays, so every award moves to a new date.
  _certTimeline = null;
  const newEventsLimit = parseInt(document.getElementById('eventsArtistLimitSelect').value) || 50;
  if (newEventsLimit !== eventsArtistLimit) {
    eventsArtistLimit = newEventsLimit;
    localStorage.setItem('dc_events_artist_limit', newEventsLimit);
    localStorage.removeItem(EVENTS_CACHE_KEY);
    const sel = document.getElementById('eventsLimitSelect');
    if (sel) sel.value = eventsArtistLimit;
  }
  noArtistSplit = document.getElementById('srcNoArtistSplit').checked;
  localStorage.setItem('dc_no_artist_split', noArtistSplit ? '1' : '0');
  chartAnimEnabled = document.getElementById('srcChartAnim').checked;
  localStorage.setItem('dc_chart_anim', chartAnimEnabled ? '1' : '0');
  closeSourceModal();
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  syncNow();
}

document.getElementById('syncNowBtn').addEventListener('click', syncNow);

// ─── LANDING / ONBOARDING ──────────────────────────────────────
function needsOnboarding() {
  if (!localStorage.getItem('dc_source')) return true;
  const src = getDataSource();
  if (src === 'sheets' && !localStorage.getItem('dc_sheet_id')) return true;
  if (src === 'lastfm' && !getLastFmUser()) return true;
  return false;
}

let _landingSrc = null;

const SAMPLE_SHEET_URL = 'https://docs.google.com/spreadsheets/d/1ulWuTKxreKLUWGBEI0g2d5iMgjHu6y02IFzg6A7BzVA/edit?gid=287480472#gid=287480472';

function loadSampleData() {
  selectLandingSource('sheets');
  const input = document.getElementById('landingSheetId');
  input.value = SAMPLE_SHEET_URL;
  input.classList.remove('landing-input-error');
}

function startWithSampleData() {
  loadSampleData();
  startFromLanding();
}

/* Musical notes flying out from behind a landing card on click.
   The notes live in a layer that paints under the clicked card but *over* the
   other two (see .landing-note-burst in style.css): each note is born hidden
   behind its own card and only shows once it clears that card's edge, then
   sails freely across its neighbours. Spawn points sit on an ellipse just
   inside the card's upper half and every note travels outward/upward from
   there, so nothing has to cross the whole card before becoming visible.
   Colour comes from the card's own --note-color (sheet green / vinyl rose /
   upload accent) — resolved here because the layer is outside the card and so
   can't inherit it. */
const LANDING_NOTE_GLYPHS = ['♪', '♫', '♬', '♩', '♪', '♫'];
let _landingBurstTimer = null;
function burstLandingNotes(card) {
  if (!card) return;
  // Respect reduced motion — a burst of flying glyphs is pure decoration
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const wrap = card.parentElement; // .landing-cards
  if (!wrap) return;

  let layer = wrap.querySelector('.landing-note-burst');
  if (!layer) {
    layer = document.createElement('div');
    layer.className = 'landing-note-burst';
    layer.setAttribute('aria-hidden', 'true');
    wrap.appendChild(layer);
  }
  // Impatient clicking shouldn't pile up hundreds of nodes
  if (layer.childElementCount > 40) layer.innerHTML = '';

  // Lift the clicked card above the note layer for as long as its notes fly, so
  // they stay hidden behind *this* card while passing over the other two. The
  // class comes off again afterwards, otherwise the last-clicked card would keep
  // swallowing every later burst that drifts across it.
  wrap.querySelectorAll('.landing-card-bursting').forEach(c => c.classList.remove('landing-card-bursting'));
  card.classList.add('landing-card-bursting');
  clearTimeout(_landingBurstTimer);
  // Longest note lifetime: max delay (0.34s) + max duration (1.5s), rounded up
  _landingBurstTimer = setTimeout(() => card.classList.remove('landing-card-bursting'), 2000);

  const wr = wrap.getBoundingClientRect();
  const cr = card.getBoundingClientRect();
  const cx = cr.left - wr.left + cr.width / 2;
  const cy = cr.top - wr.top + cr.height / 2;
  const rx = cr.width / 2, ry = cr.height / 2;

  // The landing screen scrolls, so a note drifting past the viewport sides would
  // pop a horizontal scrollbar — clamp horizontal travel to the visible width.
  const screen = document.getElementById('landingScreen');
  const sw = screen ? screen.clientWidth : window.innerWidth;
  const minX = -wr.left + 10, maxX = -wr.left + sw - 26;

  // Colour: computed value resolves the var() chain to a real colour; if a
  // browser hands back the literal token, the CSS fallback takes over.
  let color = getComputedStyle(card).getPropertyValue('--note-color').trim();
  if (!color || color.indexOf('var(') === 0) color = '';

  const N = 9; // "sparse" — a handful of notes, not a confetti cannon
  for (let i = 0; i < N; i++) {
    // Fan across the upper half (-175deg .. -5deg), stratified so the notes
    // spread out instead of clumping, with a little jitter per slot
    const ang = (-175 + (i + Math.random() * 0.85) * (170 / N)) * Math.PI / 180;
    const f = 0.5 + Math.random() * 0.25;            // spawn just inside the card edge
    const sx = cx + Math.cos(ang) * rx * f;
    const sy = cy + Math.sin(ang) * ry * f;
    const dist = 110 + Math.random() * 100;
    let dx = Math.cos(ang) * dist;
    const dy = Math.sin(ang) * dist;                 // negative = upward
    if (sx + dx < minX) dx = minX - sx;
    if (sx + dx > maxX) dx = maxX - sx;

    const n = document.createElement('span');
    n.className = 'landing-note';
    n.textContent = LANDING_NOTE_GLYPHS[(Math.random() * LANDING_NOTE_GLYPHS.length) | 0];
    n.style.left = sx.toFixed(1) + 'px';
    n.style.top = sy.toFixed(1) + 'px';
    if (color) n.style.setProperty('--note-color', color);
    n.style.setProperty('--note-dx', dx.toFixed(1) + 'px');
    n.style.setProperty('--note-dy', dy.toFixed(1) + 'px');
    n.style.setProperty('--note-rot', (Math.random() * 70 - 35).toFixed(1) + 'deg');
    n.style.setProperty('--note-size', (0.85 + Math.random() * 0.5).toFixed(2) + 'rem');
    n.style.setProperty('--note-dur', (1 + Math.random() * 0.5).toFixed(2) + 's');
    n.style.setProperty('--note-delay', (i * 0.035 + Math.random() * 0.06).toFixed(3) + 's');
    n.addEventListener('animationend', () => n.remove());
    layer.appendChild(n);
  }
}

function selectLandingSource(src) {
  _landingSrc = src;
  burstLandingNotes(document.getElementById('landingCard' + src.charAt(0).toUpperCase() + src.slice(1)));
  document.querySelectorAll('.landing-card').forEach(c => c.classList.remove('active'));
  document.querySelectorAll('.landing-card-config').forEach(c => { c.style.display = 'none'; });
  const card = document.getElementById('landingCard' + src.charAt(0).toUpperCase() + src.slice(1));
  if (card) card.classList.add('active');
  const cfg = document.getElementById('landingConfig' + src.charAt(0).toUpperCase() + src.slice(1));
  if (cfg) cfg.style.display = 'flex';
  document.getElementById('landingCta').style.display = 'flex';
}

function startFromLanding() {
  const src = _landingSrc;
  if (!src) return;
  if (src === 'sheets') {
    const rawId = document.getElementById('landingSheetId').value.trim();
    if (!rawId) {
      document.getElementById('landingSheetId').focus();
      document.getElementById('landingSheetId').classList.add('landing-input-error');
      return;
    }
    document.getElementById('landingSheetId').classList.remove('landing-input-error');
    const tab = document.getElementById('landingSheetTab').value.trim() || DEFAULT_SHEET_TAB;
    localStorage.setItem('dc_source', 'sheets');
    localStorage.setItem('dc_sheet_id', rawId);
    localStorage.setItem('dc_sheet_tab', tab);
  } else if (src === 'lastfm') {
    const user = document.getElementById('landingLastfmUser').value.trim();
    if (!user) {
      document.getElementById('landingLastfmUser').focus();
      document.getElementById('landingLastfmUser').classList.add('landing-input-error');
      return;
    }
    document.getElementById('landingLastfmUser').classList.remove('landing-input-error');
    localStorage.setItem('dc_source', 'lastfm');
    localStorage.setItem('dc_lastfm_user', user);
  } else if (src === 'file') {
    localStorage.setItem('dc_source', 'file');
  }
  document.getElementById('landingScreen').style.display = 'none';
  document.getElementById('mainApp').style.display = 'block';
  showSkeleton();
  updateMastheadDynamic();
  dcMaybeShowWelcomeGate(); // first visit: route new users into the Charts Guide
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  if (src === 'sheets') syncFromSheets();
  else if (src === 'lastfm') syncFromLastFm();
  else {
    document.getElementById('uploadZone').style.display = 'block';
  }
}

function skipLanding() {
  document.getElementById('landingScreen').style.display = 'none';
  document.getElementById('mainApp').style.display = 'block';
  showSkeleton();
  dcMaybeShowWelcomeGate(); // first visit: route new users into the Charts Guide
  syncNow();
}

// Cursor-reactive landing orbs — a damped, clamped nudge toward the pointer layered
// on top of the existing CSS orb-drift loop (via --mx/--my custom props, see
// style.css) so the background feels alive rather than just looping on a timer.
// Orb-1 (top-left) leans toward the cursor; orb-2 (bottom-right) leans the opposite
// way at reduced strength, for a subtle parallax-depth read instead of both blobs
// sliding in lockstep.
(function initLandingOrbParallax() {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const orb1 = document.querySelector('.landing-orb-1');
  const orb2 = document.querySelector('.landing-orb-2');
  const screen = document.getElementById('landingScreen');
  if (!orb1 || !orb2 || !screen) return;

  const MAX_OFFSET = 70; // px — clamps the nudge (raised from 22: at 22px against
                          // 500px/420px orbs the movement barely registered)
  const EASE = 0.09;     // lower = lazier follow (damping factor applied per animation frame)
  let targetX = 0, targetY = 0;
  let curX = 0, curY = 0;
  let rafId = null;

  function tick() {
    curX += (targetX - curX) * EASE;
    curY += (targetY - curY) * EASE;
    orb1.style.setProperty('--mx', curX.toFixed(1) + 'px');
    orb1.style.setProperty('--my', curY.toFixed(1) + 'px');
    orb2.style.setProperty('--mx', (-curX * 0.75).toFixed(1) + 'px');
    orb2.style.setProperty('--my', (-curY * 0.75).toFixed(1) + 'px');
    if (Math.abs(targetX - curX) > 0.1 || Math.abs(targetY - curY) > 0.1) {
      rafId = requestAnimationFrame(tick);
    } else {
      rafId = null;
    }
  }

  window.addEventListener('mousemove', (e) => {
    if (getComputedStyle(screen).display === 'none') return; // only while onboarding is shown
    const nx = (e.clientX / window.innerWidth) * 2 - 1;  // -1..1 across the viewport
    const ny = (e.clientY / window.innerHeight) * 2 - 1;
    targetX = nx * MAX_OFFSET;
    targetY = ny * MAX_OFFSET;
    if (!rafId) rafId = requestAnimationFrame(tick);
  }, { passive: true });
})();

// Auto-sync on page load — use cached data if synced within the last hour
window.addEventListener('load', async () => {
  updateMastheadDynamic();
  updateLfmAuthStatus();
  localStorage.removeItem('dc_sync_csv'); // clean up old oversized key if present

  if (needsOnboarding()) {
    document.getElementById('landingScreen').style.display = 'flex';
    return;
  }

  document.getElementById('mainApp').style.display = 'block';
  showSkeleton();
  dcMaybeShowWelcomeGate(); // covers already-configured users who predate the gate
  await initRulesCache();
  // Don't block first paint on the Apps Script round-trip — a cold Apps Script can take
  // several seconds. Parse with the locally cached rules now; if the sheet copy turns out
  // to differ, re-apply the merged rules to the loaded plays and quietly re-render.
  loadRulesFromSheet().then(changed => {
    if (changed && allPlays.length) {
      allPlays = applyAutocorrectRules(allPlays);
      refreshAfterPoll();
    }
  });

  if (!localStorage.getItem('dc_display_name')) {
    const btn = document.getElementById('configureSourceBtn');
    btn.classList.add('configure-attention');
    btn.title = 'Start here — configure your data source';
  }

  // Before the source branches below, because the ON AIR bar is source-independent:
  // Sheets and CSV users get it too whenever a Last.fm account is connected. Placed
  // here so every boot path is covered, including the fresh-cache branch that never
  // reaches syncFromSheets().
  startNowPlaying();

  const src = getDataSource();
  if (src === 'lastfm') {
    syncFromLastFm();
    return;
  }
  if (src === 'file') {
    const cached = await loadFromIDB(IDB_FILE_KEY);
    if (cached && cached.data) {
      allPlays = applyAutocorrectRules(cached.data.map(([title, artist, album, uts]) => {
        const ar = artist || '';
        return { title, artist: ar, artists: splitArtists(ar), album: album || '—', date: new Date(uts * 1000) };
      }));
      allPlays.sort((a, b) => b.date - a.date);
      setSyncStatus(`✓ ${allPlays.length.toLocaleString()} plays loaded from file`, 'ok');
      finalizeLoad();
    } else {
      setSyncStatus('No file loaded — click ⚙ Settings to upload a file.', 'err');
    }
    return;
  }

  const cached = await loadFromIDB(IDB_SHEETS_KEY);
  const age = cached ? Date.now() - cached.ts : Infinity;
  if (cached) {
    // Stale-while-revalidate: render the IndexedDB copy immediately no matter how old it
    // is (survives tab close / browser restart) — never make the user wait on the network
    // when a local copy exists.
    lastSyncTime = new Date(cached.ts);
    parseCsv(cached.csv, true);
    const minsAgo = Math.round(age / 60000);
    setSyncStatus(t('sync_ok_cached', { time: lastSyncTime.toLocaleTimeString(), n: allPlays.length.toLocaleString(), mins: minsAgo }), 'ok');
    if (age < SYNC_INTERVAL_MS) {
      // Cache still fresh — just schedule the next full sync and background poll
      clearTimeout(syncTimer);
      syncTimer = setTimeout(syncFromSheets, SYNC_INTERVAL_MS - age);
      clearTimeout(pollTimer);
      pollTimer = setTimeout(pollSheets, POLL_INTERVAL_MS);
    } else {
      // Cache older than the sync interval — refresh in the background while the
      // cached charts stay on screen (no skeleton, no blank wait)
      revalidateSheetsCache();
    }
  } else {
    syncFromSheets();
  }
});

function parseCsv(text, fromSheets = false) {
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) {
    if (!fromSheets) return false;
    setSyncStatus(t('sync_empty'), 'err'); return false;
  }

  const headers = lines[0].split(',').map(h => h.replace(/^"|"$/g, '').trim().toLowerCase());

  const colMap = {};
  const aliases = {
    title: ['song title', 'title', 'track', 'track name', 'song name'],
    artist: ['artist', 'artist name', 'performer'],
    album: ['album', 'album name', 'release'],
    // 'uts'/'utc_time' come from the ghan.nl Last.fm exporter
    // (mainstream.ghan.nl/export.html), whose header row is
    //   uts,utc_time,artist,artist_mbid,album,album_mbid,track,track_mbid
    // — artist/album/track already matched above, so the date column was the
    // only thing standing between a 95% compatible export and a hard "missing
    // required columns" failure. Appended last on purpose: any header a file
    // could already match still wins, so this is purely an added fallback.
    // 'uts' before 'utc_time' because it is an unambiguous unix instant, while
    // utc_time is a formatted local-time string.
    datetime: ['date and time', 'date', 'datetime', 'timestamp', 'time', 'played at', 'scrobble time', 'uts', 'utc_time']
  };
  for (const [key, names] of Object.entries(aliases)) {
    for (const n of names) {
      const idx = headers.indexOf(n);
      if (idx !== -1) { colMap[key] = idx; break; }
    }
  }

  if (colMap.title === undefined || colMap.artist === undefined || colMap.datetime === undefined) {
    setSyncStatus(t('sync_missing_cols'), 'err'); return false;
  }

  allPlays = [];
  let skippedBlank = 0;
  let skippedDate = 0;
  let skippedDateSamples = [];

  // Detect date format from first data row to avoid 5-regex fallback on every row
  let fastDateParse = null;
  for (let i = 1; i < lines.length && !fastDateParse; i++) {
    const r = splitCsvRow(lines[i]);
    if (r.length < 2) continue;
    const sample = (colMap.datetime !== undefined && r[colMap.datetime] !== undefined)
      ? r[colMap.datetime].replace(/^"|"$/g, '').trim() : '';
    if (sample) fastDateParse = makeFastDateParser(sample) || parseDate; // fallback to full parser
  }
  if (!fastDateParse) fastDateParse = parseDate;

  for (let i = 1; i < lines.length; i++) {
    const row = splitCsvRow(lines[i]);
    if (row.length < 2) { skippedBlank++; continue; }
    const get = idx => (idx !== undefined && row[idx] !== undefined) ? row[idx].replace(/^"|"$/g, '').trim() : '';
    const rawDate = get(colMap.datetime);
    let dt = fastDateParse(rawDate);
    if (!dt && fastDateParse !== parseDate) dt = parseDate(rawDate); // rare fallback for outlier rows
    if (!dt || dt.getFullYear() < 2000) {
      skippedDate++;
      if (skippedDateSamples.length < 20 && rawDate) skippedDateSamples.push(`row ${i + 1}: "${rawDate}"`);
      continue;
    }
    const artistRaw = get(colMap.artist);
    allPlays.push({
      title: get(colMap.title),
      artist: artistRaw,
      artists: splitArtists(artistRaw),
      album: get(colMap.album) || '—',
      date: dt,
      // Raw epoch ms, kept only so the sort below can compare plain numbers.
      // Sorting 150k plays by `b.date - a.date` costs two Date coercions per
      // comparison, and there are ~2.6M of them.
      _ts: +dt,
      _sheetRow: i + 1,
    });
  }

  const totalSkipped = skippedBlank + skippedDate;
  if (totalSkipped > 0) {
    console.warn(`dankcharts.fm: skipped ${totalSkipped} rows total — ${skippedDate} bad/missing date, ${skippedBlank} blank/short rows.`);
    if (skippedDateSamples.length) console.warn('Date parse failures (up to 20):', skippedDateSamples);
    setSyncStatus(t('sync_warning', { total: totalSkipped, date: skippedDate, blank: skippedBlank }), 'loading');
  }

  if (allPlays.length === 0) {
    setSyncStatus(t('sync_no_valid'), 'err'); return false;
  }

  // Every object here was built in the loop above, so _ts is always present.
  allPlays.sort((a, b) => b._ts - a._ts);

  if (fromSheets) {
    const writeUrl = getSheetWriteUrl();
    if (writeUrl) autoCorrectEntries(allPlays, writeUrl);
  }

  allPlays = applyAutocorrectRules(allPlays);
  finalizeLoad();
  return true;
}

function finalizeLoad() {
  firstSeenMaps = null;
  _certTimeline = null;   // plays changed — the certification dates move with them
  stampPlays(allPlays);   // fresh play objects — give them their derived keys
  if (allPlays.length) {
    window.firstScrobbleDate = _earliestPlayDate();
    updateMastheadDynamic();
  }
  populateYearPicker();
  // Track data loads so unvisited tabs show "new" badge after a refresh (features 9/17)
  dcNavMarkDataLoaded();
  // The ON AIR bar renders before the history download finishes, so its play-count
  // chips only become computable here.
  refreshNowPlayingStats();

  // Restore saved granularity before rendering
  const savedGran = localStorage.getItem('dc_gran');
  if (savedGran && ['day', 'month', 'year'].includes(savedGran)) {
    graphGranularity = savedGran;
    document.querySelectorAll('#graphGranularity button').forEach(b => {
      b.classList.toggle('active', b.dataset.gran === graphGranularity);
    });
  }

  // Restore per-section chart sizes — falls back to old global keys for migration
  function _loadSectionSize(key, globalKey, def) {
    const saved = localStorage.getItem(key);
    if (saved != null) { const v = parseInt(saved); return v === 0 ? Infinity : v; }
    const globalSaved = globalKey ? localStorage.getItem(globalKey) : null;
    if (globalSaved != null) { const v = parseInt(globalSaved); return v === 0 ? Infinity : v; }
    return def;
  }
  chartSizeSongsW    = _loadSectionSize('dc_chartSizeSongsW',    'dc_chartSizeWeekly',  10);
  chartSizeSongsM    = _loadSectionSize('dc_chartSizeSongsM',    'dc_chartSizeMonthly', 50);
  chartSizeSongsY    = _loadSectionSize('dc_chartSizeSongsY',    'dc_chartSizeYearly',  Infinity);
  chartSizeSongsAT   = _loadSectionSize('dc_chartSizeSongsAT',   'dc_chartSizeAllTime', Infinity);
  chartSizeArtistsW  = _loadSectionSize('dc_chartSizeArtistsW',  'dc_chartSizeWeekly',  10);
  chartSizeArtistsM  = _loadSectionSize('dc_chartSizeArtistsM',  'dc_chartSizeMonthly', 50);
  chartSizeArtistsY  = _loadSectionSize('dc_chartSizeArtistsY',  'dc_chartSizeYearly',  Infinity);
  chartSizeArtistsAT = _loadSectionSize('dc_chartSizeArtistsAT', 'dc_chartSizeAllTime', Infinity);
  chartSizeAlbumsW   = _loadSectionSize('dc_chartSizeAlbumsW',   'dc_chartSizeWeekly',  10);
  chartSizeAlbumsM   = _loadSectionSize('dc_chartSizeAlbumsM',   'dc_chartSizeMonthly', 50);
  chartSizeAlbumsY   = _loadSectionSize('dc_chartSizeAlbumsY',   'dc_chartSizeYearly',  Infinity);
  chartSizeAlbumsAT  = _loadSectionSize('dc_chartSizeAlbumsAT',  'dc_chartSizeAllTime', Infinity);
  // Keep compat vars in sync with songs (songs = primary chart)
  chartSizeWeekly  = chartSizeSongsW;
  chartSizeMonthly = chartSizeSongsM;
  chartSizeYearly  = chartSizeSongsY;
  chartSizeAllTime = chartSizeSongsAT;
  // Sync active state of all per-section size buttons
  function _syncSizeBtns(id, val) {
    const str = isFinite(val) ? String(val) : '0';
    document.querySelectorAll('#' + id + ' button').forEach(b => b.classList.toggle('active', b.dataset.size === str));
  }
  _syncSizeBtns('sizeBtnsSongsW',    chartSizeSongsW);
  _syncSizeBtns('sizeBtnsSongsM',    chartSizeSongsM);
  _syncSizeBtns('sizeBtnsSongsY',    chartSizeSongsY);
  _syncSizeBtns('sizeBtnsSongsAT',   chartSizeSongsAT);
  _syncSizeBtns('sizeBtnsArtistsW',  chartSizeArtistsW);
  _syncSizeBtns('sizeBtnsArtistsM',  chartSizeArtistsM);
  _syncSizeBtns('sizeBtnsArtistsY',  chartSizeArtistsY);
  _syncSizeBtns('sizeBtnsArtistsAT', chartSizeArtistsAT);
  _syncSizeBtns('sizeBtnsAlbumsW',   chartSizeAlbumsW);
  _syncSizeBtns('sizeBtnsAlbumsM',   chartSizeAlbumsM);
  _syncSizeBtns('sizeBtnsAlbumsY',   chartSizeAlbumsY);
  _syncSizeBtns('sizeBtnsAlbumsAT',  chartSizeAlbumsAT);

  // Restore graph settings (cumulative, total volume, volume comparison)
  const savedCumArtists = localStorage.getItem('dc_gCumulativeArtists');
  if (savedCumArtists) try { gCumulativeArtists = JSON.parse(savedCumArtists); renderCumulativeChips(); } catch (e) { }
  if (localStorage.getItem('dc_gCumulativeLabels') === '1') {
    gCumulativeLabels = true;
    updateLabelButton('gCumulativeLabelsBtn', true);
  }
  const savedCumFrom = localStorage.getItem('dc_gCumulativeFrom');
  if (savedCumFrom) document.getElementById('gCumulativeFrom').value = savedCumFrom;
  const savedCumTo = localStorage.getItem('dc_gCumulativeTo');
  if (savedCumTo) document.getElementById('gCumulativeTo').value = savedCumTo;

  if (localStorage.getItem('dc_gTotalVolumeLabels') === '1') {
    gTotalVolumeLabels = true;
    updateLabelButton('gTotalVolumeLabelsBtn', true);
  }
  if (localStorage.getItem('dc_gDiscoveriesLabels') === '1') {
    gDiscoveriesLabels = true;
    updateLabelButton('gDiscoveriesLabelsBtn', true);
  }
  const savedTVFrom = localStorage.getItem('dc_gTotalVolumeFrom');
  if (savedTVFrom) document.getElementById('gTotalVolumeFrom').value = savedTVFrom;
  const savedTVTo = localStorage.getItem('dc_gTotalVolumeTo');
  if (savedTVTo) document.getElementById('gTotalVolumeTo').value = savedTVTo;

  const savedVolArtists = localStorage.getItem('dc_gVolumeArtists');
  if (savedVolArtists) try { gVolumeArtists = JSON.parse(savedVolArtists); renderVolumeChips(); } catch (e) { }
  if (localStorage.getItem('dc_gVolumeLabels') === '1') {
    gVolumeLabels = true;
    updateLabelButton('gVolumeLabelsBtn', true);
  }
  const savedVolFrom = localStorage.getItem('dc_gVolumeFrom');
  if (savedVolFrom) document.getElementById('gVolumeFrom').value = savedVolFrom;
  const savedVolTo = localStorage.getItem('dc_gVolumeTo');
  if (savedVolTo) document.getElementById('gVolumeTo').value = savedVolTo;

  // Restore race/graph settings
  const savedRaceSpeed = localStorage.getItem('dc_raceSpeed');
  if (savedRaceSpeed) {
    raceSpeed = parseFloat(savedRaceSpeed);
    document.querySelectorAll('#raceSpeedBtns button').forEach(b => b.classList.toggle('active', b.dataset.speed === savedRaceSpeed));
  }
  const savedRaceTopN = localStorage.getItem('dc_raceTopN');
  if (savedRaceTopN) {
    raceTopN = parseInt(savedRaceTopN);
    document.querySelectorAll('#raceTopNBtns button').forEach(b => b.classList.toggle('active', b.dataset.topn === savedRaceTopN));
  }
  const savedRaceType = localStorage.getItem('dc_raceType');
  if (savedRaceType) {
    raceType = savedRaceType;
    document.querySelectorAll('#raceTypeBtns button').forEach(b => b.classList.toggle('active', b.dataset.racetype === savedRaceType));
  }
  const savedRaceFrom = localStorage.getItem('dc_raceFrom');
  if (savedRaceFrom) document.getElementById('raceFrom').value = savedRaceFrom;
  const savedRaceTo = localStorage.getItem('dc_raceTo');
  if (savedRaceTo) document.getElementById('raceTo').value = savedRaceTo;

  renderAll();
  maybeLoadUpcoming();

  // Restore saved period (after renderAll so DOM is ready)
  const savedPeriod = localStorage.getItem('dc_period');
  if (savedPeriod && savedPeriod !== 'week') {
    const periodBtn = document.querySelector(`#periodNav button[data-period="${savedPeriod}"]`);
    if (periodBtn) periodBtn.click();
  }

  // Restore saved records limit
  const savedRecLimit = localStorage.getItem('dc_rec_limit');
  if (savedRecLimit) {
    recLimit = parseInt(savedRecLimit, 10);
    const btn = document.querySelector(`#recordsSizeBtns button[data-rec-size="${savedRecLimit}"]`);
    if (btn) {
      document.querySelectorAll('#recordsSizeBtns button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    }
  }

  renderHeroStats();
  renderStreakBanner();
  handleChartHash();
}

function splitCsvRow(row) {
  if (row.indexOf('"') === -1) return row.split(','); // fast path: no quoted fields
  const result = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < row.length; i++) {
    const c = row[i];
    if (c === '"') { inQuotes = !inQuotes; }
    else if (c === ',' && !inQuotes) { result.push(cur); cur = ''; }
    else { cur += c; }
  }
  result.push(cur);
  return result;
}

// Returns a specialized fast parser if the date sample matches a common unambiguous
// format, falling back to the full parseDate otherwise. Called once per CSV load.
function makeFastDateParser(sample) {
  if (!sample) return null;
  // YYYY-MM-DD or YYYY/MM/DD with optional time — most Google Sheets exports
  if (/^\d{4}[\/\-]\d{2}[\/\-]\d{2}/.test(sample)) {
    return str => {
      const y = +str.slice(0, 4), mo = +str.slice(5, 7) - 1, d = +str.slice(8, 10);
      if (isNaN(y) || isNaN(mo) || isNaN(d)) return null;
      const h  = str.length > 10 ? +(str.slice(11, 13)) || 0 : 0;
      const mi = str.length > 13 ? +(str.slice(14, 16)) || 0 : 0;
      const s  = str.length > 16 ? +(str.slice(17, 19)) || 0 : 0;
      const dt = new Date(y, mo, d, h, mi, s);
      return isNaN(dt) ? null : dt;
    };
  }
  // Unix timestamp (10 digits)
  if (/^\d{10}$/.test(sample)) {
    return str => { const n = +str; return n ? new Date(n * 1000) : null; };
  }
  // Google Sheets date serial (plain number)
  if (/^\d{4,6}(\.\d+)?$/.test(sample)) {
    const EPOCH = new Date(1899, 11, 30).getTime();
    return str => {
      const serial = parseFloat(str);
      return (serial > 1 && serial < 100000) ? new Date(EPOCH + serial * 86400000) : null;
    };
  }
  return null;
}

function parseDate(str) {
  if (!str || !str.trim()) return null;
  str = str.trim();

  // Spanish month abbreviations and full names
  const ES_MONTHS = {
    'ene': 1, 'feb': 2, 'mar': 3, 'abr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'ago': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dic': 12,
    'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4, 'mayo': 5, 'junio': 6,
    'julio': 7, 'agosto': 8, 'septiembre': 9, 'octubre': 10, 'noviembre': 11, 'diciembre': 12
  };

  // D/MMM/YYYY H:MM:SS — e.g. "9/ene/2016 2:14:01"
  let m = str.match(/^(\d{1,2})\/([a-záéíóúüñA-Z]+)\/(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/i);
  if (m) {
    const mon = ES_MONTHS[m[2].toLowerCase()];
    if (mon) {
      const d = new Date(+m[3], mon - 1, +m[1], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
      if (!isNaN(d)) return d;
    }
  }

  // Already a valid date string (ISO, RFC, etc.)
  let d = new Date(str);
  if (!isNaN(d) && d.getFullYear() > 1990) return d;

  // MM/DD/YYYY HH:MM:SS or MM/DD/YYYY
  m = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) {
    d = new Date(+m[3], +m[1] - 1, +m[2], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
    if (!isNaN(d)) return d;
  }

  // DD/MM/YYYY or DD-MM-YYYY
  m = str.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) {
    const asMMDD = new Date(+m[3], +m[1] - 1, +m[2], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
    const asDDMM = new Date(+m[3], +m[2] - 1, +m[1], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
    if (!isNaN(asMMDD) && +m[1] <= 12) return asMMDD;
    if (!isNaN(asDDMM)) return asDDMM;
  }

  // YYYY/MM/DD or YYYY-MM-DD with optional time
  m = str.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})(?:[T\s](\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) {
    d = new Date(+m[1], +m[2] - 1, +m[3], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
    if (!isNaN(d)) return d;
  }

  // Google Sheets date serial
  if (/^\d+(\.\d+)?$/.test(str)) {
    const serial = parseFloat(str);
    if (serial > 1 && serial < 100000) {
      const epoch = new Date(1899, 11, 30);
      d = new Date(epoch.getTime() + serial * 86400000);
      if (!isNaN(d) && d.getFullYear() > 1990) return d;
    }
  }

  return null;
}

// ─── PERIOD NAV ────────────────────────────────────────────────
// Per-section chart size button handlers
// Each button group is independent; paginated=true resets search/pagination state
function _bindSectionSizeBar(id, setter, lsKey, paginated) {
  const el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('click', e => {
    const btn = e.target.closest('[data-size]'); if (!btn) return;
    el.querySelectorAll('button').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const rawV = parseInt(btn.dataset.size);
    setter(rawV === 0 ? Infinity : rawV);
    localStorage.setItem(lsKey, btn.dataset.size);
    if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
    if (paginated) {
      ['songs', 'artists', 'albums'].forEach(t => {
        searchState[t] = ''; const inp = document.getElementById(t + 'SearchInput');
        if (inp) inp.value = ''; pageState[t] = 0;
      });
    }
    renderAll();
  });
}
// Weekly size bars (non-paginated)
_bindSectionSizeBar('sizeBtnsSongsW',   v => { chartSizeSongsW   = v; chartSizeWeekly = v; }, 'dc_chartSizeSongsW',   false);
_bindSectionSizeBar('sizeBtnsArtistsW', v => { chartSizeArtistsW = v; },                      'dc_chartSizeArtistsW', false);
_bindSectionSizeBar('sizeBtnsAlbumsW',  v => { chartSizeAlbumsW  = v; },                      'dc_chartSizeAlbumsW',  false);
// Monthly size bars (non-paginated)
