// ─── NAVIGATE TO RECORD PERIOD ────────────────────────────────
function navigateToRecPeriod(period, periodKey) {
  document.getElementById('artistModal')?.classList.remove('open');
  document.getElementById('albumModal')?.classList.remove('open');
  document.getElementById('songModal')?.classList.remove('open');
  const now = tzNow();
  let offset = 0;
  if (period === 'week') {
    const nowDow = now.getDay();
    const nowOffset = (nowDow - weekStartDay + 7) % 7;
    const curStart = new Date(now); curStart.setDate(now.getDate() - nowOffset); curStart.setHours(0, 0, 0, 0);
    const targetStart = new Date(periodKey + 'T00:00:00');
    offset = Math.round((curStart - targetStart) / (7 * 86400000));
  } else if (period === 'month') {
    const [yr, mo] = periodKey.split('-').map(Number);
    offset = (now.getFullYear() - yr) * 12 + (now.getMonth() + 1 - mo);
  } else if (period === 'year') {
    offset = now.getFullYear() - parseInt(periodKey, 10);
  }
  if (offset >= 0) {
    savedOffsets[currentPeriod] = currentOffset;
    // If coming from records/graphs/rawdata, restore the chart UI
    if (currentPeriod === 'records' || currentPeriod === 'graphs' || currentPeriod === 'rawdata') {
      document.getElementById('recordsView').style.display = 'none';
      document.getElementById('graphsView').style.display = 'none';
      document.getElementById('rawDataView').style.display = 'none';
      document.getElementById('dateNav').style.display = '';
      document.getElementById('statsStrip').style.display = '';
      document.getElementById('songsSection').style.display = '';
      document.getElementById('artistsSection').style.display = '';
      document.getElementById('albumsSection').style.display = '';
      (['upcomingSection', 'recentSection']).forEach(id => {
        const el = document.getElementById(id);
        el.style.display = '';
        const savedCollapsed = localStorage.getItem('dc_section_collapsed_' + id) === '1';
        el.classList.toggle('collapsed', savedCollapsed);
        const colBtn = el.querySelector('.section-collapse-btn');
        if (colBtn) colBtn.textContent = savedCollapsed ? '+' : '−';
      });
      if (currentPeriod === 'graphs') destroyGraphCharts();
    }
    currentPeriod = period;
    updateScrobbleBtn();
    localStorage.setItem('dc_period', currentPeriod);
    document.querySelectorAll('.period-nav button').forEach(b => b.classList.toggle('active', b.dataset.period === period));
    currentOffset = offset;
    savedOffsets[period] = offset;
    pageState.songs = 0; pageState.artists = 0; pageState.albums = 0;
    renderAll();
  }
}

// ─── CHART HASH ROUTING ───────────────────────────────────────
// Allows "Open in new tab" on chart-period links via #chart/period/periodKey
function handleChartHash() {
  const m = window.location.hash.match(/^#chart\/(week|month|year)\/(.+)$/);
  if (m) navigateToRecPeriod(m[1], m[2]);
}
window.addEventListener('hashchange', handleChartHash);

// ─── RECORDS & HALL OF FAME ────────────────────────────────────
/* What the Records DOM currently in the page was built from. Records is rebuilt
   from scratch on every visit to the tab — ~1.6s of counting at 150k plays,
   with no caching of any kind, so switching away and back paid it again.

   Everything it produces is a pure function of the play data, the settings that
   change how plays are keyed, the chart sizes, the rows-per-table limit, and the
   interface language (the tables contain translated strings). _crGeneration()
   already covers the first three; the other two are added here.

   The built DOM survives a tab switch — the view is only display:none — so when
   none of those have moved, the tables on the page are still correct and the
   whole build can be skipped. */
let _recBuiltKey = null;

function _recBuildKey() {
  return _crGeneration() + '|' + recLimit + '|' + (typeof currentLang !== 'undefined' ? currentLang : '');
}

// Forces the next buildRecords() to do the work, whatever the key says.
function dcInvalidateRecords() { _recBuiltKey = null; }
window.dcInvalidateRecords = dcInvalidateRecords;

/* Artwork in Records loads through IntersectionObservers, and renderAll() calls
   clearImageObservers() — so visiting a chart tab and coming back leaves the
   kept tables with nothing watching for scroll. Rebuilding used to re-register
   them as a side effect; skipping the rebuild means doing it deliberately.

   The elements still carry the _imgItem / _imgType that loadImages() put on
   them, so the queue can be recovered from the DOM rather than stored — which
   also means a new Records section gets this for free. Anything that already
   resolved to an <img> is left alone; attachRecImgPicker is idempotent, so
   re-registering cannot double up the ✎ buttons. */
function _recReattachImageObservers() {
  const view = document.getElementById('recordsView');
  if (!view) return;
  const byType = {};
  view.querySelectorAll('[id]').forEach(el => {
    if (!el._imgItem || !el._imgType) return;
    if (el.querySelector('img')) return;   // already has its artwork
    (byType[el._imgType] || (byType[el._imgType] = [])).push(el._imgItem);
  });
  for (const type in byType) loadImages(byType[type], type);
}

function buildRecords() {
  if (!allPlays.length) return;

  /* Nothing that feeds Records has changed and the tables are still in the DOM,
     so there is nothing to rebuild. _recArtistTally is the tell that a previous
     build actually completed — it is set at the very end. */
  const _bk = _recBuildKey();
  if (_bk === _recBuiltKey && _recArtistTally) {
    _recReattachImageObservers();
    return;
  }
  _recBuiltKey = _bk;

  const wSizeSongs = chartSizeSongsW, wSizeArtists = chartSizeArtistsW, wSizeAlbums = chartSizeAlbumsW;
  const mSizeSongs = chartSizeSongsM, mSizeArtists = chartSizeArtistsM, mSizeAlbums = chartSizeAlbumsM;
  const ySizeSongs   = isFinite(chartSizeSongsY)   ? chartSizeSongsY   : 999999;
  const ySizeArtists = isFinite(chartSizeArtistsY) ? chartSizeArtistsY : 999999;
  const ySizeAlbums  = isFinite(chartSizeAlbumsY)  ? chartSizeAlbumsY  : 999999;

  // Name lookup tables
  const songNames = {}, albumNames = {};
  for (const p of allPlays) {
    const sk = songKey(p);
    if (!songNames[sk]) songNames[sk] = { title: p.title, artist: p.artist, album: p.album };
    const ak = albumKeyOf(p);
    if (!albumNames[ak]) albumNames[ak] = { album: p.album, artist: albumArtist(p) };
  }

  function fmtPeriodKey(pk, pt) {
    if (pt === 'week') { const d = new Date(pk + 'T00:00:00'); return t('period_week_of', { date: fmt(d) }); }
    if (pt === 'month') {
      const [yr, mo] = pk.split('-');
      const monthKey = ['month_jan', 'month_feb', 'month_mar', 'month_apr', 'month_may_short', 'month_jun', 'month_jul', 'month_aug', 'month_sep', 'month_oct', 'month_nov', 'month_dec'][+mo - 1];
      const monthName = t(monthKey);
      return `${monthName} ${yr}`;
    }
    return pk;
  }
  /* One end of a streak, written the way that dimension is counted. The
     streak dims are their own vocabulary ('days'/'weeks'/'months'/'years'),
     not the chart periods fmtPeriodKey() speaks, so this maps between them.
     Weeks name their start date rather than "Week of 8 Jun 2026": the column
     sits beside a second one of the same shape and the panel heading already
     says these are weeks, so the prefix would be noise twice over. */
  function fmtStreakBound(dim, key) {
    if (!key) return '';
    if (dim === 'days' || dim === 'weeks') return fmt(new Date(key + 'T00:00:00'));
    if (dim === 'months') return fmtPeriodKey(key, 'month');
    return key;
  }
  function periodAtOneHeader(pt) { return pt === 'week' ? t('rec_th_weeks_at_1') : pt === 'month' ? t('rec_th_months_at_1') : t('rec_th_years_at_1'); }
  // Same three headers for the consecutive twin of each All #1s table. Kept as
  // three keys rather than one "Consecutive {{unit}}" template because the
  // adjective is gendered in es/pt and has to agree with Semanas/Meses/Años.
  function consecAtOneHeader(pt) { return pt === 'week' ? t('rec_th_consec_weeks_at_1') : pt === 'month' ? t('rec_th_consec_months_at_1') : t('rec_th_consec_years_at_1'); }

  // Group plays by period
  // Sort on the raw numeric stamp rather than subtracting Date objects — this
  // is a full sort of the library and the comparator runs millions of times.
  // msOf(), not tzMsOf(): the original ordered by real time, and a timezone
  // shift is not guaranteed monotonic across a DST boundary.
  const chron = allPlays.slice().sort((a, b) => msOf(a) - msOf(b));
  const weekPlaysMap = {}, monthPlaysMap = {}, yearPlaysMap = {};
  for (const p of chron) {
    // All three are cached per-play stamps; none needs a Date built.
    const wk = playWeekKeyOf(p), mk = monthKeyOf(p), yk = yearKeyOf(p);
    (weekPlaysMap[wk] || (weekPlaysMap[wk] = [])).push(p);
    (monthPlaysMap[mk] || (monthPlaysMap[mk] = [])).push(p);
    (yearPlaysMap[yk] || (yearPlaysMap[yk] = [])).push(p);
  }
  const weekKeys = Object.keys(weekPlaysMap).sort();
  const monthKeys = Object.keys(monthPlaysMap).sort();
  const yearKeys = Object.keys(yearPlaysMap).sort();

  // First/last play data for appearances charts
  const songFirstPlay = {}, songLastPlay = {};
  const artistFirstSongName = {}, artistLastSongName = {};
  const albumFirstPlayDate = {}, albumFirstSongName = {};
  const artistFirstAlbum = {};
  for (const p of chron) {
    const sk = songKey(p);
    if (!songFirstPlay[sk]) songFirstPlay[sk] = p.date;
    songLastPlay[sk] = p.date;
    for (const a of p.artists) {
      if (!artistFirstSongName[a]) artistFirstSongName[a] = p.title;
      artistLastSongName[a] = p.title;
      if (!artistFirstAlbum[a] && p.album && p.album !== '—') {
        artistFirstAlbum[a] = { album: p.album, albumKey: albumKeyOf(p), artist: albumArtist(p) };
      }
    }
    if (p.album && p.album !== '—') {
      const ak = albumKeyOf(p);
      if (!albumFirstPlayDate[ak]) { albumFirstPlayDate[ak] = p.date; albumFirstSongName[ak] = p.title; }
    }
  }

  // Records containers
  const song1s = { week: {}, month: {}, year: {} };
  const artist1s = { week: {}, month: {}, year: {} };
  const album1s = { week: {}, month: {}, year: {} };
  const songApps = { week: {}, month: {}, year: {} };
  const artistApps = { week: {}, month: {}, year: {} };
  const albumApps = { week: {}, month: {}, year: {} };
  const songDebuts = { week: {}, month: {}, year: {} };
  const artistDebuts = { week: {}, month: {}, year: {} };
  const albumDebuts = { week: {}, month: {}, year: {} };
  const songPP = { week: {}, month: {}, year: {} };
  const artistPP = { week: {}, month: {}, year: {} };
  const albumPP = { week: {}, month: {}, year: {} };
  /* Perfect All Kill, one list per chart. A PAK is one artist holding #1 on the
     artist, song and album charts at the same time, and that is as true of a
     month or a year as it is of a week — a yearly PAK is simply a much rarer
     thing than a weekly one, which makes it its own record rather than a filter
     over this one. Keyed by period so the three never mix. */
  const pakPeriods = { week: [], month: [], year: [] };
  const newCountPerPeriod = {
    week: { songs: {}, artists: {}, albums: {} },
    month: { songs: {}, artists: {}, albums: {} },
    year: { songs: {}, artists: {}, albums: {} }
  };
  const newSongDebutsByArtist = { week: {}, month: {}, year: {} };
  const newSongsByArtistPerPeriod = { week: {}, month: {}, year: {} };
  const artistNewDebutPeriods = { week: {}, month: {}, year: {} };
  const song1stNo1Period = { week: {}, month: {}, year: {} };
  const albumNewTrackCount = { week: {}, month: {}, year: {} };
  const rawNewCountPerPeriod = {
    week: { songs: {}, artists: {}, albums: {} },
    month: { songs: {}, artists: {}, albums: {} },
    year: { songs: {}, artists: {}, albums: {} }
  };

  function buildPeriodRecords(pt, playsMap, keys, sizeSongs, sizeArtists, sizeAlbums) {
    let prevSong = {}, prevArtist = {}, prevAlbum = {};
    const everSong = new Set(), everArtist = new Set(), everAlbum = new Set();
    for (const pk of keys) {
      const plays = playsMap[pk];
      const sc = {}, ac = {}, lc = {};
      for (const p of plays) {
        const sk = songKey(p);
        if (!sc[sk]) sc[sk] = { count: 0, title: p.title, artist: p.artist, artists_: p.artists, album: p.album, firstAchieved: p.date };
        sc[sk].count++;
        for (const a of p.artists) {
          if (!ac[a]) ac[a] = { count: 0, firstAchieved: p.date };
          ac[a].count++;
        }
        if (p.album && p.album !== '—') {
          const ak = albumKeyOf(p);
          if (!lc[ak]) lc[ak] = { count: 0, album: p.album, artist: albumArtist(p), firstAchieved: p.date };
          lc[ak].count++;
        }
      }
      for (const [k, d] of Object.entries(sc)) { d.chartStatus = prevSong[k] ? 0 : everSong.has(k) ? 1 : 2; d.prevRank = prevSong[k] || Infinity; }
      for (const [k, d] of Object.entries(ac)) { d.chartStatus = prevArtist[k] ? 0 : everArtist.has(k) ? 1 : 2; d.prevRank = prevArtist[k] || Infinity; }
      for (const [k, d] of Object.entries(lc)) { d.chartStatus = prevAlbum[k] ? 0 : everAlbum.has(k) ? 1 : 2; d.prevRank = prevAlbum[k] || Infinity; }
      const topSongs = Object.entries(sc).sort(([, a], [, b]) => rankSortWithStatus(a, b)).slice(0, sizeSongs);
      const topArtists = Object.entries(ac).sort(([, a], [, b]) => rankSortWithStatus(a, b)).slice(0, sizeArtists);
      const topAlbums = Object.entries(lc).sort(([, a], [, b]) => rankSortWithStatus(a, b)).slice(0, sizeAlbums);
      const nPS = {}, nPA = {}, nPL = {};
      const newSongKeysThisPeriod = new Set();
      topSongs.forEach(([k, d], i) => {
        nPS[k] = i + 1;
        if (!everSong.has(k)) {
          songDebuts[pt][k] = { rank: i + 1, period: pk, title: d.title, artist: d.artist, plays: d.count };
          newSongKeysThisPeriod.add(k);
          newCountPerPeriod[pt].songs[pk] = (newCountPerPeriod[pt].songs[pk] || 0) + 1;
          newSongDebutsByArtist[pt][d.artist] = (newSongDebutsByArtist[pt][d.artist] || 0) + 1;
          if (!newSongsByArtistPerPeriod[pt][pk]) newSongsByArtistPerPeriod[pt][pk] = {};
          newSongsByArtistPerPeriod[pt][pk][d.artist] = (newSongsByArtistPerPeriod[pt][pk][d.artist] || 0) + 1;
          if (!artistNewDebutPeriods[pt][d.artist]) artistNewDebutPeriods[pt][d.artist] = [];
          artistNewDebutPeriods[pt][d.artist].push(pk);
        }
        everSong.add(k);
        if (i === 0) { if (!song1s[pt][k]) song1s[pt][k] = { title: d.title, artist: d.artist, album: d.album, count: 0, firstPeriod: pk, periods: [] }; song1s[pt][k].count++; song1s[pt][k].lastPeriod = pk; song1s[pt][k].periods.push(pk); if (!song1stNo1Period[pt][k]) song1stNo1Period[pt][k] = pk; }
        songApps[pt][k] = (songApps[pt][k] || 0) + 1;
        if (!songPP[pt][k] || d.count > songPP[pt][k].count) songPP[pt][k] = { count: d.count, period: pk, title: d.title, artist: d.artist };
      });
      topArtists.forEach(([a, d], i) => {
        nPA[a] = i + 1;
        if (!everArtist.has(a)) {
          artistDebuts[pt][a] = { rank: i + 1, period: pk, plays: d.count };
          newCountPerPeriod[pt].artists[pk] = (newCountPerPeriod[pt].artists[pk] || 0) + 1;
        }
        everArtist.add(a);
        if (i === 0) { if (!artist1s[pt][a]) artist1s[pt][a] = { count: 0, firstPeriod: pk, periods: [] }; artist1s[pt][a].count++; artist1s[pt][a].lastPeriod = pk; artist1s[pt][a].periods.push(pk); }
        artistApps[pt][a] = (artistApps[pt][a] || 0) + 1;
        if (!artistPP[pt][a] || d.count > artistPP[pt][a].count) artistPP[pt][a] = { count: d.count, period: pk };
      });
      topAlbums.forEach(([ak, d], i) => {
        nPL[ak] = i + 1;
        if (!everAlbum.has(ak)) {
          albumDebuts[pt][ak] = { rank: i + 1, period: pk, album: d.album, artist: d.artist, plays: d.count };
          newCountPerPeriod[pt].albums[pk] = (newCountPerPeriod[pt].albums[pk] || 0) + 1;
          let newTrackCt = 0;
          for (const sk of newSongKeysThisPeriod) { const sd = sc[sk]; if (sd && sd.album === d.album && albumArtist(sd) === d.artist) newTrackCt++; }
          albumNewTrackCount[pt][ak] = newTrackCt;
        }
        everAlbum.add(ak);
        if (i === 0) { if (!album1s[pt][ak]) album1s[pt][ak] = { album: d.album, artist: d.artist, count: 0, firstPeriod: pk, periods: [] }; album1s[pt][ak].count++; album1s[pt][ak].lastPeriod = pk; album1s[pt][ak].periods.push(pk); }
        albumApps[pt][ak] = (albumApps[pt][ak] || 0) + 1;
        if (!albumPP[pt][ak] || d.count > albumPP[pt][ak].count) albumPP[pt][ak] = { count: d.count, period: pk, album: d.album, artist: d.artist };
      });
      prevSong = nPS; prevArtist = nPA; prevAlbum = nPL;
      /* Perfect All Kill — the same three-way #1 test, run against whichever
         chart this pass is building. It used to be gated to `pt === 'week'`,
         which is why the monthly and yearly PAKs did not exist. */
      if (topSongs[0] && topArtists[0] && topAlbums[0]) {
        const s1k = topSongs[0][0], a1 = topArtists[0][0], l1k = topAlbums[0][0];
        if ((sc[s1k]?.artists_ || []).includes(a1) && lc[l1k]?.artist === a1) {
          pakPeriods[pt].push({ periodKey: pk, artist: a1, song: sc[s1k].title, album: lc[l1k].album });
        }
      }
    }
  }

  buildPeriodRecords('week', weekPlaysMap, weekKeys, wSizeSongs, wSizeArtists, wSizeAlbums);
  buildPeriodRecords('month', monthPlaysMap, monthKeys, mSizeSongs, mSizeArtists, mSizeAlbums);
  buildPeriodRecords('year', yearPlaysMap, yearKeys, ySizeSongs, ySizeArtists, ySizeAlbums);

  // ── New Charts Records: compute from actual New Songs/Artists/Albums charts ──
  // Uses first-ever play per item, matching the renderNewEntries logic.
  const ncSongDebuts = { week: {}, month: {}, year: {} };
  const ncArtistDebuts = { week: {}, month: {}, year: {} };
  const ncAlbumDebuts = { week: {}, month: {}, year: {} };
  const ncNewSongDebutsByArtist = { week: {}, month: {}, year: {} };
  const ncNewSongsByArtistPerPeriod = { week: {}, month: {}, year: {} };
  const ncArtistNewDebutPeriods = { week: {}, month: {}, year: {} };
  const ncAlbumNewTrackCount = { week: {}, month: {}, year: {} };
  // The New Songs/Artists/Albums charts only ever show the top N of a period.
  // Records built from every first-ever appearance were ranking entries that
  // never made the chart (a #247 "debut" on a top-20 chart, an album credited
  // with 36 debuting tracks when only 20 fit), so mirror renderNewEntries'
  // per-section limits exactly and let a record come only from a charting entry.
  const ncLimits = {
    week:  { songs: Math.max(20, chartSizeSongsW), artists: Math.max(20, chartSizeArtistsW), albums: Math.max(20, chartSizeAlbumsW) },
    month: { songs: chartSizeSongsM, artists: chartSizeArtistsM, albums: chartSizeAlbumsM },
    year:  { songs: chartSizeSongsY, artists: chartSizeArtistsY, albums: chartSizeAlbumsY },
  };
  {
    const sfp = { week: {}, month: {}, year: {} };
    const afp = { week: {}, month: {}, year: {} };
    const lfp = { week: {}, month: {}, year: {} };
    for (const p of chron) {
      const wk = playWeekKeyOf(p);
      const _td = tzDateOf(p);
      const mk = _td.getFullYear() + '-' + String(_td.getMonth() + 1).padStart(2, '0');
      const yk = String(_td.getFullYear());
      const sk = songKey(p);
      if (!sfp.week[sk]) sfp.week[sk] = { period: wk, title: p.title, artist: p.artist, album: p.album, artists_: p.artists };
      if (!sfp.month[sk]) sfp.month[sk] = { period: mk, title: p.title, artist: p.artist, album: p.album, artists_: p.artists };
      if (!sfp.year[sk]) sfp.year[sk] = { period: yk, title: p.title, artist: p.artist, album: p.album, artists_: p.artists };
      for (const artist of p.artists) {
        if (!afp.week[artist]) afp.week[artist] = wk;
        if (!afp.month[artist]) afp.month[artist] = mk;
        if (!afp.year[artist]) afp.year[artist] = yk;
      }
      if (p.album && p.album !== '—') {
        const ak = albumKeyOf(p);
        if (!lfp.week[ak]) lfp.week[ak] = { period: wk, album: p.album, artist: albumArtist(p) };
        if (!lfp.month[ak]) lfp.month[ak] = { period: mk, album: p.album, artist: albumArtist(p) };
        if (!lfp.year[ak]) lfp.year[ak] = { period: yk, album: p.album, artist: albumArtist(p) };
      }
    }
    for (const [pt, playsMap, keys] of [['week', weekPlaysMap, weekKeys], ['month', monthPlaysMap, monthKeys], ['year', yearPlaysMap, yearKeys]]) {
      const sbyp = {};
      for (const [sk, info] of Object.entries(sfp[pt])) {
        const pk = info.period;
        if (!sbyp[pk]) sbyp[pk] = {};
        sbyp[pk][sk] = { title: info.title, artist: info.artist, album: info.album, artists_: info.artists_, plays: 0 };
      }
      for (const pk of keys) {
        const ns = sbyp[pk]; if (!ns) continue;
        for (const p of playsMap[pk]) { const sk = songKey(p); if (ns[sk]) ns[sk].plays++; }
      }
      // The charting slice of each period, kept around because the album track
      // counts further down have to count charting tracks only too.
      const sTop = {};
      for (const pk of keys) {
        const ns = sbyp[pk]; if (!ns) continue;
        const ranked = Object.entries(ns).sort((a, b) => b[1].plays - a[1].plays);
        sTop[pk] = isFinite(ncLimits[pt].songs) ? ranked.slice(0, ncLimits[pt].songs) : ranked;
        sTop[pk].forEach(([sk, d], i) => {
          ncSongDebuts[pt][sk] = { rank: i + 1, period: pk, title: d.title, artist: d.artist, plays: d.plays };
          ncNewSongDebutsByArtist[pt][d.artist] = (ncNewSongDebutsByArtist[pt][d.artist] || 0) + 1;
          if (!ncNewSongsByArtistPerPeriod[pt][pk]) ncNewSongsByArtistPerPeriod[pt][pk] = {};
          ncNewSongsByArtistPerPeriod[pt][pk][d.artist] = (ncNewSongsByArtistPerPeriod[pt][pk][d.artist] || 0) + 1;
          if (!ncArtistNewDebutPeriods[pt][d.artist]) ncArtistNewDebutPeriods[pt][d.artist] = [];
          ncArtistNewDebutPeriods[pt][d.artist].push(pk);
        });
      }
      const abyp = {};
      for (const [artist, pk] of Object.entries(afp[pt])) {
        if (!abyp[pk]) abyp[pk] = {};
        abyp[pk][artist] = 0;
      }
      for (const pk of keys) {
        const na = abyp[pk]; if (!na) continue;
        for (const p of playsMap[pk]) { for (const a of p.artists) { if (na[a] !== undefined) na[a]++; } }
      }
      for (const pk of keys) {
        const na = abyp[pk]; if (!na) continue;
        const rankedA = Object.entries(na).sort((a, b) => b[1] - a[1]);
        (isFinite(ncLimits[pt].artists) ? rankedA.slice(0, ncLimits[pt].artists) : rankedA).forEach(([artist, plays], i) => {
          ncArtistDebuts[pt][artist] = { rank: i + 1, period: pk, plays };
        });
      }
      const lbyp = {};
      for (const [ak, info] of Object.entries(lfp[pt])) {
        const pk = info.period;
        if (!lbyp[pk]) lbyp[pk] = {};
        lbyp[pk][ak] = { album: info.album, artist: info.artist, plays: 0 };
      }
      for (const pk of keys) {
        const nl = lbyp[pk]; if (!nl) continue;
        for (const p of playsMap[pk]) {
          if (!p.album || p.album === '—') continue;
          const ak = albumKeyOf(p);
          if (nl[ak]) nl[ak].plays++;
        }
      }
      for (const pk of keys) {
        const nl = lbyp[pk]; if (!nl) continue;
        // Only tracks that made the New Songs chart count — an album can never
        // be credited with more debuting tracks than the chart has spots.
        const ns = sTop[pk] || [];
        const rankedL = Object.entries(nl).sort((a, b) => b[1].plays - a[1].plays);
        (isFinite(ncLimits[pt].albums) ? rankedL.slice(0, ncLimits[pt].albums) : rankedL).forEach(([ak, d], i) => {
          ncAlbumDebuts[pt][ak] = { rank: i + 1, period: pk, album: d.album, artist: d.artist, plays: d.plays };
          let nTracks = 0;
          for (const [, sd] of ns) { if (sd.album === d.album && (sd.artists_[0] || sd.artist) === d.artist) nTracks++; }
          ncAlbumNewTrackCount[pt][ak] = nTracks;
        });
      }
    }
  }

  // ── Build ncPeriodMap for tooltip use (inverted by period) ───
  ncPeriodMap = { week: {}, month: {}, year: {} };
  for (const pt of ['week', 'month', 'year']) {
    for (const [sk, d] of Object.entries(ncSongDebuts[pt])) {
      if (!ncPeriodMap[pt][d.period]) ncPeriodMap[pt][d.period] = { songs: [], artists: [], albums: [] };
      ncPeriodMap[pt][d.period].songs.push({ rank: d.rank, title: d.title, artist: d.artist });
    }
    for (const [artist, d] of Object.entries(ncArtistDebuts[pt])) {
      if (!ncPeriodMap[pt][d.period]) ncPeriodMap[pt][d.period] = { songs: [], artists: [], albums: [] };
      ncPeriodMap[pt][d.period].artists.push({ rank: d.rank, name: artist });
    }
    for (const [ak, d] of Object.entries(ncAlbumDebuts[pt])) {
      if (!ncPeriodMap[pt][d.period]) ncPeriodMap[pt][d.period] = { songs: [], artists: [], albums: [] };
      ncPeriodMap[pt][d.period].albums.push({ rank: d.rank, album: d.album, artist: d.artist });
    }
    for (const pm of Object.values(ncPeriodMap[pt])) {
      pm.songs.sort((a, b) => a.rank - b.rank);
      pm.artists.sort((a, b) => a.rank - b.rank);
      pm.albums.sort((a, b) => a.rank - b.rank);
    }
  }

  // ── New Charts Records: post-processing ──────────────────────
  // Record 8: Longest consecutive periods where artist had a new debut
  const artistConsecNewDebuts = { week: {}, month: {} };
  for (const [pt, ptKeys] of [['week', weekKeys], ['month', monthKeys]]) {
    const pidx = {};
    ptKeys.forEach((k, i) => { pidx[k] = i; });
    for (const [artist, periods] of Object.entries(ncArtistNewDebutPeriods[pt])) {
      const uniq = [...new Set(periods)].sort();
      let max = 1, cur = 1;
      for (let i = 1; i < uniq.length; i++) {
        const pi = pidx[uniq[i - 1]], ci = pidx[uniq[i]];
        if (pi !== undefined && ci !== undefined && ci === pi + 1) { if (++cur > max) max = cur; } else cur = 1;
      }
      artistConsecNewDebuts[pt][artist] = max;
    }
  }
  // Record 9: New Song → #1 fastest (fewest periods from debut on New Songs chart to first main-chart #1)
  const songNewTo1 = { week: {}, month: {} };
  for (const [pt, ptKeys] of [['week', weekKeys], ['month', monthKeys]]) {
    const pidx = {};
    ptKeys.forEach((k, i) => { pidx[k] = i; });
    for (const [sk, deb] of Object.entries(ncSongDebuts[pt])) {
      if (!song1stNo1Period[pt][sk]) continue;
      const di = pidx[deb.period], n1i = pidx[song1stNo1Period[pt][sk]];
      if (di === undefined || n1i === undefined) continue;
      songNewTo1[pt][sk] = { periods: n1i - di, debutPeriod: deb.period, no1Period: song1stNo1Period[pt][sk], debutPlays: deb.plays, title: deb.title, artist: deb.artist };
    }
  }

  // Records 4 & 5: Raw new discovery counts — all unique first appearances,
  // not limited by chart size
  for (const [pt, playsMap, keys] of [['week', weekPlaysMap, weekKeys], ['month', monthPlaysMap, monthKeys], ['year', yearPlaysMap, yearKeys]]) {
    const everS = new Set(), everA = new Set(), everL = new Set();
    for (const pk of keys) {
      for (const p of playsMap[pk]) {
        const sk = songKey(p);
        if (!everS.has(sk)) { everS.add(sk); rawNewCountPerPeriod[pt].songs[pk] = (rawNewCountPerPeriod[pt].songs[pk] || 0) + 1; }
        for (const a of p.artists) {
          if (!everA.has(a)) { everA.add(a); rawNewCountPerPeriod[pt].artists[pk] = (rawNewCountPerPeriod[pt].artists[pk] || 0) + 1; }
        }
        if (p.album && p.album !== '—') {
          const ak = albumKeyOf(p);
          if (!everL.has(ak)) { everL.add(ak); rawNewCountPerPeriod[pt].albums[pk] = (rawNewCountPerPeriod[pt].albums[pk] || 0) + 1; }
        }
      }
    }
  }

  /* Play count milestones — the ladder artists and albums are recorded on.
     Nothing is stored for a total that is missing here, so this array is what
     limits every artist/album milestone record downstream (the Milestones
     timeline reads whichever tiers the data actually filled, and FAST_TIERS
     can only name tiers that exist in this set).
     Dense in whole thousands from 4,000 to 15,000: an artist banks the plays of
     their entire catalogue, so that range is where a long-running library
     spends most of its time and 5,000 → 7,500 → 10,000 was too coarse to
     show any of it. */
  const MILESTONES = [10, 25, 50, 100, 150, 200, 250, 300, 400, 500, 600, 750, 1000, 1250, 1500, 1750, 2000, 2500, 3000, 3500, 4000, 4500, 5000, 6000, 7000, 7500, 8000, 9000, 10000, 11000, 12000, 13000, 14000, 15000, 20000, 25000, 50000];
  const MILESTONE_SET = new Set(MILESTONES);
  /* Songs run a finer ladder: every 25 plays, with no ceiling. A song is the
     smallest unit here, so the landmark steps that suit artists (10 → 25 → 50 →
     100 → …) skip most of what actually happens to one.

     Expressed as a modulo rather than an array because there is no sensible cap
     — whatever the most-played song reaches, the ladder reaches. */
  const SONG_MILESTONE_STEP = 25;
  /* Steps below the first multiple that are worth keeping anyway. 10 plays is
     the point a song stops being something you tried once, and jumping straight
     from the origin row to 25 skipped it. */
  const SONG_MILESTONE_EXTRA = new Set([10]);

  const artistMS = {}, songMS = {}, artistFirst = {}, songFirst = {}, artistCP = {}, songCP = {};
  /* Albums climb the same tier ladder as artists. They were the one entity with
     no milestone data at all, which left three overview cards permanently empty
     on the Albums pill. Keyed exactly like every other album map in this file
     (album|||albumArtist) so albumNames lookups resolve. */
  const albumMS = {}, albumFirst = {}, albumCP = {};
  /* Every count below rises by exactly one per play, so a tier is crossed on
     the single play where the running count equals it. That makes the test O(1)
     — the old `for (const m of MILESTONES) … >= m` rescanned the whole ladder on
     every play, which the every-25 song ladder (hundreds of tiers, unbounded)
     would have turned into a visible hang. */
  /* `elapsed` is the exact gap in milliseconds; `days` is that rounded, kept
     because plenty of callers only ever want the round number.

     Rounded days cannot order the Fastest ladder on its own. At the 50-play
     tier 23 of the 25 visible rows share a day count, so the ranking they were
     given was really insertion order. Every play carries a real time of day —
     a Last.fm unix timestamp, or whatever time a Sheets/CSV date column
     supplies — and the exact gap separates all of them. A date-only import
     lands every play at midnight, which makes `elapsed` a whole number of days
     and the tie-break a harmless no-op rather than a wrong answer. */
  const msAt = function (date, first) {
    const elapsed = date - first;
    return { date: date, elapsed: elapsed, days: Math.round(elapsed / 86400000) };
  };
  for (const p of chron) {
    for (const a of p.artists) {
      if (!artistFirst[a]) artistFirst[a] = p.date;
      const n = artistCP[a] = (artistCP[a] || 0) + 1;
      if (!artistMS[a]) artistMS[a] = {};
      if (MILESTONE_SET.has(n)) artistMS[a][n] = msAt(p.date, artistFirst[a]);
    }
    const sk = songKey(p);
    if (!songFirst[sk]) songFirst[sk] = p.date;
    const sn = songCP[sk] = (songCP[sk] || 0) + 1;
    if (!songMS[sk]) songMS[sk] = {};
    if (sn % SONG_MILESTONE_STEP === 0 || SONG_MILESTONE_EXTRA.has(sn)) songMS[sk][sn] = msAt(p.date, songFirst[sk]);
    // A play with no album tag can't be credited to one — CSV uploads and a fair
    // number of Last.fm scrobbles have none — so it sits this ladder out. Same
    // guard the raw discovery counts above use.
    if (p.album && p.album !== '—') {
      const ak = albumKeyOf(p);
      if (!albumFirst[ak]) albumFirst[ak] = p.date;
      const an = albumCP[ak] = (albumCP[ak] || 0) + 1;
      if (!albumMS[ak]) albumMS[ak] = {};
      if (MILESTONE_SET.has(an)) albumMS[ak][an] = msAt(p.date, albumFirst[ak]);
    }
  }

  /* ── Listening streaks and back-to-back play runs ──────────────
     Four records out of one chronological pass, for all three entities.
     A streak is consecutive calendar units — days, months or years — with at
     least one play; a run is consecutive plays in the log with nothing else
     in between. Songs, artists and albums all get every one of them: an album
     streak counts any play tagged with that album under its album artist, the
     same key the rest of Records uses, and untagged plays ('—') belong to no
     album so they are skipped rather than pooled into a phantom one. */
  const STREAK_KINDS = ['song', 'artist', 'album'];
  /* Every dimension counts units the entity was PLAYED in — charting has
     nothing to do with any of them. Weeks are calendar weeks rather than
     rolling seven-day windows, bucketed with playWeekKey() so "a week" means
     the same thing here as everywhere else in the app and moves with the
     week-start-day setting; that is the only thing the charts lend this
     ladder, exactly as the daily one borrows your calendar day. */
  const STREAK_DIMS = ['days', 'weeks', 'months', 'years'];
  /* Per entity: how many plays landed in each calendar bucket it was heard in,
     plus its play total. Counts rather than a bare set of buckets, because the
     yearly ladder ranks its ties on the leanest year of the run and needs to
     know how deep each year was — see longestUnitStreak(). */
  const streakUnits = { song: {}, artist: {}, album: {} };
  // One more play in a bucket. Maps start empty, so a missing key reads as 0.
  const bumpBucket = function (m, k) { m.set(k, (m.get(k) || 0) + 1); };
  // Per entity: its longest back-to-back run and the date that run peaked on.
  const bestRuns = { song: {}, artist: {}, album: {} };
  /* Per entity: the index of the play that last touched it, and how long the
     run ending there is. A run only continues while that index is the play
     immediately before the current one. Keeping the cursor per key rather than
     as one global "current key" is what lets a collaboration keep both of its
     artists' runs alive across the same play. */
  const runCursor = { song: {}, artist: {}, album: {} };

  function streakTouch(kind, key, i, p, dk, wk, mk, yk) {
    const c = runCursor[kind][key];
    // One play can credit the same artist twice on a sloppily tagged scrobble;
    // count it once, or the play would reset the very run it should extend.
    if (c && c.idx === i) return;
    let u = streakUnits[kind][key];
    if (!u) u = streakUnits[kind][key] = { days: new Map(), weeks: new Map(), months: new Map(), years: new Map(), plays: 0 };
    u.plays++;
    bumpBucket(u.days, dk); bumpBucket(u.weeks, wk); bumpBucket(u.months, mk); bumpBucket(u.years, yk);
    const len = (c && c.idx === i - 1) ? c.len + 1 : 1;
    runCursor[kind][key] = { idx: i, len: len };
    // A single play is not a run — only a repeat is worth recording.
    const b = bestRuns[kind][key];
    if (len > 1 && (!b || len > b.count)) bestRuns[kind][key] = { count: len, date: p.date };
  }

  for (let i = 0; i < chron.length; i++) {
    const p = chron[i];
    const d = tzDateOf(p);
    const dk = localDateStr(d);
    const wk = playWeekKeyOf(p);
    const mk = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    const yk = String(d.getFullYear());
    streakTouch('song', songKey(p), i, p, dk, wk, mk, yk);
    for (const a of p.artists) streakTouch('artist', a, i, p, dk, wk, mk, yk);
    if (p.album && p.album !== '—') streakTouch('album', albumKeyOf(p), i, p, dk, wk, mk, yk);
  }

  /* Minimum plays before an entity's ladder is worth ranking. Without a floor
     the tables fill with one-off plays that happen to land on two adjacent
     days — or, worse in the monthly and yearly ladders, on two adjacent
     Decembers. Songs need the least because a song is the smallest unit. */
  const STREAK_MIN_PLAYS = { song: 7, artist: 15, album: 10 };
  /* A lone week, month or year is not a streak, so those ladders start at 2.
     Days start at 1 the way they always have — the play floor above is already
     doing the filtering there, and dropping single days would empty the table
     for anyone who listens in bursts. */
  const STREAK_MIN_LEN = { days: 1, weeks: 2, months: 2, years: 2 };
  /* Bucket keys sort lexicographically into chronological order in every
     dimension — week keys are the week-start date, so they sort with the days
     — so "consecutive" is a +1 test on the ordinal, the same one _crStkOrd()
     runs for the per-item streak panels. */
  /* Returns the winning run itself, not just how long it was, so the tables can
     say when it happened. `start` and `end` are the first and last bucket keys
     of that run — for days a date, for weeks the week's start date, for months
     'YYYY-MM', for years 'YYYY'. `depth` is the run's leanest bucket: the
     fewest plays any single day/week/month/year of it got, which is the run's
     weakest link and the figure the yearly ladder ranks its ties on.

     `prefer` decides which run wins when an entity managed the same maximum
     length more than once, and it follows how that dimension's table ranks:

       'first'   — keep the earliest run, because those ladders order ties by
                   who got there first, and showing a later repeat would rank
                   the entity behind someone it actually beat to the mark.
       'deepest' — keep the run with the fullest leanest bucket, which is what
                   the yearly ladder ranks on; the shallower twin would
                   contradict the column beside it. Equal depth keeps the
                   earlier run, so this stays a superset of 'first'. */
  function longestUnitStreak(counts, dim, prefer) {
    const u = Array.from(counts.keys()).sort();
    if (!u.length) return { len: 0, start: null, end: null, depth: 0 };
    let best = null, runStart = 0;
    /* Closes the run [a..b] and keeps it if it beats the one already held.
       Only called once per run, never per bucket, so measuring the depth here
       costs one walk of the list in total rather than one per position. */
    const close = function (a, b) {
      const len = b - a + 1;
      if (best && len < best.len) return;
      // Same length and 'first' wins by default: the held run is the earlier.
      if (best && len === best.len && prefer === 'first') return;
      let depth = Infinity;
      for (let i = a; i <= b; i++) depth = Math.min(depth, counts.get(u[i]));
      if (best && len === best.len && depth <= best.depth) return;
      best = { len: len, s: a, e: b, depth: depth };
    };
    // The run breaks at every gap, and the last one closes at the end of the list.
    for (let i = 1; i <= u.length; i++) {
      if (i < u.length && _crStkOrd(dim, u[i]) - _crStkOrd(dim, u[i - 1]) === 1) continue;
      close(runStart, i - 1);
      runStart = i;
    }
    return { len: best.len, start: u[best.s], end: u[best.e], depth: best.depth };
  }
  /* Which run an entity keeps when it managed its own maximum twice, matched to
     how each ladder ranks — see longestUnitStreak() and STREAK_CMP below. */
  const STREAK_TIE = { days: 'first', weeks: 'first', months: 'first', years: 'deepest' };
  /* streaks[kind][dim] = { key: { len, plays, start, end, depth } }. Plays and
     depth both ride along because both are tiebreaks: the length column alone
     settles almost nothing at the top of these ladders. */
  const streaks = { song: {}, artist: {}, album: {} };
  for (const kind of STREAK_KINDS) {
    for (const dim of STREAK_DIMS) streaks[kind][dim] = {};
    for (const [key, u] of Object.entries(streakUnits[kind])) {
      if (u.plays < STREAK_MIN_PLAYS[kind]) continue;
      for (const dim of STREAK_DIMS) {
        const st = longestUnitStreak(u[dim], dim, STREAK_TIE[dim]);
        if (st.len >= STREAK_MIN_LEN[dim]) {
          streaks[kind][dim][key] = { len: st.len, plays: u.plays, start: st.start, end: st.end, depth: st.depth };
        }
      }
    }
  }
  /* How each streak ladder ranks, longest first and then the tiebreak that
     actually separates the pile-up underneath.

     Years need their own rule. A yearly streak tops out at the length of the
     library itself, so anyone who keeps an artist in rotation lands on the same
     maximum and the ladder fills to the last row with one number — the record
     stops naming a winner. `depth` is what tells those apart: the leanest year
     of the run, so eleven years that never dipped below 38 plays outranks
     eleven years carried by a single play one December. The table prints it as
     a column of its own, because a ranking on a figure the reader cannot see is
     just an arbitrary order.

     Days, weeks and months are separated by arrival instead: same length, and
     whoever reached it first is ranked first, which is why the earliest run is
     the one those dimensions keep. Bucket keys are zero-padded in every
     dimension, so comparing them as strings is comparing them chronologically.
     Lifetime plays remain the last resort in both rules. */
  const cmpBucket = function (a, b) { return a < b ? -1 : a > b ? 1 : 0; };
  const STREAK_CMP = {
    years: function (a, b) {
      return b[1].len - a[1].len || b[1].depth - a[1].depth
        || cmpBucket(a[1].end, b[1].end) || b[1].plays - a[1].plays;
    },
    first: function (a, b) {
      return b[1].len - a[1].len || cmpBucket(a[1].end, b[1].end) || b[1].plays - a[1].plays;
    },
  };
  const streakCmp = function (dim) { return STREAK_CMP[dim === 'years' ? 'years' : 'first']; };

  /* ── Certification history ────────────────────────────────────
     A certification is not a play count, it is a moment: the one play that
     carried a record over a threshold. This single chronological pass keeps
     that moment whole for every song and album — first play, the play number
     that crossed, the date it landed — so the leaderboard's expandable
     ledger, the wall of plaques and the overview cards all read the same
     history instead of each counting the same plays their own way.

     Diamond repeats. Every further multiple of the Diamond threshold is
     another Diamond on the same record, the way the album modal already
     labels 2× and 3× Diamond. Gold and Platinum are earned once. */
  const certSongItems = {}, certAlbumItems = {};
  const certCross = function (n, cfg) {
    // Diamond is tested first so a configuration where plat === diamond still
    // awards the higher tier instead of stopping at Platinum.
    if (n >= cfg.diamond && n % cfg.diamond === 0) return { tier: 'diamond', mult: n / cfg.diamond };
    if (n === cfg.plat) return { tier: 'plat', mult: 1 };
    if (n === cfg.gold) return { tier: 'gold', mult: 1 };
    return null;
  };
  const certTouch = function (map, key, p, kind, cfg, meta) {
    let it = map[key];
    // `meta` is read on creation only — the first play names the record, the
    // same way songNames/albumNames above do.
    if (!it) it = map[key] = Object.assign({ kind: kind, key: key, first: p.date, last: p.date, plays: 0, events: [] }, meta);
    it.last = p.date;
    const n = ++it.plays;
    const cross = certCross(n, cfg);
    if (cross) it.events.push({ tier: cross.tier, mult: cross.mult, n: n, date: p.date, elapsed: p.date - it.first });
  };
  for (const p of chron) {
    certTouch(certSongItems, songKey(p), p, 'song', CERT.song, {
      title: p.title, artist: p.artist, artists: [...new Set(p.artists)],
      album: (p.album && p.album !== '—') ? p.album : ''
    });
    // Untagged plays can't be credited to an album — same guard the milestone
    // ladders above use.
    if (p.album && p.album !== '—') {
      const aa = albumArtist(p);
      const isComp = aa === VARIOUS_ARTISTS;
      const ak = p.album + '|||' + aa;
      certTouch(certAlbumItems, ak, p, 'album', CERT.album, {
        title: p.album, artist: aa, artists: [aa], album: '',
        // A compilation collects the singers who actually appear on it. The
        // plaque still hangs under Various Artists, but the ledger uses this
        // to list the album under each of them.
        comp: isComp, contributors: isComp ? new Set() : null
      });
      if (isComp) {
        const contribs = certAlbumItems[ak].contributors;
        for (const a of (p.artists && p.artists.length ? p.artists : [p.artist])) contribs.add(a);
      }
    }
  }

  /* Certifications per artist. Everyone credited on a song holds its
     certification, so a collaboration counts for both — the same attribution
     the rest of Records uses. Albums go to their album artist alone.
     The item lists ride along: they are what the expandable ledger reads. */
  const artistCertCounts = {};
  const certBucket = function (a) {
    return artistCertCounts[a] || (artistCertCounts[a] = { sg: 0, sp: 0, sd: 0, ag: 0, ap: 0, ad: 0, songs: [], albums: [] });
  };
  for (const it of Object.values(certSongItems)) {
    const tier = it.plays >= CERT.song.diamond ? 'sd' : it.plays >= CERT.song.plat ? 'sp' : it.plays >= CERT.song.gold ? 'sg' : null;
    if (!tier) continue;
    for (const a of it.artists) { const b = certBucket(a); b[tier]++; b.songs.push(it); }
  }
  for (const it of Object.values(certAlbumItems)) {
    const tier = it.plays >= CERT.album.diamond ? 'ad' : it.plays >= CERT.album.plat ? 'ap' : it.plays >= CERT.album.gold ? 'ag' : null;
    if (!tier) continue;
    if (it.comp) {
      /* A compilation's certification belongs to the record, not to the singers
         on it: tallying it for each would award one album a dozen times over,
         which is the very thing merging the album was meant to stop. The ledger
         still lists it under every contributor — the album is genuinely part of
         their history — but only as a line, never as a count. */
      for (const a of it.contributors) certBucket(a).albums.push(it);
      continue;
    }
    const b = certBucket(it.artist); b[tier]++; b.albums.push(it);
  }

  // ── RENDERING ────────────────────────────────────────────────
  // The intro carries two facts, and they are the same three columns: the
  // chart size per period, and how much history exists per period. Written as
  // one run-on line joined by a pipe, that pairing was invisible. Per column
  // it reads as a sentence — "weekly records come off a Top 20, and there are
  // 312 of those weeks" — which is the whole reason the sizes are stated here.
  //
  // The period words are `nav_*`, not the `rec_*_label` pair used lower down:
  // those are "Weekly Chart"/"Monthly Chart", and "Chart" repeated three times
  // under a heading that already says Records is noise at this size. Both sets
  // are translated in all four languages, so this costs no coverage.
  const recIntroCols = [
    { label: t('nav_weekly'), size: wSizeSongs, span: tCount('weeks_full', weekKeys.length) },
    { label: t('nav_monthly'), size: mSizeSongs, span: tCount('months', monthKeys.length) },
    { label: t('nav_yearly'), size: chartSizeYearly, span: tCount('years', yearKeys.length) },
  ];
  document.getElementById('recIntro').innerHTML =
    '<div class="rec-intro-grid">' + recIntroCols.map(function (c, i) {
      // An unlimited yearly chart has no cutoff to name, so the phrase takes
      // the slot instead of a bare ∞ that the column would then have to
      // explain. It is deliberately not `rec_yearly_all` — that string starts
      // with "Yearly", which the column heading has already said.
      const cut = isFinite(c.size)
        ? '<span class="rec-intro-pre">' + esc(t('rec_intro_top')) + '</span>' +
          '<span class="rec-intro-num">' + c.size + '</span>'
        : '<span class="rec-intro-all">' + esc(t('rec_intro_all')) + '</span>';
      // --i drives the stagger and the cutoff-rule wipe; both inherit it.
      return '<div class="rec-intro-col" style="--i:' + i + '">' +
        '<span class="rec-intro-label">' + esc(c.label) + '</span>' +
        '<span class="rec-intro-cut">' + cut + '</span>' +
        '<span class="rec-intro-span">' + esc(c.span) + '</span>' +
        '</div>';
    }).join('') + '</div>';

  /* Attributes the hero-artist tally reads off a record row — see
     recRowRecord(). Only needed where the row has no .img-src-btn written into
     its markup, which is every section that draws its own thumbnail (or has no
     thumbnail at all). Those rows do eventually gain a picker badge from
     loadImages(), but that is async, so relying on it would make the tally
     depend on how many covers happened to have resolved. */
  function recRowAttrs(artist, type, name) {
    if (!artist || !name) return '';
    const prefKey = type === 'artist'
      ? 'artist:' + artist.toLowerCase()
      : type + ':' + artist.toLowerCase() + '|||' + name.toLowerCase();
    return ' data-rec-artist="' + esc(artist) + '" data-rec-type="' + esc(type) + '"'
      + ' data-rec-name="' + esc(name) + '" data-rec-prefkey="' + esc(prefKey) + '"';
  }

  // `opts` is optional and only used by the tables that need extra hooks:
  //   tableCls — extra class(es) on the <table>
  //   rowCls   — fn(i) returning extra class(es) for row i
  //   rowAttrs — fn(i) returning extra attribute string for row i
  function recTable(headers, rows, limit, detailRows, tableId, opts) {
    opts = opts || {};
    limit = (limit === undefined || limit === null) ? 25 : limit;
    if (!rows.length) return '<div class="rec-empty">' + t('rec_no_data') + '</div>';
    const sliced = isFinite(limit) ? rows.slice(0, limit) : rows;
    const slicedDetails = detailRows ? (isFinite(limit) ? detailRows.slice(0, limit) : detailRows) : null;
    const colCount = headers.length;
    return '<table class="rec-table' + (opts.tableCls ? ' ' + opts.tableCls : '') + '"' + (tableId ? ' id="' + tableId + '"' : '') + '><thead><tr>' + headers.map(function (h) { return '<th>' + h + '</th>'; }).join('') + '</tr></thead><tbody>' +
      sliced.map(function (r, i) {
        const rankCls = (i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '')
          + (opts.rowCls ? ' ' + opts.rowCls(i) : '');
        const rowAttrs = opts.rowAttrs ? opts.rowAttrs(i) : '';
        if (!slicedDetails || !slicedDetails[i]) return '<tr class="' + rankCls + '"' + rowAttrs + '>' + r + '</tr>';
        return '<tr class="' + rankCls + '"' + rowAttrs + '>' + r + '</tr>'
          + '<tr class="rec-run-detail" id="' + slicedDetails[i].id + '"><td colspan="' + colCount + '">' + slicedDetails[i].html + '</td></tr>';
      }).join('') +
      '</tbody></table>';
  }
  const lim = recLimit === 0 ? Infinity : recLimit;

  // ── All #1s ──────────────────────────────────────────────────
  /* `label` is the full chart name ("Weekly Chart") the record titles are built
     from; `short` is the bare period the pill row wears, because the title
     right under it already spells the chart name out in full. */
  const typeConfig = [
    { pt: 'week', label: t('rec_weekly_label'), short: t('nav_weekly'), size: wSizeSongs },
    { pt: 'month', label: t('rec_monthly_label'), short: t('nav_monthly'), size: mSizeSongs },
    { pt: 'year', label: t('rec_yearly_label'), short: t('nav_yearly'), size: isFinite(chartSizeSongsY) ? chartSizeSongsY : '∞' },
  ];
  const entityConfig = [
    {
      key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs'), data: song1s, type: 'song',
      nameRow: function (k, d, i, imgId) { return '<td class="rec-rank">' + (i + 1) + '</td><td class="thumb-cell"><div class="thumb-wrap"><div id="' + imgId + '"><div class="thumb-initials">' + esc(initials(d.title)) + '</div></div><button id="srcbtn-' + imgId + '" class="img-src-btn" data-imgid="' + imgId + '" data-type="song" data-prefkey="' + esc('song:' + d.artist.toLowerCase() + '|||' + d.title.toLowerCase()) + '" data-name="' + esc(d.title) + '" data-artist="' + esc(d.artist) + '" data-album="' + esc(d.album) + '">Deezer</button></div></td><td><div class="rec-name">' + esc(d.title) + '</div><div class="rec-sub">' + esc(d.artist) + '</div></td>'; }
    },
    {
      key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists'), data: artist1s, type: 'artist',
      nameRow: function (k, d, i, imgId) { return '<td class="rec-rank">' + (i + 1) + '</td><td class="thumb-cell"><div class="thumb-wrap"><div id="' + imgId + '"><div class="thumb-initials">' + esc(initials(k)) + '</div></div><button id="srcbtn-' + imgId + '" class="img-src-btn" data-imgid="' + imgId + '" data-type="artist" data-prefkey="' + esc('artist:' + k.toLowerCase()) + '" data-name="' + esc(k) + '" data-artist="' + esc(k) + '" data-album="">Deezer</button></div></td><td><div class="rec-name">' + esc(k) + '</div></td>'; }
    },
    {
      key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums'), data: album1s, type: 'album',
      nameRow: function (k, d, i, imgId) { return '<td class="rec-rank">' + (i + 1) + '</td><td class="thumb-cell"><div class="thumb-wrap"><div id="' + imgId + '"><div class="thumb-initials">' + esc(initials(d.album)) + '</div></div><button id="srcbtn-' + imgId + '" class="img-src-btn" data-imgid="' + imgId + '" data-type="album" data-prefkey="' + esc('album:' + d.artist.toLowerCase() + '|||' + d.album.toLowerCase()) + '" data-name="' + esc(d.album) + '" data-artist="' + esc(d.artist) + '" data-album="' + esc(d.album) + '">Deezer</button></div></td><td><div class="rec-name">' + esc(d.album) + '</div><div class="rec-sub">' + esc(d.artist) + '</div></td>'; }
    },
  ];
  /* One panel per entity, one on screen at a time — the same pills Milestones,
     Fastest and New Charts wear, built by recEntTabsHtml(). Nine tables (three
     entities × weekly/monthly/yearly) was never one scroll anybody read.

     Inside each entity panel a second pill row narrows it again, to one period.
     There is no umbrella "Songs — Most Times at #1 on Chart" heading any more:
     each period is a record in its own right and says so in its own title
     ("Songs — Most Times at #1 on the Weekly Chart"), which is also what the
     hero tally and the records search read off the row. */
  const onesPanels = [];
  /* Queued while the markup is built, handed to loadImages() once it is in the
     DOM — the same pattern every other Records section uses. This section used
     to call loadImages() from inside the build loop, while the panels were
     still an unattached string: loadImages() resolves each item with
     getElementById and silently skips the ones it cannot find, so on a first
     build nothing was ever observed, and on a re-build it observed the *old*
     rows that the innerHTML assignment below was about to destroy. That is why
     All #1s covers so rarely appeared. */
  const onesImgQueue = [];
  for (const ent of entityConfig) {
    const perScope = 'ones-' + ent.key;
    let h = '<div class="rec-per-tabs" data-rec-per-scope="' + esc(perScope) + '"'
      + ' role="tablist" aria-label="' + esc(t('rec_per_tabs_label')) + '">';
    for (const cfg of typeConfig) {
      h += '<button type="button" class="rec-per-tab" role="tab"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '">'
        + esc(cfg.short) + '</button>';
    }
    h += '</div>';
    for (const cfg of typeConfig) {
      const entries = Object.entries(ent.data[cfg.pt]).sort(function (a, b) { return b[1].count - a[1].count; });
      /* data-rec-scope keeps each period's collapse state to itself, the same
         way the Milestones and New Charts panels do — see
         setupRecordSubsectionCollapse(), which grows the −/+ button on the
         .rec-section-title below rather than us hand-rolling one here. */
      h += '<div class="rec-per-panel" role="tabpanel"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '"'
        + ' data-rec-scope="' + esc(perScope + '-' + cfg.pt) + '" style="display:none">';
      h += '<div class="rec-section"><div class="rec-section-title">'
        + ent.icon + ' ' + ent.label + ' &mdash; ' + t('rec_most_times_1_on', { period: cfg.label })
        + ' ' + t('rec_suffix_non_consec') + '</div>';
      h += '<div class="rec-section-sub">' + t('rec_have_hit_1', { n: '<strong>' + entries.length + '</strong>', type: ent.label.toLowerCase() }) + '</div>';
      const tableId = 'rec-1s-tbl-' + ent.key + '-' + cfg.pt;
      const runBaseId = 'rec-1s-run-' + ent.key + '-' + cfg.pt;
      const headers = ['#', '', ent.label, periodAtOneHeader(cfg.pt), t('rec_th_first_at_1')];
      if (cfg.pt !== 'year') headers.push(t('rec_th_date_at_peak'));
      // Same glyph family as the Appearances tables — one "expand all" action,
      // one pair of glyphs (▶▶ closed / ▼▼ open) everywhere in Records.
      headers.push('<button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllRecRuns(\'' + tableId + '\',this)" title="' + t('rec_expand_all') + '">▶▶</button>');
      h += recTable(headers,
        entries.map(function (e, i) {
          const imgId = 'rec-img-' + ent.key + '-' + cfg.pt + '-' + i;
          const runId = runBaseId + '-' + i;
          let row = ent.nameRow(e[0], e[1], i, imgId) + '<td class="rec-count">' + e[1].count + '</td><td class="rec-meta">' + fmtPeriodKey(e[1].firstPeriod, cfg.pt) + '</td>';
          if (cfg.pt !== 'year') {
            row += '<td class="rec-meta"><a href="#chart/' + cfg.pt + '/' + e[1].lastPeriod + '" class="rec-date-link" onclick="event.preventDefault();navigateToRecPeriod(\'' + cfg.pt + '\',\'' + e[1].lastPeriod + '\')">' + fmtPeriodKey(e[1].lastPeriod, cfg.pt) + '</a></td>';
          }
          row += '<td class="rec-run-toggle-cell"><button class="rec-run-toggle-btn" onclick="event.stopPropagation();toggleRecRun(this,\'' + runId + '\')">▶</button></td>';
          return row;
        }),
        lim,
        entries.map(function (e, i) {
          return { id: runBaseId + '-' + i, html: rec1sBoxesHTML(e[1].periods, cfg.pt) };
        }),
        tableId
      );
      // Closes .rec-section.
      h += '</div>';
      /* One row of the entries array → one image-queue item, in whichever order
         the table that owns `imgId` put its rows. Shared by the total table
         above and the consecutive one below, which rank the same entities
         differently and so cannot share ids. */
      const queueOnesImg = function (imgId, e) {
        if (ent.type === 'song') {
          onesImgQueue.push({ imgId, imgType: 'song', title: e[1].title, artist: e[1].artist, album: e[1].album, prefKey: 'song:' + e[1].artist.toLowerCase() + '|||' + e[1].title.toLowerCase(), name: e[1].title });
        } else if (ent.type === 'artist') {
          onesImgQueue.push({ imgId, imgType: 'artist', name: e[0], prefKey: 'artist:' + e[0].toLowerCase() });
        } else {
          onesImgQueue.push({ imgId, imgType: 'album', album: e[1].album, artist: e[1].artist, name: e[1].album, prefKey: 'album:' + e[1].artist.toLowerCase() + '|||' + e[1].album.toLowerCase() });
        }
      };
      // Collect image items for loading — flushed after the innerHTML below.
      entries.forEach(function (e, i) {
        queueOnesImg('rec-img-' + ent.key + '-' + cfg.pt + '-' + i, e);
      });

      /* ── The same #1s, counted consecutively ──────────────────
         A second record in the same period panel, because twelve weeks at #1 in
         a row is not the record twelve weeks at #1 spread over four years is:
         one is a reign, the other is longevity. Same entities, re-scored on
         their longest unbroken run (bestPeriodStreak() reads the `periods`
         array the total above is built from) and re-sorted on it.

         Ranking is streak first, then the total tally, then whoever set the
         streak earliest — so a tie between two four-week reigns is broken by
         the fuller career, and a tie in that by the older record. */
      const streakRows = entries
        .map(function (e) { return { e: e, streak: bestPeriodStreak(e[1].periods, cfg.pt) }; })
        .filter(function (s) { return s.streak; })
        .sort(function (a, b) {
          if (b.streak.len !== a.streak.len) return b.streak.len - a.streak.len;
          if (b.e[1].count !== a.e[1].count) return b.e[1].count - a.e[1].count;
          return a.streak.start < b.streak.start ? -1 : a.streak.start > b.streak.start ? 1 : 0;
        });
      const cTableId = 'rec-1sc-tbl-' + ent.key + '-' + cfg.pt;
      const cRunBaseId = 'rec-1sc-run-' + ent.key + '-' + cfg.pt;
      h += '<div class="rec-section"><div class="rec-section-title">'
        + ent.icon + ' ' + ent.label + ' &mdash; ' + t('rec_most_times_1_on', { period: cfg.label })
        + ' ' + t('rec_suffix_consec') + '</div>';
      h += '<div class="rec-section-sub">' + t('rec_consec_sub_1') + '</div>';
      // A streak has a start and an end rather than a "first at #1" and a peak
      // date, so the two middle columns are its own — on the yearly chart too,
      // where the total table drops its last column.
      const cHeaders = ['#', '', ent.label, consecAtOneHeader(cfg.pt), t('rec_th_streak_start'), t('rec_th_streak_end'),
        '<button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllRecRuns(\'' + cTableId + '\',this)" title="' + t('rec_expand_all') + '">▶▶</button>'];
      h += recTable(cHeaders,
        streakRows.map(function (s, i) {
          const imgId = 'rec-1sc-img-' + ent.key + '-' + cfg.pt + '-' + i;
          const runId = cRunBaseId + '-' + i;
          const dateCell = function (pk) {
            return '<td class="rec-meta"><a href="#chart/' + cfg.pt + '/' + pk + '" class="rec-date-link" onclick="event.preventDefault();navigateToRecPeriod(\'' + cfg.pt + '\',\'' + pk + '\')">' + fmtPeriodKey(pk, cfg.pt) + '</a></td>';
          };
          return ent.nameRow(s.e[0], s.e[1], i, imgId)
            + '<td class="rec-count">' + s.streak.len + '</td>'
            + dateCell(s.streak.start) + dateCell(s.streak.end)
            + '<td class="rec-run-toggle-cell"><button class="rec-run-toggle-btn" onclick="event.stopPropagation();toggleRecRun(this,\'' + runId + '\')">▶</button></td>';
        }),
        lim,
        streakRows.map(function (s, i) {
          // Only the streak's own periods, all of them #1s — the boxes are
          // gap-free by definition, which is the point of the record.
          return {
            id: cRunBaseId + '-' + i,
            html: recStreakBoxesHTML(s.streak.periods.map(function (pk) { return { periodKey: pk, rank: 1 }; }), cfg.pt)
          };
        }),
        cTableId
      );
      // Closes the consecutive .rec-section.
      h += '</div>';
      streakRows.forEach(function (s, i) {
        queueOnesImg('rec-1sc-img-' + ent.key + '-' + cfg.pt + '-' + i, s.e);
      });
      /* Closes .rec-per-panel — and only that. This loop opens exactly two
         elements per period (the panel and the .rec-section inside it) and must
         close exactly two; a stray </div> here used to close the .rec-ent-panel
         as well, which spat the monthly and yearly tables out of the panel so
         no pill could hide them. */
      h += '</div>';
    }
    onesPanels.push({ key: ent.key, icon: ent.icon, label: ent.label, html: h });
  }
  document.getElementById('recAllOnesBody').innerHTML = recEntTabsHtml('ones', onesPanels);
  /* Split by type because loadImages() takes one type for the whole batch —
     it decides between getArtistImage / getAlbumImage / getTrackImage from it.
     Lazy, so the panels behind an unpicked pill cost nothing until picked. */
  loadImages(onesImgQueue.filter(function (x) { return x.imgType === 'song'; }), 'song');
  loadImages(onesImgQueue.filter(function (x) { return x.imgType === 'artist'; }), 'artist');
  loadImages(onesImgQueue.filter(function (x) { return x.imgType === 'album'; }), 'album');

  // ── Perfect All Kill ─────────────────────────────────────────
  /* One panel per chart, behind the same period pills All #1s wears. The three
     are not one list with a filter over it: holding all three #1s for a whole
     year is a different achievement from holding them for a week, and the
     leaderboards rank different artists because of it. */
  {
    /* Everything that differs between the three charts, in one place. `unitKey`
       feeds tUnit() for the lowercase prose word ("week"/"weeks"), `big` is the
       capitalised plural the column header needs, `nav` labels the pill, `all`
       names the full-list heading (its own key per period, because Spanish and
       Portuguese inflect the article with the noun's gender), and `size` is the
       chart depth the empty state quotes. */
    const pakCfg = [
      { pt: 'week',  unitKey: 'weeks_full', big: t('rec_period_weeks'),  nav: t('nav_weekly'),  label: t('rec_weekly_label'),  all: 'rec_pak_all_week',  size: wSizeSongs },
      { pt: 'month', unitKey: 'months',     big: t('rec_period_months'), nav: t('nav_monthly'), label: t('rec_monthly_label'), all: 'rec_pak_all_month', size: mSizeSongs },
      { pt: 'year',  unitKey: 'years',      big: t('rec_period_years'),  nav: t('nav_yearly'),  label: t('rec_yearly_label'),  all: 'rec_pak_all_year',  size: isFinite(chartSizeSongsY) ? chartSizeSongsY : '∞' },
    ];
    /* Queued while the markup is built, handed to loadImages() once it is in
       the DOM — the same pattern the appearances and debuts sections use. One
       queue for all three panels, because the two hidden ones cost nothing:
       loadImages() observes intersection and a display:none panel never fires. */
    const pakImgQueue = [];
    const pakArtistItem = function (imgId, artist) {
      return { imgId, imgType: 'artist', name: artist, prefKey: 'artist:' + artist.toLowerCase() };
    };
    const pakAlbumItem = function (imgId, album, artist) {
      return {
        imgId, imgType: 'album', name: album, album: album, artist: artist,
        prefKey: 'album:' + artist.toLowerCase() + '|||' + album.toLowerCase()
      };
    };
    const pakEmpty = function (cfg) {
      return '<div class="rec-empty">' + t('rec_no_pak', {
        n: cfg.size, period: cfg.nav, unitword: tUnit(cfg.unitKey, 2), unit: tUnit(cfg.unitKey, 1)
      }) + '</div>';
    };

    /* One chart's worth of PAKs: the artist leaderboard, then the full list
       newest first. Identical in shape to what the weekly-only version built —
       every id is prefixed with the period so the three panels cannot collide
       over an artist who tops more than one chart. */
    const pakPanelHtml = function (cfg) {
      const list = pakPeriods[cfg.pt];
      if (!list.length) return pakEmpty(cfg);
      const pt = cfg.pt;
      const byArtist = {};
      for (const pw of list) { (byArtist[pw.artist] || (byArtist[pw.artist] = [])).push(pw); }
      const sortedPAK = Object.entries(byArtist).sort(function (a, b) { return b[1].length - a[1].length; });
      /* The .rec-section-sub-wrapper is not decoration: recRowLabel() reads the
         chart name out of the .rec-section-sub inside it, taking the part before
         the dash as a row's qualifier. Without it, an artist holding PAKs on all
         three charts would send three cards to the hero reel all labelled
         "Perfect All Kill" with nothing to tell them apart. */
      let ph = '<div class="rec-section-sub-wrapper"><div class="rec-section-sub">'
        + cfg.label + ' &mdash; ' + t('rec_pak_summary', {
          count: list.length, unitword: tUnit(cfg.unitKey, list.length),
          n: sortedPAK.length, artistword: tUnit('artists', sortedPAK.length)
        }) + '</div>';
      const limEntries = isFinite(lim) ? sortedPAK.slice(0, lim) : sortedPAK;
      ph += '<table class="rec-table pak-artist-table"><thead><tr>'
        + '<th></th><th>' + t('rec_th_artist') + '</th>'
        + '<th class="pak-weeks-th">' + t('rec_th_pak_periods', { unit: cfg.big }) + '</th>'
        + '<th>' + t('rec_th_first_song') + '</th>'
        + '<th>' + t('rec_th_first_album') + '</th>'
        + '<th>' + t('rec_th_most_recent') + '</th>'
        + '</tr></thead><tbody>';
      for (let i = 0; i < limEntries.length; i++) {
        const [artist, periods] = limEntries[i];
        const firstPer = periods[0];
        const lastPer = periods[periods.length - 1];
        const safeKey = pt + '-' + artist.replace(/[^a-z0-9]/gi, '-').toLowerCase() + '-' + i;
        const artistImgId = 'pak-tbl-aimg-' + safeKey;
        pakImgQueue.push(pakArtistItem(artistImgId, artist));
        const expandId = 'pak-expand-' + safeKey;
        const rankCls = i === 0 ? ' rec-rank-1' : i === 1 ? ' rec-rank-2' : i === 2 ? ' rec-rank-3' : '';
        /* data-rec-* is what the hero-artist tally reads off this row. PAK draws its
           thumbnail itself rather than through the shared nameRow helper, so there is
           no .img-src-btn here at build time to read the artist from — see
           recRowRecord(). */
        ph += '<tr class="pak-artist-row' + rankCls + '" onclick="togglePakArtistExpand(\'' + expandId + '\',this)"'
          + ' data-rec-artist="' + esc(artist) + '" data-rec-type="artist" data-rec-name="' + esc(artist) + '"'
          + ' data-rec-prefkey="' + esc('artist:' + artist.toLowerCase()) + '">'
          + '<td class="rec-rank">' + (i + 1) + '</td>'
          + '<td><div class="pak-artist-cell"><div class="pak-mini-thumb pak-mini-thumb-round" id="' + artistImgId + '"><div class="pak-mini-initials">' + esc(initials(artist)) + '</div></div><div class="rec-name">' + esc(artist) + '</div></div></td>'
          + '<td class="rec-count">' + periods.length + '</td>'
          + '<td class="rec-meta pak-tbl-song"><span class="pak-col-icon">🎵</span>' + esc(firstPer.song) + '</td>'
          + '<td class="rec-meta pak-tbl-album"><span class="pak-col-icon">💿</span>' + esc(firstPer.album) + '</td>'
          + '<td class="rec-meta pak-tbl-last-cell"><a class="pak-date pak-date-link" href="javascript:void(0)" onclick="event.stopPropagation();showPakPeriodPreview(\'' + pt + '\',\'' + esc(lastPer.periodKey) + '\',this)">' + fmtPeriodKey(lastPer.periodKey, pt) + '</a><span class="pak-expand-icon">▼</span></td>'
          + '</tr>';
        ph += '<tr class="pak-expand-row" id="' + expandId + '" style="display:none"><td colspan="6"><div class="pak-expand-list">';
        for (let j = 0; j < periods.length; j++) {
          const pw = periods[j];
          const albumImgId = 'pak-exp-img-' + safeKey + '-' + j;
          pakImgQueue.push(pakAlbumItem(albumImgId, pw.album, artist));
          ph += '<div class="pak-expand-item" data-pak-album-img="' + albumImgId + '" data-album="' + esc(pw.album) + '" data-artist="' + esc(artist) + '">'
            + '<div class="pak-mini-thumb" id="' + albumImgId + '"><div class="pak-mini-initials">' + esc(initials(pw.album)) + '</div></div>'
            + '<span class="pak-expand-album">💿 ' + esc(pw.album) + '</span>'
            + '<span class="pak-expand-song"><span class="pak-col-icon">🎵</span>' + esc(pw.song) + '</span>'
            + '<a class="pak-date pak-date-link" href="javascript:void(0)" onclick="showPakPeriodPreview(\'' + pt + '\',\'' + esc(pw.periodKey) + '\',this)">' + fmtPeriodKey(pw.periodKey, pt) + '</a>'
            + '<a class="pak-expand-link" href="#chart/' + pt + '/' + esc(pw.periodKey) + '" onclick="event.preventDefault();navigateToRecPeriod(\'' + pt + '\',\'' + esc(pw.periodKey) + '\')">' + t('rec_pak_period_preview_link', { unit: tUnit(cfg.unitKey, 1) }) + '</a>'
            + '</div>';
        }
        ph += '</div></td></tr>';
      }
      // Closes .rec-section-sub-wrapper: the full list below is not part of the
      // leaderboard and its .pak-items are not rows the tally walks.
      ph += '</tbody></table></div>';
      ph += '<br><div class="rec-section-title" style="margin-top:0.75rem;">' + t(cfg.all) + '</div><div class="pak-list">';
      const pakGlobalIdx = {};
      const pakArtistOcc = {};
      const _artOccTmp = {};
      for (let k = 0; k < list.length; k++) {
        const wk = list[k];
        pakGlobalIdx[wk.periodKey] = k + 1;
        _artOccTmp[wk.artist] = (_artOccTmp[wk.artist] || 0) + 1;
        pakArtistOcc[wk.periodKey] = _artOccTmp[wk.artist];
      }
      const pakSlice = isFinite(lim) ? [...list].reverse().slice(0, lim) : [...list].reverse();
      for (let idx = 0; idx < pakSlice.length; idx++) {
        const pw = pakSlice[idx];
        const keySlug = pt + '-' + pw.periodKey.replace(/[^a-z0-9]/gi, '-') + '-' + idx;
        const pakImgId = 'pak-img-' + keySlug;
        const pakArtistImgId = 'pak-aimg-' + keySlug;
        pakImgQueue.push(pakAlbumItem(pakImgId, pw.album, pw.artist));
        pakImgQueue.push(pakArtistItem(pakArtistImgId, pw.artist));
        ph += '<div class="pak-item">'
          + '<a class="pak-date pak-date-link" href="javascript:void(0)" onclick="showPakPeriodPreview(\'' + pt + '\',\'' + esc(pw.periodKey) + '\',this)">' + fmtPeriodKey(pw.periodKey, pt) + '</a>'
          + '<div class="pak-col pak-col-artist"><div class="pak-mini-thumb pak-mini-thumb-round" id="' + pakArtistImgId + '"><div class="pak-mini-initials">' + esc(initials(pw.artist)) + '</div></div><span class="pak-col-text">' + esc(pw.artist) + '</span></div>'
          + '<div class="pak-col pak-col-song"><span class="pak-col-icon">🎵</span>' + esc(pw.song) + '</div>'
          + '<div class="pak-col pak-col-album"><div class="pak-mini-thumb" id="' + pakImgId + '"><div class="pak-mini-initials">' + esc(initials(pw.album)) + '</div></div><span class="pak-col-text">' + esc(pw.album) + '</span></div>'
          + '<div class="pak-badge-stack">'
          + '<span class="rec-badge rec-badge-gold">#' + pakGlobalIdx[pw.periodKey] + ' / ' + list.length + '</span>'
          + '<span class="rec-badge rec-badge-artist-pak">' + t('rec_pak_badge_artist') + ' #' + pakArtistOcc[pw.periodKey] + '</span>'
          + '</div>'
          + '</div>';
      }
      ph += '</div>';
      return ph;
    };

    /* No PAK on any chart at all: one message and no pills, rather than three
       pills leading to three copies of the same "none yet". */
    if (!pakCfg.some(function (cfg) { return pakPeriods[cfg.pt].length; })) {
      document.getElementById('recPAKBody').innerHTML = pakEmpty(pakCfg[0]);
    } else {
      let ph = '<div class="rec-per-tabs" data-rec-per-scope="pak" role="tablist"'
        + ' aria-label="' + esc(t('rec_per_tabs_label')) + '">';
      for (const cfg of pakCfg) {
        ph += '<button type="button" class="rec-per-tab" role="tab"'
          + ' data-rec-per-scope="pak" data-rec-per="' + cfg.pt + '">' + esc(cfg.nav) + '</button>';
      }
      ph += '</div>';
      for (const cfg of pakCfg) {
        // data-rec-scope keeps each period's collapse state to itself, the same
        // way the All #1s and New Charts panels do.
        ph += '<div class="rec-per-panel" role="tabpanel" data-rec-per-scope="pak"'
          + ' data-rec-per="' + cfg.pt + '" data-rec-scope="pak-' + cfg.pt + '" style="display:none">'
          + pakPanelHtml(cfg) + '</div>';
      }
      document.getElementById('recPAKBody').innerHTML = ph;
      /* PAK artwork used to fetch itself: a bare getArtistImage/getAlbumImage
         loop that walked every row eagerly with a 60ms sleep between each. That
         bypassed everything the rest of the app's artwork gets — pinned picker
         choices, the source cascade, per-item source prefs — so a cover corrected
         anywhere else in the app was still wrong here, and there was no ✎ badge to
         correct it with.

         Routing it through loadImages() fixes all of that at once, and makes it
         lazy: the expand rows are display:none until opened, so their covers are
         no longer fetched for artists nobody expanded. */
      loadImages(pakImgQueue.filter(function (x) { return x.imgType === 'artist'; }), 'artist');
      loadImages(pakImgQueue.filter(function (x) { return x.imgType === 'album'; }), 'album');
    }
  }

  // ── Most Chart Appearances ────────────────────────────────────
  ensureAllChartRun();
  /* The section used to count weeks only, even though songApps/artistApps/
     albumApps have carried month and year tallies all along. Each period is now
     its own named record ("Songs — Most Weekly Chart Appearances", "… Monthly
     Chart Appearances", "… Yearly Chart Appearances") behind a period pill row,
     the same shape All #1s and Most Plays wear.

     `label` is the full chart name the record title is built from, `nav` the
     bare word the pill row wears (the title right under it already spells the
     chart out), `big` the capitalised plural the "Weeks on Chart" column header
     needs, and `unitKey` the lowercase prose plural of the count cell. */
  const appCfg = [
    { pt: 'week',  label: t('rec_weekly_label'),  nav: t('nav_weekly'),  big: t('rec_period_weeks'),  unitKey: 'weeks_full' },
    { pt: 'month', label: t('rec_monthly_label'), nav: t('nav_monthly'), big: t('rec_period_months'), unitKey: 'months' },
    { pt: 'year',  label: t('rec_yearly_label'),  nav: t('nav_yearly'),  big: t('rec_period_years'),  unitKey: 'years' },
  ];
  /* Queued while the markup is built, flushed once it is in the DOM —
     loadImages() resolves each item by id, so it has nothing to attach to while
     the panels are still an unattached string. */
  const appImgQueue = [];
  /* One builder per entity, each handed a period cfg and returning exactly one
     .rec-section. Ids carry the period so the three copies of a table don't
     collide — toggleAppCr()/toggleAllAppCr() reach their rows by id. */
  const appBuild = {
    songs: function (cfg) {
      const tops = Object.entries(songApps[cfg.pt]).sort((a, b) => b[1] - a[1]);
      const sliced = isFinite(lim) ? tops.slice(0, lim) : tops;
      const tableId = 'app-tbl-songs-' + cfg.pt;
      let ah = '<div class="rec-section"><div class="rec-section-title">' + recEntIco('songs') + ' ' + t('rec_th_songs') + ' &mdash; ' + t('rec_most_appearances_on', { period: cfg.label }) + ' ' + t('rec_suffix_non_consec') + '</div>';
      ah += '<div class="app-table-wrap"><table class="rec-table app-appearances-table" id="' + tableId + '"><thead><tr>';
      ah += '<th>#</th><th></th><th>' + t('rec_th_songs') + '</th><th class="app-art-th"></th><th>' + t('rec_th_artist') + '</th>';
      ah += '<th>' + t('rec_th_first_streamed') + '</th><th>' + t('rec_th_last_streamed') + '</th>';
      ah += '<th>' + t('rec_th_on_chart', { unit: cfg.big }) + '</th><th class="rec-cr-th"><button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllAppCr(\'' + tableId + '\',this)" title="' + t('rec_expand_all') + '">▶▶</button></th>';
      ah += '</tr></thead><tbody>';
      for (let i = 0; i < sliced.length; i++) {
        const [k, count] = sliced[i];
        const n = songNames[k] || {};
        const title = n.title || k.split('|||')[0];
        const artist = n.artist || '';
        const album = n.album || '';
        const imgId = 'app-song-img-' + cfg.pt + '-' + i;
        const artImgId = 'app-art-song-' + cfg.pt + '-' + i;
        const crRowId = 'app-cr-row-song-' + cfg.pt + '-' + i;
        const firstDate = songFirstPlay[k] ? fmt(songFirstPlay[k]) : '—';
        const lastDate = songLastPlay[k] ? fmt(songLastPlay[k]) : '—';
        const rankCls = i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '';
        ah += '<tr class="' + rankCls + '">';
        ah += '<td class="rec-rank">' + (i + 1) + '</td>';
        ah += '<td class="thumb-cell"><div class="thumb-wrap"><div id="' + imgId + '"><div class="thumb-initials">' + esc(initials(title)) + '</div></div>';
        ah += '<button id="srcbtn-' + imgId + '" class="img-src-btn" data-imgid="' + imgId + '" data-type="song" data-prefkey="' + esc('song:' + artist.toLowerCase() + '|||' + title.toLowerCase()) + '" data-name="' + esc(title) + '" data-artist="' + esc(artist) + '" data-album="' + esc(album) + '">Deezer</button></div></td>';
        ah += '<td><div class="rec-name">' + esc(title) + '</div></td>';
        ah += '<td class="thumb-cell"><div class="thumb-wrap"><div id="' + artImgId + '" class="app-art-circle"><div class="thumb-initials">' + esc(initials(artist)) + '</div></div>';
        ah += '<button id="srcbtn-' + artImgId + '" class="img-src-btn" data-imgid="' + artImgId + '" data-type="artist" data-prefkey="' + esc('artist:' + artist.toLowerCase()) + '" data-name="' + esc(artist) + '" data-artist="' + esc(artist) + '" data-album="">Deezer</button></div></td>';
        ah += '<td><div class="rec-name">' + esc(artist) + '</div></td>';
        ah += '<td class="rec-meta">' + esc(firstDate) + '</td>';
        ah += '<td class="rec-meta">' + esc(lastDate) + '</td>';
        ah += '<td class="rec-count">' + tCount(cfg.unitKey, count) + '</td>';
        ah += '<td class="rec-cr-btn-cell"><button class="rec-cr-toggle" onclick="toggleAppCr(\'' + crRowId + '\',this)" title="' + t('cr_chart_run') + '">▶</button></td>';
        ah += '</tr>';
        ah += '<tr class="app-cr-row" id="' + crRowId + '" style="display:none"><td colspan="9"><div class="app-cr-content">' + crBoxesHTML('songs', k, allChartRun[cfg.pt]) + '</div></td></tr>';
        appImgQueue.push({ imgId, imgType: 'song', name: title, prefKey: 'song:' + artist.toLowerCase() + '|||' + title.toLowerCase(), title, artist, album });
        appImgQueue.push({ imgId: artImgId, imgType: 'artist', name: artist, prefKey: 'artist:' + artist.toLowerCase() });
      }
      ah += '</tbody></table></div></div>';
      return ah;
    },

    artists: function (cfg) {
      const tops = Object.entries(artistApps[cfg.pt]).sort((a, b) => b[1] - a[1]);
      const sliced = isFinite(lim) ? tops.slice(0, lim) : tops;
      const tableId = 'app-tbl-artists-' + cfg.pt;
      let ah = '<div class="rec-section"><div class="rec-section-title">' + recEntIco('artists') + ' ' + t('rec_th_artists') + ' &mdash; ' + t('rec_most_appearances_on', { period: cfg.label }) + ' ' + t('rec_suffix_non_consec') + '</div>';
      ah += '<div class="app-table-wrap"><table class="rec-table app-appearances-table" id="' + tableId + '"><thead><tr>';
      ah += '<th>#</th><th></th><th>' + t('rec_th_artist') + '</th>';
      ah += '<th>' + t('rec_th_first_song') + '</th><th>' + t('rec_th_last_song') + '</th>';
      ah += '<th>' + t('rec_th_first_charted') + '</th>';
      ah += '<th>' + t('rec_th_on_chart', { unit: cfg.big }) + '</th><th class="rec-cr-th"><button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllAppCr(\'' + tableId + '\',this)" title="' + t('rec_expand_all') + '">▶▶</button></th>';
      ah += '</tr></thead><tbody>';
      for (let i = 0; i < sliced.length; i++) {
        const [a, count] = sliced[i];
        const imgId = 'app-artist-img-' + cfg.pt + '-' + i;
        const crRowId = 'app-cr-row-artist-' + cfg.pt + '-' + i;
        const firstSong = artistFirstSongName[a] || '—';
        const lastSong = artistLastSongName[a] || '—';
        // "First Charted" means first charted on *this* chart, so it reads the
        // debut map for the panel's own period rather than always the weekly.
        const firstCharted = artistDebuts[cfg.pt][a] ? fmtPeriodKey(artistDebuts[cfg.pt][a].period, cfg.pt) : '—';
        const rankCls = i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '';
        ah += '<tr class="' + rankCls + '">';
        ah += '<td class="rec-rank">' + (i + 1) + '</td>';
        ah += '<td class="thumb-cell"><div class="thumb-wrap"><div id="' + imgId + '" class="app-art-circle"><div class="thumb-initials">' + esc(initials(a)) + '</div></div>';
        ah += '<button id="srcbtn-' + imgId + '" class="img-src-btn" data-imgid="' + imgId + '" data-type="artist" data-prefkey="' + esc('artist:' + a.toLowerCase()) + '" data-name="' + esc(a) + '" data-artist="' + esc(a) + '" data-album="">Deezer</button></div></td>';
        ah += '<td><div class="rec-name">' + esc(a) + '</div></td>';
        ah += '<td class="rec-meta app-song-cell"><span class="app-song-icon">🎵</span>' + esc(firstSong) + '</td>';
        ah += '<td class="rec-meta app-song-cell"><span class="app-song-icon">🎵</span>' + esc(lastSong) + '</td>';
        ah += '<td class="rec-meta">' + esc(firstCharted) + '</td>';
        ah += '<td class="rec-count">' + tCount(cfg.unitKey, count) + '</td>';
        ah += '<td class="rec-cr-btn-cell"><button class="rec-cr-toggle" onclick="toggleAppCr(\'' + crRowId + '\',this)" title="' + t('cr_chart_run') + '">▶</button></td>';
        ah += '</tr>';
        ah += '<tr class="app-cr-row" id="' + crRowId + '" style="display:none"><td colspan="8"><div class="app-cr-content">' + crBoxesHTML('artists', a, allChartRun[cfg.pt]) + '</div></td></tr>';
        appImgQueue.push({ imgId, imgType: 'artist', name: a, prefKey: 'artist:' + a.toLowerCase() });
      }
      ah += '</tbody></table></div></div>';
      return ah;
    },

    albums: function (cfg) {
      const tops = Object.entries(albumApps[cfg.pt]).sort((a, b) => b[1] - a[1]);
      const sliced = isFinite(lim) ? tops.slice(0, lim) : tops;
      const tableId = 'app-tbl-albums-' + cfg.pt;
      let ah = '<div class="rec-section"><div class="rec-section-title">' + recEntIco('albums') + ' ' + t('rec_th_albums') + ' &mdash; ' + t('rec_most_appearances_on', { period: cfg.label }) + ' ' + t('rec_suffix_non_consec') + '</div>';
      ah += '<div class="app-table-wrap"><table class="rec-table app-appearances-table" id="' + tableId + '"><thead><tr>';
      ah += '<th>#</th><th></th><th>' + t('rec_th_albums') + '</th><th class="app-art-th"></th><th>' + t('rec_th_artist') + '</th>';
      ah += '<th>' + t('rec_th_first_song') + '</th>';
      ah += '<th>' + t('rec_th_first_streamed') + '</th>';
      ah += '<th>' + t('rec_th_on_chart', { unit: cfg.big }) + '</th><th class="rec-cr-th"><button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllAppCr(\'' + tableId + '\',this)" title="' + t('rec_expand_all') + '">▶▶</button></th>';
      ah += '</tr></thead><tbody>';
      for (let i = 0; i < sliced.length; i++) {
        const [k, count] = sliced[i];
        const n = albumNames[k] || {};
        const album = n.album || k.split('|||')[0];
        const artist = n.artist || '';
        const imgId = 'app-album-img-' + cfg.pt + '-' + i;
        const artImgId = 'app-art-album-' + cfg.pt + '-' + i;
        const crRowId = 'app-cr-row-album-' + cfg.pt + '-' + i;
        const firstSong = albumFirstSongName[k] || '—';
        const firstDate = albumFirstPlayDate[k] ? fmt(albumFirstPlayDate[k]) : '—';
        const rankCls = i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '';
        ah += '<tr class="' + rankCls + '">';
        ah += '<td class="rec-rank">' + (i + 1) + '</td>';
        ah += '<td class="thumb-cell"><div class="thumb-wrap"><div id="' + imgId + '"><div class="thumb-initials">' + esc(initials(album)) + '</div></div>';
        ah += '<button id="srcbtn-' + imgId + '" class="img-src-btn" data-imgid="' + imgId + '" data-type="album" data-prefkey="' + esc('album:' + artist.toLowerCase() + '|||' + album.toLowerCase()) + '" data-name="' + esc(album) + '" data-artist="' + esc(artist) + '" data-album="' + esc(album) + '">Deezer</button></div></td>';
        ah += '<td><div class="rec-name">' + esc(album) + '</div></td>';
        ah += '<td class="thumb-cell"><div class="thumb-wrap"><div id="' + artImgId + '" class="app-art-circle"><div class="thumb-initials">' + esc(initials(artist)) + '</div></div>';
        ah += '<button id="srcbtn-' + artImgId + '" class="img-src-btn" data-imgid="' + artImgId + '" data-type="artist" data-prefkey="' + esc('artist:' + artist.toLowerCase()) + '" data-name="' + esc(artist) + '" data-artist="' + esc(artist) + '" data-album="">Deezer</button></div></td>';
        ah += '<td><div class="rec-name">' + esc(artist) + '</div></td>';
        ah += '<td class="rec-meta app-song-cell"><span class="app-song-icon">🎵</span>' + esc(firstSong) + '</td>';
        ah += '<td class="rec-meta">' + esc(firstDate) + '</td>';
        ah += '<td class="rec-count">' + tCount(cfg.unitKey, count) + '</td>';
        ah += '<td class="rec-cr-btn-cell"><button class="rec-cr-toggle" onclick="toggleAppCr(\'' + crRowId + '\',this)" title="' + t('cr_chart_run') + '">▶</button></td>';
        ah += '</tr>';
        ah += '<tr class="app-cr-row" id="' + crRowId + '" style="display:none"><td colspan="9"><div class="app-cr-content">' + crBoxesHTML('albums', k, allChartRun[cfg.pt]) + '</div></td></tr>';
        appImgQueue.push({ imgId, imgType: 'album', name: album, prefKey: 'album:' + artist.toLowerCase() + '|||' + album.toLowerCase(), album, artist });
        appImgQueue.push({ imgId: artImgId, imgType: 'artist', name: artist, prefKey: 'artist:' + artist.toLowerCase() });
      }
      ah += '</tbody></table></div></div>';
      return ah;
    }
  };
  const APP_REC_TYPES = [
    { key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs') },
    { key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists') },
    { key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums') }
  ];

  /* ── The same appearances, counted consecutively ────────────────
     Every appearances table above gets a twin ranked on the longest unbroken
     run on the chart instead of the total tally: forty scattered weeks is a
     catalogue staple, forty weeks in a row is a stranglehold.

     The run itself comes from allChartRun (ensureAllChartRun() ran at the top of
     this section) rather than from a fourth set of per-key period arrays —
     it already holds every period an entity charted in, with its rank, under
     exactly the keys songApps/artistApps/albumApps use, so the streak boxes can
     show the real positions the run was made of.

     Rows are drawn with the All #1s nameRow helpers, which is why this is one
     builder for all three entities rather than three: they already write the
     thumb, the name, the artist sub-line and the Deezer picker button for each
     type, and reusing them keeps this table's artwork identical to that one's. */
  const onesEntByKey = {};
  entityConfig.forEach(function (e) { onesEntByKey[e.key] = e; });
  const appsByKey = { songs: songApps, artists: artistApps, albums: albumApps };
  function appConsecSection(ent, cfg) {
    const nameEnt = onesEntByKey[ent.key];
    const runs = (allChartRun[cfg.pt] && allChartRun[cfg.pt].result && allChartRun[cfg.pt].result[ent.key]) || {};
    const rows = [];
    for (const k of Object.keys(appsByKey[ent.key][cfg.pt])) {
      const crEntries = (runs[k] && runs[k].entries) || [];
      const streak = bestPeriodStreak(crEntries.map(function (e) { return e.periodKey; }), cfg.pt);
      if (!streak) continue;
      // The `d` each nameRow expects: song1s/album1s carry these fields, and the
      // names maps hold the same shape. Keys fall back to their own first half
      // so a missing name map still renders a title rather than "undefined".
      let d;
      if (ent.key === 'songs') {
        const n = songNames[k] || {};
        d = { title: n.title || k.split('|||')[0], artist: n.artist || '', album: n.album || '' };
      } else if (ent.key === 'albums') {
        const n = albumNames[k] || {};
        d = { album: n.album || k.split('|||')[0], artist: n.artist || '' };
      } else {
        d = {};
      }
      rows.push({
        key: k, d: d, streak: streak,
        total: appsByKey[ent.key][cfg.pt][k],
        entries: crEntries.slice(streak.startIdx, streak.startIdx + streak.len)
      });
    }
    // Streak first, then the fuller chart history, then whoever got there first.
    rows.sort(function (a, b) {
      if (b.streak.len !== a.streak.len) return b.streak.len - a.streak.len;
      if (b.total !== a.total) return b.total - a.total;
      return a.streak.start < b.streak.start ? -1 : a.streak.start > b.streak.start ? 1 : 0;
    });
    const tableId = 'app-c-tbl-' + ent.key + '-' + cfg.pt;
    const runBaseId = 'app-c-run-' + ent.key + '-' + cfg.pt;
    let ah = '<div class="rec-section"><div class="rec-section-title">'
      + ent.icon + ' ' + ent.label + ' &mdash; ' + t('rec_most_appearances_on', { period: cfg.label })
      + ' ' + t('rec_suffix_consec') + '</div>';
    ah += '<div class="rec-section-sub">' + t('rec_consec_sub_app') + '</div>';
    const headers = ['#', '', ent.label, t('rec_th_consec_on_chart', { unit: cfg.big }),
      t('rec_th_streak_start'), t('rec_th_streak_end'),
      '<button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllRecRuns(\'' + tableId + '\',this)" title="' + t('rec_expand_all') + '">▶▶</button>'];
    ah += recTable(headers,
      rows.map(function (r, i) {
        const imgId = 'app-c-img-' + ent.key + '-' + cfg.pt + '-' + i;
        const runId = runBaseId + '-' + i;
        const dateCell = function (pk) {
          return '<td class="rec-meta"><a href="#chart/' + cfg.pt + '/' + pk + '" class="rec-date-link" onclick="event.preventDefault();navigateToRecPeriod(\'' + cfg.pt + '\',\'' + pk + '\')">' + fmtPeriodKey(pk, cfg.pt) + '</a></td>';
        };
        return nameEnt.nameRow(r.key, r.d, i, imgId)
          + '<td class="rec-count">' + tCount(cfg.unitKey, r.streak.len) + '</td>'
          + dateCell(r.streak.start) + dateCell(r.streak.end)
          + '<td class="rec-run-toggle-cell"><button class="rec-run-toggle-btn" onclick="event.stopPropagation();toggleRecRun(this,\'' + runId + '\')">▶</button></td>';
      }),
      lim,
      rows.map(function (r, i) {
        // Only the streak, with the real ranks it was made of — a #1 in the
        // middle of a forty-week run is worth seeing.
        return { id: runBaseId + '-' + i, html: recStreakBoxesHTML(r.entries, cfg.pt) };
      }),
      tableId
    );
    ah += '</div>';
    const sliced = isFinite(lim) ? rows.slice(0, lim) : rows;
    sliced.forEach(function (r, i) {
      const imgId = 'app-c-img-' + ent.key + '-' + cfg.pt + '-' + i;
      if (ent.key === 'songs') {
        appImgQueue.push({ imgId, imgType: 'song', name: r.d.title, prefKey: 'song:' + r.d.artist.toLowerCase() + '|||' + r.d.title.toLowerCase(), title: r.d.title, artist: r.d.artist, album: r.d.album });
      } else if (ent.key === 'artists') {
        appImgQueue.push({ imgId, imgType: 'artist', name: r.key, prefKey: 'artist:' + r.key.toLowerCase() });
      } else {
        appImgQueue.push({ imgId, imgType: 'album', name: r.d.album, prefKey: 'album:' + r.d.artist.toLowerCase() + '|||' + r.d.album.toLowerCase(), album: r.d.album, artist: r.d.artist });
      }
    });
    return ah;
  }
  const appPanels = APP_REC_TYPES.map(function (ent) {
    // One period pill row per entity panel, so Songs can sit on Weekly while
    // Albums sits on Yearly — 'app-songs' is a different stored choice.
    const perScope = 'app-' + ent.key;
    let html = '<div class="rec-per-tabs" data-rec-per-scope="' + esc(perScope) + '"'
      + ' role="tablist" aria-label="' + esc(t('rec_per_tabs_label')) + '">';
    for (const cfg of appCfg) {
      html += '<button type="button" class="rec-per-tab" role="tab"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '">'
        + esc(cfg.nav) + '</button>';
    }
    html += '</div>';
    for (const cfg of appCfg) {
      // data-rec-scope is the entity *and* the period, because the same three
      // record titles repeat across entities and setupRecordSubsectionCollapse()
      // reads the nearest scope — this panel, not the .rec-ent-panel around it.
      html += '<div class="rec-per-panel" role="tabpanel"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '"'
        + ' data-rec-scope="' + esc(perScope + '-' + cfg.pt) + '" style="display:none">'
        + appBuild[ent.key](cfg)
        // Two records per period panel now — the total, then the longest run.
        + appConsecSection(ent, cfg)
        + '</div>';
    }
    return { key: ent.key, icon: ent.icon, label: ent.label, html: html };
  });

  document.getElementById('recAppearancesBody').innerHTML = recEntTabsHtml('app', appPanels);
  /* Split by type because loadImages() takes one type for the whole batch. The
     awaits that used to wrap these bought nothing — loadImages() is synchronous
     up to the observer setup — and the panels behind an unpicked pill cost
     nothing until that pill is picked. */
  loadImages(appImgQueue.filter(x => x.imgType === 'song'), 'song');
  loadImages(appImgQueue.filter(x => x.imgType === 'artist'), 'artist');
  loadImages(appImgQueue.filter(x => x.imgType === 'album'), 'album');

  // ── Biggest Debuts ───────────────────────────────────────────
  const debImgQueue = [];
  /* Debuts ranked the weekly chart only, though songDebuts/artistDebuts/
     albumDebuts have always held month and year maps too. Same treatment as
     Appearances above: each period is its own record behind a period pill row,
     one builder per entity handed a period cfg.

     `nav` is the bare word on the pill and inside the record title's bracket
     ("Biggest Debut Positions (Monthly)"), `unitLabel` the singular the last
     column is headed with, and `unitKey` the prose plural the period preview
     link needs. */
  const debCfg = [
    { pt: 'week',  nav: t('nav_weekly'),  unitLabel: t('rec_th_week'),  unitKey: 'weeks_full' },
    { pt: 'month', nav: t('nav_monthly'), unitLabel: t('rec_th_month'), unitKey: 'months' },
    { pt: 'year',  nav: t('nav_yearly'),  unitLabel: t('rec_th_year'),  unitKey: 'years' },
  ];
  // Biggest debut = most plays, then best chart position, then earliest period.
  const debSort = function (a, b) {
    return b[1].plays - a[1].plays || a[1].rank - b[1].rank || a[1].period.localeCompare(b[1].period);
  };
  /* The period cell: a link that previews that week/month/year's chart. Ids
     carry the period so the three copies of a row can't collide. */
  function debPeriodCell(pt, periodKey) {
    return '<td class="rec-meta"><a class="debut-week-link" href="javascript:void(0)"'
      + ' onclick="showDebutPeriodPreview(\'' + pt + '\',\'' + esc(periodKey) + '\',this,event)">'
      + fmtPeriodKey(periodKey, pt) + '</a></td>';
  }

  const debBuild = {
    songs: function (cfg) {
      const debs = Object.entries(songDebuts[cfg.pt]).sort(debSort);
      const sliced = isFinite(lim) ? debs.slice(0, lim) : debs;
      let dh = '<div class="rec-section"><div class="rec-section-title">' + recEntIco('songs') + ' ' + t('rec_th_songs') + ' &mdash; ' + t('rec_biggest_debuts_on', { period: cfg.nav }) + '</div>';
      if (!sliced.length) {
        dh += '<div class="rec-empty">' + t('rec_no_data') + '</div>';
      } else {
        dh += '<div class="app-table-wrap"><table class="rec-table debut-rich-table"><thead><tr>';
        dh += '<th>#</th><th>' + t('rec_th_songs') + '</th><th class="debut-mini-art-th"></th><th>' + t('rec_th_artist') + '</th>';
        dh += '<th>' + t('rec_th_plays') + '</th><th>' + t('rec_th_debut_rank') + '</th><th>' + cfg.unitLabel + '</th>';
        dh += '</tr></thead><tbody>';
        sliced.forEach(function (e, i) {
          const d = e[1];
          const rankCls = i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '';
          const artImgId = 'deb-song-art-' + cfg.pt + '-' + i;
          const artPrefKey = 'artist:' + d.artist.toLowerCase();
          // data-rec-* for the hero tally: the Debuts tables draw their own mini
          // thumbnails, so there is no .img-src-btn in the markup to read from —
          // the picker badge only arrives later, from loadImages().
          dh += '<tr class="' + rankCls + '" data-rec-artist="' + esc(d.artist) + '" data-rec-type="song"'
            + ' data-rec-name="' + esc(d.title) + '" data-rec-prefkey="' + esc('song:' + d.artist.toLowerCase() + '|||' + d.title.toLowerCase()) + '">';
          dh += '<td class="rec-rank">' + (i + 1) + '</td>';
          dh += '<td><span class="pak-col-icon">🎵</span><span class="rec-name">' + esc(d.title) + '</span></td>';
          dh += '<td><div class="pak-mini-thumb pak-mini-thumb-round" id="' + artImgId + '"><div class="pak-mini-initials">' + esc(initials(d.artist)) + '</div></div></td>';
          dh += '<td><div class="rec-name">' + esc(d.artist) + '</div></td>';
          dh += '<td class="rec-count">' + (d.plays || 0) + '</td>';
          dh += '<td class="rec-count">#' + d.rank + '</td>';
          dh += debPeriodCell(cfg.pt, d.period);
          dh += '</tr>';
          debImgQueue.push({ imgId: artImgId, imgType: 'artist', name: d.artist, prefKey: artPrefKey });
        });
        dh += '</tbody></table></div>';
      }
      dh += '</div>';
      return dh;
    },

    artists: function (cfg) {
      const debs = Object.entries(artistDebuts[cfg.pt]).sort(debSort);
      const sliced = isFinite(lim) ? debs.slice(0, lim) : debs;
      let dh = '<div class="rec-section"><div class="rec-section-title">' + recEntIco('artists') + ' ' + t('rec_th_artists') + ' &mdash; ' + t('rec_biggest_debuts_on', { period: cfg.nav }) + '</div>';
      if (!sliced.length) {
        dh += '<div class="rec-empty">' + t('rec_no_data') + '</div>';
      } else {
        dh += '<div class="app-table-wrap"><table class="rec-table debut-rich-table"><thead><tr>';
        dh += '<th>#</th><th class="debut-mini-art-th"></th><th>' + t('rec_th_artist') + '</th>';
        dh += '<th>' + t('rec_th_first_song') + '</th>';
        dh += '<th class="debut-mini-art-th"></th><th>' + t('rec_th_first_album') + '</th>';
        dh += '<th>' + t('rec_th_plays') + '</th><th>' + t('rec_th_debut_rank') + '</th><th>' + cfg.unitLabel + '</th>';
        dh += '</tr></thead><tbody>';
        sliced.forEach(function (e, i) {
          const a = e[0], d = e[1];
          const rankCls = i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '';
          const artImgId = 'deb-art-img-' + cfg.pt + '-' + i;
          const artPrefKey = 'artist:' + a.toLowerCase();
          const fSong = artistFirstSongName[a] || '';
          const fAlbObj = artistFirstAlbum[a] || null;
          const fAlbImgId = 'deb-art-falb-' + cfg.pt + '-' + i;
          const fAlbPrefKey = fAlbObj ? 'album:' + fAlbObj.artist.toLowerCase() + '|||' + fAlbObj.album.toLowerCase() : '';
          dh += '<tr class="' + rankCls + '" data-rec-artist="' + esc(a) + '" data-rec-type="artist"'
            + ' data-rec-name="' + esc(a) + '" data-rec-prefkey="' + esc('artist:' + a.toLowerCase()) + '">';
          dh += '<td class="rec-rank">' + (i + 1) + '</td>';
          dh += '<td><div class="pak-mini-thumb pak-mini-thumb-round" id="' + artImgId + '"><div class="pak-mini-initials">' + esc(initials(a)) + '</div></div></td>';
          dh += '<td><div class="rec-name">' + esc(a) + '</div></td>';
          if (fSong) {
            dh += '<td><span class="pak-col-icon">🎵</span><span class="rec-name debut-first-label">' + esc(fSong) + '</span></td>';
          } else {
            dh += '<td class="rec-meta">—</td>';
          }
          if (fAlbObj) {
            dh += '<td><div class="pak-mini-thumb" id="' + fAlbImgId + '"><div class="pak-mini-initials">' + esc(initials(fAlbObj.album)) + '</div></div></td>';
            dh += '<td><div class="rec-name debut-first-label">' + esc(fAlbObj.album) + '</div></td>';
            debImgQueue.push({ imgId: fAlbImgId, imgType: 'album', name: fAlbObj.album, album: fAlbObj.album, artist: fAlbObj.artist, prefKey: fAlbPrefKey });
          } else {
            dh += '<td></td><td class="rec-meta">—</td>';
          }
          dh += '<td class="rec-count">' + (d.plays || 0) + '</td>';
          dh += '<td class="rec-count">#' + d.rank + '</td>';
          dh += debPeriodCell(cfg.pt, d.period);
          dh += '</tr>';
          debImgQueue.push({ imgId: artImgId, imgType: 'artist', name: a, prefKey: artPrefKey });
        });
        dh += '</tbody></table></div>';
      }
      dh += '</div>';
      return dh;
    },

    albums: function (cfg) {
      const debs = Object.entries(albumDebuts[cfg.pt]).sort(debSort);
      const sliced = isFinite(lim) ? debs.slice(0, lim) : debs;
      let dh = '<div class="rec-section"><div class="rec-section-title">' + recEntIco('albums') + ' ' + t('rec_th_albums') + ' &mdash; ' + t('rec_biggest_debuts_on', { period: cfg.nav }) + '</div>';
      if (!sliced.length) {
        dh += '<div class="rec-empty">' + t('rec_no_data') + '</div>';
      } else {
        dh += '<div class="app-table-wrap"><table class="rec-table debut-rich-table"><thead><tr>';
        dh += '<th>#</th><th class="debut-mini-art-th"></th><th>' + t('rec_th_albums') + '</th><th class="debut-mini-art-th"></th><th>' + t('rec_th_artist') + '</th>';
        dh += '<th>' + t('rec_th_plays') + '</th><th>' + t('rec_th_debut_rank') + '</th><th>' + cfg.unitLabel + '</th>';
        dh += '</tr></thead><tbody>';
        sliced.forEach(function (e, i) {
          const d = e[1];
          const rankCls = i === 0 ? 'rec-rank-1' : i === 1 ? 'rec-rank-2' : i === 2 ? 'rec-rank-3' : '';
          const albImgId = 'deb-alb-img-' + cfg.pt + '-' + i;
          const artImgId = 'deb-alb-art-' + cfg.pt + '-' + i;
          const albPrefKey = 'album:' + d.artist.toLowerCase() + '|||' + d.album.toLowerCase();
          const artPrefKey = 'artist:' + d.artist.toLowerCase();
          dh += '<tr class="' + rankCls + '" data-rec-artist="' + esc(d.artist) + '" data-rec-type="album"'
            + ' data-rec-name="' + esc(d.album) + '" data-rec-prefkey="' + esc(albPrefKey) + '">';
          dh += '<td class="rec-rank">' + (i + 1) + '</td>';
          dh += '<td><div class="pak-mini-thumb" id="' + albImgId + '"><div class="pak-mini-initials">' + esc(initials(d.album)) + '</div></div></td>';
          dh += '<td><div class="rec-name">' + esc(d.album) + '</div></td>';
          dh += '<td><div class="pak-mini-thumb pak-mini-thumb-round" id="' + artImgId + '"><div class="pak-mini-initials">' + esc(initials(d.artist)) + '</div></div></td>';
          dh += '<td><div class="rec-name">' + esc(d.artist) + '</div></td>';
          dh += '<td class="rec-count">' + (d.plays || 0) + '</td>';
          dh += '<td class="rec-count">#' + d.rank + '</td>';
          dh += debPeriodCell(cfg.pt, d.period);
          dh += '</tr>';
          debImgQueue.push({ imgId: albImgId, imgType: 'album', name: d.album, album: d.album, artist: d.artist, prefKey: albPrefKey });
          debImgQueue.push({ imgId: artImgId, imgType: 'artist', name: d.artist, prefKey: artPrefKey });
        });
        dh += '</tbody></table></div>';
      }
      dh += '</div>';
      return dh;
    }
  };
  const DEB_REC_TYPES = [
    { key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs') },
    { key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists') },
    { key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums') }
  ];
  const debPanels = DEB_REC_TYPES.map(function (ent) {
    // 'deb-songs' is a different stored period choice from 'deb-albums', so
    // each entity remembers the chart you last looked at it on.
    const perScope = 'deb-' + ent.key;
    let html = '<div class="rec-per-tabs" data-rec-per-scope="' + esc(perScope) + '"'
      + ' role="tablist" aria-label="' + esc(t('rec_per_tabs_label')) + '">';
    for (const cfg of debCfg) {
      html += '<button type="button" class="rec-per-tab" role="tab"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '">'
        + esc(cfg.nav) + '</button>';
    }
    html += '</div>';
    for (const cfg of debCfg) {
      // Scoped by entity *and* period: the same three titles repeat across the
      // three entity panels, and setupRecordSubsectionCollapse() keys its
      // collapse state off the nearest [data-rec-scope].
      html += '<div class="rec-per-panel" role="tabpanel"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '"'
        + ' data-rec-scope="' + esc(perScope + '-' + cfg.pt) + '" style="display:none">'
        + debBuild[ent.key](cfg)
        + '</div>';
    }
    return { key: ent.key, icon: ent.icon, label: ent.label, html: html };
  });

  document.getElementById('recDebutsBody').innerHTML = recEntTabsHtml('deb', debPanels);
  // One batch per type — loadImages() picks its fetcher from the type it is
  // given, and the awaits these used to carry deferred nothing.
  loadImages(debImgQueue.filter(function (x) { return x.imgType === 'song'; }), 'song');
  loadImages(debImgQueue.filter(function (x) { return x.imgType === 'artist'; }), 'artist');
  loadImages(debImgQueue.filter(function (x) { return x.imgType === 'album'; }), 'album');

  // ── Most Plays in a Period ────────────────────────────────────
  /* `unitLabel` is the period word the record title and its last column wear
     ("Week"); `short` is the bare period the pill row wears, the same pair All
     #1s keeps above. */
  const ptCfg = [
    { pt: 'week', unitLabel: t('rec_th_week'), short: t('nav_weekly'), sPP: songPP.week, aPP: artistPP.week, lPP: albumPP.week },
    { pt: 'month', unitLabel: t('rec_th_month'), short: t('nav_monthly'), sPP: songPP.month, aPP: artistPP.month, lPP: albumPP.month },
    { pt: 'year', unitLabel: t('rec_th_year'), short: t('nav_yearly'), sPP: songPP.year, aPP: artistPP.year, lPP: albumPP.year },
  ];
  /* Nine tables: three entities across weekly, monthly and yearly. This used to
     read period-first — one section per period, all three entities crammed
     inside it, songs and artists side by side in a two-column grid and albums
     stranded full-width underneath. The pills make entity the outer axis
     instead, so a panel is one entity. One table per period means the grid is
     gone with it.

     Inside each entity panel a second pill row narrows it again, to one period,
     exactly like All #1s: three stacked collapsed headers you had to open one
     by one is a worse way through than three pills, and each period is its own
     named record anyway ("Most Plays in a Single Week").

     Each entity builds its own row markup, so the table builder is per entity
     rather than one shared loop pretending three different shapes are one. */
  const ppBuild = {
    songs: function (cfg) {
      const top = Object.entries(cfg.sPP).sort(function (a, b) { return b[1].count - a[1].count; });
      return recTable(['#', t('rec_th_songs') + ' &middot; ' + t('rec_th_artist'), t('rec_th_plays'), cfg.unitLabel],
        top.map(function (e, i) { const d = e[1]; const n = songNames[e[0]] || {}; return '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(d.title || n.title || e[0].split('|||')[0]) + '</div><div class="rec-sub">' + esc(d.artist || n.artist || '') + '</div></td><td class="rec-count">' + d.count + '</td><td class="rec-meta">' + fmtPeriodKey(d.period, cfg.pt) + '</td>'; }),
        lim, null, null,
        { rowAttrs: function (i) { const d = top[i][1], n = songNames[top[i][0]] || {};
          return recRowAttrs(d.artist || n.artist || '', 'song', d.title || n.title || top[i][0].split('|||')[0]); } }
      );
    },
    artists: function (cfg) {
      const top = Object.entries(cfg.aPP).sort(function (a, b) { return b[1].count - a[1].count; });
      return recTable(['#', t('rec_th_artist'), t('rec_th_plays'), cfg.unitLabel],
        top.map(function (e, i) { return '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(e[0]) + '</div></td><td class="rec-count">' + e[1].count + '</td><td class="rec-meta">' + fmtPeriodKey(e[1].period, cfg.pt) + '</td>'; }),
        lim, null, null,
        { rowAttrs: function (i) { return recRowAttrs(top[i][0], 'artist', top[i][0]); } }
      );
    },
    albums: function (cfg) {
      const top = Object.entries(cfg.lPP).sort(function (a, b) { return b[1].count - a[1].count; });
      return recTable(['#', t('rec_th_albums') + ' &middot; ' + t('rec_th_artist'), t('rec_th_plays'), cfg.unitLabel],
        top.map(function (e, i) { const d = e[1]; const n = albumNames[e[0]] || {}; return '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(d.album || n.album || e[0].split('|||')[0]) + '</div><div class="rec-sub">' + esc(d.artist || n.artist || '') + '</div></td><td class="rec-count">' + d.count + '</td><td class="rec-meta">' + fmtPeriodKey(d.period, cfg.pt) + '</td>'; }),
        lim, null, null,
        { rowAttrs: function (i) { const d = top[i][1], n = albumNames[top[i][0]] || {};
          return recRowAttrs(d.artist || n.artist || '', 'album', d.album || n.album || top[i][0].split('|||')[0]); } }
      );
    }
  };
  const PP_REC_TYPES = [
    { key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs') },
    { key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists') },
    { key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums') }
  ];
  const ppPanels = PP_REC_TYPES.map(function (ent) {
    // One period pill row per entity panel, so each entity remembers its own
    // period — 'pp-songs' is a different stored choice from 'pp-albums'.
    const perScope = 'pp-' + ent.key;
    let html = '<div class="rec-per-tabs" data-rec-per-scope="' + esc(perScope) + '"'
      + ' role="tablist" aria-label="' + esc(t('rec_per_tabs_label')) + '">';
    for (const cfg of ptCfg) {
      html += '<button type="button" class="rec-per-tab" role="tab"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '">'
        + esc(cfg.short) + '</button>';
    }
    html += '</div>';
    for (const cfg of ptCfg) {
      /* The three panels repeat these same three titles across entities, so the
         collapse key has to be scoped twice over: data-rec-scope here is the
         entity *and* the period, and setupRecordSubsectionCollapse() reads the
         nearest one — this panel, not the .rec-ent-panel around it. */
      html += '<div class="rec-per-panel" role="tabpanel"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pt + '"'
        + ' data-rec-scope="' + esc(perScope + '-' + cfg.pt) + '" style="display:none">'
        + '<div class="rec-section"><div class="rec-section-title">'
        + t('rec_most_plays_single', { unit: cfg.unitLabel }) + '</div>'
        + ppBuild[ent.key](cfg) + '</div>'
        + '</div>';
    }
    return { key: ent.key, icon: ent.icon, label: ent.label, html: html };
  });
  document.getElementById('recPeakPlaysBody').innerHTML = recEntTabsHtml('pp', ppPanels);

  // ── Play Count Milestones ─────────────────────────────────────
  /* Milestones are a ladder of firsts, not a leaderboard: every row is a
     different tier, and what matters is when each was reached and how long it
     took. That is a story with dates, so it renders as a vertical timeline
     rather than a four-column table.

     It stays a real <table> underneath. The records search walks tbody rows,
     the entries-per-table limit tags them by index, and both would lose this
     section entirely if the markup became divs — so the timeline is built in
     CSS (.mil-timeline) over ordinary rows. The <thead> is display:none there:
     a timeline has no columns to sort, and display:none also takes the
     sortable headers out of the tab order instead of leaving them focusable
     but invisible. */
  // Round tiers get a heavier node — the ladder has 28 steps and they are not
  // all equally worth stopping at.
  const MIL_MAJOR = new Set([100, 500, 1000, 5000, 10000, 25000, 50000]);
  /* Rows render descending, biggest tier first. The ladders ascend, so ordering
     them that way would put the trivial tiers on top and — worse — hand the
     entries-per-table limit the highest milestones to hide. Reversed, the limit
     cuts from the bottom, which is what "top 25" should mean here. */

  /* Artwork. Queued, not fetched: loadImages() attaches an IntersectionObserver,
     so the covers in the two hidden panels cost nothing until their pill is
     picked and the panel gets a box. Each entity type needs a different lookup
     key, which is the only thing that varies. */
  const milImgQueue = [];
  function milQueueArt(imgId, imgType, key, name, sub) {
    if (imgType === 'artist') {
      milImgQueue.push({ imgId, imgType, name: name, prefKey: 'artist:' + name.toLowerCase() });
    } else if (imgType === 'album') {
      milImgQueue.push({
        imgId, imgType, name: name, album: name, artist: sub,
        prefKey: 'album:' + (sub || '').toLowerCase() + '|||' + name.toLowerCase()
      });
    } else {
      milImgQueue.push({
        imgId, imgType, name: name, title: name, artist: sub, album: (songNames[key] || {}).album || '',
        prefKey: 'song:' + (sub || '').toLowerCase() + '|||' + name.toLowerCase()
      });
    }
  }

  /* One timeline. `ms` is the tier map, `first` the first-play-date map — the
     second is what the origin row at the foot of the spine is built from. */
  function milTimeline(cfg) {
    const nameFn = cfg.nameFn, subFn = cfg.subFn;

    /* Attributes the hero-artist tally reads off a timeline row. Milestone art is
       queued in JS (milQueueArt) rather than written into the markup, so there is
       no .img-src-btn here at build time to read from — see recRowRecord().
       Which field holds the artist flips with the type: on the artists timeline
       the name *is* the artist, on songs and albums it is the sub-line. */
    function milRowAttrs(key, nm, sub) {
      const artist = cfg.imgType === 'artist' ? nm : sub;
      if (!artist) return '';
      const prefKey = cfg.imgType === 'artist'
        ? 'artist:' + nm.toLowerCase()
        : cfg.imgType + ':' + (sub || '').toLowerCase() + '|||' + nm.toLowerCase();
      return ' data-rec-artist="' + esc(artist) + '" data-rec-type="' + esc(cfg.imgType) + '"'
        + ' data-rec-name="' + esc(nm) + '" data-rec-prefkey="' + esc(prefKey) + '"';
    }

    // Shared by the tier rows and the origin row so the two can't drift apart.
    function artCell(imgId, imgType, key, name, sub) {
      milQueueArt(imgId, imgType, key, name, sub);
      // .thumb-cell keeps the placeholder initials out of the records search —
      // otherwise every row would match on its own initials.
      return '<td class="thumb-cell mil-art">'
        + '<div class="mil-art-box' + (imgType === 'artist' ? ' mil-art-circle' : '') + '" id="' + imgId + '">'
        + '<div class="thumb-initials">' + esc(initials(name)) + '</div></div></td>';
    }

    /* Earliest entry per tier, in one pass over the map. The tiers come from the
       data rather than from a fixed ladder, because the song ladder is every 25
       plays with no ceiling — there is no array to iterate. Inverting the scan
       also drops the cost from O(tiers × entries) to O(milestones actually
       reached), which matters once a heavily played song contributes hundreds of
       tiers on its own. */
    const best = {};
    for (const k in cfg.ms) {
      const tiers = cfg.ms[k];
      for (const m in tiers) {
        const e = tiers[m];
        if (!best[m] || e.date < best[m].ms.date) best[m] = { key: k, ms: e };
      }
    }
    const rows = Object.keys(best).map(Number).sort(function (a, b) { return b - a; }).map(function (m) {
      const key = best[m].key, ms = best[m].ms;
      const nm = nameFn(key), sub = subFn ? subFn(key) : '';
      return '<tr class="mil-row' + (MIL_MAJOR.has(m) ? ' mil-row-major' : '') + '"' + milRowAttrs(key, nm, sub) + '>'
        + '<td class="mil-tier"><span class="milestone-number">' + m.toLocaleString() + '</span>'
        + '<span class="mil-tier-unit">' + t('mil_th_plays') + '</span></td>'
        + artCell('mil-img-' + cfg.idPrefix + '-' + m, cfg.imgType, key, nm, sub)
        + '<td class="mil-who"><div class="rec-name">' + esc(nm) + '</div>'
        + (sub ? '<div class="rec-sub">' + esc(sub) + '</div>' : '') + '</td>'
        + '<td class="mil-when">' + fmtDate(ms.date) + '</td>'
        // Same elapsed treatment the Fastest ladder uses, so a gap never reads
        // two different ways in two sections. This replaces a bare "Day 1" for
        // anything under 24 hours, which said less than the hours do.
        + '<td class="mil-after" data-sort="' + ms.elapsed + '">' + t('rec_milestone_after', { time: fmtElapsed(ms.elapsed) }) + '</td>'
        + '</tr>';
    });

    /* The origin: the very first one you ever played. Without it the timeline
       has no beginning — the lowest tier is 10 plays, so whatever started the
       whole thing was invisible. It is not a milestone tier, so it is computed
       from the first-play map rather than added to MILESTONES, which would
       otherwise pollute the fastest-to-milestone and overview record too. */
    let originRow = '';
    {
      let bk = null, bv = null;
      for (const k in cfg.first) if (bv === null || cfg.first[k] < bv) { bv = cfg.first[k]; bk = k; }
      if (bk !== null) {
        const nm = nameFn(bk), sub = subFn ? subFn(bk) : '';
        originRow = '<tr class="mil-row mil-row-origin"' + milRowAttrs(bk, nm, sub) + '>'
          + '<td class="mil-tier"><span class="milestone-number">' + t('mil_origin_label') + '</span>'
          + '<span class="mil-tier-unit">' + t('mil_origin_unit') + '</span></td>'
          + artCell('mil-img-' + cfg.idPrefix + '-origin', cfg.imgType, bk, nm, sub)
          + '<td class="mil-who"><div class="rec-name">' + esc(nm) + '</div>'
          + (sub ? '<div class="rec-sub">' + esc(sub) + '</div>' : '') + '</td>'
          + '<td class="mil-when">' + fmtDate(bv) + '</td>'
          + '<td class="mil-after">' + t('mil_origin_note') + '</td>'
          + '</tr>';
      }
    }

    // An empty section says what the record needs, not just "no data" — the
    // album ladder in particular is empty for a reason worth naming. The origin
    // row counts as content: a library too small for the 10-play tier still has
    // a first play, and that is the whole story it has to tell.
    if (!rows.length && !originRow) return '<div class="rec-empty mil-empty">' + t(cfg.emptyKey) + '</div>';
    return '<table class="milestone-table mil-timeline"><thead><tr>'
      + '<th scope="col">' + t('mil_th_plays') + '</th>'
      + '<th scope="col"></th>'
      + '<th scope="col">' + t('mil_th_first_to_reach') + '</th>'
      + '<th scope="col">' + t('mil_th_date_reached') + '</th>'
      + '<th scope="col">' + t('mil_th_time_since') + '</th>'
      + '</tr></thead><tbody>' + rows.join('') + originRow + '</tbody></table>';
  }

  /* One panel per entity, one visible at a time — the same DOM-only pattern the
     New Charts pills use. All three are always built, so the global search can
     still reach every one of them. */
  /* Each panel states its own ladder, because the two are not the same and a
     reader comparing "first to 500" across pills would otherwise have no way to
     know songs are counting in 25s and artists in landmark steps. */
  const MIL_REC_TYPES = [
    {
      key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs'), title: recEntIco('songs') + ' ' + t('rec_songs_milestones'),
      sub: t('mil_ladder_songs', { n: SONG_MILESTONE_STEP }), empty: 'mil_no_data'
    },
    {
      key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists'), title: recEntIco('artists') + ' ' + t('rec_artists_milestones'),
      sub: t('mil_ladder_landmark'), empty: 'mil_no_data'
    },
    {
      key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums'), title: recEntIco('albums') + ' ' + t('rec_albums_milestones'),
      sub: t('mil_ladder_landmark'), empty: 'mil_no_data_albums'
    }
  ];
  /* Name lookups. The overview block further down declares its own songNm /
     albumNm consts, but those are `const` in this same function scope and are
     not initialised yet at this point — reading them here would be a temporal
     dead zone error. These read the same songNames / albumNames maps. */
  const milSongNm = function (k) { return (songNames[k] || {}).title || String(k).split('|||')[0]; };
  const milSongArt = function (k) { return (songNames[k] || {}).artist || ''; };
  const milAlbumNm = function (k) { return (albumNames[k] || {}).album || String(k).split('|||')[0]; };
  const milAlbumArt = function (k) { return (albumNames[k] || {}).artist || ''; };
  const MIL_BY_TYPE = {
    songs: function () {
      return milTimeline({
        ms: songMS, first: songFirst, nameFn: milSongNm, subFn: milSongArt,
        imgType: 'song', idPrefix: 'songs', emptyKey: 'mil_no_data'
      });
    },
    artists: function () {
      return milTimeline({
        ms: artistMS, first: artistFirst, nameFn: function (k) { return k; }, subFn: null,
        imgType: 'artist', idPrefix: 'artists', emptyKey: 'mil_no_data'
      });
    },
    albums: function () {
      return milTimeline({
        ms: albumMS, first: albumFirst, nameFn: milAlbumNm, subFn: milAlbumArt,
        imgType: 'album', idPrefix: 'albums', emptyKey: 'mil_no_data_albums'
      });
    }
  };

  let mh = '<div class="mil-tabs" id="milRecTypeTabs" role="tablist" aria-label="' + esc(t('mil_tabs_label')) + '">';
  for (const ty of MIL_REC_TYPES) {
    mh += '<button type="button" class="mil-tab" role="tab" data-mil-type="' + ty.key + '">'
      + '<span class="mil-tab-icon" aria-hidden="true">' + ty.icon + '</span>' + esc(ty.label) + '</button>';
  }
  mh += '</div>';
  for (const ty of MIL_REC_TYPES) {
    // data-rec-scope keeps each panel's collapse state to itself, the same way
    // the New Charts panels do.
    mh += '<div class="mil-panel" role="tabpanel" data-mil-type="' + ty.key + '"'
      + ' data-rec-scope="mil-' + ty.key + '" style="display:none">'
      + '<div class="rec-section"><div class="rec-section-title">' + ty.title + '</div>'
      + '<div class="rec-section-sub">' + esc(ty.sub) + '</div>'
      + MIL_BY_TYPE[ty.key]() + '</div></div>';
  }
  document.getElementById('recMilestonesBody').innerHTML = mh;
  // One observer pass per entity type, matching how the appearances and debuts
  // sections hand their mixed queues to loadImages().
  (async () => {
    await loadImages(milImgQueue.filter(function (x) { return x.imgType === 'song'; }), 'song');
    await loadImages(milImgQueue.filter(function (x) { return x.imgType === 'artist'; }), 'artist');
    await loadImages(milImgQueue.filter(function (x) { return x.imgType === 'album'; }), 'album');
  })();

  // ── Fastest to Milestone ──────────────────────────────────────
  /* One ladder per entity, and each rung its own record table. The three
     ladders are deliberately different: a song is the smallest unit here, so
     it earns the finest steps at the bottom, while an artist — who collects
     the plays of every song they made — starts higher but climbs much further,
     because a favourite artist outgrows any single song of theirs. Every tier
     below must exist in the map it reads, or the section would be silently
     empty: songs are stored every 25 plays (all of these are multiples of 50),
     artists and albums are stored on MILESTONE_SET.
     Tiers nobody has reached cost nothing — fastTierSection() returns '' for an
     empty rung — so the top of the artist ladder is left long on purpose and
     fills itself in as the library grows. */
  const FAST_TIERS = {
    songs: [50, 100, 150, 200, 250, 300, 350, 400, 450, 500, 750, 1000, 1500, 2000, 2500, 5000],
    artists: [100, 250, 500, 750, 1000, 1500, 2000, 2500, 3000, 3500, 4000, 4500, 5000, 6000, 7000, 7500, 8000, 9000, 10000, 11000, 12000, 13000, 14000, 15000, 20000, 25000, 50000],
    albums: [100, 250, 500, 1000, 2000, 5000]
  };
  /* Three entities, one pill row — the same shape (and the same styling) the
     Milestones section two above uses, because a flat list of every tier for
     every entity would run to twenty-odd collapsed headers. Each panel is
     built whether or not it is on screen, so the global search still reaches
     all three; only `display` moves. */
  const FAST_REC_TYPES = [
    {
      key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs'), ms: songMS, first: songFirst,
      unit: 'songs', type: 'song',
      title: function (m) { return recEntIco('songs') + ' ' + t('rec_songs_fastest_to', { n: m.toLocaleString() }); },
      head: t('rec_th_songs') + ' &middot; ' + t('rec_th_artist'),
      nm: function (k) { return (songNames[k] || {}).title || String(k).split('|||')[0]; },
      art: function (k) { return (songNames[k] || {}).artist || ''; }
    },
    {
      key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists'), ms: artistMS, first: artistFirst,
      unit: 'artists', type: 'artist',
      title: function (m) { return t('rec_fastest_to', { type: recEntIco('artists') + ' ' + t('rec_th_artists'), n: m.toLocaleString(), s: 's' }); },
      head: t('rec_th_artist'),
      nm: function (k) { return k; },
      art: function (k) { return k; }
    },
    {
      key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums'), ms: albumMS, first: albumFirst,
      unit: 'albums', type: 'album',
      title: function (m) { return t('rec_fastest_to', { type: recEntIco('albums') + ' ' + t('rec_th_albums'), n: m.toLocaleString(), s: 's' }); },
      head: t('rec_th_albums') + ' &middot; ' + t('rec_th_artist'),
      nm: function (k) { return (albumNames[k] || {}).album || String(k).split('|||')[0]; },
      art: function (k) { return (albumNames[k] || {}).artist || ''; }
    }
  ];

  /* One tier of one entity: everyone who ever reached `m` plays, ranked by how
     few days it took them. First Play is carried alongside Date Reached so the
     day count can be checked rather than taken on trust.

     `collapsed` starts every rung but the first one shut. Sixteen open tables
     of twenty-five rows is not a record anyone reads, and the ladder is meant
     to be climbed a rung at a time. It is only a default — once a rung is
     opened or closed by hand that choice is stored and wins. */
  function fastTierSection(cfg, m, collapsed) {
    /* Ranked on the exact gap, not the rounded day count — that is the whole
       ordering at the low tiers, where almost every visible row shares a day
       count and the sort had nothing left to compare. */
    const entries = Object.entries(cfg.ms)
      .filter(function (e) { return e[1][m]; })
      .sort(function (a, b) { return a[1][m].elapsed - b[1][m].elapsed; });
    if (!entries.length) return '';
    const plays = m.toLocaleString();
    const sub = entries.length === 1
      ? t('rec_has_reached', { n: 1, type: tUnit(cfg.unit, 1), plays: plays })
      : t('rec_have_reached', { n: entries.length, type: tUnit(cfg.unit, entries.length), plays: plays });
    let h = '<div class="rec-section"' + (collapsed ? ' data-rec-default-collapsed="1"' : '')
      + '><div class="rec-section-title">' + cfg.title(m) + '</div>';
    h += '<div class="rec-section-sub">' + sub + '</div>';
    h += recTable(['#', cfg.head, t('rec_th_time_taken'), t('rec_th_first_play'), t('rec_th_date_reached')],
      entries.map(function (e, i) {
        const ms = e[1][m], fp = cfg.first[e[0]], sb = cfg.type === 'artist' ? '' : cfg.art(e[0]);
        return '<td class="rec-rank">' + (i + 1) + '</td>'
          + '<td><div class="rec-name">' + esc(cfg.nm(e[0])) + '</div>'
          + (sb ? '<div class="rec-sub">' + esc(sb) + '</div>' : '') + '</td>'
          /* recCellSortValue() would read "1d 4h" as the number 14 and "7h" as
             7, so re-sorting this column by hand would scramble it. data-sort
             hands it the raw gap instead — the same value the section ranks on. */
          + '<td class="rec-count" data-sort="' + ms.elapsed + '">' + fmtElapsed(ms.elapsed) + '</td>'
          + '<td class="rec-meta">' + (fp ? fmtDate(fp) : '—') + '</td>'
          + '<td class="rec-meta">' + fmtDate(ms.date) + '</td>';
      }),
      lim, null, null,
      { rowAttrs: function (i) { return recRowAttrs(cfg.art(entries[i][0]), cfg.type, cfg.nm(entries[i][0])); } }
    );
    return h + '</div>';
  }

  let fh = '<div class="fast-tabs" id="fastRecTypeTabs" role="tablist" aria-label="' + esc(t('fast_tabs_label')) + '">';
  for (const ty of FAST_REC_TYPES) {
    fh += '<button type="button" class="fast-tab" role="tab" data-fast-type="' + ty.key + '">'
      + '<span class="fast-tab-icon" aria-hidden="true">' + ty.icon + '</span>' + esc(ty.label) + '</button>';
  }
  fh += '</div>';
  for (const ty of FAST_REC_TYPES) {
    // data-rec-scope keeps each panel's per-tier collapse state to itself, the
    // same way the Milestones and New Charts panels do.
    // The first rung that actually has anybody on it stays open; the rest wait
    // to be asked for. Empty tiers return '' and so never claim that slot.
    let body = '';
    for (const m of FAST_TIERS[ty.key]) body += fastTierSection(ty, m, body !== '');
    fh += '<div class="fast-panel" role="tabpanel" data-fast-type="' + ty.key + '"'
      + ' data-rec-scope="fast-' + ty.key + '" style="display:none">'
      + (body || '<div class="rec-empty">' + t('rec_no_data') + '</div>')
      + '</div>';
  }
  document.getElementById('recFastestBody').innerHTML = fh;

  // ── Certifications Leaderboard ────────────────────────────────
  const certW = Object.entries(artistCertCounts).map(function (e) {
    const c = e[1];
    return {
      art: e[0], sg: c.sg, sp: c.sp, sd: c.sd, ag: c.ag, ap: c.ap, ad: c.ad,
      songs: c.songs, albums: c.albums,
      score: c.sd * 4 + c.sp * 2 + c.sg + c.ad * 4 + c.ap * 2 + c.ag
    };
  }).filter(function (e) { return e.score > 0; }).sort(function (a, b) { return b.score - a.score; });
  /* Each row opens onto that artist's whole certification ledger. The rows are
     handed over as source items, not markup: a heavy catalogue holds well over
     a hundred certifications, and only the ledgers actually opened are ever
     built (see buildCertLedger). */
  _certLedgers = certW.map(function (e) { return { artist: e.art, songs: e.songs, albums: e.albums }; });
  let ch = '<div class="rec-section"><div class="rec-section-title">' + t('rec_artists_with_certs') + '</div>';
  ch += '<div class="rec-section-sub">' + t('rec_certs_thresholds', { sg: CERT.song.gold, sp: CERT.song.plat, sd: CERT.song.diamond, ag: CERT.album.gold, ap: CERT.album.plat, ad: CERT.album.diamond }) + '</div>';
  if (!certW.length) {
    ch += '<div class="rec-empty">' + t('rec_no_certifications') + '</div>';
  } else {
    const certTblId = 'rec-certs-tbl';
    // Same glyph family as every other expandable table in Records: ▶▶ closed,
    // ▼▼ open.
    ch += recTable(['#', t('rec_th_artist'), t('rec_th_song_cert'), t('rec_th_album_cert'),
        '<button class="rec-expand-all-btn" onclick="event.stopPropagation();toggleAllCertLedgers(\'' + certTblId + '\',this)" title="' + esc(t('rec_expand_all')) + '">▶▶</button>'],
      certW.map(function (e, i) {
        const sc2 = [e.sd ? e.sd + '× 💎' : '', e.sp ? e.sp + '× 💿' : '', e.sg ? e.sg + '× 🪙' : ''].filter(Boolean).join(' ') || '—';
        const ac2 = [e.ad ? e.ad + '× 💎' : '', e.ap ? e.ap + '× 💿' : '', e.ag ? e.ag + '× 🪙' : ''].filter(Boolean).join(' ') || '—';
        const ledgerId = 'rec-cert-ledger-' + i;
        return '<td class="rec-rank">' + (i + 1) + '</td>'
          // The name opens the artist modal. It stays a plain-looking name — the
          // underline only appears on hover — so the column still reads as a list.
          + '<td><div class="rec-name"><a href="javascript:void(0)" class="rec-artist-link" onclick="event.stopPropagation();openArtistModal(' + esc(JSON.stringify(e.art)) + ')">' + esc(e.art) + '</a></div></td>'
          + '<td class="rec-meta" style="white-space:nowrap">' + sc2 + '</td><td class="rec-meta" style="white-space:nowrap">' + ac2 + '</td>'
          + '<td class="rec-run-toggle-cell"><button class="rec-run-toggle-btn" title="' + esc(t('certd_open_ledger')) + '" onclick="event.stopPropagation();toggleCertLedger(this,\'' + ledgerId + '\',' + i + ')">▶</button></td>';
      }),
      lim,
      certW.map(function (e, i) {
        return { id: 'rec-cert-ledger-' + i, html: '<div class="certd" id="certd-' + i + '"></div>' };
      }),
      certTblId,
      { rowAttrs: function (i) { return recRowAttrs(certW[i].art, 'artist', certW[i].art); } }
    );
  }
  ch += '</div>';
  document.getElementById('recCertsBody').innerHTML = ch;

  // ── Certifications Wall ───────────────────────────────────────
  /* Built from the same certification history the ledger reads, so a plaque
     and the ledger line behind it can never disagree about a date. */
  const wallItems = [];
  const wallPush = function (it, cfg, type) {
    /* One plaque per certification, not one per record. An award is not
       replaced by the next one up: a record that reached Diamond earned its
       Gold and its Platinum on the way, each on its own day, and it still
       holds both — which is exactly how the ledger has always listed them.
       Diamond then repeats, so every further multiple of the threshold is
       another plaque again (Double, Triple, 4×…). */
    it.events.forEach(function (ev, i) {
      wallItems.push({
        title: it.title, artist: it.artist, image: null, type: type,
        // The event history says 'plat'; the wall's classes and labels say
        // 'platinum'. Everything downstream reads the wall's spelling.
        tier: ev.tier === 'plat' ? 'platinum' : ev.tier,
        mult: ev.mult || 1,
        date: ev.date.toISOString().split('T')[0],
        /* The highest plaque a record holds, which is the last one it earned.
           The hero-artist tally counts this one alone — five plaques for one
           album are five awards but still one certified record, and the reel
           would otherwise show the same album five times over. */
        top: i === it.events.length - 1,
        _plays: it.plays, _album: type === 'song' ? it.album : it.title
      });
    });
  };
  for (const it of Object.values(certSongItems)) wallPush(it, CERT.song, 'song');
  for (const it of Object.values(certAlbumItems)) wallPush(it, CERT.album, 'album');
  const _wTierOrd = { diamond: 0, platinum: 1, gold: 2 };
  // Rarest first, and within Diamond the highest multiple leads.
  wallItems.sort((a, b) => (_wTierOrd[a.tier] - _wTierOrd[b.tier]) || (b.mult - a.mult) || (b._plays - a._plays));
  // renderCertifications() ends in renderCertWallCards(), which now loads its
  // own artwork — a call here would queue the same ids a second time.
  renderCertifications(wallItems);

  // ── New Charts Records ────────────────────────────────────────
  // Ten records × three entities × two period types is twenty tables, and they
  // used to render as one scroll. The pills below make it one entity and one
  // period at a time: a type row (Songs/Artists/Albums) and, under it, a
  // Weekly/Monthly row. Both are exclusive — picking Songs hides Artists and
  // Albums entirely, picking Weekly hides every monthly table.
  const NC_REC_TYPES = [
    { key: 'songs', icon: recEntIco('songs'), label: t('rec_th_songs') },
    { key: 'artists', icon: recEntIco('artists'), label: t('rec_th_artists') },
    { key: 'albums', icon: recEntIco('albums'), label: t('rec_th_albums') },
  ];
  const NC_REC_PERIODS = [
    { key: 'week', label: t('rec_weekly_label') },
    { key: 'month', label: t('rec_monthly_label') },
  ];
  // Artwork requested by the record builders below, flushed once the panels are
  // in the DOM. loadImages() observes intersection, so the art inside a panel
  // that is currently hidden behind a pill only loads when that pill is picked.
  const ncImgQueue = [];

  // One record = one collapsible .rec-section. `sub` is the optional prose line
  // under the title; the period no longer belongs there now that a panel only
  // ever holds one period.
  function ncSec(title, body, sub) {
    return '<div class="rec-section"><div class="rec-section-title">' + title + '</div>'
      + (sub ? '<div class="rec-section-sub">' + sub + '</div>' : '')
      + body + '</div>';
  }
  // Period column header + the clickable period cell, both needed by nearly
  // every table below.
  const ncPeriodTh = pt => pt === 'week' ? t('rec_th_week') : t('rec_th_month');
  // `cls` is optional, for tables whose phone layout has to address this cell.
  const ncPeriodTd = (pt, pk, cls) => '<td class="rec-meta' + (cls ? ' ' + cls : '') + '"><a href="javascript:void(0)" class="rec-date-link" onclick="showNewChartRecPreview(\'' + pt + '\',\'' + esc(pk) + '\',this,event)">' + fmtPeriodKey(pk, pt) + '</a></td>';

  // ── 1. Biggest New Song Debut ─────────────────────────────────
  // The richest table in the section: cover art per row, a podium for the top
  // three, and (via CSS) a card layout on phones, because eight columns cannot
  // survive a 390px viewport.
  function ncRecSongDebut(pt) {
    const sorted = Object.entries(ncSongDebuts[pt]).sort((a, b) => b[1].plays - a[1].plays || a[1].rank - b[1].rank || a[1].period.localeCompare(b[1].period));
    const tableId = 'nc-sd-tbl-' + pt;
    // A podium is only worth it when there is still a table left under it —
    // both in the data and after the entries-per-table limit has had its say.
    const hasPodium = sorted.length >= 4 && lim >= 4;

    // Artwork is queued, not fetched: loadImages() runs after this HTML is in
    // the DOM. imgCache is keyed by track+source, so the top three appearing in
    // both the podium and the (hidden) table row cost one lookup, not two.
    function queueArt(sk, d, imgId) {
      const nm = songNames[sk] || {};
      ncImgQueue.push({
        imgId, name: d.title, title: d.title, artist: d.artist, album: nm.album || '',
        prefKey: 'song:' + (d.artist || '').toLowerCase() + '|||' + (d.title || '').toLowerCase()
      });
    }

    /* The podium carries the canonical top three, so those three rows are
       hidden from the table below and it starts at #4. That trade only holds
       while the table is in its canonical order — searching or re-sorting a
       column makes "the top three" a different set, so both paths stand the
       podium down and put the rows back (see applyRecSort() and the
       .nc-podium rules in style.css). */
    let podHtml = '';
    if (hasPodium) {
      podHtml = '<div class="nc-podium" data-nc-podium-for="' + tableId + '">';
      sorted.slice(0, 3).forEach(([sk, d], i) => {
        const imgId = 'nc-pod-img-' + pt + '-' + i;
        queueArt(sk, d, imgId);
        podHtml += '<div class="nc-podium-card nc-podium-' + (i + 1) + '">'
          + '<div class="nc-podium-medal">' + (i + 1) + '</div>'
          + '<div class="nc-podium-art" id="' + imgId + '"><div class="pak-mini-initials">' + esc(initials(d.title)) + '</div></div>'
          + '<div class="nc-podium-title">' + esc(d.title) + '</div>'
          + '<div class="nc-podium-artist">' + esc(d.artist) + '</div>'
          + '<div class="nc-podium-figure"><span class="nc-podium-num">' + (d.plays || 0).toLocaleString() + '</span>'
          + '<span class="nc-podium-unit">' + t('rec_th_plays') + ' @ #' + d.rank + '</span></div>'
          + '<div class="nc-podium-meta">'
          + '<span class="nc-podium-total">' + (songCP[sk] || 0).toLocaleString() + ' ' + t('th_total_plays') + '</span>'
          + '<a href="javascript:void(0)" class="rec-date-link" onclick="showNewChartRecPreview(\'' + pt + '\',\'' + esc(d.period) + '\',this,event)">' + fmtPeriodKey(d.period, pt) + '</a>'
          + '</div></div>';
      });
      podHtml += '</div>';
    }

    // "Debut Plays" is what the song did in its debut period; "Total Plays" is
    // its all-time count from songCP, so a huge debut that went nowhere is
    // visibly different from one that kept growing.
    const table = recTable(
      ['#', '', t('rec_th_songs'), t('rec_th_artist'), 'Debut ' + t('rec_th_plays'), t('th_total_plays'), 'Debut Rank', ncPeriodTh(pt)],
      sorted.map((e, i) => {
        const d = e[1];
        const imgId = 'nc-sd-img-' + pt + '-' + i;
        // Rows past the limit are never rendered, so nothing past it is queued.
        if (i < lim) queueArt(e[0], d, imgId);
        /* Every cell carries a class, because the phone layout has to place
           each one individually (see .nc-sd-table in style.css). data-unit
           holds the caption that cell's figure wears once it becomes a card,
           and both strings are built exactly as the podium builds them above —
           same source, so the two card shapes cannot drift apart.
           The art cell is tagged .thumb-cell so the records search skips it:
           otherwise the placeholder initials would match as if they were data. */
        return '<td class="rec-rank">' + (i + 1) + '</td>'
          + '<td class="thumb-cell"><div class="pak-mini-thumb" id="' + imgId + '"><div class="pak-mini-initials">' + esc(initials(d.title)) + '</div></div></td>'
          + '<td class="nc-sd-title"><div class="rec-name">' + esc(d.title) + '</div></td>'
          + '<td class="nc-sd-artist"><div class="rec-sub">' + esc(d.artist) + '</div></td>'
          + '<td class="rec-count nc-sd-debut" data-unit="' + esc(t('rec_th_plays') + ' @ #' + d.rank) + '">' + (d.plays || 0) + '</td>'
          + '<td class="rec-count nc-sd-total" data-unit="' + esc(t('th_total_plays')) + '">' + (songCP[e[0]] || 0) + '</td>'
          + '<td class="rec-count nc-sd-drank">#' + d.rank + '</td>'
          + ncPeriodTd(pt, d.period, 'nc-sd-week');
      }),
      lim, null, tableId,
      {
        tableCls: 'nc-sd-table' + (hasPodium ? ' nc-podium-on' : ''),
        rowCls: i => (hasPodium && i < 3 ? 'nc-podium-row' : ''),
        rowAttrs: i => recRowAttrs(sorted[i][1].artist, 'song', sorted[i][1].title)
      }
    );

    return ncSec(recEntIco('songs') + ' ' + t('rec_th_songs') + ' &mdash; Biggest New Chart Debut', podHtml + table);
  }

  // ── 2. Biggest New Artist Debut ────────────────────────────────
  function ncRecArtistDebut(pt) {
    const sorted = Object.entries(ncArtistDebuts[pt]).sort((a, b) => b[1].plays - a[1].plays || a[1].rank - b[1].rank || a[1].period.localeCompare(b[1].period));
    return ncSec(recEntIco('artists') + ' ' + t('rec_th_artists') + ' &mdash; Biggest New Chart Debut',
      recTable(['#', t('rec_th_artist'), t('rec_th_plays'), 'Debut Rank', ncPeriodTh(pt)],
        sorted.map((e, i) => { const d = e[1]; return '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(e[0]) + '</div></td><td class="rec-count">' + (d.plays || 0) + '</td><td class="rec-count">#' + d.rank + '</td>' + ncPeriodTd(pt, d.period); }), lim, null, null,
        { rowAttrs: i => recRowAttrs(sorted[i][0], 'artist', sorted[i][0]) }));
  }

  // ── 3. Biggest New Album Debut ─────────────────────────────────
  function ncRecAlbumDebut(pt) {
    const sorted = Object.entries(ncAlbumDebuts[pt]).sort((a, b) => b[1].plays - a[1].plays || a[1].rank - b[1].rank || a[1].period.localeCompare(b[1].period));
    return ncSec(recEntIco('albums') + ' ' + t('rec_th_albums') + ' &mdash; Biggest New Chart Debut',
      recTable(['#', t('rec_th_albums'), t('rec_th_artist'), t('rec_th_plays'), 'Debut Rank', ncPeriodTh(pt)],
        sorted.map((e, i) => { const d = e[1]; return '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(d.album) + '</div></td><td><div class="rec-sub">' + esc(d.artist) + '</div></td><td class="rec-count">' + (d.plays || 0) + '</td><td class="rec-count">#' + d.rank + '</td>' + ncPeriodTd(pt, d.period); }), lim, null, null,
        { rowAttrs: i => recRowAttrs(sorted[i][1].artist, 'album', sorted[i][1].album) }));
  }

  // ── 4 & 5. Busiest Discovery Period ────────────────────────────
  // Deliberately the one pair that is *not* capped to the chart size: it answers
  // "how much did I discover", not "who charted", and capping it would flatten
  // almost every period to the chart size. The subtitle says so.
  function ncRecBusiest(pt, kind) {
    const map = kind === 'songs' ? rawNewCountPerPeriod[pt].songs : rawNewCountPerPeriod[pt].artists;
    const sorted = Object.entries(map).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    // Named for an entity like the debut tables above it, so it takes the same
    // glyph rather than a topic emoji — inside the Songs panel, one section
    // headed with a note and the next with 🔢 read as two different systems.
    return ncSec(recEntIco(kind === 'songs' ? 'songs' : 'artists') + ' ' + (kind === 'songs' ? t('rec_th_songs') : t('rec_th_artists')) + ' &mdash; Busiest Discovery Period',
      recTable(['#', ncPeriodTh(pt), kind === 'songs' ? 'New Songs' : 'New Artists'],
        sorted.map((e, i) => '<td class="rec-rank">' + (i + 1) + '</td>' + ncPeriodTd(pt, e[0]) + '<td class="rec-count">' + e[1] + '</td>'), lim),
      'Counts every ' + (kind === 'songs' ? 'song' : 'artist') + ' heard for the first time, including the ones that finished below the chart cut-off.');
  }

  // ── 6. Artist with Most Songs on One New Chart ─────────────────
  function ncRecMostSongsOneChart(pt) {
    const best = {};
    for (const [pk, artists] of Object.entries(ncNewSongsByArtistPerPeriod[pt])) {
      for (const [artist, count] of Object.entries(artists)) {
        if (!best[artist] || count > best[artist].count || (count === best[artist].count && pk < best[artist].period)) best[artist] = { count, period: pk };
      }
    }
    const sorted = Object.entries(best).sort((a, b) => b[1].count - a[1].count || a[1].period.localeCompare(b[1].period));
    return ncSec(recEntIco('songs') + ' Most Songs on a Single New Chart (by Artist)',
      recTable(['#', t('rec_th_artist'), 'New Songs', ncPeriodTh(pt)],
        sorted.map((e, i) => '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(e[0]) + '</div></td><td class="rec-count">' + e[1].count + '</td>' + ncPeriodTd(pt, e[1].period)), lim, null, null,
        { rowAttrs: i => recRowAttrs(sorted[i][0], 'artist', sorted[i][0]) }));
  }

  // ── 7. Most New Song Debuts All-Time by Artist ─────────────────
  function ncRecMostDebutsAllTime(pt) {
    const sorted = Object.entries(ncNewSongDebutsByArtist[pt]).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    return ncSec('📈 Most New Song Debuts (All-Time, by Artist)',
      recTable(['#', t('rec_th_artist'), 'Total Debut Appearances'],
        sorted.map((e, i) => '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(e[0]) + '</div></td><td class="rec-count">' + e[1] + '</td>'), lim, null, null,
        { rowAttrs: i => recRowAttrs(sorted[i][0], 'artist', sorted[i][0]) }));
  }

  // ── 8. Longest Consecutive Debut Streak by Artist ─────────────
  function ncRecDebutStreak(pt) {
    const sorted = Object.entries(artistConsecNewDebuts[pt]).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    return ncSec('🔁 Longest Consecutive Debut Streak (by Artist)',
      recTable(['#', t('rec_th_artist'), 'Consecutive ' + (pt === 'week' ? 'Weeks' : 'Months')],
        sorted.map((e, i) => '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(e[0]) + '</div></td><td class="rec-count">' + e[1] + ' ' + tUnit(pt === 'week' ? 'weeks_full' : 'months', e[1]) + '</td>'), lim, null, null,
        { rowAttrs: i => recRowAttrs(sorted[i][0], 'artist', sorted[i][0]) }));
  }

  // ── 9. New Song → #1 Fastest ──────────────────────────────────
  function ncRecNewTo1(pt) {
    const sorted = Object.entries(songNewTo1[pt]).sort((a, b) => a[1].periods - b[1].periods || a[1].debutPeriod.localeCompare(b[1].debutPeriod) || b[1].debutPlays - a[1].debutPlays);
    const colP = pt === 'week' ? 'Weeks to #1' : 'Months to #1';
    return ncSec('⚡ New Song &rarr; #1 Fastest',
      recTable(['#', t('rec_th_songs'), t('rec_th_artist'), colP, 'Debut', '#1 Achieved'],
        sorted.map((e, i) => { const d = e[1]; const pStr = d.periods === 0 ? 'Debuted at #1' : d.periods + ' ' + tUnit(pt === 'week' ? 'weeks_full' : 'months', d.periods); return '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(d.title) + '</div></td><td><div class="rec-sub">' + esc(d.artist) + '</div></td><td class="rec-count">' + pStr + '</td>' + ncPeriodTd(pt, d.debutPeriod) + ncPeriodTd(pt, d.no1Period); }), lim, null, null,
        { rowAttrs: i => recRowAttrs(sorted[i][1].artist, 'song', sorted[i][1].title) }));
  }

  // ── 10. New Album with Most Tracks Also Debuting ───────────────
  function ncRecAlbumTracks(pt) {
    const debMap = ncAlbumDebuts[pt];
    const combined = Object.entries(ncAlbumNewTrackCount[pt]).filter(e => e[1] > 0).map(([ak, cnt]) => {
      const deb = debMap[ak] || {};
      return { ak, cnt, album: deb.album || ak.split('|||')[0], artist: deb.artist || '', plays: deb.plays || 0, period: deb.period || '', rank: deb.rank || 0 };
    });
    combined.sort((a, b) => b.cnt - a.cnt || b.plays - a.plays || a.period.localeCompare(b.period));
    return ncSec(recEntIco('albums') + ' New Album with Most Tracks Also Debuting',
      combined.length
        ? recTable(['#', t('rec_th_albums'), t('rec_th_artist'), 'Tracks Debuting', t('rec_th_plays'), ncPeriodTh(pt)],
          combined.map((e, i) => '<td class="rec-rank">' + (i + 1) + '</td><td><div class="rec-name">' + esc(e.album) + '</div></td><td><div class="rec-sub">' + esc(e.artist) + '</div></td><td class="rec-count">' + e.cnt + '</td><td class="rec-count">' + e.plays + '</td>' + ncPeriodTd(pt, e.period)), lim, null, null,
          { rowAttrs: i => recRowAttrs(combined[i].artist, 'album', combined[i].album) })
        : '<div class="rec-empty">' + t('rec_no_data') + '</div>');
  }

  // Which records belong to which pill. Grouped by the entity the table ranks —
  // that is what a reader sees in the rows — so the artist leaderboards built
  // off the New Songs chart (6, 7, 8) live under Artists, not Songs.
  const NC_REC_BY_TYPE = {
    songs: [ncRecSongDebut, pt => ncRecBusiest(pt, 'songs'), ncRecNewTo1],
    artists: [ncRecArtistDebut, pt => ncRecBusiest(pt, 'artists'), ncRecMostSongsOneChart, ncRecMostDebutsAllTime, ncRecDebutStreak],
    albums: [ncRecAlbumDebut, ncRecAlbumTracks],
  };

  let nch = '<div class="nc-rec-tabs" id="ncRecTypeTabs" role="tablist" aria-label="New Charts record type">';
  for (const ty of NC_REC_TYPES) {
    nch += '<button type="button" class="nc-rec-tab" role="tab" data-nc-type="' + ty.key + '">'
      + '<span class="nc-rec-tab-icon" aria-hidden="true">' + ty.icon + '</span>' + ty.label + '</button>';
  }
  nch += '</div><div class="nc-rec-subtabs" id="ncRecPeriodTabs" role="tablist" aria-label="Chart period">';
  for (const p of NC_REC_PERIODS) {
    nch += '<button type="button" class="nc-rec-subtab" role="tab" data-nc-period="' + p.key + '">' + p.label + '</button>';
  }
  nch += '</div>';
  for (const ty of NC_REC_TYPES) {
    for (const p of NC_REC_PERIODS) {
      // data-rec-scope keeps each panel's inner collapse state to itself —
      // without it the weekly and monthly copies of a record share a key.
      nch += '<div class="nc-rec-panel" role="tabpanel" data-nc-type="' + ty.key + '" data-nc-period="' + p.key + '"'
        + ' data-rec-scope="nc-' + ty.key + '-' + p.key + '" style="display:none">'
        + NC_REC_BY_TYPE[ty.key].map(fn => fn(p.key)).join('')
        + '</div>';
    }
  }

  document.getElementById('recNewChartsBody').innerHTML = nch;
  loadImages(ncImgQueue, 'song');

  // ── Streak Records ────────────────────────────────────────────
  /* Three entity pills now, each with its own period row underneath — the
     same two-level shape Most Plays and All #1s wear. A listening streak is
     the same record whichever calendar unit it is counted in, so days, months
     and years are three periods of one record rather than three records; the
     fourth pill holds the other kind of run entirely, plays back-to-back in
     the log with nothing in between.

     Albums rank here for the first time. Their numbers read quieter than the
     same artist's on purpose: only album-tagged plays can feed them. */
  const STREAK_ENTS = [
    { key: 'songs', kind: 'song', icon: recEntIco('songs'), label: t('rec_th_songs') },
    { key: 'artists', kind: 'artist', icon: recEntIco('artists'), label: t('rec_th_artists') },
    { key: 'albums', kind: 'album', icon: recEntIco('albums'), label: t('rec_th_albums') },
  ];
  /* `runs` is the odd one out — it ranks plays, not calendar units — so it
     carries a date column and its own per-entity blurb, and its rows are
     counted with a × rather than a unit word. */
  const STREAK_PERIODS = [
    { pd: 'days', short: t('nav_daily'), title: t('rec_longest_streak_daily'), th: t('rec_th_consec_days'), unit: 'days' },
    // 'weeks_full' rather than 'weeks': the short form ("wks") is for chart
    // cells, and this column reads as prose.
    { pd: 'weeks', short: t('nav_weekly'), title: t('rec_longest_streak_weekly'), th: t('rec_th_consec_weeks'), unit: 'weeks_full' },
    { pd: 'months', short: t('nav_monthly'), title: t('rec_longest_streak_monthly'), th: t('rec_th_consec_months'), unit: 'months' },
    { pd: 'years', short: t('nav_yearly'), title: t('rec_longest_streak_yearly'), th: t('rec_th_consec_years'), unit: 'years' },
    { pd: 'runs', short: t('rec_per_runs'), title: t('rec_repeat_runs'), th: t('rec_th_consec_plays') },
  ];
  /* Names for a bare key. The songNm/albumNm helpers the overview uses are
     declared further down this function, so these can't lean on them. */
  const strName = {
    song: function (k) { const n = songNames[k] || {}; return { name: n.title || String(k).split('|||')[0], sub: n.artist || '', artist: n.artist || '', type: 'song' }; },
    artist: function (k) { return { name: k, sub: '', artist: k, type: 'artist' }; },
    album: function (k) { const n = albumNames[k] || {}; return { name: n.album || String(k).split('|||')[0], sub: n.artist || '', artist: n.artist || '', type: 'album' }; },
  };
  const strPanels = STREAK_ENTS.map(function (ent) {
    // One period row per entity panel, so each remembers its own choice —
    // 'streaks-songs' is a different stored pill from 'streaks-albums'.
    const perScope = 'streaks-' + ent.key;
    // Artists are their own credit; everything else carries one underneath.
    const nameTh = ent.kind === 'artist' ? ent.label : ent.label + ' &middot; ' + t('rec_th_artist');
    let html = '<div class="rec-per-tabs" data-rec-per-scope="' + esc(perScope) + '"'
      + ' role="tablist" aria-label="' + esc(t('rec_per_tabs_label')) + '">';
    for (const cfg of STREAK_PERIODS) {
      html += '<button type="button" class="rec-per-tab" role="tab"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pd + '">'
        + esc(cfg.short) + '</button>';
    }
    html += '</div>';
    for (const cfg of STREAK_PERIODS) {
      const isRuns = cfg.pd === 'runs';
      // Years carry an extra column: the leanest year of the run, which is also
      // what breaks their ties. See STREAK_CMP for why they need one.
      const hasDepth = cfg.pd === 'years';
      const src = isRuns ? bestRuns[ent.kind] : streaks[ent.kind][cfg.pd];
      // Longest first, then each ladder's own tiebreak (STREAK_CMP); runs rank
      // on their own figure entirely and break ties on the most recent.
      const entries = Object.entries(src).sort(isRuns
        ? function (a, b) { return b[1].count - a[1].count || b[1].date - a[1].date; }
        : streakCmp(cfg.pd));
      /* Double-scoped collapse key, the same way the Most Plays panels do it:
         these four titles repeat across all three entities, so the key has to
         carry the entity *and* the period or they would share one state. */
      html += '<div class="rec-per-panel" role="tabpanel"'
        + ' data-rec-per-scope="' + esc(perScope) + '" data-rec-per="' + cfg.pd + '"'
        + ' data-rec-scope="' + esc(perScope + '-' + cfg.pd) + '" style="display:none">'
        + '<div class="rec-section"><div class="rec-section-title">'
        + ent.icon + ' ' + ent.label + ' &mdash; ' + cfg.title + '</div>'
        + '<div class="rec-section-sub">'
        + (isRuns ? t('rec_repeat_runs_sub_' + ent.kind) : t('rec_streak_sub_' + cfg.pd)) + '</div>';
      if (!entries.length) {
        html += '<div class="rec-empty">' + t(isRuns ? 'rec_no_repeat_runs' : 'rec_no_data') + '</div>';
      } else {
        /* Streaks say when they happened; runs already carry the date their
           run peaked on, in a column of their own. "From"/"To" rather than
           "Started"/"Ended" because the top of these tables is often a run
           that is still going — nothing has ended. */
        const headers = ['#', nameTh, cfg.th];
        if (isRuns) headers.push(t('rec_th_date'));
        else {
          if (hasDepth) headers.push(t('rec_th_streak_depth'));
          headers.push(t('rec_th_streak_from'), t('rec_th_streak_to'));
        }
        html += recTable(headers,
          entries.map(function (e, i) {
            const n = strName[ent.kind](e[0]);
            const val = isRuns ? e[1].count + '&times;' : e[1].len + ' ' + tUnit(cfg.unit, e[1].len);
            let row = '<td class="rec-rank">' + (i + 1) + '</td>'
              + '<td><div class="rec-name">' + esc(n.name) + '</div>'
              + (n.sub ? '<div class="rec-sub">' + esc(n.sub) + '</div>' : '') + '</td>'
              + '<td class="rec-count">' + val + '</td>';
            if (isRuns) row += '<td class="rec-meta">' + (e[1].date ? fmt(e[1].date) : '') + '</td>';
            else {
              /* Quieter than the length beside it and louder than the dates:
                 it is the figure the rows are ordered by, so it has to be
                 read, but the years are still the headline of the record. */
              if (hasDepth) row += '<td class="rec-depth">' + tCount('plays', e[1].depth) + '</td>';
              row += '<td class="rec-meta">' + esc(fmtStreakBound(cfg.pd, e[1].start)) + '</td>'
                + '<td class="rec-meta">' + esc(fmtStreakBound(cfg.pd, e[1].end)) + '</td>';
            }
            return row;
          }),
          lim, null, null,
          { rowAttrs: function (i) {
            const n = strName[ent.kind](entries[i][0]);
            return recRowAttrs(n.artist, n.type, n.name);
          } }
        );
      }
      // Closes .rec-section, then .rec-per-panel — two opened, two closed.
      html += '</div></div>';
    }
    return { key: ent.key, icon: ent.icon, label: ent.label, html: html };
  });
  document.getElementById('recStreaksBody').innerHTML = recEntTabsHtml('streaks', strPanels);

  /* ── Overview highlights ────────────────────────────────────────────
     One headline record per section, per chart type, for the landing
     screen's Songs / Artists / Albums toggle. Every source map below is
     already built and in scope by this point, so this is a single O(n)
     pass per map with no re-derivation.

     Not every record exists for every type: albums have no play-count
     milestones and no fastest-to-milestone, because those are only tracked
     per artist and per song. Those combinations are simply left unset and the
     overview renders them as empty cards. */
  const recHi = {};
  /* `artist` is separate from `sub` on purpose. `sub` is whatever reads best
     under the name — usually the artist, but sometimes a date ("8 Jul 2026")
     — while `artist` is only ever the credited artist, because the overview
     cards look artwork up by title+artist and a date would poison the query.
     Artists' own cards need no artist: their name is the query.

     `slot` names which of a section's records this is — one card on the
     overview board. Chart-period sections use 'week' | 'month' | 'year';
     sections whose record is a lifetime total (milestones, fastest-to,
     certifications) use 'all'; Streaks names its ladder outright
     ('runs' | 'days' | 'weeks' | 'months' | 'years'), because a back-to-back
     run and a daily streak are two different records rather than two periods
     of one. REC_OV_SLOTS decides which pill each slot appears under. */
  function hi(sectionId, slot, type, label, value, name, sub, artist) {
    if (!value) return;
    if (!recHi[sectionId]) recHi[sectionId] = {};
    if (!recHi[sectionId][slot]) recHi[sectionId][slot] = {};
    recHi[sectionId][slot][type] = { label: label, value: value, name: name || '', sub: sub || '', artist: artist || '' };
  }
  // The three chart periods every splittable card is built for, the unit word
  // each one counts in, and the label lookup. Weekly keeps the untranslated
  // base key so existing translations stay valid; monthly and yearly get their
  // own strings, and anything period-neutral (a PAK is a PAK) reuses the base.
  const OV_PERIODS = ['week', 'month', 'year'];
  const OV_UNIT = { week: 'weeks_full', month: 'months', year: 'years' };
  const ovL = function (base, pd) { return t(pd === 'week' ? base : base + '_' + pd); };
  // Single-pass "best entry" helpers — cheaper and clearer than sorting to take [0].
  function topNum(map) {
    let bk = null, bv = -Infinity;
    for (const k in map) if (map[k] > bv) { bv = map[k]; bk = k; }
    return bk === null ? null : [bk, bv];
  }
  function topBy(map, worseThan) {
    let best = null;
    for (const k in map) { const e = [k, map[k]]; if (!best || worseThan(best, e)) best = e; }
    return best;
  }
  const byCount = (best, e) => e[1].count > best[1].count;
  // Debuts rank by plays, then by chart position, then by earliest period.
  // Must return a real boolean, not a comparator number — topBy tests it for
  // truthiness, and a negative difference would read as "better".
  const byDebut = function (best, e) {
    const a = e[1], b = best[1];
    if ((a.plays || 0) !== (b.plays || 0)) return (a.plays || 0) > (b.plays || 0);
    if (a.rank !== b.rank) return a.rank < b.rank;
    return a.period.localeCompare(b.period) < 0;
  };
  const songNm = k => (songNames[k] || {}).title || String(k).split('|||')[0];
  const songArt = k => (songNames[k] || {}).artist || '';
  const albumNm = k => (albumNames[k] || {}).album || String(k).split('|||')[0];
  const albumArt = k => (albumNames[k] || {}).artist || '';

  // All #1s — most periods spent at the top spot
  for (const pd of OV_PERIODS) {
    const L = ovL('rec_ov_all_ones', pd), U = OV_UNIT[pd];
    const s = topBy(song1s[pd], byCount), a = topBy(artist1s[pd], byCount), l = topBy(album1s[pd], byCount);
    if (s) hi('recAllOnesSection', pd, 'songs', L, tCount(U, s[1].count), s[1].title, s[1].artist, s[1].artist);
    if (a) hi('recAllOnesSection', pd, 'artists', L, tCount(U, a[1].count), a[0]);
    if (l) hi('recAllOnesSection', pd, 'albums', L, tCount(U, l[1].count), l[1].album, l[1].artist, l[1].artist);
  }

  /* Perfect All Kill — a PAK is an artist event, but each one also crowns a
     song and an album, so all three types have a most-frequent entry. One card
     per period: a yearly PAK is a far rarer thing than a weekly one, which is
     exactly why the pills are worth having. The label stays period-neutral —
     "Most Perfect All Kills" is true of all three — and the value carries the
     unit. */
  for (const pd of OV_PERIODS) {
    if (!pakPeriods[pd].length) continue;
    const L = t('rec_ov_pak'), U = OV_UNIT[pd];
    /* Also remembers which artist each tallied song/album belongs to — the PAK
       rows only name the work, and the overview card needs the artist to look
       its artwork up. A PAK crowns one artist per period, so the artist
       recorded alongside a title is by definition that title's own. */
    const tally = function (field) {
      const m = {}, art = {};
      for (const pw of pakPeriods[pd]) { const v = pw[field]; if (v) { m[v] = (m[v] || 0) + 1; art[v] = art[v] || pw.artist; } }
      const top = topNum(m);
      return top ? [top[0], top[1], art[top[0]] || ''] : null;
    };
    const s = tally('song'), a = tally('artist'), l = tally('album');
    if (s) hi('recPAKSection', pd, 'songs', L, tCount(U, s[1]), s[0], '', s[2]);
    if (a) hi('recPAKSection', pd, 'artists', L, tCount(U, a[1]), a[0]);
    if (l) hi('recPAKSection', pd, 'albums', L, tCount(U, l[1]), l[0], '', l[2]);
  }

  // Most chart appearances — periods spent anywhere on the chart
  for (const pd of OV_PERIODS) {
    const L = ovL('rec_ov_appearances', pd), U = OV_UNIT[pd];
    const s = topNum(songApps[pd]), a = topNum(artistApps[pd]), l = topNum(albumApps[pd]);
    if (s) hi('recAppearancesSection', pd, 'songs', L, tCount(U, s[1]), songNm(s[0]), songArt(s[0]), songArt(s[0]));
    if (a) hi('recAppearancesSection', pd, 'artists', L, tCount(U, a[1]), a[0]);
    if (l) hi('recAppearancesSection', pd, 'albums', L, tCount(U, l[1]), albumNm(l[0]), albumArt(l[0]), albumArt(l[0]));
  }

  // Biggest debut, one per chart period
  for (const pd of OV_PERIODS) {
    const L = ovL('rec_ov_debuts', pd);
    const val = d => t('rec_ov_debut_value', { rank: d.rank, plays: tCount('plays', d.plays || 0) });
    const s = topBy(songDebuts[pd], byDebut), a = topBy(artistDebuts[pd], byDebut), l = topBy(albumDebuts[pd], byDebut);
    if (s) hi('recDebutsSection', pd, 'songs', L, val(s[1]), s[1].title, s[1].artist, s[1].artist);
    if (a) hi('recDebutsSection', pd, 'artists', L, val(a[1]), a[0]);
    if (l) hi('recDebutsSection', pd, 'albums', L, val(l[1]), l[1].album, l[1].artist, l[1].artist);
  }

  // Most plays inside a single week, month or year
  for (const pd of OV_PERIODS) {
    const L = ovL('rec_ov_peak_plays', pd);
    const s = topBy(songPP[pd], byCount), a = topBy(artistPP[pd], byCount), l = topBy(albumPP[pd], byCount);
    if (s) hi('recPeakPlaysSection', pd, 'songs', L, tCount('plays', s[1].count), s[1].title || songNm(s[0]), s[1].artist || songArt(s[0]), s[1].artist || songArt(s[0]));
    if (a) hi('recPeakPlaysSection', pd, 'artists', L, tCount('plays', a[1].count), a[0]);
    if (l) hi('recPeakPlaysSection', pd, 'albums', L, tCount('plays', l[1].count), l[1].album || albumNm(l[0]), l[1].artist || albumArt(l[0]), l[1].artist || albumArt(l[0]));
  }

  // Highest play-count milestone reached (artists and songs only).
  // The highest tier anybody reached, then the earliest to reach it. Read off
  // the map's own tiers rather than a fixed ladder: songs run every 25 plays
  // with no ceiling, so walking MILESTONES would report 500 for a song that
  // actually got to 525.
  {
    const L = t('rec_ov_milestones');
    const firstTo = function (msMap) {
      let topM = -1;
      for (const k in msMap) for (const m in msMap[k]) { const mm = +m; if (mm > topM) topM = mm; }
      if (topM < 0) return null;
      let best = null;
      for (const k in msMap) {
        const ms = msMap[k][topM];
        if (ms && (!best || ms.date < best[1].date)) best = [k, ms];
      }
      return best ? { m: topM, key: best[0], ms: best[1] } : null;
    };
    const a = firstTo(artistMS), s = firstTo(songMS), l = firstTo(albumMS);
    // 'all' only: a play-count milestone is a lifetime total, not something a
    // week or a year holds, so this card sits out the period pills.
    if (s) hi('recMilestonesSection', 'all', 'songs', L, tCount('plays', s.m), songNm(s.key), fmtDate(s.ms.date), songArt(s.key));
    if (a) hi('recMilestonesSection', 'all', 'artists', L, tCount('plays', a.m), a.key, fmtDate(a.ms.date));
    // Albums now climb the same ladder, so this card is no longer permanently
    // empty on the Albums pill.
    if (l) hi('recMilestonesSection', 'all', 'albums', L, tCount('plays', l.m), albumNm(l.key), fmtDate(l.ms.date), albumArt(l.key));
  }

  /* Fastest to a milestone. Each entity is shown at the headline tier of its
     own ladder — 500 plays for songs, 1,000 for artists, 500 for albums — so
     the label carries the number rather than assuming a shared one. If nobody
     has reached that tier yet the card would be empty for no good reason, so
     it drops to the highest tier anyone did reach. */
  {
    // Exact elapsed time, matching the section's own ranking — picking the
    // winner on rounded days would sometimes name a different record than the
    // one sitting at #1 in the table this card links to.
    const fastest = function (msMap, target) {
      let best = null;
      for (const k in msMap) {
        const ms = msMap[k][target];
        if (ms && (!best || ms.elapsed < best[1].elapsed)) best = [k, ms];
      }
      return best;
    };
    // Walks the ladder down from the headline tier until one has entries.
    const fastestAtOrBelow = function (msMap, tiers) {
      for (const tier of tiers) {
        const b = fastest(msMap, tier);
        if (b) return { m: tier, best: b };
      }
      return null;
    };
    const s = fastestAtOrBelow(songMS, [500, 250, 100, 50]);
    const a = fastestAtOrBelow(artistMS, [1000, 500]);
    const l = fastestAtOrBelow(albumMS, [500, 250, 100]);
    // 'all' only, for the same reason as Milestones above: the race to a
    // lifetime total does not belong to any one chart period.
    if (s) hi('recFastestSection', 'all', 'songs', t('rec_ov_fastest', { n: s.m.toLocaleString() }),
      fmtElapsed(s.best[1].elapsed), songNm(s.best[0]), songArt(s.best[0]), songArt(s.best[0]));
    if (a) hi('recFastestSection', 'all', 'artists', t('rec_ov_fastest', { n: a.m.toLocaleString() }),
      fmtElapsed(a.best[1].elapsed), a.best[0]);
    // Albums climb their own ladder now, so this card is no longer empty on the
    // Albums pill.
    if (l) hi('recFastestSection', 'all', 'albums', t('rec_ov_fastest', { n: l.m.toLocaleString() }),
      fmtElapsed(l.best[1].elapsed), albumNm(l.best[0]), albumArt(l.best[0]), albumArt(l.best[0]));
  }

  /* Certifications. Artists rank by how many they hold, which is a genuine
     ordering. Songs and albums can't be ranked that way — plenty of them
     reach Diamond eventually, so "a Diamond song" is not a record and
     picking the one with the most plays is arbitrary. The record is who got
     there FIRST: take the highest tier anyone reached, then the earliest
     certification date at that tier. */
  {
    if (certW[0]) {
      const c0 = certW[0], nCert = c0.sg + c0.sp + c0.sd + c0.ag + c0.ap + c0.ad;
      // 'all' only: certifications are awarded on lifetime plays.
      hi('recCertsSection', 'all', 'artists', t('rec_ov_certs'), t('rec_ov_certs_value', { n: nCert }), c0.art);
    }
    const firstToTopTier = function (type) {
      let best = null, bestOrd = Infinity;
      for (const w of wallItems) {
        if (w.type !== type) continue;
        const ord = _wTierOrd[w.tier];
        if (ord > bestOrd) continue;
        if (ord < bestOrd) { bestOrd = ord; best = w; continue; }
        /* Same tier: earliest certification wins. Every plaque is dated by the
           award it *is* — a record's first Diamond is its own item, separate
           from the Double Diamond it earned later — so this compares the day
           each one reached the tier without needing to look past it. Undated
           items never displace a dated one, and only stand in if nothing dated
           exists. */
        if (w.date && (!best.date || w.date < best.date)) best = w;
      }
      return best;
    };
    [['songs', 'song'], ['albums', 'album']].forEach(function (pair) {
      const w = firstToTopTier(pair[1]);
      if (!w) return;
      hi('recCertsSection', 'all', pair[0], t('rec_ov_certs_first'), t('rec_ov_cert_tier_' + w.tier),
        w.title, w.date ? fmtDate(new Date(w.date + 'T00:00:00')) : w.artist, w.artist);
    });
  }

  /* Longest run of consecutive listening. All five of the section's ladders
     get a card, because they are five different records rather than one
     record sliced five ways: days, weeks, months and years each count a
     different unit, and a back-to-back run counts plays in the log with
     nothing in between. Weeks, months and years double as the Weekly, Monthly
     and Yearly pills; the other two are All-only. */
  {
    /* Whoever the table puts on row 1. It reads through the very comparator the
       table sorts with, so the card can never name a different holder than the
       row it sends you to — the yearly tiebreak in particular would be easy to
       let drift out of sync if this kept its own copy of the rule. */
    const bestStreak = function (kind, dim) {
      const map = streaks[kind][dim];
      const cmp = streakCmp(dim);
      let best = null;
      for (const k in map) {
        const e = [k, map[k]];
        if (!best || cmp(e, best) < 0) best = e;
      }
      return best;
    };
    /* Back-to-back runs live in their own map and rank on a different figure,
       so they get their own reader. Ties break toward the most recent run,
       matching the section's own table. */
    const bestRun = function (kind) {
      const map = bestRuns[kind];
      let bk = null, bv = null;
      for (const k in map) {
        const v = map[k];
        if (!bv || v.count > bv.count || (v.count === bv.count && v.date > bv.date)) { bk = k; bv = v; }
      }
      return bk === null ? null : [bk, bv];
    };
    // 'weeks_full' is the prose plural; the streak dims are their own unit keys.
    const STREAK_OV = [
      { slot: 'days', dim: 'days', unit: 'days', label: t('rec_ov_streaks') },
      { slot: 'weeks', dim: 'weeks', unit: 'weeks_full', label: t('rec_ov_streaks_week') },
      { slot: 'months', dim: 'months', unit: 'months', label: t('rec_ov_streaks_month') },
      { slot: 'years', dim: 'years', unit: 'years', label: t('rec_ov_streaks_year') },
    ];
    for (const cfg of STREAK_OV) {
      const s = bestStreak('song', cfg.dim), a = bestStreak('artist', cfg.dim), l = bestStreak('album', cfg.dim);
      if (s) hi('recStreaksSection', cfg.slot, 'songs', cfg.label, tCount(cfg.unit, s[1].len), songNm(s[0]), songArt(s[0]), songArt(s[0]));
      if (a) hi('recStreaksSection', cfg.slot, 'artists', cfg.label, tCount(cfg.unit, a[1].len), a[0]);
      if (l) hi('recStreaksSection', cfg.slot, 'albums', cfg.label, tCount(cfg.unit, l[1].len), albumNm(l[0]), albumArt(l[0]), albumArt(l[0]));
    }
    {
      // Same "12×" the runs table prints, so the card and the row it links to
      // quote the record in one shape.
      const R = t('rec_ov_streak_runs');
      const runVal = e => e[1].count.toLocaleString() + '×';
      const s = bestRun('song'), a = bestRun('artist'), l = bestRun('album');
      if (s) hi('recStreaksSection', 'runs', 'songs', R, runVal(s), songNm(s[0]), songArt(s[0]), songArt(s[0]));
      if (a) hi('recStreaksSection', 'runs', 'artists', R, runVal(a), a[0]);
      if (l) hi('recStreaksSection', 'runs', 'albums', R, runVal(l), albumNm(l[0]), albumArt(l[0]), albumArt(l[0]));
    }
  }

  // Biggest debut on the New Songs / New Artists / New Albums charts
  for (const pd of OV_PERIODS) {
    const L = ovL('rec_ov_new_charts', pd);
    const val = d => t('rec_ov_debut_value', { rank: d.rank, plays: tCount('plays', d.plays || 0) });
    const s = topBy(ncSongDebuts[pd], byDebut), a = topBy(ncArtistDebuts[pd], byDebut), l = topBy(ncAlbumDebuts[pd], byDebut);
    if (s) hi('recNewChartsSection', pd, 'songs', L, val(s[1]), s[1].title, s[1].artist, s[1].artist);
    if (a) hi('recNewChartsSection', pd, 'artists', L, val(a[1]), a[0]);
    if (l) hi('recNewChartsSection', pd, 'albums', L, val(l[1]), l[1].album, l[1].artist, l[1].artist);
  }

  renderRecordsOverview(recHi);
  setupRecordSubsectionCollapse();
  restoreRecordSubsectionCollapseStates();
  applyNewChartsRecTabs();
  applyMilestoneRecTabs();
  applyFastestRecTabs();
  applyRecEntTabs();
  applyRecPerTabs();
  initAllRecTableResizableCols();
  initAllRecTableSorting();

  // Canonical rank index per row, so the entries-per-table limit can be applied
  // (and re-applied at a smaller value) without rebuilding any of this.
  recBuiltLimit = lim;
  tagRecCellLabels();
  tagRecRowIndices();
  applyRecRowLimit(lim);

  /* Last, because it reads the built tables rather than the source maps — every
     section has to exist in the DOM before the tally can walk it. */
  renderRecordsHeroArtist(recTallyArtistRecords());

  if (recSearchQuery()) runRecordsSearch(recSearchQuery());
}

/* ── Records overview ──────────────────────────────────────────────────
   The landing screen: one card per section showing that section's single
   best record, so Records opens with something to read instead of dropping
   you into whichever table happened to be first.

   Card titles are read out of each section's own <h2> rather than kept in a
   second list here, so they cannot drift apart and stay translated. */
const REC_OV_TYPES = [
  { key: 'songs', label: 'rec_th_songs' },
  { key: 'artists', label: 'rec_th_artists' },
  { key: 'albums', label: 'rec_th_albums' },
];

/* Second toggle, under the type pills: which chart period the board is cut to.
   'all' is every record the overview knows about; the other three narrow it to
   one chart period. */
const REC_OV_PERIODS = [
  { key: 'all', label: 'rec_ov_period_all' },
  { key: 'week', label: 'nav_weekly' },
  { key: 'month', label: 'nav_monthly' },
  { key: 'year', label: 'nav_yearly' },
];

/* Every card the board can show, per section: which stored record it reads
   (`slot`, the key hi() filed it under), which pills it appears under
   (`pills`) and the chip it wears when several of a section's cards sit side
   by side on All (`tag`).

   All shows the lot, so every slot lists 'all'. A section whose record is a
   lifetime total has one slot and no tag — nothing to tell apart. Streaks is
   the section with the most: five ladders, five cards, of which three answer
   a period pill and two (the daily streak and the back-to-back run) are
   All-only because no chart period corresponds to them.

   A section missing from this map draws no card, which is the safe failure:
   adding a records section means adding its slots here, and forgetting leaves
   a gap rather than an empty tile or a wrong figure. */
const OV_CHART_SLOTS = [
  { slot: 'week', pills: ['all', 'week'], tag: 'nav_weekly' },
  { slot: 'month', pills: ['all', 'month'], tag: 'nav_monthly' },
  { slot: 'year', pills: ['all', 'year'], tag: 'nav_yearly' },
];
const OV_ALLTIME_SLOTS = [{ slot: 'all', pills: ['all'], tag: null }];

const REC_OV_SLOTS = {
  recAllOnesSection: OV_CHART_SLOTS,
  recPAKSection: OV_CHART_SLOTS,
  recAppearancesSection: OV_CHART_SLOTS,
  recDebutsSection: OV_CHART_SLOTS,
  recPeakPlaysSection: OV_CHART_SLOTS,
  recMilestonesSection: OV_ALLTIME_SLOTS,
  recFastestSection: OV_ALLTIME_SLOTS,
  recCertsSection: OV_ALLTIME_SLOTS,
  recStreaksSection: [
    { slot: 'runs', pills: ['all'], tag: 'rec_per_runs' },
    { slot: 'days', pills: ['all'], tag: 'nav_daily' },
    { slot: 'weeks', pills: ['all', 'week'], tag: 'nav_weekly' },
    { slot: 'months', pills: ['all', 'month'], tag: 'nav_monthly' },
    { slot: 'years', pills: ['all', 'year'], tag: 'nav_yearly' },
  ],
  recNewChartsSection: OV_CHART_SLOTS,
};

// Held so the Songs/Artists/Albums and period toggles can re-render from memory
// instead of re-running buildRecords(), which would rebuild all ~55 tables to
// change a pill. Shape: { sectionId: { slot: { type: {…} } } }.
let _recOvHighlights = {};

// The chart type the pills speak in ("songs") vs. the one the image loader
// speaks in ("song"). Every artwork lookup in the app uses the singular.
const REC_OV_IMG_TYPE = { songs: 'song', artists: 'artist', albums: 'album' };

/* One live IntersectionObserver at a time. The pills re-render this grid on
   every click, and without retiring the previous observer each toggle would
   leave another one watching elements that no longer exist. */
let _recOvImgObserver = null;

/* The loadImages() descriptor for one card's artwork. Same shape and same
   prefKey formula the weekly views use (_wvItem), so a picture pinned in the
   picker anywhere in the app shows up here too, and vice versa. */
function recOvImgItem(type, d, imgId) {
  const nm = d.name || '', art = d.artist || '';
  if (type === 'artists') {
    return { imgId, name: nm, artist: nm, prefKey: 'artist:' + nm.toLowerCase() };
  }
  if (type === 'albums') {
    return { imgId, name: nm, album: nm, artist: art, prefKey: 'album:' + art.toLowerCase() + '|||' + nm.toLowerCase() };
  }
  return { imgId, name: nm, title: nm, artist: art, album: '', prefKey: 'song:' + art.toLowerCase() + '|||' + nm.toLowerCase() };
}

function recOverviewType() {
  const stored = localStorage.getItem('dc_rec_ov_type');
  return REC_OV_TYPES.some(function (ty) { return ty.key === stored; }) ? stored : 'songs';
}

function recOverviewPeriod() {
  const stored = localStorage.getItem('dc_rec_ov_period');
  return REC_OV_PERIODS.some(function (p) { return p.key === stored; }) ? stored : 'all';
}

/* Every card on the board for one period, in nav order: each section's slots
   that answer this pill, flattened. */
function recOvCards(period) {
  const cards = [];
  for (const id of REC_SECTION_IDS) {
    if (id === 'recOverviewSection') continue;
    for (const sl of (REC_OV_SLOTS[id] || [])) {
      if (sl.pills.indexOf(period) !== -1) cards.push({ id: id, slot: sl.slot, tag: sl.tag });
    }
  }
  return cards;
}

/* Section id → sprite symbol id. The symbols themselves are defined once in
   index.html and shared by the nav pills, the section headings and these
   overview cards; this map is only needed here because the cards are the one
   place built in JS. Adding a records section means adding a <symbol> there
   and a line here — a missing entry degrades to a title with no glyph rather
   than a broken <use>. */
const REC_SECTION_ICON = {
  recAllOnesSection: 'ri-ones',
  recPAKSection: 'ri-pak',
  recAppearancesSection: 'ri-appearances',
  recDebutsSection: 'ri-debuts',
  recPeakPlaysSection: 'ri-plays',
  recMilestonesSection: 'ri-milestones',
  recFastestSection: 'ri-fastest',
  recCertsSection: 'ri-certs',
  recStreaksSection: 'ri-streaks',
  recNewChartsSection: 'ri-newcharts',
};

function renderRecordsOverview(highlights) {
  const body = document.getElementById('recOverviewBody');
  if (!body) return;
  if (highlights) _recOvHighlights = highlights;
  const type = recOverviewType();
  const period = recOverviewPeriod();
  const cards = recOvCards(period);

  let html = '<p class="rec-ov-intro">' + esc(t('rec_ov_intro')) + '</p>';
  html += '<div class="rec-ov-types" role="group" aria-label="' + esc(t('rec_ov_type_label')) + '">';
  html += REC_OV_TYPES.map(function (ty) {
    return '<button type="button" class="rec-ov-type' + (ty.key === type ? ' active' : '') +
      '" data-rec-ov-type="' + ty.key + '" aria-pressed="' + (ty.key === type) + '">' +
      esc(t(ty.label)) + '</button>';
  }).join('');
  html += '</div>';

  // Second row, one step quieter than the first: the type pills pick what the
  // board is about, these pick how it is sliced.
  html += '<div class="rec-ov-periods" role="group" aria-label="' + esc(t('rec_ov_period_label')) + '">';
  html += REC_OV_PERIODS.map(function (p) {
    return '<button type="button" class="rec-ov-period' + (p.key === period ? ' active' : '') +
      '" data-rec-ov-period="' + p.key + '" aria-pressed="' + (p.key === period) + '">' +
      esc(t(p.label)) + '</button>';
  }).join('');
  html += '</div>';

  /* Cards are built to the mosaic tile's anatomy (.wv-mos-item): the record
     holder's artwork fills the whole card, a scrim at the top carries the
     section name and one at the foot carries every fact — the figure, who
     holds it and what it is. Unlike the mosaic, all tiles are the same size;
     nothing here is being weighted against anything else. */
  const imgItems = [];
  html += cards.map(function (c, idx) {
    const id = c.id;
    const sec = document.getElementById(id);
    if (!sec) return '';
    const heading = sec.querySelector('.section-header-h2');
    const title = heading ? heading.textContent.trim() : id;
    const d = (_recOvHighlights[id] || {})[c.slot] ? _recOvHighlights[id][c.slot][type] : null;
    const hasRecord = !!(d && d.value);

    /* A <div role="button"> rather than a real <button>: the artwork carries
       the image picker's ✎ control, and a button inside a button is invalid
       HTML that browsers unnest. Keyboard activation is restored below. */
    let card = '<div class="rec-ov-card' + (hasRecord ? '' : ' rec-ov-card-empty') +
      '" role="button" tabindex="0" data-rec-goto="' + esc(id) + '">';

    // Artwork only where there is a record to illustrate — an empty card has
    // no holder, so it stays a plain surface instead of borrowing someone's art.
    if (hasRecord && d.name) {
      // Card index, not section index: All puts several cards from one section
      // on the board, and a reused id would let a stale observer resolve.
      const imgId = 'recov-' + period + '-' + type + '-' + idx;
      imgItems.push(recOvImgItem(type, d, imgId));
      card += '<div class="rec-ov-art"><div class="thumb-wrap"><div id="' + imgId + '">'
        + '<div class="thumb-initials">' + esc(initials(d.name)) + '</div></div></div></div>';
    }

    card += '<div class="rec-ov-scrim-top"></div>';
    // The card's own copy of the section's glyph — third and last place the
    // sprite appears, after the nav pill and the section heading, so a tile,
    // the pill it jumps to and the heading it lands on all carry one mark.
    // Titles no longer supply an emoji of their own: it was stripped out of
    // the rec_*_title strings when the sprite went in.
    // On All, where one section can put five cards up at once, the slot's chip
    // rides alongside the title so they are not five tiles with one name. Under
    // a period pill the pill itself already says which, so the chip is dropped.
    card += '<span class="rec-ov-title">' +
      (REC_SECTION_ICON[id]
        ? '<svg class="rec-ov-ico" aria-hidden="true" focusable="false"><use href="#' +
          REC_SECTION_ICON[id] + '" /></svg>'
        : '') +
      esc(title) +
      (period === 'all' && c.tag ? '<span class="rec-ov-tag">' + esc(t(c.tag)) + '</span>' : '') +
      '</span>';
    card += '<div class="rec-ov-bot">';
    card += '<span class="rec-ov-value">' + (hasRecord ? esc(d.value) : '—') + '</span>';
    if (hasRecord && d.name) {
      card += '<span class="rec-ov-name">' + esc(d.name) +
        (d.sub ? '<span class="rec-ov-sub"> · ' + esc(d.sub) + '</span>' : '') + '</span>';
    }
    card += '<span class="rec-ov-label">' + esc(hasRecord ? d.label : t('rec_ov_no_type_record')) + '</span>';
    card += '</div></div>';
    return card;
  }).join('');

  body.innerHTML = html;

  // Retire the previous pill's observer before the new one starts watching.
  if (_recOvImgObserver) { _recOvImgObserver.disconnect(); _recOvImgObserver = null; }
  if (imgItems.length) _recOvImgObserver = loadImages(imgItems, REC_OV_IMG_TYPE[type]);

  if (body.dataset.ready !== '1') {
    body.dataset.ready = '1';
    body.addEventListener('click', function (e) {
      const typeBtn = e.target.closest('[data-rec-ov-type]');
      if (typeBtn) {
        localStorage.setItem('dc_rec_ov_type', typeBtn.dataset.recOvType);
        renderRecordsOverview(); // re-reads the cached highlights, no rebuild
        return;
      }
      const perBtn = e.target.closest('[data-rec-ov-period]');
      if (perBtn) {
        localStorage.setItem('dc_rec_ov_period', perBtn.dataset.recOvPeriod);
        renderRecordsOverview();
        return;
      }
      const card = e.target.closest('[data-rec-goto]');
      if (!card) return;
      const view = card.dataset.recGoto;
      localStorage.setItem('dc_records_active_view', view);
      applyRecordsViewFilter(view);
      const rv = document.getElementById('recordsView');
      if (rv && rv.scrollIntoView) rv.scrollIntoView({ block: 'start', behavior: 'auto' });
    });
    // What a real <button> gave us for free, back by hand.
    body.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
      const card = e.target.closest('[data-rec-goto]');
      if (!card) return;
      e.preventDefault();
      card.click();
    });
  }
}

/* ── Hero artist: whoever holds the most records ───────────────────────
   A "record" here is any single row in any records table, at any rank — three
   Taylor Swift songs inside one Top 25 are three records, not one, and each
   gets its own card in the reel. Ranking is by raw row count, so the winner is
   the most decorated artist in the library rather than the holder of any one
   headline record.

   This is a DOM walk, not a data pass, for the same reason the global search is
   one: the built tables are the only place all ~55 record lists exist in a
   single shape. A future section is therefore counted for free, as long as its
   rows expose an artist. Two ways they can:
     - an .img-src-btn[data-artist] written by the shared nameRow helpers
       (All #1s, Appearances, New Charts, Debuts)
     - explicit data-rec-* on the row itself, for the sections that draw their
       own artwork and so have no picker button at build time (PAK, Milestones)
       or are not tables at all (the certifications wall)

   The entries-per-table limit is respected in both directions: recTable()
   slices to it at build time, so rows past it are never rendered, and rows
   hidden afterwards by applyRecRowLimit() are skipped here. If a table is
   capped at 25, only those 25 are anyone's records. */

/* Rows that are a detail of the row above them, plus the wall's own card grid.
   The wall hangs a plaque for every certification a record ever earned, so one
   album can be five cards; only its highest counts here, which is the one
   without data-cert-lesser. */
const REC_TALLY_SEL = '#recordsView tbody tr, #recordsView .cert-card:not([data-cert-lesser])';

/* One record row → the card descriptor the reel needs, or null if the row
   carries no artist (spacer rows, empty states, headers). */
function recRowRecord(row) {
  let artist = row.dataset.recArtist || '';
  let type = row.dataset.recType || '';
  let name = row.dataset.recName || '';
  let prefKey = row.dataset.recPrefkey || '';

  if (!artist) {
    // The shared nameRow helpers write everything the picker needs onto the
    // button; reuse it rather than duplicating the attributes on every row.
    const btn = row.querySelector('.img-src-btn[data-artist]');
    if (!btn) return null;
    artist = btn.getAttribute('data-artist') || '';
    type = type || btn.getAttribute('data-type') || '';
    name = name || btn.getAttribute('data-name') || '';
    prefKey = prefKey || btn.getAttribute('data-prefkey') || '';
  }
  if (!artist || !name) return null;

  // The rank the row holds in its own table — the "#" column. Absent on the
  // milestone timeline and the certifications wall, which have no rank column.
  const rankCell = row.querySelector ? row.querySelector('.rec-rank') : null;
  const rank = rankCell ? rankCell.textContent.trim() : '';

  /* isCert is carried through rather than inferred later from the section title,
     which is translated text and would break the moment anyone edited it. The
     card stacks its figure on the strength of this flag. */
  const isCert = !!(row.classList && row.classList.contains('cert-card'));
  return {
    artist, type: type || 'song', name, prefKey, rank, isCert,
    details: recRowDetails(row, name, artist)
  };
}

/* The figures that make a record specific — "12 times at #1, first Mar 2019" —
   paired out of the row's own cells against its table's own <th>. Reading the
   rendered table rather than re-deriving per section means a card carries
   whatever that record actually measures, in the section's own translated
   wording, for all ~55 tables at once. A table that gains a column gains it on
   the card too. */
const REC_DETAIL_MAX = 4;

/* Which of a record's figures is *the* figure. Usually the first, because the
   tables put the column they rank by early — "Weeks at #1", "Plays",
   "Consecutive Days", "Tier". But Appearances leads with a date and the
   certifications leaderboard leads with a long tally string, and neither reads
   as a headline, so a value is scored on being short and starting with a
   number. Returns an index into `details`. */
function pickHeadlineDetail(details) {
  let bestI = 0, bestScore = -Infinity;
  for (let i = 0; i < details.length; i++) {
    const v = details[i].value;
    let score = 0;
    if (/^[\d]/.test(v)) score += 3;          // a count, a duration, a position
    if (v.length <= 14) score += 2;           // fits at display size without wrapping
    if (v.length > 24) score -= 3;            // a tally or a sentence, not a headline
    if (/^\d{1,2} \w{3} \d{4}$/.test(v)) score -= 2; // a bare date is context, not the record
    if (/week of|^\w{3} \d{4}$/i.test(v)) score -= 2;
    score -= i * 0.1;                          // ties go to the earlier (more ranked) column
    if (score > bestScore) { bestScore = score; bestI = i; }
  }
  return bestI;
}

function recRowDetails(row, name, artist) {
  const out = [];

  /* The certifications wall is divs, not a table, so it has no <th> to pair
     against — its fields are named by their own classes instead. */
  if (row.classList && row.classList.contains('cert-card')) {
    const pick = function (sel, label, strip) {
      const el = row.querySelector(sel);
      let v = el ? el.textContent.trim() : '';
      if (strip && v.toLowerCase().indexOf(strip.toLowerCase() + ' ') === 0) v = v.slice(strip.length + 1);
      if (v) out.push({ label: label, value: v });
    };
    /* The plaque names its award as "Triple Diamond certified album". The reel's
       own description already says whether it is a song or an album, so only the
       award itself is taken — the trailing half is peeled off by its element
       rather than by matching on words, which would break the moment the
       wording is translated. .cert-date is the bare date now, so it needs no
       prefix stripping. */
    const tierEl = row.querySelector('.cert-tier-name');
    if (tierEl) {
      const ofEl = tierEl.querySelector('.cert-tier-of');
      const award = tierEl.textContent.replace(ofEl ? ofEl.textContent : '', '').trim();
      if (award) out.push({ label: t('rec_hero_d_tier'), value: award });
    }
    pick('.cert-date', t('rec_hero_d_certified'));
    return out;
  }

  const table = row.closest ? row.closest('table') : null;
  if (!table) return out;
  const ths = table.querySelectorAll('thead th');
  const cells = row.children;

  /* Raw textContent runs a cell's parts together ("550Plays", "Perfect All
     KillWeeks"), so walk the child nodes instead. Stacked <div>s are separate
     facts and get " · "; inline spans and bare text are one phrase and get a
     space. Parts that carry no letter or digit are decoration — the 🎵/💿
     column icons and PAK's ▼ expand caret — and are dropped, because a value
     reading "▼" is noise on a card. */
  const partsOf = function (el) {
    const parts = [];
    el.childNodes.forEach(function (n) {
      if (n.nodeType === 1 && n.classList.contains('col-resize-handle')) return;
      const s = n.textContent.replace(/\s+/g, ' ').trim();
      if (!s || !/[\p{L}\p{N}]/u.test(s)) return;
      parts.push({ s: s, block: n.nodeType === 1 && n.tagName === 'DIV' });
    });
    return parts;
  };

  const joinParts = function (parts) {
    let outStr = '';
    for (let i = 0; i < parts.length; i++) {
      if (i > 0) outStr += (parts[i].block || parts[i - 1].block) ? ' · ' : ' ';
      outStr += parts[i].s;
    }
    return outStr;
  };

  const cellText = function (el) { return joinParts(partsOf(el)); };

  for (let i = 0; i < cells.length && out.length < REC_DETAIL_MAX; i++) {
    const td = cells[i];
    // The rank and the artwork are already on the card; the toggle column is a
    // control, and its header holds the "expand all" glyph rather than a label.
    if (td.classList.contains('rec-rank') || td.classList.contains('thumb-cell')) continue;
    if (td.classList.contains('rec-run-toggle-cell') || td.querySelector('button')) continue;

    // The cell that names the record's subject is already the card's title.
    const nameEl = td.querySelector('.rec-name');
    if (nameEl && nameEl.textContent.trim() === name) continue;

    const th = ths[i];
    if (!th || th.querySelector('button')) continue;
    /* .rec-sort-ind is the ▲/▼ the sortable headers carry, and
       .col-resize-handle is an empty span on every th but the last — neither is
       part of the column's name. */
    const labelParts = [];
    th.childNodes.forEach(function (n) {
      if (n.nodeType === 1 && (n.classList.contains('rec-sort-ind') || n.classList.contains('col-resize-handle'))) return;
      const s = n.textContent.replace(/\s+/g, ' ').trim();
      if (s) labelParts.push({ s: s, block: false });
    });
    const label = joinParts(labelParts);
    if (!label) continue;

    let value = cellText(td);
    if (!value || value === '—') continue;
    // Skip the columns the card already shows as its title and its subject.
    if (value === name || value === artist) continue;
    /* "Week" + "Week of 14 Apr 2024" reads as a stutter once the two sit side by
       side on a card, so a value that opens with its own column name drops it. */
    if (value.toLowerCase().indexOf(label.toLowerCase() + ' ') === 0) {
      value = value.slice(label.length + 1).trim();
      if (!value) continue;
    }

    out.push({ label: label, value: value });
  }
  return out;
}

/* What record is this row a record *of*? Read from the headings the row sits
   under, so the label cannot drift from what the section actually says and
   stays translated for free — the same trick the overview cards use. */
function recRowLabel(row) {
  const sub = row.closest('.rec-section-sub-wrapper');
  const subTitle = sub ? sub.querySelector('.rec-section-sub') : null;
  const sect = row.closest('.rec-section');
  const sectTitle = sect ? sect.querySelector('.rec-section-title') : null;
  const top = row.closest('.chart-section');
  const topTitle = top ? top.querySelector('.section-header-h2') : null;

  // Sub-section headings read "Weekly Chart — 42 songs have hit #1"; only the
  // part before the dash is the qualifier, the rest is a count we already show.
  let qualifier = '';
  if (subTitle) qualifier = subTitle.textContent.split('—')[0].trim();

  const main = (sectTitle && sectTitle.textContent.trim())
    || (topTitle && topTitle.textContent.trim())
    || '';
  return { main, qualifier };
}

/* Tally every rendered record row by credited artist. Collaborations count for
   each artist named, via the app's own splitArtists() — so this credits a
   feature exactly the way the charts do, and honours the "don't split artists"
   setting for users who have it off. */
function recTallyArtistRecords() {
  const tally = Object.create(null);
  document.querySelectorAll(REC_TALLY_SEL).forEach(function (row) {
    // Detail rows belong to the row above them; counting both double-counts.
    if (row.matches && row.matches(REC_DETAIL_ROW_SEL)) return;
    // A record past the entries-per-table limit is not one of your records —
    // the tab does not show it, so the hero does not count it.
    if (row.classList.contains('rec-row-over-limit')) return;
    const rec = recRowRecord(row);
    if (!rec) return;
    const label = recRowLabel(row);
    /* The certifications wall is one section holding both songs and albums, so
       its heading — "Certifications Leaderboard" — cannot say which a card is.
       Name it from the row's own type instead. */
    if (rec.isCert) {
      label.main = t(rec.type === 'album' ? 'rec_hero_cert_album' : 'rec_hero_cert_song');
      label.qualifier = '';
    }
    splitArtists(rec.artist).forEach(function (a) {
      const nm = a.trim();
      if (!nm) return;
      const k = nm.toLowerCase();
      const bucket = tally[k] || (tally[k] = { name: nm, records: [] });
      bucket.records.push({
        type: rec.type, name: rec.name, prefKey: rec.prefKey, rank: rec.rank,
        artist: rec.artist, label: label.main, qualifier: label.qualifier,
        isCert: rec.isCert, details: rec.details
      });
    });
  });

  /* Kept for the artist modal, which shows any artist's records on demand.
     Refreshed on every tally, so it can never be staler than the hero. */
  _recArtistTally = tally;

  let best = null;
  for (const k in tally) {
    if (!best || tally[k].records.length > best.records.length) best = tally[k];
  }
  return best;
}

/* The records held by one artist, from the last tally. Null when Records has
   not been built this session — the tables the tally walks don't exist yet. */
let _recArtistTally = null;

function recArtistRecordsFor(artistName) {
  if (!_recArtistTally) return null;
  const bucket = _recArtistTally[(artistName || '').trim().toLowerCase()];
  return bucket ? bucket.records : null;
}

/* Cancels an in-flight reel image load when its host re-renders, so a stale
   pass cannot inject covers into a new deck. Same guard shape as the Time
   Machine ticker's tmLoaderId, but keyed per reel — the hero rebuilding must
   not cancel the modal's loads, or vice versa. */
const _recReelLoaderIds = {};

/* The banner + reel. The photo, the name and the total are the brag; the reel
   underneath is a sampler of the individual records, shuffled so that a long
   deck shows something different each visit rather than always opening on the
   same table's rows. Deliberately uncapped — every record the artist holds is
   in the deck. */
/* A struck gold medal with a note on its face, drawn rather than typed so it can
   carry the theme's gold and a glow — the two things an emoji cannot do.

   The medal is tonal rather than dark-centred: the disc takes --gold1 and the
   rim and note take --gold2, which is the lighter of the pair in every one of
   the nine themes. That keeps it all-gold like a real plaque and, more
   practically, means the face never has to match the card behind it — the card
   is translucent over a photograph, so a knocked-out centre would show the
   artist through the medal.

   A single eighth note, not the beamed pair it replaces: at this size two heads
   and a beam collapse into a blob, where one head and a flag still read. */
const REC_CERT_NOTE_SVG =
  '<svg class="rec-cert-mark" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'
  + '<circle class="rec-cert-disc" cx="12" cy="12" r="11"/>'
  + '<circle class="rec-cert-rim" cx="12" cy="12" r="9.1"/>'
  + '<g class="rec-cert-note">'
  + '<ellipse cx="10.3" cy="15.2" rx="2.7" ry="2.1"/>'
  + '<path d="M12.8 15V7.6" fill="none" stroke-width="1.5" stroke-linecap="round"/>'
  + '<path d="M12.8 7.9c2.9.8 3.7 2.6 2.6 4.4" fill="none" stroke-width="1.5" stroke-linecap="round"/>'
  + '</g></svg>';

/* The figure block. Ordinary records set the value and its unit on one line —
   "1129 plays". A certification is different: the tier is a word and the unit
   is the word "certified", so it stacks, and the tier badge carries a leading
   glyph ("💎 Diamond") that must sit *beside* the pair rather than inside the
   line "certified" centres under. Peeling the glyph out is what lets that
   centring be on the word alone. */
function figureHtml(rec, hi, figV) {
  if (!hi) return '';

  if (rec.isCert) {
    const m = figV.match(/^([^\p{L}\p{N}]+)\s*(.+)$/u);
    const icon = m ? m[1].trim() : '';
    const word = m ? m[2] : figV;
    return '<div class="rec-hero-card-figure">'
      + (icon ? '<span class="rec-hero-card-fig-icon" aria-hidden="true">' + esc(icon) + '</span>' : '')
      + '<span class="rec-hero-card-fig-stack">'
      + '<span class="rec-hero-card-fig-v">' + esc(word) + '</span>'
      + '<span class="rec-hero-card-fig-k">' + esc(hi.label) + '</span>'
      + '</span></div>';
  }

  /* Most figures are a short number, but a few are not — the certifications
     leaderboard's headline is a tally like "14× 💎 21× 💿 45× 🪙". Stepping the
     display size down by length keeps those inside the card instead of running
     off its edge, without shrinking the ordinary case. */
  const sizeCls = figV.length > 15 ? ' rec-hero-card-fig-v-xs'
    : (figV.length > 9 ? ' rec-hero-card-fig-v-sm' : '');
  return '<div class="rec-hero-card-figure">'
    + '<span class="rec-hero-card-fig-v' + sizeCls + '">' + esc(figV) + '</span>'
    + '<span class="rec-hero-card-fig-k">' + esc(hi.label) + '</span></div>';
}

/* Fills a marquee track with a shuffled deck of record cards. Shared by the
   hero banner and the artist modal, so a card can never look different in the
   two places. `idPrefix` keys the image element ids and the loader token —
   each host cancels only its own in-flight loads when it re-renders.

   The deck is rendered twice and the track animates to -50%, so the wrap
   lands exactly on the start of copy B and the loop is seamless. Both copies
   carry their own image ids; only copy A is fetched and the result is
   mirrored into copy B, which halves the API calls. */
function recFillReelTrack(track, records, idPrefix) {
  const cards = tmShuffle(records);
  const aItems = { song: [], artist: [], album: [] };
  const bItems = { song: [], artist: [], album: [] };

  function buildCard(rec, i, suffix) {
    const imgId = idPrefix + '-' + suffix + '-' + i;
    const type = rec.type === 'artist' ? 'artist' : (rec.type === 'album' ? 'album' : 'song');
    const bucket = suffix === 'a' ? aItems : bItems;
    bucket[type].push({
      imgId, prefKey: rec.prefKey, name: rec.name,
      title: type === 'song' ? rec.name : '',
      album: type === 'album' ? rec.name : '',
      artist: rec.artist
    });
    /* Every record has one figure that *is* the record — 5 weeks at #1, 396
       plays, 24 days, Diamond — and the rest are supporting detail. Splitting
       them that way is what lets the card lead with something instead of laying
       four equal key/value pairs in a grid that orphans the odd one out. */
    const all = rec.details || [];
    const hi = all.length ? all[pickHeadlineDetail(all)] : null;
    const rest = all.filter(function (d) { return d !== hi; });

    /* "22 weeks" under a label reading "Weeks on Chart" says weeks twice. When
       the figure's trailing unit is already in its label, the numeral stands
       alone — which is also what lets it carry the display size cleanly. */
    let figV = hi ? hi.value : '';
    if (hi) {
      const m = figV.match(/^([\d.,]+)\s+(\S+)$/);
      if (m && hi.label.toLowerCase().indexOf(m[2].toLowerCase()) !== -1) figV = m[1];
    }

    const sub = [rec.label, rec.qualifier].filter(Boolean).join(' · ');
    // Supporting figures collapse to one line: "first Sep 2025 · peak Mar 2026".
    const metaLine = rest.map(function (d) {
      return '<span class="rec-hero-card-meta-i"><span class="rec-hero-card-meta-k">'
        + esc(d.label) + '</span> ' + esc(d.value) + '</span>';
    }).join('<span class="rec-hero-card-meta-sep">·</span>');

    return '<div class="rec-hero-card rec-hero-card-' + type + (rec.isCert ? ' rec-hero-card-cert' : '') + '">'
      + (rec.rank ? '<div class="rec-hero-card-rank">' + esc(rec.rank) + '</div>' : '')
      + '<div class="rec-hero-card-head">'
      + '<div class="rec-hero-card-art' + (type === 'artist' ? ' rec-hero-card-art-round' : '') + '" id="' + imgId + '">'
      + '<div class="thumb-initials">' + esc(initials(rec.name)) + '</div></div>'
      + '<div class="rec-hero-card-headtext">'
      + '<div class="rec-hero-card-name">' + esc(rec.name) + '</div>'
      + (sub ? '<div class="rec-hero-card-sub">'
          + (rec.isCert && type === 'song' ? REC_CERT_NOTE_SVG : '')
          + esc(sub) + '</div>' : '')
      + '</div></div>'
      + figureHtml(rec, hi, figV)
      + (metaLine ? '<div class="rec-hero-card-meta">' + metaLine + '</div>' : '')
      + '</div>';
  }

  const deckA = cards.map(function (r, i) { return buildCard(r, i, 'a'); }).join('');
  const deckB = cards.map(function (r, i) { return buildCard(r, i, 'b'); }).join('');
  track.innerHTML = deckA + deckB;

  /* Seconds per card, so a long deck scrolls at the same speed as a short one
     instead of racing. 6 rather than the Time Machine's 5, because these cards
     are 288px against the ticker's 148: at a matched seconds-per-card the reel
     would travel twice the distance in the same time, which is what made it
     read as fast. 6s lands it near the Events reels, around 50px/s. */
  track.style.animationDuration = Math.max(20, cards.length * 6) + 's';

  /* Card artwork. Fetched directly in small batches rather than through
     loadImages(), because the reel is in constant motion and its
     IntersectionObserver would fire unpredictably against a moving target —
     the same reason the Time Machine ticker loads its cards this way. */
  const myLoaderId = (_recReelLoaderIds[idPrefix] = (_recReelLoaderIds[idPrefix] || 0) + 1);
  (async function () {
    for (const type of ['song', 'artist', 'album']) {
      const pairs = aItems[type].map(function (a, i) { return [a, bItems[type][i]]; });
      const BATCH = 4;
      for (let i = 0; i < pairs.length; i += BATCH) {
        if (_recReelLoaderIds[idPrefix] !== myLoaderId) return;
        await Promise.all(pairs.slice(i, i + BATCH).map(async function (pair) {
          if (_recReelLoaderIds[idPrefix] !== myLoaderId) return;
          const aEl = document.getElementById(pair[0].imgId);
          if (!aEl) return;
          await fetchAndInjectImage(aEl, pair[0], type);
          const bEl = pair[1] && document.getElementById(pair[1].imgId);
          if (bEl) bEl.innerHTML = aEl.innerHTML;
        }));
      }
    }
  })();
}

function renderRecordsHeroArtist(best) {
  const host = document.getElementById('recHeroArtist');
  if (!host) return;

  if (!best || !best.records.length) { host.style.display = 'none'; host.innerHTML = ''; return; }
  host.style.display = '';

  host.innerHTML =
    '<div class="rec-hero-banner" id="recHeroBanner"></div>'
    + '<div class="rec-hero-main">'
    + '<div class="rec-hero-label">' + esc(t('rec_hero_label')) + '</div>'
    + '<div class="rec-hero-name">' + esc(best.name) + '</div>'
    + '<div class="rec-hero-count">' + esc(tCount('records', best.records.length)) + '</div>'
    + '</div>'
    + '<div class="rec-hero-reel" id="recHeroReel">'
    + '<div class="rec-hero-track" id="recHeroTrack"></div>'
    + '</div>';

  recFillReelTrack(document.getElementById('recHeroTrack'), best.records, 'rechero');

  // Banner photo — same artist-image lookup the rest of the app uses, so it
  // honours pinned picker choices and works on every data source.
  const bannerEl = document.getElementById('recHeroBanner');
  const heroName = best.name;
  if (bannerEl) {
    getArtistImage(heroName, 'deezer').then(function (url) {
      if (bannerEl.isConnected && url) bannerEl.style.backgroundImage = 'url("' + url + '")';
    });
  }
}

/* The artist modal's own reel: every record this artist holds, in the same
   cards the hero banner shows. The tally is a walk over the built Records
   tables, and those only exist once buildRecords() has run — which happens on
   the first visit to the Records tab, not at load. So the first modal opened
   before that pays one deferred build: the modal paints first, a wait note
   shows, and the build runs on a timeout so the open animation is not blocked.
   Every later open in the session hits the cached tally. */
let _recModalBuildPending = false;

function renderModalArtistRecords(artistName) {
  const title = document.getElementById('modalHeldRecordsTitle');
  const wait = document.getElementById('modalHeldRecordsWait');
  const reel = document.getElementById('modalHeldRecordsReel');
  const track = document.getElementById('modalHeldRecordsTrack');
  if (!title || !wait || !reel || !track) return;

  // Reset — the modal is reused between artists, and a stale reel from the
  // previous artist must never show behind the new one's wait note.
  title.style.display = 'none';
  wait.style.display = 'none';
  reel.style.display = 'none';
  track.innerHTML = '';
  // Bump the loader token so an in-flight image pass for the previous artist
  // stops writing into ids the new deck is about to reuse.
  _recReelLoaderIds['recmodal'] = (_recReelLoaderIds['recmodal'] || 0) + 1;

  const paint = function () {
    const records = recArtistRecordsFor(artistName);
    wait.style.display = 'none';
    if (!records || !records.length) return; // holds none — section stays hidden
    title.style.display = '';
    title.textContent = '🏆 ' + t('modal_held_records') + ' · ' + tCount('records', records.length);
    reel.style.display = '';
    recFillReelTrack(track, records, 'recmodal');
  };

  if (_recArtistTally) { paint(); return; }

  // Records never built this session. Do it once, after the modal has painted.
  title.style.display = '';
  title.textContent = '🏆 ' + t('modal_held_records');
  wait.style.display = '';
  wait.textContent = t('modal_held_records_wait');
  if (_recModalBuildPending) return; // a previous open already queued it
  _recModalBuildPending = true;
  setTimeout(function () {
    _recModalBuildPending = false;
    if (!_recArtistTally) buildRecords();
    /* Paint for whichever artist's modal is open *now* — the user may have
       switched artists during the build, and painting the queuing artist's
       records into the new artist's modal would be worse than nothing. If the
       build produced no tally (no data), give up rather than re-queue. */
    const nameEl = document.getElementById('modalArtistName');
    const overlay = document.getElementById('artistModal');
    if (!_recArtistTally || !overlay || !overlay.classList.contains('open') || !nameEl) {
      wait.style.display = 'none';
      return;
    }
    renderModalArtistRecords(nameEl.textContent);
  }, 80);
}

function initAllRecTableResizableCols() {
  document.querySelectorAll('#recordsView .rec-table, #recordsView .milestone-table').forEach(initResizableColsForTable);
}

function initResizableColsForTable(table) {
  if (table.dataset.resizeReady === '1') return;
  table.dataset.resizeReady = '1';
  const ths = Array.from(table.querySelectorAll('thead th'));
  ths.forEach(function(th, i) {
    if (i === ths.length - 1) return; // skip last column
    const handle = document.createElement('span');
    handle.className = 'col-resize-handle';
    th.appendChild(handle);
    handle.addEventListener('mousedown', function(e) {
      e.preventDefault();
      e.stopPropagation();
      const startX = e.pageX;
      const startW = th.offsetWidth;
      if (table.style.tableLayout !== 'fixed') {
        ths.forEach(function(t) { t.style.width = t.offsetWidth + 'px'; });
        table.style.tableLayout = 'fixed';
      }
      handle.classList.add('resizing');
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      function onMouseMove(e) {
        th.style.width = Math.max(30, startW + e.pageX - startX) + 'px';
      }
      function onMouseUp() {
        handle.classList.remove('resizing');
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      }
      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    });
  });
}

/* ── Sortable record tables ────────────────────────────────────────────
   Every record table ships hard-sorted by one metric. These helpers let a
   column header re-sort the rendered rows in place, so "most appearances"
   also answers "who charted earliest" without a second table.

   Rank cells are deliberately NOT renumbered: the # column carries the
   table's canonical ranking, so sorting by another column and seeing #14
   land at the top is the information, not a bug. Sorting by # restores the
   original order. */

// Rows that belong to the row above them and must travel with it.
const REC_DETAIL_ROW_SEL = '.rec-run-detail, .app-cr-row, .pak-expand-row';

// Month names come from the active language, so the map is rebuilt per sort.
function recMonthNameMap() {
  const keys = ['month_jan', 'month_feb', 'month_mar', 'month_apr', 'month_may_short', 'month_jun',
    'month_jul', 'month_aug', 'month_sep', 'month_oct', 'month_nov', 'month_dec'];
  const map = [];
  keys.forEach(function (k, i) {
    const name = String(t(k) || '').toLowerCase();
    if (name) map.push([name, i + 1]);
  });
  // Longest first, so a short month name can't match inside a longer one.
  map.sort(function (a, b) { return b[0].length - a[0].length; });
  return map;
}

/* Record dates render through fmt()/fmtPeriodKey() in four shapes:
   "11 Mar 2024", "Mar 2024", "Week of 11 Mar 2024", "2024" — all localized.
   Collapse whichever one matches into a comparable YYYYMMDD integer. */
function recParseDateValue(text, monthMap) {
  const lower = text.toLowerCase();
  for (let i = 0; i < monthMap.length; i++) {
    const name = monthMap[i][0];
    const at = lower.indexOf(name);
    if (at === -1) continue;
    const year = (lower.slice(at + name.length).match(/(\d{4})/) || [])[1];
    if (!year) continue;
    const day = (lower.slice(0, at).match(/(\d{1,2})\s*$/) || [])[1] || '1';
    return (+year) * 10000 + monthMap[i][1] * 100 + (+day);
  }
  const iso = text.match(/^(\d{4})-(\d{2})(?:-(\d{2}))?$/);
  if (iso) return (+iso[1]) * 10000 + (+iso[2]) * 100 + (+(iso[3] || 1));
  if (/^\d{4}$/.test(text)) return (+text) * 10000;
  return null;
}

// "312", "1,234", "312 weeks", "#4", "47%" are numbers. "Song 2" is not.
const REC_NUMERIC_RE = /^[#+-]?[\d.,]+\s*[a-z%×]{0,12}$/i;

function recCellSortValue(td, monthMap) {
  if (!td) return { empty: true, num: null, str: '' };
  if (td.dataset && td.dataset.sort !== undefined) {
    const raw = td.dataset.sort.trim();
    const n = parseFloat(raw);
    return { empty: raw === '', num: isFinite(n) ? n : null, str: raw.toLowerCase() };
  }
  const text = (td.textContent || '').replace(/\s+/g, ' ').trim();
  if (!text || text === '—' || text === '-') return { empty: true, num: null, str: '' };
  const date = recParseDateValue(text, monthMap);
  if (date !== null) return { empty: false, num: date, str: text.toLowerCase() };
  if (REC_NUMERIC_RE.test(text)) {
    const n = parseFloat(text.replace(/,/g, '').replace(/[^\d.-]/g, ''));
    if (isFinite(n)) return { empty: false, num: n, str: text.toLowerCase() };
  }
  return { empty: false, num: null, str: text.toLowerCase() };
}

function sortRecTable(table, colIndex, dir) {
  const tbody = table.tBodies[0];
  if (!tbody) return;
  const monthMap = recMonthNameMap();

  // Group each visible row with the detail rows that trail it.
  const units = [];
  Array.from(tbody.rows).forEach(function (row) {
    if (row.matches(REC_DETAIL_ROW_SEL)) {
      if (units.length) units[units.length - 1].rows.push(row);
      return;
    }
    units.push({ rows: [row], cell: row.cells[colIndex] });
  });
  if (units.length < 2) return;

  units.forEach(function (u, i) {
    u.order = i;
    u.val = recCellSortValue(u.cell, monthMap);
  });

  // One comparator for the whole column, chosen by majority, so a stray
  // unparsable cell can't split the column into two orderings.
  const filled = units.filter(function (u) { return !u.val.empty; });
  const numeric = filled.length > 0 &&
    filled.filter(function (u) { return u.val.num !== null; }).length / filled.length >= 0.6;

  units.sort(function (a, b) {
    // Blanks ("—") always sink, whichever direction is active.
    if (a.val.empty !== b.val.empty) return a.val.empty ? 1 : -1;
    if (a.val.empty) return a.order - b.order;
    let cmp;
    if (numeric) {
      const an = a.val.num, bn = b.val.num;
      if (an === null && bn === null) cmp = a.val.str.localeCompare(b.val.str);
      else if (an === null) return 1;
      else if (bn === null) return -1;
      else cmp = an - bn;
    } else {
      cmp = a.val.str.localeCompare(b.val.str, undefined, { numeric: true, sensitivity: 'base' });
    }
    if (cmp) return dir === 'asc' ? cmp : -cmp;
    return a.order - b.order; // stable: equal values keep canonical rank order
  });

  const frag = document.createDocumentFragment();
  units.forEach(function (u) { u.rows.forEach(function (r) { frag.appendChild(r); }); });
  tbody.appendChild(frag);
}

// Every sortable/searchable/limitable table in Records, in build order.
function recTables() {
  return document.querySelectorAll('#recordsView .rec-table, #recordsView .milestone-table');
}

function initAllRecTableSorting() {
  recTables().forEach(initSortableColsForTable);
}

/* Put a column into a given sort direction. Shared by the header click/keyboard
   handler and by the rebuild path, which has to put the sort back afterwards. */
function applyRecSort(table, colIndex, dir) {
  const ths = Array.from(table.querySelectorAll('thead th'));
  const th = ths[colIndex];
  if (!th || !th.classList.contains('rec-sortable')) return;
  ths.forEach(function (other) {
    if (other === th) return;
    delete other.dataset.sortDir;
    other.classList.remove('rec-sorted');
    if (other.hasAttribute('aria-sort')) other.setAttribute('aria-sort', 'none');
    const oi = other.querySelector('.rec-sort-ind');
    if (oi) oi.textContent = '▲';
  });
  th.dataset.sortDir = dir;
  th.classList.add('rec-sorted');
  th.setAttribute('aria-sort', dir === 'asc' ? 'ascending' : 'descending');
  const ind = th.querySelector('.rec-sort-ind');
  if (ind) ind.textContent = dir === 'asc' ? '▲' : '▼';
  sortRecTable(table, colIndex, dir);
  standDownPodium(table);
}

/* A podium shows a table's canonical top three and hides those three rows so
   the table can start at #4. Re-sorting any column makes "the top three" a
   different set, at which point the podium is stating something false and the
   hidden rows are simply missing — so the first re-sort retires the podium for
   good and hands its rows back. There is no un-sorted state to return to
   (applyRecSort always sets a direction), so this is deliberately one-way; a
   rebuild is what brings the podium back. */
function standDownPodium(table) {
  if (!table.classList.contains('nc-podium-on')) return;
  table.classList.remove('nc-podium-on');
  if (!table.id) return;
  const pod = document.querySelector('.nc-podium[data-nc-podium-for="' + table.id + '"]');
  if (pod) pod.classList.add('nc-podium-retired');
}

/* Tables are keyed by position, not id: most of them have no id, but the same
   code builds them in the same order, so the index survives a rebuild. */
function captureRecSortState() {
  const state = [];
  recTables().forEach(function (table, ti) {
    const ths = Array.from(table.querySelectorAll('thead th'));
    for (let i = 0; i < ths.length; i++) {
      if (!ths[i].dataset.sortDir) continue;
      state.push({ table: ti, col: i, dir: ths[i].dataset.sortDir });
      break; // only one column is ever active per table
    }
  });
  return state;
}

function restoreRecSortState(state) {
  if (!state || !state.length) return;
  const tables = recTables();
  state.forEach(function (s) {
    if (tables[s.table]) applyRecSort(tables[s.table], s.col, s.dir);
  });
}

/* ── Entries per table ────────────────────────────────────────────────
   Every table is sliced to `recLimit` while it is built, so changing the
   limit used to mean a full buildRecords(): ~55 tables thrown away and
   rebuilt, every image looked up again, and any active column sort
   silently lost.

   Shrinking the limit can never need a row that isn't already there, so
   it is now done in the DOM — each row carries its canonical rank index
   and anything past the limit gets .rec-row-over-limit. Only asking for
   more rows than were actually built still rebuilds, and that path puts
   the sorts back afterwards. */
let recBuiltLimit = null; // rows per table currently in the DOM (Infinity = all)

// The rank index is assigned once per build, in canonical (pre-sort) order, so
// the limit keeps meaning "top N" no matter which column the table is sorted by.
// Detail rows inherit their parent's index and travel with it.
/* ── Card layout tagging ──────────────────────────────────────────────
   Below 768px a records table stops being a table: every row becomes a card
   (see the card-layout block in style.css). Two things have to travel with
   the cells for that to work, and both are decided here rather than in ~55
   separate table builders.

   First, a role. A card has an anatomy — the rank and the artwork lead it,
   the name is its title, the expander is its footer, and everything else is
   a labelled figure — and CSS cannot infer that from a <td> alone.

   Second, a label. The column header a figure used to sit under is off the
   screen in card mode, so "1,129" would be a number with no noun. Each
   column's header is copied onto its own cells and printed back by
   .rec-card-fact::before. Headers carrying no word — the artwork column, the
   ▶▶ expand-all button — name nothing, so their cells stay furniture. */
function recThText(node) {
  let s = '';
  Array.from(node.childNodes).forEach(function (n) {
    if (n.nodeType === 3) { s += n.nodeValue; return; }
    if (n.nodeType !== 1) return;
    if (n.classList.contains('rec-sort-ind') || n.classList.contains('col-resize-handle')) return;
    if (n.tagName === 'BR') { s += ' '; return; }
    s += recThText(n);
  });
  return s;
}

function tagRecCellLabels() {
  document.querySelectorAll('#recordsView .rec-table').forEach(function (table) {
    /* .rec-cards is what the card-layout media query keys off, and opting a
       table out is a matter of not adding it. The New Songs debut table has
       its own phone layout, built to the podium's anatomy, so it opts out. */
    if (!table.classList.contains('nc-sd-table')) table.classList.add('rec-cards');
    const labels = Array.from(table.querySelectorAll('thead th')).map(function (th) {
      /* The header carries furniture the label must not: the sort caret this
         column may have picked up, and the column-resize grip. A <br> is a
         word break in a stacked header ("Perfect<br>All Kill<br>Weeks") and
         contributes no text of its own, so it has to become a space or the
         label runs together as "PerfectAll KillWeeks". */
      const s = recThText(th).replace(/\s+/g, ' ').trim();
      // Same test recRowDetails() uses: a caret or a medal is decoration.
      return /[\p{L}\p{N}]/u.test(s) ? s : '';
    });
    const tbody = table.tBodies[0];
    if (!tbody) return;
    Array.from(tbody.rows).forEach(function (row) {
      // Detail rows are a panel belonging to the card above them, not fields
      // of it — they stay full-width blocks and are left alone.
      if (row.matches(REC_DETAIL_ROW_SEL)) return;
      /* A card has one title and one piece of artwork. Some tables carry two
         of each — Appearances pairs a song thumb and name with an artist
         thumb and name — so only the first of each takes the headline slot.
         The second name becomes a labelled figure ("Artist"), which is what
         it actually is, and the second thumbnail is dropped: at 42px it is
         decoration the card has no room for. */
      let hasTitle = false, hasThumb = false;
      Array.from(row.cells).forEach(function (td, i) {
        if (labels[i]) td.dataset.recLabel = labels[i];
        if (td.classList.contains('rec-rank')) return;
        if (td.classList.contains('thumb-cell')) {
          if (hasThumb) td.classList.add('rec-card-extra-thumb');
          hasThumb = true;
          return;
        }
        if (td.querySelector('.rec-name') && !hasTitle) {
          hasTitle = true;
          td.classList.add('rec-card-title');
          return;
        }
        if (td.classList.contains('rec-run-toggle-cell')
            || td.querySelector('.rec-run-toggle-btn, .rec-cr-toggle, .pak-expand-icon')) {
          td.classList.add('rec-card-foot');
          return;
        }
        td.classList.add('rec-card-fact');
      });
    });
  });
}

function tagRecRowIndices() {
  recTables().forEach(function (table) {
    const tbody = table.tBodies[0];
    if (!tbody) return;
    let idx = 0;
    Array.from(tbody.rows).forEach(function (row) {
      /* The milestone timeline's origin row is the foot of the spine, not the
         26th ranked entry — index 0 keeps it inside every limit. It stays out
         of REC_DETAIL_ROW_SEL on purpose: detail rows follow their parent's
         search result, and "the first thing I ever played" has to be findable
         on its own. */
      if (row.classList.contains('mil-row-origin')) { row.dataset.recIdx = 0; return; }
      if (!row.matches(REC_DETAIL_ROW_SEL)) { row.dataset.recIdx = idx++; return; }
      row.dataset.recIdx = Math.max(0, idx - 1);
    });
  });
}

function applyRecRowLimit(limit) {
  const lim = (limit === 0 || limit === undefined || limit === null) ? Infinity : limit;
  recTables().forEach(function (table) {
    const tbody = table.tBodies[0];
    if (!tbody) return;
    Array.from(tbody.rows).forEach(function (row) {
      row.classList.toggle('rec-row-over-limit', (+row.dataset.recIdx || 0) >= lim);
    });
  });
}

function applyRecordsLimitChange() {
  const want = recLimit === 0 ? Infinity : recLimit;
  if (recBuiltLimit !== null && want <= recBuiltLimit) {
    // The rows are already here — no rebuild, so the sort and the images stay put.
    applyRecRowLimit(want);
    /* The hero counts what the tab shows, so a smaller limit is a smaller set
       of records. Re-tallying here is what keeps the headline number honest
       without a rebuild; the reel reshuffles as a side effect, which is
       acceptable for an action the reader just took deliberately. */
    renderRecordsHeroArtist(recTallyArtistRecords());
    if (recSearchQuery()) runRecordsSearch(recSearchQuery());
    /* The DOM now matches the new limit without having been rebuilt, so record
       that — otherwise the build guard would see a changed limit next time the
       tab is opened and rebuild everything for a change already applied. */
    _recBuiltKey = _recBuildKey();
    return;
  }
  const sorts = captureRecSortState();
  buildRecords();
  restoreRecSortState(sorts);
}

/* ── Global records search ────────────────────────────────────────────
   Records is ten sections and ~55 tables, and the only way to ask "how did
   this artist do?" used to be to open every one of them. All the tables are
   already in the DOM (the view filter only toggles `display`), so one query
   can filter rows across every section at once and then reveal whichever
   sections still have something in them.

   Search deliberately ignores the entries-per-table limit: if a row was
   built, it is findable, even when the current limit is hiding it. */
let _recSearchQuery = '';
let _recSearchTimer = null;

function recSearchQuery() { return _recSearchQuery; }

// Row text is cached on the element: rows outlive a query, and a rebuild
// creates new elements, so the cache can never go stale.
function recRowSearchText(row) {
  if (row._recSearchText !== undefined) return row._recSearchText;
  let txt = '';
  Array.from(row.cells).forEach(function (td) {
    // Thumbnail and toggle cells hold controls ("Deezer", "▶"), not record data.
    if (td.classList.contains('thumb-cell') ||
      td.classList.contains('rec-run-toggle-cell') ||
      td.classList.contains('rec-cr-btn-cell')) return;
    txt += ' ' + td.textContent;
  });
  row._recSearchText = txt.replace(/\s+/g, ' ').trim().toLowerCase();
  return row._recSearchText;
}

function runRecordsSearch(q) {
  const view = document.getElementById('recordsView');
  if (!view) return;
  const needle = (q || '').trim().toLowerCase();
  _recSearchQuery = needle;
  const clearBtn = document.getElementById('recordsSearchClear');
  if (clearBtn) clearBtn.style.display = needle ? '' : 'none';
  if (!needle) { clearRecordsSearch(); return; }
  view.classList.add('rec-searching');

  let hits = 0;
  recTables().forEach(function (table) {
    const tbody = table.tBodies[0];
    if (!tbody) return;
    let lastHit = false;
    Array.from(tbody.rows).forEach(function (row) {
      // Detail rows carry no name of their own — they follow their parent.
      if (row.matches(REC_DETAIL_ROW_SEL)) {
        row.classList.toggle('rec-search-hidden', !lastHit);
        return;
      }
      lastHit = recRowSearchText(row).indexOf(needle) !== -1;
      row.classList.toggle('rec-search-hit', lastHit);
      row.classList.toggle('rec-search-hidden', !lastHit);
      if (lastHit) hits++;
    });
  });

  // Roll the hits up: sub-section, then section group, then the section itself.
  view.querySelectorAll('.rec-section-sub-wrapper, .rec-section').forEach(function (el) {
    el.classList.toggle('rec-search-hidden', !el.querySelector('.rec-search-hit'));
  });
  let sections = 0;
  REC_SECTION_IDS.forEach(function (id) {
    const el = document.getElementById(id);
    if (!el) return;
    // The overview is one card per section, not rows — nothing to filter.
    if (id === 'recOverviewSection') { el.style.display = 'none'; return; }
    const has = !!el.querySelector('.rec-search-hit');
    el.style.display = has ? '' : 'none';
    if (has) sections++;
  });
  // Same for the New Charts type/period pills: while a search is running the
  // panels answer to the query, not to the pills, so the pills step aside.
  const ncBody = document.getElementById('recNewChartsBody');
  if (ncBody) {
    ncBody.querySelectorAll('.nc-rec-tabs, .nc-rec-subtabs').forEach(function (el) { el.style.display = 'none'; });
    ncBody.querySelectorAll('.nc-rec-panel').forEach(function (p) {
      p.style.display = p.querySelector('.rec-search-hit') ? '' : 'none';
    });
  }
  // Milestones has the same shape — one pill row over three timeline panels —
  // so it steps aside for a search the same way.
  const milBody = document.getElementById('recMilestonesBody');
  if (milBody) {
    milBody.querySelectorAll('.mil-tabs').forEach(function (el) { el.style.display = 'none'; });
    milBody.querySelectorAll('.mil-panel').forEach(function (p) {
      p.style.display = p.querySelector('.rec-search-hit') ? '' : 'none';
    });
  }
  // And Fastest, which grew the same pill row over the same three entities.
  const fastBody = document.getElementById('recFastestBody');
  if (fastBody) {
    fastBody.querySelectorAll('.fast-tabs').forEach(function (el) { el.style.display = 'none'; });
    fastBody.querySelectorAll('.fast-panel').forEach(function (p) {
      p.style.display = p.querySelector('.rec-search-hit') ? '' : 'none';
    });
  }
  // Every section on the shared pill row — All #1s, Appearances, Debuts, Most
  // Plays, Streaks — steps aside in one pass, since they all wear the same
  // classes. A hit in any panel keeps that panel open regardless of its pill.
  view.querySelectorAll('.rec-ent-tabs').forEach(function (el) { el.style.display = 'none'; });
  view.querySelectorAll('.rec-ent-panel').forEach(function (p) {
    p.style.display = p.querySelector('.rec-search-hit') ? '' : 'none';
  });
  // And the period row nested inside those panels (All #1s), which is the same
  // shape one level down — the pill steps aside, the panels answer to the hit.
  view.querySelectorAll('.rec-per-tabs').forEach(function (el) { el.style.display = 'none'; });
  view.querySelectorAll('.rec-per-panel').forEach(function (p) {
    p.style.display = p.querySelector('.rec-search-hit') ? '' : 'none';
  });
  // No pill is "the" section while results span several of them, and the
  // entries-per-table control has no meaning while search is ignoring it.
  document.querySelectorAll('#recordsNav .records-nav-btn').forEach(function (b) {
    b.classList.remove('active');
  });
  const sizeBar = document.getElementById('recordsSizeBar');
  if (sizeBar) sizeBar.style.display = 'none';

  const status = document.getElementById('recordsSearchStatus');
  if (status) {
    status.style.display = '';
    status.classList.toggle('rec-search-status-empty', hits === 0);
    status.textContent = hits
      ? t('rec_search_results', {
        rows: tCount('rec_search_rows', hits),
        sections: tCount('rec_search_sections', sections)
      })
      : t('rec_search_none', { q: needle });
  }
  if (typeof window._refreshBackToTop === 'function') window._refreshBackToTop();
}

// Drops the query and every mark it left behind, without touching the view.
function recSearchReset() {
  const view = document.getElementById('recordsView');
  _recSearchQuery = '';
  const input = document.getElementById('recordsSearch');
  if (input) input.value = '';
  const clearBtn = document.getElementById('recordsSearchClear');
  if (clearBtn) clearBtn.style.display = 'none';
  const status = document.getElementById('recordsSearchStatus');
  if (status) status.style.display = 'none';
  if (!view) return;
  view.classList.remove('rec-searching');
  view.querySelectorAll('.rec-search-hidden, .rec-search-hit').forEach(function (el) {
    el.classList.remove('rec-search-hidden', 'rec-search-hit');
  });
}

function clearRecordsSearch() {
  recSearchReset();
  applyRecordsViewFilter(localStorage.getItem('dc_records_active_view') || REC_DEFAULT_VIEW);
}

function initSortableColsForTable(table) {
  if (table.dataset.sortReady === '1') return;
  table.dataset.sortReady = '1';
  const ths = Array.from(table.querySelectorAll('thead th'));

  ths.forEach(function (th, i) {
    // Skip artwork columns (no header text) and the expand-all control column.
    if (th.querySelector('button')) return;
    if (!th.textContent.replace(/\s+/g, '').length) return;

    th.classList.add('rec-sortable');
    th.tabIndex = 0;
    th.setAttribute('role', 'columnheader');
    th.setAttribute('aria-sort', 'none');
    const ind = document.createElement('span');
    ind.className = 'rec-sort-ind';
    ind.setAttribute('aria-hidden', 'true');
    ind.textContent = '▲';
    th.appendChild(ind);

    function activate(e) {
      // The resize grip lives inside the th; dragging it must not re-sort.
      if (e && e.target && e.target.closest && e.target.closest('.col-resize-handle')) return;
      applyRecSort(table, i, th.dataset.sortDir === 'asc' ? 'desc' : 'asc');
    }

    th.addEventListener('click', activate);
    th.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      activate(e);
    });
  });
}

function restoreRecordSubsectionCollapseStates() {
  const wrappers = document.querySelectorAll('.rec-section-sub-wrapper');
  wrappers.forEach(wrapper => {
    const subsectionId = wrapper.id.replace('-wrapper', '');
    const isCollapsed = localStorage.getItem('dc_rec_subsection_collapsed_' + subsectionId) === '1';
    if (isCollapsed) {
      wrapper.classList.add('rec-subsection-collapsed');
      const btn = wrapper.querySelector('.rec-subsection-collapse-btn');
      if (btn) {
        btn.textContent = '+';
        btn.title = 'Expand';
        btn.setAttribute('aria-expanded', 'false');
      }
    }
  });
}

function recSafeKey(str) {
  return String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80) || 'section';
}

function initRecordsViewUI() {
  const nav = document.getElementById('recordsNav');
  if (!nav || nav.dataset.ready === '1') return;
  nav.dataset.ready = '1';

  nav.addEventListener('click', e => {
    const btn = e.target.closest('.records-nav-btn');
    if (!btn) return;
    const view = btn.dataset.recView || REC_DEFAULT_VIEW;
    // Picking a section is a way out of a search — drop the query first, or
    // the filter would defer right back to it.
    recSearchReset();
    localStorage.setItem('dc_records_active_view', view);
    applyRecordsViewFilter(view);
  });

  // Add event listeners for records size buttons
  const recordsSizeBar = document.getElementById('recordsSizeBar');
  if (recordsSizeBar) {
    recordsSizeBar.addEventListener('click', e => {
      const btn = e.target.closest('[data-rec-size]');
      if (!btn) return;
      recLimit = parseInt(btn.dataset.recSize, 10);
      localStorage.setItem('dc_rec_limit', recLimit);
      document.querySelectorAll('#recordsSizeBtns button').forEach(b => {
        b.classList.toggle('active', b === btn);
      });
      applyRecordsLimitChange();
    });
  }

  const search = document.getElementById('recordsSearch');
  if (search) {
    search.addEventListener('input', () => {
      clearTimeout(_recSearchTimer);
      // Typing filters a few thousand rows, so wait for a pause in the typing.
      _recSearchTimer = setTimeout(() => runRecordsSearch(search.value), 160);
    });
    search.addEventListener('keydown', e => {
      if (e.key === 'Escape') { clearTimeout(_recSearchTimer); clearRecordsSearch(); }
      if (e.key === 'Enter') { clearTimeout(_recSearchTimer); runRecordsSearch(search.value); }
    });
  }
  const searchClear = document.getElementById('recordsSearchClear');
  if (searchClear) {
    searchClear.addEventListener('click', () => {
      clearTimeout(_recSearchTimer);
      clearRecordsSearch();
      if (search) search.focus();
    });
  }
}

const REC_SECTION_IDS = [
  'recOverviewSection',
  'recAllOnesSection',
  'recPAKSection',
  'recAppearancesSection',
  'recDebutsSection',
  'recPeakPlaysSection',
  'recMilestonesSection',
  'recFastestSection',
  'recCertsSection',
  'recStreaksSection',
  'recNewChartsSection'
];
const REC_DEFAULT_VIEW = 'recOverviewSection';

function applyRecordsViewFilter(view) {
  // The old "All" pill rendered all ten sections at once — ~55 tables and
  // several hundred image lookups in one scroll. It's gone, so migrate any
  // stored 'all' (and any stale id) back to the default view.
  if (REC_SECTION_IDS.indexOf(view) === -1) {
    view = REC_DEFAULT_VIEW;
    localStorage.setItem('dc_records_active_view', view);
  }
  // A search spans every section, so it owns what is displayed until it is
  // cleared. Callers that mean to leave a search call recSearchReset() first.
  if (recSearchQuery()) { runRecordsSearch(recSearchQuery()); return; }
  REC_SECTION_IDS.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.style.display = view === id ? '' : 'none';
  });
  document.querySelectorAll('#recordsNav .records-nav-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.recView === view);
  });
  /* The nav is one non-wrapping scrolling strip, so on a narrow screen the
     active pill can sit outside the visible span — most obviously on load,
     where a stored view like Streaks restores with its pill off to the right
     and the dial appears to be showing Overview. Pull it into view. Only the
     strip scrolls, never the page: `block: 'nearest'` leaves the vertical
     axis alone, which matters because callers here also scroll the page. */
  const activePill = document.querySelector('#recordsNav .records-nav-btn.active');
  if (activePill && activePill.scrollIntoView) {
    activePill.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'auto' });
  }
  // The entries-per-table control has nothing to act on from the overview.
  const sizeBar = document.getElementById('recordsSizeBar');
  if (sizeBar) sizeBar.style.display = view === 'recOverviewSection' ? 'none' : '';
  applyNewChartsRecTabs();
  applyMilestoneRecTabs();
  applyFastestRecTabs();
  applyRecEntTabs();
  applyRecPerTabs();
  if (typeof window._refreshBackToTop === 'function') window._refreshBackToTop();
}

/* ── New Charts record sub-tabs ───────────────────────────────────────
   New Charts alone is ten records across three entities and two period types.
   Two exclusive pill rows narrow that to one table set: the type row picks
   Songs, Artists or Albums, the row under it picks Weekly or Monthly. Both
   choices stick, so coming back to the section lands where you left it. */
const NC_REC_TYPES_ORDER = ['songs', 'artists', 'albums'];
const NC_REC_PERIODS_ORDER = ['week', 'month'];

function ncRecTabState() {
  let type = localStorage.getItem('dc_nc_rec_type');
  let period = localStorage.getItem('dc_nc_rec_period');
  if (NC_REC_TYPES_ORDER.indexOf(type) === -1) type = 'songs';
  if (NC_REC_PERIODS_ORDER.indexOf(period) === -1) period = 'week';
  return { type: type, period: period };
}

function applyNewChartsRecTabs() {
  const body = document.getElementById('recNewChartsBody');
  if (!body) return;
  const st = ncRecTabState();
  body.querySelectorAll('.nc-rec-tabs, .nc-rec-subtabs').forEach(function (el) { el.style.display = ''; });
  body.querySelectorAll('.nc-rec-tab').forEach(function (b) {
    const on = b.dataset.ncType === st.type;
    b.classList.toggle('active', on);
    b.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  body.querySelectorAll('.nc-rec-subtab').forEach(function (b) {
    const on = b.dataset.ncPeriod === st.period;
    b.classList.toggle('active', on);
    b.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  body.querySelectorAll('.nc-rec-panel').forEach(function (p) {
    p.style.display = (p.dataset.ncType === st.type && p.dataset.ncPeriod === st.period) ? '' : 'none';
  });
}

document.addEventListener('click', function (e) {
  const btn = e.target.closest('#recNewChartsBody .nc-rec-tab, #recNewChartsBody .nc-rec-subtab');
  if (!btn) return;
  if (btn.dataset.ncType) localStorage.setItem('dc_nc_rec_type', btn.dataset.ncType);
  if (btn.dataset.ncPeriod) localStorage.setItem('dc_nc_rec_period', btn.dataset.ncPeriod);
  // A search owns what is on screen; switching pills is a way out of one, and
  // it should land on New Charts rather than on whichever section was stored
  // before the search started.
  if (recSearchQuery()) {
    localStorage.setItem('dc_records_active_view', 'recNewChartsSection');
    clearRecordsSearch();
    return;
  }
  applyNewChartsRecTabs();
  if (typeof window._refreshBackToTop === 'function') window._refreshBackToTop();
});

