function navigateToCrChart(period, periodKey) {
  hideCrPreview();
  const now = tzNow();
  let offset = 0;
  if (period === 'week') {
    const nowDow = now.getDay();
    const nowOffset = (nowDow - weekStartDay + 7) % 7;
    const curStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - nowOffset);
    const targetStart = new Date(periodKey + 'T00:00:00');
    offset = Math.round((curStart - targetStart) / (7 * 86400000));
  } else if (period === 'month') {
    const [yr, mo] = periodKey.split('-').map(Number);
    offset = (now.getFullYear() - yr) * 12 + (now.getMonth() + 1 - mo);
  } else if (period === 'year') {
    offset = now.getFullYear() - parseInt(periodKey);
  }
  if (currentPeriod !== period) {
    savedOffsets[currentPeriod] = currentOffset;
    currentPeriod = period;
    document.querySelectorAll('.period-nav button').forEach(b => b.classList.toggle('active', b.dataset.period === period));
  }
  currentOffset = Math.max(0, offset);
  pageState.songs = 0; pageState.artists = 0; pageState.albums = 0;
  renderAll();
}

// ─── MONTHLY CHART STATS ───────────────────────────────────────
// Returns months-on-chart counts, previous month's chart, and
// a set of items that ever charted before the current month.
function buildPeriodStats(period) {
  const now = tzNow();
  let curKey, prevKey;

  if (period === 'week') {
    curKey = currentViewWeekKey();
    const curStartDate = new Date(curKey + 'T00:00:00');
    const prevStart = new Date(curStartDate);
    prevStart.setDate(curStartDate.getDate() - 7);
    prevKey = localDateStr(prevStart);
  } else {
    const d = new Date(now.getFullYear(), now.getMonth() - currentOffset, 1);
    curKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    const prevD = new Date(d.getFullYear(), d.getMonth() - 1, 1);
    prevKey = `${prevD.getFullYear()}-${String(prevD.getMonth() + 1).padStart(2, '0')}`;
  }

  // Group all plays by period key
  const periodMap = {};
  for (const p of allPlays) {
    // Both branches read a cached stamp; neither needs a Date object built.
    const mk = period === 'week' ? playWeekKeyOf(p) : monthKeyOf(p);
    if (mk > curKey) continue; // ignore future periods
    if (!periodMap[mk]) periodMap[mk] = { songs: {}, artists: {}, albums: {} };
    const mm = periodMap[mk];
    const sk = songKey(p);
    if (!mm.songs[sk]) mm.songs[sk] = { count: 0, firstAchieved: p.date };
    mm.songs[sk].count++;
    for (const a of p.artists) {
      if (!mm.artists[a]) mm.artists[a] = { count: 0, firstAchieved: p.date };
      mm.artists[a].count++;
    }
    const ak = albumKeyOf(p);
    if (!mm.albums[ak]) mm.albums[ak] = { count: 0, firstAchieved: p.date };
    mm.albums[ak].count++;
  }

  const periodsOnChart = { songs: {}, artists: {}, albums: {} };
  const everChartedBefore = { songs: new Set(), artists: new Set(), albums: new Set() };
  const prevChart = { songs: {}, artists: {}, albums: {} };
  // Must track prev/ever sets in order to assign chartStatus for rankSortWithStatus,
  // so ties are broken by seniority — matching buildChartRun and the render functions exactly.
  const bpsEver = { songs: new Set(), artists: new Set(), albums: new Set() };
  const bpsPrev = { songs: new Map(), artists: new Map(), albums: new Map() };

  // Bubbling Under tracking: how many total weeks each entry has appeared in the BU zone,
  // and what each entry's count was in the previous period (for "plays away" delta).
  const bubblingUnderWeeks = { songs: {}, artists: {}, albums: {} };
  const bubblingUnderStreak = { songs: {}, artists: {}, albums: {} };
  // bubblingUnderRuns: how many separate BU stints an entry has had (incremented each time
  // it enters BU fresh after an absence — i.e. streak was 0 and is now becoming 1).
  const bubblingUnderRuns = { songs: {}, artists: {}, albums: {} };
  // bubblingUnderEntryFromChart: true if the current BU run started directly from a chart
  // position (song dropped from chart → BU without leaving BU). Used to distinguish
  // "Clinging" (still in BU after dropping from chart) from "Resurgent" (returned from
  // full absence of both chart and BU).
  const bubblingUnderEntryFromChart = { songs: {}, artists: {}, albums: {} };
  const prevBubblingUnder = { songs: {}, artists: {}, albums: {} };

  // Peak rank tracking: best (lowest) rank each entry ever achieved before the current period
  const peakRank = { songs: {}, artists: {}, albums: {} };

  // Chart streak: consecutive periods an entry has charted without a break —
  // resets to 0 the moment it drops, unlike periodsOnChart which accumulates
  // across separate stints. Snapshotted at prevKey so a dropout's row can show
  // how long the run that just ended actually was, not its lifetime total.
  const chartStreak = { songs: {}, artists: {}, albums: {} };
  const chartStreakAtPrev = { songs: {}, artists: {}, albums: {} };

  for (const [mk, mm] of Object.entries(periodMap).sort((a, b) => a[0].localeCompare(b[0]))) {
    for (const type of ['songs', 'artists', 'albums']) {
      // Use per-section chart size so each section's BU/prev-chart tracking matches what's rendered
      const _typeChartSize = type === 'songs' ? chartSizeSongs : type === 'artists' ? chartSizeArtists : chartSizeAlbums;
      const _bpsBuSize = _typeChartSize >= 100 ? 50 : 10;
      for (const [k, data] of Object.entries(mm[type])) {
        const prevRk = bpsPrev[type].get(k);
        data.chartStatus = prevRk !== undefined ? 0 : bpsEver[type].has(k) ? 1 : 2;
        data.prevRank = prevRk !== undefined ? prevRk : Infinity;
      }
      // Sort once — reused for both chart entries and BU zone entries
      const _bpsAllSorted = Object.entries(mm[type]).sort(([, a], [, b]) => rankSortWithStatus(a, b));
      const newPrev = new Map();
      _bpsAllSorted.slice(0, _typeChartSize).forEach(([k, data], i) => {
        newPrev.set(k, i + 1); bpsEver[type].add(k);
        periodsOnChart[type][k] = (periodsOnChart[type][k] || 0) + 1;
        chartStreak[type][k] = (chartStreak[type][k] || 0) + 1;
        if (mk < curKey) {
          everChartedBefore[type].add(k);
          if ((peakRank[type][k] ?? Infinity) > i + 1) peakRank[type][k] = i + 1;
        }
        if (mk === prevKey) prevChart[type][k] = { rank: i + 1, count: data.count };
      });
      // Reset the streak for anyone who was charting last period but dropped this
      // period, then snapshot at prevKey — the moment right before "now".
      for (const k of bpsPrev[type].keys()) {
        if (!newPrev.has(k)) chartStreak[type][k] = 0;
      }
      if (mk === prevKey) chartStreakAtPrev[type] = Object.assign({}, chartStreak[type]);
      // Track BU zone entries (ranks _typeChartSize+1 through _typeChartSize+buSize)
      const _buKeysThisPeriod = new Set();
      _bpsAllSorted.slice(_typeChartSize, _typeChartSize + _bpsBuSize).forEach(([k, data]) => {
        bubblingUnderWeeks[type][k] = (bubblingUnderWeeks[type][k] || 0) + 1;
        // New BU stint: streak was 0 (or never set) → increment the runs counter and
        // record whether entry came from a chart position (bpsPrev still holds last period's chart)
        if (!bubblingUnderStreak[type][k]) {
          bubblingUnderRuns[type][k] = (bubblingUnderRuns[type][k] || 0) + 1;
          bubblingUnderEntryFromChart[type][k] = bpsPrev[type].has(k);
        }
        bubblingUnderStreak[type][k] = (bubblingUnderStreak[type][k] || 0) + 1;
        _buKeysThisPeriod.add(k);
        if (mk === prevKey) prevBubblingUnder[type][k] = { count: data.count };
      });
      // Reset streak for entries that had a streak but are no longer in the BU zone
      for (const k of Object.keys(bubblingUnderStreak[type])) {
        if (!_buKeysThisPeriod.has(k)) bubblingUnderStreak[type][k] = 0;
      }
      bpsPrev[type] = newPrev;
    }
  }

  return { periodsOnChart, prevChart, everChartedBefore, bubblingUnderWeeks, bubblingUnderStreak, bubblingUnderRuns, bubblingUnderEntryFromChart, prevBubblingUnder, peakRank, chartStreakAtPrev };
}

function mPrevCell(curRank, key, type, ms) {
  const prev = ms.prevChart[type][key];
  if (!prev) {
    const isRe = ms.everChartedBefore[type].has(key);
    const badgeKey = isRe ? 'badge_re' : (type === 'songs' ? 'badge_new_songs' : 'badge_new');
    const label = t(badgeKey);
    return `<td class="m-col"><span class="m-${isRe ? 're' : 'new'}">${label}</span></td>`;
  }
  const diff = prev.rank - curRank; // positive = moved up
  if (diff === 0) return `<td class="m-col"><span class="m-same">=</span><div class="m-prev-rank">#${prev.rank}</div></td>`;
  const dir = diff > 0 ? 'up' : 'down';
  const arrow = diff > 0 ? '▲' : '▼';
  return `<td class="m-col"><span class="m-${dir}">${arrow}${Math.abs(diff)}</span><div class="m-prev-rank">#${prev.rank}</div></td>`;
}

// Inline delta badge — returns a <span> (no <td>) for embedding next to the play count
function deltaInline(curCount, key, type, ms) {
  const prev = ms.prevChart[type][key];
  if (!prev) {
    const isRe = ms.everChartedBefore[type].has(key);
    const badgeKey = isRe ? 'badge_re' : (type === 'songs' ? 'badge_new_songs' : 'badge_new');
    const label = t(badgeKey);
    return `<span class="m-${isRe ? 're' : 'new'}" style="font-size:0.6rem;margin-left:0.4rem">${label}</span>`;
  }
  const diff = curCount - prev.count;
  if (diff === 0) return `<span class="m-same" style="font-size:0.6rem;margin-left:0.4rem">=</span>`;
  const dir = diff > 0 ? 'up' : 'down';
  const sign = diff > 0 ? '+' : '';
  return `<span class="m-${dir}" style="font-size:0.6rem;margin-left:0.4rem">${sign}${diff}</span>`;
}

function mMthsCell(key, type, ms) {
  const n = ms.periodsOnChart[type][key] || 1;
  return `<td class="m-col"><span class="m-mths">${n}</span></td>`;
}

// ─── ALL-TIME PEAK MAPS ────────────────────────────────────────
// Peak positions are calculated within the top N (chartSize) only —
// so #1 all-time means #1 within whichever chart size is selected.
function buildAllTimePeaks() {
  // Songs — rank within top chartSize
  const sp = {};
  for (const p of allPlays) {
    const k = songKey(p);
    if (!sp[k]) sp[k] = { count: 0, firstAchieved: p.date };
    sp[k].count++;
  }
  const songsSorted = Object.entries(sp).sort(([, a], [, b]) => rankSort(a, b)).slice(0, chartSizeAllTime);
  const songPeakMap = {};
  songsSorted.forEach(([k], i) => { songPeakMap[k] = i + 1; });

  // Artists (split) — rank within top chartSizeAllTime
  const ap = {};
  for (const p of allPlays) {
    for (const a of p.artists) {
      if (!ap[a]) ap[a] = { count: 0, songs: new Set(), firstAchieved: p.date };
      ap[a].count++;
      ap[a].songs.add(p.title);
    }
  }
  const artistsSorted = Object.entries(ap).sort(([, a], [, b]) => rankSort(a, b)).slice(0, chartSizeAllTime);
  const artistPeakMap = {};
  artistsSorted.forEach(([name], i) => { artistPeakMap[name] = i + 1; });

  // Albums — rank within top chartSizeAllTime
  const lp = {};
  for (const p of allPlays) {
    const k = albumKeyOf(p);
    if (!lp[k]) lp[k] = { count: 0, firstAchieved: p.date };
    lp[k].count++;
  }
  const albumsSorted = Object.entries(lp).sort(([, a], [, b]) => rankSort(a, b)).slice(0, chartSizeAllTime);
  const albumPeakMap = {};
  albumsSorted.forEach(([k], i) => { albumPeakMap[k] = i + 1; });

  return { songPeakMap, artistPeakMap, albumPeakMap };
}

// ─── PERIOD-BASED PEAK MAPS ────────────────────────────────────
// For weekly charts: best rank ever achieved in any week up to and
// including the currently viewed week (no future weeks bleed in).
// Same logic applies to monthly and yearly.
function buildPeriodPeaks(period) {
  const now = tzNow();

  // Compute the key for the currently viewed period so we can ignore later ones
  let curKey;
  if (period === 'week') {
    curKey = currentViewWeekKey();
  } else if (period === 'month') {
    const d = new Date(now.getFullYear(), now.getMonth() - currentOffset, 1);
    curKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
  } else {
    curKey = String(now.getFullYear() - currentOffset);
  }

  const periodMap = {};

  for (const p of allPlays) {
    // All three branches read a cached stamp; none needs a Date object built.
    const key = period === 'week' ? playWeekKeyOf(p)
              : period === 'month' ? monthKeyOf(p)
              : yearKeyOf(p);

    if (key > curKey) continue; // ignore periods after the currently viewed one

    if (!periodMap[key]) periodMap[key] = { songs: {}, artists: {}, albums: {} };
    const pm = periodMap[key];

    const sk = songKey(p);
    if (!pm.songs[sk]) pm.songs[sk] = { count: 0, firstAchieved: p.date };
    pm.songs[sk].count++;

    for (const a of p.artists) {
      if (!pm.artists[a]) pm.artists[a] = { count: 0, firstAchieved: p.date };
      pm.artists[a].count++;
    }

    const ak = albumKeyOf(p);
    if (!pm.albums[ak]) pm.albums[ak] = { count: 0, firstAchieved: p.date };
    pm.albums[ak].count++;
  }

  const songPeakMap = {};
  const artistPeakMap = {};
  const albumPeakMap = {};

  // Must use rankSortWithStatus with proper prev/ever tracking so tie-breaking matches
  // what the render functions display — otherwise a seniority-based #2 could be recorded as #1.
  const ppEver = { songs: new Set(), artists: new Set(), albums: new Set() };
  const ppPrev = { songs: new Map(), artists: new Map(), albums: new Map() };

  for (const [pKey, pm] of Object.entries(periodMap).sort((a, b) => a[0].localeCompare(b[0]))) {
    if (pKey === curKey) continue; // current period handled by render reconciliation
    for (const type of ['songs', 'artists', 'albums']) {
      for (const [k, data] of Object.entries(pm[type])) {
        const prevRk = ppPrev[type].get(k);
        data.chartStatus = prevRk !== undefined ? 0 : ppEver[type].has(k) ? 1 : 2;
        data.prevRank = prevRk !== undefined ? prevRk : Infinity;
      }
      const newPrev = new Map();
      Object.entries(pm[type]).sort(([, a], [, b]) => rankSortWithStatus(a, b)).slice(0, chartSize).forEach(([k], i) => {
        newPrev.set(k, i + 1); ppEver[type].add(k);
        const rank = i + 1;
        if (type === 'songs') { if (!songPeakMap[k] || rank < songPeakMap[k]) songPeakMap[k] = rank; }
        if (type === 'artists') { if (!artistPeakMap[k] || rank < artistPeakMap[k]) artistPeakMap[k] = rank; }
        if (type === 'albums') { if (!albumPeakMap[k] || rank < albumPeakMap[k]) albumPeakMap[k] = rank; }
      });
      ppPrev[type] = newPrev;
    }
  }

  return { songPeakMap, artistPeakMap, albumPeakMap };
}

// Small badge shown on the play count when a period play count equals the all-time per-period peak.
function playsPeakBadge() {
  return `<span class="plays-peak-badge">▲ ${t('badge_plays_peak')}</span>`;
}

// Cumulative plays per song/album up to endDate (for period cert badges).
function buildCumulativeMapsForPeriod(endDate) {
  const songs = {};
  const albums = {};
  const songAlbumCounts = {}; // songKey → { albumKey → count }
  for (const p of allPlays) {
    if (p.date > endDate) continue;
    const sk = songKey(p);
    songs[sk] = (songs[sk] || 0) + 1;
    const ak = albumKeyOf(p);
    albums[ak] = (albums[ak] || 0) + 1;
    if (!songAlbumCounts[sk]) songAlbumCounts[sk] = {};
    songAlbumCounts[sk][ak] = (songAlbumCounts[sk][ak] || 0) + 1;
  }
  // Best album key per song: mirrors bestAlbum — prefer non-self-titled (i.e. album name ≠ song title),
  // then pick the most-played. This keeps the album cert badge consistent with the displayed album name.
  const songAlbumKey = {};
  for (const [sk, ac] of Object.entries(songAlbumCounts)) {
    const entries = Object.entries(ac).sort((a, b) => b[1] - a[1]);
    const songTitle = sk.split('|||')[0];
    const nonSingle = entries.filter(([ak]) => ak.split('|||')[0].toLowerCase().trim() !== songTitle);
    songAlbumKey[sk] = (nonSingle.length > 0 ? nonSingle[0][0] : entries[0][0]);
  }
  // Album plays keyed by album name only — used as fallback for songs with no prior history
  // (e.g. NEW entries that have no songAlbumKey yet).
  const albumsByName = {};
  for (const [ak, count] of Object.entries(albums)) {
    const name = ak.split('|||')[0];
    albumsByName[name] = (albumsByName[name] || 0) + count;
  }
  return { songs, albums, songAlbumKey, albumsByName };
}

// Historical max per-period play counts, excluding the currently viewed period.
// Used to decide whether the current period is a plays-peak for a song/artist/album.
function buildPlaysPeakMaps(period) {
  // The chart run already grouped the whole history into exactly these
  // per-period, per-item counts and cached it, so read that instead of
  // walking allPlays a second time. Read-only: nothing here writes to it.
  const curKey = _crCurKey(period);
  const periodMap = _crFull(period).periodMap;

  const songs = {}, artists = {}, albums = {};
  for (const pKey in periodMap) {
    if (pKey > curKey) continue;   // periods after the one being viewed don't count
    if (pKey === curKey) continue; // current period handled at render time
    const pm = periodMap[pKey];
    for (const k in pm.songs)   { const c = pm.songs[k].count;   if (c > (songs[k]   || 0)) songs[k]   = c; }
    for (const k in pm.artists) { const c = pm.artists[k].count; if (c > (artists[k] || 0)) artists[k] = c; }
    for (const k in pm.albums)  { const c = pm.albums[k].count;  if (c > (albums[k]  || 0)) albums[k]  = c; }
  }
  return { songs, artists, albums };
}

function buildPeaks() {
  if (currentPeriod === 'week' || currentPeriod === 'month' || currentPeriod === 'year') {
    return buildPeriodPeaks(currentPeriod);
  }
  return buildAllTimePeaks();
}

function peakBadge(peak) {
  if (!peak || peak === '—') return '';
  const peakLabel = t('peak_label');
  if (peak === 1 && currentPeriod === 'alltime') return `<span class="peak-badge-1">★ ALL-TIME #1</span>`;
  if (peak === 1) return `<span class="peak-badge-1">${peakLabel} #1</span>`;
  if (peak === 2) return `<span class="peak-badge-2">${peakLabel} #2</span>`;
  if (peak === 3) return `<span class="peak-badge-3">${peakLabel} #3</span>`;
  return `<span class="peak-badge">${peakLabel} #${peak}</span>`;
}

// Line-icon for chart-run toggle buttons — replaces the old 📊 emoji so it reads as
// a UI control rather than a colorful pictograph; three ascending bars = "stats/history".
const CR_ICON = '<svg class="cr-icon" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M3 13V9"/><path d="M8 13V5"/><path d="M13 13V7"/></svg>';

function renderSongs(plays, peaks, monthlyStats) {
  const counts = {};
  for (const p of plays) {
    const k = songKey(p);
    if (!counts[k]) counts[k] = { title: p.title, artist: p.artist, album: p.album, count: 0, _albums: {}, firstAchieved: p.date };
    counts[k].count++;
    counts[k]._albums[p.album] = (counts[k]._albums[p.album] || 0) + 1;
  }
  for (const entry of Object.values(counts)) {
    entry.album = bestAlbum(entry.title, entry._albums);
    delete entry._albums;
    if (monthlyStats) {
      const k = songKey(entry);
      const prev = monthlyStats.prevChart.songs[k];
      entry.chartStatus = prev ? 0 : monthlyStats.everChartedBefore.songs.has(k) ? 1 : 2;
      entry.prevRank = prev ? prev.rank : Infinity;
    }
  }
  // Sort once; BU pool is the slice just beyond chartSize
  const _buSizeSongs = chartSize >= 100 ? 50 : 10;
  const _allSortedSongs = Object.values(counts).sort(monthlyStats ? rankSortWithStatus : rankSort);
  const sorted = _allSortedSongs.slice(0, chartSize);
  const _buPoolSongs = (currentPeriod === 'week' && monthlyStats) ? _allSortedSongs.slice(chartSize, chartSize + _buSizeSongs) : [];
  fullData.songs = sorted;
  // Reconcile peak map: current period was excluded from buildPeriodPeaks (which uses rankSort),
  // so apply the actual rendered rank here. Take the min vs any historical peak from past periods.
  if (currentPeriod !== 'alltime') {
    sorted.forEach((s, i) => { const k = songKey(s); const r = i + 1; peaks.songPeakMap[k] = peaks.songPeakMap[k] ? Math.min(peaks.songPeakMap[k], r) : r; });
  }
  const max = sorted[0]?.count || 1;
  if (currentPeriod === 'week') {
    _weeklyViewSongs = sorted; _weeklyViewMax = max;
    _weeklyViewPeaks = peaks; _weeklyViewMonthlyStats = monthlyStats;
  }
  const isAllTime = currentPeriod === 'alltime';
  const colCount = monthlyStats ? 8 : 6; // +1 for the trailing chart-run icon column
  const imgItems = [];
  const _prevMapSongs = buildPrevRankMap(_animPrevPlays, 'songs');
  const _animSongs = _animPrevPlays !== null;
  const currPairsS = sorted.map((s, i) => {
    const k = songKey(s);
    const pk = !isAllTime ? peaks.songPeakMap[k] : null;
    const imgId = 'simg-' + i;
    const prefKey = 'song:' + s.artist.toLowerCase() + '|||' + s.title.toLowerCase();
    const rowId = 'crr-song-' + i;
    imgItems.push({ imgId, title: s.title, artist: s.artist, album: s.album, type: 'song', prefKey });
    const cumSongPlays = cumulativeMaps ? (cumulativeMaps.songs[k] || 0) : s.count;
    const cumAlbumPlays = cumulativeMaps && s.album ? (cumulativeMaps.albumsByName[s.album] || 0) : 0;
    const histMaxSong = playsPeakMaps ? (playsPeakMaps.songs[k] || 0) : 0;
    const isPlaysPeak = !isAllTime && histMaxSong > 0 && s.count >= histMaxSong;
    const _sPrev = monthlyStats ? monthlyStats.prevChart.songs[k] : null;
    const barCls = !monthlyStats ? '' : !_sPrev && !monthlyStats.everChartedBefore.songs.has(k) ? ' wv-bar-new' : !_sPrev ? ' wv-bar-re' : (_sPrev.rank-(i+1)) > 0 ? ' wv-bar-up' : (_sPrev.rank-(i+1)) < 0 ? ' wv-bar-down' : '';
    const statusCls = barCls === ' wv-bar-new' ? ' wv-row-new' : barCls === ' wv-bar-re' ? ' wv-row-re' : '';
    const _prevIdxS = _animSongs ? (_prevMapSongs[k] ?? chartSize * 2) : 0;
    const _crsiOffsetS = _animSongs ? Math.max(-200, Math.min(200, (_prevIdxS - i) * 38)) : 0;
    const _animAttrsS = _animSongs ? ` style="--crsi-offset:${_crsiOffsetS}px;--crsi-delay:${i * 50}ms"` : '';
    const _animClassS = _animSongs ? ' chart-row-anim' : '';
    const _songModalClass = (isAllTime || currentPeriod === 'year') ? ' song-row' : '';
    const _songModalAttr = (isAllTime || currentPeriod === 'year') ? ` data-songkey="${encodeURIComponent(k)}"` : '';
    const mainRow = `<tr${_animAttrsS}${_songModalAttr} class="${i === 0 ? 'rank-1' : i === 1 ? 'rank-2' : i === 2 ? 'rank-3' : ''}${_animClassS}${_songModalClass}${statusCls}">
      <td class="rank-cell">${i + 1}</td>
      ${monthlyStats ? mPrevCell(i + 1, k, 'songs', monthlyStats) : ''}
      <td class="thumb-cell"><div class="thumb-wrap"><div id="${imgId}"><div class="thumb-initials">${esc(initials(s.title))}</div></div><button id="srcbtn-${imgId}" class="img-src-btn" data-imgid="${imgId}" data-type="song" data-prefkey="${esc(prefKey)}" data-name="${esc(s.title)}" data-artist="${esc(s.artist)}" data-album="${esc(s.album)}">${srcLabel(itemSourcePrefs[prefKey] || 'deezer')}</button></div></td>
      <td>
        <div class="song-title">${esc(s.title)}${pk ? peakBadge(pk) : ''}${certBadge(cumSongPlays, 'song')}</div>
        <div class="song-artist">${esc(s.artist)}</div>
        <button class="yt-play-btn" data-title="${esc(s.title)}" data-artist="${esc(s.artist)}" data-album="${esc(s.album)}" onclick="event.stopPropagation();ytPlayFromBtn(this)" title="Play on YouTube"><span class="yt-btn-content"><svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>YouTube</span></button>${dcPlBtnHtml('song', s.title, s.artist, s.album)}
      </td>
      <td class="meta-col"><div class="song-album">${esc(s.album)}${cumAlbumPlays ? certBadge(cumAlbumPlays, 'album') : ''}</div></td>
      ${monthlyStats ? mMthsCell(k, 'songs', monthlyStats) : ''}
      <td>
        <div class="play-count">${tCountHtml('plays', s.count)}${monthlyStats ? deltaInline(s.count, k, 'songs', monthlyStats) : ''}</div>
        <div class="play-bar"><div class="play-bar-fill${barCls}" style="width:${Math.round(s.count / max * 100)}%"></div></div>
        ${isPlaysPeak ? playsPeakBadge() : ''}
      </td>
      <td class="cr-cell"><button class="cr-toggle-btn" title="${t('tooltip_cr_toggle_btn_song')}" onclick="event.stopPropagation();toggleChartRun(this,'${rowId}')">${CR_ICON}</button></td>
    </tr>`;
    const expandRow = `<tr class="cr-row" id="${rowId}"><td colspan="${colCount}"><div class="cr-panel" data-crtype="songs" data-crkey="${encodeURIComponent(k)}">${buildCrPanelHTML('songs', k)}</div></td></tr>`;
    return [mainRow, expandRow];
  });
  const sbodyS = document.getElementById('songsBody');
  if (sbodyS._visObs) { sbodyS._visObs.disconnect(); delete sbodyS._visObs; }
  if (_animSongs) {
    const _capPrevS = _animPrevPlays, _capCurrS = _animCurrentPlays;
    const _prevEntriesS = buildPrevSortedEntries(_capPrevS, 'songs');
    const _startAnimS = () => {
      if (sbodyS._swToken) sbodyS._swToken.cancelled = true;
      sbodyS.innerHTML = buildPrevChartHtml(_prevEntriesS, sorted.length, colCount, 'songs');
      loadImages(_prevEntriesS.map((e, i) => ({ imgId: `pwsimg-${i}`, title: e.title, artist: e.artist, album: e.album, type: 'song', prefKey: 'song:' + e.artist.toLowerCase() + '|||' + e.title.toLowerCase(), name: e.title })), 'song');
      runSlideWindowAnim(sbodyS, 'songs', _capPrevS, _capCurrS, () => {
        for (const tr of sbodyS.querySelectorAll('tr[data-chartkey]')) {
          tr.style.transition = 'opacity 0.35s ease';
          tr.style.opacity = '0.75';
        }
        setTimeout(() => {
          sbodyS.innerHTML = currPairsS.flatMap(p => p).join('');
          loadImages(imgItems.map(i => ({ ...i, name: i.title })), 'song');
        }, 380);
      });
    };
    // Always register the manual replay function so ▶ Animate Chart works
    // even with auto-play-on-load off — only the observer below is gated.
    _replayFns['songs'] = _startAnimS;
    if (chartAnimEnabled) {
      sbodyS.innerHTML = buildPrevChartHtml(_prevEntriesS, sorted.length, colCount, 'songs');
      const _obsS = new IntersectionObserver(([entry]) => {
        if (!entry.isIntersecting) return;
        _obsS.disconnect();
        delete sbodyS._visObs;
        _startAnimS();
      }, { threshold: 0 });
      sbodyS._visObs = _obsS;
      _obsS.observe(sbodyS);
    } else {
      sbodyS.innerHTML = currPairsS.flatMap(p => p).join('');
      loadImages(imgItems.map(i => ({ ...i, name: i.title })), 'song');
    }
  } else {
    delete _replayFns['songs'];
    sbodyS.innerHTML = currPairsS.flatMap(p => p).join('');
    loadImages(imgItems.map(i => ({ ...i, name: i.title })), 'song');
  }
  const playAllRow = document.getElementById('ytPlayAllRow');
  if (playAllRow) playAllRow.style.display = sorted.length > 0 ? '' : 'none';
  if (currentPeriod === 'week') applyWeeklyChartView('songs');
  // Render Bubbling Under section (weekly only, requires history stats)
  if (currentPeriod === 'week' && monthlyStats) {
    const _buNormSongs = _buPoolSongs.map(s => ({
      key: songKey(s), displayName: s.title, subName: s.artist, album: s.album, count: s.count
    }));
    renderBubblingUnder('songs', _buNormSongs, monthlyStats, sorted[sorted.length - 1]?.count || 0);
    renderOffChart('songs', plays, monthlyStats, _buNormSongs, sorted[sorted.length - 1]?.count || 0);
  } else {
    hideBuSection('songs');
    hideOffSection('songs');
  }
}

function renderArtists(plays, peaks, monthlyStats) {
  const counts = {};
  for (const p of plays) {
    for (const artist of p.artists) {
      if (!counts[artist]) counts[artist] = { count: 0, songs: new Set(), firstAchieved: p.date };
      counts[artist].count++;
      counts[artist].songs.add(p.title);
    }
  }
  if (monthlyStats) {
    for (const [artist, data] of Object.entries(counts)) {
      const prev = monthlyStats.prevChart.artists[artist];
      data.chartStatus = prev ? 0 : monthlyStats.everChartedBefore.artists.has(artist) ? 1 : 2;
      data.prevRank = prev ? prev.rank : Infinity;
    }
  }
  // Sort once; BU pool is the slice just beyond chartSize
  const _buSizeArtists = chartSize >= 100 ? 50 : 10;
  const _allSortedArtists = Object.entries(counts).sort(([, a], [, b]) => monthlyStats ? rankSortWithStatus(a, b) : rankSort(a, b));
  const sorted = _allSortedArtists.slice(0, chartSize);
  const _buPoolArtists = (currentPeriod === 'week' && monthlyStats) ? _allSortedArtists.slice(chartSize, chartSize + _buSizeArtists) : [];
  fullData.artists = sorted.map(([name, data]) => ({ name, ...data }));
  // Reconcile peak map with actual chart ranks (current period excluded from buildPeriodPeaks)
  if (currentPeriod !== 'alltime') {
    sorted.forEach(([artist], i) => { const r = i + 1; peaks.artistPeakMap[artist] = peaks.artistPeakMap[artist] ? Math.min(peaks.artistPeakMap[artist], r) : r; });
  }
  const max = sorted[0]?.[1].count || 1;
  if (currentPeriod === 'week') { _weeklyViewArtists = fullData.artists; _weeklyViewArtistsMax = max; }
  const isAllTime = currentPeriod === 'alltime';
  const colCount = monthlyStats ? 8 : 6; // +1 for the trailing chart-run icon column
  const imgItems = [];
  const _prevMapArtists = buildPrevRankMap(_animPrevPlays, 'artists');
  const _animArtists = _animPrevPlays !== null;
  const currPairsA = sorted.map(([artist, data], i) => {
    const pk = !isAllTime ? peaks.artistPeakMap[artist] : null;
    const imgId = 'aimg-' + i;
    const prefKey = 'artist:' + artist.toLowerCase();
    const rowId = 'crr-artist-' + i;
    imgItems.push({ imgId, name: artist, prefKey });
    const histMaxArtist = playsPeakMaps ? (playsPeakMaps.artists[artist] || 0) : 0;
    const isPlaysPeak = !isAllTime && histMaxArtist > 0 && data.count >= histMaxArtist;
    const _aPrev = monthlyStats ? monthlyStats.prevChart.artists[artist] : null;
    const barCls = !monthlyStats ? '' : !_aPrev && !monthlyStats.everChartedBefore.artists.has(artist) ? ' wv-bar-new' : !_aPrev ? ' wv-bar-re' : (_aPrev.rank-(i+1)) > 0 ? ' wv-bar-up' : (_aPrev.rank-(i+1)) < 0 ? ' wv-bar-down' : '';
    const statusCls = barCls === ' wv-bar-new' ? ' wv-row-new' : barCls === ' wv-bar-re' ? ' wv-row-re' : '';
    const _prevIdxA = _animArtists ? (_prevMapArtists[artist] ?? chartSize * 2) : 0;
    const _crsiOffsetA = _animArtists ? Math.max(-200, Math.min(200, (_prevIdxA - i) * 38)) : 0;
    const _animAttrsA = _animArtists ? ` style="--crsi-offset:${_crsiOffsetA}px;--crsi-delay:${i * 50}ms"` : '';
    const _animClassA = _animArtists ? ' chart-row-anim' : '';
    const mainRow = `<tr${_animAttrsA} class="${i === 0 ? 'rank-1' : i === 1 ? 'rank-2' : i === 2 ? 'rank-3' : ''}${_animClassA} artist-row${statusCls}" data-artist="${esc(artist)}">
      <td class="rank-cell">${i + 1}</td>
      ${monthlyStats ? mPrevCell(i + 1, artist, 'artists', monthlyStats) : ''}
      <td class="thumb-cell"><div class="thumb-wrap"><div id="${imgId}"><div class="thumb-initials">${esc(initials(artist))}</div></div><button id="srcbtn-${imgId}" class="img-src-btn" data-imgid="${imgId}" data-type="artist" data-prefkey="${esc(prefKey)}" data-name="${esc(artist)}" data-artist="${esc(artist)}" data-album="">${srcLabel(itemSourcePrefs[prefKey] || 'deezer')}</button></div></td>
      <td><div class="song-title">${esc(artist)}${pk ? peakBadge(pk) : ''}</div><button class="yt-play-btn" data-title="" data-artist="${esc(artist)}" data-album="" onclick="event.stopPropagation();buShowTrackList(this,'artists')" title="Show recently played tracks"><span class="yt-btn-content"><svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>YouTube</span></button>${dcPlBtnHtml('artist', '', artist, '')}</td>
      <td class="meta-col"><div class="song-artist">${tCount('songs', data.songs.size)}</div></td>
      ${monthlyStats ? mMthsCell(artist, 'artists', monthlyStats) : ''}
      <td>
        <div class="play-count">${isPlaysPeak ? playsPeakBadge() : ''}${tCountHtml('plays', data.count)}${monthlyStats ? deltaInline(data.count, artist, 'artists', monthlyStats) : ''}</div>
        <div class="play-bar"><div class="play-bar-fill${barCls}" style="width:${Math.round(data.count / max * 100)}%"></div></div>
      </td>
      <td class="cr-cell"><button class="cr-toggle-btn" title="${t('tooltip_cr_toggle_btn_artist')}" onclick="event.stopPropagation();toggleChartRun(this,'${rowId}')">${CR_ICON}</button></td>
    </tr>`;
    const expandRow = `<tr class="cr-row" id="${rowId}"><td colspan="${colCount}"><div class="cr-panel" data-crtype="artists" data-crkey="${encodeURIComponent(artist)}">${buildCrPanelHTML('artists', artist)}</div></td></tr>`;
    return [mainRow, expandRow];
  });
  const sbodyA = document.getElementById('artistsBody');
  if (sbodyA._visObs) { sbodyA._visObs.disconnect(); delete sbodyA._visObs; }
  if (_animArtists) {
    const _capPrevA = _animPrevPlays, _capCurrA = _animCurrentPlays;
    const _prevEntriesA = buildPrevSortedEntries(_capPrevA, 'artists');
    const _startAnimA = () => {
      if (sbodyA._swToken) sbodyA._swToken.cancelled = true;
      sbodyA.innerHTML = buildPrevChartHtml(_prevEntriesA, sorted.length, colCount, 'artists');
      loadImages(_prevEntriesA.map((e, i) => ({ imgId: `pwaimg-${i}`, name: e.name, prefKey: 'artist:' + e.name.toLowerCase() })), 'artist');
      runSlideWindowAnim(sbodyA, 'artists', _capPrevA, _capCurrA, () => {
        for (const tr of sbodyA.querySelectorAll('tr[data-chartkey]')) {
          tr.style.transition = 'opacity 0.35s ease';
          tr.style.opacity = '0.75';
        }
        setTimeout(() => {
          sbodyA.innerHTML = currPairsA.flatMap(p => p).join('');
          loadImages(imgItems, 'artist');
        }, 380);
      });
    };
    // Always register the manual replay function so ▶ Animate Chart works
    // even with auto-play-on-load off — only the observer below is gated.
    _replayFns['artists'] = _startAnimA;
    if (chartAnimEnabled) {
      sbodyA.innerHTML = buildPrevChartHtml(_prevEntriesA, sorted.length, colCount, 'artists');
      const _obsA = new IntersectionObserver(([entry]) => {
        if (!entry.isIntersecting) return;
        _obsA.disconnect();
        delete sbodyA._visObs;
        _startAnimA();
      }, { threshold: 0 });
      sbodyA._visObs = _obsA;
      _obsA.observe(sbodyA);
    } else {
      sbodyA.innerHTML = currPairsA.flatMap(p => p).join('');
      loadImages(imgItems, 'artist');
    }
  } else {
    delete _replayFns['artists'];
    sbodyA.innerHTML = currPairsA.flatMap(p => p).join('');
    loadImages(imgItems, 'artist');
  }
  if (currentPeriod === 'week') applyWeeklyChartView('artists');
  // Render Bubbling Under section (weekly only, requires history stats)
  if (currentPeriod === 'week' && monthlyStats) {
    const _buNormArtists = _buPoolArtists.map(([name, data]) => ({
      key: name, displayName: name, subName: '', count: data.count
    }));
    renderBubblingUnder('artists', _buNormArtists, monthlyStats, sorted[sorted.length - 1]?.[1].count || 0);
    renderOffChart('artists', plays, monthlyStats, _buNormArtists, sorted[sorted.length - 1]?.[1].count || 0);
  } else {
    hideBuSection('artists');
    hideOffSection('artists');
  }
}

function renderAlbums(plays, peaks, monthlyStats) {
  const counts = {};
  for (const p of plays) {
    const k = albumKeyOf(p);
    if (!counts[k]) counts[k] = { album: p.album, artist: albumArtist(p), count: 0, tracks: new Set(), firstAchieved: p.date };
    counts[k].count++;
    counts[k].tracks.add(p.title);
  }
  if (monthlyStats) {
    for (const [k, entry] of Object.entries(counts)) {
      const prev = monthlyStats.prevChart.albums[k];
      entry.chartStatus = prev ? 0 : monthlyStats.everChartedBefore.albums.has(k) ? 1 : 2;
      entry.prevRank = prev ? prev.rank : Infinity;
    }
  }
  // Sort once; BU pool is the slice just beyond chartSize
  const _buSizeAlbums = chartSize >= 100 ? 50 : 10;
  const _allSortedAlbums = Object.values(counts).filter(a => a.album && a.album !== '—').sort(monthlyStats ? rankSortWithStatus : rankSort);
  const sorted = _allSortedAlbums.slice(0, chartSize);
  const _buPoolAlbums = (currentPeriod === 'week' && monthlyStats) ? _allSortedAlbums.slice(chartSize, chartSize + _buSizeAlbums) : [];
  fullData.albums = sorted;
  // Reconcile peak map with actual chart ranks (current period excluded from buildPeriodPeaks)
  if (currentPeriod !== 'alltime') {
    sorted.forEach(({ album, artist }, i) => { const ak = album + '|||' + artist; const r = i + 1; peaks.albumPeakMap[ak] = peaks.albumPeakMap[ak] ? Math.min(peaks.albumPeakMap[ak], r) : r; });
  }
  const max = sorted[0]?.count || 1;
  if (currentPeriod === 'week') { _weeklyViewAlbums = fullData.albums; _weeklyViewAlbumsMax = max; }
  const isAllTime = currentPeriod === 'alltime';
  const colCount = monthlyStats ? 8 : 6; // +1 for the trailing chart-run icon column
  const imgItems = [];
  const _prevMapAlbums = buildPrevRankMap(_animPrevPlays, 'albums');
  const _animAlbums = _animPrevPlays !== null;
  if (sorted.length === 0) {
    document.getElementById('albumsBody').innerHTML = `<tr><td colspan="${colCount}"><div class="empty-state"><p>${t('empty_no_album_data_csv')}</p></div></td></tr>`;
  } else {
    const currPairsL = sorted.map(({ album, artist, count, tracks }, i) => {
      const ak = album + '|||' + artist;
      const pk = !isAllTime ? peaks.albumPeakMap[ak] : null;
      const imgId = 'limg-' + i;
      const prefKey = 'album:' + artist.toLowerCase() + '|||' + album.toLowerCase();
      const rowId = 'crr-album-' + i;
      imgItems.push({ imgId, album, artist, name: album, prefKey });
      const cumAlbumPlays = cumulativeMaps ? (cumulativeMaps.albums[ak] || 0) : count;
      const histMaxAlbum = playsPeakMaps ? (playsPeakMaps.albums[ak] || 0) : 0;
      const isPlaysPeak = !isAllTime && histMaxAlbum > 0 && count >= histMaxAlbum;
      const _lPrev = monthlyStats ? monthlyStats.prevChart.albums[ak] : null;
      const barCls = !monthlyStats ? '' : !_lPrev && !monthlyStats.everChartedBefore.albums.has(ak) ? ' wv-bar-new' : !_lPrev ? ' wv-bar-re' : (_lPrev.rank-(i+1)) > 0 ? ' wv-bar-up' : (_lPrev.rank-(i+1)) < 0 ? ' wv-bar-down' : '';
      const statusCls = barCls === ' wv-bar-new' ? ' wv-row-new' : barCls === ' wv-bar-re' ? ' wv-row-re' : '';
      const _prevIdxL = _animAlbums ? (_prevMapAlbums[ak] ?? chartSize * 2) : 0;
      const _crsiOffsetL = _animAlbums ? Math.max(-200, Math.min(200, (_prevIdxL - i) * 38)) : 0;
      const _animAttrsL = _animAlbums ? ` style="--crsi-offset:${_crsiOffsetL}px;--crsi-delay:${i * 50}ms"` : '';
      const _animClassL = _animAlbums ? ' chart-row-anim' : '';
      const mainRow = `<tr${_animAttrsL} class="${i === 0 ? 'rank-1' : i === 1 ? 'rank-2' : i === 2 ? 'rank-3' : ''}${_animClassL} album-row${statusCls}" data-albumkey="${esc(ak)}">
      <td class="rank-cell">${i + 1}</td>
      ${monthlyStats ? mPrevCell(i + 1, ak, 'albums', monthlyStats) : ''}
      <td class="thumb-cell"><div class="thumb-wrap"><div id="${imgId}"><div class="thumb-initials">${esc(initials(album))}</div></div><button id="srcbtn-${imgId}" class="img-src-btn" data-imgid="${imgId}" data-type="album" data-prefkey="${esc(prefKey)}" data-name="${esc(album)}" data-artist="${esc(artist)}" data-album="${esc(album)}">${srcLabel(itemSourcePrefs[prefKey] || 'deezer')}</button></div></td>
      <td>
        <div class="song-title">${esc(album)}${pk ? peakBadge(pk) : ''}${certBadge(cumAlbumPlays, 'album')}</div>
        <div class="song-artist">${esc(artist)}</div>
        <button class="yt-play-btn" data-title="" data-artist="${esc(artist)}" data-album="${esc(album)}" onclick="event.stopPropagation();buShowTrackList(this,'albums')" title="Show recently played tracks"><span class="yt-btn-content"><svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>YouTube</span></button>${dcPlBtnHtml('album', '', artist, album)}
      </td>
      <td class="meta-col"><div class="song-artist">${tCount('tracks', tracks.size)}</div></td>
      ${monthlyStats ? mMthsCell(ak, 'albums', monthlyStats) : ''}
      <td>
        <div class="play-count">${isPlaysPeak ? playsPeakBadge() : ''}${tCountHtml('plays', count)}${monthlyStats ? deltaInline(count, ak, 'albums', monthlyStats) : ''}</div>
        <div class="play-bar"><div class="play-bar-fill${barCls}" style="width:${Math.round(count / max * 100)}%"></div></div>
      </td>
      <td class="cr-cell"><button class="cr-toggle-btn" title="${t('tooltip_cr_toggle_btn_album')}" onclick="event.stopPropagation();toggleChartRun(this,'${rowId}')">${CR_ICON}</button></td>
    </tr>`;
      const expandRow = `<tr class="cr-row" id="${rowId}"><td colspan="${colCount}"><div class="cr-panel" data-crtype="albums" data-crkey="${encodeURIComponent(ak)}">${buildCrPanelHTML('albums', ak)}</div></td></tr>`;
      return [mainRow, expandRow];
    });
    const sbodyL = document.getElementById('albumsBody');
    if (sbodyL._visObs) { sbodyL._visObs.disconnect(); delete sbodyL._visObs; }
    if (_animAlbums) {
      const _capPrevL = _animPrevPlays, _capCurrL = _animCurrentPlays;
      const _prevEntriesL = buildPrevSortedEntries(_capPrevL, 'albums');
      const _startAnimL = () => {
        if (sbodyL._swToken) sbodyL._swToken.cancelled = true;
        sbodyL.innerHTML = buildPrevChartHtml(_prevEntriesL, sorted.length, colCount, 'albums');
        loadImages(_prevEntriesL.map((e, i) => ({ imgId: `pwlimg-${i}`, album: e.album, artist: e.artist, name: e.album, prefKey: 'album:' + (e.album + '|||' + e.artist).toLowerCase() })), 'album');
        runSlideWindowAnim(sbodyL, 'albums', _capPrevL, _capCurrL, () => {
          for (const tr of sbodyL.querySelectorAll('tr[data-chartkey]')) {
            tr.style.transition = 'opacity 0.35s ease';
            tr.style.opacity = '0.75';
          }
          setTimeout(() => {
            sbodyL.innerHTML = currPairsL.flatMap(p => p).join('');
            loadImages(imgItems, 'album');
          }, 380);
        });
      };
      // Always register the manual replay function so ▶ Animate Chart works
      // even with auto-play-on-load off — only the observer below is gated.
      _replayFns['albums'] = _startAnimL;
      if (chartAnimEnabled) {
        sbodyL.innerHTML = buildPrevChartHtml(_prevEntriesL, sorted.length, colCount, 'albums');
        const _obsL = new IntersectionObserver(([entry]) => {
          if (!entry.isIntersecting) return;
          _obsL.disconnect();
          delete sbodyL._visObs;
          _startAnimL();
        }, { threshold: 0 });
        sbodyL._visObs = _obsL;
        _obsL.observe(sbodyL);
      } else {
        sbodyL.innerHTML = currPairsL.flatMap(p => p).join('');
        loadImages(imgItems, 'album');
      }
    } else {
      delete _replayFns['albums'];
      sbodyL.innerHTML = currPairsL.flatMap(p => p).join('');
      loadImages(imgItems, 'album');
    }
  }
  if (currentPeriod === 'week') applyWeeklyChartView('albums');
  // Render Bubbling Under section (weekly only, requires history stats)
  if (currentPeriod === 'week' && monthlyStats) {
    const _buNormAlbums = _buPoolAlbums.map(a => ({
      key: a.album + '|||' + albumArtist(a), displayName: a.album, subName: albumArtist(a), count: a.count
    }));
    renderBubblingUnder('albums', _buNormAlbums, monthlyStats, sorted[sorted.length - 1]?.count || 0);
    renderOffChart('albums', plays, monthlyStats, _buNormAlbums, sorted[sorted.length - 1]?.count || 0);
  } else {
    hideBuSection('albums');
    hideOffSection('albums');
  }
}

// ─── BUBBLING UNDER CHART RUN ────────────────────────────────────
// Cached result of buildBuChartRun(); reset to null on each new render cycle.
let buChartRunData = null;

// Builds a weekly chart-run history for the BU zone (ranks chartSize+1 through chartSize+buSize).
// Uses the same chartStatus/rankSortWithStatus logic as buildChartRun so rankings match.
/* Builds the BU run across the whole history, with no cutoff — the same
   prefix property as the main chart run (see _buildChartRunFull) makes the
   viewed period a slice rather than a rebuild.

   The BU zone is defined relative to chartSize, so the run genuinely depends
   on it and the cache is keyed on it. That mirrors the existing behaviour:
   buildBuChartRun() is called once per render behind an `if (!buChartRunData)`
   guard, so it has always used whichever chartSize was current at that moment. */
function _buildBuChartRunFull(size) {
  const buSize = size >= 100 ? 50 : 10;

  // Collect weekly play counts for all entries
  const periodMap = {};
  for (const p of allPlays) {
    const pk = playWeekKeyOf(p);
    if (!periodMap[pk]) periodMap[pk] = { songs: {}, artists: {}, albums: {} };
    const pm = periodMap[pk];
    const sk = songKey(p);
    if (!pm.songs[sk]) pm.songs[sk] = { count: 0, firstAchieved: p.date, _title: p.title, _artist: p.artist };
    pm.songs[sk].count++;
    for (const a of p.artists) {
      if (!pm.artists[a]) pm.artists[a] = { count: 0, firstAchieved: p.date };
      pm.artists[a].count++;
    }
    const ak = albumKeyOf(p);
    if (!pm.albums[ak]) pm.albums[ak] = { count: 0, firstAchieved: p.date };
    pm.albums[ak].count++;
  }

  const result = { songs: {}, artists: {}, albums: {} };
  // Stores BU zone snapshot per week for the tooltip preview (key → { songs: [], artists: [], albums: [] })
  const buPeriodMap = {};
  // Track prev/ever chart sets so chartStatus matches the main render functions
  const prevChartKeys = { songs: new Map(), artists: new Map(), albums: new Map() };
  const everChartedKeys = { songs: new Set(), artists: new Set(), albums: new Set() };

  for (const pk of Object.keys(periodMap).sort()) {
    const pm = periodMap[pk];
    const lbl = crPeriodLabel('week', pk);
    for (const type of ['songs', 'artists', 'albums']) {
      // Assign chartStatus so the sort matches how the main render functions rank entries
      for (const [k, data] of Object.entries(pm[type])) {
        const prevRk = prevChartKeys[type].get(k);
        data.chartStatus = prevRk !== undefined ? 0 : everChartedKeys[type].has(k) ? 1 : 2;
        data.prevRank = prevRk !== undefined ? prevRk : Infinity;
      }
      const allSorted = Object.entries(pm[type]).sort(([, a], [, b]) => rankSortWithStatus(a, b));
      // Update chart-zone prev/ever sets for the next period
      const newPrev = new Map();
      allSorted.slice(0, size).forEach(([k], i) => { newPrev.set(k, i + 1); everChartedKeys[type].add(k); });
      prevChartKeys[type] = newPrev;
      // Record BU zone entries (buRank 1 = just below the chart, highest possible position in BU)
      if (!buPeriodMap[pk]) buPeriodMap[pk] = { songs: [], artists: [], albums: [] };
      allSorted.slice(size, size + buSize).forEach(([k, data], i) => {
        const buRank = i + 1;
        const displayName = type === 'songs' ? (data._title || k.split('|||')[0]) : k.split('|||')[0];
        buPeriodMap[pk][type].push({ key: k, buRank, plays: data.count, displayName });
        if (!result[type][k]) result[type][k] = { entries: [], peakBuRank: buRank, peakPlays: 0 };
        result[type][k].entries.push({ periodKey: pk, label: lbl, buRank, plays: data.count });
        if (buRank < result[type][k].peakBuRank) result[type][k].peakBuRank = buRank;
        if (data.count > result[type][k].peakPlays) result[type][k].peakPlays = data.count;
      });
    }
  }

  return { period: 'week', curKey: null, result, buPeriodMap };
}

// Narrows a full-history BU run to everything up to and including curKey.
function _buSlice(full, curKey) {
  const result = { songs: {}, artists: {}, albums: {} };
  for (const type of ['songs', 'artists', 'albums']) {
    const src = full.result[type], dst = result[type];
    for (const k in src) {
      const all = src[k].entries;
      let n = all.length;   // entries are chronological, so the kept ones are a prefix
      while (n > 0 && all[n - 1].periodKey > curKey) n--;
      if (n === 0) continue;
      const entries = n === all.length ? all : all.slice(0, n);
      let peakBuRank = Infinity, peakPlays = 0;
      for (let i = 0; i < n; i++) {
        const e = entries[i];
        if (e.buRank < peakBuRank) peakBuRank = e.buRank;
        if (e.plays > peakPlays) peakPlays = e.plays;
      }
      dst[k] = { entries, peakBuRank, peakPlays };
    }
  }
  const buPeriodMap = {};
  for (const pk in full.buPeriodMap) if (pk <= curKey) buPeriodMap[pk] = full.buPeriodMap[pk];
  return { period: 'week', curKey, result, buPeriodMap };
}

let _buFullCache = {};   // chartSize -> full-history BU run
let _buSliceCache = {};  // chartSize + '|' + curKey -> sliced view
let _buCacheGen = null;

function buildBuChartRun() {
  const gen = _crGeneration();
  if (gen !== _buCacheGen) { _buFullCache = {}; _buSliceCache = {}; _buCacheGen = gen; }
  const size = chartSize;
  const curKey = currentViewWeekKey();
  const sk = size + '|' + curKey;
  let run = _buSliceCache[sk];
  if (!run) {
    const full = _buFullCache[size] || (_buFullCache[size] = _buildBuChartRunFull(size));
    run = _buSliceCache[sk] = _buSlice(full, curKey);
  }
  buChartRunData = run;
  return buChartRunData;
}

// Renders the colored BU-rank boxes for an entry's BU chart run.
// buRank 1 = closest position to the main chart in that week.
// Each box is clickable: shows a tooltip with the full BU chart for that week + a link to navigate there.
function buCrBoxesHTML(type, key) {
  const d = buChartRunData?.result?.[type]?.[key];
  if (!d || !d.entries.length) return '<div style="font-size:0.6rem;color:var(--text3);padding:4px 0">No Bubbling Under history yet.</div>';
  const safeKey = encodeKeyForOnclick(key);
  const boxes = d.entries.flatMap((e, i) => {
    const isPeak = (e.buRank === d.peakBuRank);
    const cls = isPeak ? 'cr-box cr-box-peak' : 'cr-box';
    const box = `<div class="${cls}" onclick="showBuCrPreview('${esc(e.periodKey)}','${type}','${safeKey}',this)">
      <div class="cr-box-rank">BU${e.buRank}</div>
      <div class="cr-box-label">${esc(e.label)}</div>
    </div>`;
    if (i === 0) return [box];
    const gap = crPeriodGap('week', d.entries[i - 1].periodKey, e.periodKey);
    if (gap <= 0) return [box];
    const gapEl = `<div class="cr-box-gap"><div class="cr-box-gap-label">✕${gap}</div><div class="cr-box-gap-unit">${tUnit('weeks', gap)}</div></div>`;
    return [gapEl, box];
  }).join('');
  return `<div class="cr-boxes-wrap"><div class="cr-boxes">${boxes}</div></div>`;
}

// Renders a combined timeline of both official chart weeks and BU weeks for an entry.
// Official chart boxes are green (#N); BU boxes are indigo (BUN).
// Entries are merged chronologically with gap indicators between non-consecutive weeks.
function buildCombinedCrBoxesHTML(type, key) {
  const buD = buChartRunData?.result?.[type]?.[key];
  const crD = allChartRun.week?.result?.[type]?.[key];

  if ((!buD || !buD.entries.length) && (!crD || !crD.entries.length)) {
    return '<div style="font-size:0.6rem;color:var(--text3);padding:4px 0">No history yet.</div>';
  }

  // Merge BU and official chart entries into one chronological array
  const all = [];
  if (crD) crD.entries.forEach(e => all.push({ periodKey: e.periodKey, label: e.label, zone: 'chart', rank: e.rank }));
  if (buD) buD.entries.forEach(e => all.push({ periodKey: e.periodKey, label: e.label, zone: 'bu', buRank: e.buRank }));
  all.sort((a, b) => a.periodKey < b.periodKey ? -1 : a.periodKey > b.periodKey ? 1 : 0);

  const safeKey = encodeKeyForOnclick(key);
  const boxes = all.flatMap((e, i) => {
    let cls, rankText, onclk;
    if (e.zone === 'chart') {
      const isPeak = crD && e.rank === crD.peak;
      cls = isPeak ? 'cr-box cr-box-official cr-box-official-peak' : 'cr-box cr-box-official';
      rankText = `#${e.rank}`;
      onclk = `showCrPreview('${esc(e.periodKey)}','${type}','${safeKey}',this,'week')`;
    } else {
      const isPeak = buD && e.buRank === buD.peakBuRank;
      cls = isPeak ? 'cr-box cr-box-bu-entry cr-box-peak' : 'cr-box cr-box-bu-entry';
      rankText = `BU${e.buRank}`;
      onclk = `showBuCrPreview('${esc(e.periodKey)}','${type}','${safeKey}',this)`;
    }
    const box = `<div class="${cls}" onclick="${onclk}">
      <div class="cr-box-rank">${rankText}</div>
      <div class="cr-box-label">${esc(e.label)}</div>
    </div>`;
    if (i === 0) return [box];
    const gap = crPeriodGap('week', all[i - 1].periodKey, e.periodKey);
    if (gap <= 0) return [box];
    const gapEl = `<div class="cr-box-gap"><div class="cr-box-gap-label">✕${gap}</div><div class="cr-box-gap-unit">${tUnit('weeks', gap)}</div></div>`;
    return [gapEl, box];
  }).join('');

  const legend = `<div class="bu-combined-legend">
    <span class="bu-combined-legend-chart">■ Chart</span>
    <span class="bu-combined-legend-bu">■ BU</span>
  </div>`;
  return legend + `<div class="cr-boxes-wrap"><div class="cr-boxes">${boxes}</div></div>`;
}

// Builds combined chart + BU boxes for the normal chart run panel.
// Chart weeks keep their standard styling; BU weeks appear in orange/red to mark
// "almost made it" weeks where the entry was in the BU zone but missed the official chart.
function buildCrWithBuBoxesHTML(type, key, d) {
  const buD = buChartRunData?.result?.[type]?.[key];
  if (!buD || !buD.entries.length) return '';

  // Merge chart entries (already filtered by range) with all BU entries, sorted chronologically
  const all = [];
  if (d) d.entries.forEach(e => all.push({ periodKey: e.periodKey, label: e.label, zone: 'chart', rank: e.rank }));
  buD.entries.forEach(e => all.push({ periodKey: e.periodKey, label: e.label, zone: 'bu', buRank: e.buRank }));
  all.sort((a, b) => a.periodKey < b.periodKey ? -1 : a.periodKey > b.periodKey ? 1 : 0);

  const safeKey = encodeKeyForOnclick(key);
  const boxes = all.flatMap((e, i) => {
    let cls, rankText, onclk;
    if (e.zone === 'chart') {
      const isPeak = d && e.rank === d.peak;
      cls = isPeak ? 'cr-box cr-box-peak' : 'cr-box';
      rankText = `#${e.rank}`;
      onclk = `showCrPreview('${esc(e.periodKey)}','${type}','${safeKey}',this,'week')`;
    } else {
      const isPeak = buD && e.buRank === buD.peakBuRank;
      cls = isPeak ? 'cr-box cr-box-bu-miss cr-box-bu-miss-peak' : 'cr-box cr-box-bu-miss';
      rankText = `BU${e.buRank}`;
      onclk = `showBuCrPreview('${esc(e.periodKey)}','${type}','${safeKey}',this)`;
    }
    const box = `<div class="${cls}" onclick="${onclk}">
      <div class="cr-box-rank">${rankText}</div>
      <div class="cr-box-label">${esc(e.label)}</div>
    </div>`;
    if (i === 0) return [box];
    const gap = crPeriodGap('week', all[i - 1].periodKey, e.periodKey);
    if (gap <= 0) return [box];
    const gapEl = `<div class="cr-box-gap"><div class="cr-box-gap-label">✕${gap}</div><div class="cr-box-gap-unit">${tUnit('weeks', gap)}</div></div>`;
    return [gapEl, box];
  }).join('');

  const legend = `<div class="bu-combined-legend">
    <span class="bu-combined-legend-cr">■ Chart</span>
    <span class="bu-combined-legend-bu-miss">■ BU</span>
  </div>`;
  return legend + `<div class="cr-boxes-wrap"><div class="cr-boxes">${boxes}</div></div>`;
}

// Toggles between BU-only and combined (BU + chart) timeline views in a BU panel.
function toggleBuCombinedView(btn) {
  const panel = btn.closest('.bu-cr-panel');
  if (!panel) return;
  const buView = panel.querySelector('.bu-cr-view-bu');
  const combinedView = panel.querySelector('.bu-cr-view-combined');
  if (!buView || !combinedView) return;
  const showingBu = buView.style.display !== 'none';
  buView.style.display = showingBu ? 'none' : '';
  combinedView.style.display = showingBu ? '' : 'none';
  btn.classList.toggle('active', showingBu);
  btn.textContent = showingBu ? 'BU only' : '+ Chart';
}

// Toggles between chart-only and combined (chart + BU) timeline views in the normal chart run panel.
function toggleCrBuView(btn) {
  const panel = btn.closest('.cr-panel');
  if (!panel) return;
  const chartView = panel.querySelector('.cr-view-chart');
  const combinedView = panel.querySelector('.cr-view-combined');
  if (!chartView || !combinedView) return;
  const showingChart = chartView.style.display !== 'none';
  chartView.style.display = showingChart ? 'none' : '';
  combinedView.style.display = showingChart ? '' : 'none';
  btn.classList.toggle('active', showingChart);
  btn.textContent = showingChart ? 'Chart only' : '+ BU';
}

// Builds the full BU chart run panel HTML (header + stats + boxes).
// Includes a "+ Chart" toggle button that shows a combined BU + official chart timeline.
function buildBuCrPanelHTML(type, key) {
  const d = buChartRunData?.result?.[type]?.[key];
  // Show toggle only when the entry also has official chart history
  const hasCrData = !!(allChartRun.week?.result?.[type]?.[key]?.entries?.length);
  const toggleBtn = hasCrData
    ? `<button class="bu-combined-toggle" onclick="toggleBuCombinedView(this)" title="Toggle combined Chart + BU timeline">+ Chart</button>`
    : '';

  const headerHtml = `<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:8px;padding-bottom:6px;border-bottom:1px solid var(--border);">
    <div>
      <div style="font-family:var(--font-mono);font-size:0.65rem;font-weight:700;letter-spacing:0.18em;color:var(--text);text-transform:uppercase;">🫧 BU CHART RUN</div>
      <div style="font-family:var(--font-mono);font-size:0.54rem;letter-spacing:0.07em;color:var(--text3);margin-top:2px;">Bubbling Under zone history · weekly</div>
    </div>
    ${toggleBtn}
  </div>`;

  if (!d || !d.entries.length) {
    return headerHtml + `<div style="font-size:0.6rem;color:var(--text3);padding:4px 0">No Bubbling Under history yet.</div>`;
  }

  // Compute streak and stints from the entries (which are already in chronological order)
  let longestStreak = 0, curStreak = 0, stints = 0;
  for (let i = 0; i < d.entries.length; i++) {
    if (i === 0) { curStreak = 1; stints = 1; }
    else {
      const gap = crPeriodGap('week', d.entries[i - 1].periodKey, d.entries[i].periodKey);
      if (gap === 0) { curStreak++; }
      else { longestStreak = Math.max(longestStreak, curStreak); curStreak = 1; stints++; }
    }
  }
  longestStreak = Math.max(longestStreak, curStreak);

  const n = d.entries.length;
  const peak = d.peakBuRank; // 1 = closest to the chart
  const at1 = d.entries.filter(e => e.buRank === 1).length; // weeks at BU#1 (highest BU spot)

  const statsHtml = `<div class="cr-stats">
    <div class="cr-stat"><strong>${n} ${tUnit('weeks', n)}</strong> in Bubbling Under</div>
    <div class="cr-stat"><strong>Peak BU${peak}</strong>${peak === 1 ? ' · closest to the chart' : ''} (chart rank #${chartSize + peak})</div>
    ${at1 ? `<div class="cr-stat"><strong>${at1} ${tUnit('weeks', at1)}</strong> at BU#1</div>` : ''}
    ${longestStreak > 1 ? `<div class="cr-stat"><strong>${longestStreak}-week</strong> longest streak</div>` : ''}
    ${stints > 1 ? `<div class="cr-stat"><strong>${stints} stints</strong> in Bubbling Under</div>` : ''}
    <div class="cr-stat"><strong>${d.peakPlays}</strong> peak plays in a single week</div>
  </div>`;

  // Dual-view: BU-only (default) and combined BU+chart (toggled via button)
  const buView = `<div class="bu-cr-view-bu">${buCrBoxesHTML(type, key)}</div>`;
  const combinedView = hasCrData
    ? `<div class="bu-cr-view-combined" style="display:none">${buildCombinedCrBoxesHTML(type, key)}</div>`
    : '';

  return headerHtml + statsHtml + buView + combinedView;
}

// Toggles a BU chart run expand row (same pattern as toggleChartRun).
function toggleBuCr(btn, rowId) {
  event.stopPropagation();
  const row = document.getElementById(rowId);
  if (!row) return;
  const open = !row.classList.contains('open');
  row.classList.toggle('open', open);
  btn.classList.toggle('active', open);
}

// Shows a popup tooltip for a BU chart run box — same pattern as showCrPreview.
// Lists the full BU zone ranking for that week with the active entry highlighted,
// plus a link to navigate to that week's chart.
let _buCrPreviewCleanup = null;
function showBuCrPreview(periodKey, type, encodedKey, boxEl) {
  hideBuCrPreview();
  if (!buChartRunData?.buPeriodMap?.[periodKey]) return;
  const key = decodeURIComponent(encodedKey);
  const entries = buChartRunData.buPeriodMap[periodKey][type] || [];
  const title = crPeriodTitle('week', periodKey);
  const typeLabels = { songs: t('rec_th_songs'), artists: t('rec_th_artists'), albums: t('rec_th_albums') };
  const items = entries.map(e => {
    const isActive = (e.key === key);
    return `<div class="cr-preview-item${isActive ? ' highlighted' : ''}"><span class="cr-preview-rank">BU${e.buRank}</span><span>${esc(e.displayName)}</span></div>`;
  }).join('');
  const popup = document.createElement('div');
  popup.className = 'cr-preview';
  popup.id = 'buCrPreviewPopup';
  popup.style.position = 'fixed';
  popup.innerHTML = `<button class="cr-preview-close" onclick="hideBuCrPreview()">✕</button>`
    + `<div class="cr-preview-title"><a class="cr-preview-link" href="#chart/week/${periodKey}" onclick="event.preventDefault();navigateToCrChart('week','${periodKey}')">${esc(title)}</a> · BU ${typeLabels[type]}</div>`
    + items;
  document.body.appendChild(popup);
  // Position near the box, keep within viewport
  const rect = boxEl.getBoundingClientRect();
  let top = rect.bottom + 6, left = rect.left;
  const pw = 250, ph = 300;
  if (left + pw > window.innerWidth) left = window.innerWidth - pw - 8;
  if (top + ph > window.innerHeight) top = rect.top - ph - 6;
  popup.style.top = Math.max(4, top) + 'px';
  popup.style.left = Math.max(4, left) + 'px';
  // Close on outside click (same guard as showCrPreview)
  const handler = e => { if (!popup.contains(e.target) && !e.target.closest('.cr-box')) hideBuCrPreview(); };
  setTimeout(() => document.addEventListener('click', handler, true), 0);
  _buCrPreviewCleanup = () => document.removeEventListener('click', handler, true);
}

function hideBuCrPreview() {
  const el = document.getElementById('buCrPreviewPopup');
  if (el) el.remove();
  if (_buCrPreviewCleanup) { _buCrPreviewCleanup(); _buCrPreviewCleanup = null; }
}

// ─── BUBBLING UNDER ─────────────────────────────────────────────
// Tracks open/closed state of the accordion per type (songs/artists/albums)
const _buOpen = { songs: false, artists: false, albums: false };

function toggleBuSection(type) {
  _buOpen[type] = !_buOpen[type];
  const ucType = type.charAt(0).toUpperCase() + type.slice(1);
  const bodyEl = document.getElementById('bu' + ucType + 'Body');
  const iconEl = document.getElementById('bu' + ucType + 'ToggleIcon');
  if (bodyEl) bodyEl.style.display = _buOpen[type] ? '' : 'none';
  if (iconEl) iconEl.textContent = _buOpen[type] ? '▲' : '▼';
  syncCollapseAllBtn();
}

// Toggles the New Entries section (songs/artists/albums) using the same
// collapsed class + localStorage key as the existing section system.
function toggleNeSection(type) {
  const ucType = type.charAt(0).toUpperCase() + type.slice(1);
  const sectionId = 'new' + ucType + 'Section';
  const sectionEl = document.getElementById(sectionId);
  const iconEl    = document.getElementById('ne' + ucType + 'ToggleIcon');
  if (!sectionEl) return;
  const collapsed = sectionEl.classList.toggle('collapsed');
  if (iconEl) iconEl.textContent = collapsed ? '▼' : '▲';
  // Persist via the same key used by restoreChartSectionCollapseState
  localStorage.setItem('dc_chart_section_collapsed_' + sectionId + '_' + currentPeriod, collapsed ? '1' : '0');
  syncCollapseAllBtn();
}

function hideBuSection(type) {
  const ucType = type.charAt(0).toUpperCase() + type.slice(1);
  const sectionEl = document.getElementById('bu' + ucType + 'Section');
  if (sectionEl) sectionEl.style.display = 'none';
}

// Off The Chart accordion state — mirrors _buOpen/toggleBuSection/hideBuSection above
const _offOpen = { songs: false, artists: false, albums: false };

function toggleOffSection(type) {
  _offOpen[type] = !_offOpen[type];
  const ucType = type.charAt(0).toUpperCase() + type.slice(1);
  const bodyEl = document.getElementById('off' + ucType + 'Body');
  const iconEl = document.getElementById('off' + ucType + 'ToggleIcon');
  if (bodyEl) bodyEl.style.display = _offOpen[type] ? '' : 'none';
  if (iconEl) iconEl.textContent = _offOpen[type] ? '▲' : '▼';
  syncCollapseAllBtn();
}

function hideOffSection(type) {
  const ucType = type.charAt(0).toUpperCase() + type.slice(1);
  const sectionEl = document.getElementById('off' + ucType + 'Section');
  if (sectionEl) sectionEl.style.display = 'none';
}

// Renders the Bubbling Under section for songs, artists, or albums.
// normalizedPool: array of { key, displayName, subName, count }
// ms: monthlyStats (must have bubblingUnderWeeks, prevBubblingUnder, everChartedBefore, prevChart)
// lowestChartCount: play count of the last entry on the main chart (for "X plays away")
function renderBubblingUnder(type, normalizedPool, ms, lowestChartCount) {
  const ucType = type.charAt(0).toUpperCase() + type.slice(1);
  const sectionEl  = document.getElementById('bu' + ucType + 'Section');
  const countEl    = document.getElementById('bu' + ucType + 'Count');
  const bodyEl     = document.getElementById('bu' + ucType + 'Body');
  const tbodyEl    = document.getElementById('bu' + ucType + 'TableBody');
  const iconEl     = document.getElementById('bu' + ucType + 'ToggleIcon');
  const titleEl    = document.getElementById('bu' + ucType + 'SectionTitle');

  if (!sectionEl) return;

  if (!normalizedPool || normalizedPool.length === 0) {
    sectionEl.style.display = 'none';
    return;
  }

  sectionEl.style.display = '';
  // Update title to show which chart size this BU section sits below (e.g. "BUBBLING UNDER TOP 10")
  if (titleEl) titleEl.textContent = t('sec_bubbling_under', { n: chartSize });
  if (countEl) countEl.textContent = normalizedPool.length;
  if (bodyEl)  bodyEl.style.display = _buOpen[type] ? '' : 'none';
  if (iconEl)  iconEl.textContent = _buOpen[type] ? '▲' : '▼';

  // Build BU chart run history once for this render cycle (cached in buChartRunData)
  if (!buChartRunData) buildBuChartRun();

  // Idea 17: find the top week-over-week gainer among entries that were also in BU last week
  let surgingKey = null;
  let bestSurgeDelta = 1; // minimum gain of 1 play required
  // Freefall: biggest week-over-week loser in the BU pool (counterpart to Surging)
  let freefallKey = null;
  let bestFreefallDelta = 1; // minimum drop of 1 play required
  for (const item of normalizedPool) {
    const prevCount = ms.prevBubblingUnder?.[type]?.[item.key]?.count;
    if (prevCount === undefined) continue;
    const delta = item.count - prevCount;
    if (delta > bestSurgeDelta) { bestSurgeDelta = delta; surgingKey = item.key; }
    if (-delta > bestFreefallDelta) { bestFreefallDelta = -delta; freefallKey = item.key; }
  }

  const rows = normalizedPool.flatMap((item, i) => {
    const rank = chartSize + 1 + i;
    const { key, displayName, subName, album, count } = item;

    // Idea 13: plays away from entering the chart
    const playsAway = Math.max(0, lowestChartCount - count);

    // Idea 14: total weeks this entry has appeared in the BU zone (loop already includes current week)
    const totalBuWeeks = ms.bubblingUnderWeeks?.[type]?.[key] || 0;
    const consecutiveBuWeeks = ms.bubblingUnderStreak?.[type]?.[key] || 0;

    // Idea 15: dropped off the chart since last week → fading
    const everCharted      = ms.everChartedBefore[type].has(key);
    const wasOnLastWeek    = !!ms.prevChart[type][key];
    const isFading         = wasOnLastWeek;

    // Idea 16a: never charted + was already in BU last week → trending toward the chart
    const wasBuLastWeek    = !!(ms.prevBubblingUnder?.[type]?.[key]);
    const isPersistent     = !everCharted && totalBuWeeks >= 5;
    const isTrending       = !everCharted && wasBuLastWeek && !isPersistent;

    // Idea 18: never charted, first time ever in BU this week → debut (bubblingUnderWeeks === 1 because loop counted current week)
    const isDebut          = !everCharted && totalBuWeeks === 1;

    // Whether the current BU run started from a chart position (vs. from full absence)
    const entryFromChart   = !!(ms.bubblingUnderEntryFromChart?.[type]?.[key]);
    // Idea 16b: previously charted, first week back in BU after full absence (not from chart) → resurgence
    const isResurgence     = everCharted && !wasOnLastWeek && !wasBuLastWeek && !entryFromChart;
    // Idea 16c: previously charted, persisting in BU after returning from full absence → resurgent
    const isResurgent      = everCharted && !wasOnLastWeek && wasBuLastWeek && !entryFromChart;
    // Clinging: dropped from chart directly into BU (never left BU) and still stuck there week 2+
    const isClinging       = everCharted && !wasOnLastWeek && wasBuLastWeek && entryFromChart;

    // Idea 19: was in top 3 last week, now dropped into BU → fallen
    const histPeak         = ms.peakRank?.[type]?.[key];
    const lastWeekRank     = ms.prevChart[type][key]?.rank;
    const isFallen         = wasOnLastWeek && lastWeekRank <= 3;

    // Idea 17: biggest week-over-week play gainer in the BU pool this week → surging
    const isSurging        = key === surgingKey;
    // Freefall: biggest week-over-week play loser in the BU pool this week
    const isFreefall       = key === freefallKey;
    // Revolving: has entered and exited the BU zone 3+ separate times
    const buRuns           = ms.bubblingUnderRuns?.[type]?.[key] || 0;
    const isYoYo           = buRuns >= 3;

    // Build badges (ideas 13, 14, 15, 16, 17 + Freefall + Revolving)
    let badges = '';
    if (playsAway > 0)  badges += `<span class="bu-badge bu-badge-away" title="${t(playsAway === 1 ? 'bu_badge_away_title_one' : 'bu_badge_away_title_other', { n: playsAway })}">${t(playsAway === 1 ? 'bu_badge_away_one' : 'bu_badge_away_other', { n: playsAway })}</span>`;
    if (isFading)       badges += `<span class="bu-badge bu-badge-fading" title="${t('bu_badge_fading_title')}">${t('bu_badge_fading')}</span>`;
    if (isDebut)        badges += `<span class="bu-badge bu-badge-debut" title="${t('bu_badge_debut_title')}">${t('bu_badge_debut')}</span>`;
    if (isTrending)     badges += `<span class="bu-badge bu-badge-trending" title="${t('bu_badge_trending_title')}">${t('bu_badge_trending')}</span>`;
    if (isPersistent)   badges += `<span class="bu-badge bu-badge-persistent" title="${t('bu_badge_persistent_title', { n: totalBuWeeks })}">${t('bu_badge_persistent')}</span>`;
    if (isResurgence)   badges += `<span class="bu-badge bu-badge-resurgence" title="${t('bu_badge_resurgence_title')}">${t('bu_badge_resurgence')}</span>`;
    if (isResurgent)    badges += `<span class="bu-badge bu-badge-resurgent" title="${t('bu_badge_resurgent_title')}">${t('bu_badge_resurgent')}</span>`;
    if (isClinging)     badges += `<span class="bu-badge bu-badge-clinging" title="${t('bu_badge_clinging_title')}">${t('bu_badge_clinging')}</span>`;
    if (isFallen)       badges += `<span class="bu-badge bu-badge-fallen" title="${t('bu_badge_fallen_title', { n: lastWeekRank })}">${t('bu_badge_fallen')}</span>`;
    if (isSurging)      badges += `<span class="bu-badge bu-badge-surging" title="${t('bu_badge_surging_title', { n: bestSurgeDelta })}">${t('bu_badge_surging')}</span>`;
    if (isFreefall)     badges += `<span class="bu-badge bu-badge-freefall" title="${t('bu_badge_freefall_title', { n: bestFreefallDelta })}">${t('bu_badge_freefall')}</span>`;
    if (isYoYo)         badges += `<span class="bu-badge bu-badge-yoyo" title="${t('bu_badge_yoyo_title', { n: buRuns })}">${t('bu_badge_yoyo')}</span>`;
    if (totalBuWeeks >= 2) badges += `<span class="bu-badge bu-badge-weeks" title="${t('bu_badge_weeks_title', { n: totalBuWeeks })}">${t('bu_badge_weeks_label', { n: totalBuWeeks })}</span>`;
    if (consecutiveBuWeeks >= 2) badges += `<span class="bu-badge bu-badge-streak" title="${t('bu_badge_streak_title', { n: consecutiveBuWeeks })}">${t('bu_badge_streak_label', { n: consecutiveBuWeeks })}</span>`;

    // Build YouTube button data attrs based on entry type
    const ytTitle  = type === 'songs'   ? displayName : '';
    const ytArtist = type === 'artists' ? displayName : subName;
    const ytAlbum  = type === 'albums'  ? displayName : (type === 'songs' ? (album || '') : '');
    // Songs: play immediately. Artists/albums: show last-10 track picker dropdown.
    const ytBtnOnclick = type === 'songs'
      ? `event.stopPropagation();ytPlayFromBtn(this)`
      : `event.stopPropagation();buShowTrackList(this,${esc(JSON.stringify(type))})`;
    const ytBtnTitle = t(type === 'songs' ? 'bu_yt_play_title' : 'bu_yt_tracks_title');
    const ytBtn = `<button class="yt-play-btn bu-yt-btn" data-title="${esc(ytTitle)}" data-artist="${esc(ytArtist)}" data-album="${esc(ytAlbum)}" onclick="${ytBtnOnclick}" title="${ytBtnTitle}"><span class="yt-btn-content"><svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>YouTube</span></button>`
      + dcPlBtnHtml(dcPlKindFor(type), ytTitle, ytArtist, ytAlbum);

    // BU chart run expand row — toggled by the icon button in the trailing cr-cell
    const buCrRowId = `bu-cr-${type}-${i}`;
    const mainRow = `<tr class="bu-row">
      <td class="bu-rank-cell">#${rank}</td>
      <td class="bu-name-cell">
        <div class="bu-display-name">${esc(displayName)}</div>
        ${subName ? `<div class="bu-sub-name">${esc(subName)}</div>` : ''}
        ${ytBtn}
        ${badges ? `<div class="bu-badges">${badges}</div>` : ''}
      </td>
      <td class="bu-plays-cell">
        <div class="bu-play-count">${tCountHtml('plays', count)}</div>
      </td>
      <td class="cr-cell"><button class="cr-toggle-btn bu-cr-btn" title="BU Chart Run — Bubbling Under history" onclick="event.stopPropagation();toggleBuCr(this,'${buCrRowId}')">${CR_ICON}</button></td>
    </tr>`;
    const expandRow = `<tr class="bu-cr-row cr-row" id="${buCrRowId}"><td colspan="4"><div class="cr-panel bu-cr-panel">${buildBuCrPanelHTML(type, key)}</div></td></tr>`;
    return [mainRow, expandRow];
  });

  if (tbodyEl) tbodyEl.innerHTML = rows.join('');

  const legendEl = document.getElementById('bu' + ucType + 'Legend');
  if (legendEl) legendEl.innerHTML = `
    <div class="bu-legend-item"><span class="bu-badge bu-badge-debut">${t('bu_badge_debut')}</span><span class="bu-legend-desc">${t('bu_badge_debut_title')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-trending">${t('bu_badge_trending')}</span><span class="bu-legend-desc">${t('bu_badge_trending_title')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-persistent">${t('bu_badge_persistent')}</span><span class="bu-legend-desc">${t('bu_badge_persistent_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-fading">${t('bu_badge_fading')}</span><span class="bu-legend-desc">${t('bu_badge_fading_title')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-resurgence">${t('bu_badge_resurgence')}</span><span class="bu-legend-desc">${t('bu_badge_resurgence_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-resurgent">${t('bu_badge_resurgent')}</span><span class="bu-legend-desc">${t('bu_badge_resurgent_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-clinging">${t('bu_badge_clinging')}</span><span class="bu-legend-desc">${t('bu_badge_clinging_title')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-fallen">${t('bu_badge_fallen')}</span><span class="bu-legend-desc">${t('bu_badge_fallen_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-surging">${t('bu_badge_surging')}</span><span class="bu-legend-desc">${t('bu_badge_surging_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-freefall">${t('bu_badge_freefall')}</span><span class="bu-legend-desc">${t('bu_badge_freefall_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-yoyo">${t('bu_badge_yoyo')}</span><span class="bu-legend-desc">${t('bu_badge_yoyo_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-weeks">${t('bu_badge_weeks_label', { n: 'N' })}</span><span class="bu-legend-desc">${t('bu_badge_weeks_desc')}</span></div>
    <div class="bu-legend-item"><span class="bu-badge bu-badge-streak">${t('bu_badge_streak_label', { n: 'N' })}</span><span class="bu-legend-desc">${t('bu_badge_streak_desc')}</span></div>
  `;
}

// ─── BU TRACK LIST DROPDOWN ──────────────────────────────────────
// Opens a floating panel listing the last 10 unique tracks played from an
// artist or album BU entry, with Play / Queue buttons for each track.
// btn must be the YouTube button in a BU row (has data-artist / data-album).
function buShowTrackList(btn, type) {
  const existing = document.getElementById('buTrackListDrop');
  if (existing) {
    existing.remove();
    // Toggle: clicking the same button again closes the dropdown
    if (existing._sourceBtn === btn) return;
  }

  const artistName = btn.dataset.artist || '';
  const albumName  = btn.dataset.album  || '';

  // Filter allPlays (newest→oldest) to this artist or album
  let filtered;
  if (type === 'artists') {
    filtered = allPlays.filter(p => p.artists && p.artists.includes(artistName));
  } else {
    // Albums: match album name AND artist so same-titled albums from different artists don't collide
    filtered = allPlays.filter(p => p.album === albumName && p.artists && p.artists.includes(artistName));
  }

  // Deduplicate by song key, keeping most-recently-played occurrence first
  const seen = new Set();
  const tracks = [];
  for (const p of filtered) {
    const k = songKey(p);
    if (!seen.has(k)) {
      seen.add(k);
      tracks.push(p);
      if (tracks.length >= 10) break;
    }
  }

  if (!tracks.length) return;

  const tlKey = tracks.length === 1 ? 'bu_tl_header_one' : 'bu_tl_header_other';
  const headerLabel = type === 'artists'
    ? t(tlKey, { n: tracks.length, name: artistName })
    : t(tlKey, { n: tracks.length, name: albumName });

  const rows = tracks.map((p, i) => {
    const safeTitle  = esc(p.title);
    const safeArtist = esc(p.artist);
    const safeAlbum  = esc(p.album || '');
    // Show album name below title in artist view for extra context
    const albumDisp = type === 'artists' && p.album
      ? `<span class="bu-tl-album">${esc(p.album)}</span>` : '';
    return `<div class="bu-tl-row">` +
      `<div class="bu-tl-info"><div><span class="bu-tl-num">${i + 1}</span><span class="bu-tl-title">${safeTitle}</span></div>${albumDisp}</div>` +
      `<div class="bu-tl-btns">` +
      `<button class="bu-tl-play-btn" data-title="${safeTitle}" data-artist="${safeArtist}" data-album="${safeAlbum}" onclick="buTlPlay(this)" title="${t('bu_tl_play_title')}">${t('bu_tl_play')}</button>` +
      `<button class="bu-tl-queue-btn" data-title="${safeTitle}" data-artist="${safeArtist}" data-album="${safeAlbum}" onclick="buTlQueue(this)" title="${t('bu_tl_queue_title')}">${t('bu_tl_queue')}</button>` +
      `</div></div>`;
  }).join('');

  const drop = document.createElement('div');
  drop.id = 'buTrackListDrop';
  drop.className = 'bu-tracklist-drop';
  drop._sourceBtn = btn; // remember source to support toggle-close
  drop.innerHTML =
    `<div class="bu-tl-header">` +
    `<span class="bu-tl-header-label">🎵 ${esc(headerLabel)}</span>` +
    `<button class="bu-tl-playall-btn" onclick="buTlPlayAll()" title="${t('bu_tl_play_all_title')}">${t('bu_tl_play_all')}</button>` +
    `<button class="bu-tl-queueall-btn" onclick="buTlQueueAll()" title="${t('bu_tl_queue_all_title')}">${t('bu_tl_queue_all')}</button>` +
    `<button class="bu-tl-close-btn" onclick="document.getElementById('buTrackListDrop')?.remove()" title="${t('bu_tl_close_title')}">✕</button>` +
    `</div>` +
    `<div class="bu-tl-scroll">${rows}</div>`;

  document.body.appendChild(drop);

  // Position anchored below the button; flip above if near the bottom edge
  const dropW   = 340;
  const dropMaxH = 320;
  const r = btn.getBoundingClientRect();
  let left = r.left;
  let top  = r.bottom + 6;
  if (left + dropW > window.innerWidth - 12) left = Math.max(8, window.innerWidth - dropW - 12);
  if (top + dropMaxH > window.innerHeight - 12) top = Math.max(8, r.top - dropMaxH - 6);
  drop.style.left = left + 'px';
  drop.style.top  = top  + 'px';

  // Dismiss on outside click
  const closeOnOut = e => {
    if (!drop.contains(e.target) && e.target !== btn) {
      drop.remove();
      document.removeEventListener('mousedown', closeOnOut, true);
    }
  };
  setTimeout(() => document.addEventListener('mousedown', closeOnOut, true), 50);
}

// Play a track from the BU track-list dropdown immediately.
function buTlPlay(btn) {
  document.getElementById('buTrackListDrop')?.remove();
  openYtPlayer(btn.dataset.title, btn.dataset.artist, btn.dataset.album, null);
}

// Add a track from the BU track-list dropdown to the queue (or start playing if nothing is active).
function buTlQueue(btn) {
  const { title, artist, album } = btn.dataset;
  const playerEl = document.getElementById('ytMiniPlayer');
  if (_ytCurrentTrack && playerEl && playerEl.style.display !== 'none') {
    _ytQueue.push({ title, artist, album, btn: null });
    _ytUpdateQueueDisplay();
    _ytSaveQueue();
    // Brief checkmark feedback on the button
    const orig = btn.textContent;
    btn.textContent = '✓';
    setTimeout(() => { if (btn.isConnected) btn.textContent = orig; }, 1200);
  } else {
    document.getElementById('buTrackListDrop')?.remove();
    openYtPlayer(title, artist, album, null);
  }
}

// Add all tracks in the BU track-list dropdown to the queue without closing it.
function buTlQueueAll() {
  const drop = document.getElementById('buTrackListDrop');
  if (!drop) return;
  const playBtns = [...drop.querySelectorAll('.bu-tl-play-btn')];
  if (!playBtns.length) return;
  const playerEl = document.getElementById('ytMiniPlayer');
  if (_ytCurrentTrack && playerEl && playerEl.style.display !== 'none') {
    // Player is active — append all to queue
    playBtns.forEach(b => _ytQueue.push({ title: b.dataset.title, artist: b.dataset.artist, album: b.dataset.album, btn: null }));
    _ytUpdateQueueDisplay();
    _ytSaveQueue();
    // Brief feedback on the button
    const queueAllBtn = drop.querySelector('.bu-tl-queueall-btn');
    if (queueAllBtn) {
      const orig = queueAllBtn.textContent;
      queueAllBtn.textContent = '✓ Added';
      setTimeout(() => { if (queueAllBtn.isConnected) queueAllBtn.textContent = orig; }, 1500);
    }
  } else {
    // Nothing playing — start first, queue the rest
    drop.remove();
    const [first, ...rest] = playBtns;
    openYtPlayer(first.dataset.title, first.dataset.artist, first.dataset.album, null);
    rest.forEach(b => _ytQueue.push({ title: b.dataset.title, artist: b.dataset.artist, album: b.dataset.album, btn: null }));
    _ytUpdateQueueDisplay();
    _ytSaveQueue();
  }
}

// Play all tracks in the BU track-list dropdown: start the first, queue the rest.
function buTlPlayAll() {
  const drop = document.getElementById('buTrackListDrop');
  if (!drop) return;
  const playBtns = [...drop.querySelectorAll('.bu-tl-play-btn')];
  if (!playBtns.length) return;
  drop.remove();
  const [first, ...rest] = playBtns;
  openYtPlayer(first.dataset.title, first.dataset.artist, first.dataset.album, null);
  rest.forEach(b => _ytQueue.push({ title: b.dataset.title, artist: b.dataset.artist, album: b.dataset.album, btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ─── WEEKLY CHART VIEWS ────────────────────────────────────────
function setWeeklyChartView(mode, type) {
  weeklyChartViewMode[type] = mode;
  try { localStorage.setItem('dc_weekly_chart_view_' + type, mode); } catch(e) {}
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  applyWeeklyChartView(type);
}

function applyWeeklyChartView(onlyType) {
  if (currentPeriod !== 'week') return;
  const types = onlyType ? [onlyType] : ['songs', 'artists', 'albums'];
  for (const tp of types) {
    const mode = weeklyChartViewMode[tp];
    // Update button active states and stk-2col visibility scoped to this section's bar
    const bar = document.getElementById('weeklyViewBtns-' + tp);
    if (bar) {
      bar.querySelectorAll('.weekly-view-btn:not(.stk-2col-btn)').forEach(b => b.classList.toggle('active', b.dataset.view === mode));
      const stkBtn = bar.querySelector('.stk-2col-btn');
      if (stkBtn) { stkBtn.style.display = mode === 'stack' ? '' : 'none'; stkBtn.classList.toggle('active', _stkTwoCol); }
    }
    const isAlt = mode !== 'table';
    const tbl = document.getElementById(tp + 'Table');
    const altView = document.getElementById('weeklyAltView-' + tp);
    const pgNav = document.getElementById(tp + 'Pagination');
    if (tbl) tbl.style.display = isAlt ? 'none' : '';
    if (pgNav) pgNav.style.display = 'none';
    if (altView) {
      altView.style.display = isAlt ? 'block' : 'none';
      if (isAlt) renderWeeklyAltView(tp);
    }
  }
}

function _wvMv(type, idx, k, ms) {
  if (!ms) return '';
  const prev = ms.prevChart[type][k];
  if (!prev) {
    return ms.everChartedBefore[type].has(k)
      ? `<span class="wv-re">RE</span>`
      : `<span class="wv-new">NEW</span>`;
  }
  const diff = prev.rank - (idx + 1);
  if (diff > 0) return `<span class="wv-up">▲${diff}</span>`;
  if (diff < 0) return `<span class="wv-down">▼${Math.abs(diff)}</span>`;
  return `<span class="wv-same">—</span>`;
}

function _wvThumb(imgId, ttl) {
  return `<div class="thumb-wrap"><div id="${imgId}"><div class="thumb-initials">${esc(initials(ttl))}</div></div></div>`;
}

function _wvDisp(type, item) {
  if (type === 'artists') return { ttl: item.name,  sub: item.songs ? tCount('songs', item.songs.size) : '' };
  if (type === 'albums')  return { ttl: item.album, sub: item.artist };
  return { ttl: item.title, sub: item.artist };
}

// Opens the matching detail modal from any alt chart view (grid/compact/mosaic/filmstrip/stack)
function _wvOpenModal(type, key) {
  if (type === 'artists') openArtistModal(key);
  else if (type === 'albums') openAlbumModal(key);
  else openSongModal(key);
}

function renderWeeklyAltView(type) {
  type = type || 'songs';
  const container = document.getElementById('weeklyAltView-' + type);
  const items  = type === 'songs' ? _weeklyViewSongs : type === 'artists' ? _weeklyViewArtists : _weeklyViewAlbums;
  const maxVal = type === 'songs' ? _weeklyViewMax   : type === 'artists' ? _weeklyViewArtistsMax : _weeklyViewAlbumsMax;
  if (!container || !items.length) return;
  const ms = _weeklyViewMonthlyStats;
  const imgItems = [];
  const renderers = { grid: _wvGrid, compact: _wvCompact, mosaic: _wvMosaic, filmstrip: _wvFilmstrip, stack: _wvStack };
  const mode = weeklyChartViewMode[type];
  const fn = renderers[mode];
  container.innerHTML = fn ? fn(items, maxVal, ms, imgItems, type) : '';
  if (mode === 'filmstrip') initFilmstripInteractions(type);
  if (mode === 'stack') initStkInteractions(type);
  if (imgItems.length) {
    const imgType = type === 'songs' ? 'song' : type === 'artists' ? 'artist' : 'album';
    loadImages(imgItems.map(i => ({ ...i, name: i.title || i.name || i.album })), imgType);
  }
}

function _wvItem(type, item, i, ms, imgItems, imgPrefix) {
  let k, prefKey;
  const _typePrefix = { songs: 'so', artists: 'ar', albums: 'al' };
  const imgId = (imgPrefix || 'wv-' + (_typePrefix[type] || type[0]) + 'img') + '-' + i;
  if (type === 'artists') {
    k = item.name;
    prefKey = 'artist:' + item.name.toLowerCase();
    imgItems.push({ imgId, name: item.name, artist: item.name, prefKey });
  } else if (type === 'albums') {
    k = item.album + '|||' + item.artist;
    prefKey = 'album:' + item.artist.toLowerCase() + '|||' + item.album.toLowerCase();
    imgItems.push({ imgId, album: item.album, artist: item.artist, name: item.album, prefKey });
  } else {
    k = songKey(item);
    prefKey = 'song:' + item.artist.toLowerCase() + '|||' + item.title.toLowerCase();
    imgItems.push({ imgId, title: item.title, artist: item.artist, album: item.album, prefKey });
  }
  return { k, imgId, prefKey, mv: _wvMv(type, i, k, ms) };
}

function _wvGrid(items, max, ms, imgItems, type) {
  type = type || 'songs';
  // First pass: build all item data so we can compute drama scores for animation order
  const itemData = items.map((s, i) => {
    const d = _wvItem(type, s, i, ms, imgItems);
    const { ttl, sub } = _wvDisp(type, s);
    return { ...d, s, i, ttl, sub };
  });
  // Biggest movers (NEW/RE/large ▲) animate first; drops last
  const drama = itemData.map(({ mv }) => {
    if (!mv) return 0;
    if (mv.includes('wv-new') || mv.includes('wv-re')) return 9999;
    const u = mv.match(/▲(\d+)/); if (u) return parseInt(u[1]);
    const dn = mv.match(/▼(\d+)/); if (dn) return parseInt(dn[1]);
    return 0;
  });
  const order = [...itemData.keys()].sort((a, b) => drama[b] - drama[a]);
  const animDelay = new Array(itemData.length);
  order.forEach((origIdx, pos) => { animDelay[origIdx] = pos * 45; });
  const toolbar = `<div class="wv-grid-toolbar"><button class="wv-grid-density-btn${_wvGridLarge ? ' active' : ''}" onclick="toggleGridDensity()" title="Toggle card size">⊞ ${_wvGridLarge ? 'Compact' : 'Large'}</button></div>`;
  const grid = `<div class="wv-grid${_wvGridLarge ? ' wv-grid-lg' : ''}">${itemData.map(({ k, imgId, mv, s, i, ttl, sub }) => {
    const barW = Math.round(s.count / max * 100);
    const _gPrev = ms ? ms.prevChart[type][k] : null;
    const barCls = !ms ? '' : !_gPrev && !ms.everChartedBefore[type].has(k) ? 'wv-bar-new' : !_gPrev ? 'wv-bar-re' : (_gPrev.rank-(i+1)) > 0 ? 'wv-bar-up' : (_gPrev.rank-(i+1)) < 0 ? 'wv-bar-down' : '';
    const pk = type === 'songs' ? _weeklyViewPeaks?.songPeakMap[k] : null;
    const cumPlays = type === 'songs' && cumulativeMaps ? (cumulativeMaps.songs[k] || 0) : 0;
    const cert = type === 'songs' ? certBadge(cumPlays, 'song') : '';
    const mvClass = i >= 3 ? (
      mv.includes('wv-new') || mv.includes('wv-re') ? ' wv-gc-entry' :
      mv.includes('wv-up') ? ' wv-gc-up' :
      mv.includes('wv-down') ? ' wv-gc-down' : ''
    ) : '';
    const jt = esc(JSON.stringify(ttl)), jar = esc(JSON.stringify(sub)), jal = esc(JSON.stringify(s.album || ''));
    const jtype = esc(JSON.stringify(type));
    // Songs play directly; artists and albums show the last-10 track picker,
    // since their name is not something to search as a track. Artists carry
    // their own name in data-artist and no album at all.
    const tlArtist = type === 'artists' ? s.name : (s.artist || '');
    const tlAlbum  = type === 'artists' ? ''     : (s.album  || '');
    const clickAttr = type === 'songs'
      ? ` onclick="_ytPlayOrQueue(${jt},${jar},${jal})"`
      : ` onclick="buShowTrackList(this,${jtype})" data-artist="${esc(tlArtist)}" data-album="${esc(tlAlbum)}"`;
    // Play button revealed on card hover — same target as the card itself
    const gcPlayBtn = type === 'songs'
      ? `<button class="wv-gc-play-btn" onclick="event.stopPropagation();_ytPlayOrQueue(${jt},${jar},${jal})" title="Play Now">▶</button>`
      : `<button class="wv-gc-play-btn" data-artist="${esc(tlArtist)}" data-album="${esc(tlAlbum)}" onclick="event.stopPropagation();buShowTrackList(this,${jtype})" title="Show recently played tracks">▶</button>`;
    const ctxAttr = ` oncontextmenu="_wvGridCtx(event,${jtype},${jt},${jar},${jal});return false"`;
    return `<div class="wv-card wv-grid-card wv-gc-anim${i < 3 ? ' wv-r' + (i+1) : ''}${mvClass}" style="animation-delay:${animDelay[i]}ms"${clickAttr}${ctxAttr}>` +
      `<div class="wv-card-art"><div class="wv-thumb wv-thumb-lg">${_wvThumb(imgId, ttl)}</div>` +
      `<span class="wv-rank-badge">${i+1}</span>` +
      (cert ? `<span class="wv-gc-cert">${cert}</span>` : '') +
      `<div class="wv-gc-hover">${gcPlayBtn}${dcPlBtnForWv(type, ttl, sub, s.album, 'dc-pl-add-sm')}</div>` +
      `</div><div class="wv-card-body">` +
      `<div class="wv-ttl"><span class="wv-title-link" onclick="event.stopPropagation();_wvOpenModal(${jtype},${esc(JSON.stringify(k))})" title="View details">${esc(ttl)}</span>${pk ? peakBadge(pk) : ''}</div>` +
      `<div class="wv-art">${esc(sub)}</div>` +
      `<div class="wv-gc-plays-row"><span class="wv-plays">${s.count} ${s.count===1?'play':'plays'}</span>${mv || ''}</div>` +
      `<div class="wv-bar"><div class="wv-bar-fill${barCls ? ' '+barCls : ''}" style="width:${barW}%"></div></div>` +
      `</div></div>`;
  }).join('')}</div>`;
  return toolbar + grid;
}

function toggleGridDensity() {
  _wvGridLarge = !_wvGridLarge;
  try { localStorage.setItem('dc_grid_density', _wvGridLarge ? 'lg' : 'sm'); } catch(e) {}
  document.querySelectorAll('.wv-grid').forEach(g => g.classList.toggle('wv-grid-lg', _wvGridLarge));
  document.querySelectorAll('.wv-grid-density-btn').forEach(b => {
    b.textContent = `⊞ ${_wvGridLarge ? 'Compact' : 'Large'}`;
    b.classList.toggle('active', _wvGridLarge);
  });
}

function _wvGridCtx(e, type, title, artist, album) {
  e.preventDefault();
  let menu = document.getElementById('wvGridCtxMenu');
  if (!menu) {
    menu = document.createElement('div');
    menu.id = 'wvGridCtxMenu';
    menu.className = 'wv-ctx-menu';
    document.body.appendChild(menu);
    menu.addEventListener('click', function(ev) {
      const item = ev.target.closest('.wv-ctx-item[data-action]');
      if (!item) return;
      const action = item.dataset.action;
      const t  = JSON.parse(menu.dataset.t);
      const ar = JSON.parse(menu.dataset.ar);
      const al = JSON.parse(menu.dataset.al);
      if (action === 'play') {
        _ytPlayOrQueue(t, ar, al);
      } else if (action === 'next') {
        _ytQueue.unshift({ title: t, artist: ar, album: al, btn: null });
        _ytUpdateQueueDisplay(); _ytSaveQueue();
      } else if (action === 'queue') {
        _ytQueue.push({ title: t, artist: ar, album: al, btn: null });
        _ytUpdateQueueDisplay(); _ytSaveQueue();
      } else if (action === 'similar') {
        const others = _weeklyViewSongs.filter(s =>
          s.artist.toLowerCase() === ar.toLowerCase() && !(s.title === t && s.artist === ar));
        others.forEach(s => _ytQueue.push({ title: s.title, artist: s.artist, album: s.album || '', btn: null }));
        _ytUpdateQueueDisplay(); _ytSaveQueue();
        const statusEl = document.getElementById('ytMiniStatus');
        if (statusEl) { statusEl.textContent = others.length ? `+${others.length} by ${ar} queued` : `No other songs by ${ar} in chart`; statusEl.className = 'yt-mini-status' + (others.length ? ' ok' : ''); setTimeout(() => { if (statusEl.textContent.includes('queued') || statusEl.textContent.includes('No other')) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2500); }
      } else if (action === 'yt') {
        window.open('https://www.youtube.com/results?search_query=' + encodeURIComponent(ar + ' ' + t), '_blank');
      }
      menu.style.display = 'none';
    });
    document.addEventListener('click', (ev) => { if (!menu.contains(ev.target)) menu.style.display = 'none'; }, true);
    document.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') menu.style.display = 'none'; });
  }
  menu.dataset.t  = JSON.stringify(title);
  menu.dataset.ar = JSON.stringify(artist);
  menu.dataset.al = JSON.stringify(album);
  const playerEl = document.getElementById('ytMiniPlayer');
  const playerActive = typeof _ytCurrentTrack !== 'undefined' && _ytCurrentTrack && playerEl && playerEl.style.display !== 'none';
  const isSong = type === 'songs';
  menu.innerHTML =
    `<div class="wv-ctx-item" data-action="play">▶ Play Now</div>` +
    (playerActive ? `<div class="wv-ctx-item" data-action="next">⏭ Play Next</div><div class="wv-ctx-item" data-action="queue">＋ Add to Queue</div>` : '') +
    (isSong && playerActive ? `<div class="wv-ctx-item" data-action="similar">♪ Play Similar</div>` : '') +
    `<div class="wv-ctx-sep"></div>` +
    `<div class="wv-ctx-item" data-action="yt">🔍 Search on YouTube</div>`;
  menu.style.display = 'block';
  const mw = menu.offsetWidth || 180, mh = menu.offsetHeight || 140;
  const vw = window.innerWidth, vh = window.innerHeight;
  menu.style.left = Math.min(e.clientX, vw - mw - 8) + 'px';
  menu.style.top  = Math.min(e.clientY, vh - mh - 8) + 'px';
}

function _wvCompact(items, max, ms, imgItems, type) {
  type = type || 'songs';
  const jtype = esc(JSON.stringify(type));
  const header = `<div class="wv-cx-header">` +
    `<span class="wv-cx-rank">#</span>` +
    `<div class="wv-cx-hd-spacer"></div>` +
    `<span class="wv-cx-hd-title">Title — Artist</span>` +
    `<span class="wv-cx-hd-wks">Weeks</span>` +
    `<span class="wv-cx-hd-prev">Previous</span>` +
    `<span class="wv-cx-hd-plays">Plays</span>` +
    `</div>`;

  const rows = items.map((s, i) => {
    const { k, imgId, mv, prefKey } = _wvItem(type, s, i, ms, imgItems);
    const { ttl, sub } = _wvDisp(type, s);
    const pk        = type === 'songs' ? _weeklyViewPeaks?.songPeakMap[k] : null;
    const cumPlays  = type === 'songs' && cumulativeMaps ? (cumulativeMaps.songs[k] || 0) : 0;
    const weeks     = ms ? (ms.periodsOnChart[type][k] || 1) : null;
    const cert      = type === 'songs' ? certBadge(cumPlays, 'song') : '';
    const album     = s.album || '';

    // Feature 8: number rank for all positions, colored gold/silver/bronze for top 3
    const rankHtml = `${i + 1}`;

    // Feature 9: art tooltip — second image element with same prefKey so cache is shared
    const tipId = 'wv-sart-tip-' + i;
    if (type === 'artists') imgItems.push({ imgId: tipId, name: s.name, artist: s.name, prefKey });
    else if (type === 'albums') imgItems.push({ imgId: tipId, album: s.album, artist: s.artist, name: s.album, prefKey });
    else imgItems.push({ imgId: tipId, title: s.title, artist: s.artist, album: s.album, prefKey });
    const artTip = `<div class="wv-cx-art-tip">` +
      `<div class="wv-thumb wv-thumb-lg"><div class="thumb-wrap"><div id="${tipId}"><div class="thumb-initials">${esc(initials(ttl))}</div></div></div></div>` +
      (album && album !== '—' ? `<span class="wv-cx-art-alb">${esc(album)}</span>` : '') +
      `</div>`;

    // Feature 6: play button — songs play directly; artists and albums show the
    // last-10 track picker, since their name is not something to search as a track.
    // Artists carry their own name in data-artist and no album at all.
    const jt = esc(JSON.stringify(ttl)), jar = esc(JSON.stringify(sub)), jal = esc(JSON.stringify(album));
    const tlArtist = type === 'artists' ? s.name : (s.artist || '');
    const tlAlbum  = type === 'artists' ? ''     : (s.album  || '');
    const playBtn = type === 'songs'
      ? `<button class="wv-cx-play-btn" onclick="event.stopPropagation();_ytPlayOrQueue(${jt},${jar},${jal})" title="Play">▶</button>`
      : `<button class="wv-cx-play-btn" data-artist="${esc(tlArtist)}" data-album="${esc(tlAlbum)}" onclick="event.stopPropagation();buShowTrackList(this,${jtype})" title="Show recently played tracks">▶</button>`;
    const cxPlBtn = dcPlBtnForWv(type, ttl, sub, album, 'dc-pl-add-sm');

    // Feature 2: weeks-on-chart column (spelled out)
    const weeksText = weeks ? (weeks === 1 ? '1 Week' : `${weeks} Weeks`) : '';

    // Previous column: movement arrow + previous rank, like the table view
    const prevContent = (() => {
      if (!ms) return '';
      const prev = ms.prevChart[type][k];
      if (!prev) {
        return ms.everChartedBefore[type].has(k)
          ? `<span class="wv-re">RE</span>`
          : `<span class="wv-new">NEW</span>`;
      }
      const diff = prev.rank - (i + 1);
      if (diff === 0) return `<span class="wv-same">—</span><div class="wv-cx-prev-rank">#${prev.rank}</div>`;
      const dir = diff > 0 ? 'up' : 'down';
      const arrow = diff > 0 ? '▲' : '▼';
      return `<span class="wv-${dir}">${arrow}${Math.abs(diff)}</span><div class="wv-cx-prev-rank">#${prev.rank}</div>`;
    })();

    // Feature 7: color-scaled play count
    const ratio = max > 0 ? s.count / max : 0;
    const playsColor = ratio > 0.6 ? 'var(--accent)' : ratio > 0.3 ? 'var(--text)' : '';
    const playsStyle = playsColor ? ` style="color:${playsColor}"` : '';

    // Feature 5: expand-on-click accordion shelf
    const shelfParts = [];
    if (album && album !== '—') shelfParts.push(`<span class="wv-cx-shelf-item">💿 ${esc(album)}</span>`);
    if (pk) shelfParts.push(`<span class="wv-cx-shelf-item">${peakBadge(pk)}</span>`);
    if (cumPlays > 0) shelfParts.push(`<span class="wv-cx-shelf-item wv-cx-shelf-total">${cumPlays} all-time</span>`);
    if (weeks && weeks > 1) shelfParts.push(`<span class="wv-cx-shelf-item wv-cx-shelf-wks">${weeks}w on chart</span>`);
    const shelf = shelfParts.length ? `<div class="wv-cx-shelf">${shelfParts.join('')}</div>` : '';
    const statusCls = mv.includes('wv-new') ? ' wv-stk-new' : mv.includes('wv-re') ? ' wv-stk-re' : '';

    return `<div class="wv-cx-row${i < 3 ? ' wv-r' + (i + 1) : ''}${statusCls}" onclick="toggleCxExpand(this)">` +
      `<span class="wv-cx-rank">${rankHtml}</span>` +
      `<div class="wv-cx-art-wrap" onclick="event.stopPropagation()">` +
        `<div class="wv-thumb wv-thumb-sm">${_wvThumb(imgId, ttl)}</div>` +
        artTip +
      `</div>` +
      `<span class="wv-cx-title"><span class="wv-title-link" onclick="event.stopPropagation();_wvOpenModal(${jtype},${esc(JSON.stringify(k))})" title="View details">${esc(ttl)}</span>${pk ? peakBadge(pk) : ''}${cert}</span>` +
      `<span class="wv-cx-sep">—</span>` +
      `<span class="wv-cx-artist">${esc(sub)}</span>` +
      playBtn +
      cxPlBtn +
      `<span class="wv-cx-wks">${weeksText}</span>` +
      `<span class="wv-cx-prev">${prevContent}</span>` +
      `<span class="wv-cx-plays"${playsStyle}>${s.count}</span>` +
      shelf +
      `</div>`;
  }).join('');

  return `<div class="wv-compact">${header}${rows}</div>`;
}

function toggleCxExpand(row) {
  row.classList.toggle('wv-cx-open');
}

function _tmWorst(row, l) {
  const s = row.reduce((a, b) => a + b, 0);
  const maxA = Math.max(...row), minA = Math.min(...row);
  return Math.max((l * l * maxA) / (s * s), (s * s) / (l * l * minA));
}
function _tmRow(row, x, y, w, h) {
  const s = row.reduce((a, b) => a + b, 0);
  const out = [];
  if (w >= h) {
    const sw = s / h; let p = y;
    for (const a of row) { const ih = (a / s) * h; out.push([x, p, sw, ih]); p += ih; }
  } else {
    const sh = s / w; let p = x;
    for (const a of row) { const iw = (a / s) * w; out.push([p, y, iw, sh]); p += iw; }
  }
  return out;
}
function _computeTreemap(values, W, H) {
  const total = values.reduce((a, b) => a + b, 0);
  const areas = values.map(v => (v / total) * W * H);
  const all = [];
  let rem = [...areas], x = 0, y = 0, w = W, h = H;
  while (rem.length) {
    const l = Math.min(w, h);
    let row = [rem.shift()];
    while (rem.length) {
      const next = [...row, rem[0]];
      if (_tmWorst(next, l) <= _tmWorst(row, l)) { row = next; rem.shift(); } else break;
    }
    all.push(..._tmRow(row, x, y, w, h));
    const rs = row.reduce((a, b) => a + b, 0);
    if (w >= h) { const sw = rs / h; x += sw; w -= sw; }
    else { const sh = rs / w; y += sh; h -= sh; }
  }
  return all;
}
function _wvMosaic(items, max, ms, imgItems, type) {
  type = type || 'songs';
  const jtype = esc(JSON.stringify(type));
  const W = 1000;
  const H = Math.min(2800, 480 + items.length * 22);
  const vals = items.map(s => Math.sqrt(s.count));
  const rects = _computeTreemap(vals, W, H);
  return `<div class="wv-mosaic" style="height:${H}px">${items.map((s, i) => {
    const { k, imgId, mv, prefKey } = _wvItem(type, s, i, ms, imgItems);
    const backImgId = imgId + 'b';
    if (type === 'artists') imgItems.push({ imgId: backImgId, name: s.name, artist: s.name, prefKey });
    else if (type === 'albums') imgItems.push({ imgId: backImgId, album: s.album, artist: s.artist, name: s.album, prefKey });
    else imgItems.push({ imgId: backImgId, title: s.title, artist: s.artist, album: s.album, prefKey });
    const { ttl, sub } = _wvDisp(type, s);
    const [rx, ry, rw, rh] = rects[i];
    const st = `left:${(rx/W*100).toFixed(2)}%;top:${(ry/H*100).toFixed(2)}%;width:${(rw/W*100).toFixed(2)}%;height:${(rh/H*100).toFixed(2)}%;--bar-w:${Math.round(s.count/max*100)}%`;
    const rc = i < 3 ? ` wv-r${i+1}` : '';
    const pk = type === 'songs' ? _weeklyViewPeaks?.songPeakMap[k]
             : type === 'artists' ? _weeklyViewPeaks?.artistPeakMap[k]
             : _weeklyViewPeaks?.albumPeakMap[k];
    const wks = ms?.periodsOnChart[type][k] || null;
    const cumPlays = type === 'songs' ? (cumulativeMaps?.songs[k] || 0)
                   : type === 'albums' ? (cumulativeMaps?.albums[k] || 0) : 0;
    const cert = (type !== 'artists' && cumPlays) ? certBadge(cumPlays, type === 'songs' ? 'song' : 'album') : '';
    const playTitle  = type === 'songs' ? s.title  : type === 'artists' ? s.name  : s.album;
    const playArtist = type === 'songs' ? s.artist : type === 'artists' ? s.name  : s.artist;
    const playAlbum  = type === 'songs' ? (s.album || '') : type === 'artists' ? '' : s.album;
    // Songs play directly; artists and albums show the last-10 track picker
    // (an artist/album name is not a track, so searching it as one lands wrong)
    const mosYtOnclick = type === 'songs'
      ? `event.stopPropagation();ytPlayFromBtn(this)`
      : `event.stopPropagation();buShowTrackList(this,${jtype})`;
    const mosYtTitle = type === 'songs' ? 'Play on YouTube' : 'Show recently played tracks';
    return `<div class="wv-mos-item${rc}" style="${st}" title="#${i+1}: ${esc(ttl)} — ${esc(sub)}" onclick="wvMosTileClick(event,this)">
      <div class="wv-mos-item-inner">
        <div class="wv-mos-front">
          <div class="wv-thumb wv-thumb-full">${_wvThumb(imgId, ttl)}</div>
          <div class="wv-mos-top"></div>
          <span class="wv-rank-badge">${i+1}</span>
          ${mv ? `<div class="wv-mv-ov">${mv}</div>` : ''}
          <div class="wv-mos-bot"><div class="wv-ttl">${esc(ttl)}</div><div class="wv-art">${esc(sub)}</div><div class="wv-plays">${s.count} ${tUnit('plays', s.count)}</div></div>
          <div class="wv-mos-hcard">
            <button class="yt-play-btn wv-mos-play-btn" data-title="${esc(playTitle)}" data-artist="${esc(playArtist)}" data-album="${esc(playAlbum)}" onclick="${mosYtOnclick}" title="${mosYtTitle}"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg></button>${dcPlBtnHtml(dcPlKindFor(type), playTitle, playArtist, playAlbum, 'dc-pl-add-sm')}
            <div class="wv-mos-hcard-ttl"><span class="wv-title-link" onclick="event.stopPropagation();_wvOpenModal(${jtype},${esc(JSON.stringify(k))})" title="View details">${esc(ttl)}</span></div>
            <div class="wv-mos-hcard-art">${esc(sub)}</div>
            <div class="wv-mos-hcard-stats">
              ${pk ? peakBadge(pk) : ''}
              ${wks ? `<span class="wv-mos-hcard-wks">${wks} ${tUnit('weeks_full', wks)}</span>` : ''}
            </div>
            ${cumPlays ? `<div class="wv-mos-hcard-alltime">${cumPlays.toLocaleString()} ${tUnit('plays', cumPlays)} · ${t('nav_alltime')}${cert}</div>` : ''}
            <div class="wv-mos-hcard-bar"><div class="wv-mos-hcard-fill"></div></div>
          </div>
        </div>
        <div class="wv-mos-back">
          <button class="wv-mos-back-close" onclick="event.stopPropagation();wvMosaicCloseAll(this.closest('.wv-mosaic'))">×</button>
          <div class="wv-mos-back-header">
            <div class="wv-mos-back-img">${_wvThumb(backImgId, ttl)}</div>
            <div class="wv-mos-back-meta">
              <div class="wv-mos-back-rank-row"><span class="wv-mos-back-ranknum">#${i+1}</span>${mv ? `<span class="wv-mv-ov">${mv}</span>` : ''}</div>
              <div class="wv-mos-back-ttl"><span class="wv-title-link" onclick="event.stopPropagation();_wvOpenModal(${jtype},${esc(JSON.stringify(k))})" title="View details">${esc(ttl)}</span></div>
              <div class="wv-mos-back-sub">${esc(sub)}</div>
            </div>
          </div>
          <div class="wv-mos-back-plays">${s.count}<span class="wv-mos-back-plays-unit"> ${tUnit('plays', s.count)}</span></div>
          <div class="wv-mos-back-stats">
            ${pk ? peakBadge(pk) : ''}
            ${wks ? `<span class="wv-mos-hcard-wks">${wks} ${tUnit('weeks_full', wks)}</span>` : ''}
          </div>
          ${cumPlays ? `<div class="wv-mos-hcard-alltime">${cumPlays.toLocaleString()} ${tUnit('plays', cumPlays)} · ${t('nav_alltime')}${cert}</div>` : ''}
          <div class="wv-mos-hcard-bar"><div class="wv-mos-hcard-fill"></div></div>
          <button class="yt-play-btn wv-mos-play-btn wv-mos-back-play-btn" data-title="${esc(playTitle)}" data-artist="${esc(playArtist)}" data-album="${esc(playAlbum)}" onclick="${mosYtOnclick}" title="${mosYtTitle}"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg><span class="wv-btn-full"> ${mosYtTitle}</span><span class="wv-btn-short">${type === 'songs' ? 'PLAY' : 'TRACKS'}</span></button>${dcPlBtnHtml(dcPlKindFor(type), playTitle, playArtist, playAlbum, 'dc-pl-add-sm')}
        </div>
      </div>
    </div>`;
  }).join('')}</div>`;
}

function wvMosTileClick(e, el) {
  e.stopPropagation();
  const mosaic = el.closest('.wv-mosaic');
  const wasFlipped = el.classList.contains('wv-mos-flipped');
  wvMosaicCloseAll(mosaic);
  if (!wasFlipped) {
    const eRect = el.getBoundingClientRect();
    const mRect = mosaic.getBoundingClientRect();
    const minPx = 190;
    const scale = Math.min(Math.max(1, minPx / Math.min(eRect.width, eRect.height)), 2.8);
    if (scale > 1.05) {
      const cx = (eRect.left + eRect.width / 2 - mRect.left) / mRect.width;
      const cy = (eRect.top + eRect.height / 2 - mRect.top) / mRect.height;
      const ox = cx < 0.35 ? 'left' : cx > 0.65 ? 'right' : 'center';
      const oy = cy < 0.35 ? 'top' : cy > 0.65 ? 'bottom' : 'center';
      el.style.transformOrigin = `${oy} ${ox}`;
      el.style.transform = `scale(${scale.toFixed(2)})`;
    }
    el.classList.add('wv-mos-flipped');
  }
}
function wvMosaicCloseAll(mosaic) {
  if (!mosaic) return;
  mosaic.querySelectorAll('.wv-mos-flipped').forEach(t => {
    t.style.transform = '';
    t.style.transformOrigin = '';
    t.classList.remove('wv-mos-flipped');
  });
}

function _wvFilmstrip(items, max, ms, imgItems, type) {
  type = type || 'songs';
  const jtype = esc(JSON.stringify(type));
  const decades = [];
  for (let d = 0; d < items.length; d += 10) decades.push(d);

  const cards = items.map((s, i) => {
    const { k, imgId, mv } = _wvItem(type, s, i, ms, imgItems);
    const { ttl, sub } = _wvDisp(type, s);
    const barW = Math.round(s.count / max * 100);
    const _fPrev = ms ? ms.prevChart[type][k] : null;
    const barCls = !ms ? '' : !_fPrev && !ms.everChartedBefore[type].has(k) ? 'wv-bar-new' : !_fPrev ? 'wv-bar-re' : (_fPrev.rank-(i+1)) > 0 ? 'wv-bar-up' : (_fPrev.rank-(i+1)) < 0 ? 'wv-bar-down' : '';
    const pk = type === 'songs' ? _weeklyViewPeaks?.songPeakMap[k]
             : type === 'artists' ? _weeklyViewPeaks?.artistPeakMap[k]
             : _weeklyViewPeaks?.albumPeakMap[k];
    const wks = ms?.periodsOnChart?.[type]?.[k] || null;
    const cumPlays = type === 'songs' ? (cumulativeMaps?.songs[k] || 0)
                   : type === 'albums' ? (cumulativeMaps?.albums[k] || 0) : 0;
    const cert = (type !== 'artists' && cumPlays) ? certBadge(cumPlays, type === 'songs' ? 'song' : 'album') : '';
    const playTitle  = type === 'songs' ? s.title  : type === 'artists' ? s.name  : s.album;
    const playArtist = type === 'songs' ? s.artist : type === 'artists' ? s.name  : s.artist;
    const playAlbum  = type === 'songs' ? (s.album || '') : type === 'artists' ? '' : s.album;
    const rc = i < 3 ? ` wv-r${i+1}` : '';
    const thumbCls = i < 3 ? 'wv-thumb-xl' : 'wv-thumb-lg';
    const ytSvg = `<svg viewBox="0 0 24 24" fill="currentColor" style="width:14px;height:14px"><path d="M8 5v14l11-7z"/></svg>`;
    const ytSvgSm = `<svg viewBox="0 0 24 24" fill="currentColor" style="width:10px;height:10px;margin-right:3px"><path d="M8 5v14l11-7z"/></svg>`;
    // Songs play directly; artists and albums show the last-10 track picker
    const filmYtOnclick = type === 'songs'
      ? `event.stopPropagation();ytPlayFromBtn(this)`
      : `event.stopPropagation();buShowTrackList(this,${jtype})`;
    const filmYtTitle = type === 'songs' ? 'Play on YouTube' : 'Show recently played tracks';
    const filmYtLabel = type === 'songs' ? 'Play on YouTube' : 'Show Tracks';
    return `<div class="wv-card wv-film-card${rc}" tabindex="0" data-idx="${i}" onclick="wvFilmCardClick(event,this)">
      <div class="wv-film-rank-row">
        <span class="wv-film-ranknum">${i+1}</span>
        ${mv ? `<span class="wv-film-mv">${mv}</span>` : ''}
      </div>
      <div class="wv-film-thumb-wrap">
        <div class="wv-thumb ${thumbCls}">${_wvThumb(imgId, ttl)}</div>
        <div class="wv-film-thumb-hover">
          <button class="yt-play-btn wv-film-yt-btn" data-title="${esc(playTitle)}" data-artist="${esc(playArtist)}" data-album="${esc(playAlbum)}" onclick="${filmYtOnclick}" title="${filmYtTitle}">${ytSvg}</button>${dcPlBtnHtml(dcPlKindFor(type), playTitle, playArtist, playAlbum, 'dc-pl-add-sm')}
        </div>
      </div>
      <div class="wv-ttl"><span class="wv-title-link" onclick="event.stopPropagation();_wvOpenModal(${jtype},${esc(JSON.stringify(k))})" title="View details">${esc(ttl)}</span></div>
      <div class="wv-art">${esc(sub)}</div>
      <div class="wv-plays">${s.count} plays</div>
      <div class="wv-bar"><div class="wv-bar-fill${barCls ? ' '+barCls : ''}" style="width:${barW}%"></div></div>
      <div class="wv-film-expand"><div class="wv-film-expand-inner">
        ${(pk || cert) ? `<div class="wv-film-exp-badges">${pk ? peakBadge(pk) : ''}${cert}</div>` : ''}
        ${wks ? `<div class="wv-film-exp-wks">${tCount('weeks_full', wks)} ${t('film_on_chart')}</div>` : ''}
        ${cumPlays ? `<div class="wv-film-exp-alltime">${cumPlays.toLocaleString()} ${t('film_alltime_plays')}</div>` : ''}
        <button class="yt-play-btn" data-title="${esc(playTitle)}" data-artist="${esc(playArtist)}" data-album="${esc(playAlbum)}" onclick="${filmYtOnclick}" title="${filmYtTitle}" style="margin-top:4px">${ytSvgSm}${filmYtLabel}</button>${dcPlBtnHtml(dcPlKindFor(type), playTitle, playArtist, playAlbum, 'dc-pl-add-sm')}
      </div></div>
    </div>`;
  }).join('');

  const jumpBtns = decades.map(d =>
    `<button class="wv-film-jump-btn" onclick="wvFilmJump(${d},'${type}')">#${d+1}</button>`
  ).join('');

  return `<div class="wv-film-wrap">
    <div class="wv-film-controls">
      <div class="wv-film-jump-btns">${jumpBtns}</div>
      <div class="wv-film-action-btns">
        <button class="wv-film-auto-btn" id="wv-film-auto-${type}" onclick="wvFilmAutoScroll('${type}')">▶ Auto</button>
        <button class="wv-film-share-btn" onclick="shareFilmstrip('${type}')">⬇ Save</button>
      </div>
    </div>
    <div class="wv-filmstrip" id="wv-filmstrip-${type}">${cards}</div>
    <div class="wv-film-scrolltrack" id="wv-film-track-${type}">
      <div class="wv-film-scrollfill" id="wv-film-fill-${type}"></div>
    </div>
  </div>`;
}

function wvFilmCardClick(event, card) {
  if (event.target.closest('button')) return;
  card.classList.toggle('wv-film-open');
}

function wvFilmJump(idx, type) {
  const strip = document.getElementById('wv-filmstrip-' + type);
  if (!strip) return;
  const card = strip.querySelectorAll('.wv-film-card')[idx];
  if (card) {
    strip.scrollTo({ left: card.offsetLeft - 8, behavior: 'smooth' });
    card.focus({ preventScroll: true });
  }
}

function wvFilmAutoScroll(type) {
  const strip = document.getElementById('wv-filmstrip-' + type);
  const btn = document.getElementById('wv-film-auto-' + type);
  const scrollTrack = document.getElementById('wv-film-track-' + type);
  if (!strip || !btn) return;

  if (strip.classList.contains('wv-film-auto-mode')) {
    // Stop: unwrap the auto track, restore original cards
    const track = strip.querySelector('.wv-film-auto-track');
    if (track) {
      Array.from(track.querySelectorAll('.wv-film-card:not([data-auto-clone])')).forEach(c => strip.appendChild(c));
      track.remove();
    }
    strip.classList.remove('wv-film-auto-mode');
    btn.classList.remove('wv-film-auto-on');
    btn.textContent = '▶ Auto';
    if (scrollTrack) scrollTrack.style.display = '';
  } else {
    // Start: wrap cards in a track, duplicate, animate infinitely
    const cards = Array.from(strip.querySelectorAll('.wv-film-card'));
    if (!cards.length) return;
    const track = document.createElement('div');
    track.className = 'wv-film-auto-track';
    cards.forEach(c => track.appendChild(c));
    cards.map(c => { const cl = c.cloneNode(true); cl.setAttribute('data-auto-clone', '1'); return cl; })
         .forEach(c => track.appendChild(c));
    strip.appendChild(track);
    track.style.animationDuration = Math.max(20, cards.length * 3) + 's';
    strip.classList.add('wv-film-auto-mode');
    btn.classList.add('wv-film-auto-on');
    btn.textContent = '⏸ Auto';
    if (scrollTrack) scrollTrack.style.display = 'none';
  }
}

async function shareFilmstrip(type) {
  const strip = document.getElementById('wv-filmstrip-' + type);
  if (!strip || typeof html2canvas === 'undefined') return;

  const btn = strip.closest('.wv-film-wrap')?.querySelector('.wv-film-share-btn');
  const origText = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Saving…'; }

  // Clone off-screen at full scrollable width so html2canvas captures all cards
  const fullW = strip.scrollWidth;
  const fullH = strip.scrollHeight;
  const clone = strip.cloneNode(true);
  Object.assign(clone.style, {
    position: 'fixed', left: '-99999px', top: '0',
    overflow: 'visible', width: fullW + 'px', height: fullH + 'px',
    flexShrink: '0', animation: 'none'
  });
  document.body.appendChild(clone);

  // Pre-convert cross-origin images to data URLs so the canvas isn't tainted
  await Promise.all(Array.from(clone.querySelectorAll('img')).map(img => new Promise(resolve => {
    if (!img.src || img.src.startsWith('data:')) { resolve(); return; }
    const t = new Image();
    t.crossOrigin = 'anonymous';
    const timer = setTimeout(() => { img.style.visibility = 'hidden'; resolve(); }, 3000);
    t.onload = () => {
      clearTimeout(timer);
      try {
        const c = document.createElement('canvas');
        c.width = t.naturalWidth; c.height = t.naturalHeight;
        c.getContext('2d').drawImage(t, 0, 0);
        img.src = c.toDataURL();
      } catch { img.style.visibility = 'hidden'; }
      resolve();
    };
    t.onerror = () => { clearTimeout(timer); img.style.visibility = 'hidden'; resolve(); };
    t.src = img.src;
  })));

  try {
    const cvs = await html2canvas(clone, {
      scale: 2, useCORS: false, allowTaint: false,
      backgroundColor: '#0f172a', logging: false,
      width: fullW, height: fullH
    });
    const link = document.createElement('a');
    const { label } = getDateRange();
    link.download = `filmstrip-${type}-${(label||'chart').replace(/[^a-z0-9]/gi,'-')}.png`;
    link.href = cvs.toDataURL('image/png');
    link.click();
    if (btn) { btn.textContent = '✓ Saved'; setTimeout(() => { btn.textContent = origText; btn.disabled = false; }, 2000); }
  } catch(e) {
    console.error('shareFilmstrip', e);
    if (btn) { btn.textContent = origText; btn.disabled = false; }
  } finally {
    clone.remove();
  }
}

function initFilmstripInteractions(type) {
  const strip = document.getElementById('wv-filmstrip-' + type);
  if (!strip) return;

  // Drag to scroll
  let isDragging = false, dragStartX = 0, dragScrollLeft = 0;
  strip.addEventListener('mousedown', e => {
    if (e.button !== 0) return;
    isDragging = true;
    dragStartX = e.pageX - strip.getBoundingClientRect().left;
    dragScrollLeft = strip.scrollLeft;
    strip.classList.add('is-dragging');
  });
  strip.addEventListener('mousemove', e => {
    if (!isDragging) return;
    e.preventDefault();
    strip.scrollLeft = dragScrollLeft - (e.pageX - strip.getBoundingClientRect().left - dragStartX);
  });
  const endDrag = () => { isDragging = false; strip.classList.remove('is-dragging'); };
  strip.addEventListener('mouseup', endDrag);
  strip.addEventListener('mouseleave', endDrag);

  // Mouse wheel scrolls horizontally
  strip.addEventListener('wheel', e => {
    if (e.deltaY === 0) return;
    e.preventDefault();
    strip.scrollLeft += e.deltaY;
  }, { passive: false });

  // Scroll position indicator
  const fill = document.getElementById('wv-film-fill-' + type);
  if (fill) {
    const updateFill = () => {
      const maxScroll = strip.scrollWidth - strip.clientWidth;
      const pct = maxScroll > 0 ? strip.scrollLeft / maxScroll : 0;
      fill.style.width = Math.max(6, Math.round(pct * 94) + 6) + '%';
    };
    strip.addEventListener('scroll', updateFill, { passive: true });
    updateFill();
  }

  // Keyboard navigation
  strip.addEventListener('keydown', e => {
    const cards = Array.from(strip.querySelectorAll('.wv-film-card'));
    const focused = strip.querySelector('.wv-film-card:focus');
    if (!focused) return;
    const idx = cards.indexOf(focused);
    if (e.key === 'ArrowRight' && idx < cards.length - 1) {
      cards[idx + 1].focus();
      cards[idx + 1].scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'start' });
      e.preventDefault();
    } else if (e.key === 'ArrowLeft' && idx > 0) {
      cards[idx - 1].focus();
      cards[idx - 1].scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'start' });
      e.preventDefault();
    }
  });

  // Pinch to zoom (touch)
  let pinchDist0 = null, pinchBaseW = null;
  strip.addEventListener('touchstart', e => {
    if (e.touches.length === 2) {
      pinchDist0 = Math.hypot(e.touches[0].pageX - e.touches[1].pageX, e.touches[0].pageY - e.touches[1].pageY);
      const first = strip.querySelector('.wv-film-card');
      pinchBaseW = first ? first.offsetWidth : 155;
    }
  }, { passive: true });
  strip.addEventListener('touchmove', e => {
    if (e.touches.length !== 2 || !pinchDist0) return;
    const dist = Math.hypot(e.touches[0].pageX - e.touches[1].pageX, e.touches[0].pageY - e.touches[1].pageY);
    const newW = Math.max(90, Math.min(240, Math.round(pinchBaseW * dist / pinchDist0)));
    strip.querySelectorAll('.wv-film-card').forEach(c => { c.style.flex = `0 0 ${newW}px`; });
  }, { passive: true });
  strip.addEventListener('touchend', () => { pinchDist0 = null; }, { passive: true });
}

function _wvStack(items, max, ms, imgItems, type) {
  type = type || 'songs';
  const crData = allChartRun?.week || chartRunData;
  return `<div class="wv-stack${_stkTwoCol ? ' wv-stack-2col' : ''}">${items.map((s, i) => {
    const { k, imgId, mv } = _wvItem(type, s, i, ms, imgItems);
    const { ttl, sub } = _wvDisp(type, s);
    const pk = type === 'songs' ? _weeklyViewPeaks?.songPeakMap[k] : null;
    const cumSongPlays = type === 'songs' && cumulativeMaps ? (cumulativeMaps.songs[k] || 0) : 0;
    const weeks = ms ? (ms.periodsOnChart[type][k] || 1) : null;
    const weeksText = weeks ? `<span class="wv-wks">${weeks} ${weeks === 1 ? 'week' : 'weeks'}</span>` : '';
    const barW = Math.round(s.count / max * 100);

    // Movement direction for bar color and debut/re border
    const prevEntry = ms ? ms.prevChart[type][k] : null;
    const isNew = ms && !prevEntry && !ms.everChartedBefore[type].has(k);
    const isRe  = ms && !prevEntry &&  ms.everChartedBefore[type].has(k);
    const mvDiff = prevEntry ? (prevEntry.rank - (i + 1)) : null;
    const barCls = isNew ? 'wv-bar-new' : isRe ? 'wv-bar-re' : mvDiff > 0 ? 'wv-bar-up' : mvDiff < 0 ? 'wv-bar-down' : '';
    const statusCls = isNew ? ' wv-stk-new' : isRe ? ' wv-stk-re' : '';

    // Album inline (songs only, same title row, dimmed)
    const albumName = type === 'songs' && s.album && s.album !== '—' ? s.album : '';
    const albumInline = albumName ? ` <span class="wv-stk-alb-inline">· ${esc(albumName)}</span>` : '';

    // Cumulative plays
    const cumHtml = cumSongPlays > 0 ? `<span class="wv-stk-cum">${cumSongPlays} all-time</span>` : '';

    // YT play button
    const jt = esc(JSON.stringify(ttl));
    const jar = esc(JSON.stringify(type !== 'artists' ? sub : ''));
    const jal = esc(JSON.stringify(s.album || ''));
    const jtype = esc(JSON.stringify(type));
    // Songs play directly; artists and albums show the last-10 track picker,
    // since their name is not something to search as a track. Artists carry
    // their own name in data-artist and no album at all.
    const tlArtist = type === 'artists' ? s.name : (s.artist || '');
    const tlAlbum  = type === 'artists' ? ''     : (s.album  || '');
    const ytBtn = type === 'songs'
      ? `<button class="wv-stk-yt-btn" onclick="event.stopPropagation();_ytPlayOrQueue(${jt},${jar},${jal})" title="Play on YouTube">▶</button>`
      : `<button class="wv-stk-yt-btn" data-artist="${esc(tlArtist)}" data-album="${esc(tlAlbum)}" onclick="event.stopPropagation();buShowTrackList(this,${jtype})" title="Show recently played tracks">▶</button>`;

    // Artist line — plain display only; no modal opens from here
    const artistLine = `<div class="wv-art">${esc(sub)}</div>`;

    // Title — clickable → opens the matching artist/album/song detail modal
    const jmodalKey = esc(JSON.stringify(k));
    const ttlInner = `<span class="wv-stk-artist" onclick="event.stopPropagation();_wvOpenModal(${jtype},${jmodalKey})">${esc(ttl)}</span>`;

    // Expand shelf: chart run summary + squares
    const crD = crData?.result?.[type]?.[k];
    const crPeak = crD ? crD.peak : null;
    const crWks  = crD ? crD.entries.length : null;
    const sumParts = [];
    if (crWks)  sumParts.push(`${crWks} ${crWks === 1 ? 'week' : 'weeks'} on chart`);
    if (crPeak) sumParts.push(`peaked #${crPeak}`);
    const summaryHtml = sumParts.length ? `<div class="wv-stk-shelf-sum">${sumParts.join(' · ')}</div>` : '';
    const shelf = `<div class="wv-stk-shelf">${summaryHtml}${crBoxesHTML(type, k, crData)}</div>`;

    return `<div class="wv-stk-card${i < 3 ? ' wv-r' + (i+1) : ''}${statusCls}" tabindex="0" onclick="toggleStkExpand(this)">
      <div class="wv-stk-row">
        <div class="wv-stk-rank">${i+1}</div>
        <div class="wv-thumb wv-thumb-lg">${_wvThumb(imgId, ttl)}</div>
        <div class="wv-stk-body">
          <div class="wv-ttl">${ttlInner}${albumInline}${pk ? peakBadge(pk) : ''}${type === 'songs' ? certBadge(cumSongPlays, 'song') : ''}</div>
          ${artistLine}
          <div class="wv-stk-meta">${ytBtn}${dcPlBtnForWv(type, ttl, sub, s.album, 'dc-pl-add-sm')}<span class="wv-plays">${s.count} ${s.count===1?'play':'plays'}</span> ${mv}${weeksText}${cumHtml}</div>
          <div class="wv-bar"><div class="wv-bar-fill${barCls ? ' '+barCls : ''}" style="width:${barW}%"></div></div>
        </div>
      </div>
      ${shelf}
    </div>`;
  }).join('')}</div>`;
}

function toggleStkExpand(card) {
  card.classList.toggle('wv-stk-open');
}

function toggleStkTwoCol() {
  _stkTwoCol = !_stkTwoCol;
  try { localStorage.setItem('dc_stk_2col', _stkTwoCol ? '1' : '0'); } catch(e) {}
  document.querySelectorAll('.stk-2col-btn').forEach(b => b.classList.toggle('active', _stkTwoCol));
  applyWeeklyChartView();
}

function initStkInteractions(type) {
  const container = document.getElementById('weeklyAltView-' + type);
  if (!container) return;

  // Keyboard: ↑↓ navigate, Enter/Space expand, P play
  container.addEventListener('keydown', e => {
    const focused = document.activeElement;
    if (!focused?.classList.contains('wv-stk-card')) return;
    const cards = Array.from(container.querySelectorAll('.wv-stk-card'));
    const idx = cards.indexOf(focused);
    if (idx === -1) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); cards[Math.min(idx + 1, cards.length - 1)]?.focus(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); cards[Math.max(idx - 1, 0)]?.focus(); }
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleStkExpand(focused); }
    else if (e.key === 'p' || e.key === 'P') { e.preventDefault(); focused.querySelector('.wv-stk-yt-btn')?.click(); }
  });

  // Swipe right → play on YT
  container.querySelectorAll('.wv-stk-card').forEach(card => {
    let tx0 = 0, ty0 = 0;
    card.addEventListener('touchstart', e => { tx0 = e.changedTouches[0].clientX; ty0 = e.changedTouches[0].clientY; }, { passive: true });
    card.addEventListener('touchend', e => {
      const dx = e.changedTouches[0].clientX - tx0;
      const dy = e.changedTouches[0].clientY - ty0;
      if (Math.abs(dx) > 55 && Math.abs(dy) < 35 && dx > 0) card.querySelector('.wv-stk-yt-btn')?.click();
    }, { passive: true });
  });
}

// ─── OFF THE CHART (per-type, weekly-only) ─────────────────────
// Entries that dropped out of the Top N since last week, rendered as its
// own accordion per type (songs/artists/albums) — sits between Bubbling
// Under and New Entries for that type. Was previously one combined section
// with all three types side by side; each type is now fully independent.
function renderOffChart(type, plays, periodStats, buPool, lowestChartCount) {
  const ucType    = type.charAt(0).toUpperCase() + type.slice(1);
  const sectionEl = document.getElementById('off' + ucType + 'Section');
  if (!sectionEl) return;
  if (!periodStats || currentPeriod !== 'week') { sectionEl.style.display = 'none'; return; }

  // Current week's chart keys for this type — must use rankSortWithStatus to match main chart tiebreakers
  const counts = {};
  if (type === 'songs') {
    for (const p of plays) {
      const k = songKey(p);
      if (!counts[k]) counts[k] = { count: 0, firstAchieved: p.date };
      counts[k].count++;
    }
  } else if (type === 'artists') {
    for (const p of plays) {
      for (const a of p.artists) {
        if (!counts[a]) counts[a] = { count: 0, firstAchieved: p.date };
        counts[a].count++;
      }
    }
  } else {
    for (const p of plays) {
      if (!p.album || p.album === '—') continue;
      const k = albumKeyOf(p);
      if (!counts[k]) counts[k] = { count: 0, firstAchieved: p.date };
      counts[k].count++;
    }
  }
  for (const [k, d] of Object.entries(counts)) {
    const prev = periodStats.prevChart[type][k];
    d.chartStatus = prev !== undefined ? 0 : periodStats.everChartedBefore[type].has(k) ? 1 : 2;
    d.prevRank = prev !== undefined ? prev.rank : Infinity;
  }
  const curKeys = new Set(Object.entries(counts).sort(([, a], [, b]) => rankSortWithStatus(a, b)).slice(0, chartSize).map(([k]) => k));

  // Dropouts: in previous week's chart but not in this week's
  const dropped = Object.entries(periodStats.prevChart[type])
    .filter(([k]) => !curKeys.has(k)).sort((a, b) => a[1].rank - b[1].rank);

  // With no previous week's chart to compare against there's nothing to report,
  // so stay hidden. But if a previous chart exists and nothing dropped out, that's
  // a stability streak worth showing off rather than silently disappearing.
  const hadPrevChart = Object.keys(periodStats.prevChart[type]).length > 0;
  if (!dropped.length && !hadPrevChart) { sectionEl.style.display = 'none'; return; }

  // Name lookup for songs and albums (keys are lowercase, need original casing)
  const names = {};
  if (type === 'songs') {
    for (const p of allPlays) {
      const k = songKey(p);
      if (!names[k]) names[k] = { title: p.title, artist: p.artist, album: p.album };
    }
  } else if (type === 'albums') {
    for (const p of allPlays) {
      const k = albumKeyOf(p);
      if (!names[k]) names[k] = { album: p.album, artist: albumArtist(p) };
    }
  }

  sectionEl.style.display = '';
  const subEl   = document.getElementById('off' + ucType + 'Sub');
  const countEl = document.getElementById('off' + ucType + 'Count');
  const bodyEl  = document.getElementById('off' + ucType + 'Body');
  const iconEl  = document.getElementById('off' + ucType + 'ToggleIcon');
  if (subEl)   { subEl.dataset.i18nN = chartSize; subEl.textContent = t('sub_off_chart', { n: chartSize }); }
  if (countEl) countEl.textContent = dropped.length;
  if (bodyEl)  bodyEl.style.display = _offOpen[type] ? '' : 'none';
  if (iconEl)  iconEl.textContent = _offOpen[type] ? '▲' : '▼';

  // Nothing dropped out this week — celebrate the stability instead of hiding.
  if (!dropped.length) {
    const contentEl = document.getElementById('off' + ucType + 'Content');
    if (contentEl) contentEl.innerHTML = `<div class="dropout-empty">${t('off_chart_empty', { n: chartSize })}</div>`;
    return;
  }

  // A dropout that fell from a top-tier rank (top ~30% of the chart) reads as
  // much bigger news than one that was already clinging to the bottom — flag
  // it so the eye catches the real story first instead of treating every row
  // as equally significant.
  const severeRankCutoff = Math.max(1, Math.floor(chartSize * 0.3));

  // Cross-reference with this week's Bubbling Under zone: a dropout that landed
  // there had a soft landing (still hovering just below the chart) rather than
  // vanishing outright. Map key → its BU rank + count so rows can link the two.
  const buMap = new Map((buPool || []).map((item, i) => [item.key, { rank: chartSize + 1 + i, count: item.count }]));

  const rows = dropped.map(([k, { rank, count }]) => {
    // Lifetime total weeks charted, ever — may span several separate,
    // non-consecutive stints. The run that just ended (streakWks below) is
    // called out separately so the two aren't conflated.
    const wks = periodStats.periodsOnChart[type][k] || 1;
    // The consecutive run immediately before THIS drop, even if the entry had
    // an earlier streak at some other point in its history.
    const streakWks = periodStats.chartStreakAtPrev?.[type]?.[k] || 0;
    let name, sub;
    if (type === 'songs') { name = names[k]?.title || k.split('|||')[0]; sub = names[k]?.artist || ''; }
    else if (type === 'artists') { name = k; sub = ''; }
    else { name = names[k]?.album || k.split('|||')[0]; sub = names[k]?.artist || ''; }

    // YouTube button — same play/track-list pattern as Bubbling Under's ytBtn:
    // songs play directly, artists/albums open a last-10-tracks picker.
    const ytTitle  = type === 'songs'   ? name : '';
    const ytArtist = type === 'artists' ? name : sub;
    const ytAlbum  = type === 'albums'  ? name : (type === 'songs' ? (names[k]?.album || '') : '');
    const ytBtnOnclick = type === 'songs'
      ? `event.stopPropagation();ytPlayFromBtn(this)`
      : `event.stopPropagation();buShowTrackList(this,${esc(JSON.stringify(type))})`;
    const ytBtnTitle = t(type === 'songs' ? 'bu_yt_play_title' : 'bu_yt_tracks_title');
    const ytBtn = `<button class="yt-play-btn off-yt-btn" data-title="${esc(ytTitle)}" data-artist="${esc(ytArtist)}" data-album="${esc(ytAlbum)}" onclick="${ytBtnOnclick}" title="${ytBtnTitle}"><span class="yt-btn-content"><svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>YouTube</span></button>`
      + dcPlBtnHtml(dcPlKindFor(type), ytTitle, ytArtist, ytAlbum);

    const severeCls = rank <= severeRankCutoff ? ' dropout-row--severe' : '';

    // Idea 3+5: if this dropout landed in the Bubbling Under zone this week
    // rather than vanishing outright, say so and borrow the same badge
    // vocabulary used in the Bubbling Under section itself — a user who
    // recognizes those badges down there recognizes them here too.
    let buLineHtml = '';
    const buEntry = buMap.get(k);
    if (buEntry) {
      const totalBuWeeks      = periodStats.bubblingUnderWeeks?.[type]?.[k] || 0;
      const consecutiveBuWeeks = periodStats.bubblingUnderStreak?.[type]?.[k] || 0;
      const playsAway = Math.max(0, (lowestChartCount || 0) - buEntry.count);
      let buBadges = '';
      if (rank <= 3) buBadges += `<span class="bu-badge bu-badge-fallen" title="${t('bu_badge_fallen_title', { n: rank })}">${t('bu_badge_fallen')}</span>`;
      if (playsAway > 0) buBadges += `<span class="bu-badge bu-badge-away" title="${t(playsAway === 1 ? 'off_bu_reenter_title_one' : 'off_bu_reenter_title_other', { n: playsAway })}">${t(playsAway === 1 ? 'bu_badge_away_one' : 'bu_badge_away_other', { n: playsAway })}</span>`;
      if (totalBuWeeks >= 2) buBadges += `<span class="bu-badge bu-badge-weeks" title="${t('bu_badge_weeks_title', { n: totalBuWeeks })}">${t('bu_badge_weeks_label', { n: totalBuWeeks })}</span>`;
      if (consecutiveBuWeeks >= 2) buBadges += `<span class="bu-badge bu-badge-streak" title="${t('bu_badge_streak_title', { n: consecutiveBuWeeks })}">${t('bu_badge_streak_label', { n: consecutiveBuWeeks })}</span>`;
      buLineHtml = `<div class="dropout-bu-line"><span class="dropout-bu-now">${t('off_bu_now_at', { n: buEntry.rank })}</span>${buBadges}</div>`;
    } else {
      // Not even in the Bubbling Under zone — say so explicitly instead of
      // leaving the absence of a BU line to be read as a gap in the data.
      const thisWeekCount = counts[k]?.count || 0;
      const goneNote = thisWeekCount > 0
        ? t(thisWeekCount === 1 ? 'off_bu_gone_one' : 'off_bu_gone_other', { n: thisWeekCount })
        : t('off_bu_no_plays');
      buLineHtml = `<div class="dropout-bu-line dropout-bu-line--gone"><span class="dropout-bu-gone">${esc(goneNote)}</span></div>`;
    }

    // Idea 1: only worth calling out if this entry once did BETTER than the
    // rank it just fell from — restating "Peak #9" next to "Was #9" is noise,
    // but "Peak #1" next to "Was #9" is the actual story.
    const pk = periodStats.peakRank?.[type]?.[k];
    const peakBadgeHtml = (pk && pk < rank) ? peakBadge(pk) : '';

    // Only ever having charted once, period, is worth muting — but not the
    // lifetime total in general, since that would misrepresent an entry with
    // several separate stints as unremarkable.
    const wksCls = wks === 1 ? ' dropout-wks--flash' : '';

    // Distinct from the lifetime total: call out a real (2+ week) consecutive
    // run immediately before THIS drop, explicitly anchored to "before dropping
    // out" so it can't be mistaken for some earlier streak in the entry's history.
    const streakNoteHtml = streakWks >= 2
      ? `<div class="dropout-streak-note">${t('off_chart_streak_before_drop', { n: streakWks })}</div>`
      : '';

    return `<div class="dropout-row${severeCls}">
      <span class="dropout-rank"><span class="dropout-rank-was">${t('off_chart_rank_was')}</span>#${rank}</span>
      <div class="dropout-info">
        <div class="dropout-name-row">
          <span class="dropout-name">${esc(name)}</span>
          ${peakBadgeHtml}
        </div>
        ${sub ? `<div class="dropout-artist">${esc(sub)}</div>` : ''}
        ${streakNoteHtml}
        ${buLineHtml}
        ${ytBtn}
      </div>
      <div class="dropout-stats">
        <span class="dropout-plays">${tCountHtml('plays', count)}</span>
        <span class="dropout-wks${wksCls}">${tCount('weeks_full', wks)} ${t('film_on_chart')}</span>
      </div>
    </div>`;
  }).join('');

  const contentEl = document.getElementById('off' + ucType + 'Content');
  if (contentEl) contentEl.innerHTML = rows;
}

// ─── CERTIFICATIONS ────────────────────────────────────────────
const CERT_DEFAULTS = {
  song:  { gold: 50,  plat: 100, diamond: 200 },
  album: { gold: 120, plat: 300, diamond: 600 }
};
const CERT = {
  song:  { gold: 50,  plat: 100, diamond: 200 },
  album: { gold: 120, plat: 300, diamond: 600 }
};
(function () {
  try {
    const saved = JSON.parse(localStorage.getItem('dc_cert_config') || 'null');
    if (!saved) return;
    if (saved.ag > 0) CERT.album.gold    = saved.ag;
    if (saved.ap > 0) CERT.album.plat    = saved.ap;
    if (saved.ad > 0) CERT.album.diamond = saved.ad;
    if (saved.sg > 0) CERT.song.gold    = saved.sg;
    if (saved.sp > 0) CERT.song.plat    = saved.sp;
    if (saved.sd > 0) CERT.song.diamond = saved.sd;
  } catch (e) {}
})();

function diamondMultiLabel(n) {
  if (n === 1) return { icon: '💎', label: 'Diamond' };
  if (n === 2) return { icon: '💎💎', label: 'Double Diamond' };
  if (n === 3) return { icon: '💎💎💎', label: 'Triple Diamond' };
  return { icon: '💎', label: `${n}× Diamond` };
}
function tDiamondLabel(mult) {
  if (mult === 1) return t('cert_diamond');
  if (mult === 2) return t('cert_dbl_diamond');
  if (mult === 3) return t('cert_tri_diamond');
  return t('cert_nx_diamond', { n: mult });
}

function certBadge(plays, type) {
  const certTiers = CERT[type];
  if (!certTiers) return '';
  if (plays >= certTiers.diamond) {
    const { icon, label } = diamondMultiLabel(Math.floor(plays / certTiers.diamond));
    return `<span class="cert cert-diamond"><span class="cert-icon">${icon}</span>${label.toUpperCase()}</span>`;
  }
  if (plays >= certTiers.plat) return `<span class="cert cert-plat"><span class="cert-icon">💿</span>PLATINUM</span>`;
  if (plays >= certTiers.gold) return `<span class="cert cert-gold"><span class="cert-icon">🪙</span>GOLD</span>`;
  return '';
}

// ─── EXPORT PLAYLIST ───────────────────────────────────────────
let _exportSongsOverride = null;

function getCurrentChartSongs() {
  if (_exportSongsOverride) return _exportSongsOverride;
  // fullData.songs is always set by renderSongs/buildSongsFull with the correct sort
  // (rankSortWithStatus for weekly/monthly, rankSort for yearly/alltime) and the
  // correct size limit, so use it directly for all periods.
  return fullData.songs.map(s => ({ title: s.title, artist: s.artist, album: s.album || '' }));
}

let exportReversed = false;
let exportWithAlbum = false;

function buildExportText(songs) {
  const list = exportReversed ? [...songs].reverse() : songs;
  return list.map(s => {
    const base = `${s.artist} - ${s.title}`;
    return (exportWithAlbum && s.album && s.album !== '—') ? `${base} - ${s.album}` : base;
  }).join('\n');
}

function toggleExportOrder() {
  exportReversed = !exportReversed;
  const btn = document.getElementById('exportOrderBtn');
  btn.textContent = exportReversed ? t('export_no1_last') : t('export_no1_first');
  const songs = getCurrentChartSongs();
  document.getElementById('exportTracklist').textContent = buildExportText(songs);
}

function toggleExportAlbum() {
  exportWithAlbum = !exportWithAlbum;
  const btn = document.getElementById('exportAlbumBtn');
  btn.textContent = exportWithAlbum ? '✓ + Album' : '+ Album';
  btn.classList.toggle('active', exportWithAlbum);
  const songs = getCurrentChartSongs();
  document.getElementById('exportTracklist').textContent = buildExportText(songs);
}

function generatePlaylistNames(songs, periodName) {
  const names = new Set();
  const { label, sub } = getDateRange();
  const weekLabel = currentPeriod === 'week' ? sub : label; // sub has actual dates e.g. "Apr 5 – Apr 11, 2026"

  // ── Chart-based names ──
  if (currentPeriod === 'week') {
    names.add(t('export_pn_week_top', { n: songs.length, date: weekLabel }));
    names.add(t('export_pn_week_my', { date: weekLabel }));
    names.add(t('export_pn_week_picks', { date: weekLabel }));
    names.add(t('export_pn_week_hits', { date: weekLabel }));
  } else if (currentPeriod === 'month') {
    names.add(t('export_pn_month_top', { n: songs.length, label }));
    names.add(t('export_pn_month_favorites', { label }));
    names.add(t('export_pn_month_playlist', { label }));
    names.add(t('export_pn_best_of', { label }));
  } else if (currentPeriod === 'year') {
    names.add(t('export_pn_month_top', { n: songs.length, label }));
    names.add(t('export_pn_best_of', { label }));
    names.add(t('export_pn_year_highlights', { label }));
    names.add(t('export_pn_year_soundtrack', { label }));
    names.add(t('export_pn_year_chart', { label }));
  } else if (currentPeriod === 'alltime') {
    names.add(t('export_pn_alltime_top', { n: songs.length }));
    names.add(t('export_pn_alltime_favorites'));
    names.add(t('export_pn_alltime_greatest'));
    names.add(t('export_pn_alltime_definitive'));
  }

  // ── Artist-based names ──
  // Count plays per artist across the song list
  const artistCount = {};
  for (const s of songs) {
    const primary = s.artist.split(',')[0].trim();
    artistCount[primary] = (artistCount[primary] || 0) + 1;
  }
  const topArtists = Object.entries(artistCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([a]) => a);

  const [a1, a2, a3] = topArtists;
  const a1Share = a1 ? artistCount[a1] / songs.length : 0;

  if (a1 && a1Share >= 0.5) {
    names.add(t('export_pn_artist_best_of', { artist: a1 }));
    names.add(t('export_pn_artist_top_tracks', { artist: a1 }));
    names.add(t('export_pn_artist_essentials', { artist: a1 }));
  } else if (a1 && a2 && a1Share >= 0.25) {
    names.add(t('export_pn_artist_and_more', { artist: a1 }));
    names.add(t('export_pn_two_artist_mix', { a1, a2 }));
  } else if (a1 && a2 && a3) {
    names.add(t('export_pn_artists_and_more', { a1, a2 }));
    names.add(t('export_pn_feat_three', { a1, a2, a3 }));
  } else if (a1 && a2) {
    names.add(t('export_pn_two_and_mix', { a1, a2 }));
  }

  // ── Song count flavour ──
  const n = songs.length;
  if (n <= 10) names.add(t('export_pn_the_top', { n }));
  else if (n <= 50) names.add(t('export_pn_top_picks', { n }));
  else names.add(t('export_pn_top_tracks', { n }));

  return [...names];
}

function openExportModal() {
  const songs = getCurrentChartSongs();
  const { label } = getDateRange();
  const periodName = currentPeriod === 'alltime' ? t('period_alltime') :
    currentPeriod === 'week' ? t('period_week_of', { date: label }) :
      label;

  document.getElementById('exportModalSubtitle').textContent =
    t('export_subtitle', { count: tCount('songs', songs.length), period: periodName });

  // Playlist name suggestions
  const names = generatePlaylistNames(songs, periodName);
  document.getElementById('exportNameChips').innerHTML = names.map(name =>
    `<button class="export-name-chip" onclick="copyChipName(this,'${esc(name)}')">${esc(name)}</button>`
  ).join('');

  exportReversed = false;
  exportWithAlbum = false;
  document.getElementById('exportOrderBtn').textContent = t('export_no1_first');
  const albumBtn = document.getElementById('exportAlbumBtn');
  if (albumBtn) { albumBtn.textContent = '+ Album'; albumBtn.classList.remove('active'); }
  document.getElementById('exportTracklist').textContent = buildExportText(songs);

  document.getElementById('exportNoteBody').innerHTML =
    `<strong style="color:var(--text2)">${t('export_how_to_title')}</strong><br>` +
    `1. ${t('export_how_to_step1')}<br>` +
    `2. ${t('export_how_to_step2')}<br>` +
    `&nbsp;&nbsp;&nbsp;${t('export_how_to_step2b')}<br>` +
    `3. ${t('export_how_to_step3')}<br>` +
    `4. ${t('export_how_to_step4')}<br><br>` +
    t('export_format_used');

  _liftExportModalIfStacked();
  document.getElementById('exportModal').classList.add('open');
}

// #exportModal sits early in index.html, so at the shared --z-modal level any
// modal declared after it (Streaks, Calendar, …) paints over it. When the export
// modal is opened from inside another open modal, lift it above the caller —
// otherwise it opens invisibly behind and looks like nothing happened.
function _liftExportModalIfStacked() {
  const modal = document.getElementById('exportModal');
  if (!modal) return;
  const overAnother = Array.from(document.querySelectorAll('.modal-overlay.open'))
    .some(m => m !== modal);
  modal.classList.toggle('modal-on-top', overAnother);
}

function copyChipName(btn, name) {
  navigator.clipboard.writeText(name).then(() => {
    btn.classList.add('copied');
    const orig = btn.textContent;
    btn.textContent = '✓ ' + orig;
    setTimeout(() => { btn.textContent = orig; btn.classList.remove('copied'); }, 2000);
  });
}

function closeExportModal() {
  _exportSongsOverride = null;
  const modal = document.getElementById('exportModal');
  modal.classList.remove('open');
  modal.classList.remove('modal-on-top'); // back to the shared modal level
}

// Play all singles for the currently viewed day in the in-site music player
function calPlayAll() {
  if (!_eventsCalendarData) return;
  const dateObj = new Date(eventsCalendarYear, eventsCalendarMonth, eventsCalendarDay);
  const ds = localDateStr(dateObj);
  const dayMap = buildCalendarDayMap(
    { ..._eventsCalendarData, concerts: [] },
    new Set([ds])
  );
  const events = (dayMap[ds] || []).filter(ev => ev.ttType === 'anniversary' || ev.ttType === 'release');
  if (!events.length) return;
  const tracks = events.map(ev => ({ title: ev.ttTitle, artist: ev.ttArtist }));
  const [first, ...rest] = tracks;
  openYtPlayer(first.title, first.artist, '', null);
  rest.forEach(t => _ytQueue.push({ title: t.title, artist: t.artist, album: '', btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

let _calCreatePlTracks = null; // tracks staged for the create-playlist modal

function openCalCreatePlModal() {
  if (!_eventsCalendarData) return;
  const dateObj = new Date(eventsCalendarYear, eventsCalendarMonth, eventsCalendarDay);
  const ds = localDateStr(dateObj);
  const dayMap = buildCalendarDayMap(
    { ..._eventsCalendarData, concerts: [] },
    new Set([ds])
  );
  const events = (dayMap[ds] || []).filter(ev => ev.ttType === 'anniversary' || ev.ttType === 'release');
  if (!events.length) { alert('No singles found on this day.'); return; }
  _calCreatePlTracks = events.map(ev => ({ title: ev.ttTitle, artist: ev.ttArtist, album: '' }));
  const dateLabel = fmtDate(dateObj);
  document.getElementById('calCreatePlSub').textContent = `${tCount('songs', _calCreatePlTracks.length)} · ${dateLabel}`;
  const nameInput = document.getElementById('calCreatePlName');
  nameInput.value = `Singles · ${dateLabel}`;
  document.getElementById('calCreatePlModal').classList.add('open');
  // Pre-select so user can immediately type a new name
  setTimeout(() => nameInput.select(), 80);
}

function closeCalCreatePlModal() {
  document.getElementById('calCreatePlModal').classList.remove('open');
  _calCreatePlTracks = null;
}

function _calCreatePlConfirm() {
  const nameInput = document.getElementById('calCreatePlName');
  const name = nameInput.value.trim();
  if (!name) { nameInput.focus(); return; }
  if (!_calCreatePlTracks || !_calCreatePlTracks.length) return;
  _ytPlaylists[name] = _calCreatePlTracks;
  _ytTouchPlaylist(name);
  _ytSavePlaylists();
  _ytRenderPlaylists();
  // Refresh the Playlists tab manager if it's currently open
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'playlists') dcRenderPlaylistsView();
  closeCalCreatePlModal();
}

