// ─── BAR CHART RACE ────────────────────────────────────────────
let raceFrames = [];
let raceFrameIdx = 0;
let raceProgress = 0;
let racePlaying = false;
let raceAnimId = null;
let raceSpeed = 1;
let raceTopN = 10;
let raceType = 'artists'; // 'artists' | 'songs' | 'albums'
let raceLastTime = null;
let raceW = 0;
let raceH = 0;
const raceImageCache = {};
const raceAvatarCache = {};
const raceArtistColors = {};
const BASE_FRAME_MS = 600;

function getRaceColor(name) {
  if (!raceArtistColors[name]) {
    const n = Object.keys(raceArtistColors).length;
    raceArtistColors[name] = GRAPH_PALETTE[n % GRAPH_PALETTE.length];
  }
  return raceArtistColors[name];
}

function raceLabel(key) {
  const locale = currentLang === 'en' ? 'en-US' : currentLang;
  if (graphGranularity === 'day') {
    const d = new Date(key + 'T00:00:00');
    return d.toLocaleDateString(locale, { month: 'short', day: 'numeric', year: 'numeric' });
  }
  if (graphGranularity === 'month') {
    const [y, m] = key.split('-');
    return new Date(+y, +m - 1, 1).toLocaleDateString(locale, { month: 'short', year: 'numeric' });
  }
  return key; // year already is 4 digits
}

function loadRaceImage(key, meta) {
  // key = unique string, meta = { type, name, artist, album }
  if (raceImageCache[key] !== undefined) return;
  raceImageCache[key] = null;
  let promise;
  if (meta.type === 'artists') promise = getArtistImage(meta.name, 'deezer');
  else if (meta.type === 'songs') promise = getTrackImage(meta.name, meta.artist, 'deezer');
  else promise = getAlbumImage(meta.name, meta.artist, 'deezer');
  promise.then(url => {
    if (!url) return;
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      raceImageCache[key] = img;
      Object.keys(raceAvatarCache).filter(k => k.startsWith(key + ':')).forEach(k => delete raceAvatarCache[k]);
      if (!racePlaying && raceFrames.length) drawRace(raceFrameIdx, raceProgress);
    };
    img.onerror = () => { };
    img.src = url;
  }).catch(() => { });
}

function getRaceAvatar(imgKey, size) {
  const cacheKey = `${imgKey}:${size}`;
  if (raceAvatarCache[cacheKey]) return raceAvatarCache[cacheKey];
  const img = raceImageCache[imgKey];
  if (!img) return null;
  const oc = document.createElement('canvas');
  oc.width = oc.height = size;
  const oc_ctx = oc.getContext('2d');
  try {
    oc_ctx.beginPath();
    oc_ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
    oc_ctx.clip();
    oc_ctx.drawImage(img, 0, 0, size, size);
    raceAvatarCache[cacheKey] = oc;
    return oc;
  } catch (e) {
    // Image tainted (loaded without crossOrigin) — skip avatar, return null
    delete raceImageCache[imgKey];
    return null;
  }
}

function buildRaceFrames() {
  // Date filter
  const fromVal = document.getElementById('raceFrom')?.value;
  const toVal = document.getElementById('raceTo')?.value;
  const fromDate = fromVal ? new Date(fromVal + 'T00:00:00') : null;
  const toDate = toVal ? new Date(toVal + 'T23:59:59') : null;
  const filtered = allPlays.filter(p => {
    if (fromDate && p.date < fromDate) return false;
    if (toDate && p.date > toDate) return false;
    return true;
  });

  const allKeys = new Set();
  for (const p of filtered) allKeys.add(graphKey(p.date));
  const sortedKeys = [...allKeys].sort();

  const periodPlays = {};
  for (const p of filtered) {
    const k = graphKey(p.date);
    if (!periodPlays[k]) periodPlays[k] = [];
    periodPlays[k].push(p);
  }

  const totals = {}; // imgKey -> count
  const metaMap = {}; // imgKey -> { type, name, artist, display, sub }
  const frames = [];

  for (const key of sortedKeys) {
    for (const p of (periodPlays[key] || [])) {
      if (raceType === 'artists') {
        for (const a of p.artists) {
          totals[a] = (totals[a] || 0) + 1;
          if (!metaMap[a]) metaMap[a] = { type: 'artists', name: a, display: a, sub: '' };
        }
      } else if (raceType === 'songs') {
        const mainArtist = (p.artists && p.artists[0]) || p.artist;
        const imgKey = `${mainArtist}||${p.title}`;
        totals[imgKey] = (totals[imgKey] || 0) + 1;
        if (!metaMap[imgKey]) metaMap[imgKey] = { type: 'songs', name: p.title, artist: mainArtist, display: p.title, sub: mainArtist };
      } else { // albums
        const mainArtist = (p.artists && p.artists[0]) || p.artist;
        const imgKey = `${mainArtist}||${p.album}`;
        totals[imgKey] = (totals[imgKey] || 0) + 1;
        if (!metaMap[imgKey]) metaMap[imgKey] = { type: 'albums', name: p.album, artist: mainArtist, display: p.album, sub: mainArtist };
      }
    }
    const ranked = Object.entries(totals).sort((a, b) => b[1] - a[1]);
    ranked.slice(0, raceTopN + 10).forEach(([k]) => getRaceColor(k));
    frames.push({
      key, label: raceLabel(key),
      artists: ranked.slice(0, raceTopN + 5).map(([imgKey, count]) => {
        const m = metaMap[imgKey] || { display: imgKey, sub: '' };
        return { imgKey, name: m.display, sub: m.sub, count };
      })
    });
  }

  // Prepend a zero frame so bars grow from nothing at the start
  if (frames.length) {
    const zeroArtists = frames[0].artists.map(a => ({ ...a, count: 0 }));
    frames.unshift({ key: '__zero__', label: frames[0].label, artists: zeroArtists });
  }

  // Load images for every entity that appears in the top-N across all frames
  // Clear stale image cache entries so they reload with crossOrigin=anonymous
  const topKeys = new Set();
  frames.forEach(f => f.artists.slice(0, raceTopN).forEach(a => topKeys.add(a.imgKey)));
  topKeys.forEach(k => {
    const m = metaMap[k];
    if (m) {
      delete raceImageCache[k];
      Object.keys(raceAvatarCache).filter(c => c.startsWith(k + ':')).forEach(c => delete raceAvatarCache[c]);
      loadRaceImage(k, m);
    }
  });
  return frames;
}

function easeRace(t) { return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t; }

function rrect(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  if (r <= 0 || w <= 0 || h <= 0) { if (w > 0 && h > 0) ctx.rect(x, y, w, h); return; }
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y); ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r); ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h); ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r); ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

function drawRace(frameIdx, progress, targetCanvas) {
  const canvas = targetCanvas || document.getElementById('gBarRace');
  if (!canvas || !raceFrames.length) return;
  const ctx = canvas.getContext('2d');
  const W = targetCanvas ? canvas.width : raceW;
  const H = targetCanvas ? canvas.height : raceH;
  const frameA = raceFrames[frameIdx];
  const frameB = raceFrames[Math.min(frameIdx + 1, raceFrames.length - 1)];
  const gc = getGraphColors();
  const eased = easeRace(progress);

  const LABEL_W = 148;
  const PAD_TOP = 12;
  const BAR_H = raceTopN > 15 ? 26 : 32;
  const SLOT_H = raceTopN > 15 ? 36 : 42;
  const AV_R = raceTopN > 15 ? 12 : 15;
  const CNT_W = 74;
  const BAR_X = LABEL_W + 6;
  const BAR_MAX_W = W - BAR_X - AV_R * 2 - 8 - CNT_W;

  ctx.clearRect(0, 0, W, H);
  if (targetCanvas) {
    ctx.fillStyle = gc.bg || '#0a1628';
    ctx.fillRect(0, 0, W, H);
  }

  const mapA = new Map(frameA.artists.map((a, i) => [a.imgKey, { rank: i, count: a.count, name: a.name, sub: a.sub }]));
  const mapB = new Map(frameB.artists.map((a, i) => [a.imgKey, { rank: i, count: a.count, name: a.name, sub: a.sub }]));
  const maxCount = Math.max(1, frameB.artists[0]?.count || 0, frameA.artists[0]?.count || 0);

  const visSet = new Set([
    ...frameA.artists.slice(0, raceTopN).map(a => a.imgKey),
    ...frameB.artists.slice(0, raceTopN).map(a => a.imgKey)
  ]);
  const items = [];
  for (const imgKey of visSet) {
    const a = mapA.get(imgKey) || { rank: raceTopN + 2, count: 0 };
    const b = mapB.get(imgKey) || { rank: raceTopN + 2, count: a.count };
    const meta = mapA.get(imgKey) || mapB.get(imgKey) || {};
    items.push({
      imgKey, name: meta.name || imgKey, sub: meta.sub || '',
      rank: a.rank + (b.rank - a.rank) * eased, count: a.count + (b.count - a.count) * progress
    });
  }
  items.sort((a, b) => a.rank - b.rank);

  const dpr = window.devicePixelRatio || 1;
  const avSize = Math.round(AV_R * 2 * dpr);

  for (const { imgKey, name, sub, rank, count } of items) {
    const alpha = rank >= raceTopN ? Math.max(0, (raceTopN + 0.6 - rank) / 0.6) : 1;
    if (alpha <= 0) continue;
    ctx.globalAlpha = alpha;

    const y = PAD_TOP + rank * SLOT_H;
    const bW = Math.max(0, Math.min((count / maxCount) * BAR_MAX_W, BAR_MAX_W));
    const color = getRaceColor(imgKey);

    // Bar track
    ctx.beginPath(); rrect(ctx, BAR_X, y, BAR_MAX_W, BAR_H, 5);
    ctx.fillStyle = (gc.card || '#0e1e38');
    ctx.fill();

    // Bar fill with gradient
    if (bW > 1) {
      const grad = ctx.createLinearGradient(BAR_X, 0, BAR_X + bW, 0);
      grad.addColorStop(0, color + '55'); grad.addColorStop(1, color + 'dd');
      ctx.fillStyle = grad;
      ctx.beginPath(); rrect(ctx, BAR_X, y, bW, BAR_H, 5);
      ctx.fill();
    }

    // Rank badge — colored pill on the far left
    const rankN = Math.round(rank) + 1;
    const rankStr = String(rankN);
    ctx.font = `bold ${raceTopN > 15 ? 11 : 13}px "JetBrains Mono", monospace`;
    const pillW = Math.max(24, ctx.measureText(rankStr).width + 12);
    const pillH = Math.min(BAR_H - 6, raceTopN > 15 ? 16 : 20);
    const pillX = 2;
    const pillY = y + (BAR_H - pillH) / 2;
    ctx.beginPath(); rrect(ctx, pillX, pillY, pillW, pillH, 4);
    ctx.fillStyle = color + '35'; ctx.fill();
    ctx.strokeStyle = color + '90'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = color;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(rankStr, pillX + pillW / 2, pillY + pillH / 2 + 0.5);

    // Name (and optional sub) — right-aligned in remaining label space
    const nameAreaX = pillX + pillW + 4;
    const nameMaxW = LABEL_W - 2 - nameAreaX;
    ctx.textAlign = 'right';
    if (sub) {
      ctx.fillStyle = gc.text || '#e8f0ff';
      ctx.font = '500 11px "IBM Plex Sans", sans-serif';
      ctx.textBaseline = 'middle';
      let dname = name;
      while (ctx.measureText(dname).width > nameMaxW && dname.length > 3) dname = dname.slice(0, -2) + '…';
      ctx.fillText(dname, LABEL_W - 2, y + BAR_H / 2 - 4);
      ctx.fillStyle = gc.text3 || '#7aa0d0';
      ctx.font = '400 9px "IBM Plex Sans", sans-serif';
      let dsub = sub;
      while (ctx.measureText(dsub).width > nameMaxW && dsub.length > 3) dsub = dsub.slice(0, -2) + '…';
      ctx.fillText(dsub, LABEL_W - 2, y + BAR_H / 2 + 7);
    } else {
      ctx.fillStyle = gc.text || '#e8f0ff';
      ctx.font = `500 ${raceTopN > 15 ? 11 : 12}px "IBM Plex Sans", sans-serif`;
      ctx.textBaseline = 'middle';
      let dname = name;
      while (ctx.measureText(dname).width > nameMaxW && dname.length > 3) dname = dname.slice(0, -2) + '…';
      ctx.fillText(dname, LABEL_W - 2, y + BAR_H / 2 + 1);
    }

    // Avatar at bar tip (clamped so it stays on screen)
    const avX = BAR_X + Math.max(AV_R + 2, Math.min(bW + AV_R + 1, BAR_MAX_W - AV_R - 2));
    const avY = y + BAR_H / 2;
    const avatarCanvas = getRaceAvatar(imgKey, avSize);
    if (avatarCanvas) {
      ctx.save();
      ctx.beginPath(); ctx.arc(avX, avY, AV_R, 0, Math.PI * 2); ctx.clip();
      ctx.drawImage(avatarCanvas, avX - AV_R, avY - AV_R, AV_R * 2, AV_R * 2);
      ctx.restore();
    } else {
      ctx.beginPath(); ctx.arc(avX, avY, AV_R, 0, Math.PI * 2);
      ctx.fillStyle = color; ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.font = `700 ${Math.max(7, Math.round(AV_R * 0.62))}px "IBM Plex Sans", sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(name.split(/[\s\-&]+/).slice(0, 2).map(w => w[0] || '').join('').toUpperCase() || '?', avX, avY + 0.5);
    }
    ctx.beginPath(); ctx.arc(avX, avY, AV_R, 0, Math.PI * 2);
    ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.stroke();

    // Play count
    ctx.fillStyle = gc.text || '#e8f0ff';
    ctx.font = '600 11px "JetBrains Mono", monospace';
    ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    ctx.fillText(Math.round(count).toLocaleString(), W - 4, y + BAR_H / 2 + 1);

    ctx.globalAlpha = 1;
  }

  // Date — bottom right, crossfade between frame labels
  ctx.globalAlpha = 1;
  ctx.font = 'bold 18px "JetBrains Mono", monospace';
  ctx.textAlign = 'right'; ctx.textBaseline = 'bottom';
  ctx.fillStyle = gc.text3 || '#7aa0d0';
  if (progress > 0 && frameA.label !== frameB.label) {
    ctx.globalAlpha = 1 - progress; ctx.fillText(frameA.label, W - 12, H - 10);
    ctx.globalAlpha = progress; ctx.fillText(frameB.label, W - 12, H - 10);
    ctx.globalAlpha = 1;
  } else {
    ctx.fillText(frameA.label, W - 12, H - 10);
  }
}

function raceAnimate(ts) {
  if (!racePlaying) return;
  if (!raceLastTime) raceLastTime = ts;
  raceProgress += (ts - raceLastTime) / (BASE_FRAME_MS / raceSpeed);
  raceLastTime = ts;
  if (raceProgress >= 1) {
    raceProgress = 0; raceFrameIdx++;
    if (raceFrameIdx >= raceFrames.length - 1) {
      raceFrameIdx = raceFrames.length - 1; raceProgress = 0; racePlaying = false;
      const btn = document.getElementById('racePlayBtn');
      btn.textContent = '▶ Play'; btn.classList.add('active');
      drawRace(raceFrameIdx, 0); raceUpdateSlider(); return;
    }
  }
  drawRace(raceFrameIdx, raceProgress);
  raceUpdateSlider();
  raceAnimId = requestAnimationFrame(raceAnimate);
}

function raceUpdateSlider() {
  const s = document.getElementById('raceSeekSlider');
  if (s) s.value = raceFrameIdx + raceProgress;
}

function initRace() {
  if (!allPlays.length) return;
  racePlaying = false;
  if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
  raceLastTime = null;
  raceFrames = buildRaceFrames();
  raceFrameIdx = 0; raceProgress = 0;

  const canvas = document.getElementById('gBarRace');
  if (!canvas) return;
  const dpr = window.devicePixelRatio || 1;
  const SLOT_H = raceTopN > 15 ? 36 : 42; // compact rows for larger counts
  raceW = Math.max(300, (canvas.parentElement?.clientWidth || 600) - 34);
  raceH = raceTopN * SLOT_H + 62;
  canvas.width = Math.round(raceW * dpr);
  canvas.height = Math.round(raceH * dpr);
  canvas.style.height = raceH + 'px';
  canvas.getContext('2d').setTransform(dpr, 0, 0, dpr, 0, 0);

  const slider = document.getElementById('raceSeekSlider');
  slider.max = Math.max(1, raceFrames.length - 1); slider.value = 0;
  document.getElementById('racePlayBtn').textContent = '▶ Play';
  document.getElementById('racePlayBtn').classList.add('active');
  drawRace(0, 0);
}

document.getElementById('racePlayBtn').addEventListener('click', () => {
  if (!raceFrames.length) return;
  if (raceFrameIdx >= raceFrames.length - 1 && !racePlaying) {
    raceFrameIdx = 0; raceProgress = 0; raceLastTime = null; raceUpdateSlider();
  }
  racePlaying = !racePlaying;
  const btn = document.getElementById('racePlayBtn');
  btn.textContent = racePlaying ? '⏸ Pause' : '▶ Play';
  btn.classList.toggle('active', racePlaying);
  if (racePlaying) { raceLastTime = null; raceAnimId = requestAnimationFrame(raceAnimate); }
  else {
    if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
    localStorage.setItem('dc_raceFrameIdx', raceFrameIdx);
  }
});

document.getElementById('raceRestartBtn').addEventListener('click', () => {
  racePlaying = false;
  if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
  raceFrameIdx = 0; raceProgress = 0; raceLastTime = null;
  localStorage.removeItem('dc_raceFrameIdx');
  document.getElementById('racePlayBtn').textContent = '▶ Play';
  document.getElementById('racePlayBtn').classList.add('active');
  raceUpdateSlider(); drawRace(0, 0);
});

document.getElementById('raceSpeedBtns').addEventListener('click', e => {
  const btn = e.target.closest('[data-speed]'); if (!btn) return;
  document.querySelectorAll('#raceSpeedBtns button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  raceSpeed = parseFloat(btn.dataset.speed);
  localStorage.setItem('dc_raceSpeed', btn.dataset.speed);
});

document.getElementById('raceTopNBtns').addEventListener('click', e => {
  const btn = e.target.closest('[data-topn]'); if (!btn) return;
  document.querySelectorAll('#raceTopNBtns button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  raceTopN = parseInt(btn.dataset.topn);
  localStorage.setItem('dc_raceTopN', btn.dataset.topn);
  if (currentPeriod === 'graphs') initRace();
});

document.getElementById('raceSeekSlider').addEventListener('input', e => {
  if (racePlaying) {
    racePlaying = false;
    if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
    const btn = document.getElementById('racePlayBtn');
    btn.textContent = '▶ Play'; btn.classList.add('active');
  }
  const v = parseFloat(e.target.value);
  raceFrameIdx = Math.min(Math.floor(v), raceFrames.length - 1);
  raceProgress = v - Math.floor(v);
  raceLastTime = null;
  localStorage.setItem('dc_raceFrameIdx', raceFrameIdx);
  drawRace(raceFrameIdx, raceProgress);
});

document.getElementById('raceTypeBtns').addEventListener('click', e => {
  const btn = e.target.closest('[data-racetype]'); if (!btn) return;
  document.querySelectorAll('#raceTypeBtns button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  raceType = btn.dataset.racetype;
  localStorage.setItem('dc_raceType', raceType);
  if (currentPeriod === 'graphs') initRace();
});

document.getElementById('raceFrom').addEventListener('change', () => {
  localStorage.setItem('dc_raceFrom', document.getElementById('raceFrom').value);
  if (currentPeriod === 'graphs') initRace();
});
document.getElementById('raceTo').addEventListener('change', () => {
  localStorage.setItem('dc_raceTo', document.getElementById('raceTo').value);
  if (currentPeriod === 'graphs') initRace();
});
document.getElementById('raceResetRange').addEventListener('click', () => {
  if (!allPlays.length) return;
  document.getElementById('raceFrom').value = localDateStr(tzDate(allPlays[allPlays.length - 1].date));
  document.getElementById('raceTo').value = localDateStr(tzNow());
  localStorage.removeItem('dc_raceFrom');
  localStorage.removeItem('dc_raceTo');
  if (currentPeriod === 'graphs') initRace();
});

document.getElementById('raceStepBackBtn').addEventListener('click', () => {
  if (!raceFrames.length) return;
  if (racePlaying) {
    racePlaying = false;
    if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
    const btn = document.getElementById('racePlayBtn');
    btn.textContent = '▶ Play'; btn.classList.add('active');
  }
  raceProgress = 0;
  raceFrameIdx = Math.max(0, raceFrameIdx - 1);
  raceLastTime = null;
  localStorage.setItem('dc_raceFrameIdx', raceFrameIdx);
  raceUpdateSlider(); drawRace(raceFrameIdx, 0);
});

document.getElementById('raceStepFwdBtn').addEventListener('click', () => {
  if (!raceFrames.length) return;
  if (racePlaying) {
    racePlaying = false;
    if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
    const btn = document.getElementById('racePlayBtn');
    btn.textContent = '▶ Play'; btn.classList.add('active');
  }
  raceProgress = 0;
  raceFrameIdx = Math.min(raceFrames.length - 1, raceFrameIdx + 1);
  raceLastTime = null;
  localStorage.setItem('dc_raceFrameIdx', raceFrameIdx);
  raceUpdateSlider(); drawRace(raceFrameIdx, 0);
});

document.getElementById('raceEndBtn').addEventListener('click', () => {
  if (!raceFrames.length) return;
  if (racePlaying) {
    racePlaying = false;
    if (raceAnimId) { cancelAnimationFrame(raceAnimId); raceAnimId = null; }
    const btn = document.getElementById('racePlayBtn');
    btn.textContent = '▶ Play'; btn.classList.add('active');
  }
  raceProgress = 0;
  raceFrameIdx = raceFrames.length - 1;
  raceLastTime = null;
  localStorage.setItem('dc_raceFrameIdx', raceFrameIdx);
  raceUpdateSlider(); drawRace(raceFrameIdx, 0);
});

// ─── GIF EXPORT ────────────────────────────────────────────────
async function loadGifJs() {
  if (window.GIF) return;
  await new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/gif.js@0.2.0/dist/gif.js';
    s.onload = resolve; s.onerror = reject;
    document.head.appendChild(s);
  });
}

async function downloadRaceGif() {
  if (!raceFrames.length) return;
  const btn = document.getElementById('raceGifBtn');
  btn.disabled = true; btn.textContent = 'Loading…';
  try { await loadGifJs(); } catch (e) {
    btn.disabled = false; btn.textContent = '⬇ GIF';
    alert('Could not load GIF encoder. Check your connection.'); return;
  }
  let workerUrl;
  try {
    const workerText = await fetch('https://cdn.jsdelivr.net/npm/gif.js@0.2.0/dist/gif.worker.js').then(r => r.text());
    workerUrl = URL.createObjectURL(new Blob([workerText], { type: 'application/javascript' }));
  } catch (e) {
    btn.disabled = false; btn.textContent = '⬇ GIF';
    alert('Could not load GIF worker. Check your connection.'); return;
  }

  btn.textContent = 'Capturing…';
  const W = Math.round(raceW), H = Math.round(raceH);
  const tmpCanvas = document.createElement('canvas');
  tmpCanvas.width = W; tmpCanvas.height = H;
  const frameDelay = Math.max(50, Math.round(BASE_FRAME_MS / raceSpeed));
  const gif = new GIF({ workers: 2, quality: 8, width: W, height: H, workerScript: workerUrl });

  const frameCount = raceFrames.length;
  for (let i = 0; i < frameCount; i++) {
    drawRace(i, 0, tmpCanvas);
    gif.addFrame(tmpCanvas, { copy: true, delay: i === frameCount - 1 ? frameDelay * 4 : frameDelay });
    if (i % 4 === 0) {
      btn.textContent = `Capturing… ${Math.round((i / frameCount) * 40)}%`;
      await new Promise(r => setTimeout(r, 0));
    }
  }
  // Restore main canvas view
  drawRace(raceFrameIdx, raceProgress);

  gif.on('progress', p => { btn.textContent = `Encoding… ${Math.round(40 + p * 60)}%`; });
  gif.on('finished', blob => {
    URL.revokeObjectURL(workerUrl);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `bar-race-${raceType}-${new Date().toISOString().slice(0, 10)}.gif`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
    btn.disabled = false; btn.textContent = '⬇ GIF';
  });
  gif.on('abort', () => { URL.revokeObjectURL(workerUrl); btn.disabled = false; btn.textContent = '⬇ GIF'; });

  btn.textContent = 'Encoding… 40%';
  gif.render();
}

document.getElementById('raceGifBtn').addEventListener('click', downloadRaceGif);

document.getElementById('graphGranularity').addEventListener('click', e => {
  const btn = e.target.closest('button');
  if (!btn) return;
  document.querySelectorAll('#graphGranularity button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  graphGranularity = btn.dataset.gran;
  localStorage.setItem('dc_gran', graphGranularity);
  if (currentPeriod === 'graphs') renderGraphs();
});

// ── BACK TO TOP BUTTON ──
// Only shown while actively scrolling, then auto-hides shortly after scrolling
// stops — otherwise it can sit over section buttons (e.g. Share as Image) and
// intercept taps meant for them.
const backToTopBtn = document.getElementById('backToTop');
let backToTopHideTimer = null;
window.addEventListener('scroll', () => {
  const shouldShow = window.scrollY > window.innerHeight / 6;
  backToTopBtn.classList.toggle('visible', shouldShow);
  clearTimeout(backToTopHideTimer);
  if (shouldShow) {
    backToTopHideTimer = setTimeout(() => {
      backToTopBtn.classList.remove('visible');
    }, 2500);
  }
}, { passive: true });
backToTopBtn.addEventListener('click', () => {
  window.scrollTo({ top: 0, behavior: 'smooth' });
});

// ── MASTHEAD CONTROLS AUTO-HIDE (mobile) ──
// The theme/day/language button stack (.theme-toggle) is position:fixed on
// mobile (see the max-width:700px rules in style.css) so it's always on
// screen. That's convenient, but it also means it can sit on top of content
// — including the sticky date-nav bar — while the user is just reading and
// not touching anything. To fix that, we mirror the #backToTop pattern:
// the stack fades out (.idle-hidden, defined in style.css) after a few
// seconds of no scroll activity, and snaps back to visible the moment the
// user scrolls again. It only applies on mobile — on desktop the buttons
// are laid out inline in the masthead, not fixed, so there's nothing to hide.
const mastheadControls = document.querySelector('.theme-toggle');
if (mastheadControls) {
  // Handle for the pending "go idle" timeout, so each new scroll event can
  // cancel and restart the countdown (clearTimeout on an already-fired
  // timer is a harmless no-op).
  let controlsIdleTimer = null;

  // Re-checked on every call (rather than cached once) so resizing the
  // window across the 700px breakpoint — e.g. rotating a tablet, or a
  // desktop user shrinking the window — is picked up automatically.
  const isMobileControls = () => window.matchMedia('(max-width: 700px)').matches;

  // Arms (or re-arms) the countdown to hide the controls. Only does
  // anything on mobile; on desktop we just make sure no stale timer is
  // left running from a previous narrow-viewport state.
  const scheduleControlsHide = () => {
    clearTimeout(controlsIdleTimer);
    if (!isMobileControls()) return;
    controlsIdleTimer = setTimeout(function checkIdle() {
      // If the user has one of the theme/day/language panels open (tapped
      // a ctrl-group-btn to expand it), hiding the whole stack out from
      // under them mid-tap would be jarring and could strand an open
      // panel with no way to close it visibly. Instead, keep polling every
      // second until they close it, then hide as normal.
      if (mastheadControls.querySelector('.ctrl-group.open')) {
        controlsIdleTimer = setTimeout(checkIdle, 1000);
      } else {
        mastheadControls.classList.add('idle-hidden');
      }
    }, 3000);
  };

  // Reveals the controls immediately and resets the idle countdown. Called
  // on every scroll event, on page load, and (via the global hook below)
  // whenever a ctrl-group panel is opened — so opening a panel keeps the
  // stack visible even if the user hasn't scrolled recently.
  const showControls = () => {
    mastheadControls.classList.remove('idle-hidden');
    scheduleControlsHide();
  };

  // Exposed globally so the CTRL GROUP TOGGLE click handler (defined much
  // earlier in this file, before this IIFE-free block runs) can call back
  // in to keep the stack visible when a panel is opened. Same pattern as
  // window._refreshBackToTop used elsewhere in the codebase.
  window._showMastheadControls = showControls;
  window.addEventListener('scroll', showControls, { passive: true });
  showControls(); // start visible + arm the first countdown on load
}

// ─── CERTIFICATIONS WALL ────────────────────────────────────────
const CWALL_TIER_CLASS = { gold: 'gold', platinum: 'plat', diamond: 'diamond' };
const CWALL_TIER_LABEL = { gold: 'Gold', platinum: 'Platinum', diamond: 'Diamond' };
const CWALL_TYPE_LABEL = { song: 'song', album: 'album' };

/* The award a plaque names. Only Diamond repeats, and it repeats the way the
   album modal already writes it — Double and Triple get their words, and past
   that it goes compact ("5× Diamond") rather than inventing vocabulary.
   No emoji: they render differently on every OS, and the plaque now says the
   tier in the tier's own colour, which the emoji was only standing in for. */
function cwallTierName(item) {
  if (item.tier !== 'diamond') return CWALL_TIER_LABEL[item.tier] || esc(item.tier || '');
  return esc(diamondMultiLabel(Math.max(1, item.mult || 1)).label);
}

/* How many records to press for one award. Diamond repeats, so a 3× hangs
   three; everything else hangs one. Five is the ceiling — a sixth would push
   the fan past the cover it sits beside, and the line underneath still says
   the true multiple. */
const CWALL_FAN_MAX = 5;
function cwallDiscCount(item) {
  if (item.tier !== 'diamond') return 1;
  return Math.max(1, Math.min(CWALL_FAN_MAX, item.mult || 1));
}

/* Every sort is written once, ascending, and simply run backwards for the
   other direction — so the two halves of a toggle can never disagree about how
   ties break, and adding a sort means adding one line rather than two.

   Ascending by tier is the lowest plaque first, which needs one number per
   plaque rather than a tier order plus a multiple: Gold 1, Platinum 2, Diamond
   2 + its multiple, the same weight the ledger ranks its rows by. A record
   holds several plaques now, so every comparator ends on the award date, which
   keeps one record's Gold, Platinum and Diamond sitting together in the order
   it earned them. */
const cwallTierRank = it => it.tier === 'diamond'
  ? 2 + Math.max(1, it.mult || 1)
  : (it.tier === 'platinum' ? 2 : 1);
const cwallByDate = (a, b) => (a.date || '').localeCompare(b.date || '');
const cwallByTitle = (a, b) => (a.title || '').localeCompare(b.title || '');
const cwallByArtist = (a, b) => (a.artist || '').localeCompare(b.artist || '');
const CWALL_CMP = {
  tier:   (a, b) => (cwallTierRank(a) - cwallTierRank(b)) || (a._plays - b._plays) || cwallByDate(a, b),
  artist: (a, b) => cwallByArtist(a, b) || cwallByTitle(a, b) || cwallByDate(a, b),
  title:  (a, b) => cwallByTitle(a, b) || cwallByArtist(a, b) || cwallByDate(a, b),
  date:   (a, b) => cwallByDate(a, b) || cwallByTitle(a, b),
};
function cwallComparator() {
  const cmp = CWALL_CMP[certWallSort] || CWALL_CMP.tier;
  const dir = certWallSortAsc ? 1 : -1;
  return (a, b) => dir * cmp(a, b);
}

/* Which sort is in force and which way it runs. The arrow is only drawn on the
   active button — an arrow on all four would read as four separate controls —
   but its box is held open on every one of them (see .cwall-dir) so the row
   does not jump sideways when the active button moves. */
function paintCwallSortBtns(wall) {
  wall.querySelectorAll('[data-cwall-sort]').forEach(function (b) {
    const s = CWALL_SORTS.find(x => x.key === b.dataset.cwallSort);
    if (!s) return;
    const on = s.key === certWallSort;
    const asc = on ? certWallSortAsc : s.asc;
    b.classList.toggle('active', on);
    const dir = b.querySelector('.cwall-dir');
    if (dir) dir.textContent = on ? (asc ? '▲' : '▼') : '';
    b.title = on
      ? s.label + ': ' + (asc ? s.up : s.down) + ' — click to reverse'
      : 'Sort by ' + s.label.toLowerCase() + ' (' + (asc ? s.up : s.down) + ')';
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
}

function wallInitials(str) {
  return (str || '').split(/\s+/).slice(0, 2).map(w => w[0] || '').join('').toUpperCase() || '?';
}

function fmtCertDate(dateStr) {
  if (!dateStr) return '';
  try {
    return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  } catch (e) { return String(dateStr); }
}

function renderCertifications(data) {
  certWallData = data || [];
  /* Each plaque's permanent id, stamped once. Every sort and filter reorders
     the array, so the element ids have to come from something that does not
     move — and a record now holds several plaques, which made the old
     indexOf() lookup both a linear scan per card and, on a big library, a scan
     over four times as many cards as it used to be. */
  certWallData.forEach(function (item, i) { item._i = i; });
  const wall = document.getElementById('certifications-wall');
  if (!wall) return;

  if (!certWallData.length) {
    wall.innerHTML = '<div class="cwall-empty">No certifications to display.</div>';
    return;
  }

  wall.innerHTML = `
    <div class="cwall-controls">
      <div class="cwall-search-wrap">
        <input class="cwall-search" id="cwall-search-input" type="search"
          placeholder="Search by artist, song, or album…" value="${esc(certWallSearch)}">
      </div>
      <div class="cwall-filter-row">
        <div class="cwall-filter-btns">
          <button class="cwall-btn${certWallFilter==='all'?' active':''}" data-cwall-filter="all">All</button>
          <button class="cwall-btn${certWallFilter==='song'?' active':''}" data-cwall-filter="song">Songs</button>
          <button class="cwall-btn${certWallFilter==='album'?' active':''}" data-cwall-filter="album">Albums</button>
        </div>
        <div class="cwall-sort-btns">
          <span class="cwall-sort-label">Sort:</span>
          ${CWALL_SORTS.map(s => `<button class="cwall-btn cwall-sort-btn${certWallSort===s.key?' active':''}" data-cwall-sort="${s.key}">${s.label}<span class="cwall-dir"></span></button>`).join('')}
        </div>
      </div>
    </div>
    <div class="cwall-grid" id="cwall-grid"></div>`;

  document.getElementById('cwall-search-input').addEventListener('input', e => {
    certWallSearch = e.target.value;
    renderCertWallCards();
  });

  wall.querySelector('.cwall-filter-btns').addEventListener('click', e => {
    const btn = e.target.closest('[data-cwall-filter]');
    if (!btn) return;
    certWallFilter = btn.dataset.cwallFilter;
    wall.querySelectorAll('[data-cwall-filter]').forEach(b =>
      b.classList.toggle('active', b.dataset.cwallFilter === certWallFilter));
    renderCertWallCards();
  });

  wall.querySelector('.cwall-sort-btns').addEventListener('click', e => {
    const btn = e.target.closest('[data-cwall-sort]');
    if (!btn) return;
    const key = btn.dataset.cwallSort;
    /* Clicking the sort already in force turns it around — Diamond-first
       becomes Gold-first, A→Z becomes Z→A, oldest-first becomes newest-first.
       Picking a different sort starts it in its own natural direction rather
       than inheriting the direction the last one happened to be left in. */
    if (key === certWallSort) certWallSortAsc = !certWallSortAsc;
    else { certWallSort = key; certWallSortAsc = cwallSortDefaultAsc(key); }
    paintCwallSortBtns(wall);
    renderCertWallCards();
  });

  paintCwallSortBtns(wall);

  // The grid element outlives every re-render, so one observer covers them all.
  watchCertWallCovers();
  renderCertWallCards();
}

function renderCertWallCards() {
  const grid = document.getElementById('cwall-grid');
  if (!grid) return;

  let items = certWallData.slice();

  if (certWallFilter !== 'all') {
    items = items.filter(item => item.type === certWallFilter);
  }

  if (certWallSearch.trim()) {
    const q = certWallSearch.trim().toLowerCase();
    items = items.filter(item =>
      item.title.toLowerCase().includes(q) ||
      item.artist.toLowerCase().includes(q));
  }

  // Ascending, then run backwards for the other direction (see CWALL_CMP).
  items.sort(cwallComparator());

  harvestCertWallImages();

  if (!items.length) {
    grid.innerHTML = '<div class="cwall-empty">No certifications match your search.</div>';
    return;
  }

  grid.innerHTML = items.map(item => {
    const origIdx = item._i;
    const cwKey = certWallPrefKey(item);
    const known = _certWallResolved[cwKey];
    const tierClass = CWALL_TIER_CLASS[item.tier] || 'gold';
    const ini = esc(wallInitials(item.title));
    const dateStr = fmtCertDate(item.date);

    /* The cover mounts beside the records, in its own slot: loadImages()
       replaces its target's innerHTML when the artwork lands, so the slot holds
       nothing else, and it is what carries the ✎ picker badge. */
    /* data-rec-* lets the hero-artist tally count a certification the same way it
       counts a table row. The wall is divs rather than a <table>, so it is the one
       place the tally cannot walk tbody rows — it matches .cert-card instead. */
    /* …and `data-cert-lesser` takes it back off the plaques below a record's
       highest one. All five plaques of a 3× Diamond album are real awards, but
       they are one certified record — the tally skips the lesser ones so the
       reel does not show the same album five times (see REC_TALLY_SEL). */
    const cwType = item.type === 'album' ? 'album' : 'song'; // the wall holds songs and albums only
    const cwPrefKey = cwType + ':' + (item.artist || '').toLowerCase() + '|||' + (item.title || '').toLowerCase();
    // One record per multiple, so a Triple Diamond is counted, not read.
    const cwDiscs = cwallDiscCount(item);
    return `<div class="cert-card cert-card--${tierClass}"${item.top ? '' : ' data-cert-lesser="1"'} data-rec-artist="${esc(item.artist || '')}" data-rec-type="${esc(cwType)}" data-rec-name="${esc(item.title || '')}" data-rec-prefkey="${esc(cwPrefKey)}">
  <div class="cert-frame">
    <span class="cert-bolt cert-bolt--tl"></span><span class="cert-bolt cert-bolt--tr"></span>
    <span class="cert-bolt cert-bolt--bl"></span><span class="cert-bolt cert-bolt--br"></span>
    <div class="cert-stage" id="cwrec-${origIdx}">
      <div class="cert-art-slot" id="cwrec-img-${origIdx}" data-cwkey="${esc(cwKey)}">${known
      ? `<img class="thumb" src="${esc(known)}" alt="" loading="lazy">`
      : `<div class="cert-art-initials">${ini}</div>`}</div>
      <div class="cert-fan cert-fan--${cwDiscs}">${'<div class="cert-disc"></div>'.repeat(cwDiscs)}</div>
    </div>
    <div class="cert-info">
      <div class="cert-title">${esc(item.title)}</div>
      <div class="cert-artist">${esc(item.artist)}</div>
      <div class="cert-tier-name">${cwallTierName(item)} <span class="cert-tier-of">certified ${esc(CWALL_TYPE_LABEL[item.type] || item.type || '')}</span></div>
      ${dateStr ? `<div class="cert-date">${dateStr}</div>` : ''}
    </div>
  </div>
</div>`;
  }).join('');

  loadCertWallImages(items);
}

/* Artwork for the wall. Called from renderCertWallCards() on *every* render,
   not once at build time: the wall re-renders on each filter, sort and search
   change, which throws away the elements a one-shot loader had filled in.

   Routed through loadImages() like the rest of Records, which buys three
   things the old direct-fetch loop did not have: pinned picker choices are
   honoured, the source cascade applies, and — because the wall sits inside
   #recordsView — attachRecImgPicker() puts a ✎ badge on every record. */
// The picker key for a wall item, in the same shape the rest of the app uses.
function certWallPrefKey(item) {
  const artist = (item.artist || '').toLowerCase();
  const title = (item.title || '').toLowerCase();
  return (item.type === 'album' ? 'album:' : 'song:') + artist + '|||' + title;
}

/* Covers already resolved, keyed by picker key so they survive a re-sort that
   renumbers every card. The wall re-renders on each filter, sort and search
   change; without this it would blank every cover and re-run the lookups —
   and imgCache stores a null placeholder for the duration of an in-flight
   fetch, so re-resolving an item mid-flight caches a permanent miss and the
   cover never comes back at all. */
const _certWallResolved = {};
function harvestCertWallImages() {
  const grid = document.getElementById('cwall-grid');
  if (!grid) return;
  grid.querySelectorAll('.cert-art-slot').forEach(function (slot) {
    const wrap = slot.closest('.thumb-wrap');
    const btn = wrap && wrap.querySelector('.img-src-btn');
    if (!btn || !btn.dataset.prefkey) return;
    const img = slot.querySelector('img.thumb');
    if (img && img.getAttribute('src')) {
      _certWallResolved[btn.dataset.prefkey] = img.getAttribute('src');
      return;
    }
    /* .thumb-initials is what the loader writes when it finds nothing, or when
       the picker is pinned to "No image" — that is a resolved answer, and
       recording it is what stops a cleared cover coming back on the next sort.
       .cert-art-initials is our own pre-load placeholder and means the loader
       has not run yet, so it must not be recorded as a miss. */
    if (slot.querySelector('.thumb-initials')) _certWallResolved[btn.dataset.prefkey] = '';
  });
}

let _certWallObservers = [];
function loadCertWallImages(items) {
  /* Retire the previous render's observers first. Without this every filter,
     sort or search click would leave another pair watching elements that are
     no longer in the document — and this wall runs to well over a thousand
     cards on a large library. */
  _certWallObservers.forEach(function (o) {
    o.disconnect();
    // Drop it from the global list too, or the array itself grows by two on
    // every click even though the observers behind it are already dead.
    const i = imgObservers.indexOf(o);
    if (i !== -1) imgObservers.splice(i, 1);
  });
  _certWallObservers = [];
  const queue = items.map(function (item) {
    const imgId = 'cwrec-img-' + certWallData.indexOf(item);
    const prefKey = certWallPrefKey(item);
    if (item.type === 'album') {
      return { imgId, imgType: 'album', name: item.title, album: item.title, artist: item.artist, prefKey };
    }
    return {
      imgId, imgType: 'song', name: item.title, title: item.title,
      artist: item.artist, album: item._album || '', prefKey
    };
  });

  /* Every card gets the ✎ badge, including the ones rendered straight from a
     known cover — those are not handed to loadImages(), so they would
     otherwise be the only artwork in Records without the control. */
  queue.forEach(function (it) {
    const el = document.getElementById(it.imgId);
    if (el) attachRecImgPicker(el, it, it.imgType);
  });

  /* Only what has no answer yet is worth observing — and only one plaque per
     record. A record's plaques all show the same cover, and fetchAndInjectImage
     runs off a single serialised queue that rests 120ms between lookups, so
     pointing the loader at all five plaques of a 3× Diamond would cost five
     turns of that queue to answer one question. The first plaque of each record
     is fetched; mirrorCertWallCovers() copies what lands onto the rest. */
  const queued = new Set();
  const pending = queue.filter(function (x) {
    if (Object.prototype.hasOwnProperty.call(_certWallResolved, x.prefKey)) return false;
    if (queued.has(x.prefKey)) return false;
    queued.add(x.prefKey);
    return true;
  });
  _certWallObservers.push(loadImages(pending.filter(function (x) { return x.imgType === 'album'; }), 'album'));
  _certWallObservers.push(loadImages(pending.filter(function (x) { return x.imgType === 'song'; }), 'song'));
}

/* One cover, several plaques. The loader writes into one element, so when a
   cover lands this copies it onto the record's other plaques — otherwise a 3×
   Diamond album's Gold would sit on its initials for as long as the wall was
   open. It works off a MutationObserver rather than a callback because the
   cover can also arrive from the ✎ picker, and that path should update the
   record's other plaques too rather than leave them disagreeing.

   Only loader-written images are read as the answer — they carry data-imgid —
   and only slots that hold no such image are written to. A mirrored copy can
   therefore never become the source of another mirror, so the pass this makes
   the observer fire finds nothing left to do and it settles. */
let _cwallMirrorObs = null;
function watchCertWallCovers() {
  const grid = document.getElementById('cwall-grid');
  if (!grid) return;
  if (_cwallMirrorObs) _cwallMirrorObs.disconnect();
  _cwallMirrorObs = new MutationObserver(function (muts) {
    const keys = new Set();
    for (const m of muts) {
      // A full re-render mutates the grid itself, which owns no key — the cards
      // it writes come from _certWallResolved and need no mirroring.
      const slot = m.target.closest && m.target.closest('.cert-art-slot');
      if (slot && slot.dataset.cwkey) keys.add(slot.dataset.cwkey);
    }
    if (keys.size) mirrorCertWallCovers(keys);
  });
  _cwallMirrorObs.observe(grid, { childList: true, subtree: true });
}

// One sweep of the grid per batch of mutations, rather than an attribute
// selector per key: the keys are titles and artists, so they carry quotes.
function mirrorCertWallCovers(keys) {
  const grid = document.getElementById('cwall-grid');
  if (!grid) return;
  const src = {}, targets = {};
  grid.querySelectorAll('.cert-art-slot[data-cwkey]').forEach(function (slot) {
    const k = slot.dataset.cwkey;
    if (!keys.has(k)) return;
    const img = slot.querySelector('img.thumb');
    if (img && img.dataset.imgid && img.getAttribute('src')) { src[k] = img.getAttribute('src'); return; }
    (targets[k] || (targets[k] = [])).push(slot);
  });
  Object.keys(src).forEach(function (k) {
    (targets[k] || []).forEach(function (slot) {
      const img = slot.querySelector('img.thumb');
      if (img && img.getAttribute('src') === src[k]) return; // already showing it
      slot.innerHTML = '<img class="thumb" src="' + esc(src[k]) + '" alt="" loading="lazy">';
    });
  });
}

// Fills in the vinyl artwork for the album-modal certification plaques (same card style as the Certifications Wall)
async function loadAlbumCertPlaqueImages(items, albumName, artistName) {
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    let url = null;
    try {
      if (item.type === 'Album') {
        url = await getAlbumImage(albumName, artistName);
      } else {
        url = await getAlbumImage(albumName, artistName) || await getTrackImage(item.name, artistName);
      }
    } catch (e) {}
    if (!url) continue;
    const slot = document.getElementById('albcp-' + i);
    if (!slot) continue;
    /* The slot holds the artwork and nothing else, so the cover simply replaces
       what is in it — and if the URL turns out to be dead, the initials it
       replaced come back rather than leaving an empty square. */
    const ini = slot.innerHTML;
    slot.innerHTML = `<img class="thumb" src="${esc(url)}" alt="" loading="lazy">`;
    const img = slot.querySelector('img');
    if (img) img.onerror = function () { slot.innerHTML = ini; };
  }
}

// ─── CERTIFIED THIS PERIOD (the moving shelf) ──────────────────
/* The Certifications Wall answers "what have I ever earned". This answers a
   different question — "what did this week earn" — off the same history and
   the same plaques, so the two can never disagree about a date.

   A certification is a moment: the single play that carried a record over a
   threshold. That moment has a date, so it falls inside exactly one week and
   one month, which is what makes a per-period reel possible at all.

   Built once and cached. Records builds its own copy of this history inside
   buildRecords(), but that pass is lazy — the weekly chart has to work whether
   or not the user has ever opened Records, so this stands alone. */
let _certTimeline = null;
window.dcResetCertTimeline = () => { _certTimeline = null; };

function buildCertTimeline() {
  const items = {};
  // allPlays runs newest → oldest; a certification is about the order plays
  // arrived, so this walks it backwards into chronological order.
  const touch = function (key, p, kind, cfg, meta) {
    let it = items[key];
    if (!it) it = items[key] = Object.assign({ kind, key, first: p.date, plays: 0, events: [] }, meta);
    const n = ++it.plays;
    let tier = null, mult = 1;
    // Diamond first, so a config where plat === diamond still awards the
    // higher tier — the same order certCross() uses inside Records.
    if (n >= cfg.diamond && n % cfg.diamond === 0) { tier = 'diamond'; mult = n / cfg.diamond; }
    else if (n === cfg.plat) tier = 'plat';
    else if (n === cfg.gold) tier = 'gold';
    if (tier) it.events.push({ tier, mult, n, date: p.date });
  };

  for (let i = allPlays.length - 1; i >= 0; i--) {
    const p = allPlays[i];
    touch(songKey(p), p, 'song', CERT.song, {
      title: p.title, artist: p.artist,
      album: (p.album && p.album !== '—') ? p.album : ''
    });
    if (p.album && p.album !== '—') {
      // albumArtist() again, so a compilation contributes one album here too.
      const aa = albumArtist(p);
      touch(p.album + '|||' + aa, p, 'album', CERT.album, { title: p.album, artist: aa, album: '' });
    }
  }

  /* Flattened to one entry per plaque, in the wall's own vocabulary: the event
     history says 'plat', every plaque downstream says 'platinum'. */
  const out = [];
  for (const it of Object.values(items)) {
    it.events.forEach(function (ev, i) {
      out.push({
        type: it.kind, title: it.title, artist: it.artist, album: it.album,
        tier: ev.tier === 'plat' ? 'platinum' : ev.tier,
        mult: ev.mult || 1, n: ev.n, date: ev.date,
        // The comparison date has to be the one the charts filter by, or a
        // plaque earned late on a Sunday night would land in the wrong week.
        tz: tzDate(ev.date),
        top: i === it.events.length - 1,
        key: it.key
      });
    });
  }
  // Newest first: the reel reads as "here is what just happened".
  out.sort((a, b) => b.date - a.date);
  return out;
}

// Awards whose crossing play landed inside the period on screen.
function certsInRange(start, end) {
  if (!_certTimeline) _certTimeline = buildCertTimeline();
  return _certTimeline.filter(c => c.tz >= start && c.tz <= end);
}

/* One plaque. Deliberately the same markup as the wall's card — same frame,
   bolts, stage, fan and info block — so the two read as the same object and
   every plaque style is written once. Only the ids differ, because the wall
   and the reel can be on screen at the same time. */
function certReelCard(item, i) {
  const tierClass = CWALL_TIER_CLASS[item.tier] || 'gold';
  const discs = cwallDiscCount(item);
  const imgId = 'creel-img-' + i;
  return `<div class="cert-card creel-card cert-card--${tierClass}">
    <div class="cert-frame">
      <span class="cert-bolt cert-bolt--tl"></span><span class="cert-bolt cert-bolt--tr"></span>
      <span class="cert-bolt cert-bolt--bl"></span><span class="cert-bolt cert-bolt--br"></span>
      <div class="cert-stage">
        <div class="cert-art-slot" id="${esc(imgId)}"><div class="cert-art-initials">${esc(wallInitials(item.title))}</div></div>
        <div class="cert-fan cert-fan--${discs}">${'<div class="cert-disc"></div>'.repeat(discs)}</div>
      </div>
      <div class="cert-info">
        <div class="cert-title">${esc(item.title)}</div>
        <div class="cert-artist">${esc(item.artist)}</div>
        <div class="cert-tier-name">${cwallTierName(item)} <span class="cert-tier-of">certified ${esc(CWALL_TYPE_LABEL[item.type] || item.type || '')}</span></div>
        <div class="cert-date">${fmtCertDate(item.date)}</div>
      </div>
    </div>
  </div>`;
}

let _creelLoaderId = 0;

/* Takes the shelf down and empties it. The reel lives in the chart column,
   which the non-chart tabs (Records, Events, Awards, Soundtrack…) leave in
   place rather than unmount, so every one of them has to hide it explicitly —
   the nav handler calls this before switching views. Bumping the loader id
   orphans any artwork still in flight for a reel that is now gone. */
function hideCertReel() {
  const section = document.getElementById('certReelSection');
  const track = document.getElementById('certReelTrack');
  if (section) section.style.display = 'none';
  if (track) track.innerHTML = '';
  _creelLoaderId++;
}

/* Called from renderAll() with the period's own range, so the reel follows the
   prev/next navigation: step back a week and it shows that week's awards. */
function renderCertReel(start, end) {
  const section = document.getElementById('certReelSection');
  const track = document.getElementById('certReelTrack');
  if (!section || !track) return;

  // Weekly and monthly only. A year hands over hundreds of plaques, which is a
  // wall, not a reel — and that wall already exists in Records.
  if ((currentPeriod !== 'week' && currentPeriod !== 'month') || !allPlays.length) {
    hideCertReel();
    return;
  }

  const items = certsInRange(start, end);
  const countEl = document.getElementById('certReelCount');
  const subEl = document.getElementById('certReelSub');

  if (!items.length) {
    hideCertReel();
    return;
  }
  section.style.display = '';
  if (countEl) countEl.textContent = items.length;
  if (subEl) {
    /* Built from the plural helpers rather than one sentence with two numbers
       dropped in: "1 song awards" is wrong in English and worse in Spanish,
       where the noun and its article both have to agree. A kind with nothing
       to report is left out entirely instead of reading "and 0 albums". */
    const songs = items.filter(c => c.type === 'song').length;
    const albums = items.length - songs;
    subEl.textContent = [
      songs ? tCount('songs', songs) : '',
      albums ? tCount('albums', albums) : ''
    ].filter(Boolean).join(' · ');
  }

  /* One copy first, then measure. A week that earned two awards does not fill
     the shelf, and duplicating it there would hang the same plaque twice side
     by side — the loop is only honest once the content is wider than what can
     be seen. Card widths are fixed in CSS, so this measures true before any
     artwork has landed. */
  const vp = document.getElementById('certReelViewport');
  track.innerHTML = items.map(certReelCard).join('');
  const overflows = !!vp && track.scrollWidth > vp.clientWidth;

  /* Two copies back to back. The scroller wraps by subtracting one copy's
     width the moment it passes it, and with identical halves that subtraction
     lands on a pixel-identical frame — the seam is unobservable. */
  if (overflows) {
    track.innerHTML += items.map((it, i) => certReelCard(it, i + items.length)).join('');
  }
  // A shelf that fits sits still and centred; there is nothing to travel to.
  if (vp) {
    vp.classList.toggle('creel-static', !overflows);
    vp.dataset.loop = overflows ? '1' : '0';
    vp.scrollLeft = 0;
  }
  const hintEl = document.querySelector('#certReelSection .creel-hint');
  if (hintEl) hintEl.style.display = overflows ? '' : 'none';

  const ldr = ++_creelLoaderId;
  loadCertReelImages(items, ldr, overflows);
  initCertReel();
}

/* Artwork, fetched once per award and mirrored onto its twin in the second
   copy — the loop shows every plaque twice, and paying twice for the same
   cover would double the API traffic for nothing. */
async function loadCertReelImages(items, loaderId, hasTwin) {
  const BATCH = 4;
  for (let i = 0; i < items.length; i += BATCH) {
    if (_creelLoaderId !== loaderId) return;
    await Promise.all(items.slice(i, i + BATCH).map(async (item, j) => {
      const idx = i + j;
      const el = document.getElementById('creel-img-' + idx);
      if (!el || _creelLoaderId !== loaderId) return;
      const isSong = item.type === 'song';
      const name = item.title;
      const prefKey = (isSong ? 'song:' : 'album:') + (item.artist || '').toLowerCase() + '|||' + name.toLowerCase();
      await fetchAndInjectImage(el, {
        imgId: 'creel-img-' + idx, prefKey, name,
        title: isSong ? item.title : '',
        album: isSong ? (item.album || '') : item.title,
        artist: item.artist
      }, isSong ? 'song' : 'album');
      if (!hasTwin) return;
      const twin = document.getElementById('creel-img-' + (idx + items.length));
      if (twin) twin.innerHTML = el.innerHTML;
    }));
  }
}

/* ── The reel's motion ─────────────────────────────────────────
   Driven by scrollLeft rather than a CSS keyframe, because a keyframed
   transform cannot be dragged: the pointer and the animation would fight over
   the same property. Scrolling a real overflow container means the drag is
   just an assignment, the wrap is arithmetic, and the keyboard and trackpad
   get to move it for free.

   Three things stop the drift: the pointer resting on it, a drag in progress,
   and the section being off screen — an invisible reel should not be waking
   the compositor sixty times a second. */
function initCertReel() {
  const vp = document.getElementById('certReelViewport');
  if (!vp || vp.dataset.ready === '1') return;
  vp.dataset.ready = '1';

  const SPEED = 0.4;          // px per frame ≈ 24px/s at 60Hz — a slow shelf
  let hovering = false, dragging = false, visible = true, raf = null;
  let dragX = 0, dragScroll = 0, moved = 0;
  /* Its own flag rather than a permanent "hover": mouseleave would clear that
     on the first pass of the pointer and the shelf would start drifting for a
     reader who asked it not to. */
  let reduceMotion = false;

  /* The authoritative position, kept here rather than read back off the
     element. scrollLeft snaps to whole device pixels, so `scrollLeft += 0.4`
     is written as 0.4 and read back as 0 — the drift would round itself away
     every frame and the shelf would sit still at sixty frames a second. The
     fraction accumulates in `pos` instead, and only whole values reach the DOM. */
  let pos = 0;

  // One copy's width. Read live rather than cached: the plaques resize with
  // the viewport, and a stale half-width would make the loop jump.
  const half = () => vp.scrollWidth / 2;

  // A shelf whose plaques all fit has no second copy to wrap onto, so it must
  // not drift — it would scroll the content clean out of view.
  const looping = () => vp.dataset.loop === '1';

  // Both directions, so dragging backwards past the start wraps too.
  function wrapped(v) {
    if (!looping()) return v;
    const h = half();
    if (h <= 0) return v;
    if (v >= h) return v - h;
    if (v < 0) return v + h;
    return v;
  }

  function tick() {
    raf = null;
    /* Anything else that moved the shelf — a re-render resetting to 0, a
       trackpad swipe, the scrollbar — wins, and `pos` picks up from there.
       The threshold is wider than one pixel so the browser's own rounding of
       our writes doesn't read as an external change. */
    if (Math.abs(vp.scrollLeft - pos) > 2) pos = vp.scrollLeft;
    if (looping() && !hovering && !dragging && !reduceMotion) {
      pos = wrapped(pos + SPEED);
      vp.scrollLeft = pos;
    }
    schedule();
  }
  function schedule() {
    if (raf === null && visible && !document.hidden) raf = requestAnimationFrame(tick);
  }
  function stop() { if (raf !== null) { cancelAnimationFrame(raf); raf = null; } }

  vp.addEventListener('mouseenter', () => { hovering = true; });
  vp.addEventListener('mouseleave', () => { hovering = false; });

  vp.addEventListener('pointerdown', e => {
    // Let the middle and right buttons keep their native behaviour.
    if (e.button !== 0) return;
    dragging = true; moved = 0;
    dragX = e.clientX; dragScroll = vp.scrollLeft;
    vp.setPointerCapture(e.pointerId);
    vp.classList.add('is-dragging');
  });
  vp.addEventListener('pointermove', e => {
    if (!dragging) return;
    const dx = e.clientX - dragX;
    moved = Math.max(moved, Math.abs(dx));
    // Drag right, shelf goes right: the plaques follow the finger.
    pos = wrapped(dragScroll - dx);
    vp.scrollLeft = pos;
    // The anchor moves with the wrap, so the next frame of the same drag
    // measures from where the shelf actually is rather than jumping back.
    if (pos !== dragScroll - dx) { dragScroll = pos; dragX = e.clientX; }
  });
  const endDrag = e => {
    if (!dragging) return;
    dragging = false;
    vp.classList.remove('is-dragging');
    if (e.pointerId != null && vp.hasPointerCapture?.(e.pointerId)) vp.releasePointerCapture(e.pointerId);
  };
  vp.addEventListener('pointerup', endDrag);
  vp.addEventListener('pointercancel', endDrag);

  // A drag that crossed the shelf shouldn't also count as a click on whatever
  // plaque happened to be under the finger when it stopped.
  vp.addEventListener('click', e => { if (moved > 4) { e.stopPropagation(); e.preventDefault(); } }, true);

  // Keyboard: the viewport is focusable, so arrows should move it.
  vp.addEventListener('keydown', e => {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    e.preventDefault();
    pos = wrapped(vp.scrollLeft + (e.key === 'ArrowRight' ? 1 : -1) * 60);
    vp.scrollLeft = pos;
  });

  // Off screen or on a hidden tab, the loop shuts down entirely.
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(entries => {
      visible = entries[0].isIntersecting;
      if (visible) schedule(); else stop();
    }, { threshold: 0 }).observe(vp);
  }
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) stop(); else schedule();
  });

  /* Reduced motion means no unbidden drift — but the shelf stays draggable,
     so the content is still reachable rather than simply frozen. */
  const rm = window.matchMedia('(prefers-reduced-motion: reduce)');
  const applyRM = () => { reduceMotion = rm.matches; };
  applyRM();
  rm.addEventListener?.('change', applyRM);

  schedule();
}

/* ── DRAG TO BROWSE — the shared reel engine ───────────────────
   The certified shelf above proved the mechanism; this is that same mechanism
   with the ids taken out, so every other marquee in the app can have it. A CSS
   keyframe cannot be dragged — the pointer and the animation would both be
   writing `transform` — so a reel that opts in stops being an animation and
   becomes a real overflow container scrolled from rAF. Drag is then an
   assignment, the wrap is arithmetic, and the trackpad and keyboard move it
   for free.

   What a caller has to provide is what these marquees already had: a masked
   viewport, a `width: max-content` track, and the deck rendered twice. The
   second copy is what makes the loop seamless — subtracting one copy's width
   the moment the scroll passes it lands on a pixel-identical frame.

   Users: the Time Machine ticker, the Soundtrack reel, and every Events
   section's "Reel" view. */

// Per-viewport state, keyed off the element so a re-render can update the
// measurements without the listeners being attached a second time.
const _dcReels = new WeakMap();

/* Call after every render, with the track that was just filled and the number
   of seconds the old marquee took to cross one copy. Safe to call repeatedly:
   only the first call wires up the listeners. */
function dcMountReel(vp, track, durationSec) {
  if (!vp || !track) return;
  _dcReels.set(vp, { track, dur: Math.max(1, durationSec || 60), speed: 0.4 });
  vp.classList.add('dcreel');
  vp.dataset.reelPaused = '0';
  if (!vp.hasAttribute('tabindex')) vp.tabIndex = 0;
  vp.scrollLeft = 0;
  dcMeasureReel(vp);
  dcInitReel(vp);
}

/* Decides whether this deck is long enough to travel, and translates the
   marquee's duration into a per-frame drift so each reel keeps its own pace.
   Re-run by a ResizeObserver, because a reel is routinely built while its
   section is collapsed or its tab is hidden — where every measurement is 0. */
function dcMeasureReel(vp) {
  const st = _dcReels.get(vp);
  if (!st || !vp.classList.contains('dcreel')) return;
  const track = st.track;
  if (!track || !track.isConnected || !vp.clientWidth) return;

  /* One copy's width. While static the duplicate is hidden, so the track *is*
     one copy — reading it the same way in both states is what lets a reel that
     was measured at zero width recover the moment it gets a box. */
  const isStatic = vp.classList.contains('dcreel-static');
  const copyW = isStatic ? track.scrollWidth : track.scrollWidth / 2;
  const loops = copyW > vp.clientWidth + 8;

  vp.classList.toggle('dcreel-static', !loops);
  vp.dataset.reelLoop = loops ? '1' : '0';
  /* px per *second* that covers one copy in the time the marquee used to take.
     Per second, not per frame: the keyframe this replaced was time-based, so
     pacing the drift by frame instead would run it at 2× on a 120Hz panel and
     2.4× on a 144Hz one — the same reel at a different speed on every display. */
  st.pps = Math.min(120, Math.max(6, copyW / st.dur));
  if (!loops) vp.scrollLeft = 0;
}

function dcInitReel(vp) {
  if (vp.dataset.reelReady === '1') return;
  vp.dataset.reelReady = '1';

  // How far the pointer has to travel before this counts as a drag rather than
  // a click on the card underneath.
  const DRAG_SLOP = 4;

  let hovering = false, dragging = false, captured = false, visible = true, raf = null;
  let dragX = 0, dragScroll = 0, moved = 0;
  /* Its own flag rather than a permanent "hover": mouseleave would clear that
     on the first pass of the pointer. */
  let reduceMotion = false;

  /* The authoritative position, kept here rather than read back off the
     element. scrollLeft snaps to whole device pixels, so `scrollLeft += 0.4`
     is written as 0.4 and read back as 0 — the drift would round itself away
     every frame. The fraction accumulates here; only whole values reach the DOM. */
  let pos = 0;
  // Timestamp of the last drifting frame; null whenever the reel is held, so
  // the time it spent parked never counts as distance owed.
  let last = null;

  const state = () => _dcReels.get(vp);
  // The class goes away when the element is reused for another view (the Events
  // sections swap the same node between Reel, Tiles, Table and List), which is
  // what stops a stale listener from scrolling a table.
  const live = () => vp.classList.contains('dcreel');
  const looping = () => live() && vp.dataset.reelLoop === '1';
  const half = () => { const s = state(); return s && s.track ? s.track.scrollWidth / 2 : 0; };

  // Both directions, so dragging backwards past the start wraps too.
  function wrapped(v) {
    if (!looping()) return v;
    const h = half();
    if (h <= 0) return v;
    if (v >= h) return v - h;
    if (v < 0) return v + h;
    return v;
  }

  function tick(now) {
    raf = null;
    /* Anything else that moved the reel — a re-render resetting to 0, a
       trackpad swipe, the scrollbar — wins, and `pos` picks up from there. The
       threshold is wider than one pixel so the browser's own rounding of our
       writes doesn't read as an external change. */
    if (Math.abs(vp.scrollLeft - pos) > 2) pos = vp.scrollLeft;
    // An open card menu parks the reel: the tooltip is anchored to a card, and
    // a card that keeps moving walks out from under its own menu.
    const held = hovering || dragging || reduceMotion || vp.dataset.reelPaused === '1';
    /* Elapsed time, not frames — see dcMeasureReel(). Capped at ~3 frames so a
       long stall (a heavy render, a tab coming back) resumes the drift instead
       of teleporting the reel forward by however long it was away. */
    const dt = last === null ? 0 : Math.min(50, now - last);
    last = held ? null : now;
    if (looping() && !held) {
      pos = wrapped(pos + (state()?.pps || 24) * dt / 1000);
      vp.scrollLeft = pos;
    }
    schedule();
  }
  function schedule() {
    if (raf === null && visible && !document.hidden) raf = requestAnimationFrame(tick);
  }
  // Clearing the timestamp is what stops a reel that was off screen or on a
  // background tab from owing itself the whole absence when it comes back.
  function stop() { last = null; if (raf !== null) { cancelAnimationFrame(raf); raf = null; } }

  vp.addEventListener('mouseenter', () => { hovering = true; });
  vp.addEventListener('mouseleave', () => { hovering = false; });

  vp.addEventListener('pointerdown', e => {
    // Let the middle and right buttons keep their native behaviour.
    if (!live() || e.button !== 0) return;
    dragging = true; moved = 0; captured = false;
    dragX = e.clientX; dragScroll = vp.scrollLeft;
    vp.classList.add('is-dragging');
  });
  vp.addEventListener('pointermove', e => {
    if (!dragging) return;
    const dx = e.clientX - dragX;
    moved = Math.max(moved, Math.abs(dx));
    /* The capture is what keeps a drag alive once the pointer leaves the reel —
       but it also retargets the click that follows to the viewport, and the
       cards here are clickable (unlike the certified shelf's plaques). So it is
       taken only once the pointer has travelled far enough to be a drag rather
       than a press, which leaves an ordinary click on a card untouched. */
    if (!captured) {
      if (moved <= DRAG_SLOP) return;
      captured = true;
      vp.setPointerCapture(e.pointerId);
    }
    // Drag right, reel goes right: the cards follow the finger.
    pos = wrapped(dragScroll - dx);
    vp.scrollLeft = pos;
    // The anchor moves with the wrap, so the next frame of the same drag
    // measures from where the reel actually is rather than jumping back.
    if (pos !== dragScroll - dx) { dragScroll = pos; dragX = e.clientX; }
  });
  const endDrag = e => {
    if (!dragging) return;
    dragging = false;
    vp.classList.remove('is-dragging');
    if (captured && e.pointerId != null && vp.hasPointerCapture?.(e.pointerId)) vp.releasePointerCapture(e.pointerId);
    captured = false;
  };
  vp.addEventListener('pointerup', endDrag);
  vp.addEventListener('pointercancel', endDrag);

  /* The Events reels are built from <a> cards over <img> covers, both of which
     the browser will happily start a native drag on — which cancels the pointer
     stream mid-grab and leaves a ghost image trailing the cursor. */
  vp.addEventListener('dragstart', e => { if (live()) e.preventDefault(); });

  // A drag that crossed the reel shouldn't also count as a click on whatever
  // card happened to be under the finger when it stopped.
  vp.addEventListener('click', e => { if (moved > 4) { e.stopPropagation(); e.preventDefault(); } }, true);

  // Keyboard: the viewport is focusable, so arrows should move it.
  vp.addEventListener('keydown', e => {
    if (!live() || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return;
    e.preventDefault();
    pos = wrapped(vp.scrollLeft + (e.key === 'ArrowRight' ? 1 : -1) * 60);
    vp.scrollLeft = pos;
  });

  // Off screen or on a hidden tab, the loop shuts down entirely.
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(entries => {
      visible = entries[0].isIntersecting;
      if (visible) schedule(); else stop();
    }, { threshold: 0 }).observe(vp);
  }
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) stop(); else schedule();
  });

  /* A section expanding, a tab being shown, the window resizing: all of them
     change whether this deck still overflows, and the first two are how a reel
     measured at zero width gets its real numbers. */
  if ('ResizeObserver' in window) {
    new ResizeObserver(() => dcMeasureReel(vp)).observe(vp);
  }

  /* Reduced motion means no unbidden drift — but the reel stays draggable, so
     the cards past the right edge are still reachable rather than lost. */
  const rm = window.matchMedia('(prefers-reduced-motion: reduce)');
  const applyRM = () => { reduceMotion = rm.matches; };
  applyRM();
  rm.addEventListener?.('change', applyRM);

  schedule();
}

// ─── EVENTS CALENDAR (Birthdays & Anniversaries) ─────────────
function releaseIcon(type) {
  const t = (type || '').toLowerCase();
  if (t === 'single') return '🎵';
  if (t === 'album')  return '💿';
  if (t === 'ep')     return '📀';
  return '🎶';
}

function _releaseTypeKey(type) {
  const t = (type || '').toLowerCase();
  if (t === 'album') return 'album';
  if (t === 'single') return 'single';
  if (t === 'ep') return 'ep';
  return 'other';
}

function applyEventsTypeFilter(data) {
  const { birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent } = data;
  const showBirthday = eventsTypeFilter.has('birthday');
  const rtMatch = (type) => eventsTypeFilter.has(_releaseTypeKey(type));
  return {
    birthdays: showBirthday ? birthdays : [],
    recentBirthdays: showBirthday ? recentBirthdays : [],
    anniversaries: anniversaries.filter(a => rtMatch(a.type)),
    recentAnniversaries: recentAnniversaries.filter(a => rtMatch(a.type)),
    eventsUpcoming: eventsUpcoming.filter(({ release }) => rtMatch(release.type)),
    eventsRecent: eventsRecent.filter(({ release }) => rtMatch(release.type)),
  };
}

function toggleEventsType(type) {
  if (eventsTypeFilter.has(type)) {
    eventsTypeFilter.delete(type);
  } else {
    eventsTypeFilter.add(type);
  }
  try { localStorage.setItem('dc_events_type_filter', JSON.stringify([...eventsTypeFilter])); } catch (e) {}
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  _syncEventsTypeFilter();
  _syncCalExportBtn();
  if (type === 'show') {
    _syncConcertsSectionVisibility();
    if (_eventsCalendarData) renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);
  } else {
    if (_eventsRawData) _renderEventsFromRaw(_eventsRawData, _eventsArtists, true);
  }
}

function _syncConcertsSectionVisibility() {
  const section = document.getElementById('concertsSection');
  const filterBtn = document.getElementById('showsFilterBtn');
  const hasConcerts = true;
  if (filterBtn) filterBtn.style.display = hasConcerts ? '' : 'none';
  if (!section) return;
  const visible = hasConcerts && eventsTypeFilter.has('show');
  section.style.display = visible ? '' : 'none';
}

function _syncEventsTypeFilter() {
  document.querySelectorAll('.events-type-btn').forEach(btn => {
    btn.classList.toggle('active', eventsTypeFilter.has(btn.dataset.etype));
  });
  _syncConcertsSectionVisibility();
}

const EVENTS_CACHE_KEY = 'dc_eventsCache';
const EVENTS_CACHE_VER = 2;
const EVENTS_CACHE_TTL = 24 * 60 * 60 * 1000;
const EVENTS_WINDOW_DAYS = 30;
const CONCERTS_CACHE_KEY = 'dc_concertsCache';
const CONCERTS_CACHE_TTL = 6 * 60 * 60 * 1000;
const NMF_CACHE_KEY = 'dc_nmfCache';
const NMF_CACHE_TTL = 7 * 24 * 60 * 60 * 1000;
const NMF_HISTORY_KEY = 'dc_nmfHistory';
const NMF_HISTORY_MAX_WEEKS = 16;
const CONCERTS_ARTIST_LIMIT = 10;

function getTopNArtists(n) {
  const counts = {};
  for (const p of allPlays) {
    for (const a of p.artists) counts[a] = (counts[a] || 0) + 1;
  }
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, n).map(([name]) => name);
}

// TheAudioDB fallback — returns "YYYY-MM-DD" or null
const _tadbCache = {};
async function fetchBirthdayTADB(name) {
  if (_tadbCache[name] !== undefined) return _tadbCache[name];
  await new Promise(r => setTimeout(r, 500));
  try {
    const res = await fetch(`https://www.theaudiodb.com/api/v1/json/2/search.php?s=${encodeURIComponent(name)}`);
    if (!res.ok) { _tadbCache[name] = null; return null; }
    const d = await res.json();
    const born = d?.artists?.[0]?.strBornDT || null;
    _tadbCache[name] = (born && born.length >= 10) ? born.slice(0, 10) : null;
    return _tadbCache[name];
  } catch (e) { _tadbCache[name] = null; return null; }
}

// Wikidata SPARQL fallback — returns "YYYY-MM-DD" or null
const _wikidataCache = {};
async function fetchBirthdayWikidata(name) {
  if (_wikidataCache[name] !== undefined) return _wikidataCache[name];
  await new Promise(r => setTimeout(r, 300));
  try {
    const safeName = name.replace(/["\\]/g, ' ');
    const sparql = `SELECT ?dob WHERE { ?person rdfs:label "${safeName}"@en; wdt:P569 ?dob. FILTER(!ISBLANK(?dob)) } LIMIT 1`;
    const url = `https://query.wikidata.org/sparql?query=${encodeURIComponent(sparql)}&format=json`;
    const res = await fetch(url, { headers: { 'Accept': 'application/sparql-results+json' } });
    if (!res.ok) { _wikidataCache[name] = null; return null; }
    const d = await res.json();
    const val = d?.results?.bindings?.[0]?.dob?.value;
    if (!val) { _wikidataCache[name] = null; return null; }
    const m = val.match(/(\d{4}-\d{2}-\d{2})/);
    _wikidataCache[name] = m ? m[1] : null;
    return _wikidataCache[name];
  } catch (e) { _wikidataCache[name] = null; return null; }
}

// Returns days until next occurrence of MM-DD within windowDays, or null if too far away
function daysUntilNextOccurrence(mmdd, windowDays) {
  if (!mmdd || mmdd.includes('00')) return null;
  const today = tzNow(); today.setHours(0, 0, 0, 0);
  const [mm, dd] = mmdd.split('-').map(Number);
  let candidate = new Date(today.getFullYear(), mm - 1, dd);
  candidate.setHours(0, 0, 0, 0);
  if (candidate < today) candidate = new Date(today.getFullYear() + 1, mm - 1, dd);
  const days = Math.round((candidate - today) / 86400000);
  return days <= windowDays ? days : null;
}

// Returns days since last occurrence of MM-DD within windowDays, or null if too far back (or today)
function daysSinceLastOccurrence(mmdd, windowDays) {
  if (!mmdd || mmdd.includes('00')) return null;
  const today = tzNow(); today.setHours(0, 0, 0, 0);
  const [mm, dd] = mmdd.split('-').map(Number);
  let candidate = new Date(today.getFullYear(), mm - 1, dd);
  candidate.setHours(0, 0, 0, 0);
  if (candidate >= today) candidate = new Date(today.getFullYear() - 1, mm - 1, dd);
  const days = Math.round((today - candidate) / 86400000);
  return days > 0 && days <= windowDays ? days : null;
}

function ordinalSuffix(n) {
  if (n === 11 || n === 12 || n === 13) return n + 'th';
  const s = ['th', 'st', 'nd', 'rd'];
  return n + (s[n % 10] || 'th');
}

function renderBirthdayCard(entry) {
  const { artistName, dateStr, daysUntil } = entry;
  const isToday = daysUntil === 0;
  const birthYear = parseInt(dateStr.slice(0, 4));
  const currentYear = tzNow().getFullYear();
  const age = isToday ? currentYear - birthYear : (currentYear + (daysUntil > 0 ? 0 : 1)) - birthYear;
  const [, mm, dd] = dateStr.split('-');
  const displayDate = fmtDate(new Date(currentYear + (daysUntil < 0 ? 1 : 0), parseInt(mm) - 1, parseInt(dd)));
  const countdownLabel = isToday ? 'TODAY' : `in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`;
  const searchUrl = `https://www.google.com/search?q=${encodeURIComponent(artistName + ' birthday')}`;
  const imgHtml = `<img class="upcoming-card-img upcoming-card-img-pending" alt="" loading="lazy" data-artist="${esc(artistName)}" data-title="" data-sources="deezer-artist">`;
  // The card itself opens a Google search; the ＋ builds a playlist from what
  // the user has actually played by this artist (see dcPlTracksFor).
  return `<a class="upcoming-card${isToday ? ' event-today' : ''}" href="${searchUrl}" target="_blank" rel="noopener noreferrer">
    ${dcPlBtnHtml('artist', '', artistName, '', 'dc-pl-add-card')}
    ${imgHtml}
    <div class="upcoming-card-date${isToday ? ' soon' : ''}">${countdownLabel}</div>
    <div class="upcoming-card-title">${esc(artistName)}</div>
    <div class="upcoming-card-artist">${esc(displayDate)} · Turning ${age}</div>
    <div class="upcoming-card-type">🎂 Birthday</div>
  </a>`;
}

function renderRecentBirthdayCard(entry) {
  const { artistName, dateStr, daysAgo } = entry;
  const birthYear = parseInt(dateStr.slice(0, 4));
  const currentYear = tzNow().getFullYear();
  const age = currentYear - birthYear;
  const [, mm, dd] = dateStr.split('-');
  const displayDate = fmtDate(new Date(currentYear, parseInt(mm) - 1, parseInt(dd)));
  const daysAgoLabel = `${daysAgo} day${daysAgo === 1 ? '' : 's'} ago`;
  const searchUrl = `https://www.google.com/search?q=${encodeURIComponent(artistName + ' birthday')}`;
  const imgHtml = `<img class="upcoming-card-img upcoming-card-img-pending" alt="" loading="lazy" data-artist="${esc(artistName)}" data-title="" data-sources="deezer-artist">`;
  return `<a class="upcoming-card" href="${searchUrl}" target="_blank" rel="noopener noreferrer">
    ${dcPlBtnHtml('artist', '', artistName, '', 'dc-pl-add-card')}
    ${imgHtml}
    <div class="upcoming-card-date recent">${daysAgoLabel}</div>
    <div class="upcoming-card-title">${esc(artistName)}</div>
    <div class="upcoming-card-artist">${esc(displayDate)} · Turned ${age}</div>
    <div class="upcoming-card-type">🎂 Birthday</div>
  </a>`;
}

function renderAnniversaryCard(entry) {
  const { artistName, title, type, releaseDate, years, daysUntil, mbid } = entry;
  const isToday = daysUntil === 0;
  const typeKey = 'mb_type_' + (type || 'Release').toLowerCase();
  const typeLabel = t(typeKey) || type || 'Release';
  const countdownLabel = isToday ? 'TODAY' : `in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`;
  const searchUrl = `https://www.google.com/search?q=${encodeURIComponent(title + ' ' + artistName)}`;
  const imgSrc = mbid ? `https://coverartarchive.org/release-group/${mbid}/front-250` : null;
  const imgHtml = `<img class="upcoming-card-img${imgSrc ? '' : ' upcoming-card-img-pending'}" ${imgSrc ? `src="${imgSrc}" onerror="releaseImgFallback(this)"` : ''} alt="" loading="lazy" data-artist="${esc(artistName)}" data-title="${esc(title)}" data-sources="deezer,itunes,lastfm">`;
  // ＋ pulls this release's played tracks, falling back to the release itself
  // when it has never been played (see dcPlTracksFor).
  return `<a class="upcoming-card${isToday ? ' event-today' : ''}" href="${searchUrl}" target="_blank" rel="noopener noreferrer">
    ${dcPlBtnHtml('album', title, artistName, title, 'dc-pl-add-card')}
    ${imgHtml}
    <div class="upcoming-card-date${isToday ? ' soon' : ''}">${countdownLabel}</div>
    <div class="upcoming-card-title">${esc(title)}</div>
    <div class="upcoming-card-artist">${esc(artistName)}</div>
    <div class="upcoming-card-type">${releaseIcon(type)} ${ordinalSuffix(years)} Anniversary · ${esc(typeLabel)} · ${releaseDate.slice(0, 4)}</div>
  </a>`;
}

function renderRecentAnniversaryCard(entry) {
  const { artistName, title, type, releaseDate, years, daysAgo, mbid } = entry;
  const typeKey = 'mb_type_' + (type || 'Release').toLowerCase();
  const typeLabel = t(typeKey) || type || 'Release';
  const daysAgoLabel = `${daysAgo} day${daysAgo === 1 ? '' : 's'} ago`;
  const searchUrl = `https://www.google.com/search?q=${encodeURIComponent(title + ' ' + artistName)}`;
  const imgSrc = mbid ? `https://coverartarchive.org/release-group/${mbid}/front-250` : null;
  const imgHtml = `<img class="upcoming-card-img${imgSrc ? '' : ' upcoming-card-img-pending'}" ${imgSrc ? `src="${imgSrc}" onerror="releaseImgFallback(this)"` : ''} alt="" loading="lazy" data-artist="${esc(artistName)}" data-title="${esc(title)}" data-sources="deezer,itunes,lastfm">`;
  return `<a class="upcoming-card" href="${searchUrl}" target="_blank" rel="noopener noreferrer">
    ${dcPlBtnHtml('album', title, artistName, title, 'dc-pl-add-card')}
    ${imgHtml}
    <div class="upcoming-card-date recent">${daysAgoLabel}</div>
    <div class="upcoming-card-title">${esc(title)}</div>
    <div class="upcoming-card-artist">${esc(artistName)}</div>
    <div class="upcoming-card-type">${releaseIcon(type)} ${ordinalSuffix(years)} Anniversary · ${esc(typeLabel)} · ${releaseDate.slice(0, 4)}</div>
  </a>`;
}

// ─── EVENTS CALENDAR VIEW ──────────────────────────────────────

const _CAL_MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const _CAL_DAYS   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];

function buildCalendarDayMap(data, dateSet) {
  const { birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent, concerts = [] } = data;
  const map = {};
  const add = (ds, ev) => { if (!map[ds]) map[ds] = []; map[ds].push(ev); };
  const today = tzNow(); today.setHours(0, 0, 0, 0);
  const dateFromDelta = (delta) => {
    const d = new Date(today); d.setDate(d.getDate() + delta); return localDateStr(d);
  };
  const currentYear = tzNow().getFullYear();
  for (const b of birthdays) {
    const ds = dateFromDelta(b.daysUntil);
    if (!dateSet.has(ds)) continue;
    const isToday = b.daysUntil === 0;
    const birthYear = parseInt(b.dateStr.slice(0, 4));
    const age = currentYear - birthYear;
    const [, mm, dd] = b.dateStr.split('-');
    const dispDate = fmtDate(new Date(currentYear, parseInt(mm) - 1, parseInt(dd)));
    add(ds, { icon: '🎂', label: b.artistName, past: false, url: `https://www.google.com/search?q=${encodeURIComponent(b.artistName + ' birthday')}`, cls: 'cal-ev-birthday',
      ttType: 'birthday', ttArtist: b.artistName, ttTitle: b.artistName, ttMbid: '',
      ttDetail: `🎂 Birthday · ${dispDate} · Turning ${age}`,
      ttDateTxt: isToday ? 'TODAY' : `in ${b.daysUntil} day${b.daysUntil === 1 ? '' : 's'}`, ttDateCls: isToday ? 'soon' : '' });
  }
  for (const b of recentBirthdays) {
    const ds = dateFromDelta(-b.daysAgo);
    if (!dateSet.has(ds)) continue;
    const birthYear = parseInt(b.dateStr.slice(0, 4));
    const age = currentYear - birthYear;
    const [, mm, dd] = b.dateStr.split('-');
    const dispDate = fmtDate(new Date(currentYear, parseInt(mm) - 1, parseInt(dd)));
    add(ds, { icon: '🎂', label: b.artistName, past: true, url: `https://www.google.com/search?q=${encodeURIComponent(b.artistName + ' birthday')}`, cls: 'cal-ev-birthday',
      ttType: 'birthday', ttArtist: b.artistName, ttTitle: b.artistName, ttMbid: '',
      ttDetail: `🎂 Birthday · ${dispDate} · Turned ${age}`,
      ttDateTxt: `${b.daysAgo} day${b.daysAgo === 1 ? '' : 's'} ago`, ttDateCls: 'recent' });
  }
  for (const a of anniversaries) {
    const ds = dateFromDelta(a.daysUntil);
    if (!dateSet.has(ds)) continue;
    const isToday = a.daysUntil === 0;
    const typeKey = 'mb_type_' + (a.type || 'Release').toLowerCase();
    const typeLabel = t(typeKey) || a.type || 'Release';
    add(ds, { icon: releaseIcon(a.type), label: a.title, sub: a.artistName, past: false, url: `https://www.google.com/search?q=${encodeURIComponent(a.title + ' ' + a.artistName)}`, cls: 'cal-ev-anniversary',
      ttType: 'anniversary', ttArtist: a.artistName, ttTitle: a.title, ttMbid: a.mbid || '',
      ttDetail: `${releaseIcon(a.type)} ${ordinalSuffix(a.years)} Anniversary · ${typeLabel} · ${(a.releaseDate || '').slice(0, 4)}`,
      ttDateTxt: isToday ? 'TODAY' : `in ${a.daysUntil} day${a.daysUntil === 1 ? '' : 's'}`, ttDateCls: isToday ? 'soon' : '' });
  }
  for (const a of recentAnniversaries) {
    const ds = dateFromDelta(-a.daysAgo);
    if (!dateSet.has(ds)) continue;
    const typeKey = 'mb_type_' + (a.type || 'Release').toLowerCase();
    const typeLabel = t(typeKey) || a.type || 'Release';
    add(ds, { icon: releaseIcon(a.type), label: a.title, sub: a.artistName, past: true, url: `https://www.google.com/search?q=${encodeURIComponent(a.title + ' ' + a.artistName)}`, cls: 'cal-ev-anniversary',
      ttType: 'anniversary', ttArtist: a.artistName, ttTitle: a.title, ttMbid: a.mbid || '',
      ttDetail: `${releaseIcon(a.type)} ${ordinalSuffix(a.years)} Anniversary · ${typeLabel} · ${(a.releaseDate || '').slice(0, 4)}`,
      ttDateTxt: `${a.daysAgo} day${a.daysAgo === 1 ? '' : 's'} ago`, ttDateCls: 'recent' });
  }
  for (const { release: r, artistName } of eventsUpcoming) {
    if (!r.date || !dateSet.has(r.date)) continue;
    const { label: dateLabel, soon } = upcomingDateLabel(r.date);
    const typeKey = 'mb_type_' + (r.type || 'Release').toLowerCase();
    const typeLabel = t(typeKey) || r.type || 'Release';
    add(r.date, { icon: releaseIcon(r.type), label: r.title, sub: artistName, past: false, url: `https://www.google.com/search?q=${encodeURIComponent(r.title + ' ' + artistName)}`, cls: 'cal-ev-release',
      ttType: 'release', ttArtist: artistName, ttTitle: r.title, ttMbid: r.mbid || '',
      ttDetail: `${releaseIcon(r.type)} ${typeLabel}`,
      ttDateTxt: dateLabel, ttDateCls: soon ? 'soon' : '' });
  }
  for (const { release: r, artistName } of eventsRecent) {
    if (!r.date || !dateSet.has(r.date)) continue;
    const typeKey = 'mb_type_' + (r.type || 'Release').toLowerCase();
    const typeLabel = t(typeKey) || r.type || 'Release';
    add(r.date, { icon: releaseIcon(r.type), label: r.title, sub: artistName, past: true, url: `https://www.google.com/search?q=${encodeURIComponent(r.title + ' ' + artistName)}`, cls: 'cal-ev-release',
      ttType: 'release', ttArtist: artistName, ttTitle: r.title, ttMbid: r.mbid || '',
      ttDetail: `${releaseIcon(r.type)} ${typeLabel}`,
      ttDateTxt: fmtDate(new Date(r.date + 'T00:00:00')), ttDateCls: 'recent' });
  }
  const todayCal = tzNow(); todayCal.setHours(0, 0, 0, 0);
  for (const { event: ev, artistName } of concerts) {
    const date = ev.dates?.start?.localDate;
    if (!date || !dateSet.has(date)) continue;
    const time = ev.dates?.start?.localTime || '';
    const venue = ev._embedded?.venues?.[0];
    const venueName = venue?.name || '';
    const city = venue?.city?.name || '';
    const stateCode = venue?.state?.stateCode || venue?.country?.countryCode || '';
    const loc = [city, stateCode].filter(Boolean).join(', ');
    const showDate = new Date(date + 'T00:00:00');
    const isPast = showDate < todayCal;
    const daysUntil = Math.round((showDate - todayCal) / 86400000);
    const isToday = daysUntil === 0;
    add(date, { icon: '🎤', label: artistName, sub: venueName + (loc ? ' · ' + loc : ''), past: isPast,
      url: ev.url || `https://www.ticketmaster.com/search?q=${encodeURIComponent(artistName)}`, cls: 'cal-ev-concert',
      ttType: 'concert', ttArtist: artistName, ttTitle: ev.name || artistName, ttMbid: '',
      ttDetail: `🎤 Live Show · ${venueName}${loc ? ' · ' + loc : ''}${time ? ' · ' + time.slice(0, 5) : ''}`,
      ttDateTxt: isToday ? 'TODAY' : isPast ? fmtDate(showDate) : `in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`,
      ttDateCls: isToday ? 'soon' : isPast ? 'recent' : '' });
  }
  return map;
}

// ── Calendar helpers ───────────────────────────────────────────

function _calDateStr(y, m, d) {
  return `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

function _calMonthDateSet(year, month) {
  const days = new Date(year, month + 1, 0).getDate();
  const p = `${year}-${String(month + 1).padStart(2, '0')}`;
  return new Set(Array.from({ length: days }, (_, i) => `${p}-${String(i + 1).padStart(2, '0')}`));
}

function getWeekDates(year, month, day) {
  const anchor = new Date(year, month, day);
  const offset = (anchor.getDay() - weekStartDay + 7) % 7;
  const start = new Date(anchor);
  start.setDate(start.getDate() - offset);
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(start); d.setDate(d.getDate() + i); return d;
  });
}

function _calAdjustDate(year, month, day, delta) {
  const d = new Date(year, month, day + delta);
  return { year: d.getFullYear(), month: d.getMonth(), day: d.getDate() };
}

function renderCalEventsHtml(events) {
  return `<div class="cal-cell-events">` + events.map(ev =>
    `<a class="cal-ev ${ev.cls}${ev.past ? ' cal-ev-past' : ''}" href="${ev.url}" target="_blank" rel="noopener noreferrer" data-ctt="${esc(ev.ttType||'')}" data-cta="${esc(ev.ttArtist||'')}" data-ctl="${esc(ev.ttTitle||'')}" data-ctm="${esc(ev.ttMbid||'')}" data-ctd="${esc(ev.ttDetail||'')}" data-ctx="${esc(ev.ttDateTxt||'')}" data-ctf="${esc(ev.ttDateCls||'')}">
      <span class="cal-ev-icon">${ev.icon}</span><span class="cal-ev-text"><span class="cal-ev-label">${esc(ev.label)}</span>${ev.sub ? `<span class="cal-ev-sub">${esc(ev.sub)}</span>` : ''}</span>
    </a>`
  ).join('') + `</div>`;
}

// ── Month view ─────────────────────────────────────────────────

function renderCalMonth(calEl, titleEl, data, year, month) {
  const dateSet = _calMonthDateSet(year, month);
  const dayMap = buildCalendarDayMap(data, dateSet);
  const today = tzNow(); today.setHours(0, 0, 0, 0);
  const todayStr = localDateStr(today);
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  titleEl.innerHTML = `<span class="cal-title-month">${_CAL_MONTHS[month]}</span><span class="cal-title-year">${year}</span>`;

  let html = _CAL_DAYS.map(d => `<div class="cal-dow">${d}</div>`).join('');
  for (let i = 0; i < firstDow; i++) html += `<div class="cal-cell cal-cell-empty"></div>`;
  for (let d = 1; d <= daysInMonth; d++) {
    const ds = _calDateStr(year, month, d);
    const events = dayMap[ds] || [];
    const isToday = ds === todayStr;
    const isPast  = ds < todayStr;
    html += `<div class="cal-cell${isToday ? ' cal-today' : ''}${isPast && !isToday ? ' cal-past' : ''}">
      <div class="cal-cell-num">${d}</div>`;
    if (events.length) html += renderCalEventsHtml(events);
    html += `</div>`;
  }
  calEl.className = 'events-cal-grid';
  calEl.innerHTML = html;
}

// ── Week view ──────────────────────────────────────────────────

function renderCalWeek(calEl, titleEl, data, year, month, day) {
  const weekDates = getWeekDates(year, month, day);
  const dateSet = new Set(weekDates.map(d => localDateStr(d)));
  const dayMap = buildCalendarDayMap(data, dateSet);
  const today = tzNow(); today.setHours(0, 0, 0, 0);
  const todayStr = localDateStr(today);

  const first = weekDates[0], last = weekDates[6];
  const fm = _CAL_MONTHS[first.getMonth()], lm = _CAL_MONTHS[last.getMonth()];
  titleEl.textContent = first.getMonth() === last.getMonth()
    ? `${fm} ${first.getDate()}–${last.getDate()}, ${last.getFullYear()}`
    : `${fm} ${first.getDate()} – ${lm} ${last.getDate()}, ${last.getFullYear()}`;

  let html = weekDates.map(d => {
    const ds = localDateStr(d);
    const isToday = ds === todayStr;
    const isPast  = ds < todayStr;
    return `<div class="cal-dow cal-week-dow${isToday ? ' cal-week-dow-today' : ''}${isPast && !isToday ? ' cal-week-dow-past' : ''}">
      <div class="cal-week-dow-name">${_CAL_DAYS[d.getDay()]}</div>
      <div class="cal-week-dow-num">${d.getDate()}</div>
    </div>`;
  }).join('');

  html += weekDates.map(d => {
    const ds = localDateStr(d);
    const events = dayMap[ds] || [];
    const isToday = ds === todayStr;
    const isPast  = ds < todayStr;
    return `<div class="cal-cell cal-week-cell${isToday ? ' cal-today' : ''}${isPast && !isToday ? ' cal-past' : ''}">
      ${events.length ? renderCalEventsHtml(events) : ''}
    </div>`;
  }).join('');

  calEl.className = 'events-cal-grid cal-week-grid';
  calEl.innerHTML = html;
}

// ── Day view ───────────────────────────────────────────────────

const _CAL_DOW_FULL = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];

function renderCalDay(calEl, titleEl, data, year, month, day) {
  const dateObj = new Date(year, month, day);
  const ds = localDateStr(dateObj);
  const dateSet = new Set([ds]);
  const dayMap = buildCalendarDayMap(data, dateSet);
  const events = dayMap[ds] || [];

  titleEl.textContent = `${_CAL_DOW_FULL[dateObj.getDay()]}, ${fmtDate(dateObj)}`;

  if (!events.length) {
    calEl.className = 'events-cal-day';
    calEl.innerHTML = `<div class="cal-day-empty">No events on this day</div>`;
    return;
  }

  const html = events.map(ev => {
    const mainTitle = ev.ttType === 'birthday' ? ev.ttArtist : ev.ttTitle;
    const artistLine = ev.ttType !== 'birthday' ? `<div class="cal-day-item-artist">${esc(ev.ttArtist)}</div>` : '';
    return `<a class="cal-day-item ${ev.cls}${ev.past ? ' cal-ev-past' : ''}" href="${ev.url}" target="_blank" rel="noopener noreferrer" data-ctt="${esc(ev.ttType||'')}" data-cta="${esc(ev.ttArtist||'')}" data-ctl="${esc(ev.ttTitle||'')}" data-ctm="${esc(ev.ttMbid||'')}" data-ctd="${esc(ev.ttDetail||'')}" data-ctx="${esc(ev.ttDateTxt||'')}" data-ctf="${esc(ev.ttDateCls||'')}">
      <div class="cal-day-item-img-wrap" data-mbid="${esc(ev.ttMbid||'')}" data-artist="${esc(ev.ttArtist||'')}" data-evtype="${esc(ev.ttType||'')}"></div>
      <div class="cal-day-item-body">
        <div class="cal-day-item-title">${esc(mainTitle)}</div>
        ${artistLine}
        <div class="cal-day-item-detail">${ev.ttDetail}</div>
      </div>
    </a>`;
  }).join('');

  calEl.className = 'events-cal-day';
  calEl.innerHTML = html;
  _triggerCalDayImgs(calEl);
}

function _triggerCalDayImgs(calEl) {
  calEl.querySelectorAll('.cal-day-item-img-wrap').forEach(wrap => {
    const { mbid, artist, evtype } = wrap.dataset;
    if (mbid) {
      const img = document.createElement('img');
      img.className = 'cal-day-item-img';
      img.alt = '';
      img.onerror = () => { if (wrap.isConnected) wrap.innerHTML = _calTtPlaceholderHtml(artist); };
      img.src = `https://coverartarchive.org/release-group/${mbid}/front-250`;
      wrap.appendChild(img);
    } else {
      wrap.innerHTML = _calTtPlaceholderHtml(artist);
      if (evtype === 'birthday' && artist) _loadCalTtArtistImg(wrap, artist);
    }
  });
}

// ── Dispatcher ─────────────────────────────────────────────────

function renderEventsCalendar(data, year, month) {
  const calEl = document.getElementById('eventsCalendarGrid');
  const titleEl = document.getElementById('eventsCalendarTitle');
  if (!calEl || !titleEl) return;
  const merged = { ...data, concerts: eventsTypeFilter.has('show') ? (_concertsData || []) : [] };
  if (eventsCalendarView === 'week') {
    renderCalWeek(calEl, titleEl, merged, year, month, eventsCalendarDay);
  } else if (eventsCalendarView === 'day') {
    renderCalDay(calEl, titleEl, merged, year, month, eventsCalendarDay);
  } else {
    renderCalMonth(calEl, titleEl, merged, year, month);
  }
  _syncCalViewBtns();
}

function _syncCalViewBtns() {
  document.querySelectorAll('.cal-view-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.view === eventsCalendarView);
  });
  _syncCalExportBtn();
}

function _syncCalExportBtn() {
  const btn = document.getElementById('calExportPlaylistBtn');
  const playBtn = document.getElementById('calPlayAllBtn');
  const createPlBtn = document.getElementById('calCreatePlBtn');
  const isDay = eventsCalendarView === 'day';
  const singlesOnly = eventsTypeFilter.size === 1 && eventsTypeFilter.has('single');
  const show = (isDay && singlesOnly) ? '' : 'none';
  if (btn) btn.style.display = show;
  if (playBtn) playBtn.style.display = show;
  if (createPlBtn) createPlBtn.style.display = show;
}

function setCalView(view) {
  eventsCalendarView = view;
  try { localStorage.setItem('dc_cal_view', view); } catch (e) {}
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  if (view !== 'month') {
    const tod = tzNow();
    if (tod.getFullYear() === eventsCalendarYear && tod.getMonth() === eventsCalendarMonth) {
      eventsCalendarDay = tod.getDate();
    } else {
      eventsCalendarDay = 1;
    }
  }
  if (_eventsCalendarData) renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);
}

function eventsCalendarPrev() {
  if (eventsCalendarView === 'week') {
    const r = _calAdjustDate(eventsCalendarYear, eventsCalendarMonth, eventsCalendarDay, -7);
    eventsCalendarYear = r.year; eventsCalendarMonth = r.month; eventsCalendarDay = r.day;
  } else if (eventsCalendarView === 'day') {
    const r = _calAdjustDate(eventsCalendarYear, eventsCalendarMonth, eventsCalendarDay, -1);
    eventsCalendarYear = r.year; eventsCalendarMonth = r.month; eventsCalendarDay = r.day;
  } else {
    eventsCalendarMonth--;
    if (eventsCalendarMonth < 0) { eventsCalendarMonth = 11; eventsCalendarYear--; }
  }
  if (_eventsCalendarData) renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);
}

function eventsCalendarNext() {
  if (eventsCalendarView === 'week') {
    const r = _calAdjustDate(eventsCalendarYear, eventsCalendarMonth, eventsCalendarDay, 7);
    eventsCalendarYear = r.year; eventsCalendarMonth = r.month; eventsCalendarDay = r.day;
  } else if (eventsCalendarView === 'day') {
    const r = _calAdjustDate(eventsCalendarYear, eventsCalendarMonth, eventsCalendarDay, 1);
    eventsCalendarYear = r.year; eventsCalendarMonth = r.month; eventsCalendarDay = r.day;
  } else {
    eventsCalendarMonth++;
    if (eventsCalendarMonth > 11) { eventsCalendarMonth = 0; eventsCalendarYear++; }
  }
  if (_eventsCalendarData) renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);
}

// ====== Events Section View Modes ======
const _eventsViewDefaults = {
  birthdays: 'carousel', anniversaries: 'carousel', eventsUpcoming: 'carousel',
  eventsRecent: 'carousel', recentBirthdays: 'carousel', recentAnniversaries: 'carousel', concerts: 'carousel',
  nmf: 'carousel', upcoming: 'carousel', recent: 'carousel'
};
const eventsViewModes = Object.assign({}, _eventsViewDefaults,
  (() => { try { return JSON.parse(localStorage.getItem('dc_events_view_modes') || '{}'); } catch (e) { return {}; } })()
);
let _eventsLastData = null;
let _upcomingLastData = null;
let _recentLastData = null;
const EV_GRID_IDS = {
  birthdays: 'birthdaysGrid', anniversaries: 'anniversariesGrid',
  eventsUpcoming: 'eventsUpcomingGrid', eventsRecent: 'eventsRecentGrid',
  recentBirthdays: 'eventsRecentBirthdaysGrid', recentAnniversaries: 'eventsRecentAnniversariesGrid',
  concerts: 'concertsGrid', nmf: 'nmfGrid',
  upcoming: 'upcomingGrid', recent: 'recentGrid'
};

function setEventsView(sectionKey, mode) {
  eventsViewModes[sectionKey] = mode;
  try { localStorage.setItem('dc_events_view_modes', JSON.stringify(eventsViewModes)); } catch (e) {}
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  document.querySelectorAll('#' + sectionKey + 'ViewBtns .ev-view-btn')
    .forEach(b => b.classList.toggle('active', b.dataset.view === mode));
  _evReRenderSection(sectionKey);
}

function _evReRenderSection(sectionKey) {
  if (sectionKey === 'concerts') {
    if (_concertsData && _concertsData.length) _evRenderSectionByKey('concerts', _concertsData);
    return;
  }
  if (sectionKey === 'nmf') {
    if (_nmfData && _nmfData.length) _evRenderSectionByKey('nmf', _nmfData);
    return;
  }
  if (sectionKey === 'upcoming') {
    if (_upcomingLastData) _evRenderSectionByKey('upcoming', sortUpcomingReleases([..._upcomingLastData]));
    return;
  }
  if (sectionKey === 'recent') {
    if (_recentLastData) _evRenderSectionByKey('recent', sortRecentReleases([..._recentLastData]));
    return;
  }
  if (!_eventsLastData) return;
  const f = applyEventsTypeFilter(_eventsLastData);
  const sortFn = (a, b) => a.daysUntil - b.daysUntil;
  const sortFnAgo = (a, b) => a.daysAgo - b.daysAgo;
  const itemsMap = {
    birthdays: () => [...f.birthdays].sort(sortFn),
    anniversaries: () => [...f.anniversaries].sort(sortFn),
    eventsUpcoming: () => sortUpcomingReleases([...f.eventsUpcoming]),
    eventsRecent: () => sortRecentReleases([...f.eventsRecent]),
    recentBirthdays: () => [...f.recentBirthdays].sort(sortFnAgo),
    recentAnniversaries: () => [...f.recentAnniversaries].sort(sortFnAgo)
  };
  if (itemsMap[sectionKey]) _evRenderSectionByKey(sectionKey, itemsMap[sectionKey]());
}

// `pl` (added below for the sections that link straight out to a search instead
// of opening the action menu) is what the ＋ add-to-playlist button on each row
// or card is built from — see dcPlBtnHtml. Sections carrying a `menuAction`
// don't need it: their menu already offers the playlist option.
function _evNormalize(sectionKey, items) {
  const out = [];
  const mkLabel = (n, unit) => `${n} ${unit}${n === 1 ? '' : 's'}`;
  if (sectionKey === 'birthdays') {
    for (const { artistName, dateStr, daysUntil } of items) {
      const isToday = daysUntil === 0;
      const curYr = tzNow().getFullYear();
      const age = parseInt(dateStr.slice(0, 4));
      const [, mm, dd] = dateStr.split('-');
      const d = new Date(curYr + (daysUntil < 0 ? 1 : 0), parseInt(mm) - 1, parseInt(dd));
      out.push({ title: artistName, artist: `${fmtDate(d)} · Turning ${curYr - age + (daysUntil < 0 ? 1 : 0)}`,
        dateLabel: isToday ? 'TODAY' : `in ${mkLabel(daysUntil, 'day')}`, dateSort: daysUntil,
        artistSort: artistName, typeLabel: '🎂 Birthday',
        href: `https://www.google.com/search?q=${encodeURIComponent(artistName + ' birthday')}`,
        pl: { kind: 'artist', title: '', artist: artistName, album: '' },
        imgSrc: null, imgAttr: { artist: artistName, title: '', sources: 'deezer-artist' }, isToday });
    }
  } else if (sectionKey === 'anniversaries') {
    for (const { artistName, title, type, releaseDate, years, daysUntil, mbid } of items) {
      const isToday = daysUntil === 0;
      const tl = t('mb_type_' + (type || 'Release').toLowerCase()) || type || 'Release';
      out.push({ title, artist: artistName,
        dateLabel: isToday ? 'TODAY' : `in ${mkLabel(daysUntil, 'day')}`, dateSort: daysUntil,
        artistSort: artistName, typeLabel: `🎵 ${ordinalSuffix(years)} Anniversary · ${tl} · ${releaseDate.slice(0, 4)}`,
        href: `https://www.google.com/search?q=${encodeURIComponent(title + ' ' + artistName)}`,
        pl: { kind: 'album', title, artist: artistName, album: title },
        imgSrc: mbid ? `https://coverartarchive.org/release-group/${mbid}/front-250` : null,
        imgAttr: { artist: artistName, title, sources: 'deezer,itunes,lastfm' }, isToday });
    }
  } else if (sectionKey === 'eventsUpcoming' || sectionKey === 'upcoming') {
    for (const { release, artistName } of items) {
      const { label } = upcomingDateLabel(release.date);
      const tl = t('mb_type_' + (release.type || 'Release').toLowerCase()) || release.type || 'Release';
      out.push({ title: release.title, artist: artistName, dateLabel: label, dateSort: release.date,
        artistSort: artistName, typeLabel: tl,
        menuAction: '_relShowMenu', // unreleased — Spotify/Google popup only, never a player option
        imgSrc: release.mbid ? `https://coverartarchive.org/release-group/${release.mbid}/front-250` : null,
        imgAttr: { artist: artistName, title: release.title, sources: 'itunes,lastfm' }, isToday: false });
    }
  } else if (sectionKey === 'eventsRecent' || sectionKey === 'recent') {
    for (const { release, artistName } of items) {
      const tl = t('mb_type_' + (release.type || 'Release').toLowerCase()) || release.type || 'Release';
      out.push({ title: release.title, artist: artistName,
        dateLabel: fmtDate(new Date(release.date + 'T00:00:00')), dateSort: release.date,
        artistSort: artistName, typeLabel: tl,
        menuAction: '_tmShowAlbumMenu', // already released — popup adds a player option if it's been played
        imgSrc: release.mbid ? `https://coverartarchive.org/release-group/${release.mbid}/front-250` : null,
        imgAttr: { artist: artistName, title: release.title, sources: 'itunes,lastfm' }, isToday: false });
    }
  } else if (sectionKey === 'recentBirthdays') {
    for (const { artistName, dateStr, daysAgo } of items) {
      const curYr = tzNow().getFullYear();
      const birthYr = parseInt(dateStr.slice(0, 4));
      const [, mm, dd] = dateStr.split('-');
      out.push({ title: artistName,
        artist: `${fmtDate(new Date(curYr, parseInt(mm) - 1, parseInt(dd)))} · Turned ${curYr - birthYr}`,
        dateLabel: mkLabel(daysAgo, 'day') + ' ago', dateSort: -daysAgo,
        artistSort: artistName, typeLabel: '🎂 Birthday',
        href: `https://www.google.com/search?q=${encodeURIComponent(artistName + ' birthday')}`,
        pl: { kind: 'artist', title: '', artist: artistName, album: '' },
        imgSrc: null, imgAttr: { artist: artistName, title: '', sources: 'deezer-artist' }, isToday: false });
    }
  } else if (sectionKey === 'recentAnniversaries') {
    for (const { artistName, title, type, releaseDate, years, daysAgo, mbid } of items) {
      const tl = t('mb_type_' + (type || 'Release').toLowerCase()) || type || 'Release';
      out.push({ title, artist: artistName,
        dateLabel: mkLabel(daysAgo, 'day') + ' ago', dateSort: -daysAgo,
        artistSort: artistName, typeLabel: `🎵 ${ordinalSuffix(years)} Anniversary · ${tl} · ${releaseDate.slice(0, 4)}`,
        href: `https://www.google.com/search?q=${encodeURIComponent(title + ' ' + artistName)}`,
        pl: { kind: 'album', title, artist: artistName, album: title },
        imgSrc: mbid ? `https://coverartarchive.org/release-group/${mbid}/front-250` : null,
        imgAttr: { artist: artistName, title, sources: 'deezer,itunes,lastfm' }, isToday: false });
    }
  } else if (sectionKey === 'nmf') {
    const typeMap = { album: '💿 Album', single: '🎵 Single', ep: '📀 EP' };
    for (const album of items) {
      const typeLabel = typeMap[album.record_type] || '🎶 Release';
      const href = album.link || `https://www.deezer.com/album/${album.id}`;
      const dateStr = album.release_date || '';
      out.push({
        title: album.title || '',
        artist: album.artist?.name || '',
        dateLabel: dateStr ? fmtDate(new Date(dateStr + 'T00:00:00')) : '',
        dateSort: dateStr,
        artistSort: album.artist?.name || '',
        typeLabel,
        href,
        imgSrc: album.cover_xl || album.cover_big || album.cover_medium || null,
        imgAttr: { artist: album.artist?.name || '', title: album.title || '', sources: 'deezer' },
        isToday: false
      });
    }
  } else if (sectionKey === 'concerts') {
    for (const { event, artistName } of items) {
      const date = event.dates?.start?.localDate || '';
      const time = event.dates?.start?.localTime || '';
      const venue = event._embedded?.venues?.[0];
      const venueName = venue?.name || '';
      const city = venue?.city?.name || '';
      const sc = venue?.state?.stateCode || venue?.country?.countryCode || '';
      const loc = [city, sc].filter(Boolean).join(', ');
      const url = event.url || `https://www.ticketmaster.com/search?q=${encodeURIComponent(artistName)}`;
      const sd = date ? new Date(date + 'T12:00:00') : null;
      const du = sd ? Math.round((sd - tzNow()) / 86400000) : null;
      const isToday = du === 0;
      out.push({ title: artistName, artist: `${venueName}${loc ? ' · ' + loc : ''}`,
        dateLabel: du === null ? '' : isToday ? 'TODAY' : `in ${mkLabel(du, 'day')}`,
        dateSort: du !== null ? du : 9999, artistSort: artistName,
        typeLabel: `🎤 Live Show · ${date ? fmtDate(sd) : ''}${time ? ' · ' + time.slice(0, 5) : ''}`,
        href: url, imgSrc: null,
        imgAttr: { artist: artistName, title: '', sources: 'deezer-artist' }, isToday: !!isToday });
    }
  }
  return out;
}

function _evImgTag(item, cls) {
  const attrs = `data-artist="${esc(item.imgAttr.artist)}" data-title="${esc(item.imgAttr.title)}" data-sources="${esc(item.imgAttr.sources)}"`;
  if (item.imgSrc)
    return `<img class="${cls}" src="${esc(item.imgSrc)}" onerror="releaseImgFallback(this)" alt="" loading="lazy" ${attrs}>`;
  return `<img class="${cls} upcoming-card-img-pending" alt="" loading="lazy" ${attrs}>`;
}

// What each section last rendered, so the header's "＋ Playlist" button can
// stage exactly what's on screen without re-deriving it (see evAddSectionToPlaylist).
const _evLastItems = {};

function _evRenderSectionByKey(sectionKey, items) {
  const gridEl = document.getElementById(EV_GRID_IDS[sectionKey]);
  if (!gridEl) return;
  _evLastItems[sectionKey] = items || [];
  _evUpdatePlBtn(sectionKey);
  const mode = eventsViewModes[sectionKey] || 'tiles';

  const nmfCalOuter = document.getElementById('nmfCalOuter');

  if (sectionKey === 'nmf' && mode === 'calendar') {
    if (nmfCalOuter) nmfCalOuter.style.display = '';
    const history = _getNMFHistory();
    const fridays = Object.keys(history).sort().reverse();
    if (!_nmfCalSelectedFriday || !history[_nmfCalSelectedFriday]) {
      _nmfCalSelectedFriday = fridays[0] || null;
    }
    renderNMFCalendar();
    const selAlbums = (_nmfCalSelectedFriday && history[_nmfCalSelectedFriday]) || items || [];
    gridEl.className = 'upcoming-grid';
    gridEl.innerHTML = selAlbums.map(renderNMFCard).join('');
    triggerPendingImgs(gridEl);
    return;
  }

  if (sectionKey === 'nmf' && nmfCalOuter) nmfCalOuter.style.display = 'none';

  if (mode === 'tiles') {
    gridEl.className = 'upcoming-grid';
    if (!items.length) { gridEl.innerHTML = ''; return; }
    if (sectionKey === 'birthdays') gridEl.innerHTML = items.map(renderBirthdayCard).join('');
    else if (sectionKey === 'anniversaries') gridEl.innerHTML = items.map(renderAnniversaryCard).join('');
    else if (sectionKey === 'eventsUpcoming' || sectionKey === 'upcoming') gridEl.innerHTML = items.map(({ release, artistName }) => renderUpcomingCard(release, artistName)).join('');
    else if (sectionKey === 'eventsRecent' || sectionKey === 'recent') gridEl.innerHTML = items.map(({ release, artistName }) => renderRecentCard(release, artistName)).join('');
    else if (sectionKey === 'recentBirthdays') gridEl.innerHTML = items.map(renderRecentBirthdayCard).join('');
    else if (sectionKey === 'recentAnniversaries') gridEl.innerHTML = items.map(renderRecentAnniversaryCard).join('');
    else if (sectionKey === 'concerts') gridEl.innerHTML = items.map(({ event, artistName }) => renderConcertCard(event, artistName)).join('');
    else if (sectionKey === 'nmf') gridEl.innerHTML = items.map(renderNMFCard).join('');
    triggerPendingImgs(gridEl);
    return;
  }
  const normalized = _evNormalize(sectionKey, items);
  if (!normalized || !normalized.length) { gridEl.innerHTML = ''; gridEl.className = ''; return; }
  if (mode === 'table') _evTable(gridEl, normalized);
  else if (mode === 'carousel') _evCarousel(gridEl, normalized);
  else if (mode === 'list') _evList(gridEl, sectionKey, normalized);
}

// onclick attr for a card whose section uses a popup menu instead of a direct link
// (item.menuAction names the global function to call: _relShowMenu or _tmShowAlbumMenu).
function _evReleaseClickAttr(item) {
  return `onclick="${item.menuAction}(event,${esc(JSON.stringify(item.title))},${esc(JSON.stringify(item.artist))})"`;
}

// ＋ add-to-playlist button for a normalized event item, or nothing when the row
// already opens an action menu that carries the option (see _evNormalize).
function _evPlBtn(item, extraCls) {
  return item.pl ? dcPlBtnHtml(item.pl.kind, item.pl.title, item.pl.artist, item.pl.album, extraCls) : '';
}

// ── Section-level "save everything here to a playlist" ──────────────────────
// Each entry names the header button and says how to turn one raw section item
// into a track. Artist entries resolve to that artist's most recent play (one
// each, so a 30-artist birthday list makes a 30-track mix rather than 750);
// release entries resolve to the release's most recent play, falling back to
// the release itself when it has never been played.
const EV_PL_SECTIONS = {
  birthdays:           { label: 'Birthdays',           pick: it => _tmArtistLastSongs(it.artistName, 1)[0] },
  recentBirthdays:     { label: 'Recent Birthdays',    pick: it => _tmArtistLastSongs(it.artistName, 1)[0] },
  anniversaries:       { label: 'Anniversaries',       pick: it => _evPlRelease(it.title, it.artistName) },
  recentAnniversaries: { label: 'Recent Anniversaries', pick: it => _evPlRelease(it.title, it.artistName) },
  eventsRecent:        { label: 'Recent Releases',     pick: it => _evPlRelease(it.release?.title, it.artistName) },
  recent:              { label: 'Recent Releases',     pick: it => _evPlRelease(it.release?.title, it.artistName) }
};

function _evPlRelease(title, artist) {
  if (!title) return null;
  return _tmAlbumLastSongs(title, artist, 1)[0] || { title, artist: artist || '', album: title };
}

function evAddSectionToPlaylist(sectionKey) {
  const cfg = EV_PL_SECTIONS[sectionKey];
  if (!cfg) return;
  const items  = _evLastItems[sectionKey] || [];
  const tracks = items.map(cfg.pick).filter(Boolean);
  dcOpenPlaylistPicker(tracks, cfg.label, `${cfg.label} · ${_dcPlDateTag()}`);
}

// Hides the header button while a section has nothing in it — an empty section
// with a live "save these" button reads as broken.
function _evUpdatePlBtn(sectionKey) {
  if (!EV_PL_SECTIONS[sectionKey]) return;
  const btn = document.getElementById(sectionKey + 'PlBtn');
  if (btn) btn.style.display = (_evLastItems[sectionKey] || []).length ? '' : 'none';
}

function _evTable(gridEl, items) {
  gridEl.className = 'ev-table-wrap';
  // The ＋ gets its own trailing column rather than sharing the 42px image cell,
  // which would stack it under the thumbnail and double every row's height.
  // Sections whose rows open an action menu instead don't get the column at all.
  const hasPl = items.some(it => it.pl);
  const rows = items.map(item => {
    const evCell = item.menuAction
      ? `<span class="ev-tbl-link ev-tbl-link-btn" ${_evReleaseClickAttr(item)}>${esc(item.title)}</span>`
      : `<a class="ev-tbl-link" href="${esc(item.href)}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a>`;
    return `<tr><td class="ev-tbl-img">${_evImgTag(item, 'ev-tbl-thumb')}</td>` +
      `<td class="ev-tbl-ev">${evCell}</td>` +
      `<td class="ev-tbl-artist">${esc(item.artist)}</td>` +
      `<td class="ev-tbl-date">${esc(item.dateLabel)}</td>` +
      `<td class="ev-tbl-type">${esc(item.typeLabel)}</td>` +
      (hasPl ? `<td class="ev-tbl-pl">${_evPlBtn(item, 'dc-pl-add-sm')}</td>` : '') +
      `</tr>`;
  }).join('');
  gridEl.innerHTML = `<table class="ev-table"><thead><tr><th></th><th>Event</th><th>Artist</th><th>Date</th><th>Type</th>${hasPl ? '<th></th>' : ''}</tr></thead><tbody>${rows}</tbody></table>`;
  triggerPendingImgs(gridEl);
}

function _evCarousel(gridEl, items) {
  gridEl.className = 'ev-carousel-outer';
  const dur = Math.max(20, items.length * 3);
  /* `dupe` marks copy B of the deck. The reel is rendered twice so it can wrap
     onto an identical frame, and copy B is hidden when the deck is short enough
     to fit — see dcMountReel(), which drives the motion and the drag. */
  const card = (item, dupe) => {
    const tag = item.menuAction ? 'div' : 'a';
    const openAttrs = item.menuAction
      ? _evReleaseClickAttr(item)
      // draggable=false: a grab that starts on a link would otherwise become a
      // native link drag and take the pointer away from the reel mid-scroll.
      : `href="${esc(item.href)}" target="_blank" rel="noopener noreferrer" draggable="false"`;
    return `<${tag} class="ev-carousel-card${item.isToday ? ' event-today' : ''}${dupe ? ' dcreel-dupe' : ''}" ${openAttrs}>` +
      `${_evPlBtn(item, 'dc-pl-add-card')}` +
      `${_evImgTag(item, 'ev-carousel-img')}` +
      `<div class="ev-carousel-date">${esc(item.dateLabel)}</div>` +
      `<div class="ev-carousel-title">${esc(item.title)}</div>` +
      `<div class="ev-carousel-artist">${esc(item.artist)}</div>` +
      `<div class="ev-carousel-type">${esc(item.typeLabel)}</div></${tag}>`;
  };
  gridEl.innerHTML = `<div class="ev-carousel-track">${items.map(it => card(it, false)).join('')}${items.map(it => card(it, true)).join('')}</div>`;
  dcMountReel(gridEl, gridEl.firstElementChild, dur);
  triggerPendingImgs(gridEl);
}

function _evList(gridEl, sectionKey, items) {
  gridEl.className = 'ev-list-wrap';
  const sort = gridEl.dataset.evListSort || 'date';
  const sorted = [...items].sort((a, b) =>
    sort === 'artist' ? a.artistSort.localeCompare(b.artistSort)
    : typeof a.dateSort === 'string' ? a.dateSort.localeCompare(b.dateSort) : a.dateSort - b.dateSort
  );
  const rows = sorted.map(item => {
    const tag = item.menuAction ? 'div' : 'a';
    const openAttrs = item.menuAction
      ? _evReleaseClickAttr(item)
      : `href="${esc(item.href)}" target="_blank" rel="noopener noreferrer"`;
    // The row is a fixed 4-column grid; the extra child needs its own column or
    // it wraps onto a second line (see .ev-list-row--pl).
    return `<${tag} class="ev-list-row${item.pl ? ' ev-list-row--pl' : ''}${item.isToday ? ' event-today' : ''}" ${openAttrs}>` +
      `${_evPlBtn(item, 'dc-pl-add-sm')}` +
      `<span class="ev-list-date">${esc(item.dateLabel)}</span>` +
      `<span class="ev-list-title">${esc(item.title)}</span>` +
      `<span class="ev-list-artist">${esc(item.artist)}</span>` +
      `<span class="ev-list-type">${esc(item.typeLabel)}</span></${tag}>`;
  }).join('');
  gridEl.innerHTML =
    `<div class="ev-list-sort"><span class="ev-list-sort-lbl">Sort:</span>` +
    `<button class="ev-list-sort-btn${sort === 'date' ? ' active' : ''}" onclick="sortEvListView('${esc(sectionKey)}','date')">Date</button>` +
    `<button class="ev-list-sort-btn${sort === 'artist' ? ' active' : ''}" onclick="sortEvListView('${esc(sectionKey)}','artist')">Artist</button></div>` +
    `<div class="ev-list-items">${rows}</div>`;
}

function sortEvListView(sectionKey, sortBy) {
  const gridEl = document.getElementById(EV_GRID_IDS[sectionKey]);
  if (!gridEl) return;
  gridEl.dataset.evListSort = sortBy;
  _evReRenderSection(sectionKey);
}

function renderEventsPartial(birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent) {
  _eventsLastData = { birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent };
  const f = applyEventsTypeFilter(_eventsLastData);
  const sortFn = (a, b) => a.daysUntil - b.daysUntil;
  const sortFnAgo = (a, b) => a.daysAgo - b.daysAgo;
  if (f.birthdays.length) _evRenderSectionByKey('birthdays', [...f.birthdays].sort(sortFn));
  if (f.anniversaries.length) _evRenderSectionByKey('anniversaries', [...f.anniversaries].sort(sortFn));
  if (f.recentBirthdays.length) _evRenderSectionByKey('recentBirthdays', [...f.recentBirthdays].sort(sortFnAgo));
  if (f.recentAnniversaries.length) _evRenderSectionByKey('recentAnniversaries', [...f.recentAnniversaries].sort(sortFnAgo));
  if (f.eventsUpcoming.length) _evRenderSectionByKey('eventsUpcoming', sortUpcomingReleases([...f.eventsUpcoming]));
  if (f.eventsRecent.length) _evRenderSectionByKey('eventsRecent', sortRecentReleases([...f.eventsRecent]));
  renderEventsCalendar(f, eventsCalendarYear, eventsCalendarMonth);
}

async function fetchConcertsForArtist(artistName, apiKey) {
  const today = tzNow().toISOString().slice(0, 10) + 'T00:00:00Z';
  const url = `https://app.ticketmaster.com/discovery/v2/events.json?keyword=${encodeURIComponent(artistName)}&classificationName=music&apikey=${encodeURIComponent(apiKey)}&size=5&sort=date,asc&startDateTime=${today}`;
  try {
    const resp = await fetch(url);
    if (!resp.ok) return [];
    const data = await resp.json();
    return data._embedded?.events || [];
  } catch (e) { return []; }
}

function renderConcertCard(event, artistName) {
  const date = event.dates?.start?.localDate || '';
  const time = event.dates?.start?.localTime || '';
  const venue = event._embedded?.venues?.[0];
  const venueName = venue?.name || '';
  const city = venue?.city?.name || '';
  const stateCode = venue?.state?.stateCode || venue?.country?.countryCode || '';
  const location = [city, stateCode].filter(Boolean).join(', ');
  const url = event.url || `https://www.ticketmaster.com/search?q=${encodeURIComponent(artistName)}`;

  const today = tzNow();
  const showDate = date ? new Date(date + 'T12:00:00') : null;
  const daysUntil = showDate ? Math.round((showDate - today) / 86400000) : null;
  const isToday = daysUntil === 0;
  const countdownLabel = daysUntil === null ? '' : isToday ? 'TODAY' : `in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`;
  const isSoon = daysUntil !== null && daysUntil <= 7;
  const displayDate = date ? fmtDate(showDate) : '';
  const timeLabel = time ? ' · ' + time.slice(0, 5) : '';

  const imgHtml = `<img class="upcoming-card-img upcoming-card-img-pending" alt="" loading="lazy" data-artist="${esc(artistName)}" data-title="" data-sources="deezer-artist">`;
  return `<a class="upcoming-card${isToday ? ' event-today' : ''}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">
    ${imgHtml}
    <div class="upcoming-card-date${isToday || isSoon ? ' soon' : ''}">${esc(countdownLabel)}</div>
    <div class="upcoming-card-title">${esc(artistName)}</div>
    <div class="upcoming-card-artist">${esc(venueName)}${location ? ' · ' + esc(location) : ''}</div>
    <div class="upcoming-card-type">🎤 Live Show · ${esc(displayDate)}${esc(timeLabel)}</div>
  </a>`;
}

// ─── NMF History helpers ───────────────────────────────────────
function _mostRecentFriday(refDate) {
  const d = refDate || tzNow();
  const offset = (d.getDay() - 5 + 7) % 7;
  const friday = new Date(d);
  friday.setDate(d.getDate() - offset);
  return localDateStr(friday);
}

function _getNMFHistory() {
  try { return JSON.parse(localStorage.getItem(NMF_HISTORY_KEY) || '{}'); } catch (e) { return {}; }
}

// Returns true if a new week was added. Idempotent — won't overwrite an existing Friday entry.
function _saveNMFSnapshot(albums, ts) {
  const refDate = ts ? new Date(ts) : tzNow();
  const friday = _mostRecentFriday(refDate);
  const history = _getNMFHistory();
  if (history[friday]) return false;
  history[friday] = albums.map(a => ({
    id: a.id, title: a.title || '',
    artist: { name: a.artist?.name || '' },
    cover_medium: a.cover_medium || '',
    cover_big: a.cover_big || '',
    cover_xl: a.cover_xl || '',
    link: a.link || '',
    record_type: a.record_type || 'album',
    release_date: a.release_date || ''
  }));
  const keys = Object.keys(history).sort().reverse();
  keys.slice(NMF_HISTORY_MAX_WEEKS).forEach(k => delete history[k]);
  try { localStorage.setItem(NMF_HISTORY_KEY, JSON.stringify(history)); } catch (e) {}
  return true;
}

// ─── NMF Calendar ─────────────────────────────────────────────
function renderNMFCalendar() {
  const calGrid = document.getElementById('nmfCalGrid');
  const titleEl = document.getElementById('nmfCalTitle');
  if (!calGrid || !titleEl) return;

  const history = _getNMFHistory();
  const year = _nmfCalYear;
  const month = _nmfCalMonth;
  const todayStr = localDateStr(tzNow());
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  titleEl.innerHTML = `<span class="cal-title-month">${_CAL_MONTHS[month]}</span><span class="cal-title-year">${year}</span>`;

  let html = _CAL_DAYS.map(d => `<div class="cal-dow">${d}</div>`).join('');
  for (let i = 0; i < firstDow; i++) html += '<div class="cal-cell cal-cell-empty"></div>';

  for (let d = 1; d <= daysInMonth; d++) {
    const ds = _calDateStr(year, month, d);
    const isFriday = new Date(year, month, d).getDay() === 5;
    const hasData = isFriday && !!history[ds];
    const isSelected = ds === _nmfCalSelectedFriday;
    const isToday = ds === todayStr;
    const isPast = ds < todayStr;
    const count = hasData ? history[ds].length : 0;

    let cls = 'cal-cell';
    if (isToday) cls += ' cal-today';
    else if (isPast) cls += ' cal-past';
    if (isFriday) cls += ' nmf-cal-friday';
    if (hasData) cls += ' nmf-cal-has-data';
    if (isSelected) cls += ' nmf-cal-selected';

    const onclick = hasData ? ` onclick="selectNMFFriday('${ds}')"` : '';
    html += `<div class="${cls}"${onclick}>` +
      `<div class="cal-cell-num">${d}</div>` +
      (hasData ? `<div class="nmf-cal-pill">${count} release${count !== 1 ? 's' : ''}</div>` : '') +
      `</div>`;
  }

  calGrid.className = 'events-cal-grid';
  calGrid.innerHTML = html;
}

function selectNMFFriday(dateStr) {
  _nmfCalSelectedFriday = dateStr;
  const history = _getNMFHistory();
  const albums = history[dateStr] || [];
  const gridEl = document.getElementById('nmfGrid');
  if (gridEl) {
    gridEl.className = 'upcoming-grid';
    gridEl.innerHTML = albums.map(renderNMFCard).join('');
    triggerPendingImgs(gridEl);
  }
  renderNMFCalendar();
}

function nmfCalPrev() {
  _nmfCalMonth--;
  if (_nmfCalMonth < 0) { _nmfCalMonth = 11; _nmfCalYear--; }
  renderNMFCalendar();
}

function nmfCalNext() {
  _nmfCalMonth++;
  if (_nmfCalMonth > 11) { _nmfCalMonth = 0; _nmfCalYear++; }
  renderNMFCalendar();
}

function renderNMFCard(album) {
  const cover = album.cover_xl || album.cover_big || album.cover_medium || '';
  const typeMap = { album: '💿 Album', single: '🎵 Single', ep: '📀 EP' };
  const typeLabel = typeMap[album.record_type] || '🎶 Release';
  const href = album.link || `https://www.deezer.com/album/${album.id}`;
  const dateStr = album.release_date ? fmtDate(new Date(album.release_date + 'T00:00:00')) : '';
  const imgHtml = cover
    ? `<img class="upcoming-card-img" src="${esc(cover)}" onerror="releaseImgFallback(this)" alt="" loading="lazy" data-artist="${esc(album.artist?.name||'')}" data-title="${esc(album.title||'')}" data-sources="deezer">`
    : `<img class="upcoming-card-img upcoming-card-img-pending" alt="" loading="lazy" data-artist="${esc(album.artist?.name||'')}" data-title="${esc(album.title||'')}" data-sources="deezer">`;
  return `<a class="upcoming-card" href="${esc(href)}" target="_blank" rel="noopener noreferrer">
    ${imgHtml}
    <div class="upcoming-card-date">${esc(dateStr)}</div>
    <div class="upcoming-card-title">${esc(album.title || '')}</div>
    <div class="upcoming-card-artist">${esc(album.artist?.name || '')}</div>
    <div class="upcoming-card-type">${esc(typeLabel)}</div>
  </a>`;
}

function _renderNMF(albums, fromCache) {
  _nmfData = albums;
  if (albums.length) {
    let snapshotTs = Date.now();
    if (fromCache) {
      try { snapshotTs = JSON.parse(localStorage.getItem(NMF_CACHE_KEY)).ts; } catch (e) {}
    }
    const addedNew = _saveNMFSnapshot(albums, snapshotTs);
    if (addedNew && eventsViewModes['nmf'] === 'calendar') renderNMFCalendar();
  }
  const gridEl = document.getElementById('nmfGrid');
  const status = document.getElementById('nmfStatus');
  const refreshBtn = document.getElementById('nmfRefreshBtn');
  if (gridEl) {
    if (albums.length) {
      _evRenderSectionByKey('nmf', albums);
    } else {
      gridEl.className = 'upcoming-grid';
      gridEl.innerHTML = '<div class="upcoming-empty">No new releases found.</div>';
    }
  }
  if (refreshBtn) refreshBtn.style.display = 'block';
  if (status) {
    const ts = fromCache
      ? (() => { try { return new Date(JSON.parse(localStorage.getItem(NMF_CACHE_KEY)).ts).toLocaleString(); } catch (e) { return ''; } })()
      : new Date().toLocaleString();
    status.textContent = `${albums.length} release${albums.length !== 1 ? 's' : ''} · Deezer Editorial · ${ts}${fromCache ? ' (cached)' : ''}`;
  }
}

async function loadNMF(forceRefresh = false) {
  const status = document.getElementById('nmfStatus');
  const refreshBtn = document.getElementById('nmfRefreshBtn');

  if (!forceRefresh) {
    try {
      const cached = JSON.parse(localStorage.getItem(NMF_CACHE_KEY) || 'null');
      if (cached && Date.now() - cached.ts < NMF_CACHE_TTL && cached.albums && cached.albums.length) {
        _renderNMF(cached.albums, true);
        return;
      }
    } catch (e) {}
  }

  if (status) status.textContent = 'Fetching new releases from Deezer…';
  if (refreshBtn) refreshBtn.style.display = 'none';

  try {
    const [relR, tracksR] = await Promise.all([
      deezerFetch('editorial/0/releases?limit=100'),
      deezerFetch('chart/0/tracks?limit=100')
    ]);

    const albums = relR.ok ? ((await relR.json())?.data || []) : [];
    const tracks = tracksR.ok ? ((await tracksR.json())?.data || []) : [];

    // Add chart tracks released in the last 14 days that aren't already in the editorial list
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - 14);
    const cutoffStr = localDateStr(cutoff);
    const seenIds = new Set(albums.map(a => a.id));

    for (const track of tracks) {
      const alb = track.album;
      if (!alb || !alb.release_date || alb.release_date < cutoffStr) continue;
      if (seenIds.has(alb.id)) continue;
      seenIds.add(alb.id);
      albums.push({
        id: alb.id,
        title: alb.title || track.title,
        link: alb.link || `https://www.deezer.com/album/${alb.id}`,
        cover: alb.cover || '',
        cover_medium: alb.cover_medium || '',
        cover_big: alb.cover_big || '',
        cover_xl: alb.cover_xl || '',
        release_date: alb.release_date,
        record_type: 'single',
        artist: track.artist || {},
        type: 'album'
      });
    }

    albums.sort((a, b) => (b.release_date || '').localeCompare(a.release_date || ''));

    try { localStorage.setItem(NMF_CACHE_KEY, JSON.stringify({ ts: Date.now(), albums })); } catch (e) {}
    _renderNMF(albums, false);
  } catch (e) {
    if (status) status.textContent = 'Could not load new releases — try again later.';
    if (refreshBtn) refreshBtn.style.display = 'block';
  }
}

async function loadConcerts(forceRefresh = false) {
  _syncConcertsSectionVisibility();
  if (!allPlays.length) return;

  if (!forceRefresh) {
    try {
      const cached = JSON.parse(localStorage.getItem(CONCERTS_CACHE_KEY) || 'null');
      if (cached && Date.now() - cached.ts < CONCERTS_CACHE_TTL) {
        _renderConcerts(cached.shows, true);
        return;
      }
    } catch (e) {}
  }

  const artists = getTopNArtists(CONCERTS_ARTIST_LIMIT);
  const statusEl = document.getElementById('concertsStatus');
  const gridEl = document.getElementById('concertsGrid');
  const refreshEl = document.getElementById('concertsRefreshBtn');
  if (statusEl) statusEl.textContent = `Fetching shows for top ${artists.length} artists…`;
  if (gridEl) gridEl.innerHTML = '';
  if (refreshEl) refreshEl.style.display = 'none';

  const allShows = [];
  for (let i = 0; i < artists.length; i++) {
    const name = artists[i];
    if (statusEl) statusEl.textContent = `Fetching shows (${i + 1}/${artists.length}): ${name}`;
    const events = await fetchConcertsForArtist(name, tmApiKey);
    for (const ev of events) allShows.push({ event: ev, artistName: name });
  }

  allShows.sort((a, b) =>
    (a.event.dates?.start?.localDate || '').localeCompare(b.event.dates?.start?.localDate || ''));

  try {
    localStorage.setItem(CONCERTS_CACHE_KEY, JSON.stringify({ ts: Date.now(), shows: allShows }));
  } catch (e) {}

  _renderConcerts(allShows, false);
}

function _renderConcerts(shows, fromCache) {
  _concertsData = shows;
  _syncConcertsSectionVisibility();
  const grid = document.getElementById('concertsGrid');
  const status = document.getElementById('concertsStatus');
  const refreshBtn = document.getElementById('concertsRefreshBtn');

  if (grid) {
    if (shows.length) {
      _evRenderSectionByKey('concerts', shows);
    } else {
      grid.className = 'upcoming-grid';
      grid.innerHTML = `<div class="upcoming-empty">No upcoming shows found for your top ${CONCERTS_ARTIST_LIMIT} artists.</div>`;
    }
  }
  if (refreshBtn) refreshBtn.style.display = 'block';
  if (status) {
    const cacheNote = fromCache ? ' (cached)' : '';
    const ts = fromCache
      ? (() => { try { return new Date(JSON.parse(localStorage.getItem(CONCERTS_CACHE_KEY)).ts).toLocaleString(); } catch (e) { return ''; } })()
      : new Date().toLocaleString();
    status.textContent = `${shows.length} show${shows.length !== 1 ? 's' : ''} · top ${CONCERTS_ARTIST_LIMIT} artists · ${ts}${cacheNote}`;
  }
  if (_eventsCalendarData) renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);
}

function _eventsFromCache(cached) {
  renderEventsResults(
    cached.birthdays, cached.anniversaries,
    cached.recentBirthdays || [], cached.recentAnniversaries || [],
    cached.eventsUpcoming || [], cached.eventsRecent || [],
    cached.artists, true
  );
}

function _isCacheValid(cached) {
  return cached && cached.ver === EVENTS_CACHE_VER && Date.now() - cached.ts < EVENTS_CACHE_TTL && cached.limit === eventsArtistLimit && cached.eventsUpcoming;
}

async function loadEvents(forceRefresh = false) {
  if (!allPlays.length) return;

  if (!forceRefresh) {
    // 1. Check localStorage (instant, same device)
    try {
      const cached = JSON.parse(localStorage.getItem(EVENTS_CACHE_KEY) || 'null');
      if (_isCacheValid(cached)) { _eventsFromCache(cached); return; }
    } catch (e) {}

    // 2. Check Firestore (cross-device, cross-login)
    if (typeof dcLoadEventsCache === 'function') {
      const statusEl2 = document.getElementById('eventsStatus');
      if (statusEl2) statusEl2.textContent = 'Loading events…';
      try {
        const fsCached = await dcLoadEventsCache();
        if (_isCacheValid(fsCached)) {
          try { localStorage.setItem(EVENTS_CACHE_KEY, JSON.stringify(fsCached)); } catch (e) {}
          _eventsFromCache(fsCached);
          return;
        }
      } catch (e) {}
    }
  }

  const artists = getTopNArtists(eventsArtistLimit);
  const statusEl = document.getElementById('eventsStatus');
  const refreshEl = document.getElementById('eventsRefreshBtn');
  if (!statusEl) return;

  ['birthdaysGrid', 'anniversariesGrid', 'eventsRecentBirthdaysGrid', 'eventsRecentAnniversariesGrid', 'eventsUpcomingGrid', 'eventsRecentGrid'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = '';
  });
  if (refreshEl) refreshEl.style.display = 'none';
  statusEl.textContent = `Fetching events for top ${artists.length} artists…`;

  const birthdays = [];
  const anniversaries = [];
  const recentBirthdays = [];
  const recentAnniversaries = [];
  const eventsUpcoming = [];
  const eventsRecent = [];

  for (let i = 0; i < artists.length; i++) {
    const name = artists[i];
    statusEl.textContent = `Fetching (${i + 1}/${artists.length}): ${name}`;

    const mbid = await searchArtistMBID(name);

    // Birthday: MusicBrainz (from search result cache) → TheAudioDB → Wikidata
    let birthday = _mbBirthdayCache[name] || null;
    if (!birthday) birthday = await fetchBirthdayTADB(name);
    if (!birthday) birthday = await fetchBirthdayWikidata(name);

    if (birthday && birthday.length >= 10) {
      const mmdd = birthday.slice(5, 10);
      const days = daysUntilNextOccurrence(mmdd, EVENTS_WINDOW_DAYS);
      if (days !== null) birthdays.push({ artistName: name, dateStr: birthday, mmdd, daysUntil: days });
      const daysAgo = daysSinceLastOccurrence(mmdd, EVENTS_WINDOW_DAYS);
      if (daysAgo !== null) recentBirthdays.push({ artistName: name, dateStr: birthday, mmdd, daysAgo });
    }

    // Album anniversaries + upcoming/recent releases from shared MB releases cache
    if (mbid) {
      const groups = await fetchAllReleasesRaw(mbid);
      const currentYear = tzNow().getFullYear();
      for (const g of groups) {
        const type = g['primary-type'] || 'Release';
        const validReleases = (g.releases || []).filter(r => r.date && r.date.length >= 10 && !r.date.slice(5, 10).includes('00'));
        let entryDate = null;
        if (validReleases.length > 0) {
          const mmddCounts = {};
          for (const r of validReleases) {
            const md = r.date.slice(5, 10);
            mmddCounts[md] = (mmddCounts[md] || 0) + 1;
          }
          const modeMmdd = Object.entries(mmddCounts).sort((a, b) => b[1] - a[1])[0][0];
          entryDate = validReleases.filter(r => r.date.slice(5, 10) === modeMmdd).sort((a, b) => a.date.localeCompare(b.date))[0].date;
        } else if (g['first-release-date'] && g['first-release-date'].length >= 10) {
          entryDate = g['first-release-date'];
        }
        const entries = entryDate ? [{ date: entryDate, title: g.title }] : [];
        for (const { date, title } of entries) {
          const mmdd = date.slice(5, 10);
          if (mmdd.includes('00')) continue;
          const releaseYear = parseInt(date.slice(0, 4));
          if (releaseYear >= currentYear) continue;
          const years = currentYear - releaseYear;
          const days = daysUntilNextOccurrence(mmdd, EVENTS_WINDOW_DAYS);
          if (days !== null) {
            anniversaries.push({ artistName: name, title, type, releaseDate: date, years, mmdd, daysUntil: days, mbid: g.id });
          }
          const daysAgo = daysSinceLastOccurrence(mmdd, EVENTS_WINDOW_DAYS);
          if (daysAgo !== null) {
            recentAnniversaries.push({ artistName: name, title, type, releaseDate: date, years, mmdd, daysAgo, mbid: g.id });
          }
        }
      }

      const upcomingRels = await fetchReleasesForMBID(mbid);
      for (const r of upcomingRels) eventsUpcoming.push({ release: r, artistName: name });
      const recentRels = await fetchRecentReleasesForMBID(mbid);
      for (const r of recentRels) eventsRecent.push({ release: r, artistName: name });
    }

    if (i % 5 === 4 || i === artists.length - 1) renderEventsPartial(birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent);
  }

  const cacheData = { ver: EVENTS_CACHE_VER, ts: Date.now(), limit: eventsArtistLimit, birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent, artists };
  try { localStorage.setItem(EVENTS_CACHE_KEY, JSON.stringify(cacheData)); } catch (e) {}
  if (typeof dcSaveEventsCache === 'function') dcSaveEventsCache(cacheData);

  renderEventsResults(birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent, artists, false);
}

function renderEventsResults(birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent, artists, fromCache) {
  _eventsRawData = { birthdays, anniversaries, recentBirthdays, recentAnniversaries, eventsUpcoming, eventsRecent };
  _eventsArtists = artists;
  _renderEventsFromRaw(_eventsRawData, artists, fromCache);
}

function _renderEventsFromRaw(raw, artists, fromCache) {
  _eventsLastData = raw;
  const f = applyEventsTypeFilter(raw);
  const statusEl = document.getElementById('eventsStatus');
  const refreshEl = document.getElementById('eventsRefreshBtn');
  const sortFn = (a, b) => a.daysUntil - b.daysUntil;
  const sortFnAgo = (a, b) => a.daysAgo - b.daysAgo;
  const emptyGrid = (key, msg) => {
    const el = document.getElementById(EV_GRID_IDS[key]);
    if (el) { el.className = 'upcoming-grid'; el.innerHTML = `<div class="upcoming-empty">${msg}</div>`; }
  };
  const renderSec = (key, items, emptyMsg) => items.length
    ? _evRenderSectionByKey(key, items)
    : emptyGrid(key, emptyMsg);

  renderSec('birthdays', [...f.birthdays].sort(sortFn),
    `No birthdays found in the next ${EVENTS_WINDOW_DAYS} days for your top ${artists.length} artists.`);
  renderSec('anniversaries', [...f.anniversaries].sort(sortFn),
    `No anniversaries found in the next ${EVENTS_WINDOW_DAYS} days for your top ${artists.length} artists.`);
  renderSec('recentBirthdays', [...f.recentBirthdays].sort(sortFnAgo),
    `No birthdays found in the past ${EVENTS_WINDOW_DAYS} days for your top ${artists.length} artists.`);
  renderSec('recentAnniversaries', [...f.recentAnniversaries].sort(sortFnAgo),
    `No anniversaries found in the past ${EVENTS_WINDOW_DAYS} days for your top ${artists.length} artists.`);
  renderSec('eventsUpcoming', sortUpcomingReleases([...f.eventsUpcoming]),
    `No upcoming releases in the next 90 days for your top ${artists.length} artists.`);
  renderSec('eventsRecent', sortRecentReleases([...f.eventsRecent]),
    `No recent releases in the past 6 months for your top ${artists.length} artists.`);

  _eventsCalendarData = f;
  renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);

  const cacheNote = fromCache ? ' (cached)' : '';
  const ts = fromCache
    ? (() => { try { return new Date(JSON.parse(localStorage.getItem(EVENTS_CACHE_KEY)).ts).toLocaleString(); } catch (e) { return ''; } })()
    : new Date().toLocaleString();
  if (statusEl) statusEl.textContent = `${raw.birthdays.length} birthdays · ${raw.anniversaries.length} anniversaries · ${raw.eventsUpcoming.length} upcoming · ${raw.eventsRecent.length} recent · top ${artists.length} artists · ${ts}${cacheNote}`;
  if (refreshEl) refreshEl.style.display = 'block';

  const sel = document.getElementById('eventsLimitSelect');
  if (sel) sel.value = eventsArtistLimit;

  _syncEventsTypeFilter();
}

function eventsLimitChanged(val) {
  const newLimit = parseInt(val) || 50;
  if (newLimit === eventsArtistLimit) return;
  eventsArtistLimit = newLimit;
  localStorage.setItem('dc_events_artist_limit', newLimit);
  localStorage.removeItem(EVENTS_CACHE_KEY);
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  loadEvents(true);
}

// ── FILE IMPORT (Spotify ZIP, Deezer XLSX, CSV) ────────────────────

function readFileAsText(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = e => resolve(e.target.result);
    r.onerror = () => reject(new Error('Could not read file'));
    r.readAsText(file, 'utf-8');
  });
}

function readFileAsBuffer(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = e => resolve(e.target.result);
    r.onerror = () => reject(new Error('Could not read file'));
    r.readAsArrayBuffer(file);
  });
}

// Flexible datetime parser for imported data
const _IMPORT_ES_MONTHS = {ene:0,feb:1,mar:2,abr:3,may:4,jun:5,jul:6,ago:7,sep:8,oct:9,nov:10,dic:11};
function parseDtStrImport(s) {
  if (!s) return null;
  s = s.trim();
  if (/^\d{10,}$/.test(s)) return new Date(parseInt(s) * 1000);
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    const d = new Date(s.includes('T') ? s : s.replace(' ', 'T') + (s.length <= 10 ? 'T00:00:00Z' : 'Z'));
    if (!isNaN(d)) return d;
  }
  const mES = s.match(/^(\d{1,2})\/([a-zA-Z]{3})\/(\d{4})\s+(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (mES) {
    const mon = _IMPORT_ES_MONTHS[mES[2].toLowerCase()];
    if (mon !== undefined) {
      const d = new Date(Date.UTC(+mES[3], mon, +mES[1], +mES[4], +mES[5], +(mES[6]||0)));
      if (!isNaN(d)) return d;
    }
  }
  const d = new Date(s);
  return isNaN(d) ? null : d;
}

// ─── LAZY-LOADED CDN LIBRARIES ─────────────────────────────────
// html2canvas (~180 KB), SheetJS (~900 KB) and JSZip (~100 KB) used to be
// render-blocking <script> tags in index.html's <head>, yet they are only needed
// for image exports and Excel/ZIP file imports. Loading them on first use means
// first-time visitors never download ~1.2 MB of JS just to see their charts.
const LAZY_LIB_SRC = {
  html2canvas: 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js',
  XLSX:        'https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js',
  JSZip:       'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js',
};
const _lazyLibLoads = {};
function ensureLazyLib(name) {
  if (!_lazyLibLoads[name]) {
    _lazyLibLoads[name] = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = LAZY_LIB_SRC[name];
      s.onload = () => resolve(window[name]);
      // Drop the cached promise on failure so the next attempt retries the CDN
      s.onerror = () => { delete _lazyLibLoads[name]; reject(new Error(name + ' failed to load')); };
      document.head.appendChild(s);
    });
  }
  return _lazyLibLoads[name];
}
// Shim so the existing bare html2canvas(...) call sites keep working unchanged:
// the first call pulls the real library — whose UMD global replaces this shim on
// load — and forwards the call; later calls hit the real library directly.
window.html2canvas = (...args) => ensureLazyLib('html2canvas').then(lib => lib(...args));

async function parseSpotifyZip(file) {
  await ensureLazyLib('JSZip'); // fetched on demand — not shipped with first paint
  const buf = await readFileAsBuffer(file);
  const zip = await window.JSZip.loadAsync(buf);
  const scrobbles = [];
  for (const [name, entry] of Object.entries(zip.files)) {
    const lower = name.toLowerCase();
    if (!lower.endsWith('.json')) continue;
    if (!['streaming', 'endsong', 'audio'].some(k => lower.includes(k))) continue;
    let data;
    try { data = JSON.parse(await entry.async('string')); } catch { continue; }
    if (!Array.isArray(data)) continue;
    for (const item of data) {
      if (!item || typeof item !== 'object') continue;
      // Spotify ships two shapes and this guard has to read both. The extended
      // streaming history uses snake_case (ms_played); the plain "Account data"
      // export uses camelCase (msPlayed) alongside endTime/trackName/artistName.
      // Reading only ms_played meant every account-data row scored 0 ms and was
      // dropped as a skip — the endTime/trackName fallbacks below could never
      // fire, so that whole export type silently imported nothing.
      if (parseInt(item.ms_played ?? item.msPlayed ?? 0) < 30000) continue;
      const dt = parseDtStrImport(item.ts || item.endTime || '');
      if (!dt) continue;
      const track  = item.master_metadata_track_name || item.trackName || '';
      const artist = item.master_metadata_album_artist_name || item.artistName || '';
      if (!track || !artist) continue;
      scrobbles.push({ artist, album: item.master_metadata_album_album_name || '—', track, date: dt });
    }
  }
  return scrobbles;
}

async function parseDeezerXlsx(file) {
  await ensureLazyLib('XLSX'); // fetched on demand — not shipped with first paint
  const buf = await readFileAsBuffer(file);
  const wb = window.XLSX.read(buf, { type: 'array', cellDates: true });
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = window.XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, dateNF: 'yyyy-mm-dd HH:mm:ss' });
  if (rows.length < 2) return [];
  const header = rows[0].map(h => String(h || '').toLowerCase().trim());
  const col = {};
  header.forEach((h, i) => {
    if (['song','title','track','titre','piste'].some(x => h.includes(x))) { if (col.track == null) col.track = i; }
    else if (['artist','artiste'].some(x => h.includes(x)))                { if (col.artist == null) col.artist = i; }
    else if (h.includes('album'))                                           { if (col.album == null) col.album = i; }
    else if (['date','time','listened','ecoute'].some(x => h.includes(x))) { if (col.ts == null) col.ts = i; }
  });
  const scrobbles = [];
  for (const row of rows.slice(1)) {
    const get = k => col[k] != null ? String(row[col[k]] || '') : '';
    const dt = parseDtStrImport(get('ts'));
    if (!dt) continue;
    const artist = get('artist'), track = get('track');
    if (!artist || !track) continue;
    scrobbles.push({ artist, album: get('album') || '—', track, date: dt });
  }
  return scrobbles;
}

async function importFileData(file) {
  if (!file) return;
  const statusEl = document.getElementById('srcFileStatus');
  if (statusEl) statusEl.textContent = `Parsing ${file.name}…`;
  try {
    const fname = file.name.toLowerCase();
    if (fname.endsWith('.csv')) {
      // CSV: delegate to existing parseCsv which sets allPlays and calls finalizeLoad
      const text = await readFileAsText(file);
      parseCsv(text, false);
      if (!allPlays.length) { if (statusEl) statusEl.textContent = 'No valid records found.'; return; }
      const compact = allPlays.map(p => [p.title, p.artist, p.album, Math.floor(p.date.getTime()/1000)]);
      await saveToIDB(IDB_FILE_KEY, { ts: Date.now(), data: compact });
      localStorage.setItem('dc_source', 'file');
      if (statusEl) statusEl.textContent = `✓ ${allPlays.length.toLocaleString()} plays loaded`;
      closeSourceModal();
      return;
    }
    let plays = [];
    if (fname.endsWith('.zip')) {
      const scrobbles = await parseSpotifyZip(file);
      plays = scrobbles.map(s => {
        const ar = s.artist || '';
        return { title: s.track || '', artist: ar, artists: splitArtists(ar), album: s.album || '—', date: s.date };
      });
    } else if (fname.endsWith('.xlsx') || fname.endsWith('.xls')) {
      const scrobbles = await parseDeezerXlsx(file);
      plays = scrobbles.map(s => {
        const ar = s.artist || '';
        return { title: s.track || '', artist: ar, artists: splitArtists(ar), album: s.album || '—', date: s.date };
      });
    } else {
      if (statusEl) statusEl.textContent = 'Unsupported file type.';
      return;
    }
    plays = plays.filter(p => p.title && p.artist && p.date && !isNaN(p.date));
    if (!plays.length) { if (statusEl) statusEl.textContent = 'No valid records found.'; return; }
    plays.sort((a, b) => b.date - a.date);
    allPlays = plays;
    const compact = allPlays.map(p => [p.title, p.artist, p.album, Math.floor(p.date.getTime()/1000)]);
    await saveToIDB(IDB_FILE_KEY, { ts: Date.now(), data: compact });
    localStorage.setItem('dc_source', 'file');
    if (statusEl) statusEl.textContent = `✓ ${allPlays.length.toLocaleString()} plays loaded`;
    closeSourceModal();
    setSyncStatus(`✓ ${allPlays.length.toLocaleString()} plays loaded from ${file.name}`, 'ok');
    finalizeLoad();
  } catch (e) {
    if (statusEl) statusEl.textContent = `Error: ${e.message}`;
  }
}

let _srcFileUploadReady = false;

function initSrcFileUpload() {
  const zone = document.getElementById('srcFileDrop');
  const input = document.getElementById('srcFileInput');
  if (!zone || !input) return;
  // Called on every modal open — without this guard the listeners stack up and
  // the file picker opens once per time the modal has ever been opened.
  if (_srcFileUploadReady) return;
  _srcFileUploadReady = true;
  input.addEventListener('change', () => { if (input.files[0]) importFileData(input.files[0]); input.value = ''; });
  zone.addEventListener('click', () => input.click());
  zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('dragover'); });
  zone.addEventListener('dragleave', () => zone.classList.remove('dragover'));
  zone.addEventListener('drop', e => {
    e.preventDefault(); zone.classList.remove('dragover');
    if (e.dataTransfer.files[0]) importFileData(e.dataTransfer.files[0]);
  });
}

// ─── YOUTUBE PLAYER ───────────────────────────────────────────────────────────

let _ytPlayer          = null;
let _ytApiReady        = false;
let _ytPendingVideo    = null;
let _ytScrobbleTimer   = null;
let _ytCurrentTrack    = null;
let _ytScrobbled       = false;
let _ytActiveBtn       = null;
let _ytCurrentVideoId  = null;
let _ytQueue           = [];
let _ytQueueToastTimer = null;
let _ytDragInitialized   = false;
let _ytExpandSize        = 0;
let _ytEmbedRetry        = 0;
let _ytQueueDragSrc      = null;
let _ytHistory           = [];
let _ytHistoryRecorded   = false;
let _ytVolume            = 80;
let _ytMuted             = false;
let _ytPreMuteVol        = 80;
let _ytScrobbleInterval  = null;
let _ytPlayStart         = null;
let _ytRepeat            = parseInt(localStorage.getItem('yt-repeat') || '0'); // 0=off,1=one,2=all
let _ytSeekInterval      = null;
let _ytSeekDragging      = false;
let _ytSleepRemaining    = 0;
let _ytSleepInterval     = null;
let _ytSpeedIdx          = (() => { try { return Math.min(4, Math.max(0, parseInt(localStorage.getItem('yt-speed-idx') || '1'))); } catch(e) { return 1; } })();
let _ytSpeed             = [0.75, 1, 1.25, 1.5, 2][_ytSpeedIdx] || 1;
let _ytCrossfade         = parseInt(localStorage.getItem('yt-crossfade') || '0');
let _ytCrossfadeRamp     = null;
let _ytCrossfadingOut    = false;
let _ytNewTrackFade      = false;
let _ytScrobbleThreshold = localStorage.getItem('yt-scrobble-threshold') || '30s';
let _ytPlaylists         = {};
let _ytPlaylistModified  = {}; // name -> last-modified timestamp
let _ytDeletedPlaylists  = {}; // name -> deletion timestamp (tombstone so a delete on one device isn't undone by a stale copy on another — see _ytMergePlaylists)
let _ytPipWindow         = null;
let _ytPipUpdate         = null;
let _ytLyricsCache       = {};
// True when Chrome auto-paused the iframe because the page went to background
let _ytHiddenWhilePlaying  = false;
let _ytHiddenResumeIv      = null; // interval that keeps re-asserting playback while tab is hidden

// ── Queue history / played-track tracking ──────────────────────────────────────
let _ytQueuePlayed       = [];    // items already played from the queue; shown dimmed above current
let _ytCurrentFromQueue  = null;  // the queue item currently playing (null = playing from chart)
let _ytAdvancingQueue    = false; // flag: openYtPlayer was called by _ytAdvanceFromQueue, not user

// ── Queue management helpers ────────────────────────────────────────────────────
let _ytLastRemovedItem   = null;  // { item, idx } saved for one-step undo
let _ytUndoTimer         = null;  // auto-clear handle for undo toast
let _ytQueueMultiSelect  = false; // whether multi-select mode is active
let _ytQueueSelected     = new Set(); // set of selected queue indices
let _ytQueueLastChecked  = null;  // last-checked index for shift-range multi-select

// ── Queue panel visibility (#11 badge / #12 empty state) ──────────────────────
let _ytQueueHidden    = false; // user has manually hidden the queue panel
let _ytQueuePrevCount = 0;     // tracks previous total to detect first-add auto-open

// ── Touch drag (long-press to reorder on mobile, feature #19) ──────────────────
let _ytQueueTouchTimer = null;  // long-press countdown
let _ytTouchDragSrc    = null;  // item being dragged by touch
let _ytTouchDragClone  = null;  // ghost element shown during touch drag
let _ytTouchDragOver   = null;  // current drop target during touch drag

// Called automatically by the YouTube IFrame API script once it loads.
function onYouTubeIframeAPIReady() {
  _ytApiReady = true;
  if (_ytPendingVideo) {
    _ytLoadVideo(_ytPendingVideo);
    _ytPendingVideo = null;
  }
}

function _ytInjectApi() {
  if (document.getElementById('yt-iframe-api')) return;
  const s = document.createElement('script');
  s.id  = 'yt-iframe-api';
  s.src = 'https://www.youtube.com/iframe_api';
  document.head.appendChild(s);
}

// Fire-and-forget ping to wake Render's free-tier backend before the user clicks play.
// Uses a 10-minute cooldown so page navigation doesn't spam the endpoint.
let _ytLastPrewarm = 0;
function _ytPrewarmBackend() {
  const now = Date.now();
  if (now - _ytLastPrewarm < 10 * 60 * 1000) return;
  _ytLastPrewarm = now;
  fetch(`${BACKEND_API}/health`).catch(() => {});
}

function ytPlayFromBtn(btn) {
  const playerEl = document.getElementById('ytMiniPlayer');
  if (_ytCurrentTrack && playerEl && playerEl.style.display !== 'none') {
    _ytShowQueueToast(btn.dataset.title, btn.dataset.artist, btn.dataset.album, btn);
  } else {
    openYtPlayer(btn.dataset.title, btn.dataset.artist, btn.dataset.album, btn);
  }
}

function _ytPlayOrQueue(title, artist, album) {
  const playerEl = document.getElementById('ytMiniPlayer');
  if (_ytCurrentTrack && playerEl && playerEl.style.display !== 'none') {
    _ytShowQueueToast(title, artist, album, null);
  } else {
    openYtPlayer(title, artist, album, null);
  }
}

function _ytStreakPlay(title, artist) {
  const playerEl = document.getElementById('ytMiniPlayer');
  if (_ytCurrentTrack && playerEl && playerEl.style.display !== 'none') {
    _ytQueue.push({ title, artist, album: '', btn: null });
    _ytUpdateQueueDisplay(); _ytSaveQueue();
    const statusEl = document.getElementById('ytMiniStatus');
    if (statusEl) { statusEl.textContent = `"${title}" added to queue`; statusEl.className = 'yt-mini-status ok'; setTimeout(() => { if (statusEl.textContent.includes('added to queue')) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2500); }
  } else {
    openYtPlayer(title, artist, '', null);
  }
}

function openYtPlayer(title, artist, album, btn) {
  if (_ytActiveBtn) _ytActiveBtn.classList.remove('yt-btn-loading', 'yt-btn-playing');
  document.querySelectorAll('.yt-now-playing-row').forEach(r => r.classList.remove('yt-now-playing-row'));
  _ytStopScrobbleRing();
  // When a song is started directly by the user (not by auto-advancing the queue),
  // reset played history so the queue shows a clean upcoming list.
  if (!_ytAdvancingQueue) {
    _ytQueuePlayed      = [];
    _ytCurrentFromQueue = null;
    _ytQueueMultiSelect = false;
    _ytQueueSelected    = new Set();
    _ytUpdateQueueDisplay();
  }
  _ytAdvancingQueue = false; // always reset the flag
  // Treat '—' placeholder as empty so it isn't sent as an album name when scrobbling
  album = (album && album !== '—') ? album : '';
  _ytCurrentTrack    = { title, artist, album };
  try { localStorage.setItem('yt-player-current', JSON.stringify({ title, artist, album })); } catch(e) {}
  _ytCurrentVideoId  = null;
  _ytScrobbled       = false;
  _ytHistoryRecorded = false;
  _ytEmbedRetry      = 0;
  _ytCrossfadingOut  = false;
  if (_ytCrossfade > 0) _ytNewTrackFade = true;
  clearTimeout(_ytScrobbleTimer);
  _ytActiveBtn = btn || null;
  if (_ytActiveBtn) {
    _ytActiveBtn.classList.add('yt-btn-loading');
    const row = _ytActiveBtn.closest('tr');
    if (row) row.classList.add('yt-now-playing-row');
  }
  const player = document.getElementById('ytMiniPlayer');
  player.style.display = '';
  document.getElementById('ytMiniTitle').textContent  = title;
  document.getElementById('ytMiniArtist').textContent = artist;
  const statusEl = document.getElementById('ytMiniStatus');
  statusEl.textContent = 'Searching…';
  statusEl.className   = 'yt-mini-status';
  const seekWrap = document.getElementById('ytSeekBarWrap');
  if (seekWrap) seekWrap.style.display = 'none';
  const seekBar = document.getElementById('ytSeekBar');
  if (seekBar) seekBar.value = 0;
  _ytStopSeekUpdate();
  const pauseBtn = document.getElementById('ytMiniPauseBtn');
  if (pauseBtn) { pauseBtn.innerHTML = _YT_IC.pause; pauseBtn.title = 'Pause'; }
  if (!_ytDragInitialized) { _ytDragInitialized = true; _ytInitDrag(); }
  _ytLoadVolume();
  requestAnimationFrame(_ytClampToViewport);
  _ytInjectApi();
  _ytSearch(artist, title);
  // If album is unknown, first try the site's own play data, then fall back to Last.fm.
  if (!album) {
    const dataAlbum = _lookupAlbumFromData(title, artist);
    if (dataAlbum) {
      _ytCurrentTrack.album = dataAlbum;
    } else {
      _ytFetchAlbum(title, artist);
    }
  }
}

// Looks up the album for the currently playing track via Last.fm track.getInfo.
// Updates _ytCurrentTrack.album if the same track is still playing when it resolves.
async function _ytFetchAlbum(title, artist) {
  try {
    // Use only the primary artist for the lookup — feat. artists cause track.getInfo to fail
    const lookupArtist = _primaryArtist(artist);
    const url = lfmUrl('track.getInfo', { track: title, artist: lookupArtist, autocorrect: 1 });
    const r = await fetch(url);
    const d = await r.json();
    const albumName = d?.track?.album?.title;
    // Only update if we're still on the same track and haven't already scrobbled
    if (albumName && _ytCurrentTrack && !_ytScrobbled &&
        _ytCurrentTrack.title === title && _ytCurrentTrack.artist === artist) {
      _ytCurrentTrack.album = albumName;
    }
  } catch(e) {
    // Silently fail — scrobble will just go through without album
  }
}

async function _ytSearch(artist, title, overrideQuery) {
  const query = overrideQuery || (artist + ' ' + title + ' official audio');
  const statusEl = document.getElementById('ytMiniStatus');
  // Render free tier cold starts take up to ~30s; 5 retries × 6s = 30s total wait
  const MAX_RETRIES = 5;
  const RETRY_DELAY_MS = 6000;
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      const res  = await fetch(`${BACKEND_API}/api/youtube/search?q=${encodeURIComponent(query)}`);
      if (res.status === 502 || res.status === 503) {
        if (attempt < MAX_RETRIES) {
          if (statusEl) { statusEl.textContent = 'Waking up server…'; statusEl.className = 'yt-mini-status'; }
          await new Promise(r => setTimeout(r, RETRY_DELAY_MS));
          continue;
        }
        throw new Error('Server unavailable');
      }
      const data = await res.json();
      if (data.error) throw new Error(data.error);
      const videoId = data.videoId;
      if (!videoId) throw new Error('No results found');
      _ytCurrentVideoId = videoId;
      _ytUpdateThumb();
      if ((data.videoTitle || data.title) && _ytActiveBtn) {
        _ytActiveBtn.title = '▶ ' + (data.videoTitle || data.title);
      }
      if (statusEl) { statusEl.textContent = ''; }
      if (_ytApiReady) {
        _ytLoadVideo(videoId);
      } else {
        _ytPendingVideo = videoId;
      }
      return;
    } catch (e) {
      if (attempt < MAX_RETRIES && (e.message === 'Server unavailable' || e.name === 'TypeError')) {
        if (statusEl) { statusEl.textContent = 'Waking up server…'; statusEl.className = 'yt-mini-status'; }
        await new Promise(r => setTimeout(r, RETRY_DELAY_MS));
        continue;
      }
      if (_ytActiveBtn) _ytActiveBtn.classList.remove('yt-btn-loading', 'yt-btn-playing');
      if (statusEl) {
        const skipPart = _ytQueue.length > 0 ? ` — <button class="yt-err-open-btn" onclick="_ytSkip()">skip ⏭</button>` : '';
        statusEl.innerHTML = `Not found — <button class="yt-err-open-btn" onclick="_ytOpenInYT()">search YouTube ↗</button>${skipPart}`;
        statusEl.className = 'yt-mini-status err';
      }
      return;
    }
  }
}

function _ytLoadVideo(videoId) {
  if (_ytPlayer) {
    _ytPlayer.loadVideoById(videoId);
  } else {
    _ytPlayer = new YT.Player('yt-player-frame', {
      height: '90',
      width: '160',
      videoId,
      playerVars: { autoplay: 1, playsinline: 1, rel: 0 },
      events: { onStateChange: _ytOnState, onError: _ytOnError }
    });
  }
}

function _ytOnState(event) {
  const pauseBtn = document.getElementById('ytMiniPauseBtn');
  if (event.data === YT.PlayerState.PLAYING) {
    clearTimeout(_ytScrobbleTimer);
    if (!_ytScrobbled) {
      if (_ytScrobbleThreshold === '30s') {
        _ytScrobbleTimer = setTimeout(_ytScrobble, 30000);
        _ytStartScrobbleRing();
      }
    }
    _ytStartSeekUpdate();
    _ytApplySpeed();
    if (_ytCrossfade > 0 && _ytNewTrackFade) { _ytNewTrackFade = false; _ytStartFadeIn(); }
    if (pauseBtn) { pauseBtn.innerHTML = _YT_IC.pause; pauseBtn.title = 'Pause'; }
    if (_ytActiveBtn) { _ytActiveBtn.classList.remove('yt-btn-loading'); _ytActiveBtn.classList.add('yt-btn-playing'); }
    if (!_ytHistoryRecorded && _ytCurrentTrack) {
      _ytHistoryRecorded = true;
      _ytRecordHistory(_ytCurrentTrack.title, _ytCurrentTrack.artist, _ytCurrentTrack.album);
    }
    if (_ytPipUpdate) _ytPipUpdate();
    // Register with OS for lock screen controls and background audio permission
    // Only clear the hidden flag when we're actually in the foreground; if Chrome
    // let us resume briefly while still hidden we want the guard to keep retrying.
    if (!document.hidden) _ytHiddenWhilePlaying = false;
    _ytSetMediaSession();
    if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'playing';
    // Re-assert our handlers after YouTube's iframe may override them (needed for prev/next buttons)
    setTimeout(() => {
      _ytSetMediaSession();
      if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'playing';
    }, 800);
  } else if (event.data === YT.PlayerState.PAUSED) {
    // If the page is hidden, YouTube auto-paused us — keep retrying until we're back in foreground
    if (document.hidden && _ytHiddenWhilePlaying) {
      clearInterval(_ytHiddenResumeIv);
      _ytHiddenResumeIv = setInterval(() => {
        if (!document.hidden || !_ytHiddenWhilePlaying) {
          clearInterval(_ytHiddenResumeIv);
          _ytHiddenResumeIv = null;
          return;
        }
        if (_ytPlayer) {
          try {
            if (_ytPlayer.getPlayerState() !== YT.PlayerState.PLAYING) _ytPlayer.playVideo();
          } catch(e) {}
        }
      }, 600);
      // First attempt immediately
      setTimeout(() => { if (_ytPlayer && document.hidden) { try { _ytPlayer.playVideo(); } catch(e) {} } }, 300);
      return;
    }
    clearTimeout(_ytScrobbleTimer);
    _ytStopScrobbleRing();
    _ytStopSeekUpdate();
    if (pauseBtn) { pauseBtn.innerHTML = _YT_IC.play; pauseBtn.title = 'Resume'; }
    if ('mediaSession' in navigator) navigator.mediaSession.playbackState = 'paused';
  } else if (event.data === YT.PlayerState.ENDED) {
    clearTimeout(_ytScrobbleTimer);
    _ytStopSeekUpdate();
    if (!_ytScrobbled && _ytScrobbleThreshold === 'end') _ytScrobble();
    if (_ytActiveBtn) _ytActiveBtn.classList.remove('yt-btn-loading', 'yt-btn-playing');
    if (_ytRepeat === 1 && _ytCurrentTrack) {
      openYtPlayer(_ytCurrentTrack.title, _ytCurrentTrack.artist, _ytCurrentTrack.album, _ytActiveBtn);
    } else if (_ytQueue.length > 0) {
      _ytAdvanceFromQueue();
    } else if (_ytRepeat === 2 && _ytCurrentTrack) {
      openYtPlayer(_ytCurrentTrack.title, _ytCurrentTrack.artist, _ytCurrentTrack.album, _ytActiveBtn);
    }
  } else {
    clearTimeout(_ytScrobbleTimer);
  }
}

function _ytOnError(event) {
  const statusEl = document.getElementById('ytMiniStatus');
  const code = event && event.data;
  if (_ytCurrentTrack && _ytEmbedRetry < 5) {
    _ytEmbedRetry++;
    const { title, artist } = _ytCurrentTrack;
    const fallbacks = [
      `${artist} ${title} lyric video`,
      `${artist} ${title} official`,
      `${artist} ${title} - Topic`,
      `${artist} ${title} audio`,
      `${artist} ${title} remastered`,
    ];
    if (statusEl) { statusEl.textContent = `Trying alternate ${_ytEmbedRetry}/5…`; statusEl.className = 'yt-mini-status'; }
    _ytSearch(null, null, fallbacks[_ytEmbedRetry - 1]);
    return;
  }
  if (_ytActiveBtn) _ytActiveBtn.classList.remove('yt-btn-loading', 'yt-btn-playing');
  if (_ytQueue.length > 0) {
    if (statusEl) { statusEl.textContent = 'Skipping unavailable…'; statusEl.className = 'yt-mini-status'; }
    setTimeout(_ytSkip, 1500);
    return;
  }
  if (statusEl) {
    const msg = (code === 101 || code === 150) ? 'Embedding disabled' : 'Playback unavailable';
    statusEl.innerHTML = `${msg} — <button class="yt-err-open-btn" onclick="_ytOpenInYT()">open in YouTube ↗</button>`;
    statusEl.className = 'yt-mini-status err';
  }
}

async function _ytScrobble() {
  if (!_ytCurrentTrack || _ytScrobbled) return;
  _ytScrobbled = true;
  const { title, artist, album } = _ytCurrentTrack;
  const timestamp = Math.floor(Date.now() / 1000);
  const statusEl  = document.getElementById('ytMiniStatus');
  const hasLfm    = !!(getScrobbleSession() && getScrobbleUser());
  const hasSheet  = !!(getSheetWriteUrl() && getDataSource() === 'sheets');
  const username  = getLastFmUser();
  try {
    if (hasLfm) {
      const params = { method: 'track.scrobble', artist, track: title, timestamp: String(timestamp), sk: getScrobbleSession() };
      if (album) params.album = album;
      // Only send albumArtist when it differs from artist (collaboration tracks)
      const primaryArt = _primaryArtist(artist);
      if (primaryArt !== artist) params.albumArtist = primaryArt;
      await lfmPost(params);
    } else if (hasSheet) {
      const res  = await fetch(getSheetWriteUrl(), { method: 'POST', body: JSON.stringify({ artist, track: title, album, timestamp }) });
      const data = await res.json();
      if (data.status === 'error') throw new Error(data.message || 'Script error');
    } else if (username) {
      const r = await fetch(`${BACKEND_API}/api/sync/rows/${encodeURIComponent(username)}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows: [{ artist, track: title, album: album || '', scrobbled_at: new Date(timestamp * 1000).toISOString() }] })
      });
      if (!r.ok) throw new Error('Backend error');
    } else {
      throw new Error('No scrobble destination');
    }
    if (statusEl) { statusEl.textContent = '✓ Scrobbled'; statusEl.className = 'yt-mini-status ok'; }
    _ytFlashScrobbleRing();
  } catch (e) {
    _ytScrobbled = false;
    if (statusEl) { statusEl.textContent = 'Scrobble failed'; statusEl.className = 'yt-mini-status err'; }
  }
}

function closeYtPlayer() {
  clearTimeout(_ytScrobbleTimer);
  clearTimeout(_ytQueueToastTimer);
  _ytStopScrobbleRing();
  _ytStopSeekUpdate();
  clearInterval(_ytSleepInterval); _ytSleepInterval = null; _ytSleepRemaining = 0; _ytUpdateSleepBtn();
  clearInterval(_ytCrossfadeRamp); _ytCrossfadeRamp = null; _ytCrossfadingOut = false; _ytNewTrackFade = false;
  if (_ytPipWindow) { try { _ytPipWindow.close(); } catch(e) {} _ytPipWindow = null; _ytPipUpdate = null; _ytUpdatePipBtn(); }
  const seekWrap = document.getElementById('ytSeekBarWrap');
  if (seekWrap) seekWrap.style.display = 'none';
  if (_ytPlayer) {
    try { _ytPlayer.stopVideo(); } catch(e) {}
    try { _ytPlayer.destroy(); } catch(e) {}
    _ytPlayer = null;
  }
  if (_ytActiveBtn) { _ytActiveBtn.classList.remove('yt-btn-loading', 'yt-btn-playing'); _ytActiveBtn = null; }
  document.querySelectorAll('.yt-now-playing-row').forEach(r => r.classList.remove('yt-now-playing-row'));
  const player = document.getElementById('ytMiniPlayer');
  if (player) player.style.display = 'none';
  const toast = document.getElementById('ytQueueToast');
  if (toast) toast.style.display = 'none';
  _ytCurrentTrack   = null;
  try { localStorage.removeItem('yt-player-current'); } catch(e) {}
  _ytCurrentVideoId = null;
  _ytScrobbled      = false;
  // Clear OS lock screen / media controls
  if ('mediaSession' in navigator) {
    try { navigator.mediaSession.metadata = null; } catch(e) {}
    try { navigator.mediaSession.playbackState = 'none'; } catch(e) {}
  }
  _ytExpandSize       = 0;
  _ytQueue            = [];
  _ytQueuePlayed      = [];
  _ytCurrentFromQueue = null;
  _ytQueueMultiSelect = false;
  _ytQueueSelected    = new Set();
  clearTimeout(_ytUndoTimer);
  _ytLastRemovedItem  = null;
  _ytUndoTimer        = null;
  _ytQueueHidden      = false; // panel will re-auto-open on next add
  _ytQueuePrevCount   = 0;    // reset so next add triggers auto-open
  _ytSaveQueue();
  _ytUpdateQueueDisplay();
  if (player) player.classList.remove('yt-expanded', 'yt-expanded-lg', 'yt-expanded-xl', 'yt-mini-collapsed');
  const expandBtn = document.getElementById('ytMiniExpandBtn');
  if (expandBtn) { expandBtn.innerHTML = _YT_IC.expand; expandBtn.title = 'Size: S → M'; }
  const collapseBtn = document.getElementById('ytMiniCollapseBtn');
  if (collapseBtn) { collapseBtn.innerHTML = _YT_IC.collapseV; collapseBtn.title = 'Collapse player'; }
  ['ytMiniSearchBox','ytSearchResults','ytMiniHistory','ytShortcutsPanel','ytLyricsPanel','ytSleepPanel','ytPlaylistsPanel'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
  ['ytMiniSearchBtn','ytMiniHistoryBtn','ytMiniShortcutsBtn','ytLyricsBtn','ytSleepBtn','ytPlaylistsBtn'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove('yt-ctrl-active');
  });
}

function _ytPauseToggle() {
  if (!_ytPlayer) {
    if (_ytCurrentTrack) openYtPlayer(_ytCurrentTrack.title, _ytCurrentTrack.artist, _ytCurrentTrack.album, null);
    return;
  }
  const state = _ytPlayer.getPlayerState();
  if (state === YT.PlayerState.PLAYING) { _ytPlayer.pauseVideo(); }
  else { _ytPlayer.playVideo(); }
}

const _YT_IC = {
  pause:    `<svg class="yt-icon" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>`,
  play:     `<svg class="yt-icon" viewBox="0 0 24 24" fill="currentColor"><polygon points="5,3 19,12 5,21"/></svg>`,
  expand:   `<svg class="yt-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15,3 21,3 21,9"/><polyline points="9,21 3,21 3,15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>`,
  shrink:   `<svg class="yt-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4,14 10,14 10,20"/><polyline points="20,10 14,10 14,4"/><line x1="10" y1="14" x2="3" y2="21"/><line x1="21" y1="3" x2="14" y2="10"/></svg>`,
  collapseV:`<svg class="yt-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6,9 12,15 18,9"/></svg>`,
  expandV:  `<svg class="yt-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6,15 12,9 18,15"/></svg>`,
};

const _YT_SIZES = [
  { w: 160, h: 90,  cls: '',               iconKey: 'expand', title: 'Size: S → M'  },
  { w: 320, h: 180, cls: 'yt-expanded',    iconKey: 'expand', title: 'Size: M → L'  },
  { w: 480, h: 270, cls: 'yt-expanded-lg', iconKey: 'expand', title: 'Size: L → XL' },
  { w: 640, h: 360, cls: 'yt-expanded-xl', iconKey: 'shrink', title: 'Size: XL → S' },
];
function _ytExpand() {
  _ytExpandSize = (_ytExpandSize + 1) % _YT_SIZES.length;
  const { w, h, cls, iconKey, title } = _YT_SIZES[_ytExpandSize];
  const player = document.getElementById('ytMiniPlayer');
  player.classList.remove('yt-expanded', 'yt-expanded-lg', 'yt-expanded-xl');
  if (cls) player.classList.add(cls);
  const btn = document.getElementById('ytMiniExpandBtn');
  if (btn) { btn.innerHTML = _YT_IC[iconKey]; btn.title = title; }
  if (_ytPlayer) { try { _ytPlayer.setSize(w, h); } catch(e) {} }
}

function _ytOpenInYT() {
  if (_ytCurrentVideoId) {
    window.open('https://www.youtube.com/watch?v=' + _ytCurrentVideoId, '_blank');
  } else if (_ytCurrentTrack) {
    window.open('https://www.youtube.com/results?search_query=' + encodeURIComponent(_ytCurrentTrack.artist + ' ' + _ytCurrentTrack.title), '_blank');
  }
}

function _ytSkip() {
  if (_ytQueue.length > 0) {
    _ytAdvanceFromQueue();
  } else {
    const statusEl = document.getElementById('ytMiniStatus');
    if (statusEl) {
      const prev = statusEl.innerHTML;
      statusEl.textContent = 'Nothing queued';
      statusEl.className = 'yt-mini-status';
      setTimeout(() => { if (statusEl.textContent === 'Nothing queued') { statusEl.innerHTML = prev; } }, 2000);
    }
  }
}

function _ytToggleSearch() {
  const box = document.getElementById('ytMiniSearchBox');
  if (!box) return;
  const isVisible = box.style.display !== 'none';
  box.style.display = isVisible ? 'none' : 'flex';
  const btn = document.getElementById('ytMiniSearchBtn');
  if (btn) btn.classList.toggle('yt-ctrl-active', !isVisible);
  if (!isVisible) {
    const input = document.getElementById('ytMiniSearchInput');
    if (input) {
      if (_ytCurrentTrack) input.value = _ytCurrentTrack.artist + ' ' + _ytCurrentTrack.title;
      input.focus();
      input.select();
    }
  }
}

function _ytRunCustomSearch() {
  const input = document.getElementById('ytMiniSearchInput');
  if (!input || !input.value.trim()) return;
  const q = input.value.trim();
  _ytToggleSearch();
  _ytEmbedRetry = 0;
  _ytSearchMulti(q);
}

async function _ytSearchMulti(baseQuery) {
  const resultsEl = document.getElementById('ytSearchResults');
  const statusEl  = document.getElementById('ytMiniStatus');
  if (resultsEl) { resultsEl.style.display = 'block'; resultsEl.innerHTML = '<div class="yt-sr-loading">Searching…</div>'; }
  if (statusEl)  { statusEl.textContent = ''; }
  const variants = ['official audio', 'official video', 'lyric video'];
  const needsVariants = !/(official|lyric|audio|video|live|acoustic|cover)/i.test(baseQuery);
  const queries = needsVariants ? variants.map(v => `${baseQuery} ${v}`) : [baseQuery];

  // Retry loop for server wake-up (Render free tier sleeps after inactivity; cold start ~30s)
  const MAX_RETRIES = 5;
  const RETRY_DELAY_MS = 6000;
  let settled;
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    settled = await Promise.allSettled(
      queries.map(q => fetch(`${BACKEND_API}/api/youtube/search?q=${encodeURIComponent(q)}`).then(r => {
        if (r.status === 502 || r.status === 503) throw new Error('server_unavailable');
        return r.json();
      }))
    );
    // Check if all failed with server_unavailable — if so, retry after delay
    const allUnavailable = settled.every(r => r.status === 'rejected' && r.reason && r.reason.message === 'server_unavailable');
    if (allUnavailable && attempt < MAX_RETRIES) {
      if (statusEl)  { statusEl.textContent = 'Waking up server…'; statusEl.className = 'yt-mini-status'; }
      if (resultsEl) { resultsEl.innerHTML = '<div class="yt-sr-loading">Waking up server…</div>'; }
      await new Promise(r => setTimeout(r, RETRY_DELAY_MS));
      continue;
    }
    break;
  }
  if (statusEl) { statusEl.textContent = ''; }

  const seen = new Set();
  const hits = settled
    .filter(r => r.status === 'fulfilled' && r.value && r.value.videoId)
    .map(r => r.value)
    .filter(v => { if (seen.has(v.videoId)) return false; seen.add(v.videoId); return true; });
  if (!resultsEl) return;
  if (hits.length === 0) { resultsEl.innerHTML = '<div class="yt-sr-no-results">No results found</div>'; return; }
  if (hits.length === 1) { resultsEl.style.display = 'none'; _ytPickResult(hits[0].videoId); return; }
  resultsEl.innerHTML = hits.map(h =>
    `<div class="yt-sr-item" data-vid="${h.videoId}" onclick="_ytPickResult(this.dataset.vid)">` +
    `<img class="yt-sr-thumb" src="https://img.youtube.com/vi/${h.videoId}/default.jpg" loading="lazy" onerror="this.style.display='none'">` +
    `<span class="yt-sr-title">${esc(h.videoTitle || h.title || 'Unknown')}</span>` +
    `</div>`
  ).join('');
}

function _ytPickResult(videoId) {
  const resultsEl = document.getElementById('ytSearchResults');
  if (resultsEl) resultsEl.style.display = 'none';
  _ytCurrentVideoId = videoId;
  _ytUpdateThumb();
  const statusEl = document.getElementById('ytMiniStatus');
  if (statusEl) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; }
  if (_ytApiReady) { _ytLoadVideo(videoId); } else { _ytPendingVideo = videoId; }
}

function _ytSaveQueue() {
  try {
    const saveable = _ytQueue.map(({ title, artist, album }) => ({ title, artist, album }));
    localStorage.setItem('yt-player-queue', JSON.stringify(saveable));
  } catch(e) {}
}

function _ytLoadQueue() {
  try {
    const saved = localStorage.getItem('yt-player-queue');
    if (saved) {
      const items = JSON.parse(saved);
      if (Array.isArray(items) && items.length > 0) {
        _ytQueue = items;
        _ytUpdateQueueDisplay();
      }
    }
  } catch(e) {}
}

function _ytLoadVolume() {
  try {
    const v = localStorage.getItem('yt-volume');
    if (v !== null) _ytVolume = Math.max(0, Math.min(100, parseInt(v)));
  } catch(e) {}
  const slider = document.getElementById('ytVolumeSlider');
  if (slider) slider.value = _ytVolume;
  _ytUpdateVolIcon();
  if (_ytPlayer) { try { _ytPlayer.setVolume(_ytVolume); } catch(e) {} }
}

function _ytSetVolume(v) {
  _ytVolume = Math.max(0, Math.min(100, v));
  _ytMuted  = _ytVolume === 0;
  const slider = document.getElementById('ytVolumeSlider');
  if (slider) slider.value = _ytVolume;
  if (_ytPlayer) { try { _ytPlayer.setVolume(_ytVolume); } catch(e) {} }
  try { localStorage.setItem('yt-volume', _ytVolume); } catch(e) {}
  _ytUpdateVolIcon();
}

function _ytToggleMute() {
  if (_ytMuted) {
    _ytMuted = false;
    _ytSetVolume(_ytPreMuteVol || 80);
  } else {
    _ytPreMuteVol = _ytVolume || 80;
    _ytMuted = true;
    _ytSetVolume(0);
  }
}

function _ytUpdateVolIcon() {
  const path = document.getElementById('ytVolPath');
  if (!path) return;
  if (_ytVolume === 0) {
    path.setAttribute('d', 'M23,9l-6,6M17,9l6,6');
  } else if (_ytVolume < 50) {
    path.setAttribute('d', 'M15.54,8.46a5,5,0,0,1,0,7.07');
  } else {
    path.setAttribute('d', 'M15.54,8.46a5,5,0,0,1,0,7.07M19.07,4.93a10,10,0,0,1,0,14.14');
  }
}

function _ytRecordHistory(title, artist, album) {
  _ytHistory = _ytHistory.filter(h => !(h.title === title && h.artist === artist));
  _ytHistory.unshift({ title, artist, album });
  if (_ytHistory.length > 20) _ytHistory.pop();
}

function _ytToggleHistory() {
  const el  = document.getElementById('ytMiniHistory');
  const btn = document.getElementById('ytMiniHistoryBtn');
  if (!el) return;
  const visible = el.style.display !== 'none';
  ['ytSearchResults','ytShortcutsPanel','ytLyricsPanel','ytSleepPanel','ytPlaylistsPanel'].forEach(id => { const e = document.getElementById(id); if (e) e.style.display = 'none'; });
  ['ytMiniShortcutsBtn','ytLyricsBtn','ytSleepBtn','ytPlaylistsBtn'].forEach(id => { const e = document.getElementById(id); if (e) e.classList.remove('yt-ctrl-active'); });
  el.style.display = visible ? 'none' : 'block';
  if (btn) btn.classList.toggle('yt-ctrl-active', !visible);
  if (!visible) _ytRenderHistory();
}

function _ytRenderHistory() {
  const el = document.getElementById('ytMiniHistory');
  if (!el) return;
  if (_ytHistory.length === 0) { el.innerHTML = '<div class="yt-hist-empty">No history yet</div>'; return; }
  el.innerHTML =
    `<div class="yt-hist-header">` +
    `<button class="yt-hist-addall-btn" onclick="_ytAddHistoryToQueue()" title="Add all to queue">+ Queue all</button>` +
    `</div>` +
    _ytHistory.map((h, i) =>
    `<div class="yt-hist-item">` +
    `<span class="yt-hist-title">${esc(h.title)}</span>` +
    `<button class="yt-hist-play" onclick="_ytPlayFromHistory(${i})" title="Play">▶</button>` +
    `</div>`
  ).join('');
}

function _ytPlayFromHistory(i) {
  const h = _ytHistory[i];
  if (h) openYtPlayer(h.title, h.artist, h.album, null);
}

function _ytToggleCollapse() {
  const player = document.getElementById('ytMiniPlayer');
  if (!player) return;
  const collapsed = player.classList.toggle('yt-mini-collapsed');
  const btn = document.getElementById('ytMiniCollapseBtn');
  if (btn) { btn.innerHTML = collapsed ? _YT_IC.expandV : _YT_IC.collapseV; btn.title = collapsed ? 'Expand player' : 'Collapse player'; }
  _ytUpdateCollapsedCount(); // show/hide queue count badge (#14)
}

function _ytToggleShortcuts() {
  const el  = document.getElementById('ytShortcutsPanel');
  const btn = document.getElementById('ytMiniShortcutsBtn');
  if (!el) return;
  const visible = el.style.display !== 'none';
  ['ytMiniHistory','ytSearchResults','ytLyricsPanel','ytSleepPanel','ytPlaylistsPanel'].forEach(id => { const e = document.getElementById(id); if (e) e.style.display = 'none'; });
  ['ytMiniHistoryBtn','ytLyricsBtn','ytSleepBtn','ytPlaylistsBtn'].forEach(id => { const e = document.getElementById(id); if (e) e.classList.remove('yt-ctrl-active'); });
  el.style.display = visible ? 'none' : 'block';
  if (btn) btn.classList.toggle('yt-ctrl-active', !visible);
}

function _ytStartScrobbleRing() {
  const wrap = document.querySelector('.yt-pause-wrap');
  if (!wrap) return;
  _ytPlayStart = Date.now();
  wrap.style.setProperty('--yt-sp', 0);
  wrap.classList.remove('yt-scrobbled');
  wrap.classList.add('yt-scrobbling');
  clearInterval(_ytScrobbleInterval);
  _ytScrobbleInterval = setInterval(() => {
    const progress = Math.min((Date.now() - _ytPlayStart) / 30000, 1);
    wrap.style.setProperty('--yt-sp', progress);
    if (progress >= 1) { clearInterval(_ytScrobbleInterval); _ytScrobbleInterval = null; }
  }, 500);
}

function _ytStopScrobbleRing() {
  clearInterval(_ytScrobbleInterval);
  _ytScrobbleInterval = null;
  _ytPlayStart = null;
  const wrap = document.querySelector('.yt-pause-wrap');
  if (wrap) { wrap.classList.remove('yt-scrobbling', 'yt-scrobbled'); wrap.style.setProperty('--yt-sp', 0); }
}

function _ytFlashScrobbleRing() {
  const wrap = document.querySelector('.yt-pause-wrap');
  if (!wrap) return;
  wrap.classList.remove('yt-scrobbling');
  wrap.classList.add('yt-scrobbled');
  setTimeout(() => { if (wrap) { wrap.classList.remove('yt-scrobbled'); wrap.style.setProperty('--yt-sp', 0); } }, 2000);
}

// ── Seek bar helpers ───────────────────────────────────────────────
function _ytStartSeekUpdate() {
  clearInterval(_ytSeekInterval);
  _ytSeekInterval = setInterval(_ytUpdateSeekBar, 500);
}

function _ytStopSeekUpdate() {
  clearInterval(_ytSeekInterval);
  _ytSeekInterval = null;
}

function _ytUpdateSeekBar() {
  if (!_ytPlayer || _ytSeekDragging) return;
  try {
    const dur = _ytPlayer.getDuration();
    const cur = _ytPlayer.getCurrentTime();
    if (!dur) return;
    const wrap   = document.getElementById('ytSeekBarWrap');
    const bar    = document.getElementById('ytSeekBar');
    const curEl  = document.getElementById('ytSeekCurrent');
    const durEl  = document.getElementById('ytSeekDuration');
    if (wrap && wrap.style.display === 'none') wrap.style.display = '';
    if (bar)   { bar.max = dur; bar.value = cur; }
    if (curEl) curEl.textContent = _ytFmtTime(cur);
    if (durEl) durEl.textContent = _ytFmtTime(dur);
    if (!_ytScrobbled && (_ytScrobbleThreshold === '50%' || _ytScrobbleThreshold === '70%')) {
      const pct = parseFloat(_ytScrobbleThreshold) / 100;
      if (cur / dur >= pct) _ytScrobble();
    }
    if (_ytCrossfade > 0 && !_ytCrossfadingOut && _ytQueue.length > 0) {
      const remaining = dur - cur;
      if (remaining > 0 && remaining <= _ytCrossfade) { _ytCrossfadingOut = true; _ytStartFadeOut(); }
    }
    // Keep OS media controls position updated (required for prev/next to stay visible)
    if ('mediaSession' in navigator && navigator.mediaSession.metadata) {
      try { navigator.mediaSession.setPositionState({ duration: dur, playbackRate: _ytSpeed || 1, position: Math.min(cur, dur) }); } catch(e2) {}
    }
  } catch(e) {}
}

function _ytFmtTime(s) {
  s = Math.max(0, Math.floor(s));
  const m = Math.floor(s / 60);
  const sec = (s % 60).toString().padStart(2, '0');
  return `${m}:${sec}`;
}

function _ytSeek(val) {
  if (_ytPlayer) { try { _ytPlayer.seekTo(val, true); } catch(e) {} }
}

// ── Repeat mode ────────────────────────────────────────────────────
function _ytCycleRepeat() {
  _ytRepeat = (_ytRepeat + 1) % 3;
  try { localStorage.setItem('yt-repeat', _ytRepeat); } catch(e) {}
  _ytUpdateRepeatBtn();
}

function _ytUpdateRepeatBtn() {
  const btn   = document.getElementById('ytMiniRepeatBtn');
  const badge = document.getElementById('ytRepeatBadge');
  if (!btn) return;
  const labels = ['Repeat: Off', 'Repeat: One', 'Repeat: All'];
  btn.title = labels[_ytRepeat];
  btn.classList.toggle('yt-ctrl-active', _ytRepeat > 0);
  if (badge) badge.style.display = _ytRepeat === 1 ? '' : 'none';
}

// ── Thumbnail helper ────────────────────────────────────────────────
function _ytUpdateThumb() {
  const img = document.getElementById('ytMiniThumb');
  if (!img) return;
  if (_ytCurrentVideoId) {
    img.src = `https://img.youtube.com/vi/${_ytCurrentVideoId}/default.jpg`;
  } else {
    img.src = '';
  }
}

// ── Media Session API ──────────────────────────────────────────────────────
// Registers the current track with the OS so playback can continue on the
// lock screen and hardware media keys (headphones, Bluetooth) work correctly.
function _ytSetMediaSession() {
  if (!('mediaSession' in navigator) || !_ytCurrentTrack) return;
  const { title, artist, album } = _ytCurrentTrack;
  // Use YouTube thumbnails for artwork when a video ID is known
  const artwork = _ytCurrentVideoId ? [
    { src: `https://img.youtube.com/vi/${_ytCurrentVideoId}/mqdefault.jpg`,  sizes: '320x180', type: 'image/jpeg' },
    { src: `https://img.youtube.com/vi/${_ytCurrentVideoId}/hqdefault.jpg`,  sizes: '480x360', type: 'image/jpeg' },
    { src: `https://img.youtube.com/vi/${_ytCurrentVideoId}/maxresdefault.jpg`, sizes: '1280x720', type: 'image/jpeg' },
  ] : [];
  navigator.mediaSession.metadata = new MediaMetadata({ title, artist, album: album || '', artwork });
  // Wire OS/hardware controls to the existing player functions
  navigator.mediaSession.setActionHandler('play',          () => { if (_ytPlayer) _ytPlayer.playVideo(); });
  navigator.mediaSession.setActionHandler('pause',         () => { if (_ytPlayer) _ytPlayer.pauseVideo(); });
  navigator.mediaSession.setActionHandler('stop',          () => closeYtPlayer());
  navigator.mediaSession.setActionHandler('nexttrack',     () => _ytSkip());
  // Previous: restart the track (or seek to 0 if already near the start)
  navigator.mediaSession.setActionHandler('previoustrack', () => {
    if (_ytPlayer) {
      try { _ytPlayer.seekTo(0, true); } catch(e) {}
    }
  });
  navigator.mediaSession.setActionHandler('seekto', e => {
    if (_ytPlayer && e.seekTime != null) {
      try { _ytPlayer.seekTo(e.seekTime, true); } catch(e2) {}
    }
  });
  // Provide position state so Chrome shows prev/next buttons and a seek bar
  if (_ytPlayer) {
    try {
      const dur = _ytPlayer.getDuration();
      const cur = _ytPlayer.getCurrentTime();
      if (dur > 0) {
        navigator.mediaSession.setPositionState({ duration: dur, playbackRate: _ytSpeed || 1, position: Math.min(cur, dur) });
      }
    } catch(e) {}
  }
}

// ── Background-play guard ───────────────────────────────────────────
// Chrome/Android pauses YouTube iframes when the page goes hidden. We track
// whether we were playing before hiding and auto-resume in two ways:
//   1. Directly in _ytOnState (PAUSED) when document.hidden is true
//   2. Here on visibilitychange when returning to foreground (belt-and-suspenders)
document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    // Record whether playback was active so the PAUSED handler can decide
    if (_ytPlayer) {
      try { _ytHiddenWhilePlaying = _ytPlayer.getPlayerState() === YT.PlayerState.PLAYING; } catch(e) {}
    }
  } else {
    // Returning to foreground — stop the retry interval and resume if we were playing
    clearInterval(_ytHiddenResumeIv);
    _ytHiddenResumeIv = null;
    if (_ytHiddenWhilePlaying) {
      _ytHiddenWhilePlaying = false;
      setTimeout(() => {
        if (_ytPlayer) {
          try { _ytPlayer.playVideo(); } catch(e) {}
        }
      }, 200);
    }
  }
});

// ── Queue shuffle ───────────────────────────────────────────────────
function _ytShuffleQueue() {
  for (let i = _ytQueue.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [_ytQueue[i], _ytQueue[j]] = [_ytQueue[j], _ytQueue[i]];
  }
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── History bulk-queue ──────────────────────────────────────────────
function _ytAddHistoryToQueue() {
  _ytHistory.forEach(h => _ytQueue.push({ title: h.title, artist: h.artist, album: h.album, btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  _ytToggleHistory();
}

function ytPlayAll() {
  const btns = [...document.querySelectorAll('#songsBody .yt-play-btn')];
  if (btns.length === 0) return;
  const [first, ...rest] = btns;
  openYtPlayer(first.dataset.title, first.dataset.artist, first.dataset.album, first);
  rest.forEach(b => _ytQueue.push({ title: b.dataset.title, artist: b.dataset.artist, album: b.dataset.album, btn: b }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

function ytShuffleAll() {
  const btns = [...document.querySelectorAll('#songsBody .yt-play-btn')];
  if (btns.length === 0) return;
  for (let i = btns.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [btns[i], btns[j]] = [btns[j], btns[i]];
  }
  const [first, ...rest] = btns;
  openYtPlayer(first.dataset.title, first.dataset.artist, first.dataset.album, first);
  rest.forEach(b => _ytQueue.push({ title: b.dataset.title, artist: b.dataset.artist, album: b.dataset.album, btn: b }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

function _ytShowQueueToast(title, artist, album, btn) {
  const toast = document.getElementById('ytQueueToast');
  if (!toast) { openYtPlayer(title, artist, album, btn); return; }
  toast.querySelector('.yt-queue-toast-label').textContent = '"' + title + '"';
  const playerEl = document.getElementById('ytMiniPlayer');
  if (playerEl) {
    const r = playerEl.getBoundingClientRect();
    toast.style.right = (window.innerWidth - r.right) + 'px';
    toast.style.left  = 'auto';
    if (r.top < 80) {
      toast.style.top    = (r.bottom + 8) + 'px';
      toast.style.bottom = 'auto';
    } else {
      toast.style.bottom = (window.innerHeight - r.top + 8) + 'px';
      toast.style.top    = 'auto';
    }
  }
  toast.style.display = 'flex';
  toast.querySelector('.yt-queue-now-btn').onclick = () => {
    toast.style.display = 'none';
    openYtPlayer(title, artist, album, btn);
  };
  toast.querySelector('.yt-queue-next-btn').onclick = () => {
    toast.style.display = 'none';
    _ytQueue.unshift({ title, artist, album, btn });
    _ytUpdateQueueDisplay();
    _ytSaveQueue();
  };
  toast.querySelector('.yt-queue-add-btn').onclick = () => {
    toast.style.display = 'none';
    _ytQueue.push({ title, artist, album, btn });
    _ytUpdateQueueDisplay();
    _ytSaveQueue();
  };
}

function _ytUpdateQueueDisplay() {
  const el = document.getElementById('ytMiniQueue');
  if (!el) return;
  const totalVisible = _ytQueuePlayed.length + (_ytCurrentFromQueue ? 1 : 0) + _ytQueue.length;

  // Auto-open the panel when the queue goes from empty → non-empty (#11)
  if (totalVisible > 0 && _ytQueuePrevCount === 0) {
    _ytQueueHidden = false;
    const btn = document.getElementById('ytQueueBtn');
    if (btn) btn.classList.add('yt-ctrl-active');
  }
  _ytQueuePrevCount = totalVisible;

  // Update the count badge on the toggle button (#11) and collapsed badge (#14)
  _ytUpdateQueueBadge();
  _ytUpdateCollapsedCount();

  // Panel is manually hidden — keep it off-screen but badges are already updated
  if (_ytQueueHidden) { el.style.display = 'none'; return; }

  // Empty-state prompt (#12): show a hint instead of disappearing entirely
  if (totalVisible === 0) {
    el.style.display = 'block';
    el.innerHTML =
      `<div class="yt-queue-empty">` +
      `<div class="yt-queue-empty-msg">Queue is empty</div>` +
      `<div class="yt-queue-empty-hint">Click ▶ on any song to play it, or ⏭ Next to queue it</div>` +
      `</div>`;
    return;
  }

  el.style.display = 'block';

  // ── Header row ──────────────────────────────────────────────────────────────
  const selCount = _ytQueueSelected.size;
  let html =
    `<div class="yt-queue-header">` +
    `<span class="yt-queue-header-count">${_ytQueue.length} up next</span>` +
    `<div class="yt-queue-header-btns">` +
    // Multi-select toggle (#9)
    `<button class="yt-queue-multi-btn${_ytQueueMultiSelect ? ' yt-ctrl-active' : ''}" onclick="_ytToggleQueueMultiSelect()" title="Multi-select">` +
    `<svg class="yt-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="4" height="4" rx="0.5"/><rect x="3" y="11" width="4" height="4" rx="0.5"/><rect x="3" y="17" width="4" height="4" rx="0.5"/><line x1="10" y1="7" x2="21" y2="7"/><line x1="10" y1="13" x2="21" y2="13"/><line x1="10" y1="19" x2="21" y2="19"/></svg>` +
    `</button>` +
    `<button class="yt-queue-shuffle-btn" onclick="_ytShuffleQueue()" title="Shuffle queue">` +
    `<svg class="yt-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16,3 21,3 21,8"/><line x1="4" y1="20" x2="21" y2="3"/><polyline points="21,16 21,21 16,21"/><line x1="15" y1="15" x2="21" y2="21"/></svg>` +
    ` Shuffle</button>` +
    `<button class="yt-queue-reverse-btn" onclick="_ytReverseQueue()" title="Reverse queue order">↕ Rev</button>` + // #16
    `<button class="yt-queue-dedup-btn" onclick="_ytDeduplicateQueue()" title="Remove duplicates">Dedup</button>` + // #7
    `<button class="yt-queue-save-btn" onclick="_ytSaveQueueAsPlaylist()" title="Save queue as playlist">💾</button>` + // #8
    `<button class="yt-queue-clear-btn" onclick="_ytClearQueue()" title="Clear queue">✕ Clear</button>` +
    `</div>` +
    `</div>`;

  // ── Multi-select batch actions (#9) ─────────────────────────────────────────
  if (_ytQueueMultiSelect && selCount > 0) {
    html +=
      `<div class="yt-queue-multi-actions">` +
      `<span class="yt-queue-sel-count">${selCount} selected</span>` +
      `<button class="yt-queue-multi-act-btn" onclick="_ytMoveSelectedToTop()" title="Move selected to top">↑ Top</button>` +
      `<button class="yt-queue-multi-act-btn yt-queue-multi-del-btn" onclick="_ytDeleteSelected()" title="Delete selected">✕ Del</button>` +
      `</div>`;
  }

  // ── Played items (dimmed) — shown when playing from queue ───────────────────
  if (_ytQueuePlayed.length > 0) {
    html += `<div class="yt-mini-queue-played">`;
    _ytQueuePlayed.forEach(t => {
      html +=
        `<div class="yt-mini-queue-item yt-mini-queue-played-item">` +
        `<span class="yt-mini-queue-num">✓</span>` +
        `<span class="yt-mini-queue-title">${esc(t.title)}` +
        (t.artist ? `<span class="yt-mini-queue-artist"> · ${esc(t.artist)}</span>` : '') +
        `</span>` +
        `</div>`;
    });
    html += `</div>`;
  }

  // ── Currently playing from queue (highlighted) ──────────────────────────────
  if (_ytCurrentFromQueue) {
    const t = _ytCurrentFromQueue;
    html +=
      `<div class="yt-mini-queue-item yt-mini-queue-now-item">` +
      `<span class="yt-mini-queue-num">▶</span>` +
      `<span class="yt-mini-queue-title">${esc(t.title)}` +
      (t.artist ? `<span class="yt-mini-queue-artist"> · ${esc(t.artist)}</span>` : '') +
      `</span>` +
      `</div>`;
  }

  // ── Upcoming queue items ─────────────────────────────────────────────────────
  html += _ytQueue.map((t, i) => {
    const jt  = JSON.stringify(t.title);
    const jar = JSON.stringify(t.artist  || '');
    const jal = JSON.stringify(t.album   || '');
    const isSel = _ytQueueMultiSelect && _ytQueueSelected.has(i);
    return (
      `<div class="yt-mini-queue-item${isSel ? ' yt-queue-item-selected' : ''}" draggable="true" data-qi="${i}"` +
      ` oncontextmenu="event.preventDefault();_ytShowQueueContextMenu(event,${i})">` +
      // Left side: checkbox (multi-select) or drag handle
      (_ytQueueMultiSelect
        ? `<input type="checkbox" class="yt-mini-queue-cb"${isSel ? ' checked' : ''} onclick="event.stopPropagation();_ytQueueCheckbox(${i},event)">`
        : `<span class="yt-mini-queue-drag" title="Long-press on mobile / drag on desktop to reorder">⠿</span>`) +
      `<span class="yt-mini-queue-num">${i + 1}</span>` +
      `<button class="yt-mini-queue-move-top" onclick="_ytMoveToTop(${i})" title="Move to top (play next)">↑</button>` + // #5
      `<span class="yt-mini-queue-title">${esc(t.title)}` +
      (t.artist ? `<span class="yt-mini-queue-artist"> · ${esc(t.artist)}</span>` : '') +
      `</span>` +
      `<button class="yt-mini-queue-rm" onclick="_ytRemoveFromQueue(${i})" title="Remove">✕</button>` +
      `</div>`
    );
  }).join('');

  // ── Undo bar (#6) ────────────────────────────────────────────────────────────
  if (_ytLastRemovedItem) {
    html +=
      `<div class="yt-queue-undo-bar">` +
      `<span class="yt-queue-undo-label">Removed "${esc(_ytLastRemovedItem.item.title)}"</span>` +
      `<button class="yt-queue-undo-btn" onclick="_ytUndoRemove()">Undo</button>` +
      `</div>`;
  }

  el.innerHTML = html;
  _ytInitQueueDrag(el);
}

function _ytInitQueueDrag(container) {
  // Only draggable items (upcoming queue items) get drag/touch events
  container.querySelectorAll('.yt-mini-queue-item[draggable]').forEach(item => {

    // ── Desktop HTML5 drag-and-drop ──────────────────────────────────────────
    item.addEventListener('dragstart', e => {
      _ytQueueDragSrc = item;
      item.classList.add('yt-queue-dragging');
      e.dataTransfer.effectAllowed = 'move';
    });
    item.addEventListener('dragend', () => {
      _ytQueueDragSrc = null;
      container.querySelectorAll('.yt-mini-queue-item').forEach(i => i.classList.remove('yt-queue-dragging', 'yt-queue-drag-over'));
    });
    item.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      container.querySelectorAll('.yt-mini-queue-item').forEach(i => i.classList.remove('yt-queue-drag-over'));
      if (item !== _ytQueueDragSrc) item.classList.add('yt-queue-drag-over');
    });
    item.addEventListener('dragleave', () => item.classList.remove('yt-queue-drag-over'));
    item.addEventListener('drop', e => {
      e.preventDefault();
      if (_ytQueueDragSrc && _ytQueueDragSrc !== item) {
        const fromIdx = parseInt(_ytQueueDragSrc.dataset.qi);
        const toIdx   = parseInt(item.dataset.qi);
        const [moved] = _ytQueue.splice(fromIdx, 1);
        _ytQueue.splice(toIdx, 0, moved);
        _ytUpdateQueueDisplay();
        _ytSaveQueue();
      }
    });

    // ── Mobile: long-press (400ms) to start touch drag (#19) ─────────────────
    item.addEventListener('touchstart', e => {
      // Don't start a drag timer on checkbox or button taps
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'BUTTON') return;
      const touch = e.touches[0];
      clearTimeout(_ytQueueTouchTimer);
      _ytQueueTouchTimer = setTimeout(() => {
        _ytTouchDragSrc = item;
        item.classList.add('yt-queue-dragging');
        // Build a ghost clone anchored to the touch point
        const clone = item.cloneNode(true);
        clone.className = 'yt-mini-queue-item yt-touch-drag-ghost';
        clone.style.cssText = `position:fixed;width:${item.offsetWidth}px;` +
          `left:${touch.clientX - 20}px;top:${touch.clientY - 20}px;` +
          `pointer-events:none;z-index:9999;`;
        document.body.appendChild(clone);
        _ytTouchDragClone = clone;
        // Haptic feedback where available
        if (navigator.vibrate) navigator.vibrate(30);
      }, 400);
    }, { passive: true });

    item.addEventListener('touchmove', e => {
      if (!_ytTouchDragSrc) { clearTimeout(_ytQueueTouchTimer); return; }
      e.preventDefault(); // block scroll while dragging
      const touch = e.touches[0];
      if (_ytTouchDragClone) {
        _ytTouchDragClone.style.left = (touch.clientX - 20) + 'px';
        _ytTouchDragClone.style.top  = (touch.clientY - 20) + 'px';
      }
      // Determine which item the finger is over
      let newOver = null;
      container.querySelectorAll('.yt-mini-queue-item[draggable]').forEach(el => {
        const r = el.getBoundingClientRect();
        el.classList.remove('yt-queue-drag-over');
        if (touch.clientY >= r.top && touch.clientY <= r.bottom && el !== _ytTouchDragSrc) newOver = el;
      });
      if (newOver) { newOver.classList.add('yt-queue-drag-over'); _ytTouchDragOver = newOver; }
      else _ytTouchDragOver = null;
    }, { passive: false });

    const _ytFinishTouchDrag = () => {
      clearTimeout(_ytQueueTouchTimer);
      if (_ytTouchDragClone) { _ytTouchDragClone.remove(); _ytTouchDragClone = null; }
      if (_ytTouchDragSrc && _ytTouchDragOver) {
        const from = parseInt(_ytTouchDragSrc.dataset.qi);
        const to   = parseInt(_ytTouchDragOver.dataset.qi);
        if (from !== to) {
          const [moved] = _ytQueue.splice(from, 1);
          _ytQueue.splice(to, 0, moved);
          _ytUpdateQueueDisplay();
          _ytSaveQueue();
        }
      }
      if (_ytTouchDragSrc) _ytTouchDragSrc.classList.remove('yt-queue-dragging');
      container.querySelectorAll('.yt-mini-queue-item').forEach(i => i.classList.remove('yt-queue-drag-over'));
      _ytTouchDragSrc  = null;
      _ytTouchDragOver = null;
    };

    item.addEventListener('touchend',    _ytFinishTouchDrag);
    item.addEventListener('touchcancel', _ytFinishTouchDrag);
  });
}

function _ytRemoveFromQueue(i) {
  // Save for one-step undo (#6)
  clearTimeout(_ytUndoTimer);
  _ytLastRemovedItem = { item: _ytQueue[i], idx: i };
  _ytQueue.splice(i, 1);
  _ytQueueSelected.delete(i); // keep selection coherent
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  // Auto-expire undo after 4s
  _ytUndoTimer = setTimeout(() => {
    _ytLastRemovedItem = null;
    _ytUndoTimer       = null;
    _ytUpdateQueueDisplay();
  }, 4000);
}

function _ytClearQueue() {
  _ytQueue            = [];
  _ytQueuePlayed      = [];
  _ytCurrentFromQueue = null;
  _ytQueueMultiSelect = false;
  _ytQueueSelected    = new Set();
  clearTimeout(_ytUndoTimer);
  _ytLastRemovedItem  = null;
  _ytUndoTimer        = null;
  _ytQueuePrevCount   = 0;   // reset so next add auto-re-opens
  // Keep _ytQueueHidden as-is: if panel was open it stays open showing empty state
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── Queue advance: move to played history, pop next, and play (#songs-don't-disappear) ──
function _ytAdvanceFromQueue() {
  if (_ytCurrentFromQueue) _ytQueuePlayed.push(_ytCurrentFromQueue);
  const next = _ytQueue.shift();
  _ytCurrentFromQueue = next;
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  _ytAdvancingQueue = true; // tell openYtPlayer not to wipe played history
  openYtPlayer(next.title, next.artist, next.album, next.btn || null);
}

// ── #5: Move item at index i to position 0 (plays next) ──────────────────────
function _ytMoveToTop(i) {
  if (i <= 0 || i >= _ytQueue.length) return;
  const [item] = _ytQueue.splice(i, 1);
  _ytQueue.unshift(item);
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── #7: Remove duplicate entries (same title + artist) ───────────────────────
function _ytDeduplicateQueue() {
  const seen = new Set();
  _ytQueue = _ytQueue.filter(t => {
    const key = (t.title + '|||' + (t.artist || '')).toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  _ytQueueSelected = new Set(); // reset selection after dedup
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── #16: Reverse the queue order ─────────────────────────────────────────────
function _ytReverseQueue() {
  _ytQueue.reverse();
  _ytQueueSelected = new Set();
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── #17: Remove all items by a specific artist ────────────────────────────────
function _ytRemoveByArtist(artist) {
  _ytHideQueueContextMenu();
  _ytQueue = _ytQueue.filter(t => (t.artist || '').toLowerCase() !== artist.toLowerCase());
  _ytQueueSelected = new Set();
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── #8: Save current queue as a named playlist ────────────────────────────────
function _ytSaveQueueAsPlaylist() {
  const name = prompt('Save queue as playlist:', '');
  if (name && name.trim()) _ytSaveCurrentQueue(name.trim());
}

// ── #6: Undo last removal ─────────────────────────────────────────────────────
function _ytUndoRemove() {
  if (!_ytLastRemovedItem) return;
  clearTimeout(_ytUndoTimer);
  const { item, idx } = _ytLastRemovedItem;
  _ytLastRemovedItem = null;
  _ytUndoTimer       = null;
  // Re-insert at original position, clamped if queue is shorter now
  _ytQueue.splice(Math.min(idx, _ytQueue.length), 0, item);
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── #10 + #17: Queue item right-click context menu ────────────────────────────
function _ytShowQueueContextMenu(e, i) {
  _ytHideQueueContextMenu();
  const t = _ytQueue[i];
  if (!t) return;
  const jt  = JSON.stringify(t.title);
  const jar = JSON.stringify(t.artist  || '');
  const jal = JSON.stringify(t.album   || '');
  const menu = document.createElement('div');
  menu.id        = 'ytQueueCtx';
  menu.className = 'yt-queue-ctx';
  menu.innerHTML =
    // Play now: remove from queue then open directly
    `<button onclick="_ytQueuePlayNow(${i})">▶ Play now</button>` +
    // Play next: move to top of upcoming list
    `<button onclick="_ytHideQueueContextMenu();_ytMoveToTop(${i})">⏭ Play next</button>` +
    // Remove with undo support
    `<button onclick="_ytHideQueueContextMenu();_ytRemoveFromQueue(${i})">✕ Remove</button>` +
    // Remove all by artist (only if artist is set)
    (t.artist ? `<button onclick="_ytRemoveByArtist(${jar})">🗑 Remove all by ${esc(t.artist)}</button>` : '');
  // Position near cursor, clamped to viewport edges
  const x = Math.min(e.clientX, window.innerWidth  - 185);
  const y = Math.min(e.clientY, window.innerHeight - 150);
  menu.style.left = x + 'px';
  menu.style.top  = y + 'px';
  document.body.appendChild(menu);
  // Dismiss on any click outside
  setTimeout(() => document.addEventListener('click', _ytHideQueueContextMenu, { once: true }), 0);
}

function _ytHideQueueContextMenu() {
  const m = document.getElementById('ytQueueCtx');
  if (m) m.remove();
}

// "Play now" from context menu: remove from queue, play directly (clears played history)
function _ytQueuePlayNow(i) {
  _ytHideQueueContextMenu();
  const item = _ytQueue.splice(i, 1)[0];
  if (!item) return;
  _ytQueueSelected.delete(i);
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  openYtPlayer(item.title, item.artist, item.album, item.btn || null);
}

// ── #9: Multi-select mode ─────────────────────────────────────────────────────
function _ytToggleQueueMultiSelect() {
  _ytQueueMultiSelect = !_ytQueueMultiSelect;
  if (!_ytQueueMultiSelect) { _ytQueueSelected = new Set(); _ytQueueLastChecked = null; }
  _ytUpdateQueueDisplay();
}

function _ytQueueCheckbox(i, e) {
  // Shift+click extends the selection range from the last-checked item
  if (e.shiftKey && _ytQueueLastChecked !== null) {
    const lo = Math.min(i, _ytQueueLastChecked);
    const hi = Math.max(i, _ytQueueLastChecked);
    const addMode = _ytQueueSelected.has(_ytQueueLastChecked);
    for (let k = lo; k <= hi; k++) {
      if (addMode) _ytQueueSelected.add(k);
      else         _ytQueueSelected.delete(k);
    }
  } else {
    if (_ytQueueSelected.has(i)) _ytQueueSelected.delete(i);
    else                          _ytQueueSelected.add(i);
    _ytQueueLastChecked = i;
  }
  _ytUpdateQueueDisplay();
}

function _ytDeleteSelected() {
  // Delete from highest index down to preserve lower indices
  [..._ytQueueSelected].sort((a, b) => b - a).forEach(i => _ytQueue.splice(i, 1));
  _ytQueueSelected    = new Set();
  _ytQueueLastChecked = null;
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

function _ytMoveSelectedToTop() {
  const sorted = [..._ytQueueSelected].sort((a, b) => a - b);
  const items  = sorted.map(i => _ytQueue[i]);
  // Remove from end to keep earlier indices valid
  [..._ytQueueSelected].sort((a, b) => b - a).forEach(i => _ytQueue.splice(i, 1));
  _ytQueue.unshift(...items); // restore at top in original order
  _ytQueueSelected    = new Set();
  _ytQueueLastChecked = null;
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// ── #11: Count badge on the queue toggle button ───────────────────────────────
function _ytUpdateQueueBadge() {
  const badge = document.getElementById('ytQueueBadge');
  if (!badge) return;
  const count = _ytQueue.length;
  if (count > 0) {
    badge.textContent  = count > 99 ? '99+' : count;
    badge.style.display = '';
  } else {
    badge.style.display = 'none';
  }
}

// ── #11: Toggle queue panel open / closed ─────────────────────────────────────
function _ytToggleQueue() {
  _ytQueueHidden = !_ytQueueHidden;
  const btn = document.getElementById('ytQueueBtn');
  if (btn) btn.classList.toggle('yt-ctrl-active', !_ytQueueHidden);
  _ytUpdateQueueDisplay();
}

// ── #14: Collapsed count badge ────────────────────────────────────────────────
function _ytUpdateCollapsedCount() {
  const el     = document.getElementById('ytQueueCollapsedCount');
  const player = document.getElementById('ytMiniPlayer');
  if (!el || !player) return;
  const count     = _ytQueue.length;
  const collapsed = player.classList.contains('yt-mini-collapsed');
  if (collapsed && count > 0) {
    el.textContent = `+${count} queued`;
    el.style.display = 'block';
  } else {
    el.style.display = 'none';
  }
}

function _ytClampToViewport() {
  const player = document.getElementById('ytMiniPlayer');
  if (!player || player.style.display === 'none') return;
  const r  = player.getBoundingClientRect();
  const vw = window.innerWidth, vh = window.innerHeight;
  const nl = Math.max(12, Math.min(r.left, vw - r.width  - 12));
  const nt = Math.max(12, Math.min(r.top,  vh - r.height - 12));
  player.style.left   = nl + 'px';
  player.style.top    = nt + 'px';
  player.style.bottom = 'auto';
  player.style.right  = 'auto';
  try { localStorage.setItem('yt-player-pos', JSON.stringify({ left: nl, top: nt })); } catch(e) {}
}

function _ytInitDrag() {
  const player = document.getElementById('ytMiniPlayer');
  if (!player) return;
  try {
    const saved = localStorage.getItem('yt-player-pos');
    if (saved) {
      const { left, top } = JSON.parse(saved);
      const vw = window.innerWidth, vh = window.innerHeight;
      // Discard stale positions that are too close to any edge; fall back to CSS bottom-right default
      const safeTop  = Math.max(12, Math.min(top,  vh - 120));
      const safeLeft = Math.max(12, Math.min(left, vw - 200));
      if (top >= 60 && top < vh - 60) {
        player.style.left   = safeLeft + 'px';
        player.style.top    = safeTop  + 'px';
        player.style.bottom = 'auto';
        player.style.right  = 'auto';
      } else {
        localStorage.removeItem('yt-player-pos');
      }
    }
  } catch(e) {}
  // Re-clamp whenever the player grows (panels opening, queue items, etc.)
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(() => { if (!dragging) _ytClampToViewport(); }).observe(player);
  }
  const handle = player.querySelector('.yt-mini-drag-handle');
  if (!handle) return;
  let dragging = false, sx, sy, sl, st;
  function _savePos() {
    const r  = player.getBoundingClientRect();
    const vw = window.innerWidth, vh = window.innerHeight;
    const nl = Math.max(12, Math.min(r.left, vw - r.width  - 12));
    const nt = Math.max(12, Math.min(r.top,  vh - r.height - 12));
    player.style.left = nl + 'px';
    player.style.top  = nt + 'px';
    try { localStorage.setItem('yt-player-pos', JSON.stringify({ left: nl, top: nt })); } catch(e) {}
  }
  handle.addEventListener('mousedown', e => {
    dragging = true;
    const r = player.getBoundingClientRect();
    sx = e.clientX; sy = e.clientY; sl = r.left; st = r.top;
    player.style.right = 'auto'; player.style.bottom = 'auto';
    e.preventDefault();
  });
  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    player.style.left = (sl + e.clientX - sx) + 'px';
    player.style.top  = (st + e.clientY - sy) + 'px';
  });
  document.addEventListener('mouseup', () => { if (!dragging) return; dragging = false; _savePos(); });
  handle.addEventListener('touchstart', e => {
    const t = e.touches[0]; dragging = true;
    const r = player.getBoundingClientRect();
    sx = t.clientX; sy = t.clientY; sl = r.left; st = r.top;
    player.style.right = 'auto'; player.style.bottom = 'auto';
  }, { passive: false });
  document.addEventListener('touchmove', e => {
    if (!dragging) return;
    const t = e.touches[0];
    player.style.left = (sl + t.clientX - sx) + 'px';
    player.style.top  = (st + t.clientY - sy) + 'px';
    e.preventDefault();
  }, { passive: false });
  document.addEventListener('touchend', () => { if (!dragging) return; dragging = false; _savePos(); });
}

// Keyboard shortcuts when mini player is visible and no input is focused
document.addEventListener('keydown', e => {
  const playerEl = document.getElementById('ytMiniPlayer');
  if (!playerEl || playerEl.style.display === 'none') return;
  const tag = document.activeElement && document.activeElement.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (document.activeElement && document.activeElement.isContentEditable)) return;
  const key = e.key;
  if (e.code === 'Space')              { e.preventDefault(); _ytPauseToggle(); }
  else if (key === 'n' || key === 'N') { e.preventDefault(); _ytSkip(); }
  else if (key === 'ArrowLeft')        { e.preventDefault(); if (_ytPlayer) { try { _ytPlayer.seekTo(Math.max(0, _ytPlayer.getCurrentTime() - 10), true); } catch(ex) {} } }
  else if (key === 'ArrowRight')       { e.preventDefault(); if (_ytPlayer) { try { _ytPlayer.seekTo(_ytPlayer.getCurrentTime() + 10, true); } catch(ex) {} } }
  else if (key === 'ArrowUp')          { e.preventDefault(); _ytSetVolume(_ytVolume + 5); }
  else if (key === 'ArrowDown')        { e.preventDefault(); _ytSetVolume(_ytVolume - 5); }
  else if (key === 'r' || key === 'R') { e.preventDefault(); _ytCycleRepeat(); }
  else if (key === 'f' || key === 'F') { e.preventDefault(); _ytToggleSearch(); }
  else if (key === 'h' || key === 'H') { e.preventDefault(); _ytToggleHistory(); }
  else if (key === 'l' || key === 'L') { e.preventDefault(); _ytToggleLyrics(); }
  else if (key === 't' || key === 'T') { e.preventDefault(); _ytToggleSleep(); }
  else if (key === 's' || key === 'S') { e.preventDefault(); _ytCycleSpeed(); }
  else if (key === '?')                { e.preventDefault(); _ytToggleShortcuts(); }
  else if (key === 'Escape')           { e.preventDefault(); closeYtPlayer(); }
});

// Scroll wheel on mini player changes volume (but not when scrolling the queue list)
document.addEventListener('wheel', e => {
  const playerEl = document.getElementById('ytMiniPlayer');
  if (!playerEl || playerEl.style.display === 'none') return;
  if (!playerEl.contains(e.target)) return;
  const queueEl = document.getElementById('ytMiniQueue');
  if (queueEl && queueEl.contains(e.target)) return;
  const lyricsEl = document.getElementById('ytLyricsPanel');
  if (lyricsEl && lyricsEl.contains(e.target)) return;
  e.preventDefault();
  _ytSetVolume(_ytVolume + (e.deltaY < 0 ? 5 : -5));
}, { passive: false });

// Load persisted queue, volume, and repeat state on page load
_ytLoadQueue();
_ytUpdateRepeatBtn();
_ytLoadPlaylists();
_ytUpdateSpeedBtn();
_ytUpdateCrossfadeBtn();
_ytUpdateScrobbleThresholdBtn();
try {
  const sv = localStorage.getItem('yt-volume');
  if (sv !== null) { _ytVolume = Math.max(0, Math.min(100, parseInt(sv))); }
} catch(e) {}

// Restore last-playing track from previous session
try {
  const savedTrack = localStorage.getItem('yt-player-current');
  if (savedTrack) {
    const track = JSON.parse(savedTrack);
    if (track && track.title) {
      _ytCurrentTrack = track;
      const player = document.getElementById('ytMiniPlayer');
      if (player) {
        player.style.display = '';
        const titleEl  = document.getElementById('ytMiniTitle');
        const artistEl = document.getElementById('ytMiniArtist');
        const statusEl = document.getElementById('ytMiniStatus');
        const pauseBtn = document.getElementById('ytMiniPauseBtn');
        if (titleEl)  titleEl.textContent  = track.title;
        if (artistEl) artistEl.textContent = track.artist || '';
        if (statusEl) { statusEl.textContent = 'Tap ▶ to resume'; statusEl.className = 'yt-mini-status'; }
        if (pauseBtn) { pauseBtn.innerHTML = _YT_IC.play; pauseBtn.title = 'Play'; }
        if (!_ytDragInitialized) { _ytDragInitialized = true; _ytInitDrag(); }
        _ytLoadVolume();
        requestAnimationFrame(_ytClampToViewport);
      }
    }
  }
} catch(e) {}

// ── NEW PLAYER FEATURES ───────────────────────────────────────────────────

// ── 1. Sleep timer ────────────────────────────────────────────────
function _ytToggleSleep() {
  const panel = document.getElementById('ytSleepPanel');
  if (!panel) return;
  const visible = panel.style.display !== 'none';
  _ytCloseExtraPanels(['ytSleepPanel']);
  panel.style.display = visible ? 'none' : 'block';
  const btn = document.getElementById('ytSleepBtn');
  if (btn) btn.classList.toggle('yt-ctrl-active', !visible && _ytSleepRemaining === 0);
}

function _ytStartSleep(minutes) {
  clearInterval(_ytSleepInterval);
  _ytSleepRemaining = minutes * 60;
  _ytSleepInterval  = setInterval(() => {
    _ytSleepRemaining--;
    _ytUpdateSleepBtn();
    if (_ytSleepRemaining <= 0) {
      clearInterval(_ytSleepInterval); _ytSleepInterval = null; _ytSleepRemaining = 0;
      _ytUpdateSleepBtn();
      if (_ytPlayer) { try { _ytPlayer.pauseVideo(); } catch(e) {} }
    }
  }, 1000);
  _ytUpdateSleepBtn();
  const panel = document.getElementById('ytSleepPanel');
  if (panel) panel.style.display = 'none';
}

function _ytCancelSleep() {
  clearInterval(_ytSleepInterval); _ytSleepInterval = null; _ytSleepRemaining = 0;
  _ytUpdateSleepBtn();
  const panel = document.getElementById('ytSleepPanel');
  if (panel) panel.style.display = 'none';
  const btn = document.getElementById('ytSleepBtn');
  if (btn) btn.classList.remove('yt-ctrl-active');
}

function _ytUpdateSleepBtn() {
  const btn   = document.getElementById('ytSleepBtn');
  const badge = document.getElementById('ytSleepBadge');
  if (!btn) return;
  if (_ytSleepRemaining > 0) {
    btn.classList.add('yt-ctrl-active');
    const m = Math.ceil(_ytSleepRemaining / 60);
    if (badge) { badge.textContent = m + 'm'; badge.style.display = ''; }
    btn.title = `Sleep in ${m}m (click to edit)`;
  } else {
    btn.classList.remove('yt-ctrl-active');
    if (badge) badge.style.display = 'none';
    btn.title = 'Sleep timer [T]';
  }
}

// ── 2. Crossfade ──────────────────────────────────────────────────
const _YT_CROSSFADE_OPTIONS = [0, 3, 5, 8];

function _ytCycleCrossfade() {
  const idx    = _YT_CROSSFADE_OPTIONS.indexOf(_ytCrossfade);
  _ytCrossfade = _YT_CROSSFADE_OPTIONS[(idx + 1) % _YT_CROSSFADE_OPTIONS.length];
  try { localStorage.setItem('yt-crossfade', _ytCrossfade); } catch(e) {}
  _ytUpdateCrossfadeBtn();
}

function _ytUpdateCrossfadeBtn() {
  const btn = document.getElementById('ytCrossfadeBtn');
  if (!btn) return;
  btn.textContent = _ytCrossfade === 0 ? 'Off' : `${_ytCrossfade}s`;
  btn.classList.toggle('yt-setting-active', _ytCrossfade > 0);
}

function _ytStartFadeOut() {
  if (!_ytPlayer) return;
  clearInterval(_ytCrossfadeRamp);
  const startVol = _ytVolume;
  const steps    = _ytCrossfade * 10;
  let   done     = 0;
  _ytCrossfadeRamp = setInterval(() => {
    done++;
    const newVol = Math.max(0, Math.round(startVol * (1 - done / steps)));
    try { if (_ytPlayer) _ytPlayer.setVolume(newVol); } catch(e) {}
    if (done >= steps) { clearInterval(_ytCrossfadeRamp); _ytCrossfadeRamp = null; }
  }, 100);
}

function _ytStartFadeIn() {
  if (!_ytPlayer) return;
  clearInterval(_ytCrossfadeRamp);
  try { _ytPlayer.setVolume(0); } catch(e) {}
  const targetVol = _ytVolume;
  const steps     = _ytCrossfade * 10;
  let   done      = 0;
  _ytCrossfadeRamp = setInterval(() => {
    done++;
    const newVol = Math.min(targetVol, Math.round(targetVol * done / steps));
    try { if (_ytPlayer) _ytPlayer.setVolume(newVol); } catch(e) {}
    if (done >= steps) {
      clearInterval(_ytCrossfadeRamp); _ytCrossfadeRamp = null;
      try { if (_ytPlayer) _ytPlayer.setVolume(targetVol); } catch(e) {}
    }
  }, 100);
}

// ── 3. Lyrics panel ───────────────────────────────────────────────
function _ytToggleLyrics() {
  const el  = document.getElementById('ytLyricsPanel');
  const btn = document.getElementById('ytLyricsBtn');
  if (!el) return;
  const visible = el.style.display !== 'none';
  _ytCloseExtraPanels(['ytLyricsPanel']);
  el.style.display = visible ? 'none' : 'block';
  if (btn) btn.classList.toggle('yt-ctrl-active', !visible);
  if (!visible) _ytFetchLyrics();
}

async function _ytFetchLyrics() {
  const el = document.getElementById('ytLyricsPanel');
  if (!el || !_ytCurrentTrack) return;
  const { artist, title } = _ytCurrentTrack;
  const key = artist + '|||' + title;
  if (_ytLyricsCache[key]) { el.innerHTML = _ytLyricsCache[key]; return; }
  el.innerHTML = '<div class="yt-lyrics-loading">Loading lyrics…</div>';
  try {
    const res  = await fetch(`https://api.lyrics.ovh/v1/${encodeURIComponent(artist)}/${encodeURIComponent(title)}`);
    const data = await res.json();
    if (data.lyrics) {
      const html = `<div class="yt-lyrics-text">${esc(data.lyrics).replace(/\n/g, '<br>')}</div>`;
      _ytLyricsCache[key] = html;
      el.innerHTML = html;
    } else {
      el.innerHTML = '<div class="yt-lyrics-empty">No lyrics found</div>';
    }
  } catch(e) {
    el.innerHTML = '<div class="yt-lyrics-empty">Lyrics unavailable</div>';
  }
}

// ── 4. Scrobble threshold ─────────────────────────────────────────
const _YT_SCROBBLE_OPTIONS = ['30s', '50%', '70%', 'end'];

function _ytCycleScrobbleThreshold() {
  const idx            = _YT_SCROBBLE_OPTIONS.indexOf(_ytScrobbleThreshold);
  _ytScrobbleThreshold = _YT_SCROBBLE_OPTIONS[(idx + 1) % _YT_SCROBBLE_OPTIONS.length];
  try { localStorage.setItem('yt-scrobble-threshold', _ytScrobbleThreshold); } catch(e) {}
  _ytUpdateScrobbleThresholdBtn();
}

function _ytUpdateScrobbleThresholdBtn() {
  const btn = document.getElementById('ytScrobbleThresholdBtn');
  if (btn) btn.textContent = _ytScrobbleThreshold;
}

// ── 6. Named playlists ────────────────────────────────────────────
function _ytLoadPlaylists() {
  try { const s = localStorage.getItem('yt-playlists'); if (s) _ytPlaylists = JSON.parse(s); } catch(e) { _ytPlaylists = {}; }
  try { const s = localStorage.getItem('yt-playlists-modified'); _ytPlaylistModified = s ? JSON.parse(s) : {}; } catch(e) { _ytPlaylistModified = {}; }
  try { const s = localStorage.getItem('yt-playlists-deleted'); _ytDeletedPlaylists = s ? JSON.parse(s) : {}; } catch(e) { _ytDeletedPlaylists = {}; }
}

// Call whenever a playlist is created or its contents/order change, so a later merge
// can tell a genuine recreation/edit apart from a stale copy that never received a
// remote deletion (see _ytMergePlaylists).
function _ytTouchPlaylist(name) {
  _ytPlaylistModified[name] = Date.now();
  delete _ytDeletedPlaylists[name];
}

// Call whenever a playlist is deleted, so the deletion propagates correctly even if
// another device still has a stale local copy (see _ytMergePlaylists).
function _ytMarkPlaylistDeleted(name) {
  delete _ytPlaylists[name];
  delete _ytPlaylistModified[name];
  _ytDeletedPlaylists[name] = Date.now();
}

function _ytSavePlaylists() {
  const json = JSON.stringify(_ytPlaylists);
  const modifiedJson = JSON.stringify(_ytPlaylistModified);
  const deletedJson = JSON.stringify(_ytDeletedPlaylists);
  try {
    localStorage.setItem('yt-playlists', json);
    localStorage.setItem('yt-playlists-modified', modifiedJson);
    localStorage.setItem('yt-playlists-deleted', deletedJson);
  } catch(e) {}
  // Sync to Firestore if the user is logged in
  if (typeof dcSavePlaylistsToFirestore === 'function') dcSavePlaylistsToFirestore(json, modifiedJson, deletedJson);
}

// Merge remote (Firestore) playlists with local ones. A name is kept if its most
// recent local-or-remote action was a create/edit; it's dropped if its most recent
// action was a delete — so a deletion on one device isn't undone by a stale copy
// that another device never received the delete for.
function _ytMergePlaylists(remote) {
  try {
    const remotePlaylists = JSON.parse(remote.data || '{}');
    const remoteModified  = remote.modified ? JSON.parse(remote.modified) : {};
    const remoteDeleted   = remote.deleted  ? JSON.parse(remote.deleted)  : {};

    const mergedModified = Object.assign({}, remoteModified);
    for (const [name, ts] of Object.entries(_ytPlaylistModified)) {
      if (!mergedModified[name] || ts > mergedModified[name]) mergedModified[name] = ts;
    }
    const mergedDeleted = Object.assign({}, remoteDeleted);
    for (const [name, ts] of Object.entries(_ytDeletedPlaylists)) {
      if (!mergedDeleted[name] || ts > mergedDeleted[name]) mergedDeleted[name] = ts;
    }

    const mergedPlaylists = Object.assign({}, remotePlaylists, _ytPlaylists); // local wins on same-name conflict
    for (const name of Object.keys(mergedPlaylists)) {
      const deletedAt = mergedDeleted[name] || 0;
      const modifiedAt = mergedModified[name] || 0;
      if (deletedAt > modifiedAt) delete mergedPlaylists[name];
    }
    for (const name of Object.keys(mergedDeleted)) {
      if (!(name in mergedPlaylists)) delete mergedDeleted[name]; // nothing left to remember deleting
    }

    _ytPlaylists = mergedPlaylists;
    _ytPlaylistModified = mergedModified;
    _ytDeletedPlaylists = mergedDeleted;
    try {
      localStorage.setItem('yt-playlists', JSON.stringify(_ytPlaylists));
      localStorage.setItem('yt-playlists-modified', JSON.stringify(_ytPlaylistModified));
      localStorage.setItem('yt-playlists-deleted', JSON.stringify(_ytDeletedPlaylists));
    } catch(e) {}
    // Push the merged result back so every device converges on the same state
    if (typeof dcSavePlaylistsToFirestore === 'function') {
      dcSavePlaylistsToFirestore(JSON.stringify(_ytPlaylists), JSON.stringify(_ytPlaylistModified), JSON.stringify(_ytDeletedPlaylists));
    }
    // Refresh the player panel if it's open
    const panel = document.getElementById('ytPlaylistsPanel');
    if (panel && panel.style.display !== 'none') _ytRenderPlaylists();
    // Refresh the full manager view if it's the active tab
    if (typeof currentPeriod !== 'undefined' && currentPeriod === 'playlists') dcRenderPlaylistsView();
  } catch(e) { console.warn('[dankcharts] Playlist merge error:', e); }
}

function _ytTogglePlaylists() {
  const el  = document.getElementById('ytPlaylistsPanel');
  const btn = document.getElementById('ytPlaylistsBtn');
  if (!el) return;
  const visible = el.style.display !== 'none';
  _ytCloseExtraPanels(['ytPlaylistsPanel']);
  el.style.display = visible ? 'none' : 'block';
  if (btn) btn.classList.toggle('yt-ctrl-active', !visible);
  if (!visible) _ytRenderPlaylists();
}

function _ytRenderPlaylists() {
  const el = document.getElementById('ytPlaylistsPanel');
  if (!el) return;
  const names = Object.keys(_ytPlaylists);
  let html = `<div class="yt-pl-save-row">` +
    `<input id="ytPlNewName" class="yt-pl-name-input" type="text" placeholder="Playlist name…" maxlength="40" onkeydown="if(event.key==='Enter')_ytSaveCurrentQueue(this.value.trim())">` +
    `<button class="yt-pl-save-btn" onclick="_ytSaveCurrentQueue(document.getElementById('ytPlNewName').value.trim())">Save</button>` +
    `</div>`;
  if (names.length === 0) {
    html += '<div class="yt-pl-empty">No saved playlists</div>';
  } else {
    html += names.map(n =>
      `<div class="yt-pl-item">` +
      `<button class="yt-pl-load-btn" onclick="_ytLoadPlaylist(${JSON.stringify(n)})" title="Load">${esc(n)}</button>` +
      `<span class="yt-pl-count">${_ytPlaylists[n].length}</span>` +
      `<button class="yt-pl-del-btn" onclick="_ytDeletePlaylist(${JSON.stringify(n)})" title="Delete">✕</button>` +
      `</div>`
    ).join('');
  }
  el.innerHTML = html;
}

function _ytSaveCurrentQueue(name) {
  if (!name) return;
  const tracks = [];
  if (_ytCurrentTrack) tracks.push({ title: _ytCurrentTrack.title, artist: _ytCurrentTrack.artist, album: _ytCurrentTrack.album });
  _ytQueue.forEach(t => tracks.push({ title: t.title, artist: t.artist, album: t.album }));
  if (!tracks.length) return;
  _ytPlaylists[name] = tracks;
  _ytTouchPlaylist(name);
  _ytSavePlaylists();
  _ytRenderPlaylists();
  // Also refresh the full manager view if it's the active tab
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'playlists') dcRenderPlaylistsView();
}

function _ytLoadPlaylist(name) {
  const pl = _ytPlaylists[name];
  if (!pl || !pl.length) return;
  const [first, ...rest] = pl;
  openYtPlayer(first.title, first.artist, first.album, null);
  rest.forEach(t => _ytQueue.push({ title: t.title, artist: t.artist, album: t.album, btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  _ytTogglePlaylists();
}

function _ytDeletePlaylist(name) {
  _ytMarkPlaylistDeleted(name);
  _ytSavePlaylists();
  _ytRenderPlaylists();
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'playlists') dcRenderPlaylistsView();
}

// ── Add to Playlist — the shared picker ────────────────────────────────────
// Every surface that shows songs (Time Machine, the YouTube buttons on the
// charts, the events sections, the Soundtrack reels) stages its tracks here
// instead of pushing them straight into the player queue. One modal covers both
// halves of the flow: dropping tracks into a playlist that already exists, and
// creating a new one from them. Playlists live in _ytPlaylists, so anything
// saved here shows up in the Playlists tab and syncs to Firestore for free.

let _dcPickTracks  = [];  // tracks staged for the picker: {title, artist, album}
let _dcPickLabel   = '';  // where they came from, shown under the modal title
let _dcPickSuggest = '';  // pre-filled name on the create-new view

// How many past songs an artist/album card contributes when it's added on its
// own. Entity cards have no track of their own, so we reach into play history.
const DC_PL_ENTITY_LIMIT = 25;

// Same identity rule the queue uses — artist + title, case-insensitive. Album is
// deliberately left out: the same song reached from a chart row and from an
// album card carries different album text and is still the same song.
function _dcPickKey(tr) {
  return (tr.artist || '').toLowerCase() + '|||' + (tr.title || '').toLowerCase();
}

// Drops blanks and repeats while keeping the order the caller handed us, and
// normalises the '—' album placeholder away so it never reaches a playlist.
function _dcPickDedupe(tracks) {
  const seen = new Set();
  const out  = [];
  for (const tr of (tracks || [])) {
    if (!tr || !tr.title) continue;
    const clean = {
      title:  tr.title,
      artist: tr.artist || '',
      album:  (tr.album && tr.album !== '—') ? tr.album : ''
    };
    const k = _dcPickKey(clean);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(clean);
  }
  return out;
}

// Songs to stage for a card, by what kind of thing the card is. Artists and
// albums resolve to what the user has actually played; a release with no plays
// yet (a brand-new single, an anniversary for an album that never got a spin)
// falls back to its own title, which is exactly what a search would look up.
function dcPlTracksFor(kind, title, artist, album) {
  if (kind === 'artist') return _tmArtistLastSongs(artist, DC_PL_ENTITY_LIMIT);
  if (kind === 'album') {
    const played = _tmAlbumLastSongs(album, artist, DC_PL_ENTITY_LIMIT);
    return played.length ? played : [{ title: album, artist, album }];
  }
  return [{ title, artist, album: album || '' }];
}

// Entry point for every caller. `label` names the source ("Time Machine",
// "Artist Birthdays"); `suggest` seeds the new-playlist name box.
function dcOpenPlaylistPicker(tracks, label, suggest) {
  const list = _dcPickDedupe(tracks);
  if (!list.length) { dcPlToast(t('pl_pick_nothing')); return; }
  _dcPickTracks  = list;
  _dcPickLabel   = label || '';
  _dcPickSuggest = suggest || label || '';
  const modal = document.getElementById('dcPlPickModal');
  if (!modal) return;
  const sub = document.getElementById('dcPlPickSub');
  if (sub) sub.textContent = tCount('songs', list.length) + (_dcPickLabel ? ' · ' + _dcPickLabel : '');
  _dcPickRenderList();
  modal.classList.add('open');
}

function dcClosePlaylistPicker() {
  const modal = document.getElementById('dcPlPickModal');
  if (modal) modal.classList.remove('open');
  _dcPickTracks = [];
}

// View 1 — pick an existing playlist, or step over to creating a new one.
function _dcPickRenderList() {
  const body = document.getElementById('dcPlPickBody');
  if (!body) return;
  const names = Object.keys(_ytPlaylists);
  const staged = new Set(_dcPickTracks.map(_dcPickKey));

  let html = `<button class="dc-plpick-new" onclick="_dcPickShowNew()">＋ ${esc(t('pl_pick_new'))}</button>`;

  if (!names.length) {
    html += `<div class="dc-plpick-empty">${esc(t('pl_pick_none_yet'))}</div>`;
  } else {
    html += `<div class="dc-plpick-list">` + names.map(n => {
      // How many of the staged tracks this playlist doesn't have yet — so the
      // user can see at a glance that a second click would be a no-op.
      const have = new Set((_ytPlaylists[n] || []).map(_dcPickKey));
      let fresh = 0;
      staged.forEach(k => { if (!have.has(k)) fresh++; });
      const full = fresh === 0;
      return `<button class="dc-plpick-item${full ? ' dc-plpick-item-full' : ''}" onclick="_dcPickAddTo(${esc(JSON.stringify(n))})">` +
        `<span class="dc-plpick-item-name">${esc(n)}</span>` +
        `<span class="dc-plpick-item-count">${_ytPlaylists[n].length}</span>` +
        `<span class="dc-plpick-item-add">${full ? '✓' : '+' + fresh}</span>` +
        `</button>`;
    }).join('') + `</div>`;
  }
  body.innerHTML = html;
}

// View 2 — name and create a brand-new playlist from the staged tracks.
function _dcPickShowNew() {
  const body = document.getElementById('dcPlPickBody');
  if (!body) return;
  body.innerHTML =
    `<button class="dc-plpick-back" onclick="_dcPickRenderList()">‹ ${esc(t('pl_pick_back'))}</button>` +
    `<input class="dc-plpick-input" id="dcPlPickName" type="text" maxlength="60" placeholder="${esc(t('pl_pick_name_ph'))}" ` +
    `onkeydown="if(event.key==='Enter')_dcPickCreate()">` +
    `<div class="dc-plpick-preview">` +
    _dcPickTracks.slice(0, 5).map(tr =>
      `<div class="dc-plpick-preview-row">${esc(tr.title)}${tr.artist ? ` <span>· ${esc(tr.artist)}</span>` : ''}</div>`
    ).join('') +
    (_dcPickTracks.length > 5 ? `<div class="dc-plpick-preview-more">+ ${_dcPickTracks.length - 5}…</div>` : '') +
    `</div>` +
    `<button class="dc-plpick-create" onclick="_dcPickCreate()">✓ ${esc(t('pl_pick_create'))}</button>`;
  const input = document.getElementById('dcPlPickName');
  if (input) { input.value = _dcPickSuggest.slice(0, 60); setTimeout(() => input.select(), 60); }
}

// Persist + refresh every surface that shows playlists. Mirrors what
// _ytSaveCurrentQueue does after it writes a playlist.
function _dcPickCommit(name) {
  _ytTouchPlaylist(name);
  _ytSavePlaylists();
  _ytRenderPlaylists();
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'playlists') dcRenderPlaylistsView();
}

function _dcPickAddTo(name) {
  const existing = _ytPlaylists[name];
  if (!existing) return;
  const have  = new Set(existing.map(_dcPickKey));
  const fresh = _dcPickTracks.filter(tr => !have.has(_dcPickKey(tr)));
  if (!fresh.length) {
    dcPlToast(t('pl_pick_all_dupes', { name }));
    dcClosePlaylistPicker();
    return;
  }
  const skipped = _dcPickTracks.length - fresh.length;
  _ytPlaylists[name] = existing.concat(fresh);
  _dcPickCommit(name);
  dcPlToast(
    t(fresh.length === 1 ? 'pl_pick_added_one' : 'pl_pick_added_other', { n: fresh.length, name }) +
    (skipped ? ' · ' + t('pl_pick_skipped', { n: skipped }) : '')
  );
  dcClosePlaylistPicker();
}

function _dcPickCreate() {
  const input = document.getElementById('dcPlPickName');
  if (!input) return;
  const name = input.value.trim();
  if (!name) { input.focus(); return; }
  // Typing the name of a playlist that already exists merges into it rather than
  // silently replacing it — losing a playlist to a name collision would be worse
  // than the small surprise of an append.
  if (_ytPlaylists[name]) { _dcPickAddTo(name); return; }
  const n = _dcPickTracks.length;
  _ytPlaylists[name] = _dcPickTracks.slice();
  _dcPickCommit(name);
  dcPlToast(t('pl_pick_created', { name, songs: tCount('songs', n) }));
  dcClosePlaylistPicker();
}

// Small self-mounting toast. The player's own status line (#ytMiniStatus) is no
// good here: these actions deliberately don't open the player, so its status
// line is usually off screen.
let _dcPlToastTimer = null;
function dcPlToast(msg) {
  let el = document.getElementById('dcPlToast');
  if (!el) {
    el = document.createElement('div');
    el.id = 'dcPlToast';
    el.className = 'dc-pl-toast';
    document.body.appendChild(el);
  }
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(_dcPlToastTimer);
  _dcPlToastTimer = setTimeout(() => el.classList.remove('show'), 3200);
}

// ── The ＋ button that sits next to a play button or on a card ──────────────
// One markup helper for every call site, so the data-attribute contract and the
// event-swallowing (cards below are often links or have their own onclick) live
// in exactly one place.
const DC_PL_ICON = '<svg class="dc-pl-add-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M14 10H2v2h12v-2zm0-4H2v2h12V6zm4 8v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zM2 16h8v-2H2v2z"/></svg>';

function dcPlBtnHtml(kind, title, artist, album, extraCls) {
  const lbl = t('pl_add_btn_title');
  return '<button class="dc-pl-add-btn' + (extraCls ? ' ' + extraCls : '') + '"' +
    ' data-plkind="'   + esc(kind)         + '"' +
    ' data-pltitle="'  + esc(title  || '') + '"' +
    ' data-plartist="' + esc(artist || '') + '"' +
    ' data-plalbum="'  + esc(album  || '') + '"' +
    ' onclick="event.preventDefault();event.stopPropagation();dcPlBtnClick(this)"' +
    ' title="' + esc(lbl) + '" aria-label="' + esc(lbl) + '">' + DC_PL_ICON + '</button>';
}

// A chart section's type ('songs'/'artists'/'albums') → the picker's kind.
function dcPlKindFor(type) {
  return type === 'artists' ? 'artist' : type === 'albums' ? 'album' : 'song';
}

// The ▶ buttons in the weekly view's Card Grid, Coverflow and Stack layouts are
// those layouts' play buttons — the same role the YouTube button plays in the
// table — so they carry the same option. Those three build their cards from the
// same `ttl`/`sub` pair: for a song that's title + artist, for an artist the
// name is the title, and for an album it's the album + its artist.
function dcPlBtnForWv(type, ttl, sub, album, extraCls) {
  if (type === 'artists') return dcPlBtnHtml('artist', '', ttl, '', extraCls);
  if (type === 'albums')  return dcPlBtnHtml('album', ttl, sub, album || ttl, extraCls);
  return dcPlBtnHtml('song', ttl, sub, album || '', extraCls);
}

function dcPlBtnClick(btn) {
  const kind   = btn.dataset.plkind;
  const title  = btn.dataset.pltitle;
  const artist = btn.dataset.plartist;
  const album  = btn.dataset.plalbum;
  const label  = kind === 'artist' ? artist : (title || album);
  dcOpenPlaylistPicker(dcPlTracksFor(kind, title, artist, album), label, label);
}

// Today's date, short — the tail of every suggested playlist name.
function _dcPlDateTag() {
  return tzNow().toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

// ── Full Playlist Manager View ─────────────────────────────────────────────

let _dcPlExpandedName = null; // name of the playlist currently expanded in the manager
let _dcPlDragSrc      = null; // index of the track being dragged for reorder

function dcRenderPlaylistsView() {
  const el = document.getElementById('playlistsView');
  if (!el) return;
  const names = Object.keys(_ytPlaylists);

  // Header with title, optional resume row, and save-current-queue form
  let html = `<div class="dc-pl-view">` +
    `<div class="dc-pl-header">` +
    `<h2 class="dc-pl-title">My Playlists</h2>`;

  // Resume row: show if a track was playing (this session or restored from a prior session)
  if (_ytCurrentTrack && _ytCurrentTrack.title) {
    const resumeLabel = esc(_ytCurrentTrack.title) + (_ytCurrentTrack.artist ? ` – ${esc(_ytCurrentTrack.artist)}` : '');
    html +=
      `<div class="dc-pl-resume-row">` +
      `<button class="dc-pl-resume-btn" onclick="dcPlResume()" title="Resume where you left off">▶ Resume: ${resumeLabel}</button>` +
      (_ytQueue.length > 0 ? `<span class="dc-pl-resume-hint">+ ${_ytQueue.length} in queue</span>` : '') +
      `</div>`;
  }

  html +=
    `<div class="dc-pl-save-row">` +
    `<input id="dcPlNewName" class="dc-pl-name-input" type="text" placeholder="Save current queue as…" maxlength="40" ` +
    `onkeydown="if(event.key==='Enter'){dcPlSaveQueue(this.value.trim());}">` +
    `<button class="dc-pl-save-btn" onclick="dcPlSaveQueue(document.getElementById('dcPlNewName').value.trim())">Save Queue</button>` +
    `<span id="dcPlStatus" class="dc-pl-status"></span>` +
    `</div>` +
    `</div>`;

  if (names.length === 0) {
    html += `<div class="dc-pl-empty-state">No saved playlists yet.<br>Start playing music and use the <strong>Save Queue</strong> button above (or the save icon in the player) to save your queue here.</div>`;
  } else {
    html += `<div class="dc-pl-list">`;
    names.forEach(name => {
      const tracks = _ytPlaylists[name];
      const isExpanded = _dcPlExpandedName === name;
      const nameEsc  = esc(name);
      const nameJson = esc(JSON.stringify(name)); // must escape " so it doesn't break the onclick="" attribute

      html += `<div class="dc-pl-card${isExpanded ? ' dc-pl-card-open' : ''}">` +
        `<div class="dc-pl-card-header" onclick="dcPlToggleExpand(${nameJson})">` +
        `<svg class="dc-pl-chevron${isExpanded ? ' dc-pl-chevron-open' : ''}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9,18 15,12 9,6"/></svg>` +
        `<span class="dc-pl-name">${nameEsc}</span>` +
        `<span class="dc-pl-count">${tracks.length} track${tracks.length !== 1 ? 's' : ''}</span>` +
        `<div class="dc-pl-actions" onclick="event.stopPropagation()">` +
        `<button class="dc-pl-play-btn" onclick="dcPlPlayFromStart(${nameJson})" title="Play playlist">` +
        `<svg class="dc-pl-ic" viewBox="0 0 24 24" fill="currentColor"><polygon points="5,3 19,12 5,21"/></svg>` +
        `</button>` +
        `<button class="dc-pl-rename-btn" onclick="dcPlStartRename(${nameJson})" title="Rename">` +
        `<svg class="dc-pl-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>` +
        `</button>` +
        `<button class="dc-pl-del-btn" onclick="dcPlDeleteFromView(${nameJson})" title="Delete playlist">` +
        `<svg class="dc-pl-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3,6 5,6 21,6"/><path d="M19,6l-1,14a2,2,0,0,1-2,2H8a2,2,0,0,1-2-2L5,6"/><path d="M10,11v6"/><path d="M14,11v6"/><path d="M9,6V4a1,1,0,0,1,1-1h4a1,1,0,0,1,1,1v2"/></svg>` +
        `</button>` +
        `</div>` +
        `</div>`; // end card-header

      if (isExpanded) {
        html += `<div class="dc-pl-tracks">`;
        tracks.forEach((t, idx) => {
          html += `<div class="dc-pl-track" draggable="true" ` +
            `ondragstart="event.stopPropagation();dcPlDragStart(event,${nameJson},${idx})" ` +
            `ondragover="event.preventDefault();event.currentTarget.classList.add('dc-pl-drag-over')" ` +
            `ondragleave="event.currentTarget.classList.remove('dc-pl-drag-over')" ` +
            `ondrop="dcPlDrop(event,${nameJson},${idx})">` +
            `<span class="dc-pl-drag-handle" title="Drag to reorder">⠿</span>` +
            `<div class="dc-pl-track-info">` +
            `<span class="dc-pl-track-title">${esc(t.title)}</span>` +
            `<span class="dc-pl-track-sep"> – </span>` +
            `<span class="dc-pl-track-artist">${esc(t.artist)}</span>` +
            `</div>` +
            `<div class="dc-pl-track-actions">` +
            `<button class="dc-pl-track-play-btn" onclick="dcPlPlayFromTrack(${nameJson},${idx})" title="Play from here">▶</button>` +
            `<button class="dc-pl-track-del-btn" onclick="dcPlRemoveTrack(${nameJson},${idx})" title="Remove track">✕</button>` +
            `</div>` +
            `</div>`; // end track
        });
        html += `</div>`; // end tracks
      }

      html += `</div>`; // end card
    });
    html += `</div>`; // end list
  }

  html += `</div>`; // end view
  el.innerHTML = html;
}

// Toggle a playlist's track list open/closed
function dcPlToggleExpand(name) {
  _dcPlExpandedName = _dcPlExpandedName === name ? null : name;
  dcRenderPlaylistsView();
}

// Load a playlist into the player (player floats over the page, no tab switch needed)
function dcPlPlayFromStart(name) {
  _ytLoadPlaylist(name);
}

// Play a playlist starting from a specific track index
function dcPlPlayFromTrack(name, idx) {
  const pl = _ytPlaylists[name];
  if (!pl || idx >= pl.length) return;
  const tracks = pl.slice(idx);
  const [first, ...rest] = tracks;
  openYtPlayer(first.title, first.artist, first.album, null);
  rest.forEach(t => _ytQueue.push({ title: t.title, artist: t.artist, album: t.album, btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

// Resume the last-played track (with queue already loaded from localStorage on startup)
function dcPlResume() {
  if (!_ytCurrentTrack || !_ytCurrentTrack.title) return;
  openYtPlayer(_ytCurrentTrack.title, _ytCurrentTrack.artist, _ytCurrentTrack.album, null);
}

// Replace the name span with an inline input to rename a playlist in-place
function dcPlStartRename(oldName) {
  const nameEls = document.querySelectorAll('.dc-pl-name');
  let targetEl = null;
  nameEls.forEach(el => { if (el.textContent === oldName) targetEl = el; });
  if (!targetEl) return;
  const input = document.createElement('input');
  input.type      = 'text';
  input.value     = oldName;
  input.maxLength = 40;
  input.className = 'dc-pl-name-edit';
  let confirmed = false;
  const doConfirm = () => {
    if (confirmed) return;
    confirmed = true;
    dcPlConfirmRename(oldName, input.value.trim());
  };
  input.addEventListener('blur',    doConfirm);
  input.addEventListener('click',   e => e.stopPropagation()); // don't collapse card
  input.addEventListener('keydown', e => {
    if (e.key === 'Enter')  { e.preventDefault(); doConfirm(); }
    if (e.key === 'Escape') { confirmed = true; dcRenderPlaylistsView(); }
  });
  targetEl.replaceWith(input);
  input.focus();
  input.select();
}

// Commit an in-place rename — rebuilds the playlist object to preserve order
function dcPlConfirmRename(oldName, newName) {
  if (!newName || newName === oldName) { dcRenderPlaylistsView(); return; }
  if (_ytPlaylists[newName] !== undefined) {
    if (!confirm(`A playlist named "${newName}" already exists. Overwrite it?`)) { dcRenderPlaylistsView(); return; }
  }
  const rebuilt = {};
  Object.keys(_ytPlaylists).forEach(k => {
    if (k === oldName)  rebuilt[newName] = _ytPlaylists[k];       // rename in-place
    else if (k !== newName) rebuilt[k]   = _ytPlaylists[k];       // skip old target (overwrite)
  });
  _ytPlaylists = rebuilt;
  _ytMarkPlaylistDeleted(oldName);
  _ytTouchPlaylist(newName);
  if (_dcPlExpandedName === oldName) _dcPlExpandedName = newName;
  _ytSavePlaylists();
  dcRenderPlaylistsView();
}

// Delete a playlist from the manager view
function dcPlDeleteFromView(name) {
  _ytMarkPlaylistDeleted(name);
  if (_dcPlExpandedName === name) _dcPlExpandedName = null;
  _ytSavePlaylists();
  dcRenderPlaylistsView();
}

// Remove a single track from a playlist
function dcPlRemoveTrack(name, idx) {
  const pl = _ytPlaylists[name];
  if (!pl) return;
  pl.splice(idx, 1);
  if (pl.length === 0) {
    _ytMarkPlaylistDeleted(name);
    if (_dcPlExpandedName === name) _dcPlExpandedName = null;
  } else {
    _ytTouchPlaylist(name);
  }
  _ytSavePlaylists();
  dcRenderPlaylistsView();
}

// Drag-and-drop handlers for track reordering
function dcPlDragStart(event, name, idx) {
  _dcPlDragSrc = idx;
  event.dataTransfer.effectAllowed = 'move';
  event.dataTransfer.setData('text/plain', String(idx));
}

function dcPlDrop(event, name, toIdx) {
  event.preventDefault();
  event.currentTarget.classList.remove('dc-pl-drag-over');
  if (_dcPlDragSrc === null || _dcPlDragSrc === toIdx) { _dcPlDragSrc = null; return; }
  const pl = _ytPlaylists[name];
  if (!pl) return;
  const [moved] = pl.splice(_dcPlDragSrc, 1);
  pl.splice(toIdx, 0, moved);
  _dcPlDragSrc = null;
  _ytTouchPlaylist(name);
  _ytSavePlaylists();
  dcRenderPlaylistsView();
}

// Save the current player queue as a named playlist from the manager view
function dcPlSaveQueue(name) {
  if (!name) { dcPlShowStatus('Enter a playlist name first'); return; }
  if (!_ytCurrentTrack && !_ytQueue.length) { dcPlShowStatus('No active playback to save — start playing music first'); return; }
  _ytSaveCurrentQueue(name);
  const input = document.getElementById('dcPlNewName');
  if (input) input.value = '';
  dcPlShowStatus(`Saved "${name}"`);
  dcRenderPlaylistsView();
}

// Show a brief status message below the save form
function dcPlShowStatus(msg) {
  const el = document.getElementById('dcPlStatus');
  if (!el) return;
  el.textContent = msg;
  el.style.opacity = '1';
  clearTimeout(el._hideTimer);
  el._hideTimer = setTimeout(() => { el.style.opacity = '0'; }, 2500);
}

// ── 7. Play Similar ───────────────────────────────────────────────
function _ytPlaySimilar() {
  if (!_ytCurrentTrack) return;
  const { artist, title } = _ytCurrentTrack;
  const btns = [...document.querySelectorAll('#songsBody .yt-play-btn')]
    .filter(b => b.dataset.artist && b.dataset.artist.toLowerCase() === artist.toLowerCase()
      && !(b.dataset.title === title && b.dataset.artist === artist));
  const statusEl = document.getElementById('ytMiniStatus');
  if (btns.length === 0) {
    if (statusEl) { statusEl.textContent = `No other songs by ${artist} in chart`; statusEl.className = 'yt-mini-status'; setTimeout(() => { if (statusEl.textContent.startsWith('No other')) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 3000); }
    return;
  }
  btns.forEach(b => _ytQueue.push({ title: b.dataset.title, artist: b.dataset.artist, album: b.dataset.album, btn: b }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  if (statusEl) { statusEl.textContent = `+${btns.length} by ${artist} queued`; statusEl.className = 'yt-mini-status ok'; setTimeout(() => { if (statusEl.textContent.includes('queued')) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2000); }
}

// ── 8. Picture-in-Picture ─────────────────────────────────────────
async function _ytTogglePiP() {
  if (_ytPipWindow) {
    try { _ytPipWindow.close(); } catch(e) {}
    _ytPipWindow = null; _ytPipUpdate = null;
    _ytUpdatePipBtn(); return;
  }
  if (!window.documentPictureInPicture) {
    const statusEl = document.getElementById('ytMiniStatus');
    if (statusEl) { statusEl.textContent = 'PiP requires Chrome 116+'; statusEl.className = 'yt-mini-status err'; setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; }, 3000); }
    return;
  }
  try {
    const pipWin = await window.documentPictureInPicture.requestWindow({ width: 280, height: 130 });
    _ytPipWindow  = pipWin;
    function pipRender() {
      if (!_ytPipWindow) return;
      const t   = _ytCurrentTrack;
      const vid = _ytCurrentVideoId;
      pipWin.document.body.innerHTML = '';
      pipWin.document.body.style.cssText = 'margin:0;padding:10px;background:#111;color:#fff;font-family:system-ui,sans-serif;box-sizing:border-box;overflow:hidden;';
      const wrap = pipWin.document.createElement('div');
      wrap.innerHTML =
        `<style>.pi{display:flex;gap:8px;align-items:flex-start;margin-bottom:8px}.pt{width:72px;height:41px;object-fit:cover;border-radius:3px;background:#222;flex-shrink:0}.pm{flex:1;min-width:0}.pn{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pa{font-size:10px;color:#aaa;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pb{display:flex;gap:6px}button{background:#333;border:none;color:#fff;padding:4px 10px;border-radius:4px;cursor:pointer;font-size:14px;transition:background .12s}button:hover{background:#e00}</style>` +
        `<div class="pi">${vid ? `<img class="pt" src="https://img.youtube.com/vi/${vid}/default.jpg" onerror="this.style.display='none'">` : ''}<div class="pm"><div class="pn">${t ? esc(t.title) : '—'}</div><div class="pa">${t ? esc(t.artist || '') : ''}</div></div></div>` +
        `<div class="pb"><button id="pp">⏯</button><button id="ps">⏭</button></div>`;
      pipWin.document.body.appendChild(wrap);
      pipWin.document.getElementById('pp').onclick = () => _ytPauseToggle();
      pipWin.document.getElementById('ps').onclick = () => _ytSkip();
    }
    pipRender();
    _ytPipUpdate = pipRender;
    pipWin.addEventListener('pagehide', () => { _ytPipWindow = null; _ytPipUpdate = null; _ytUpdatePipBtn(); });
    _ytUpdatePipBtn();
  } catch(e) { console.error('PiP error:', e); }
}

function _ytUpdatePipBtn() {
  const btn = document.getElementById('ytPipBtn');
  if (!btn) return;
  btn.classList.toggle('yt-ctrl-active', !!_ytPipWindow);
  btn.title = _ytPipWindow ? 'Close Picture-in-Picture' : 'Picture-in-Picture';
}

// ── 9. Playback speed ─────────────────────────────────────────────
const _YT_SPEEDS = [0.75, 1, 1.25, 1.5, 2];

function _ytCycleSpeed() {
  _ytSpeedIdx = (_ytSpeedIdx + 1) % _YT_SPEEDS.length;
  _ytSpeed    = _YT_SPEEDS[_ytSpeedIdx];
  _ytApplySpeed();
  try { localStorage.setItem('yt-speed-idx', _ytSpeedIdx); } catch(e) {}
  _ytUpdateSpeedBtn();
}

function _ytApplySpeed() {
  if (_ytPlayer && _ytSpeed !== undefined) { try { _ytPlayer.setPlaybackRate(_ytSpeed); } catch(e) {} }
}

function _ytUpdateSpeedBtn() {
  const btn   = document.getElementById('ytSpeedBtn');
  const badge = document.getElementById('ytSpeedBadge');
  if (!btn) return;
  btn.classList.toggle('yt-ctrl-active', _ytSpeed !== 1);
  btn.title = `Speed: ${_ytSpeed}x [S]`;
  if (badge) { badge.textContent = _ytSpeed === 1 ? '' : _ytSpeed + 'x'; badge.style.display = _ytSpeed === 1 ? 'none' : ''; }
}

// ── 10. Share card ────────────────────────────────────────────────
async function _ytShare() {
  if (!_ytCurrentTrack) return;
  const { title, artist, album } = _ytCurrentTrack;
  const vid     = _ytCurrentVideoId;
  const dateStr = new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
  const lines   = [`🎵 ${title}${artist ? ` — ${artist}` : ''}${album ? ` (${album})` : ''}`, `dankcharts.fm  ·  ${dateStr}`];
  if (vid) lines.push(`https://www.youtube.com/watch?v=${vid}`);
  const text    = lines.join('\n');
  const statusEl = document.getElementById('ytMiniStatus');
  try {
    await navigator.clipboard.writeText(text);
    if (statusEl) { statusEl.textContent = '✓ Copied!'; statusEl.className = 'yt-mini-status ok'; setTimeout(() => { if (statusEl.textContent === '✓ Copied!') { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2000); }
    const btn = document.getElementById('ytShareBtn');
    if (btn) { btn.classList.add('yt-ctrl-active'); setTimeout(() => btn && btn.classList.remove('yt-ctrl-active'), 1500); }
  } catch(e) {
    if (statusEl) { statusEl.textContent = 'Copy failed'; statusEl.className = 'yt-mini-status err'; setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; }, 2000); }
  }
}

// ── Panel helper (close all extra panels except the listed ones) ───
function _ytCloseExtraPanels(keep = []) {
  const map = { ytSleepPanel: 'ytSleepBtn', ytLyricsPanel: 'ytLyricsBtn', ytPlaylistsPanel: 'ytPlaylistsBtn' };
  Object.entries(map).forEach(([panelId, btnId]) => {
    if (keep.includes(panelId)) return;
    const el = document.getElementById(panelId); if (el) el.style.display = 'none';
    const b  = document.getElementById(btnId);   if (b)  b.classList.remove('yt-ctrl-active');
  });
}

// ── Listening Activity Heatmap ─────────────────────────────────────────────

const HM_THEMES = {
  default: ['#1c2b3f', '#3a1858', '#6a28a0', '#c048cc', '#ff7ee0'],
  fire:    ['#1a0900', '#5c1500', '#c03800', '#e87000', '#ffd030'],
  ocean:   ['#030e1a', '#0d3060', '#0b6fa4', '#12b5d4', '#7ee8ff'],
  forest:  ['#0a1a0a', '#174d17', '#2a8c2a', '#5cc45c', '#b0f0b0'],
  ember:   ['#140303', '#4a0a08', '#991818', '#d44000', '#f09000'],
};
const HM_TYPE_THEME = { all: 'default', artist: 'fire', song: 'ocean', album: 'forest' };
const HM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const HM_DOW_LABELS = ['Mon', '', 'Wed', '', 'Fri', '', 'Sun'];

function hmLerpColor(h1, h2, t) {
  const p = s => parseInt(s, 16);
  const r = v => Math.round(v).toString(16).padStart(2, '0');
  const [r1, g1, b1] = [p(h1.slice(1, 3)), p(h1.slice(3, 5)), p(h1.slice(5, 7))];
  const [r2, g2, b2] = [p(h2.slice(1, 3)), p(h2.slice(3, 5)), p(h2.slice(5, 7))];
  return '#' + r(r1 + (r2 - r1) * t) + r(g1 + (g2 - g1) * t) + r(b1 + (b2 - b1) * t);
}

function hmCellColor(count, max) {
  const stops = HM_THEMES[hmTheme] || HM_THEMES.default;
  if (!count || !max) return stops[0];
  const ratio = Math.min(Math.log1p(count) / Math.log1p(max), 1);
  const idx = ratio * (stops.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.min(lo + 1, stops.length - 1);
  return lo === hi ? stops[lo] : hmLerpColor(stops[lo], stops[hi], idx - lo);
}

function hmOrdinal(n) {
  const s = n % 100;
  if (s >= 11 && s <= 13) return n + 'th';
  switch (n % 10) {
    case 1: return n + 'st';
    case 2: return n + 'nd';
    case 3: return n + 'rd';
    default: return n + 'th';
  }
}

function hmMatchesFilter(p) {
  if (heatmapType === 'artist') return p.artists.some(a => heatmapFilters.includes(a));
  if (heatmapType === 'song') return heatmapFilters.includes(`${p.title} • ${p.artist}`);
  if (heatmapType === 'album') return heatmapFilters.includes(`${p.album} • ${albumArtist(p)}`);
  return true;
}

function buildHeatmapData() {
  const dayMap = {};
  const msMap = {};
  const chrono = [...allPlays].sort((a, b) => a.date - b.date);
  const isFiltered = heatmapType !== 'all' && heatmapFilters.length > 0;

  if (!isFiltered) {
    for (const p of chrono) {
      const dk = dayStrOf(p);
      if (!dayMap[dk]) dayMap[dk] = { count: 0, plays: [] };
      dayMap[dk].count++;
      dayMap[dk].plays.push(p);
    }
    // First scrobble of each year milestone
    const firstPlayOfYear = {};
    for (const p of chrono) {
      const yr = tzDateOf(p).getFullYear();
      if (!firstPlayOfYear[yr]) firstPlayOfYear[yr] = p;
    }
    for (const [yr, p] of Object.entries(firstPlayOfYear)) {
      const dk = dayStrOf(p);
      if (!msMap[dk]) msMap[dk] = { daily: [], allTime: [] };
      msMap[dk].allTime.push({ label: `First scrobble of ${yr}`, play: p, isYearFirst: true });
    }
    // Daily milestones: how many plays you hit within a single day
    for (const [dk, data] of Object.entries(dayMap)) {
      const daily = [];
      for (const n of [1, 50, 100, 200, 500, 1000]) {
        if (data.plays.length >= n) daily.push({ label: hmOrdinal(n) + ' of the day', play: data.plays[n - 1] });
      }
      if (daily.length) {
        if (!msMap[dk]) msMap[dk] = { daily: [], allTime: [] };
        msMap[dk].daily = daily;
      }
    }
    // All-time milestones: cumulative scrobble count across your entire history
    const allTimeMilestones = new Set([100, 250, 500, 1000, 2500, 5000, 10000, 25000, 50000, 100000]);
    let cumCount = 0;
    for (const p of chrono) {
      cumCount++;
      if (allTimeMilestones.has(cumCount)) {
        const dk = dayStrOf(p);
        if (!msMap[dk]) msMap[dk] = { daily: [], allTime: [] };
        msMap[dk].allTime.push({ label: hmOrdinal(cumCount) + ' scrobble ever', play: p });
      }
    }
  } else {
    const milestoneSet = new Set([1, 10, 25, 50, 100, 200, 250, 300, 400, 500, 600, 700, 800, 900, 1000, 1500, 2000, 2500, 5000, 10000]);
    let cumCount = 0;
    for (const p of chrono) {
      if (!hmMatchesFilter(p)) continue;
      cumCount++;
      const dk = dayStrOf(p);
      if (!dayMap[dk]) dayMap[dk] = { count: 0, plays: [], chipIndices: new Set() };
      dayMap[dk].count++;
      dayMap[dk].plays.push(p);
      // Track which filter chips contributed to each day (for split-color cells)
      heatmapFilters.forEach((f, i) => {
        let matched = false;
        if (heatmapType === 'artist') matched = p.artists.some(a => a === f);
        else if (heatmapType === 'song') matched = `${p.title} • ${p.artist}` === f;
        else if (heatmapType === 'album') matched = `${p.album} • ${albumArtist(p)}` === f;
        if (matched) dayMap[dk].chipIndices.add(i);
      });
      if (milestoneSet.has(cumCount)) {
        if (!msMap[dk]) msMap[dk] = { daily: [], allTime: [] };
        msMap[dk].allTime.push({ label: hmOrdinal(cumCount) + ' scrobble', play: p });
      }
    }
  }
  return { dayMap, msMap };
}

function updateHeatmapFilterList() {
  const dl = document.getElementById('heatmapFilterList');
  if (!dl) return;
  if (heatmapType === 'artist') {
    const totals = {};
    for (const p of allPlays) for (const a of p.artists) totals[a] = (totals[a] || 0) + 1;
    const sorted = Object.keys(totals).sort((a, b) => totals[b] - totals[a]);
    dl.innerHTML = sorted.map(a => `<option value="${esc(a)}">`).join('');
  } else if (heatmapType === 'song') {
    const totals = {};
    for (const p of allPlays) {
      const k = `${p.title} • ${p.artist}`;
      totals[k] = (totals[k] || 0) + 1;
    }
    const sorted = Object.keys(totals).sort((a, b) => totals[b] - totals[a]);
    dl.innerHTML = sorted.map(s => `<option value="${esc(s)}">`).join('');
  } else if (heatmapType === 'album') {
    const totals = {};
    for (const p of allPlays) {
      if (!p.album || p.album === '—') continue;
      const k = `${p.album} • ${albumArtist(p)}`;
      totals[k] = (totals[k] || 0) + 1;
    }
    const sorted = Object.keys(totals).sort((a, b) => totals[b] - totals[a]);
    dl.innerHTML = sorted.map(s => `<option value="${esc(s)}">`).join('');
  }
}

function renderHeatmapChips() {
  const wrap = document.getElementById('heatmapChips');
  if (!wrap) return;
  wrap.innerHTML = heatmapFilters.map((f, i) => {
    const col = GRAPH_PALETTE[i % GRAPH_PALETTE.length];
    return `<span style="display:inline-flex;align-items:center;gap:4px;background:${col}22;border:1px solid ${col};
              color:${col};font-family:var(--font-mono);font-size:0.65rem;padding:2px 8px;border-radius:20px;
              letter-spacing:0.04em;">${esc(f)}
              <button onclick="removeHeatmapFilter(${i})" style="background:none;border:none;color:${col};
                cursor:pointer;font-size:0.75rem;line-height:1;padding:0 0 1px 2px;">×</button>
            </span>`;
  }).join('');
}

function removeHeatmapFilter(idx) {
  heatmapFilters.splice(idx, 1);
  renderHeatmapChips();
  renderHeatmap();
}

function hmComputeStreaks(dayMap) {
  const days = Object.keys(dayMap).filter(k => dayMap[k].count > 0).sort();
  if (!days.length) return { best: 0, current: 0 };
  let best = 1, streak = 1;
  for (let i = 1; i < days.length; i++) {
    const prev = new Date(days[i - 1] + 'T00:00:00');
    const curr = new Date(days[i] + 'T00:00:00');
    if ((curr - prev) / 86400000 === 1) { streak++; if (streak > best) best = streak; }
    else streak = 1;
  }
  const today = localDateStr(tzNow());
  const daysSet = new Set(days);
  let cur = 0;
  const check = new Date(today + 'T00:00:00');
  while (daysSet.has(localDateStr(check))) { cur++; check.setDate(check.getDate() - 1); }
  return { best, current: cur };
}

function hmComputeDroughts(dayMap) {
  const days = Object.keys(dayMap).filter(k => dayMap[k].count > 0).sort();
  const droughtCells = new Set();
  const returnMap = {};
  for (let i = 1; i < days.length; i++) {
    const prev = new Date(days[i - 1] + 'T00:00:00');
    const curr = new Date(days[i] + 'T00:00:00');
    const gap = Math.round((curr - prev) / 86400000) - 1;
    if (gap > 6) {
      const d = new Date(prev);
      d.setDate(d.getDate() + 1);
      while (d < curr) { droughtCells.add(localDateStr(d)); d.setDate(d.getDate() + 1); }
      returnMap[days[i]] = gap;
    }
  }
  return { droughtCells, returnMap };
}

function hmComputePercentile(dayMap) {
  const counts = Object.values(dayMap).map(d => d.count).sort((a, b) => a - b);
  return count => {
    const below = counts.filter(c => c < count).length;
    return Math.round((below / counts.length) * 100);
  };
}

function hmYearStats(dayMap) {
  const yearStats = {};
  const seenArtists = new Set();
  const sortedKeys = Object.keys(dayMap).sort();
  for (const dk of sortedKeys) {
    const yr = new Date(dk + 'T00:00:00').getFullYear();
    const data = dayMap[dk];
    if (!yearStats[yr]) yearStats[yr] = { total: 0, artists: {}, newArtists: 0, bestDay: 0, bestDk: '' };
    yearStats[yr].total += data.count;
    if (data.count > yearStats[yr].bestDay) { yearStats[yr].bestDay = data.count; yearStats[yr].bestDk = dk; }
    for (const p of data.plays) {
      const artists = p.artists && p.artists.length ? p.artists : [p.artist];
      for (const a of artists) {
        yearStats[yr].artists[a] = (yearStats[yr].artists[a] || 0) + 1;
        if (!seenArtists.has(a)) { seenArtists.add(a); yearStats[yr].newArtists++; }
      }
    }
  }
  for (const yr of Object.keys(yearStats)) {
    const artists = yearStats[yr].artists;
    yearStats[yr].topArtist = Object.keys(artists).sort((a, b) => artists[b] - artists[a])[0] || '';
  }
  return yearStats;
}

function hmRenderPatterns(dayMap) {
  const dowLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const dowTotals = Array(7).fill(0);
  const dowDayCount = Array(7).fill(0);
  for (const [dk, data] of Object.entries(dayMap)) {
    const dow = (new Date(dk + 'T00:00:00').getDay() + 6) % 7;
    dowTotals[dow] += data.count;
    dowDayCount[dow]++;
  }
  const dowAvg = dowTotals.map((t, i) => dowDayCount[i] > 0 ? t / dowDayCount[i] : 0);
  const maxAvg = Math.max(...dowAvg, 1);

  const grid = Array.from({ length: 7 }, () => Array(24).fill(0));
  const plays = heatmapType !== 'all' && heatmapFilters.length > 0
    ? allPlays.filter(p => hmMatchesFilter(p))
    : allPlays;
  for (const p of plays) {
    const d = tzDateOf(p);
    grid[(d.getDay() + 6) % 7][d.getHours()]++;
  }
  const maxHour = Math.max(...grid.flat(), 1);

  const stops = HM_THEMES[hmTheme] || HM_THEMES.default;
  const accent = stops[stops.length - 1];

  const barsHtml = dowLabels.map((label, i) => {
    const avg = dowAvg[i];
    const w = Math.round((avg / maxAvg) * 100);
    const alpha = 0.45 + 0.55 * (avg / maxAvg);
    return `<div class="hm-pat-bar-row">
      <span class="hm-pat-dow-label">${label}</span>
      <div class="hm-pat-bar-track"><div class="hm-pat-bar-fill" style="width:${w}%;background:${accent};opacity:${alpha.toFixed(2)};"></div></div>
      <span class="hm-pat-bar-val">${Number.isInteger(avg) ? avg : avg.toFixed(1)}/day</span>
    </div>`;
  }).join('');

  const hourHeaderCells = Array(24).fill(0).map((_, h) => {
    const label = h === 0 ? '12a' : h === 6 ? '6a' : h === 12 ? '12p' : h === 18 ? '6p' : '';
    return `<div class="hm-pat-hour-label">${label}</div>`;
  }).join('');

  let gridRows = '';
  for (let dow = 0; dow < 7; dow++) {
    gridRows += '<div class="hm-pat-grid-row">';
    for (let hr = 0; hr < 24; hr++) {
      const cnt = grid[dow][hr];
      const bg = hmCellColor(cnt, maxHour);
      gridRows += cnt > 0
        ? `<div class="hm-pat-cell has-data" style="background:${bg};" data-hm-pattern="${dow},${hr}" data-hm-pat-count="${cnt}"></div>`
        : `<div class="hm-pat-cell" style="background:${stops[0]};"></div>`;
    }
    gridRows += '</div>';
  }

  return `<div class="hm-patterns-section">
    <div class="hm-patterns-header">Listening Patterns</div>
    <div class="hm-patterns-body">
      <div class="hm-pat-weekday">
        <div class="hm-pat-sublabel">Weekday rhythm</div>
        <div class="hm-pat-bars">${barsHtml}</div>
      </div>
      <div class="hm-pat-hourblock">
        <div class="hm-pat-sublabel">Hour of day</div>
        <div class="hm-pat-hour-grid">
          <div class="hm-pat-dow-col">${dowLabels.map(l => `<div class="hm-pat-dow-side-label">${l}</div>`).join('')}</div>
          <div><div class="hm-pat-hour-row">${hourHeaderCells}</div>${gridRows}</div>
        </div>
      </div>
    </div>
  </div>`;
}

function renderHeatmap() {
  const container = document.getElementById('gHeatmap');
  const tooltip = document.getElementById('heatmapTooltip');
  if (!container || !allPlays.length) return;
  if (tooltip) tooltip.style.display = 'none';

  const { dayMap, msMap } = buildHeatmapData();
  _hmDayMap = dayMap;
  _hmMsMap = msMap;
  updateHeatmapFilterList();

  const today = localDateStr(tzNow());
  const allDayKeys = Object.keys(dayMap).sort();

  if (!allDayKeys.length) {
    container.innerHTML = '<div style="font-family:var(--font-mono);font-size:0.7rem;color:var(--text3);padding:1rem 0;">No scrobbles found for the selected filters.</div>';
    return;
  }

  const firstDate = new Date(allDayKeys[0] + 'T00:00:00');
  const lastDate = new Date(today + 'T00:00:00');

  // Find max count and best day
  let maxCount = 1;
  _hmBestDayDk = '';
  for (const [dk, d] of Object.entries(dayMap)) {
    if (d.count > maxCount) { maxCount = d.count; _hmBestDayDk = dk; }
  }

  // Streaks, droughts, percentile
  const { best: bestStreak, current: curStreak } = hmComputeStreaks(dayMap);
  const { droughtCells, returnMap } = hmComputeDroughts(dayMap);
  _hmReturnMap = returnMap;
  _hmPercentileFn = hmComputePercentile(dayMap);

  // Year-in-review stats (ALL view only)
  const isAll = heatmapType === 'all';
  const yearStats = isAll ? hmYearStats(dayMap) : null;

  const stops = HM_THEMES[hmTheme] || HM_THEMES.default;

  // Streak bar
  let streakHtml = '';
  if (bestStreak > 1 || curStreak > 0) {
    const chips = [];
    if (curStreak > 0) chips.push(`<span class="hm-streak-chip">🔥 ${curStreak}-day streak</span>`);
    if (bestStreak > 1) chips.push(`<span class="hm-streak-chip">Best: ${bestStreak} days</span>`);
    streakHtml = `<div class="hm-streak-bar">${chips.join('')}</div>`;
  }

  const startDow = firstDate.getDay();
  const padStart = startDow === 0 ? 6 : startDow - 1;
  const gridStart = new Date(firstDate);
  gridStart.setDate(gridStart.getDate() - padStart);

  const yearGroups = {};
  const cur = new Date(gridStart);
  while (cur <= lastDate) {
    const thu = new Date(cur);
    thu.setDate(thu.getDate() + 3);
    const yr = thu.getFullYear();
    if (!yearGroups[yr]) yearGroups[yr] = [];
    const week = [];
    for (let i = 0; i < 7; i++) {
      const dk = localDateStr(cur);
      const data = dayMap[dk] || null;
      const inRange = cur >= firstDate && cur <= lastDate;
      week.push({ dk, count: data ? data.count : 0, inRange, chipIndices: data ? data.chipIndices : null });
      cur.setDate(cur.getDate() + 1);
    }
    yearGroups[yr].push(week);
  }

  let html = '';
  for (const yr of Object.keys(yearGroups).sort((a, b) => +a - +b)) {
    const weeks = yearGroups[yr];

    let monthHtml = '';
    let lastMonth = -1;
    for (const week of weeks) {
      const monDate = new Date(week[0].dk + 'T00:00:00');
      const month = monDate.getMonth();
      if (week[0].inRange && month !== lastMonth) {
        monthHtml += `<div class="heatmap-week-col heatmap-month-header-row" style="position:relative;"><span class="heatmap-month-label">${HM_MONTHS[month]}</span></div>`;
        lastMonth = month;
      } else {
        monthHtml += '<div class="heatmap-week-col heatmap-month-header-row"></div>';
      }
    }

    let cellsHtml = '';
    for (const week of weeks) {
      cellsHtml += '<div class="heatmap-week-col">';
      for (const cell of week) {
        let bg, cls = 'heatmap-cell', attr = '';
        if (!cell.inRange) {
          bg = 'transparent';
        } else if (cell.count === 0) {
          if (droughtCells.has(cell.dk)) { bg = 'rgba(180,80,20,0.13)'; cls += ' hm-drought'; }
          else bg = 'transparent';
        } else {
          cls += ' has-data';
          attr = ` data-dk="${cell.dk}"`;
          if (cell.dk === _hmBestDayDk) cls += ' hm-best-day';
          // Split-color for multi-chip overlap
          if (cell.chipIndices && cell.chipIndices.size > 1) {
            const idxs = [...cell.chipIndices].slice(0, 2);
            const c1 = GRAPH_PALETTE[idxs[0] % GRAPH_PALETTE.length];
            const c2 = GRAPH_PALETTE[idxs[1] % GRAPH_PALETTE.length];
            bg = `linear-gradient(135deg,${c1} 50%,${c2} 50%)`;
          } else {
            bg = hmCellColor(cell.count, maxCount);
          }
        }
        cellsHtml += `<div class="${cls}" style="background:${bg};"${attr}></div>`;
      }
      cellsHtml += '</div>';
    }

    // Year-in-review card
    let reviewHtml = '';
    if (yearStats && yearStats[yr]) {
      const ys = yearStats[yr];
      const bd = ys.bestDk ? new Date(ys.bestDk + 'T00:00:00') : null;
      const bestDayStr = bd ? `${HM_MONTHS[bd.getMonth()]} ${bd.getDate()}` : '—';
      reviewHtml = `<div class="hm-year-review">
        <span class="hm-yr-stat"><span class="hm-yr-num">${ys.total.toLocaleString()}</span> plays</span>
        <span class="hm-yr-dot">·</span>
        <span class="hm-yr-stat">Best day <span class="hm-yr-num">${bestDayStr}</span> <span class="hm-yr-muted">(${ys.bestDay.toLocaleString()})</span></span>
        <span class="hm-yr-dot">·</span>
        <span class="hm-yr-stat">Top: <span class="hm-yr-name">${esc(ys.topArtist)}</span></span>
        ${ys.newArtists > 0 ? `<span class="hm-yr-dot">·</span><span class="hm-yr-stat"><span class="hm-yr-num">${ys.newArtists.toLocaleString()}</span> new artists</span>` : ''}
      </div>`;
    }

    html += `<div class="heatmap-year-block">
      <div class="heatmap-year-header">${yr}</div>
      <div class="heatmap-outer">
        <div class="heatmap-dow-labels">${HM_DOW_LABELS.map(l => `<div class="heatmap-dow-label">${l}</div>`).join('')}</div>
        <div class="heatmap-inner">
          <div class="heatmap-grid-wrap">
            <div class="heatmap-weeks-row" style="height:16px;margin-bottom:3px;">${monthHtml}</div>
            <div class="heatmap-weeks-row">${cellsHtml}</div>
          </div>
        </div>
      </div>
      ${reviewHtml}
    </div>`;
  }

  const legendCells = [0, 0.2, 0.45, 0.7, 1].map(r => {
    const cnt = r === 0 ? 0 : Math.round(Math.exp(r * Math.log1p(maxCount)) - 1);
    return `<div class="heatmap-cell" style="background:${hmCellColor(cnt, maxCount)};cursor:default;"></div>`;
  }).join('');
  html += `<div class="heatmap-legend"><span class="heatmap-legend-label">Less</span>${legendCells}<span class="heatmap-legend-label">More</span></div>`;

  html += hmRenderPatterns(dayMap);

  container.innerHTML = streakHtml + html;
}

// Heatmap tooltip — attached once to the static container
(function () {
  const cont = document.getElementById('gHeatmap');
  const tip = document.getElementById('heatmapTooltip');
  if (!cont || !tip) return;

  function positionTip(refEl) {
    const rect = refEl.getBoundingClientRect();
    const margin = 12;
    const tw = tip.offsetWidth || 220;
    const th = tip.offsetHeight || 120;
    let x = rect.right + margin;
    let y = rect.top - 4;
    if (x + tw > window.innerWidth - 8) x = rect.left - tw - margin;
    if (y + th > window.innerHeight - 8) y = Math.max(8, window.innerHeight - th - 8);
    tip.style.left = x + 'px';
    tip.style.top = y + 'px';
  }

  cont.addEventListener('mouseover', e => {
    // Pattern cell (time-of-day grid)
    const patCell = e.target.closest('.hm-pat-cell.has-data');
    if (patCell && patCell.dataset.hmPattern) {
      const [dow, hr] = patCell.dataset.hmPattern.split(',').map(Number);
      const cnt = parseInt(patCell.dataset.hmPatCount) || 0;
      const dowName = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][dow];
      const hrLabel = hr === 0 ? 'midnight' : hr < 12 ? `${hr}am` : hr === 12 ? 'noon' : `${hr - 12}pm`;
      tip.innerHTML = `<div class="hm-tt-date">${dowName} · ${hrLabel}</div>
        <div class="hm-tt-count">${cnt.toLocaleString()} scrobble${cnt !== 1 ? 's' : ''}</div>`;
      tip.style.display = 'block';
      positionTip(patCell);
      return;
    }

    // Regular calendar cell
    const cell = e.target.closest('.heatmap-cell.has-data');
    if (!cell) { tip.style.display = 'none'; return; }

    const dk = cell.dataset.dk;
    const data = _hmDayMap[dk];
    const msEntry = _hmMsMap[dk];
    const ms = msEntry || { daily: [], allTime: [] };
    const dailyMs = ms.daily || [];
    const allTimeMs = ms.allTime || [];
    if (!data) return;

    const d = new Date(dk + 'T00:00:00');
    const dayName = d.toLocaleDateString('en-US', { weekday: 'long' });
    const day = d.getDate();
    const monthName = d.toLocaleDateString('en-US', { month: 'long' });
    const yr = d.getFullYear();
    const word = data.count === 1 ? 'scrobble' : 'scrobbles';

    // Best day badge
    const bestHtml = dk === _hmBestDayDk
      ? '<div class="hm-tt-best">⭐ Your best day ever</div>' : '';

    // Percentile
    const pct = _hmPercentileFn ? _hmPercentileFn(data.count) : null;
    const topPct = pct !== null ? 100 - pct : null;
    const pctHtml = (topPct !== null && topPct <= 20 && dk !== _hmBestDayDk)
      ? `<div class="hm-tt-pct">Top ${topPct < 1 ? '<1' : topPct}% day</div>` : '';

    // Drought return
    const gapDays = _hmReturnMap && _hmReturnMap[dk];
    const gapHtml = gapDays
      ? `<div class="hm-tt-gap">🌧 Back after ${gapDays}-day break</div>` : '';

    let msHtml = '';
    const hasBoth = dailyMs.length > 0 && allTimeMs.length > 0;
    if (dailyMs.length || allTimeMs.length) {
      msHtml = '<hr class="hm-tt-rule">';
      if (dailyMs.length) {
        if (hasBoth) msHtml += '<div class="hm-tt-section-label">📅 Today</div>';
        for (const m of dailyMs) {
          msHtml += `<div class="hm-tt-ms-wrap">
            <div class="hm-tt-ms-label">🚩 ${esc(m.label)}</div>
            <div class="hm-tt-ms-track">${esc(m.play.title)}</div>
            <div class="hm-tt-ms-artist">${esc(m.play.artist)}</div>
          </div>`;
        }
      }
      if (allTimeMs.length) {
        if (hasBoth) msHtml += '<div class="hm-tt-rule-minor"></div><div class="hm-tt-section-label">🏆 All-time</div>';
        for (const m of allTimeMs) {
          const icon = m.isYearFirst ? '🎆' : '🏆';
          msHtml += `<div class="hm-tt-ms-wrap">
            <div class="hm-tt-ms-label hm-tt-ms-alltime">${icon} ${esc(m.label)}</div>
            <div class="hm-tt-ms-track">${esc(m.play.title)}</div>
            <div class="hm-tt-ms-artist">${esc(m.play.artist)}</div>
          </div>`;
        }
      }
    }

    tip.innerHTML = `<div class="hm-tt-date">${dayName} ${day} ${esc(monthName)} ${yr}</div>
      <div class="hm-tt-count">${data.count.toLocaleString()} ${word}</div>
      ${bestHtml}${pctHtml}${gapHtml}${msHtml}`;
    tip.style.display = 'block';
    positionTip(cell);
  });

  cont.addEventListener('mouseleave', () => { tip.style.display = 'none'; });
}());

// Heatmap type buttons
document.getElementById('heatmapTypeBtns').addEventListener('click', e => {
  const btn = e.target.closest('button[data-hmtype]');
  if (!btn) return;
  document.querySelectorAll('#heatmapTypeBtns button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  heatmapType = btn.dataset.hmtype;
  heatmapFilters = [];
  // Auto-apply the default color theme for this view type
  hmTheme = HM_TYPE_THEME[heatmapType] || 'default';
  document.querySelectorAll('#heatmapThemeBtns button').forEach(b => {
    b.classList.toggle('active', b.dataset.hmtheme === hmTheme);
  });
  renderHeatmapChips();
  const filterRow = document.getElementById('heatmapFilterRow');
  filterRow.style.display = heatmapType === 'all' ? 'none' : 'flex';
  const placeholders = { artist: 'Add an artist…', song: 'Add a song…', album: 'Add an album…' };
  const inp = document.getElementById('heatmapFilterInput');
  if (inp) inp.placeholder = placeholders[heatmapType] || 'Add filter…';
  if (currentPeriod === 'graphs') renderHeatmap();
});

// Heatmap theme swatches
document.getElementById('heatmapThemeBtns').addEventListener('click', e => {
  const btn = e.target.closest('button[data-hmtheme]');
  if (!btn) return;
  document.querySelectorAll('#heatmapThemeBtns button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  hmTheme = btn.dataset.hmtheme;
  if (currentPeriod === 'graphs') renderHeatmap();
});

function hmAddFilter() {
  const inp = document.getElementById('heatmapFilterInput');
  const val = inp.value.trim();
  if (!val || heatmapFilters.includes(val)) { inp.value = ''; return; }
  heatmapFilters.push(val);
  inp.value = '';
  renderHeatmapChips();
  if (currentPeriod === 'graphs') renderHeatmap();
}

document.getElementById('heatmapFilterBtn').addEventListener('click', hmAddFilter);
document.getElementById('heatmapFilterInput').addEventListener('keydown', e => {
  if (e.key === 'Enter') hmAddFilter();
});

// ─── STICKY NAV SENTINEL ───────────────────────────────────────
(function () {
  const sentinel = document.getElementById('stickyNavSentinel');
  const bar = document.getElementById('stickyNavBar');
  if (!sentinel || !bar) return;
  const obs = new IntersectionObserver(
    ([entry]) => bar.classList.toggle('is-stuck', !entry.isIntersecting),
    { threshold: 0, rootMargin: '0px' }
  );
  obs.observe(sentinel);
})();

// ─── LOADING SKELETON ──────────────────────────────────────────
function showSkeleton() {
  const skRow = () => `
    <tr class="skeleton-row">
      <td><div class="skeleton-cell" style="width:28px"></div></td>
      <td><div class="skeleton-cell skeleton-thumb"></div></td>
      <td>
        <div class="skeleton-cell" style="width:55%;margin-bottom:6px"></div>
        <div class="skeleton-cell" style="width:35%"></div>
      </td>
      <td><div class="skeleton-cell" style="width:50%"></div></td>
      <td><div class="skeleton-cell" style="width:32px;margin-left:auto"></div></td>
    </tr>`;
  ['songsBody', 'artistsBody', 'albumsBody'].forEach(id => {
    const el = document.getElementById(id);
    if (el && !el.querySelector('tr:not(.skeleton-row)')) {
      el.innerHTML = Array.from({ length: 6 }, skRow).join('');
    }
  });
}

// ─── HERO STATS ────────────────────────────────────────────────
function renderHeroStats() {
  const el = document.getElementById('heroStats');
  if (!el || !allPlays.length) return;

  const total = allPlays.length;

  const days = new Set(allPlays.map(p => {
    const d = tzDateOf(p);
    return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
  }));

  const artistCounts = {};
  for (const p of allPlays) {
    for (const a of p.artists) {
      artistCounts[a] = (artistCounts[a] || 0) + 1;
    }
  }
  const topArtist = Object.entries(artistCounts).sort((a, b) => b[1] - a[1])[0];

  // Consecutive day streak ending today (or yesterday if today has no plays yet)
  const daySet = days;
  const now = tzNow();
  function toNum(d) { return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate(); }
  function prevDay(n) {
    const d = new Date(Math.floor(n / 10000), Math.floor(n / 100) % 100 - 1, n % 100);
    d.setDate(d.getDate() - 1);
    return toNum(d);
  }
  let streak = 0;
  let cur = toNum(now);
  if (!daySet.has(cur)) cur = prevDay(cur);
  while (daySet.has(cur)) { streak++; cur = prevDay(cur); }

  // Personal best streak (longest consecutive run across all time)
  const sortedDays = [...daySet].sort((a, b) => a - b);
  let pb = streak || 1, pbCur = 1;
  for (let i = 1; i < sortedDays.length; i++) {
    const prev = sortedDays[i - 1];
    const prevD = new Date(Math.floor(prev / 10000), Math.floor(prev / 100) % 100 - 1, prev % 100);
    prevD.setDate(prevD.getDate() + 1);
    if (toNum(prevD) === sortedDays[i]) { pbCur++; if (pbCur > pb) pb = pbCur; }
    else pbCur = 1;
  }

  const avgPerDay = Math.round(total / days.size);

  // Icons are drawn in CSS rather than set as emoji, matching the language the
  // landing-page source cards already use (.sheets-grid / .lastfm-vinyl /
  // .upload-stack): each one is a small built object with its own identity
  // colour that animates on hover instead of a flat glyph that can only scale.
  el.innerHTML = `
    <div class="hero-stat" data-tip="${total.toLocaleString()} plays across ${days.size.toLocaleString()} unique days">
      <!-- A record: total plays are total spins. Grooves + label, disc turns on hover. -->
      <span class="hero-icon hero-icon-vinyl" aria-hidden="true"><i class="hero-vinyl-disc"></i></span>
      <span class="hero-val" data-countup="${total}">${total.toLocaleString()}</span>
      <span class="hero-label">${t('hero_total_plays')}</span>
    </div>
    <div class="hero-stat-sep">·</div>
    <div class="hero-stat hero-stat-days" data-tip="Click to view your listening heatmap">
      <!-- Calendar: binding tabs, header band, and a cell grid whose days fill in
           on hover — the same header-row-plus-grid build as .sheets-grid. -->
      <span class="hero-icon hero-icon-cal" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></span>
      <span class="hero-val" data-countup="${days.size}">${days.size.toLocaleString()}</span>
      <span class="hero-label">${t('hero_days_listened')}</span>
    </div>
    <div class="hero-stat-sep">·</div>
    <div class="hero-stat" data-tip="~${avgPerDay.toLocaleString()} plays on average per day listened">
      <!-- Bars sitting flat on a baseline that stagger-grow into a chart, the
           same rest→peak waterfall the Sheets card icon runs. -->
      <span class="hero-icon hero-icon-bars" aria-hidden="true"><i></i><i></i><i></i><i></i></span>
      <span class="hero-val" data-countup="${avgPerDay}">${avgPerDay.toLocaleString()}</span>
      <span class="hero-label">${t('hero_plays_per_day')}</span>
    </div>
    <div class="hero-stat-sep">·</div>
    <div class="hero-stat hero-stat-artist" data-tip="Click to jump to Top Artists">
      <!-- Crown: the chart-topper. Lifts off its base on hover, which is also
           the "this is clickable" cue. -->
      <span class="hero-icon hero-icon-crown" aria-hidden="true"><i class="hero-crown-base"></i><i class="hero-crown-body"></i></span>
      <span class="hero-val hero-val-artist">${topArtist ? topArtist[0] : '—'}</span>
      <span class="hero-label">${t('hero_top_artist')}</span>
    </div>
    <div class="hero-stat-sep">·</div>
    <div class="hero-stat" id="hero-streak-stat" data-tip="Click for streak details · Personal best: ${pb} day${pb === 1 ? '' : 's'}">
      <!-- Flame instead of the old 📆/🔥/🌟 emoji swap: the same element grows,
           recolours and starts flickering as the count-up crosses each tier, so
           the icon is driven by the .hero-stat--streak-N class, not by JS text. -->
      <span class="hero-icon hero-icon-flame" aria-hidden="true"><i class="hero-flame-body"></i><i class="hero-flame-core"></i></span>
      <span class="hero-val">0</span>
      <span class="hero-label">${t('hero_day_streak')}</span>
      <span class="hero-stat-pb">PB: ${pb}</span>
    </div>`;

  el.style.display = '';

  // Switch to All-Time tab and scroll to artists section when Top Artist is clicked
  el.querySelector('.hero-stat-artist').addEventListener('click', () => {
    const alltimeBtn = document.querySelector('#periodNav button[data-period="alltime"]');
    const needsSwitch = alltimeBtn && currentPeriod !== 'alltime';
    if (needsSwitch) alltimeBtn.click();
    const sec = document.getElementById('artistsSection');
    if (sec) {
      if (needsSwitch) {
        setTimeout(() => sec.scrollIntoView({ behavior: 'smooth', block: 'start' }), 150);
      } else {
        sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
  });

  // Switch to Graphs tab and scroll to heatmap when Days Listened is clicked
  el.querySelector('.hero-stat-days').addEventListener('click', () => {
    const graphsBtn = document.querySelector('#periodNav button[data-period="graphs"]');
    const needsSwitch = graphsBtn && currentPeriod !== 'graphs';
    if (needsSwitch) graphsBtn.click();
    const card = document.getElementById('heatmapCard');
    if (card) {
      setTimeout(() => card.scrollIntoView({ behavior: 'smooth', block: 'start' }), needsSwitch ? 300 : 0);
    }
  });

  // Open streak details modal when streak stat is clicked
  const streakStatEl = el.querySelector('#hero-streak-stat');
  if (streakStatEl) streakStatEl.addEventListener('click', openStreakModal);

  // Count-up animation for numeric values
  el.querySelectorAll('[data-countup]').forEach(span => {
    const target = parseInt(span.dataset.countup, 10);
    if (!target) return;
    const duration = 2200;
    const startTime = performance.now();
    function frame(now) {
      const progress = Math.min((now - startTime) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      span.textContent = Math.round(eased * target).toLocaleString();
      if (progress < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  });

  // Streak count-up: slow linear animation that transitions through each tier
  const streakEl = el.querySelector('#hero-streak-stat');
  if (streakEl && streak > 0) {
    const valSpan = streakEl.querySelector('.hero-val');
    const iconSpan = streakEl.querySelector('.hero-icon');
    const duration = 5000;
    const startTime = performance.now();
    function streakFrame(now) {
      const progress = Math.min((now - startTime) / duration, 1);
      const cur = Math.round(progress * streak);
      valSpan.textContent = cur;
      const t = cur >= 100 ? 6 : cur >= 60 ? 5 : cur >= 30 ? 4 : cur >= 14 ? 3 : cur >= 7 ? 2 : cur >= 1 ? 1 : 0;
      // The flame is CSS-drawn, so the tier class alone resizes and recolours it
      // — no icon glyph to swap.
      streakEl.className = `hero-stat${t > 0 ? ` hero-stat--streak-${t}` : ''}`;
      if (progress < 1) {
        requestAnimationFrame(streakFrame);
      } else {
        valSpan.style.animation = 'streak-finish-burst 1.4s ease-out forwards';
        iconSpan.style.animation = 'streak-icon-burst 1.4s ease-out forwards';
        setTimeout(() => {
          valSpan.style.animation = '';
          iconSpan.style.animation = '';
        }, 1400);
      }
    }
    requestAnimationFrame(streakFrame);
  }
}

// ─── STREAK HEATMAP STATE ─────────────────────────────────────
let _skHmTheme = localStorage.getItem('sk-hm-theme') || 'ocean';
let _skHmRange = 'year';
let _skHmCount = {}, _skHmNames = {}, _skHmByType = {}, _skHmNamesByType = {};

// ─── STREAK DETAILS MODAL ─────────────────────────────────────
function openStreakModal() {
  if (!allPlays.length) return;

  // ── Helpers ─────────────────────────────────────────────────────
  function prevDs(ds) {
    const d = new Date(ds + 'T12:00:00');
    d.setDate(d.getDate() - 1);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }
  function longestInSet(daySet) {
    if (daySet.size < 2) return daySet.size;
    const s = [...daySet].sort();
    let best = 1, cur = 1;
    for (let i = 1; i < s.length; i++) {
      const diff = Math.round((+new Date(s[i] + 'T12:00:00') - +new Date(s[i - 1] + 'T12:00:00')) / 86400000);
      if (diff === 1) { if (++cur > best) best = cur; } else cur = 1;
    }
    return best;
  }
  function longestStreakRange(daySet) {
    if (!daySet.size) return { len: 0, startDs: '', endDs: '' };
    const s = [...daySet].sort();
    if (s.length === 1) return { len: 1, startDs: s[0], endDs: s[0] };
    let best = 1, bestEndIdx = 0, cur = 1;
    for (let i = 1; i < s.length; i++) {
      const diff = Math.round((+new Date(s[i] + 'T12:00:00') - +new Date(s[i - 1] + 'T12:00:00')) / 86400000);
      if (diff === 1) { cur++; if (cur > best) { best = cur; bestEndIdx = i; } } else cur = 1;
    }
    return { len: best, startDs: streakStartDs(s[bestEndIdx], best), endDs: s[bestEndIdx] };
  }
  function streakStartDs(endDs, len) {
    let c = endDs;
    for (let i = 1; i < len; i++) c = prevDs(c);
    return c;
  }
  function fmtD(ds) {
    return new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  }
  const MILESTONES = [7, 14, 30, 50, 100, 200, 365];
  function nextMs(len) { return MILESTONES.find(m => m > len) || null; }

  // ── Date anchors ─────────────────────────────────────────────────
  const todayStr = localDateStr(tzNow());
  const yest = prevDs(todayStr);
  const dayBefore = prevDs(yest);
  const nowDate = new Date();
  const hour = nowDate.getHours();
  const weekAgo = new Date(nowDate); weekAgo.setDate(nowDate.getDate() - 6);
  const weekAgoStr = localDateStr(weekAgo);

  // ── Build day-sets + last-5-songs maps ───────────────────────────
  const songDays = {}, songInfo = {};
  const artistDays = {};
  const albumDays = {}, albumInfo = {};
  const artLastSongs = {}, albLastSongs = {};

  for (const p of allPlays) {
    const ds = dayStrOf(p);
    const sk = songKey(p);
    if (!songDays[sk]) { songDays[sk] = new Set(); songInfo[sk] = { title: p.title, artist: p.artist, album: p.album && p.album !== '—' ? p.album : '' }; }
    songDays[sk].add(ds);
    for (const a of p.artists) {
      if (!artistDays[a]) artistDays[a] = new Set();
      artistDays[a].add(ds);
      if (!artLastSongs[a]) artLastSongs[a] = [];
      if (artLastSongs[a].length < 5 && !artLastSongs[a].some(s => s.title === p.title)) artLastSongs[a].push({ title: p.title, artist: p.artist, album: p.album || '' });
    }
    if (p.album && p.album !== '—') {
      const ak = albumKeyOf(p);
      if (!albumDays[ak]) { albumDays[ak] = new Set(); albumInfo[ak] = { album: p.album, artist: albumArtist(p) }; }
      albumDays[ak].add(ds);
      if (!albLastSongs[ak]) albLastSongs[ak] = [];
      if (albLastSongs[ak].length < 5 && !albLastSongs[ak].some(s => s.title === p.title)) albLastSongs[ak].push({ title: p.title, artist: p.artist, album: p.album });
    }
  }

  // ── Streak helpers ───────────────────────────────────────────────
  function streakEndingAt(daySet, end) {
    if (!daySet.has(end)) return 0;
    let n = 1, cur = end;
    while (true) { const prev = prevDs(cur); if (!daySet.has(prev)) break; n++; cur = prev; }
    return n;
  }
  function cal14(daySet) {
    const arr = []; let cur = todayStr;
    for (let i = 0; i < 14; i++) { arr.unshift(daySet.has(cur) ? 1 : 0); cur = prevDs(cur); }
    return arr;
  }

  // ── All-time bests ───────────────────────────────────────────────
  const songBest = {}, artBest = {}, albBest = {};
  for (const [k, d] of Object.entries(songDays)) songBest[k] = longestInSet(d);
  for (const [k, d] of Object.entries(artistDays)) artBest[k] = longestInSet(d);
  for (const [k, d] of Object.entries(albumDays)) albBest[k] = longestInSet(d);

  // ── Heatmap data ─────────────────────────────────────────────────
  _skHmCount = {}; _skHmNames = {}; _skHmByType = {}; _skHmNamesByType = {};
  function accHm(daySet, name, type) {
    const s = [...daySet].sort();
    for (let i = 1; i < s.length; i++) {
      const diff = Math.round((+new Date(s[i] + 'T12:00:00') - +new Date(s[i - 1] + 'T12:00:00')) / 86400000);
      if (diff === 1) {
        _skHmCount[s[i]] = (_skHmCount[s[i]] || 0) + 1;
        (_skHmNames[s[i]] = _skHmNames[s[i]] || []).push(name);
        if (!_skHmByType[s[i]]) _skHmByType[s[i]] = { artist: 0, album: 0, song: 0 };
        _skHmByType[s[i]][type]++;
        if (!_skHmNamesByType[s[i]]) _skHmNamesByType[s[i]] = { artist: [], song: [], album: [] };
        _skHmNamesByType[s[i]][type].push(name);
      }
    }
  }
  for (const [a, d] of Object.entries(artistDays)) accHm(d, a, 'artist');
  for (const [sk, d] of Object.entries(songDays)) accHm(d, songInfo[sk].title + ' · ' + songInfo[sk].artist, 'song');
  for (const [ak, d] of Object.entries(albumDays)) accHm(d, albumInfo[ak].album + ' · ' + albumInfo[ak].artist, 'album');

  // ── Build enriched item ──────────────────────────────────────────
  function mkItem(name, sub, type, len, key, endD) {
    const best = type === 'song' ? songBest[key] || len : type === 'artist' ? artBest[key] || len : albBest[key] || len;
    const ds = type === 'song' ? songDays[key] : type === 'artist' ? artistDays[key] : albumDays[key];
    return { name, sub, type, len, key, endDs: endD, startDs: streakStartDs(endD, len), best, milestone: nextMs(len), cal: ds ? cal14(ds) : [] };
  }

  // ── Active, at-risk, lost ────────────────────────────────────────
  const activeSongs = [], activeArtists = [], activeAlbums = [];
  for (const [sk, d] of Object.entries(songDays)) { const l = streakEndingAt(d, todayStr); if (l >= 2) activeSongs.push(mkItem(songInfo[sk].title, songInfo[sk].artist, 'song', l, sk, todayStr)); }
  for (const [a, d] of Object.entries(artistDays)) { const l = streakEndingAt(d, todayStr); if (l >= 2) activeArtists.push(mkItem(a, '', 'artist', l, a, todayStr)); }
  for (const [ak, d] of Object.entries(albumDays)) { const l = streakEndingAt(d, todayStr); if (l >= 2) activeAlbums.push(mkItem(albumInfo[ak].album, albumInfo[ak].artist, 'album', l, ak, todayStr)); }
  activeSongs.sort((a, b) => b.len - a.len);
  activeArtists.sort((a, b) => b.len - a.len);
  activeAlbums.sort((a, b) => b.len - a.len);

  const atRisk = [];
  for (const [sk, d] of Object.entries(songDays)) { if (d.has(yest) && !d.has(todayStr)) { const l = streakEndingAt(d, yest); if (l >= 2) atRisk.push(mkItem(songInfo[sk].title, songInfo[sk].artist, 'song', l, sk, yest)); } }
  for (const [a, d] of Object.entries(artistDays)) { if (d.has(yest) && !d.has(todayStr)) { const l = streakEndingAt(d, yest); if (l >= 2) atRisk.push(mkItem(a, '', 'artist', l, a, yest)); } }
  for (const [ak, d] of Object.entries(albumDays)) { if (d.has(yest) && !d.has(todayStr)) { const l = streakEndingAt(d, yest); if (l >= 2) atRisk.push(mkItem(albumInfo[ak].album, albumInfo[ak].artist, 'album', l, ak, yest)); } }
  atRisk.sort((a, b) => b.len - a.len);

  // ── At Risk — enriched song list for Save Playlist / Copy Tracklist ─────
  // Those two actions need to protect every at-risk streak, not just song streaks.
  // Album/artist streaks have no "song" of their own, so: first pass over at-risk
  // albums — if a song already in the list is from that album, the streak is covered
  // for free; otherwise pull that album's most-recently-played song. Second pass over
  // at-risk artists does the same (checked against the list *including* the album
  // additions), so an artist already covered by an album pick isn't duplicated.
  function primaryArtistOf(artistStr) { const s = splitArtists(artistStr); return (s && s[0]) || artistStr; }
  const atRiskFull = atRisk.filter(it => it.type === 'song').map(it => ({
    title: it.name, artist: it.sub, album: (songInfo[it.key] && songInfo[it.key].album) || ''
  }));
  function addAtRiskFull(song) {
    if (!song) return;
    const dupe = atRiskFull.some(s => s.title.toLowerCase() === song.title.toLowerCase() && s.artist.toLowerCase() === song.artist.toLowerCase());
    if (!dupe) atRiskFull.push({ title: song.title, artist: song.artist, album: song.album || '' });
  }
  for (const it of atRisk) {
    if (it.type !== 'album') continue;
    const info = albumInfo[it.key];
    const covered = atRiskFull.some(s => s.album === info.album && primaryArtistOf(s.artist) === info.artist);
    if (!covered) addAtRiskFull((albLastSongs[it.key] || [])[0]);
  }
  for (const it of atRisk) {
    if (it.type !== 'artist') continue;
    const covered = atRiskFull.some(s => splitArtists(s.artist).includes(it.key));
    if (!covered) addAtRiskFull((artLastSongs[it.key] || [])[0]);
  }
  window._skAtRiskFullSongs = atRiskFull;

  const lost = [];
  for (const [sk, d] of Object.entries(songDays)) { if (!d.has(yest) && d.has(dayBefore)) { const l = streakEndingAt(d, dayBefore); if (l >= 2) lost.push(mkItem(songInfo[sk].title, songInfo[sk].artist, 'song', l, sk, dayBefore)); } }
  for (const [a, d] of Object.entries(artistDays)) { if (!d.has(yest) && d.has(dayBefore)) { const l = streakEndingAt(d, dayBefore); if (l >= 2) lost.push(mkItem(a, '', 'artist', l, a, dayBefore)); } }
  for (const [ak, d] of Object.entries(albumDays)) { if (!d.has(yest) && d.has(dayBefore)) { const l = streakEndingAt(d, dayBefore); if (l >= 2) lost.push(mkItem(albumInfo[ak].album, albumInfo[ak].artist, 'album', l, ak, dayBefore)); } }
  lost.sort((a, b) => b.len - a.len);

  // ── Hall of Fame & Graveyard ─────────────────────────────────────
  const fameCandidates = [];
  for (const [sk] of Object.entries(songDays)) { const b = songBest[sk]; if (b >= 7) { const r = longestStreakRange(songDays[sk]); fameCandidates.push({ name: songInfo[sk].title, sub: songInfo[sk].artist, type: 'song', len: b, key: sk, best: b, milestone: nextMs(b), cal: cal14(songDays[sk]), startDs: r.startDs, endDs: r.endDs }); } }
  for (const [a] of Object.entries(artistDays)) { const b = artBest[a]; if (b >= 7) { const r = longestStreakRange(artistDays[a]); fameCandidates.push({ name: a, sub: '', type: 'artist', len: b, key: a, best: b, milestone: nextMs(b), cal: cal14(artistDays[a]), startDs: r.startDs, endDs: r.endDs }); } }
  for (const [ak] of Object.entries(albumDays)) { const b = albBest[ak]; if (b >= 7) { const r = longestStreakRange(albumDays[ak]); fameCandidates.push({ name: albumInfo[ak].album, sub: albumInfo[ak].artist, type: 'album', len: b, key: ak, best: b, milestone: nextMs(b), cal: cal14(albumDays[ak]), startDs: r.startDs, endDs: r.endDs }); } }
  fameCandidates.sort((a, b) => b.len - a.len);
  const hallOfFame = fameCandidates.slice(0, 10);
  const activeKeys = new Set([...activeSongs, ...activeArtists, ...activeAlbums, ...atRisk].map(it => it.key));
  const graveyardAll = fameCandidates.filter(it => !activeKeys.has(it.key));

  // ── Weekly digest ─────────────────────────────────────────────────
  const allAR = [...activeSongs, ...activeArtists, ...activeAlbums, ...atRisk];
  const weekStarted = allAR.filter(it => it.startDs >= weekAgoStr).length;
  let weekEnded = 0;
  const _chkEnded = entries => { for (const [, d] of entries) { const s = [...d].sort(); const last = s[s.length - 1]; if (last >= weekAgoStr && last < yest && streakEndingAt(d, last) >= 2) weekEnded++; } };
  _chkEnded(Object.entries(songDays)); _chkEnded(Object.entries(artistDays)); _chkEnded(Object.entries(albumDays));

  // ── Hall of Fame plaque card ─────────────────────────────────────
  function hofItemHtml(it, rank, isActive) {
    const typeTag = `<span class="streak-type-tag streak-type-tag--${it.type}">${it.type}</span>`;
    const sub = it.sub ? `<div class="sk-hof-sub">${it.sub}</div>` : '';
    const cy = String(nowDate.getFullYear());
    const fmtDY = ds => new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric', ...(ds.slice(0, 4) !== cy ? { year: 'numeric' } : {}) });
    const dateRange = it.startDs && it.endDs ? `${fmtDY(it.startDs)} – ${fmtDY(it.endDs)}` : '';
    const statusBadge = isActive
      ? `<span class="sk-hof-badge sk-hof-badge--active">🔥 Active</span>`
      : `<span class="sk-hof-badge sk-hof-badge--ended">Ended</span>`;
    const calAttr = it.cal && it.cal.length ? `data-skc="${esc(JSON.stringify(it.cal))}" data-skn="${esc(it.name)}"` : '';
    const calBtn = calAttr ? `<span class="sk-cal-trig sk-hof-cal" ${calAttr}>◈</span>` : '';
    return `<div class="sk-hof-card">` +
      `<div class="sk-hof-rank">#${rank}</div>` +
      `<div class="sk-hof-body">` +
      `<div class="sk-hof-name">${it.name}${typeTag}</div>` +
      sub +
      `<div class="sk-hof-record">🏆 <span class="streak-days" data-len="${it.len}">0d</span> record</div>` +
      (dateRange ? `<div class="sk-hof-dates">${dateRange}</div>` : '') +
      `<div class="sk-hof-foot">${statusBadge}${calBtn}</div>` +
      `</div></div>`;
  }
  function hofSection() {
    if (!hallOfFame.length) return '';
    const collapsed = localStorage.getItem('skc-fame') === '1';
    const chev = collapsed ? '▶' : '▼';
    const inner = `<div class="sk-hof-grid">${hallOfFame.map((it, i) => hofItemHtml(it, i + 1, activeKeys.has(it.key))).join('')}</div>`;
    return `<div class="streak-section streak-section--fame${collapsed ? ' streak-section--collapsed' : ''}" data-skid="fame">` +
      `<div class="streak-section-title" onclick="_streakToggleSection(this.closest('.streak-section'))"><span class="sk-chev">${chev}</span> 🏅 Hall of Fame <span class="streak-count">(${hallOfFame.length})</span></div>` +
      `<div class="sk-sec-body${collapsed ? ' sk-sec-hidden' : ''}">${inner}</div></div>`;
  }

  // ── Item HTML ────────────────────────────────────────────────────
  function itemHtml(it, mode) {
    const sub = it.sub ? `<span class="streak-sub"> — ${it.sub}</span>` : '';
    const icon = mode === 'lost' ? '💔' : mode === 'risk' ? '⚠️' : mode === 'fame' ? '🏅' : '🔥';
    const cls = mode === 'lost' ? ' streak-item--lost' : mode === 'risk' ? ' streak-item--risk' : '';
    const tag = mode !== 'active' ? `<span class="streak-type-tag streak-type-tag--${it.type}">${it.type}</span>` : '';
    const since = it.startDs && it.len >= 3 ? `<span class="sk-since">since ${fmtD(it.startDs)}</span>` : '';
    const pb = it.best && it.len >= it.best && it.len >= 7 ? `<span class="sk-pb" title="Personal best!">🏆</span>` : '';
    const ms = it.milestone; const msLeft = ms ? ms - it.len : null;
    const msB = msLeft !== null && msLeft >= 1 && msLeft <= 3 ? `<span class="sk-ms" title="${ms}d milestone in ${msLeft}d">🎯 ${ms}d</span>` : '';
    const calAttr = it.cal && it.cal.length ? `data-skc="${esc(JSON.stringify(it.cal))}" data-skn="${esc(it.name)}"` : '';
    const calBtn = calAttr ? `<span class="sk-cal-trig" ${calAttr}>◈</span>` : '';
    let nameHtml, spLink = '';
    if (mode === 'risk') {
      if (it.type === 'song') {
        const q = encodeURIComponent(it.name + (it.sub ? ' ' + it.sub : ''));
        const jt = esc(JSON.stringify(it.name)); const jar = esc(JSON.stringify(it.sub || ''));
        nameHtml = `<span class="streak-name-link streak-name-link--play" onclick="_ytStreakPlay(${jt},${jar})" title="Play in player">${it.name}${sub}</span>`;
        spLink = `<a class="sk-sp-link" href="https://open.spotify.com/search/${q}" target="_blank" rel="noopener" title="Spotify">♫</a>`;
      } else {
        const songs = it.type === 'artist' ? (artLastSongs[it.key] || []) : (albLastSongs[it.key] || []);
        nameHtml = `<span class="streak-entity-trigger streak-name-link" data-ske="${esc(JSON.stringify(songs))}" data-sken="${esc(it.name)}">${it.name}${sub}</span>`;
      }
    } else {
      nameHtml = `${it.name}${sub}`;
    }
    return `<div class="streak-item${cls}">` +
      `<span class="streak-fire">${icon}</span>` +
      `<span class="streak-days" data-len="${it.len}">0d</span>` +
      `<span class="streak-label">${nameHtml}</span>${spLink}` +
      `${since}${pb}${msB}${tag}${calBtn}</div>`;
  }

  // ── Section HTML ─────────────────────────────────────────────────
  function section(title, items, mode, sid, extraTitleHtml = '') {
    const collapsed = localStorage.getItem('skc-' + sid) === '1';
    const inner = items.length ? items.map(it => itemHtml(it, mode)).join('') : `<div class="streak-empty">${t('streak_none')}</div>`;
    const cls = mode === 'lost' ? ' streak-section--lost' : mode === 'risk' ? ' streak-section--risk' : mode === 'fame' ? ' streak-section--fame' : '';
    const chev = collapsed ? '▶' : '▼';
    return `<div class="streak-section${cls}${collapsed ? ' streak-section--collapsed' : ''}" data-skid="${sid}">` +
      `<div class="streak-section-title" onclick="_streakToggleSection(this.closest('.streak-section'))"><span class="sk-chev">${chev}</span> ${title} <span class="streak-count">(${items.length})</span>${extraTitleHtml}</div>` +
      `<div class="sk-sec-body${collapsed ? ' sk-sec-hidden' : ''}">${inner}</div></div>`;
  }

  // ── Urgency banner ───────────────────────────────────────────────
  const urgency = atRisk.length ? (
    hour >= 21 ? `<div class="sk-urgency sk-urg--critical">🚨 ${24 - hour}h or less left today — listen now to save your streaks!</div>` :
    hour >= 18 ? `<div class="sk-urgency sk-urg--warning">⏰ Evening — a few hours left to save these.</div>` :
    hour >= 13 ? `<div class="sk-urgency sk-urg--mild">☀️ Afternoon — you still have time today.</div>` :
    `<div class="sk-urgency sk-urg--safe">🌅 Day is young — come back later to listen.</div>`
  ) : '';

  // ── Summary stat ─────────────────────────────────────────────────
  const totalActive = activeSongs.length + activeArtists.length + activeAlbums.length;
  const summaryEl = document.getElementById('streakSummaryStat');
  if (summaryEl) summaryEl.innerHTML =
    `<span class="sk-stat">🔥 ${totalActive}</span>` +
    `<span class="sk-stat sk-stat--risk">⚠️ ${atRisk.length}</span>` +
    `<span class="sk-stat sk-stat--lost">💔 ${lost.length}</span>`;

  // ── Weekly digest HTML ────────────────────────────────────────────
  const weeklyHtml = weekStarted || weekEnded
    ? `<div class="sk-weekly">📅 <strong>This week:</strong> ` +
      (weekStarted ? `${weekStarted} streak${weekStarted !== 1 ? 's' : ''} started` : '') +
      (weekStarted && weekEnded ? ' · ' : '') +
      (weekEnded ? `${weekEnded} ended` : '') + `</div>`
    : '';

  // ── At Risk — store songs for global play/queue/save functions ──
  // Play All / Queue All only make sense for actual at-risk SONG streaks. Save Playlist /
  // Copy Tracklist use the enriched atRiskFull list (built above) so they also cover
  // at-risk ARTIST/ALBUM streaks via a representative song.
  window._skAtRiskSongs = atRisk.filter(it => it.type === 'song');
  const _atRiskPlayBtns = window._skAtRiskSongs.length > 0
    ? `<button class="sk-atrisk-btn" onclick="skAtRiskPlayAll()" title="Play all at-risk songs in the music player">▶ Play All</button>` +
      `<button class="sk-atrisk-btn" onclick="skAtRiskQueueAll()" title="Add all at-risk songs to the queue">+ Queue All</button>`
    : '';
  const _atRiskFullBtns = window._skAtRiskFullSongs.length > 0
    ? `<button class="sk-atrisk-btn" onclick="skAtRiskSavePl()" title="Save a playlist covering all at-risk streaks (songs, plus a representative track for at-risk artists/albums)">♫ Save Playlist</button>` +
      `<button class="sk-atrisk-btn" onclick="skAtRiskExport()" title="Copy a tracklist covering all at-risk streaks for Soundiiz">📋 Copy Tracklist</button>`
    : '';
  const _atRiskSongBtns = (_atRiskPlayBtns || _atRiskFullBtns)
    ? `<span class="sk-sec-btns" onclick="event.stopPropagation()">${_atRiskPlayBtns}${_atRiskFullBtns}</span>` : '';

  // ── Render ───────────────────────────────────────────────────────
  const streaksHtml =
    weeklyHtml +
    `<div class="sk-toolbar"><input type="text" id="skFilter" class="sk-filter" placeholder="Filter…"><button id="skSortBtn" class="sk-sort-btn" data-mode="len">⬇ Length</button></div>` +
    section(t('streak_section_artists'), activeArtists, 'active', 'artists') +
    section(t('streak_section_albums'), activeAlbums, 'active', 'albums') +
    section(t('streak_section_songs'), activeSongs, 'active', 'songs') +
    urgency +
    section(t('streak_section_at_risk'), atRisk, 'risk', 'atrisk', _atRiskSongBtns) +
    section(t('streak_section_lost'), lost, 'lost', 'lost') +
    hofSection();

  // ── Graveyard pagination ──────────────────────────────────────────
  const GRAVE_PAGE_SIZE = 25;
  let gravePage = 0;
  function renderGraveyard() {
    const totalPages = Math.max(1, Math.ceil(graveyardAll.length / GRAVE_PAGE_SIZE));
    gravePage = Math.max(0, Math.min(gravePage, totalPages - 1));
    const start = gravePage * GRAVE_PAGE_SIZE;
    const pageItems = graveyardAll.slice(start, start + GRAVE_PAGE_SIZE);
    const listHtml = graveyardAll.length
      ? `<div class="sk-grave-hdr">All-time ended streaks (≥ 7 days)</div>` + pageItems.map(it => itemHtml(it, 'fame')).join('')
      : `<div class="streak-empty" style="padding:1.2rem 1.4rem">No ended streaks ≥ 7 days yet.</div>`;
    const pagerHtml = graveyardAll.length > GRAVE_PAGE_SIZE
      ? `<div class="page-nav sk-grave-nav">` +
          `<button class="page-nav-first" onclick="_skGraveGoToPage(0)"${gravePage === 0 ? ' disabled' : ''} title="First page">|◄</button>` +
          `<button class="page-nav-prev" onclick="_skGraveGoToPage(${gravePage - 1})"${gravePage === 0 ? ' disabled' : ''}>◄ PREV</button>` +
          `<span>#${start + 1}–${Math.min(start + GRAVE_PAGE_SIZE, graveyardAll.length)} of ${graveyardAll.length}</span>` +
          `<button class="page-nav-next" onclick="_skGraveGoToPage(${gravePage + 1})"${gravePage >= totalPages - 1 ? ' disabled' : ''}>NEXT ►</button>` +
          `<button class="page-nav-last" onclick="_skGraveGoToPage(${totalPages - 1})"${gravePage >= totalPages - 1 ? ' disabled' : ''} title="Last page">►|</button>` +
        `</div>`
      : '';
    const el = document.getElementById('skTabGraveyard');
    if (el) el.innerHTML = listHtml + pagerHtml;
    // Fill in streak-day counters for this page — the count-up animation only ever
    // ran once against the page-1 elements at modal-open time, so later pages need
    // their numbers set directly or they'd stay stuck at "0d".
    el?.querySelectorAll('.streak-days[data-len]').forEach(elx => { elx.textContent = elx.dataset.len + 'd'; });
  }
  window._skGraveGoToPage = function(page) { gravePage = page; renderGraveyard(); };

  document.getElementById('streakModalBody').innerHTML =
    `<div id="skTabStreaks" class="sk-tab-pane">${streaksHtml}</div>` +
    `<div id="skTabHeatmap" class="sk-tab-pane" style="display:none"></div>` +
    `<div id="skTabGraveyard" class="sk-tab-pane" style="display:none"></div>`;
  renderGraveyard();

  // restore last-used range, validating it's a known year or keyword
  const _skHmValidYrs = new Set(Object.keys(_skHmCount).map(d => d.slice(0, 4)));
  const _skHmStoredRange = sessionStorage.getItem('sk-hm-range') || 'year';
  _skHmRange = (['year', 'all'].includes(_skHmStoredRange) || _skHmValidYrs.has(_skHmStoredRange)) ? _skHmStoredRange : 'year';
  _skHmBuild();

  _streakSwitchTab(sessionStorage.getItem('sk-tab') || 'streaks');

  document.getElementById('skFilter')?.addEventListener('input', e => {
    const q = e.target.value.toLowerCase();
    document.querySelectorAll('#skTabStreaks .streak-item').forEach(el => {
      el.style.display = !q || (el.querySelector('.streak-label')?.textContent || '').toLowerCase().includes(q) ? '' : 'none';
    });
  });
  document.getElementById('skSortBtn')?.addEventListener('click', function() {
    const mode = this.dataset.mode === 'len' ? 'alpha' : 'len';
    this.dataset.mode = mode; this.textContent = mode === 'len' ? '⬇ Length' : '🔤 A–Z';
    document.querySelectorAll('#skTabStreaks .sk-sec-body').forEach(body => {
      const items = [...body.querySelectorAll('.streak-item')];
      if (mode === 'alpha') items.sort((a, b) => (a.querySelector('.streak-label')?.textContent || '').localeCompare(b.querySelector('.streak-label')?.textContent || ''));
      else items.sort((a, b) => +(b.querySelector('.streak-days')?.dataset.len || 0) - +(a.querySelector('.streak-days')?.dataset.len || 0));
      items.forEach(el => body.appendChild(el));
    });
  });

  // ── Heatmap interaction (delegated on persistent pane element) ────
  const _skHmPane = document.getElementById('skTabHeatmap');
  if (_skHmPane) {
    _skHmPane.addEventListener('mouseover', _skHmOnMouseover);
    _skHmPane.addEventListener('mouseout', _skHmOnMouseout);
    _skHmPane.addEventListener('click', _skHmOnClick);
    _skHmPane.addEventListener('touchend', _skHmOnTouchend, { passive: false });
  }

  document.getElementById('streakModal').classList.add('open');
  const cEls = document.querySelectorAll('#streakModalBody .streak-days[data-len]');
  const t0 = performance.now();
  (function tick(ts) {
    const prog = Math.min((ts - t0) / 700, 1), ease = 1 - Math.pow(1 - prog, 3);
    cEls.forEach(el => { el.textContent = Math.round(ease * +el.dataset.len) + 'd'; });
    if (prog < 1) requestAnimationFrame(tick);
  })(t0);
}

function closeStreakModal() {
  document.getElementById('streakModal').classList.remove('open');
}

// ─── STREAK MODAL HELPERS ──────────────────────────────────────

function _streakToggleSection(sectionEl) {
  const c = sectionEl.classList.toggle('streak-section--collapsed');
  const body = sectionEl.querySelector('.sk-sec-body');
  const chev = sectionEl.querySelector('.sk-chev');
  if (c) { body?.classList.add('sk-sec-hidden'); if (chev) chev.textContent = '▶'; }
  else { body?.classList.remove('sk-sec-hidden'); if (chev) chev.textContent = '▼'; }
  try { localStorage.setItem('skc-' + sectionEl.dataset.skid, c ? '1' : '0'); } catch(e) {}
}

// ── At Risk Today — Play All / Queue All / Save Playlist ────────────────────
// These operate only on songs (artists/albums are excluded) from the AT RISK TODAY section.

function skAtRiskPlayAll() {
  const songs = window._skAtRiskSongs || [];
  if (!songs.length) return;
  const [first, ...rest] = songs;
  openYtPlayer(first.name, first.sub, '', null);
  rest.forEach(s => _ytQueue.push({ title: s.name, artist: s.sub, album: '', btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
}

function skAtRiskQueueAll() {
  const songs = window._skAtRiskSongs || [];
  if (!songs.length) return;
  songs.forEach(s => _ytQueue.push({ title: s.name, artist: s.sub, album: '', btn: null }));
  _ytUpdateQueueDisplay();
  _ytSaveQueue();
  const statusEl = document.getElementById('ytMiniStatus');
  if (statusEl) {
    statusEl.textContent = `${songs.length} at-risk song${songs.length !== 1 ? 's' : ''} added to queue`;
    statusEl.className = 'yt-mini-status ok';
    setTimeout(() => { if (statusEl.textContent.includes('at-risk')) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2500);
  }
}

function skAtRiskSavePl() {
  // Uses the enriched list (window._skAtRiskFullSongs) so at-risk artist/album streaks
  // are covered too, not just at-risk songs — see openStreakModal's atRiskFull build.
  const songs = window._skAtRiskFullSongs || [];
  if (!songs.length) return;
  // Reuse the calendar create-playlist modal — populate it with at-risk songs
  _calCreatePlTracks = songs.map(s => ({ title: s.title, artist: s.artist, album: s.album || '' }));
  const today = new Date();
  const dateLabel = today.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  const subEl = document.getElementById('calCreatePlSub');
  if (subEl) subEl.textContent = `${songs.length} song${songs.length !== 1 ? 's' : ''} · At Risk Today`;
  const nameInput = document.getElementById('calCreatePlName');
  if (nameInput) nameInput.value = `At Risk · ${dateLabel}`;
  const modal = document.getElementById('calCreatePlModal');
  if (modal) { modal.classList.add('open'); setTimeout(() => nameInput && nameInput.select(), 80); }
}

function skAtRiskExport() {
  // Uses the enriched list (window._skAtRiskFullSongs) so at-risk artist/album streaks
  // are covered too, not just at-risk songs — see openStreakModal's atRiskFull build.
  const songs = window._skAtRiskFullSongs || [];
  if (!songs.length) return;
  // Build tracklist text (Artist - Title per line, Soundiiz-compatible)
  const mapped = songs.map(s => ({ title: s.title, artist: s.artist, album: s.album || '' }));
  const text = mapped.map(s => `${s.artist} - ${s.title}`).join('\n');

  // Auto-copy to clipboard immediately
  navigator.clipboard.writeText(text).catch(() => {});

  // Pre-load into export modal so user can see the list and pick a playlist name
  _exportSongsOverride = mapped;
  openExportModal();
  // Override subtitle and playlist name chips with at-risk-specific content
  const today = new Date();
  const dateLabel = today.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  const subEl = document.getElementById('exportModalSubtitle');
  if (subEl) subEl.textContent = `${songs.length} song${songs.length !== 1 ? 's' : ''} · At Risk Today · ${dateLabel} — ✓ Copied to clipboard`;
  const chipsEl = document.getElementById('exportNameChips');
  if (chipsEl) {
    const names = _genAtRiskPlNames(mapped, dateLabel);
    chipsEl.innerHTML = names.map(n => `<button class="export-name-chip" onclick="copyChipName(this,'${esc(n)}')">${esc(n)}</button>`).join('');
  }
}

// Generate playlist name suggestions tailored for the At Risk Today export
function _genAtRiskPlNames(songs, dateLabel) {
  const names = [];
  names.push(`At Risk · ${dateLabel}`);
  names.push(`Streak Savers · ${dateLabel}`);
  names.push(`Save My Streaks · ${dateLabel}`);
  names.push(`Don't Break the Streak · ${dateLabel}`);
  names.push(`Listen Today · ${dateLabel}`);

  // Add artist-based suggestions if one artist dominates
  const artistCount = {};
  for (const s of songs) {
    const primary = s.artist.split(',')[0].trim();
    artistCount[primary] = (artistCount[primary] || 0) + 1;
  }
  const top = Object.entries(artistCount).sort((a, b) => b[1] - a[1]);
  if (top.length && top[0][1] / songs.length >= 0.3) {
    const a1 = top[0][0];
    names.push(`${a1} – Streak Songs`);
    if (top[1] && top[1][1] / songs.length >= 0.2) names.push(`${a1} & ${top[1][0]} – At Risk`);
  }

  return names;
}

function _streakSwitchTab(tab) {
  document.querySelectorAll('.sk-tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  ['Streaks', 'Heatmap', 'Graveyard'].forEach(n => {
    const el = document.getElementById('skTab' + n);
    if (el) el.style.display = n.toLowerCase() === tab ? '' : 'none';
  });
  if (tab === 'heatmap') _skHmAnimate();
  try { sessionStorage.setItem('sk-tab', tab); } catch(e) {}
}

// ─── STREAK HEATMAP FUNCTIONS ─────────────────────────────────

// Persistent tooltip div
const _skHmTip = (() => {
  const el = document.createElement('div');
  el.id = 'skHmTip'; el.className = 'sk-hm-tip'; el.style.display = 'none';
  document.body.appendChild(el); return el;
})();

function _skHmShowTip(cell, ev) {
  const ds = cell.dataset.ds;
  const cnt = +cell.dataset.cnt || 0;
  if (!cnt) return;
  const names = _skHmNames[ds] || [];
  const fmtDs = new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
  const top6 = names.slice(0, 6);
  const extra = names.length - top6.length;
  _skHmTip.innerHTML =
    `<div class="sk-hm-tip-date">${fmtDs}</div>` +
    `<div class="sk-hm-tip-count">${cnt} active streak${cnt !== 1 ? 's' : ''}</div>` +
    (top6.length ? `<ul class="sk-hm-tip-list">${top6.map(n => `<li>${esc(n)}</li>`).join('')}${extra ? `<li class="sk-hm-tip-more">+${extra} more</li>` : ''}</ul>` : '');
  _skHmTip.style.display = 'block';
  const cx = ev.clientX != null ? ev.clientX : ev.pageX - window.scrollX;
  const cy = ev.clientY != null ? ev.clientY : ev.pageY - window.scrollY;
  const W = _skHmTip.offsetWidth || 190, H = _skHmTip.offsetHeight || 100;
  let l = cx + 12, top = cy + 12;
  if (l + W > innerWidth - 8) l = cx - W - 12;
  if (top + H > innerHeight - 8) top = cy - H - 12;
  _skHmTip.style.left = l + 'px'; _skHmTip.style.top = top + 'px';
}

function _skHmShowDrill(ds) {
  const drill = document.getElementById('skHmDrill');
  if (!drill) return;
  const names = _skHmNames[ds] || [];
  const cnt = _skHmCount[ds] || 0;
  if (!cnt) { drill.style.display = 'none'; return; }
  const fmtDs = new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
  drill.innerHTML =
    `<div class="sk-hm-drill-hdr">${fmtDs} — ${cnt} active streak${cnt !== 1 ? 's' : ''}</div>` +
    `<ul class="sk-hm-drill-list">${names.map(n => `<li>${esc(n)}</li>`).join('')}</ul>`;
  drill.style.display = '';
}

function _skHmShowCatTip(cell, ev) {
  const ds = cell.dataset.ds;
  const type = cell.dataset.type;
  const cnt = +cell.dataset.cnt || 0;
  if (!cnt) return;
  const names = (_skHmNamesByType[ds] || {})[type] || [];
  const typeLabel = type === 'artist' ? 'artist' : type === 'song' ? 'song' : 'album';
  const fmtDs = new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
  const top6 = names.slice(0, 6);
  const extra = names.length - top6.length;
  _skHmTip.innerHTML =
    `<div class="sk-hm-tip-date">${fmtDs}</div>` +
    `<div class="sk-hm-tip-count">${cnt} ${typeLabel} streak${cnt !== 1 ? 's' : ''}</div>` +
    (top6.length ? `<ul class="sk-hm-tip-list">${top6.map(n => `<li>${esc(n)}</li>`).join('')}${extra ? `<li class="sk-hm-tip-more">+${extra} more</li>` : ''}</ul>` : '');
  _skHmTip.style.display = 'block';
  const cx = ev.clientX != null ? ev.clientX : ev.pageX - window.scrollX;
  const cy = ev.clientY != null ? ev.clientY : ev.pageY - window.scrollY;
  const W = _skHmTip.offsetWidth || 190, H = _skHmTip.offsetHeight || 100;
  let l = cx + 12, top = cy + 12;
  if (l + W > innerWidth - 8) l = cx - W - 12;
  if (top + H > innerHeight - 8) top = cy - H - 12;
  _skHmTip.style.left = l + 'px'; _skHmTip.style.top = top + 'px';
}

function _skHmShowCatDrill(ds, type) {
  const drill = document.getElementById('skHmDrill');
  if (!drill) return;
  const names = (_skHmNamesByType[ds] || {})[type] || [];
  const cnt = names.length;
  if (!cnt) { drill.style.display = 'none'; return; }
  const fmtDs = new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
  const typeLabel = type === 'artist' ? 'artist' : type === 'song' ? 'song' : 'album';
  drill.innerHTML =
    `<div class="sk-hm-drill-hdr">${fmtDs} — ${cnt} ${typeLabel} streak${cnt !== 1 ? 's' : ''}</div>` +
    `<ul class="sk-hm-drill-list">${names.map(n => `<li>${esc(n)}</li>`).join('')}</ul>`;
  drill.style.display = '';
}

function _skHmOnMouseover(e) {
  const catCell = e.target.closest('.sk-hm-cat-has');
  if (catCell) { _skHmShowCatTip(catCell, e); return; }
  const cell = e.target.closest('.sk-hm-has');
  if (!cell) { _skHmTip.style.display = 'none'; return; }
  _skHmShowTip(cell, e);
}
function _skHmOnMouseout(e) {
  if (!e.relatedTarget?.closest('#skTabHeatmap')) _skHmTip.style.display = 'none';
}
function _skHmOnClick(e) {
  const catCell = e.target.closest('.sk-hm-cat-has');
  if (catCell) { _skHmShowCatDrill(catCell.dataset.ds, catCell.dataset.type); return; }
  const cell = e.target.closest('.sk-hm-has');
  if (!cell) { const d = document.getElementById('skHmDrill'); if (d) d.style.display = 'none'; return; }
  _skHmShowDrill(cell.dataset.ds);
}
function _skHmOnTouchend(e) {
  const catCell = e.target.closest('.sk-hm-cat-has');
  if (catCell) { e.preventDefault(); _skHmShowCatTip(catCell, e.changedTouches[0]); return; }
  const cell = e.target.closest('.sk-hm-has');
  if (!cell) return;
  e.preventDefault();
  _skHmShowTip(cell, e.changedTouches[0]);
}

function _skHmAnimate() {
  document.querySelectorAll('#skTabHeatmap .sk-hm-col-anim').forEach((col, i) => {
    col.style.animation = 'none';
    col.offsetHeight; // force reflow to restart animation
    col.style.animation = '';
    col.style.animationDelay = (i * 5) + 'ms';
  });
}

function _skHmSetRange(r) {
  _skHmRange = String(r);
  try { sessionStorage.setItem('sk-hm-range', _skHmRange); } catch(e) {}
  _skHmBuild();
}

function _skHmSetTheme(t) {
  _skHmTheme = t;
  try { localStorage.setItem('sk-hm-theme', t); } catch(e) {}
  _skHmBuild();
}

function _skHmBuild() {
  const pane = document.getElementById('skTabHeatmap');
  if (!pane) return;
  pane.innerHTML = _skHmGenHTML();
}

function _skHmCopyImg() {
  const grid = document.querySelector('#skTabHeatmap .sk-hm-grid');
  if (!grid) return;
  const cols = [...grid.querySelectorAll('.sk-hm-col')];
  const CELL = 10, GAP = 2, ROWS = 7;
  const W = cols.length * (CELL + GAP) - GAP, H = ROWS * (CELL + GAP) - GAP;
  const canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#0b0f1e'; ctx.fillRect(0, 0, W, H);
  cols.forEach((col, ci) => {
    [...col.querySelectorAll('.sk-hm-cell')].forEach((cell, ri) => {
      const bg = cell.style.background;
      ctx.fillStyle = (bg && bg !== 'transparent') ? bg : 'rgba(255,255,255,0.05)';
      ctx.beginPath();
      const x = ci * (CELL + GAP), y = ri * (CELL + GAP);
      try { ctx.roundRect(x, y, CELL, CELL, 2); } catch { ctx.rect(x, y, CELL, CELL); }
      ctx.fill();
    });
  });
  canvas.toBlob(blob => {
    if (!blob) return;
    const btn = document.querySelector('.sk-hm-copy-btn');
    navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })])
      .then(() => { if (btn) { btn.textContent = '✓ Copied'; setTimeout(() => btn.textContent = '📋 Copy', 1500); } })
      .catch(() => { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'streaks-heatmap.png'; a.click(); });
  });
}

function _skHmGenHTML() {
  const count = _skHmCount, byType = _skHmByType;
  const todayD = new Date(), todayS = localDateStr(todayD);
  const allDates = Object.keys(count).sort();

  // ── Determine date range ──────────────────────────────────────
  let rangeStart, rangeEnd, numWeeks;
  if (_skHmRange === 'year') {
    rangeEnd = todayD;
    const base = new Date(todayD); base.setDate(todayD.getDate() - 363);
    base.setDate(base.getDate() - base.getDay());
    rangeStart = base; numWeeks = 54;
  } else if (_skHmRange === 'all') {
    if (!allDates.length) {
      rangeEnd = todayD;
      rangeStart = new Date(todayD); rangeStart.setFullYear(rangeStart.getFullYear() - 1);
    } else {
      const fd = new Date(allDates[0] + 'T12:00:00');
      fd.setDate(fd.getDate() - fd.getDay()); rangeStart = fd; rangeEnd = todayD;
    }
    numWeeks = Math.ceil(Math.round((rangeEnd - rangeStart) / 86400000) / 7) + 2;
  } else {
    const yr = +_skHmRange;
    rangeStart = new Date(yr, 0, 1);
    rangeStart.setDate(rangeStart.getDate() - rangeStart.getDay());
    rangeEnd = new Date(yr, 11, 31);
    if (rangeEnd > todayD) rangeEnd = todayD;
    numWeeks = 54;
  }
  const baseT = rangeStart.getTime();

  // ── Compute stats ─────────────────────────────────────────────
  let activeDays = 0, totalStreakDays = 0, maxCount = 0, maxDate = '';
  const peakSet = new Set();
  let rangeDays = 0;
  for (let i = 0; i < numWeeks * 7; i++) {
    const dt = new Date(baseT + i * 86400000);
    if (dt > rangeEnd || dt > todayD) break;
    rangeDays++;
    const ds = localDateStr(dt);
    const cnt = count[ds] || 0;
    if (cnt > 0) { activeDays++; totalStreakDays += cnt; }
    if (cnt > maxCount) { maxCount = cnt; maxDate = ds; peakSet.clear(); peakSet.add(ds); }
    else if (cnt === maxCount && cnt > 0) peakSet.add(ds);
  }
  const avgPerActive = activeDays > 0 ? (totalStreakDays / activeDays).toFixed(1) : '0';

  // Busiest week
  let bestWeekStart = '', bestWeekSum = 0;
  for (let w = 0; w < numWeeks; w++) {
    let sum = 0;
    for (let d = 0; d < 7; d++) {
      const dt = new Date(baseT + (w * 7 + d) * 86400000);
      if (dt > rangeEnd || dt > todayD) break;
      sum += count[localDateStr(dt)] || 0;
    }
    if (sum > bestWeekSum) { bestWeekSum = sum; bestWeekStart = localDateStr(new Date(baseT + w * 7 * 86400000)); }
  }

  // Longest dense run (≥2 concurrent streaks per day)
  let longestRun = 0, curRun = 0;
  for (let i = 0; i < numWeeks * 7; i++) {
    const dt = new Date(baseT + i * 86400000);
    if (dt > rangeEnd || dt > todayD) break;
    (count[localDateStr(dt)] || 0) >= 2 ? (++curRun > longestRun && (longestRun = curRun)) : (curRun = 0);
  }

  // ── Color function (continuous, logarithmic) ──────────────────
  const themeStops = HM_THEMES[_skHmTheme] || HM_THEMES.ocean;
  function cellBg(cnt) {
    if (!cnt || !maxCount) return 'rgba(255,255,255,0.05)';
    const ratio = Math.min(Math.log1p(cnt) / Math.log1p(maxCount), 1);
    const idx = ratio * (themeStops.length - 1);
    const lo = Math.floor(idx), hi = Math.min(lo + 1, themeStops.length - 1);
    return hmLerpColor(themeStops[lo], themeStops[hi], idx - lo);
  }

  // ── Controls ──────────────────────────────────────────────────
  const availYears = [...new Set(allDates.map(d => d.slice(0, 4)))].sort();
  const rangeBtns =
    `<button class="sk-hm-rbtn${_skHmRange === 'year' ? ' active' : ''}" onclick="_skHmSetRange('year')">Past Year</button>` +
    availYears.map(y => `<button class="sk-hm-rbtn${_skHmRange === y ? ' active' : ''}" onclick="_skHmSetRange('${y}')">${y}</button>`).join('') +
    `<button class="sk-hm-rbtn${_skHmRange === 'all' ? ' active' : ''}" onclick="_skHmSetRange('all')">All Time</button>`;
  const themeSwatches = Object.entries(HM_THEMES).map(([k, stops]) =>
    `<div class="sk-hm-tswatch${_skHmTheme === k ? ' active' : ''}" style="background:linear-gradient(90deg,${stops[0]},${stops[stops.length - 1]})" onclick="_skHmSetTheme('${k}')" title="${k}"></div>`
  ).join('');

  // ── Summary stats ─────────────────────────────────────────────
  const peakFmt = maxDate ? new Date(maxDate + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : '';
  const summaryHtml =
    `<div class="sk-hm-summary">` +
    (maxDate ? `<span class="sk-hm-stat">Peak: <strong>${maxCount}</strong> on ${peakFmt}</span>` : '') +
    `<span class="sk-hm-stat">Active: <strong>${activeDays}</strong>/${rangeDays} days</span>` +
    `<span class="sk-hm-stat">Avg: <strong>${avgPerActive}</strong>/active day</span>` +
    `</div>`;

  // ── Callout bar (busiest week + dense run) ─────────────────────
  let calloutParts = [];
  if (bestWeekStart && bestWeekSum > 0) {
    const wEnd = new Date(new Date(bestWeekStart + 'T12:00:00').getTime() + 6 * 86400000);
    const wFmt = d => new Date(d + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    calloutParts.push(`📅 Busiest week: ${wFmt(bestWeekStart)}–${wFmt(localDateStr(wEnd))} (${(bestWeekSum / 7).toFixed(1)} avg/day)`);
  }
  if (longestRun >= 3) calloutParts.push(`🔥 Longest dense run: ${longestRun} consecutive days with ≥2 active`);
  const calloutHtml = calloutParts.length ? `<div class="sk-hm-callout">${calloutParts.join(' · ')}</div>` : '';

  // ── Month label row ───────────────────────────────────────────
  let monthRowHtml = '';
  let lastMonth = -1;
  for (let w = 0; w < numWeeks; w++) {
    const dt = new Date(baseT + w * 7 * 86400000);
    const m = dt.getMonth();
    if (dt <= rangeEnd && dt <= todayD && m !== lastMonth) {
      monthRowHtml += `<div class="sk-hm-month-cell"><span class="sk-hm-month-lbl">${HM_MONTHS[m]}</span></div>`;
      lastMonth = m;
    } else {
      monthRowHtml += '<div class="sk-hm-month-cell"></div>';
    }
  }

  // ── Day-of-week labels ────────────────────────────────────────
  const DOW_LABELS = ['Mon', '', 'Wed', '', 'Fri', '', ''];
  const dowHtml = `<div class="sk-hm-dow-col">${DOW_LABELS.map(l => `<div class="sk-hm-dow-label">${l}</div>`).join('')}</div>`;

  // ── Main grid ─────────────────────────────────────────────────
  let gridHtml = '';
  for (let w = 0; w < numWeeks; w++) {
    gridHtml += `<div class="sk-hm-col sk-hm-col-anim" style="animation-delay:${w * 5}ms">`;
    for (let d = 0; d < 7; d++) {
      const dt = new Date(baseT + (w * 7 + d) * 86400000);
      if (dt > rangeEnd || dt > todayD) { gridHtml += '<div class="sk-hm-cell" style="background:transparent"></div>'; continue; }
      const ds = localDateStr(dt);
      const cnt = count[ds] || 0;
      const bg = cellBg(cnt);
      let cls = 'sk-hm-cell';
      if (cnt > 0) cls += ' sk-hm-has';
      if (ds === todayS) cls += ' sk-hm-today';
      if (peakSet.has(ds)) cls += ' sk-hm-peak';
      gridHtml += `<div class="${cls}" style="background:${bg}" data-ds="${ds}" data-cnt="${cnt}"></div>`;
    }
    gridHtml += '</div>';
  }

  // ── Category breakdown (mini grids) ──────────────────────────
  function miniGrid(type, label, themeKey) {
    const stops = HM_THEMES[themeKey] || HM_THEMES.default;
    let maxV = 0;
    for (let i = 0; i < numWeeks * 7; i++) {
      const dt = new Date(baseT + i * 86400000);
      if (dt > rangeEnd || dt > todayD) break;
      const v = (byType[localDateStr(dt)] || {})[type] || 0;
      if (v > maxV) maxV = v;
    }
    function miniColor(cnt) {
      if (!cnt || !maxV) return 'rgba(255,255,255,0.05)';
      const r = Math.min(Math.log1p(cnt) / Math.log1p(maxV), 1);
      const idx = r * (stops.length - 1);
      const lo = Math.floor(idx), hi = Math.min(lo + 1, stops.length - 1);
      return hmLerpColor(stops[lo], stops[hi], idx - lo);
    }
    let catMonthRow = '', lastCatMonth = -1;
    for (let w = 0; w < numWeeks; w++) {
      const dt = new Date(baseT + w * 7 * 86400000);
      const m = dt.getMonth();
      if (dt <= rangeEnd && dt <= todayD && m !== lastCatMonth) {
        catMonthRow += `<div class="sk-hm-month-cell"><span class="sk-hm-month-lbl">${HM_MONTHS[m]}</span></div>`;
        lastCatMonth = m;
      } else {
        catMonthRow += '<div class="sk-hm-month-cell"></div>';
      }
    }
    const catDowHtml = `<div class="sk-hm-dow-col">${['Mon','','Wed','','Fri','',''].map(l => `<div class="sk-hm-dow-label">${l}</div>`).join('')}</div>`;
    let cols = '';
    for (let w = 0; w < numWeeks; w++) {
      cols += '<div class="sk-hm-cat-col">';
      for (let d = 0; d < 7; d++) {
        const dt = new Date(baseT + (w * 7 + d) * 86400000);
        if (dt > rangeEnd || dt > todayD) { cols += '<div class="sk-hm-cat-cell" style="background:transparent"></div>'; continue; }
        const ds = localDateStr(dt);
        const cnt = (byType[ds] || {})[type] || 0;
        cols += cnt > 0
          ? `<div class="sk-hm-cat-cell sk-hm-cat-has" style="background:${miniColor(cnt)}" data-ds="${ds}" data-cnt="${cnt}" data-type="${type}"></div>`
          : `<div class="sk-hm-cat-cell" style="background:rgba(255,255,255,0.05)"></div>`;
      }
      cols += '</div>';
    }
    return `<div class="sk-hm-cat">
      <div class="sk-hm-cat-label">${label}</div>
      <div class="sk-hm-outer">
        ${catDowHtml}
        <div class="sk-hm-scroll">
          <div class="sk-hm-grid-wrap">
            <div class="sk-hm-month-row-outer">${catMonthRow}</div>
            <div class="sk-hm-cat-grid">${cols}</div>
          </div>
        </div>
      </div>
    </div>`;
  }
  const catsHtml = `<div class="sk-hm-cats">` +
    miniGrid('artist', '🎤 Artists', 'fire') +
    miniGrid('song', '🎵 Songs', 'ocean') +
    miniGrid('album', '💿 Albums', 'forest') +
    `</div>`;

  // ── Numbered legend ───────────────────────────────────────────
  const lgRatios = [0, 0.25, 0.5, 0.75, 1];
  const lgCells = lgRatios.map((r, i) => {
    const cnt = r === 0 ? 0 : Math.max(1, Math.round(Math.exp(r * Math.log1p(maxCount)) - 1));
    const bg = cellBg(cnt);
    const lbl = i === 0 ? '0' : (i === lgRatios.length - 1 && maxCount > 0 ? `${cnt}+` : String(cnt));
    return `<div class="sk-hm-leg-wrap"><div class="sk-hm-cell" style="background:${bg};width:9px;height:9px;border-radius:1.5px;flex-shrink:0"></div><span class="sk-hm-leg-num">${lbl}</span></div>`;
  }).join('');

  return `<div class="sk-hm-wrap">
    <div class="sk-hm-controls">
      <div class="sk-hm-ranges">${rangeBtns}</div>
      <div class="sk-hm-themes">${themeSwatches}</div>
    </div>
    ${summaryHtml}
    ${calloutHtml}
    <div class="sk-hm-outer">
      ${dowHtml}
      <div class="sk-hm-scroll">
        <div class="sk-hm-grid-wrap">
          <div class="sk-hm-month-row-outer">${monthRowHtml}</div>
          <div class="sk-hm-grid">${gridHtml}</div>
        </div>
      </div>
    </div>
    ${catsHtml}
    <div class="sk-hm-leg-row">
      <div class="sk-hm-legend-inner"><span>Less</span>${lgCells}<span>More</span></div>
      <button class="sk-hm-copy-btn" onclick="_skHmCopyImg()" title="Copy heatmap as image">📋 Copy</button>
    </div>
    <div id="skHmDrill" class="sk-hm-drill" style="display:none"></div>
  </div>`;
}

// Calendar strip tooltip
const _skCalTip = (() => {
  const el = document.createElement('div');
  el.id = 'skCalTip'; el.className = 'sk-cal-tip'; el.style.display = 'none';
  document.body.appendChild(el); return el;
})();
let _skCalTimer = null;

function _skShowCalTip(trig) {
  clearTimeout(_skCalTimer);
  let days; try { days = JSON.parse(trig.dataset.skc); } catch { return; }
  const name = trig.dataset.skn || '';
  const today = new Date();
  const labels = Array.from({ length: 14 }, (_, i) => {
    const d = new Date(today); d.setDate(d.getDate() - (13 - i));
    return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  });
  _skCalTip.innerHTML = `<div class="sk-ct-name">${esc(name)}</div>` +
    `<div class="sk-ct-grid">${days.map((v, i) => `<span class="sk-ct-dot${v ? ' sk-ct-on' : ''}" title="${labels[i]}"></span>`).join('')}</div>` +
    `<div class="sk-ct-foot"><span>${labels[0]}</span><span>${labels[13]}</span></div>`;
  _skCalTip.style.display = 'block';
  const r = trig.getBoundingClientRect(), w = 220;
  let l = r.left; if (l + w > innerWidth - 8) l = innerWidth - w - 8; if (l < 8) l = 8;
  let top = r.bottom + 4; if (top + (_skCalTip.offsetHeight || 60) > innerHeight - 8) top = r.top - (_skCalTip.offsetHeight || 60) - 4;
  _skCalTip.style.left = l + 'px'; _skCalTip.style.top = top + 'px';
}

// Entity tooltip (artist/album → last 5 songs)
const _skEntTip = (() => {
  const el = document.createElement('div');
  el.id = 'skEntTip'; el.className = 'sk-ent-tip'; el.style.display = 'none';
  document.body.appendChild(el); return el;
})();
let _skEntTimer = null;

function _skShowEntTip(trig) {
  clearTimeout(_skEntTimer);
  let songs; try { songs = JSON.parse(trig.dataset.ske); } catch { return; }
  if (!songs.length) return;
  const name = trig.dataset.sken || '';
  const ytSvg = `<svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>`;
  _skEntTip.innerHTML = `<div class="sk-et-hdr">Last played from <strong>${esc(name)}</strong></div>` +
    songs.map(s => `<div class="sk-et-row"><span class="sk-et-name">${esc(s.title)}</span>` +
      `<button class="yt-play-btn sk-et-yt" data-title="${esc(s.title)}" data-artist="${esc(s.artist)}" data-album="${esc(s.album || '')}" onclick="event.stopPropagation();_ytStreakPlay(this.dataset.title,this.dataset.artist)" title="Play / Add to Queue"><span class="yt-btn-content">${ytSvg}</span></button>${dcPlBtnHtml('song', s.title, s.artist, s.album || '')}` +
    `</div>`).join('');
  _skEntTip.style.display = 'block';
  const r = trig.getBoundingClientRect(), w = 300;
  let l = r.left; if (l + w > innerWidth - 8) l = innerWidth - w - 8; if (l < 8) l = 8;
  let top = r.bottom + 4; if (top + (_skEntTip.offsetHeight || 150) > innerHeight - 8) top = r.top - (_skEntTip.offsetHeight || 150) - 4;
  _skEntTip.style.left = l + 'px'; _skEntTip.style.top = top + 'px';
}

document.addEventListener('mouseover', e => {
  const ct = e.target.closest('.sk-cal-trig');
  if (ct) { _skShowCalTip(ct); return; }
  if (e.target.closest('#skCalTip')) { clearTimeout(_skCalTimer); return; }
  const et = e.target.closest('.streak-entity-trigger');
  if (et) { _skShowEntTip(et); return; }
  if (e.target.closest('#skEntTip')) { clearTimeout(_skEntTimer); return; }
});
document.addEventListener('mouseout', e => {
  if (e.target.closest('.sk-cal-trig') || e.target.closest('#skCalTip')) {
    const to = e.relatedTarget;
    if (to && (to.closest('.sk-cal-trig') || to.closest('#skCalTip'))) return;
    _skCalTimer = setTimeout(() => { _skCalTip.style.display = 'none'; }, 130);
  }
  if (e.target.closest('.streak-entity-trigger') || e.target.closest('#skEntTip')) {
    const to = e.relatedTarget;
    if (to && (to.closest('.streak-entity-trigger') || to.closest('#skEntTip'))) return;
    _skEntTimer = setTimeout(() => { _skEntTip.style.display = 'none'; }, 130);
  }
});

// ─── PERIOD LABEL CLICK → OPEN PICKER ─────────────────────────
document.getElementById('periodLabel').addEventListener('click', () => {
  if (!['week', 'month', 'year'].includes(currentPeriod)) return;
  const wp = document.getElementById('weekPicker');
  const mp = document.getElementById('monthPicker');
  const yp = document.getElementById('yearPicker');
  if (currentPeriod === 'week') {
    try { wp.showPicker(); } catch (e) { wp.focus(); }
  } else if (currentPeriod === 'month') {
    try { mp.showPicker(); } catch (e) { mp.focus(); }
  } else {
    yp.focus();
  }
});

// ─── KEYBOARD NAVIGATION ──────────────────────────────────────
document.addEventListener('keydown', e => {
  const tag = document.activeElement?.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
  if (document.activeElement?.isContentEditable) return;
  if (document.querySelector('.modal.open, .source-modal.open, [class*="modal"].open')) return;
  const mainApp = document.getElementById('mainApp');
  if (!mainApp || mainApp.style.display === 'none') return;

  const flash = btn => { if (btn) { btn.classList.remove('kb-flash'); void btn.offsetWidth; btn.classList.add('kb-flash'); } };

  switch (e.key) {
    case 'ArrowLeft': {
      e.preventDefault();
      const btn = document.getElementById('prevBtn');
      if (btn && !btn.disabled) { btn.click(); flash(btn); }
      break;
    }
    case 'ArrowRight': {
      e.preventDefault();
      const btn = document.getElementById('nextBtn');
      if (btn && !btn.disabled) { btn.click(); flash(btn); }
      break;
    }
    case 'w': case 'W': document.querySelector('#periodNav button[data-period="week"]')?.click(); break;
    case 'm': case 'M': document.querySelector('#periodNav button[data-period="month"]')?.click(); break;
    case 'y': case 'Y': document.querySelector('#periodNav button[data-period="year"]')?.click(); break;
    case 'a': case 'A': document.querySelector('#periodNav button[data-period="alltime"]')?.click(); break;
  }
});

// ─── SWIPE GESTURES (HammerJS) ────────────────────────────────
(function initSwipe() {
  if (typeof Hammer === 'undefined') return;
  const el = document.getElementById('mainApp');
  if (!el) return;
  const mc = new Hammer.Manager(el);
  mc.add(new Hammer.Swipe({ direction: Hammer.DIRECTION_HORIZONTAL, threshold: 25, velocity: 0.25 }));
  mc.on('swipeleft swiperight', e => {
    if (e.pointerType !== 'touch') return;
    if (!['week', 'month', 'year'].includes(currentPeriod)) return;
    if (e.srcEvent?.target?.tagName === 'CANVAS') return;
    document.getElementById('navHint')?.classList.add('swipe-done');
    if (e.direction === Hammer.DIRECTION_LEFT) {
      // Swipe left → go forward (earlier offset - 1)
      const btn = document.getElementById('nextBtn');
      if (btn && !btn.disabled) btn.click();
    } else {
      // Swipe right → go back (later offset + 1)
      const btn = document.getElementById('prevBtn');
      if (btn && !btn.disabled) btn.click();
    }
  });
})();

// ─── NEW ARTIST SONGS TOOLTIP ──────────────────────────────────
const _naTooltip = (() => {
  const el = document.createElement('div');
  el.id = 'naSongsTooltip';
  el.className = 'na-songs-tooltip';
  el.style.display = 'none';
  document.body.appendChild(el);
  return el;
})();

let _naHideTimer = null;

function _naShowTooltip(trigger) {
  clearTimeout(_naHideTimer);
  const artist = trigger.dataset.artist;
  let songs;
  try { songs = JSON.parse(trigger.dataset.songs); } catch { return; }
  const ytSvg = `<svg class="yt-btn-icon" viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2C0 8.1 0 12 0 12s0 3.9.5 5.8a3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1C24 15.9 24 12 24 12s0-3.9-.5-5.8zM9.7 15.5V8.5l6.3 3.5-6.3 3.5z"/></svg>`;
  _naTooltip.innerHTML = songs.map(title =>
    `<div class="na-tt-item">
      <span class="na-tt-name">${esc(title)}</span>
      <button class="yt-play-btn na-tt-yt-btn" data-title="${esc(title)}" data-artist="${esc(artist)}" data-album="" onclick="event.stopPropagation();ytPlayFromBtn(this)" title="Play on YouTube"><span class="yt-btn-content">${ytSvg}YouTube</span></button>${dcPlBtnHtml('song', title, artist, '')}
    </div>`
  ).join('');
  _naTooltip.style.display = 'block';
  const rect = trigger.getBoundingClientRect();
  const ttW = 280;
  let left = rect.left;
  let top = rect.bottom + 5;
  if (left + ttW > window.innerWidth - 8) left = window.innerWidth - ttW - 8;
  if (left < 8) left = 8;
  if (top + _naTooltip.offsetHeight > window.innerHeight - 8) top = rect.top - _naTooltip.offsetHeight - 5;
  _naTooltip.style.left = left + 'px';
  _naTooltip.style.top = top + 'px';
}

function _naHideTooltip() {
  _naHideTimer = setTimeout(() => { _naTooltip.style.display = 'none'; }, 130);
}


document.addEventListener('mouseover', e => {
  const trigger = e.target.closest('.na-songs-trigger');
  if (trigger) { _naShowTooltip(trigger); return; }
  if (e.target.closest('#naSongsTooltip')) { clearTimeout(_naHideTimer); }
});

document.addEventListener('mouseout', e => {
  if (!e.target.closest('.na-songs-trigger') && !e.target.closest('#naSongsTooltip')) return;
  const to = e.relatedTarget;
  if (to && (to.closest('.na-songs-trigger') || to.closest('#naSongsTooltip'))) return;
  _naHideTooltip();
});

// ─── EVENTS CALENDAR MINI-CARD TOOLTIP ─────────────────────────
const _calEvTooltip = (() => {
  const el = document.createElement('div');
  el.id = 'calEvTooltip';
  el.className = 'cal-ev-tooltip';
  el.style.display = 'none';
  document.body.appendChild(el);
  return el;
})();

let _calEvHideTimer = null;

function _calTtPlaceholderHtml(artist) {
  const words = (artist || '').replace(/^The\s+/i, '').split(/\s+/).filter(Boolean);
  const inits = words.slice(0, 2).map(w => w[0].toUpperCase()).join('');
  const colors = ['#0d2137', '#1a1040', '#0d2e1f', '#2b1a0d', '#0d1e2b', '#1f0d0d'];
  const hash = (artist || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0);
  return `<div class="ctt-placeholder" style="background:${colors[hash % colors.length]}">${inits}</div>`;
}

async function _loadCalTtArtistImg(imgWrap, artist) {
  try {
    const url = await deezerArtistImage(artist);
    if (!imgWrap.isConnected || !url) return;
    const ph = imgWrap.querySelector('.ctt-placeholder');
    if (!ph) return;
    const img = document.createElement('img');
    img.className = 'ctt-img';
    img.alt = '';
    img.onerror = () => {};
    img.src = url;
    imgWrap.replaceChild(img, ph);
  } catch (e) {}
}

function _showCalEvTooltip(target) {
  clearTimeout(_calEvHideTimer);
  const { ctt: evType = '', cta: artist = '', ctl: title = '', ctm: mbid = '', ctd: detail = '', ctx: dtxt = '', ctf: dtf = '' } = target.dataset;

  const mainTitle = evType === 'birthday' ? artist : title;
  const artistLine = evType !== 'birthday' ? `<div class="ctt-artist">${esc(artist)}</div>` : '';
  const dateLine = dtxt ? `<div class="ctt-date${dtf ? ' ' + dtf : ''}">${esc(dtxt)}</div>` : '';

  _calEvTooltip.innerHTML = `
    <div class="ctt-img-wrap"></div>
    <div class="ctt-body">
      ${dateLine}
      <div class="ctt-title">${esc(mainTitle)}</div>
      ${artistLine}
      <div class="ctt-type">${detail}</div>
    </div>`;

  const imgWrap = _calEvTooltip.querySelector('.ctt-img-wrap');
  if (mbid) {
    const img = document.createElement('img');
    img.className = 'ctt-img';
    img.alt = '';
    img.onerror = () => { if (imgWrap.isConnected) imgWrap.innerHTML = _calTtPlaceholderHtml(artist); };
    img.src = `https://coverartarchive.org/release-group/${mbid}/front-250`;
    imgWrap.appendChild(img);
  } else {
    imgWrap.innerHTML = _calTtPlaceholderHtml(artist);
    if (evType === 'birthday' && artist) _loadCalTtArtistImg(imgWrap, artist);
  }

  _calEvTooltip.style.display = 'flex';
  const rect = target.getBoundingClientRect();
  const ttW = _calEvTooltip.offsetWidth || 220;
  const ttH = _calEvTooltip.offsetHeight || 90;
  let left = rect.right + 8;
  let top = rect.top - 4;
  if (left + ttW > window.innerWidth - 8) left = rect.left - ttW - 8;
  if (top + ttH > window.innerHeight - 8) top = window.innerHeight - ttH - 8;
  _calEvTooltip.style.left = `${Math.max(8, left)}px`;
  _calEvTooltip.style.top = `${Math.max(8, top)}px`;
}

function _hideCalEvTooltip() {
  _calEvHideTimer = setTimeout(() => { _calEvTooltip.style.display = 'none'; }, 130);
}

document.addEventListener('mouseover', e => {
  const ev = e.target.closest('.cal-ev[data-ctt]');
  if (ev) { _showCalEvTooltip(ev); return; }
  if (e.target.closest('#calEvTooltip')) clearTimeout(_calEvHideTimer);
});

document.addEventListener('mouseout', e => {
  if (!e.target.closest('.cal-ev[data-ctt]') && !e.target.closest('#calEvTooltip')) return;
  const to = e.relatedTarget;
  if (to && (to.closest('.cal-ev[data-ctt]') || to.closest('#calEvTooltip'))) return;
  _hideCalEvTooltip();
});

// ─── TIME MACHINE ──────────────────────────────────────────────
const tmToggles = (() => {
  const saved = localStorage.getItem('dc_tm_toggles');
  if (saved) { try { return JSON.parse(saved); } catch (e) {} }
  return { songs: true, artists: true, albums: true };
})();
let tmData = null;
let tmImgQueue = Promise.resolve();
let tmLoaderId = 0;

function buildTimeMachineData() {
  const today = new Date();
  const todayMonth = today.getMonth();
  const todayDay = today.getDate();
  const todayYear = today.getFullYear();

  const pastPlays = allPlays.filter(p =>
    p.date instanceof Date &&
    p.date.getMonth() === todayMonth &&
    p.date.getDate() === todayDay &&
    p.date.getFullYear() < todayYear
  );

  const songsSeen = new Set();
  const songs = [];
  for (const p of pastPlays) {
    const year = p.date.getFullYear();
    const k = p.title + '\0' + p.artist + '\0' + year;
    if (!songsSeen.has(k)) {
      songsSeen.add(k);
      songs.push({ type: 'song', title: p.title, artist: p.artist, album: p.album || '—', year });
    }
  }

  const artistsSeen = new Set();
  const artists = [];
  for (const p of pastPlays) {
    const year = p.date.getFullYear();
    const list = (p.artists && p.artists.length) ? p.artists : [p.artist];
    for (const ar of list) {
      const k = ar + '\0' + year;
      if (!artistsSeen.has(k)) {
        artistsSeen.add(k);
        artists.push({ type: 'artist', artist: ar, year });
      }
    }
  }

  const albumsSeen = new Set();
  const albums = [];
  for (const p of pastPlays) {
    if (!p.album || p.album === '—') continue;
    const year = p.date.getFullYear();
    const aa = albumArtist(p);
    const k = p.album + '\0' + aa + '\0' + year;
    if (!albumsSeen.has(k)) {
      albumsSeen.add(k);
      albums.push({ type: 'album', album: p.album, artist: aa, year });
    }
  }

  return { songs, artists, albums };
}

function tmShuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function renderTimeMachine(forceRebuild) {
  const section = document.getElementById('timeMachineSection');
  const track = document.getElementById('tmTickerTrack');
  if (!section || !track || !allPlays.length) return;

  for (const type of ['songs', 'artists', 'albums']) {
    const btn = document.getElementById('tmToggle' + type.charAt(0).toUpperCase() + type.slice(1));
    if (btn) btn.classList.toggle('active', !!tmToggles[type]);
  }

  const newData = buildTimeMachineData();
  const newHash = newData.songs.length + '|' + newData.artists.length + '|' + newData.albums.length;

  // The Awards and Soundtrack tabs hide this section outright, and the block that
  // restores the chart UI on the way back out never puts it back — so visibility
  // has to be re-asserted here rather than only on the rebuild path below, or one
  // visit to either tab hides the ticker for the rest of the session (the hash is
  // unchanged, so this early return is exactly what runs). Guarded on the current
  // view: a background re-render while Awards or Soundtrack is on screen must not
  // pop the ticker back up over them.
  const tmHiddenView = currentPeriod === 'awards' || currentPeriod === 'soundtrack';

  if (!forceRebuild && tmData && tmData._hash === newHash && track.firstChild) {
    if (!tmHiddenView) section.style.display = ''; // cached cards are still in the track
    return;
  }

  newData._hash = newHash;
  tmData = newData;

  let entries = [];
  if (tmToggles.songs) entries = entries.concat(tmData.songs);
  if (tmToggles.artists) entries = entries.concat(tmData.artists);
  if (tmToggles.albums) entries = entries.concat(tmData.albums);
  entries = tmShuffle(entries);

  const tickerOuter = document.getElementById('tmTickerOuter');
  const emptyEl = document.getElementById('tmEmpty');
  const hintEl = document.getElementById('tmHint');
  // Nothing on the reel means nothing to save — the header button goes with it.
  const plBtn = document.getElementById('tmPlBtn');
  if (plBtn) plBtn.style.display = entries.length ? '' : 'none';
  // Did this day happen at all in past years? That is a different question from
  // whether anything is on screen — the type toggles can empty a day that has
  // plenty of history behind it.
  const hasDayData = tmData.songs.length || tmData.artists.length || tmData.albums.length;

  if (entries.length === 0) {
    if (tickerOuter) tickerOuter.style.display = 'none';
    track.innerHTML = '';
    // Nothing was played on this date in any past year — there is genuinely
    // nothing to show, so the section stays out of the way.
    if (!hasDayData) { section.style.display = 'none'; return; }
    // Otherwise all three types are switched off. Keep the section on screen with
    // an empty state instead of vanishing: the Songs/Artists/Albums buttons live
    // in its own header, so hiding it strands the user with no way to switch one
    // back on — and the state rides along in Firestore, so neither a reload nor a
    // cache clear undoes it. The card hint would be nonsense with no cards.
    if (!tmHiddenView) section.style.display = '';
    if (emptyEl) emptyEl.style.display = '';
    if (hintEl) hintEl.style.display = 'none';
    return;
  }
  if (!tmHiddenView) section.style.display = ''; // same view guard as the early return above
  if (tickerOuter) tickerOuter.style.display = '';
  if (emptyEl) emptyEl.style.display = 'none';
  if (hintEl) hintEl.style.display = '';

  tmImgQueue = Promise.resolve();
  const myLoaderId = ++tmLoaderId;

  const aSongItems = [], aArtistItems = [], aAlbumItems = [];
  const bSongItems = [], bArtistItems = [], bAlbumItems = [];

  /* The deck is rendered twice so the reel can wrap seamlessly (see
     dcMountReel). Copy B is tagged, because a deck short enough to fit on
     screen has nothing to wrap onto and would just show everything twice. */
  function buildCard(entry, i, suffix, songArr, artistArr, albumArr) {
    const imgId = 'tmimg-' + suffix + '-' + i;
    const dupe = suffix === 'b' ? ' dcreel-dupe' : '';
    if (entry.type === 'song') {
      const sub = entry.artist + (entry.album && entry.album !== '—' ? ' · ' + entry.album : '');
      const prefKey = 'song:' + entry.artist.toLowerCase() + '|||' + entry.title.toLowerCase();
      songArr.push({ imgId, title: entry.title, artist: entry.artist, album: entry.album, name: entry.title, prefKey });
      return '<div class="tm-card tm-card-song' + dupe + '" data-type="song" onclick="_tmShowSongMenu(event,' + esc(JSON.stringify(entry.title)) + ',' + esc(JSON.stringify(entry.artist)) + ',' + esc(JSON.stringify(entry.album)) + ')">' +
        '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.title)) + '</div></div>' +
        '<div class="tm-card-info">' +
        '<div class="tm-card-title">' + esc(entry.title) + '</div>' +
        '<div class="tm-card-sub">' + esc(sub) + '</div>' +
        '<div class="tm-card-year">' + entry.year + '</div>' +
        '</div></div>';
    } else if (entry.type === 'artist') {
      const prefKey = 'artist:' + entry.artist.toLowerCase();
      artistArr.push({ imgId, name: entry.artist, artist: entry.artist, album: '', title: '', prefKey });
      return '<div class="tm-card tm-card-search' + dupe + '" data-type="artist" onclick="_tmShowArtistMenu(event,' + esc(JSON.stringify(entry.artist)) + ')">' +
        '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.artist)) + '</div></div>' +
        '<div class="tm-card-info">' +
        '<div class="tm-card-title">' + esc(entry.artist) + '</div>' +
        '<div class="tm-card-year">' + entry.year + '</div>' +
        '</div></div>';
    } else {
      const prefKey = 'album:' + entry.artist.toLowerCase() + '|||' + entry.album.toLowerCase();
      albumArr.push({ imgId, album: entry.album, artist: entry.artist, name: entry.album, title: '', prefKey });
      return '<div class="tm-card tm-card-search' + dupe + '" data-type="album" onclick="_tmShowAlbumMenu(event,' + esc(JSON.stringify(entry.album)) + ',' + esc(JSON.stringify(entry.artist)) + ')">' +
        '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.album)) + '</div></div>' +
        '<div class="tm-card-info">' +
        '<div class="tm-card-title">' + esc(entry.album) + '</div>' +
        '<div class="tm-card-sub">' + esc(entry.artist) + '</div>' +
        '<div class="tm-card-year">' + entry.year + '</div>' +
        '</div></div>';
    }
  }

  const firstCopy = entries.map((e, i) => buildCard(e, i, 'a', aSongItems, aArtistItems, aAlbumItems)).join('');
  const secondCopy = entries.map((e, i) => buildCard(e, i, 'b', bSongItems, bArtistItems, bAlbumItems)).join('');

  track.innerHTML = firstCopy + secondCopy;
  /* Was a CSS marquee; the pace is now the reel's drift and it can be grabbed
     and dragged. See dcMountReel(). 5s a card rather than the marquee's 4 —
     this is the reel that sits on the charts page all day, and it reads as
     something to browse rather than something going past. */
  dcMountReel(tickerOuter, track, Math.max(20, entries.length * 5));

  // Load images for a-copy in parallel batches; mirror results to b-copy (halves API calls)
  async function loadTmBatch(aPairs, type, loaderId) {
    const BATCH = 4;
    for (let i = 0; i < aPairs.length; i += BATCH) {
      if (tmLoaderId !== loaderId) return;
      await Promise.all(aPairs.slice(i, i + BATCH).map(async ([aItem, bItem]) => {
        if (tmLoaderId !== loaderId) return;
        const aEl = document.getElementById(aItem.imgId);
        if (!aEl) return;
        await fetchAndInjectImage(aEl, aItem, type);
        const bEl = document.getElementById(bItem.imgId);
        if (bEl) bEl.innerHTML = aEl.innerHTML;
      }));
    }
  }

  const ldr = myLoaderId;
  const songPairs  = aSongItems.map((a, i) => [a, bSongItems[i]]);
  const artistPairs = aArtistItems.map((a, i) => [a, bArtistItems[i]]);
  const albumPairs  = aAlbumItems.map((a, i) => [a, bAlbumItems[i]]);

  tmImgQueue = tmImgQueue
    .then(() => loadTmBatch(songPairs,   'song',   ldr))
    .then(() => loadTmBatch(artistPairs, 'artist', ldr))
    .then(() => loadTmBatch(albumPairs,  'album',  ldr));
}

// Everything the reel is currently showing, straight into the picker. Artist and
// album cards have no track of their own, so each contributes its single most
// recent play — a deck of only artists still yields a playlist rather than
// nothing, and one entry each keeps the result the length of what's on screen.
function tmAddAllToPlaylist() {
  if (!tmData) return;
  const tracks = [];
  if (tmToggles.songs)   tmData.songs.forEach(e => tracks.push({ title: e.title, artist: e.artist, album: e.album }));
  if (tmToggles.artists) tmData.artists.forEach(e => { const s = _tmArtistLastSongs(e.artist, 1)[0]; if (s) tracks.push(s); });
  if (tmToggles.albums)  tmData.albums.forEach(e => { const s = _tmAlbumLastSongs(e.album, e.artist, 1)[0]; if (s) tracks.push(s); });
  const label = t('time_machine_title').replace(/^[^\p{L}]+/u, ''); // drop the ⏳ from the tab title
  dcOpenPlaylistPicker(tracks, label, `${label} · ${_dcPlDateTag()}`);
}

function tmToggleType(type) {
  tmToggles[type] = !tmToggles[type];
  const id = 'tmToggle' + type.charAt(0).toUpperCase() + type.slice(1);
  const btn = document.getElementById(id);
  if (btn) btn.classList.toggle('active', tmToggles[type]);
  localStorage.setItem('dc_tm_toggles', JSON.stringify(tmToggles));
  if (typeof dcSaveUserConfig === 'function') dcSaveUserConfig();
  renderTimeMachine(true);
}

// ── Time Machine action menus — tooltip-style popups for song and artist cards ──
let _tmMenuEl = null;
// The reel this menu is parked on, if any. These menus are opened from the Time
// Machine, the Soundtrack reel and the Events reels alike, so which one to hold
// still is a question about the card that was clicked, not a fixed element.
let _tmPausedReel = null;

function _tmCloseMenu() {
  if (_tmMenuEl) { _tmMenuEl.remove(); _tmMenuEl = null; }
  if (_tmPausedReel) { _tmPausedReel.dataset.reelPaused = '0'; _tmPausedReel = null; }
  document.removeEventListener('click', _tmOutsideMenuClick, true);
  document.removeEventListener('keydown', _tmMenuKeydown, true);
  window.removeEventListener('scroll', _tmCloseMenu, true);
  window.removeEventListener('resize', _tmCloseMenu, true);
}

function _tmOutsideMenuClick(e) {
  if (_tmMenuEl && !_tmMenuEl.contains(e.target)) _tmCloseMenu();
}

function _tmMenuKeydown(e) {
  if (e.key === 'Escape') _tmCloseMenu();
}

// Anchors an already-built (and already-appended) menu to its trigger card, as a tooltip:
// centered above by default, flipping below if there's no room. Re-run after content changes.
function _tmPositionMenu(menu, card) {
  menu.classList.remove('tm-action-menu--top', 'tm-action-menu--bottom');
  const r = card.getBoundingClientRect();
  const mr = menu.getBoundingClientRect();
  let placement = 'top';
  let top = r.top - mr.height - 8;
  if (top < 8) { top = r.bottom + 8; placement = 'bottom'; }
  menu.classList.add('tm-action-menu--' + placement);

  let left = r.left + r.width / 2 - mr.width / 2;
  left = Math.max(8, Math.min(left, window.innerWidth - mr.width - 8));
  menu.style.top = (top + window.scrollY) + 'px';
  menu.style.left = (left + window.scrollX) + 'px';

  const arrow = menu.querySelector('.tm-action-menu-arrow');
  if (arrow) {
    let arrowLeft = (r.left + r.width / 2) - left;
    arrowLeft = Math.max(12, Math.min(arrowLeft, mr.width - 12));
    arrow.style.left = arrowLeft + 'px';
  }
}

// Opens `menu` (already filled with its first view) as a tooltip on `card`, wiring up
// the shared dismiss handlers (outside click, Escape, scroll, resize) and pausing the ticker.
function _tmOpenMenu(menu, card) {
  document.body.appendChild(menu);
  _tmPositionMenu(menu, card);

  // A card that keeps drifting walks out from under its own menu, so whichever
  // reel this card belongs to parks until the menu closes.
  _tmPausedReel = card.closest('.dcreel');
  if (_tmPausedReel) _tmPausedReel.dataset.reelPaused = '1';

  _tmMenuEl = menu;
  setTimeout(() => {
    document.addEventListener('click', _tmOutsideMenuClick, true);
    document.addEventListener('keydown', _tmMenuKeydown, true);
    window.addEventListener('scroll', _tmCloseMenu, true);
    window.addEventListener('resize', _tmCloseMenu, true);
  }, 0);
}

function _tmShowSongMenu(ev, title, artist, album) {
  ev.stopPropagation();
  const card = ev.currentTarget;
  _tmCloseMenu();

  const q = encodeURIComponent(title + ' ' + artist);
  const menu = document.createElement('div');
  menu.className = 'tm-action-menu';
  menu.innerHTML =
    '<div class="tm-action-menu-arrow"></div>' +
    '<button class="tm-action-menu-item" data-act="spotify">🎧 ' + esc(t('tm_action_spotify')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="playlist">' + DC_PL_ICON + esc(t('tm_action_playlist')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="player">▶ ' + esc(t('tm_action_player')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="google">🔎 ' + esc(t('tm_action_google')) + '</button>';

  menu.querySelector('[data-act="spotify"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://open.spotify.com/search/' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });
  // Saves the song to a playlist instead of the player queue — the menu closes
  // first so the picker isn't fighting the popup's outside-click handler.
  menu.querySelector('[data-act="playlist"]').addEventListener('click', (e) => {
    e.stopPropagation();
    _tmCloseMenu();
    dcOpenPlaylistPicker([{ title, artist, album }], title, title);
  });
  menu.querySelector('[data-act="player"]').addEventListener('click', (e) => {
    e.stopPropagation();
    _ytPlayOrQueue(title, artist, album);
    _tmCloseMenu();
  });
  menu.querySelector('[data-act="google"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://www.google.com/search?q=' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });

  _tmOpenMenu(menu, card);
}

// Most-recently-played songs by an artist, newest first (allPlays is sorted newest-first).
function _tmArtistLastSongs(artist, limit) {
  const seen = new Set();
  const out = [];
  for (const p of allPlays) {
    const list = (p.artists && p.artists.length) ? p.artists : [p.artist];
    if (!list.includes(artist)) continue;
    const key = p.title.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ title: p.title, artist, album: p.album || '' });
    if (out.length >= limit) break;
  }
  return out;
}

function _tmQueueToast(n) {
  const statusEl = document.getElementById('ytMiniStatus');
  if (!statusEl) return;
  const msg = t(n === 1 ? 'tm_action_queued_toast_one' : 'tm_action_queued_toast_other', { n });
  statusEl.textContent = msg;
  statusEl.className = 'yt-mini-status ok';
  setTimeout(() => { if (statusEl.textContent === msg) { statusEl.textContent = ''; statusEl.className = 'yt-mini-status'; } }, 2500);
}

// Shared popup for artist/album cards: Spotify search, a playlist option, a
// "last 10 songs" sub-view (add one-by-one or all at once), and a Google search.
// `searchQuery` drives both the Spotify and Google links; `fetchSongs(limit)`
// supplies the songs for the sub-view; `plLabel` names the entity in the
// playlist picker (the search query reads badly there — it's "Album Artist");
// `plFallback` is what the playlist option stages when there's no play history
// at all, and is the only reason that option can appear when the queue ones
// don't.
function _tmShowEntityMenu(ev, searchQuery, fetchSongs, plLabel, plFallback) {
  ev.stopPropagation();
  const card = ev.currentTarget;
  _tmCloseMenu();

  const q = encodeURIComponent(searchQuery);
  const menu = document.createElement('div');
  menu.className = 'tm-action-menu';

  function renderMain() {
    // Only offer the player queue if there's actually play history to queue from —
    // e.g. a Recent Release the user hasn't listened to yet shouldn't show it.
    const hasPlays = fetchSongs(1).length > 0;
    const canPlaylist = hasPlays || (plFallback && plFallback.length);
    menu.innerHTML =
      '<div class="tm-action-menu-arrow"></div>' +
      '<button class="tm-action-menu-item" data-act="spotify">🎧 ' + esc(t('tm_action_spotify')) + '</button>' +
      (canPlaylist ? '<button class="tm-action-menu-item" data-act="playlist">' + DC_PL_ICON + esc(t('tm_action_playlist')) + '</button>' : '') +
      (hasPlays ? '<button class="tm-action-menu-item" data-act="last10">🎵 ' + esc(t('tm_action_last10')) + '</button>' : '') +
      '<button class="tm-action-menu-item" data-act="google">🔎 ' + esc(t('tm_action_google')) + '</button>';
    menu.querySelector('[data-act="spotify"]').addEventListener('click', (e) => {
      e.stopPropagation();
      window.open('https://open.spotify.com/search/' + q, '_blank', 'noopener');
      _tmCloseMenu();
    });
    if (canPlaylist) {
      // Stages a deeper slice than the "last 10" sub-view offers — picking a
      // playlist is a deliberate act, so it's worth carrying more of the history.
      menu.querySelector('[data-act="playlist"]').addEventListener('click', (e) => {
        e.stopPropagation();
        const songs = hasPlays ? fetchSongs(DC_PL_ENTITY_LIMIT) : plFallback;
        _tmCloseMenu();
        dcOpenPlaylistPicker(songs, plLabel, plLabel);
      });
    }
    if (hasPlays) {
      menu.querySelector('[data-act="last10"]').addEventListener('click', (e) => {
        e.stopPropagation();
        renderSongs();
        _tmPositionMenu(menu, card);
      });
    }
    menu.querySelector('[data-act="google"]').addEventListener('click', (e) => {
      e.stopPropagation();
      window.open('https://www.google.com/search?q=' + q, '_blank', 'noopener');
      _tmCloseMenu();
    });
  }

  function renderSongs() {
    const songs = fetchSongs(10);
    const backBtn = '<button class="tm-action-menu-back" data-act="back">‹ ' + esc(t('tm_action_last10')) + '</button>';
    if (!songs.length) {
      menu.innerHTML = '<div class="tm-action-menu-arrow"></div>' + backBtn +
        '<div class="tm-action-menu-empty">' + esc(t('tm_action_no_songs')) + '</div>';
      menu.querySelector('[data-act="back"]').addEventListener('click', (e) => { e.stopPropagation(); renderMain(); _tmPositionMenu(menu, card); });
      return;
    }
    menu.innerHTML =
      '<div class="tm-action-menu-arrow"></div>' + backBtn +
      '<button class="tm-action-menu-item" data-act="plall">' + DC_PL_ICON + esc(t('tm_action_pl_all')) + '</button>' +
      '<button class="tm-action-menu-item tm-action-menu-addall" data-act="addall">➕ ' + esc(t('tm_action_add_all')) + '</button>' +
      '<div class="tm-action-menu-songs">' +
      songs.map((s, i) => '<div class="tm-action-menu-song">' +
        '<span class="tm-action-menu-song-title">' + esc(s.title) + '</span>' +
        '<button class="tm-action-menu-song-add" data-i="' + i + '" title="' + esc(t('tm_action_add_one')) + '">+</button>' +
        '</div>').join('') +
      '</div>';

    menu.querySelector('[data-act="back"]').addEventListener('click', (e) => { e.stopPropagation(); renderMain(); _tmPositionMenu(menu, card); });
    // Same set the sub-view is showing, straight into a playlist rather than the queue.
    menu.querySelector('[data-act="plall"]').addEventListener('click', (e) => {
      e.stopPropagation();
      _tmCloseMenu();
      dcOpenPlaylistPicker(songs, plLabel, plLabel);
    });
    menu.querySelector('[data-act="addall"]').addEventListener('click', (e) => {
      e.stopPropagation();
      const playerEl = document.getElementById('ytMiniPlayer');
      const playerActive = _ytCurrentTrack && playerEl && playerEl.style.display !== 'none';
      let toQueue = songs;
      if (!playerActive) {
        // Nothing playing yet — open the player on the first song instead of silently queuing it.
        const [first, ...rest] = songs;
        openYtPlayer(first.title, first.artist, first.album, null);
        toQueue = rest;
      }
      toQueue.forEach(s => _ytQueue.push({ title: s.title, artist: s.artist, album: s.album, btn: null }));
      _ytUpdateQueueDisplay();
      _ytSaveQueue();
      _tmQueueToast(songs.length);
      _tmCloseMenu();
    });
    menu.querySelectorAll('.tm-action-menu-song-add').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const s = songs[+btn.dataset.i];
        _ytStreakPlay(s.title, s.artist);
      });
    });
  }

  renderMain();
  _tmOpenMenu(menu, card);
}

function _tmShowArtistMenu(ev, artist) {
  _tmShowEntityMenu(ev, artist, (limit) => _tmArtistLastSongs(artist, limit), artist);
}

// Most-recently-played songs from an album (by this artist), newest first.
function _tmAlbumLastSongs(album, artist, limit) {
  const seen = new Set();
  const out = [];
  for (const p of allPlays) {
    if (!p.album || p.album.toLowerCase() !== album.toLowerCase()) continue;
    if (albumArtist(p).toLowerCase() !== artist.toLowerCase()) continue;
    const key = p.title.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ title: p.title, artist, album });
    if (out.length >= limit) break;
  }
  return out;
}

function _tmShowAlbumMenu(ev, album, artist) {
  // The playlist fallback is the release itself: an anniversary or a recent
  // release the user has never played has no tracks in history, but "Artist –
  // Release" is still a perfectly good thing to save. It stays out of
  // fetchSongs so the player-queue options keep their play-history-only rule.
  _tmShowEntityMenu(ev, album + ' ' + artist, (limit) => _tmAlbumLastSongs(album, artist, limit),
    album, [{ title: album, artist, album }]);
}

// Tooltip popup for unreleased upcoming-release cards (the main Upcoming Releases section
// and the Events tab's Upcoming Releases). No "add to player" option — nothing to play yet.
function _relShowMenu(ev, title, artist) {
  ev.stopPropagation();
  const card = ev.currentTarget;
  _tmCloseMenu();

  const q = encodeURIComponent(title + ' ' + artist);
  const menu = document.createElement('div');
  menu.className = 'tm-action-menu';
  menu.innerHTML =
    '<div class="tm-action-menu-arrow"></div>' +
    '<button class="tm-action-menu-item" data-act="spotify">🎧 ' + esc(t('tm_action_spotify')) + '</button>' +
    '<button class="tm-action-menu-item" data-act="google">🔎 ' + esc(t('tm_action_google')) + '</button>';

  menu.querySelector('[data-act="spotify"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://open.spotify.com/search/' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });
  menu.querySelector('[data-act="google"]').addEventListener('click', (e) => {
    e.stopPropagation();
    window.open('https://www.google.com/search?q=' + q, '_blank', 'noopener');
    _tmCloseMenu();
  });

  _tmOpenMenu(menu, card);
}

