const COLLAB_EXCEPTIONS = [
  'Tyler, The Creator', 'Earth, Wind & Fire', 'Simon & Garfunkel',
  'Of Monsters and Men', 'Panic! at the Disco', 'Portugal. The Man',
];

let _awardsYear     = tzNow().getFullYear() - 1;
let _awardsYearData = {};
let _awardsSubTab   = 'mygrammys';
let _awardsGenreCache = {};
let _awardsGenreQueue = {};
const _awardsAlbumYearCache = {};
// --- Nominee picker state (all reset every time the modal opens) ---
let _awardsPickerSel      = [];        // ordered list of chosen nominees (order = display order)
let _awardsPickerSelKeys  = new Set(); // _awardItemKey() of everything in _awardsPickerSel, for O(1) lookups
let _awardsPickerCatType  = '';
let _awardsPickerCatFilter = '';
let _awardsPickerEligWin  = { start: '', end: '' };
let _awardsPickerAutoCands = [];
let _awardsPickerAllItems = [];        // every song/album/artist played in the eligibility window, built once per open
let _awardsPickerSuggKeys = new Set(); // keys of the auto-generated suggestions, so they can be pinned to the top
let _awardsPickerSort     = 'plays';   // plays | az | recent
let _awardsPickerShown    = 60;        // how many rows of the current list are rendered ("Show more" bumps this)
let _awardsPickerRows     = [];        // items currently rendered in the body, index-addressable for clicks/keyboard
let _awardsPickerActive   = -1;        // keyboard-highlighted row, -1 = none
let _awardsPickerCtx      = { year: 0, catId: '', typeLabel: '' };
let _awardsPickerKeyHandler = null;    // document keydown listener, removed on close
let _awardsPickerDragFrom = -1;        // index of the nominee chip being dragged
const AWARDS_PICKER_PAGE  = 60;        // rows added per "Show more"
let _realLifeYear   = tzNow().getFullYear();

function _awardsDefaultData(year) {
  const cats = {};
  for (const cat of AWARD_CATEGORIES) {
    cats[cat.id] = { enabled: cat.defaultOn, nominees: [], winner: null };
  }
  return { year, eligStart: `${year}-01-01`, eligEnd: `${year}-12-31`, categories: cats };
}

async function _awardsLoad(year) {
  if (_awardsYearData[year]) return _awardsYearData[year];
  const remote = (typeof dcLoadAwards === 'function') ? await dcLoadAwards(year) : null;
  if (remote) {
    // Ensure any newly-added categories exist in the loaded data
    for (const cat of AWARD_CATEGORIES) {
      if (!remote.categories[cat.id]) remote.categories[cat.id] = { enabled: cat.defaultOn, nominees: [], winner: null };
    }
    _awardsYearData[year] = remote;
  } else {
    _awardsYearData[year] = _awardsDefaultData(year);
  }
  return _awardsYearData[year];
}

async function _awardsEnsureAllYearsLoaded() {
  if (!allPlays.length) return;
  const minYear = tzDate(allPlays[allPlays.length - 1].date).getFullYear();
  const maxYear = tzNow().getFullYear();
  const toLoad = [];
  for (let y = minYear; y <= maxYear; y++) {
    if (!_awardsYearData[y]) toLoad.push(_awardsLoad(y));
  }
  if (toLoad.length) await Promise.all(toLoad);
}

function _renderModalGrammyStrip(artistName) {
  const catMap = Object.fromEntries(AWARD_CATEGORIES.map(c => [c.id, c]));
  const entries = [];
  for (const [year, yearData] of Object.entries(_awardsYearData)) {
    if (!yearData?.categories) continue;
    for (const [catId, cat] of Object.entries(yearData.categories)) {
      if (!cat.enabled) continue;
      const catInfo = catMap[catId];
      if (!catInfo) continue;
      const inNominees = (cat.nominees || []).some(n => n.artist === artistName);
      const isWinner = cat.winner?.artist === artistName;
      if (inNominees || isWinner) entries.push({ year: parseInt(year), label: catInfo.label, isWin: isWinner });
    }
  }
  entries.sort((a, b) => (b.isWin - a.isWin) || (b.year - a.year));
  const noms = entries.length;
  const wins = entries.filter(e => e.isWin).length;
  const grammyEl = document.getElementById('modalGrammyStrip');
  grammyEl.innerHTML = `
    <div class="modal-stat"><div class="se">🏅</div><div class="sv" data-countup="${noms}">${noms}</div><div class="sl">Nominations</div></div>
    <div class="modal-stat ${wins > 0 ? 'modal-stat--gold' : ''}"><div class="se">🏆</div><div class="sv ${wins > 0 ? 'sv--gold' : ''}" data-countup="${wins}">${wins}</div><div class="sl">Wins</div></div>
  `;
  animateModalCountup(grammyEl);
  const detailEl = document.getElementById('modalGrammyDetail');
  if (entries.length > 0) {
    const n = entries.length;
    const listHTML = entries.map(e =>
      `<div class="modal-grammy-entry${e.isWin ? ' modal-grammy-entry--win' : ''}"><span class="mge-icon">${e.isWin ? '🏆' : '🏅'}</span><span class="mge-year">${e.year}</span><span class="mge-cat">${esc(e.label)}</span></div>`
    ).join('');
    detailEl.innerHTML = `<button class="modal-grammy-toggle" onclick="toggleModalGrammyDetail(this)" data-count="${n}">▾ Show all ${n} categor${n === 1 ? 'y' : 'ies'}</button><div class="modal-grammy-list" style="display:none">${listHTML}</div>`;
  } else {
    detailEl.innerHTML = '';
  }
}

async function _awardsSave(year) {
  const data = _awardsYearData[year];
  if (!data) return;
  if (typeof dcSaveAwards === 'function') await dcSaveAwards(year, data);
}

function _isCollab(play) {
  if (Array.isArray(play.artists) && play.artists.length > 1) return true;
  const artist = play.artist || '';
  const cleaned = COLLAB_EXCEPTIONS.reduce((s, ex) => s.replace(ex, ex.replace(/,/g, '​')), artist);
  const parts = cleaned.split(/,|(?:\s+(?:&|feat\.?|ft\.?|x)\s+)/i).map(s => s.trim()).filter(Boolean);
  return parts.length > 1;
}

function _isDuo(play) {
  if (Array.isArray(play.artists)) return play.artists.length === 2;
  const artist = play.artist || '';
  const cleaned = COLLAB_EXCEPTIONS.reduce((s, ex) => s.replace(ex, ex.replace(/,/g, '​')), artist);
  const parts = cleaned.split(/,|(?:\s+(?:&|feat\.?|ft\.?|x)\s+)/i).map(s => s.trim()).filter(Boolean);
  return parts.length === 2;
}

function _isRemix(play) {
  return /\b(remix|remaster|edit|version|cover)\b/i.test(play.title || '');
}

function _hasNonLatinScript(str) {
  return /[Ѐ-ӿ؀-ۿऀ-ॿ぀-ヿ㐀-䶿一-鿿가-힯฀-๿ᄀ-ᇿ]/.test(str || '');
}

// Matches the app-wide songKey() convention (title+full-artist, trimmed) so a song's
// play count in Awards never splits from its count on the main Songs chart due to
// stray whitespace from CSV/Sheets imports.
function _sk(p) { return `${(p.title||'').toLowerCase().trim()}|||${(p.artist||'').toLowerCase().trim()}`; }
function _pa(p)  { return (Array.isArray(p.artists) && p.artists.length) ? p.artists[0] : (p.artist || ''); }
function _pk(p)  { return _pa(p).toLowerCase(); }
// Album/artist keys use the primary artist (via _pk), matching _awardsCountMaps and the
// app-wide albumArtist() convention — keeps every Awards category consistent so a collab
// track's album/artist isn't treated as a different entity depending on which category built it.
function _ak(p) { return `${(p.album||'').toLowerCase()}|||${_pk(p)}`; }
function _rk(p) { return _pk(p); }

function _awardsCountMaps(plays) {
  const songs = {}, albums = {}, artists = {};
  for (const p of plays) {
    const sk = _sk(p), pk = _pk(p);
    const albumKey = `${(p.album||'').toLowerCase()}|||${pk}`;
    if (!songs[sk])   songs[sk]   = { title: p.title,  artist: p.artist, album: p.album, plays: 0 };
    if (!albums[albumKey] && p.album) albums[albumKey] = { album: p.album, artist: _pa(p), plays: 0 };
    if (!artists[pk]) artists[pk] = { artist: _pa(p), plays: 0 };
    songs[sk].plays++;
    if (p.album) albums[albumKey].plays++;
    artists[pk].plays++;
  }
  return { songs, albums, artists };
}

function _awardsTopN(map, n, cap) {
  cap = cap || 3;
  const sorted = Object.values(map).sort((a, b) => b.plays - a.plays);
  const result = [], ac = {};
  for (const item of sorted) {
    const key = (item.artist || '').toLowerCase();
    ac[key] = (ac[key] || 0);
    if (ac[key] >= cap) continue;
    ac[key]++;
    result.push(item);
    if (result.length >= n) break;
  }
  return result;
}

async function _awardsGetArtistGenre(artist) {
  const key = (artist || '').toLowerCase();
  if (_awardsGenreCache[key] !== undefined) return _awardsGenreCache[key];
  if (_awardsGenreQueue[key]) return _awardsGenreQueue[key];
  const apiKey = localStorage.getItem('dc_lfm_api_key') || 'a8a5bfd6f2e57c45c4bdf6b5c58e1cd5';
  _awardsGenreQueue[key] = fetch(
    `https://ws.audioscrobbler.com/2.0/?method=artist.gettoptags&artist=${encodeURIComponent(artist)}&api_key=${encodeURIComponent(apiKey)}&format=json`
  ).then(r => r.json()).then(d => {
    const tags = (d?.toptags?.tag || []).map(t => t.name.toLowerCase()).slice(0, 10);
    _awardsGenreCache[key] = tags;
    delete _awardsGenreQueue[key];
    return tags;
  }).catch(() => { _awardsGenreCache[key] = []; delete _awardsGenreQueue[key]; return []; });
  return _awardsGenreQueue[key];
}

async function _awardsGetAlbumYear(album, artist) {
  const key = album.toLowerCase() + '|||' + artist.toLowerCase();
  if (key in _awardsAlbumYearCache) return _awardsAlbumYearCache[key];
  const albumL      = album.toLowerCase();
  const artistW     = artist.toLowerCase().split(/[\s,&]/)[0];
  const searchArtist = artist.split(',')[0].trim(); // drop collab artists for API queries

  // 1. iTunes
  try {
    const q = encodeURIComponent(searchArtist + ' ' + album);
    const r = await fetch(`https://itunes.apple.com/search?term=${q}&entity=album&limit=10`);
    const d = await r.json();
    const results = d?.results || [];
    const match = results.find(x =>
      x.collectionName?.toLowerCase().includes(albumL) &&
      x.artistName?.toLowerCase().includes(artistW)
    );
    if (match?.releaseDate) {
      const year = new Date(match.releaseDate).getFullYear();
      _awardsAlbumYearCache[key] = year;
      return year;
    }
  } catch (e) {}

  // 2. Deezer
  try {
    const r = await deezerFetch(`search/album?q=${encodeURIComponent(searchArtist + ' ' + album)}&limit=10`);
    if (r.ok) {
      const d = await r.json();
      const items = d?.data || [];
      const match = items.find(x =>
        x.title?.toLowerCase().includes(albumL) &&
        x.artist?.name?.toLowerCase().includes(artistW)
      );
      const year = match?.release_date ? parseInt(match.release_date.slice(0, 4), 10) : null;
      if (year) {
        _awardsAlbumYearCache[key] = year;
        return year;
      }
    }
  } catch (e) {}

  // 3. MusicBrainz
  try {
    const mbid = await searchArtistMBID(searchArtist);
    if (mbid) {
      const groups = await fetchAllReleasesRaw(mbid);
      const match = groups.find(g => g.title?.toLowerCase() === albumL)
        || groups.find(g => g.title?.toLowerCase().includes(albumL));
      const year = match?.['first-release-date'] ? parseInt(match['first-release-date'].slice(0, 4), 10) : null;
      if (year) {
        _awardsAlbumYearCache[key] = year;
        return year;
      }
    }
  } catch (e) {}

  _awardsAlbumYearCache[key] = null;
  return null;
}

function _genreMatch(tags, filterStr) {
  const g = filterStr.replace('genre:', '');
  const aliases = {
    'pop':         ['pop','dance pop','electropop','synth-pop','teen pop','pop rock','indie pop'],
    'rock':        ['rock','classic rock','hard rock','indie rock','punk rock','alternative rock','metal','emo','post-rock'],
    'alternative': ['alternative','indie','indie rock','alternative rock','post-punk','dream pop','shoegaze'],
    'hip-hop':     ['hip-hop','hip hop','rap','trap','conscious hip hop'],
    'rnb':         ['r&b','soul','neo soul','contemporary r&b','rnb','rhythm and blues'],
    'latin':       ['latin','reggaeton','latin pop','salsa','cumbia','bachata','latin rap','regional mexicano'],
    'electronic':  ['electronic','edm','house','techno','dance','electro','synth-pop','trance','ambient'],
    'k-pop':       ['k-pop','kpop','korean pop','k pop','korean'],
  };
  const list = aliases[g] || [g];
  return tags.some(t => list.some(m => t === m));
}

async function _awardsGeminiClassifyArtists(artists) {
  const apiKey = localStorage.getItem('dc_gemini_api_key');
  if (!apiKey) return;
  const needed = artists.filter(a => _awardsGenreCache[a.toLowerCase()] === undefined);
  if (!needed.length) return;
  const tags = 'rock, classic rock, hard rock, indie rock, punk rock, alternative rock, metal, emo, post-rock, alternative, indie, indie rock, post-punk, dream pop, shoegaze, hip-hop, hip hop, rap, trap, conscious hip hop, r&b, soul, neo soul, contemporary r&b, rnb, rhythm and blues, pop, dance pop, indie pop, pop rock, teen pop, synth-pop, electropop, latin, reggaeton, latin pop, salsa, cumbia, bachata, latin rap, regional mexicano, electronic, edm, house, techno, dance, electro, trance, ambient, k-pop, kpop, korean pop, k pop, korean';
  const prompt = `Classify each music artist using ONLY these genre tags (use multiple per artist if applicable):\n${tags}\n\nReturn a JSON object: { "Artist Name": ["tag1", "tag2"] }. Include every artist listed, even if unsure — guess based on your knowledge.\n\nArtists to classify:\n${needed.join('\n')}`;
  try {
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${encodeURIComponent(apiKey)}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { responseMimeType: 'application/json', temperature: 0 }
      })
    });
    if (!res.ok) throw new Error('Gemini ' + res.status);
    const d = await res.json();
    const text = d?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) throw new Error('empty response');
    const map = JSON.parse(text);
    for (const [artist, artistTags] of Object.entries(map)) {
      const key = artist.toLowerCase();
      if (needed.some(a => a.toLowerCase() === key)) {
        _awardsGenreCache[key] = Array.isArray(artistTags) ? artistTags.map(t => String(t).toLowerCase()) : [];
      }
    }
  } catch (e) { /* fall through to Last.fm */ }
}

async function _awardsGetCandidates(catDef, eligStart, eligEnd, log) {
  const start = new Date(eligStart + 'T00:00:00');
  const end   = new Date(eligEnd   + 'T23:59:59');
  const inWin = allPlays.filter(p => p.date >= start && p.date <= end);
  if (!inWin.length) return [];
  const { songs, albums, artists } = _awardsCountMaps(inWin);
  const f = catDef.filter;

  if (f === 'stat') {
    if (catDef.type === 'song')   return _awardsTopN(songs,   1, 99);
    if (catDef.type === 'album')  return _awardsTopN(albums,  1, 99);
    if (catDef.type === 'artist') return _awardsTopN(artists, 1, 99);
    return [];
  }
  if (f === 'all') {
    if (catDef.type === 'song')   return _awardsTopN(songs,   20, 3);
    if (catDef.type === 'album')  return _awardsTopN(albums,  20, 3);
    if (catDef.type === 'artist') return _awardsTopN(artists, 20, 1);
    return [];
  }
  if (f === 'collab') {
    const m = {};
    for (const p of inWin) { if (!_isCollab(p)) continue; const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++; }
    return _awardsTopN(m, 20, 4);
  }
  if (f === 'duo') {
    const m = {};
    for (const p of inWin) { if (!_isDuo(p)) continue; const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++; }
    return _awardsTopN(m, 20, 4);
  }
  if (f === 'remix') {
    const m = {};
    for (const p of inWin) { if (!_isRemix(p)) continue; const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++; }
    return _awardsTopN(m, 20, 3);
  }
  if (f === 'summer') {
    const sp = inWin.filter(p => { const m = tzDateOf(p).getMonth(); return m >= 5 && m <= 7; });
    const { songs: ss } = _awardsCountMaps(sp);
    return _awardsTopN(ss, 20, 3);
  }
  if (f === 'new' || f === 'discovery') {
    if (!firstSeenMaps) firstSeenMaps = buildFirstSeenMaps();
    const m = {};
    for (const p of inWin) {
      const pa = _pa(p);
      const k  = pa.toLowerCase();
      const first = firstSeenMaps.artistFirst[pa];
      if (!first || first < start) continue;
      m[k] = m[k] || { artist: pa, plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'comeback') {
    // Gap: 2 years before the selected year's start
    const gapS = new Date(start); gapS.setFullYear(gapS.getFullYear() - 2);
    const gapE = new Date(start); gapE.setDate(gapE.getDate() - 1);
    // Before-gap: anything played before the 2-year gap
    const beforeGapE = new Date(gapS); beforeGapE.setDate(beforeGapE.getDate() - 1);
    const gapSet    = new Set(allPlays.filter(p => p.date >= gapS && p.date <= gapE).map(p => _pk(p)));
    const historySet = new Set(allPlays.filter(p => p.date <= beforeGapE).map(p => _pk(p)));
    const m = {};
    for (const p of inWin) {
      const k = _pk(p);
      if (gapSet.has(k)) continue;     // played within the 2-year gap → not a comeback
      if (!historySet.has(k)) continue; // never played before the gap → new artist, not a comeback
      m[k] = m[k] || { artist: _pa(p), plays: 0 };
      m[k].plays++;
    }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'growth') {
    const prevS = new Date(start); prevS.setFullYear(prevS.getFullYear() - 1);
    const prevE = new Date(start); prevE.setDate(prevE.getDate() - 1);
    const { artists: prev } = _awardsCountMaps(allPlays.filter(p => p.date >= prevS && p.date <= prevE));
    const m = {};
    for (const [k, d] of Object.entries(artists)) {
      const delta = d.plays - (prev[k]?.plays || 0);
      if (delta > 0) m[k] = { artist: d.artist, plays: delta };
    }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'spike') {
    const weekPeak = {};
    for (const p of inWin) {
      const d = tzDateOf(p);
      const wk = `${d.getFullYear()}-${Math.floor((d.getDate() - 1) / 7)}`;
      const k = _sk(p) + '|||' + wk;
      weekPeak[k] = weekPeak[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0, sk: _sk(p) };
      weekPeak[k].plays++;
    }
    const best = {};
    for (const v of Object.values(weekPeak)) { if (!best[v.sk] || v.plays > best[v.sk].plays) best[v.sk] = v; }
    return _awardsTopN(best, 20, 3);
  }
  if (f === 'streak') {
    const dayMap = {};
    for (const p of inWin) {
      const d = tzDateOf(p);
      const day = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      const k = _sk(p);
      if (!dayMap[k]) dayMap[k] = { title: p.title, artist: p.artist, album: p.album, days: new Set() };
      dayMap[k].days.add(day);
    }
    const m = {};
    for (const [k, v] of Object.entries(dayMap)) {
      const streak = longestConsecutiveDays(v.days);
      if (streak >= 2) m[k] = { title: v.title, artist: v.artist, album: v.album, plays: streak, playLabel: `${streak}-day streak` };
    }
    return _awardsTopN(m, 20, 3);
  }
  if (f === 'one_hit') {
    const as = {};
    for (const p of inWin) { const k = _pk(p); const sk = _sk(p); if (!as[k]) as[k] = { artist: _pa(p), songPlays: {}, songTitles: {} }; as[k].songPlays[sk] = (as[k].songPlays[sk] || 0) + 1; as[k].songTitles[sk] = p.title; }
    const m = {};
    for (const [k, v] of Object.entries(as)) { const hits = Object.entries(v.songPlays).filter(([, c]) => c >= 10); if (hits.length === 1) { const [sk, plays] = hits[0]; m[k] = { artist: v.artist, song: v.songTitles[sk], plays }; } }
    return _awardsTopN(m, 20, 1);
  }
  if (f === 'late_disc') {
    // Count plays per album strictly before the awards year window.
    const priorPlays = {};
    for (const p of allPlays) {
      if (p.date >= start || !p.album) continue;
      const k = _ak(p);
      priorPlays[k] = (priorPlays[k] || 0) + 1;
    }
    const m = {};
    for (const p of inWin) {
      if (!p.album) continue;
      const k = _ak(p);
      // Allow albums the user barely knew before (≤20 prior plays) — covers both
      // true first-time discoveries and slow burns that finally clicked this year.
      if ((priorPlays[k] || 0) > 20) continue;
      m[k] = m[k] || { album: p.album, artist: p.artist, plays: 0 };
      m[k].plays++;
    }
    // Exclude albums released during the awards year — those aren't late discoveries.
    // (Only needed for the zero-prior-plays case; any prior play proves an earlier release.)
    const awardsYear = start.getFullYear();
    const candidates = Object.entries(m).map(([k, v]) => ({ k, ...v }));
    if (log) log(`Fetching release years for ${candidates.length} album${candidates.length !== 1 ? 's' : ''}…`);
    await Promise.all(candidates.map(c => _awardsGetAlbumYear(c.album, c.artist)));
    for (const { k, album, artist } of candidates) {
      const releaseYear = _awardsAlbumYearCache[album.toLowerCase() + '|||' + artist.toLowerCase()];
      const prior = priorPlays[k] || 0;
      // Exclude if release year is known and falls within the awards year.
      // Also exclude if year is unknown AND prior plays = 0: any prior play proves an older
      // release, but zero prior plays with no API result almost certainly means a new release.
      if ((releaseYear !== null && releaseYear >= awardsYear) || (releaseYear === null && prior === 0)) {
        delete m[k];
      } else if (m[k]) {
        m[k].releaseYear = releaseYear;
      }
    }
    return _awardsTopN(m, 20, 2);
  }
  if (f === 'nonenglish') {
    const m = {};
    for (const p of inWin) {
      if (!_hasNonLatinScript(p.title) && !_hasNonLatinScript(p.artist)) continue;
      const k = _sk(p); m[k] = m[k] || { title: p.title, artist: p.artist, album: p.album, plays: 0 }; m[k].plays++;
    }
    return _awardsTopN(m, 20, 3);
  }
  if (f.startsWith('genre:')) {
    const uniq = [...new Set(inWin.map(p => _pa(p)))];
    await _awardsGeminiClassifyArtists(uniq.slice(0, 150));
    await Promise.all(uniq.filter(a => _awardsGenreCache[a.toLowerCase()] === undefined).slice(0, 60).map(a => _awardsGetArtistGenre(a)));
    const gs = {}, ga = {}, gr = {};
    for (const p of inWin) {
      const tags = _awardsGenreCache[_pa(p).toLowerCase()] || [];
      if (!_genreMatch(tags, f)) continue;
      const sk = _sk(p), ak = _ak(p), rk = _rk(p);
      if (!gs[sk]) gs[sk] = { title: p.title, artist: p.artist, album: p.album, plays: 0 };
      if (!ga[ak] && p.album) ga[ak] = { album: p.album, artist: p.artist, plays: 0 };
      if (!gr[rk]) gr[rk] = { artist: p.artist, plays: 0 };
      gs[sk].plays++; if (p.album) ga[ak].plays++; gr[rk].plays++;
    }
    if (catDef.type === 'song')   return _awardsTopN(gs, 20, 3);
    if (catDef.type === 'album')  return _awardsTopN(ga, 20, 2);
    if (catDef.type === 'artist') return _awardsTopN(gr, 20, 1);
  }
  return [];
}

// ── UI Rendering ──────────────────────────────────────────────────────────────

async function awardsInit() {
  document.getElementById('awardsYearLabel').textContent   = _awardsYear;
  document.getElementById('realLifeYearLabel').textContent = _realLifeYear;
  awardsSubTab(_awardsSubTab);
}

function awardsSubTab(tab) {
  _awardsSubTab = tab;
  document.querySelectorAll('.awards-subnav-btn').forEach(b => b.classList.toggle('active', b.dataset.awardsTab === tab));
  document.getElementById('awardsMyGrammys').style.display = tab === 'mygrammys' ? '' : 'none';
  document.getElementById('awardsRealLife').style.display  = tab === 'reallife'  ? '' : 'none';
  if (tab === 'mygrammys') awardsRenderYear(_awardsYear);
  if (tab === 'reallife')  loadRealLifeAwards(_realLifeYear);
}

function awardsChangeYear(delta) {
  _awardsYear = Math.max(2000, Math.min(tzNow().getFullYear(), _awardsYear + delta));
  document.getElementById('awardsYearLabel').textContent = _awardsYear;
  awardsRenderYear(_awardsYear);
}

function realLifeAwardsChangeYear(delta) {
  _realLifeYear = Math.max(2000, Math.min(tzNow().getFullYear(), _realLifeYear + delta));
  document.getElementById('realLifeYearLabel').textContent = _realLifeYear;
  loadRealLifeAwards(_realLifeYear);
}

async function awardsRenderYear(year) {
  const statusEl = document.getElementById('awardsStatus');
  statusEl.textContent = '';
  if (!allPlays.length) {
    statusEl.textContent = 'Load your music data to use My Grammys.';
    document.getElementById('awardsCatList').innerHTML = '';
    document.getElementById('awardsCeremonyBar').style.display = 'none';
    return;
  }
  statusEl.textContent = 'Loading…';
  const data = await _awardsLoad(year);
  statusEl.textContent = '';
  _awardsRenderCatToggles(data);
  document.getElementById('awardsEligStart').value = data.eligStart;
  document.getElementById('awardsEligEnd').value   = data.eligEnd;
  _awardsRenderCatList(data);
}

function _awardsRenderCatToggles(data) {
  const el = document.getElementById('awardsCatToggles');
  if (!el) return;
  el.innerHTML = AWARD_CATEGORIES.map(cat => {
    const enabled = data.categories[cat.id]?.enabled ?? cat.defaultOn;
    return `<label class="awards-cat-toggle-row">
      <input type="checkbox" ${enabled ? 'checked' : ''} onchange="awardsToggleCat('${cat.id}',this.checked)">
      <span class="awards-type-badge awards-type-${cat.type}">${cat.type}</span>
      ${esc(t('awards_cat_' + cat.id))}${cat.auto ? ' <span class="awards-auto-badge">auto</span>' : ''}
    </label>`;
  }).join('');
}

function _awardsRenderCatList(data) {
  const el = document.getElementById('awardsCatList');
  if (!el) return;
  const activeCats = AWARD_CATEGORIES.filter(c => data.categories[c.id]?.enabled ?? c.defaultOn);
  if (!activeCats.length) {
    el.innerHTML = `<div class="awards-empty">${t('awards_no_categories')}</div>`;
    document.getElementById('awardsCeremonyBar').style.display = 'none';
    return;
  }
  el.innerHTML = activeCats.map(cat => _awardsRenderCatCard(cat, data.categories[cat.id] || { enabled: true, nominees: [], winner: null }, data.year)).join('');
  const hasWinner = activeCats.some(c => data.categories[c.id]?.winner);
  document.getElementById('awardsCeremonyBar').style.display = hasWinner ? '' : 'none';
}

function _awardItemKey(item) {
  return JSON.stringify({ t: item.title || '', al: item.album || '', ar: item.artist || '' });
}

function _awardsRenderCatCard(cat, catData, year) {
  const nominees  = catData.nominees || [];
  const winner    = catData.winner   || null;
  const winnerKey = winner ? _awardItemKey(winner) : null;
  const emoji     = cat.emoji || { song: '🎵', album: '💿', artist: '🎤' }[cat.type] || '🏆';

  let bodyHtml = '';
  if (cat.auto && nominees.length) {
    const w = nominees[0];
    bodyHtml = `<div class="awards-auto-winner">
      <span class="awards-winner-trophy">🏆</span>
      <span class="awards-winner-text">${esc(w.title || w.album || w.artist || '')}</span>
      ${(w.title || w.album) && w.artist ? `<span class="awards-winner-sub">${esc(w.artist)}</span>` : ''}
    </div>`;
  } else if (nominees.length) {
    bodyHtml = nominees.map(item => {
      const ik  = _awardItemKey(item);
      const lbl = item.title || item.album || item.artist || '';
      const sub = item.title ? item.artist : (item.album ? item.artist : (item.song || ''));
      return `<div class="awards-nominee-row${ik === winnerKey ? ' is-winner' : ''}" onclick="awardsPickWinner(${year},'${esc(cat.id)}',${esc(JSON.stringify(item))})">
        <span class="awards-nominee-icon">${ik === winnerKey ? '🏆' : '○'}</span>
        <span class="awards-nominee-label">${esc(lbl)}</span>
        ${sub ? `<span class="awards-nominee-sub">${esc(sub)}</span>` : ''}
        <button class="awards-nominee-remove" onclick="awardsRemoveNominee(event,${year},'${esc(cat.id)}',${esc(JSON.stringify(item))})" title="Remove">✕</button>
      </div>`;
    }).join('') + (!winner ? `<div class="awards-pick-hint">${t('awards_pick_hint')}</div>` : '');
  } else {
    bodyHtml = `<div class="awards-no-nominees">${t('awards_no_nominees')}</div>`;
  }

  const genBtn = cat.auto ? '' : `<button class="awards-cat-action-btn" onclick="awardsGenerateCatCandidates(${year},'${esc(cat.id)}')" data-catid="${esc(cat.id)}">${nominees.length ? t('awards_change_btn') : t('awards_pick_nominees_btn')}</button>`;

  return `<div class="awards-cat-card${winner ? ' has-winner' : ''}" id="awardsCat_${cat.id}">
    <div class="awards-cat-header">
      <span class="awards-cat-emoji">${emoji}</span>
      <span class="awards-cat-name">${esc(t('awards_cat_' + cat.id))}</span>
      ${cat.auto ? '<span class="awards-auto-tag">auto</span>' : ''}
    </div>
    <div class="awards-cat-body">${bodyHtml}</div>
    <div class="awards-cat-footer">${genBtn}</div>
  </div>`;
}

function awardsToggleConfig() {
  const panel = document.getElementById('awardsConfigPanel');
  const open = panel.style.display !== 'none';
  panel.style.display = open ? 'none' : '';
  document.getElementById('awardsConfigToggleBtn').classList.toggle('active', !open);
  if (!open) {
    const keyEl = document.getElementById('awardsGeminiKey');
    if (keyEl) keyEl.value = localStorage.getItem('dc_gemini_api_key') || '';
  }
}

function awardsUpdateElig() {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  data.eligStart = document.getElementById('awardsEligStart').value;
  data.eligEnd   = document.getElementById('awardsEligEnd').value;
  _awardsSave(_awardsYear);
}

function awardsToggleCat(catId, enabled) {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  if (!data.categories[catId]) data.categories[catId] = { enabled, nominees: [], winner: null };
  data.categories[catId].enabled = enabled;
  _awardsSave(_awardsYear);
  _awardsRenderCatList(data);
}

function awardsToggleAllCats(enabled) {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  for (const cat of AWARD_CATEGORIES) {
    if (!data.categories[cat.id]) data.categories[cat.id] = { enabled, nominees: [], winner: null };
    data.categories[cat.id].enabled = enabled;
  }
  _awardsRenderCatToggles(data);
  _awardsSave(_awardsYear);
  _awardsRenderCatList(data);
}

async function awardsGenerateCandidates() {
  if (!allPlays.length) return;
  const btn = document.getElementById('awardsGenerateBtn');
  const statusEl = document.getElementById('awardsStatus');
  const log = msg => { if (statusEl) statusEl.textContent = msg; };

  // The button label is HTML (it carries the ✨ icon span), so stash/restore innerHTML —
  // writing t('awards_generate') into textContent would print the raw markup.
  const btnLabel = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.textContent = t('awards_generating'); }

  let data;
  try {
    log('Loading year data…');
    data = await _awardsLoad(_awardsYear);
    const active = AWARD_CATEGORIES.filter(c => data.categories[c.id]?.enabled ?? c.defaultOn);

    for (const cat of active) {
      log(`Calculating ${cat.label}…`);
      const cands = await _awardsGetCandidates(cat, data.eligStart, data.eligEnd, log);
      const cd = data.categories[cat.id];
      if (cat.auto) {
        cd.nominees = cands.slice(0, 1);
        cd.winner   = cands[0] || null;
      } else if (!cd.nominees.length && cands.length) {
        cd.nominees = cands.slice(0, 8);
      }
    }
    log('Saving…');
    await _awardsSave(_awardsYear);
  } finally {
    // Always give the button back, even if a category blew up mid-run
    if (btn) { btn.disabled = false; btn.innerHTML = btnLabel; }
    if (statusEl) statusEl.textContent = '';
  }
  if (data) _awardsRenderCatList(data);
}

async function awardsGenerateCatCandidates(year, catId) {
  const data = _awardsYearData[year] || await _awardsLoad(year);
  if (!data) return;
  const catDef = AWARD_CATEGORIES.find(c => c.id === catId);
  if (!catDef) return;
  const btn = document.querySelector(`[data-catid="${catId}"]`);
  // Restore whatever label the card had (Change / Pick nominees) instead of hard-coding one
  const btnLabel = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.textContent = t('awards_loading'); }
  let cands = [];
  try {
    cands = await _awardsGetCandidates(catDef, data.eligStart, data.eligEnd);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = btnLabel; }
  }
  _awardsShowPicker(year, catId, cands);
}

/* ─── Nominee picker ─────────────────────────────────────────────────────────
   The picker builds ONE play-count index for the eligibility window when it
   opens, then every search / sort / page runs off that cached array instead of
   re-walking allPlays on each keystroke.                                     */

// Does a play fit the category's own rule? Answered on the raw play, which still has the
// structured `artists` array the indexed item drops. `null` = the category is about listening
// history (new artist, comeback, growth…) rather than the item itself, so it can't rank a
// browse list; genre is answered later, from the tag cache, since those load asynchronously.
function _awardsPickerPlayFits(p) {
  const f = _awardsPickerCatFilter;
  if (f === 'collab')     return _isCollab(p);
  if (f === 'duo')        return _isDuo(p);
  if (f === 'remix')      return _isRemix(p);
  if (f === 'nonenglish') return _hasNonLatinScript(p.title) || _hasNonLatinScript(p.artist);
  return null;
}

// Same question for an indexed item: the flag stored at build time, or a live genre lookup.
// Deliberately a soft signal, never a hard filter — a "collab" the artist field can't reveal
// (one credited artist, two people actually singing) is still one the user can pick by hand.
function _awardsPickerItemFits(item) {
  const f = _awardsPickerCatFilter;
  if (f === 'summer') return (item.summerPlays || 0) > 0;
  if (f.startsWith('genre:')) {
    const tags = _awardsGenreCache[(item.artist || '').toLowerCase()];
    return tags === undefined ? false : _genreMatch(tags, f);
  }
  return item.fit;
}

// Whether this category can rank the browse list at all
function _awardsPickerHasFit() {
  const f = _awardsPickerCatFilter;
  return f === 'summer' || f.startsWith('genre:') || _awardsPickerPlayFits({}) !== null;
}

// Plural noun for the category's matches, used in the group headers
function _awardsPickerFitLabel() {
  const f = _awardsPickerCatFilter;
  const kind = _awardsPickerCatType === 'album' ? 'albums' : _awardsPickerCatType === 'artist' ? 'artists' : 'songs';
  if (f === 'collab')     return 'Collaborations';
  if (f === 'duo')        return 'Duos';
  if (f === 'remix')      return 'Remixes, edits & versions';
  if (f === 'nonenglish') return 'Non-English ' + kind;
  if (f === 'summer')     return 'Summer songs';
  if (f.startsWith('genre:')) return f.replace('genre:', '').replace('rnb', 'R&B').replace(/^./, c => c.toUpperCase()) + ' ' + kind;
  return '';
}

// One pass over allPlays → every song/album/artist in the window, with play count + last play
function _awardsPickerBuildIndex() {
  const start = new Date(_awardsPickerEligWin.start + 'T00:00:00');
  const end   = new Date(_awardsPickerEligWin.end   + 'T23:59:59');
  const map   = {};
  for (const p of allPlays) {
    if (p.date < start || p.date > end) continue;
    let k;
    if (_awardsPickerCatType === 'song') {
      k = _sk(p);
      if (!map[k]) map[k] = { title: p.title, artist: p.artist, album: p.album, plays: 0, last: 0 };
    } else if (_awardsPickerCatType === 'album') {
      if (!p.album) continue;
      k = _ak(p);
      if (!map[k]) map[k] = { album: p.album, artist: _pa(p), plays: 0, last: 0 };
    } else {
      k = _pk(p);
      if (!map[k]) map[k] = { artist: _pa(p), plays: 0, last: 0 };
    }
    const item = map[k];
    if (item.fit === undefined) item.fit = _awardsPickerPlayFits(p);   // computed once, off the raw play
    item.plays++;
    const ts = +p.date;
    if (ts > item.last) item.last = ts;
    if (_awardsPickerCatFilter === 'summer') {
      const mo = tzDateOf(p).getMonth();
      if (mo >= 5 && mo <= 7) item.summerPlays = (item.summerPlays || 0) + 1;
    }
  }
  // Song of the Summer ranks on summer plays, so label the rows with that number
  if (_awardsPickerCatFilter === 'summer') {
    for (const item of Object.values(map)) item.playLabel = (item.summerPlays || 0) + ' summer plays';
  }

  // Carry the suggestion metadata (custom play labels, release years) onto the indexed
  // items so the generated candidates and the browse list stay one and the same object.
  _awardsPickerSuggKeys = new Set();
  for (const cand of _awardsPickerAutoCands) {
    const ck = _awardItemKey(cand);
    _awardsPickerSuggKeys.add(ck);
    const hit = map[_awardsPickerCatType === 'song' ? _sk(cand)
              : _awardsPickerCatType === 'album' ? _ak(cand)
              : _pk(cand)];
    if (hit) {
      hit.sugg = true;
      if (cand.playLabel) hit.playLabel = cand.playLabel;
      if (cand.releaseYear !== undefined) hit.releaseYear = cand.releaseYear;
    } else {
      // Candidate the raw index can't reproduce (growth deltas, streaks…) — keep it as-is
      map[ck] = Object.assign({ plays: 0, last: 0 }, cand, { sugg: true });
    }
  }

  _awardsPickerAllItems = Object.values(map).sort((a, b) => b.plays - a.plays);
}

// The list the body should show right now: search filter + genre filter + sort
function _awardsPickerVisible() {
  const q = (document.getElementById('awardsPickerSearch')?.value || '').toLowerCase().trim();
  const hasFit = _awardsPickerHasFit();
  const isSummer = _awardsPickerCatFilter === 'summer';

  const list = _awardsPickerAllItems.filter(item =>
    !q || [item.title, item.album, item.artist].filter(Boolean).join(' ').toLowerCase().includes(q));

  // group: 0 = suggested, 1 = matches the category's rule, 2 = everything else.
  // Nothing is ever dropped — the rule only decides the order.
  for (const item of list) item.grp = item.sugg ? 0 : (hasFit && _awardsPickerItemFits(item) ? 1 : 2);

  if (_awardsPickerSort === 'az') {
    list.sort((a, b) => (a.title || a.album || a.artist || '').localeCompare(b.title || b.album || b.artist || ''));
  } else if (_awardsPickerSort === 'recent') {
    list.sort((a, b) => b.last - a.last);
  } else {
    list.sort((a, b) => a.grp - b.grp
      || (isSummer ? (b.summerPlays || 0) - (a.summerPlays || 0) : 0)
      || b.plays - a.plays);
  }
  return list;
}

function _awardsPickerResultRow(item, idx) {
  const picked = _awardsPickerSelKeys.has(_awardItemKey(item));
  const lbl = item.title || item.album || item.artist || '';
  const sub = item.title ? item.artist : (item.album ? item.artist : '');
  const rel = item.releaseYear ? ' · ' + item.releaseYear : (item.releaseYear === null ? ' · year unknown' : '');
  let genreHtml = '';
  if (_awardsPickerCatFilter.startsWith('genre:') && item.grp !== 2) {
    const tags = _awardsGenreCache[(item.artist || '').toLowerCase()];
    if (tags && tags.length) {
      genreHtml = `<span class="awards-picker-genre-tags">${tags.slice(0, 3).map(t => `<span class="awards-picker-genre-tag">${esc(t)}</span>`).join('')}</span>`;
    } else {
      genreHtml = `<span class="awards-picker-genre-tags"><span class="awards-picker-genre-tag awards-picker-genre-unk">${tags === undefined ? '?' : 'no genre'}</span></span>`;
    }
  }
  const cls = 'awards-picker-result-row'
    + (picked ? ' is-picked' : '')
    + (idx === _awardsPickerActive ? ' is-active' : '');
  return `<div class="${cls}" data-idx="${idx}" onclick="awardsPickerToggleRow(${idx})" title="${picked ? 'Click to remove' : 'Click to nominate'}">
    <span class="awards-picker-add-icon">${picked ? '✓' : '+'}</span>
    <span class="awards-picker-lbl">${esc(lbl)}</span>
    ${sub ? `<span class="awards-picker-sub">${esc(sub)}${rel}</span>` : ''}
    ${genreHtml}
    <span class="awards-picker-plays">${item.playLabel || item.plays + ' plays'}</span>
  </div>`;
}

function _awardsPickerSelHtml() {
  if (!_awardsPickerSel.length) return '<div class="awards-picker-nom-empty">No nominees yet — click any row below to add one</div>';
  return _awardsPickerSel.map((item, i) => {
    const lbl = item.title || item.album || item.artist || '';
    const sub = item.title ? item.artist : (item.album ? item.artist : '');
    // Draggable chips: the order here is the order the nominees appear on the award card
    return `<div class="awards-picker-nom-row" draggable="true" data-i="${i}"
        ondragstart="awardsPickerDragStart(event,${i})"
        ondragover="awardsPickerDragOver(event)"
        ondragleave="awardsPickerDragLeave(event)"
        ondrop="awardsPickerDrop(event,${i})"
        ondragend="awardsPickerDragEnd(event)">
      <span class="awards-picker-nom-num">${i + 1}</span>
      <span class="awards-picker-nom-lbl">${esc(lbl)}</span>
      ${sub ? `<span class="awards-picker-nom-sub">${esc(sub)}</span>` : ''}
      <button class="awards-picker-nom-x" data-i="${i}" onclick="awardsPickerRemoveNom(this)" title="Remove">✕</button>
    </div>`;
  }).join('');
}

function _awardsPickerBodyHtml() {
  const list = _awardsPickerVisible();
  const q = (document.getElementById('awardsPickerSearch')?.value || '').trim();
  if (!list.length) {
    return `<div class="awards-empty">${q ? `No results for "${esc(q)}"` : t('awards_no_candidates')}</div>`;
  }
  _awardsPickerRows = list.slice(0, _awardsPickerShown);

  const showHeaders = _awardsPickerSort === 'plays';
  const fitLabel = _awardsPickerFitLabel();
  const year = _awardsPickerCtx.year;
  const headers = [
    'Suggested for this category',
    fitLabel ? `${fitLabel} from ${year}` : `Everything else you played in ${year}`,
    // For a filtered category the tail is still fair game: the artist field can't spot every
    // collab, so say so rather than hiding those rows.
    fitLabel ? `Everything else from ${year} — pick any if you know it fits`
             : `Everything else you played in ${year}`,
  ];
  let html = '', lastGrp = -1;
  _awardsPickerRows.forEach((item, i) => {
    if (showHeaders && item.grp !== lastGrp) {
      lastGrp = item.grp;
      html += `<div class="awards-picker-group">${headers[item.grp]}</div>`;
    }
    html += _awardsPickerResultRow(item, i);
  });

  const left = list.length - _awardsPickerRows.length;
  if (left > 0) html += `<button class="awards-picker-more" onclick="awardsPickerShowMore()">Show ${Math.min(left, AWARDS_PICKER_PAGE)} more · ${left} left</button>`;
  return html;
}

function _awardsPickerRefresh(resetPaging) {
  if (resetPaging) { _awardsPickerShown = AWARDS_PICKER_PAGE; _awardsPickerActive = -1; }
  const selEl   = document.getElementById('awardsPickerSelected');
  const countEl = document.getElementById('awardsPickerCount');
  if (selEl)   selEl.innerHTML = _awardsPickerSelHtml();
  if (countEl) countEl.textContent = t('awards_picker_selected', { count: _awardsPickerSel.length });
  const bodyEl = document.getElementById('awardsPickerBody');
  if (bodyEl) bodyEl.innerHTML = _awardsPickerBodyHtml();
}

function _awardsShowPicker(year, catId, candidates) {
  const data = _awardsYearData[year];
  if (!data) return;
  const catDef = AWARD_CATEGORIES.find(c => c.id === catId);
  if (!catDef) return;

  const existingNominees = data.categories[catId]?.nominees || [];
  _awardsPickerSel       = existingNominees.slice();
  _awardsPickerSelKeys   = new Set(_awardsPickerSel.map(_awardItemKey));
  _awardsPickerCatType   = catDef.type;
  _awardsPickerCatFilter = catDef.filter || '';
  _awardsPickerEligWin   = { start: data.eligStart, end: data.eligEnd };
  _awardsPickerAutoCands = candidates || [];
  _awardsPickerSort      = 'plays';
  _awardsPickerShown     = AWARDS_PICKER_PAGE;
  _awardsPickerActive    = -1;
  _awardsPickerRows      = [];

  const typeLabel = catDef.type === 'song' ? 'songs' : catDef.type === 'album' ? 'albums' : 'artists';
  _awardsPickerCtx = { year, catId, typeLabel };
  _awardsPickerBuildIndex();

  const html = `<div class="awards-picker-overlay" id="awardsPickerOverlay" onclick="awardsPickerBgClick(event)">
    <div class="awards-picker-modal">
      <div class="awards-picker-head">
        <span class="awards-picker-title">${esc(t('awards_cat_' + catDef.id))}</span>
        <span class="awards-picker-hint">Click a row to add or remove · drag the chips to reorder · ↑↓ then Enter</span>
        <button class="awards-picker-close" onclick="awardsPickerClose()">✕</button>
      </div>
      <div class="awards-picker-selected" id="awardsPickerSelected">${_awardsPickerSelHtml()}</div>
      <div class="awards-picker-tools">
        <input type="text" id="awardsPickerSearch" placeholder="Search all ${typeLabel} from ${year}…" oninput="awardsPickerDoSearch()" autocomplete="off" spellcheck="false">
        <select class="awards-picker-sort" id="awardsPickerSort" onchange="awardsPickerSetSort(this.value)" title="Sort the list">
          <option value="plays">Most played</option>
          <option value="az">A–Z</option>
          <option value="recent">Most recent</option>
        </select>
      </div>
      <div class="awards-picker-quick">
        <button onclick="awardsPickerFillTop(8)">Fill top 8</button>
        <button onclick="awardsPickerFillTop(5)">Top 5</button>
        <button onclick="awardsPickerClearSel()">Clear all</button>
      </div>
      <div class="awards-picker-body" id="awardsPickerBody">${_awardsPickerBodyHtml()}</div>
      <div class="awards-picker-foot">
        <span class="awards-picker-count" id="awardsPickerCount">${t('awards_picker_selected', { count: _awardsPickerSel.length })}</span>
        <button class="awards-picker-save" onclick="awardsPickerSave(${year},'${catId}')">${t('awards_save_nominees')}</button>
      </div>
    </div>
  </div>`;

  const wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstElementChild);
  requestAnimationFrame(() => document.getElementById('awardsPickerSearch')?.focus());

  // Keyboard: ↑↓ walk the list, Enter adds/removes, Ctrl/⌘+Enter saves, Esc closes
  _awardsPickerKeyHandler = e => {
    if (!document.getElementById('awardsPickerOverlay')) return;
    if (e.key === 'Escape') { e.preventDefault(); awardsPickerClose(); return; }
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); awardsPickerSave(year, catId); return; }
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      if (!_awardsPickerRows.length) return;
      e.preventDefault();
      const next = _awardsPickerActive + (e.key === 'ArrowDown' ? 1 : -1);
      _awardsPickerActive = Math.max(0, Math.min(_awardsPickerRows.length - 1, next));
      _awardsPickerPaintActive();
      return;
    }
    if (e.key === 'Enter') {
      e.preventDefault();
      awardsPickerToggleRow(_awardsPickerActive >= 0 ? _awardsPickerActive : 0);
    }
  };
  document.addEventListener('keydown', _awardsPickerKeyHandler);
}

// Move the keyboard highlight without re-rendering the whole list
function _awardsPickerPaintActive() {
  const bodyEl = document.getElementById('awardsPickerBody');
  if (!bodyEl) return;
  bodyEl.querySelectorAll('.awards-picker-result-row.is-active').forEach(el => el.classList.remove('is-active'));
  const row = bodyEl.querySelector(`.awards-picker-result-row[data-idx="${_awardsPickerActive}"]`);
  if (row) { row.classList.add('is-active'); row.scrollIntoView({ block: 'nearest' }); }
}

// Clicking a row toggles it: add if new, remove if it is already nominated
function awardsPickerToggleRow(idx) {
  const item = _awardsPickerRows[idx];
  if (!item) return;
  const k = _awardItemKey(item);
  if (_awardsPickerSelKeys.has(k)) {
    _awardsPickerSel = _awardsPickerSel.filter(n => _awardItemKey(n) !== k);
    _awardsPickerSelKeys.delete(k);
  } else {
    _awardsPickerSel.push(item);
    _awardsPickerSelKeys.add(k);
  }
  _awardsPickerActive = idx;
  _awardsPickerRefresh();
  _awardsPickerPaintActive();
}

function awardsPickerRemoveNom(btn) {
  const i = +btn.dataset.i;
  const item = _awardsPickerSel[i];
  if (!item) return;
  _awardsPickerSelKeys.delete(_awardItemKey(item));
  _awardsPickerSel.splice(i, 1);
  _awardsPickerRefresh();
}

function awardsPickerClearSel() {
  _awardsPickerSel = [];
  _awardsPickerSelKeys = new Set();
  _awardsPickerRefresh();
}

// One-click ballot: take the top N of whatever list is currently on screen
function awardsPickerFillTop(n) {
  for (const item of _awardsPickerVisible()) {
    if (_awardsPickerSel.length >= n) break;
    const k = _awardItemKey(item);
    if (_awardsPickerSelKeys.has(k)) continue;
    _awardsPickerSel.push(item);
    _awardsPickerSelKeys.add(k);
  }
  _awardsPickerRefresh();
}

function awardsPickerShowMore() {
  _awardsPickerShown += AWARDS_PICKER_PAGE;
  const bodyEl = document.getElementById('awardsPickerBody');
  if (bodyEl) bodyEl.innerHTML = _awardsPickerBodyHtml();
}

function awardsPickerSetSort(v) {
  _awardsPickerSort = v;
  _awardsPickerRefresh(true);
}

function awardsPickerDoSearch() {
  _awardsPickerShown  = AWARDS_PICKER_PAGE;
  _awardsPickerActive = -1;
  const bodyEl = document.getElementById('awardsPickerBody');
  if (bodyEl) bodyEl.innerHTML = _awardsPickerBodyHtml();
}

/* --- Drag to reorder the selected nominees --- */
function awardsPickerDragStart(e, i) {
  _awardsPickerDragFrom = i;
  e.dataTransfer.effectAllowed = 'move';
  try { e.dataTransfer.setData('text/plain', String(i)); } catch (_) {}
  e.currentTarget.classList.add('is-dragging');
}
function awardsPickerDragOver(e) {
  if (_awardsPickerDragFrom < 0) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  e.currentTarget.classList.add('is-dropzone');
}
function awardsPickerDragLeave(e) { e.currentTarget.classList.remove('is-dropzone'); }
function awardsPickerDragEnd(e)   { _awardsPickerDragFrom = -1; e.currentTarget.classList.remove('is-dragging'); }
function awardsPickerDrop(e, to) {
  e.preventDefault();
  const from = _awardsPickerDragFrom;
  _awardsPickerDragFrom = -1;
  if (from < 0 || from === to) { _awardsPickerRefresh(); return; }
  const [moved] = _awardsPickerSel.splice(from, 1);
  _awardsPickerSel.splice(to, 0, moved);
  _awardsPickerRefresh();
}

function awardsPickerBgClick(e) { if (e.target.id === 'awardsPickerOverlay') awardsPickerClose(); }

function awardsPickerClose() {
  const el = document.getElementById('awardsPickerOverlay');
  if (el) el.remove();
  if (_awardsPickerKeyHandler) { document.removeEventListener('keydown', _awardsPickerKeyHandler); _awardsPickerKeyHandler = null; }
  _awardsPickerSel      = [];
  _awardsPickerSelKeys  = new Set();
  _awardsPickerAllItems = [];   // drop the index so a big library isn't held in memory
  _awardsPickerRows     = [];
  _awardsPickerSuggKeys = new Set();
}

// Indexed items carry picker-only fields (fit, grp, last, summerPlays…) — keep them out of
// the saved/synced document, which only ever held the identity plus the play count.
function _awardsCleanNominee(item) {
  const out = {};
  for (const f of ['title', 'album', 'artist', 'plays', 'playLabel', 'releaseYear']) {
    if (item[f] !== undefined) out[f] = item[f];
  }
  return out;
}

async function awardsPickerSave(year, catId) {
  const nominees = _awardsPickerSel.map(_awardsCleanNominee);
  awardsPickerClose();
  const data = _awardsYearData[year];
  if (!data) return;
  if (!data.categories[catId]) data.categories[catId] = { enabled: true, nominees: [], winner: null };
  data.categories[catId].nominees = nominees;
  const wk = data.categories[catId].winner ? _awardItemKey(data.categories[catId].winner) : null;
  if (wk && !nominees.some(n => _awardItemKey(n) === wk)) data.categories[catId].winner = null;
  await _awardsSave(year);
  _awardsRenderCatList(data);
}

async function awardsPickWinner(year, catId, item) {
  const data = _awardsYearData[year];
  if (!data?.categories?.[catId]) return;
  const curWk = data.categories[catId].winner ? _awardItemKey(data.categories[catId].winner) : null;
  data.categories[catId].winner = (_awardItemKey(item) === curWk) ? null : item;
  await _awardsSave(year);
  _awardsRenderCatList(data);
}

async function awardsRemoveNominee(e, year, catId, item) {
  e.stopPropagation();
  const data = _awardsYearData[year];
  if (!data?.categories?.[catId]) return;
  const ik = _awardItemKey(item);
  data.categories[catId].nominees = data.categories[catId].nominees.filter(n => _awardItemKey(n) !== ik);
  if (data.categories[catId].winner && _awardItemKey(data.categories[catId].winner) === ik) data.categories[catId].winner = null;
  await _awardsSave(year);
  _awardsRenderCatList(data);
}

// ── Real-Life Awards ──────────────────────────────────────────────────────────

async function loadRealLifeAwards(year) {
  const contentEl = document.getElementById('realLifeContent');
  const statusEl  = document.getElementById('realLifeStatus');
  contentEl.innerHTML = '';
  statusEl.textContent = `Looking up Grammy nominations for your top artists in ${year}…`;

  const start = new Date(`${year}-01-01`);
  const end   = new Date(`${year}-12-31T23:59:59`);
  const inYear = allPlays.filter(p => p.date >= start && p.date <= end);
  if (!inYear.length && !allPlays.length) {
    statusEl.textContent = 'Load your music data first.';
    return;
  }
  const pool = inYear.length ? inYear : allPlays;
  const { artists } = _awardsCountMaps(pool);
  const topArtists  = _awardsTopN(artists, 20, 1);

  const results = [];
  for (const a of topArtists) {
    const awards = await _mbFetchAwards(a.artist, year);
    if (awards.length) results.push({ artist: a.artist, awards });
    await new Promise(r => setTimeout(r, 1100));
  }

  statusEl.textContent = '';
  if (!results.length) {
    contentEl.innerHTML = `<div class="awards-empty">No Grammy data found for your top ${topArtists.length} artists in ${year}. MusicBrainz coverage may be incomplete for this period.</div>`;
    return;
  }

  contentEl.innerHTML = results.map(r =>
    `<div class="awards-reallife-card">
      <div class="awards-reallife-artist">${esc(r.artist)}</div>
      ${r.awards.map(a => `<div class="awards-reallife-row">
        <span class="awards-reallife-badge ${a.won ? 'won' : 'nom'}">${a.won ? '🏆 Won' : '🎗 Nominated'}</span>
        <span class="awards-reallife-cat">${esc(a.category)}</span>
        ${a.year ? `<span class="awards-reallife-year">${a.year}</span>` : ''}
      </div>`).join('')}
    </div>`
  ).join('');
}

async function _mbFetchAwards(artist, year) {
  try {
    const r1 = await fetch(`https://musicbrainz.org/ws/2/artist/?query=${encodeURIComponent(`"${artist}"`)}&fmt=json&limit=1`);
    const d1 = await r1.json();
    const mbid = d1?.artists?.[0]?.id;
    if (!mbid) return [];
    await new Promise(r => setTimeout(r, 1100));
    const r2 = await fetch(`https://musicbrainz.org/ws/2/artist/${mbid}?inc=artist-rels&fmt=json`);
    const d2 = await r2.json();
    const out = [];
    for (const rel of (d2.relations || [])) {
      if (!rel.series) continue;
      const name = rel.series?.name || '';
      if (!/grammy/i.test(name)) continue;
      const relYear = (rel.begin || rel.end || '').split('-')[0];
      if (relYear && Math.abs(parseInt(relYear) - year) > 1) continue;
      out.push({ category: name, year: relYear, won: (rel.attributes || []).includes('Winner') });
    }
    return out;
  } catch(_) { return []; }
}

// ── Ceremony ──────────────────────────────────────────────────────────────────
// One category per slide: the nominees with their artwork, a sealed envelope, and
// — only once the envelope is opened — the winner, with a 30-second preview of the
// track playing underneath. The last slide is a roll call of every winner.

let _ceremonyYear = null;
let _ceremonyCats = [];
let _ceremonyIdx  = 0;
let _ceremonyRevealed = new Set();   // category ids already opened this session
let _ceremonyRenderSeq = 0;          // bumped per render so stale image loads can't land
let _ceremonyAudio = null;           // one <audio>, reused by every slide
let _ceremonyAudioToken = 0;         // guards async preview lookups against fast nav
let _ceremonyFadeTimer = null;
let _ceremonySound = localStorage.getItem('dc_ceremony_sound') !== 'off';
let _ceremonyKeyHandler = null;
const _ceremonyPreviewCache = {};    // "type:artist|||name" → preview url or null

// Nominee showcase: walks the nominees one at a time with a clip of each, before
// anyone touches the envelope.
let _cerShowIdx   = -1;              // nominee being showcased, -1 = not running
let _cerShowTimer = null;
let _cerShowToken = 0;               // cancels a step whose async work outlived it
const CER_SHOW_MS        = 15000;    // seconds per nominee, with sound
const CER_SHOW_SILENT_MS = 6000;     // …and without

function startAwardsCeremony() {
  const data = _awardsYearData[_awardsYear];
  if (!data) return;
  _ceremonyYear = _awardsYear;
  _ceremonyCats = AWARD_CATEGORIES.filter(c => {
    const cd = data.categories[c.id];
    return cd?.enabled && (cd.nominees?.length > 0 || cd.winner);
  });
  if (!_ceremonyCats.length) return;
  _ceremonyIdx = 0;
  _ceremonyRevealed = new Set();
  document.getElementById('awardsCeremonyOverlay').style.display = 'flex';
  document.body.style.overflow = 'hidden';
  _ceremonyPaintSoundBtn();
  _ceremonyDrawSidebar(data);
  _ceremonyRender();

  // ← → walk the ceremony, space/enter opens the envelope, esc leaves
  _ceremonyKeyHandler = e => {
    if (document.getElementById('awardsCeremonyOverlay')?.style.display === 'none') return;
    const showing = _cerShowIdx >= 0;
    if (e.key === 'Escape')     { e.preventDefault(); showing ? cerShowStop() : closeCeremony(); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); showing ? cerShowNext() : ceremonyNav(1); }
    else if (e.key === 'ArrowLeft')  { e.preventDefault(); showing ? cerShowPrev() : ceremonyNav(-1); }
    else if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); ceremonyReveal(); }
  };
  document.addEventListener('keydown', _ceremonyKeyHandler);
}

function closeCeremony() {
  document.getElementById('awardsCeremonyOverlay').style.display = 'none';
  document.body.style.overflow = '';
  cerShowStop(true);
  _ceremonyStopAudio();
  if (_ceremonyKeyHandler) { document.removeEventListener('keydown', _ceremonyKeyHandler); _ceremonyKeyHandler = null; }
}

function ceremonyOverlayClick(e) {
  if (e.target.id === 'awardsCeremonyOverlay') closeCeremony();
}

function _ceremonyIsFinale() { return _ceremonyIdx >= _ceremonyCats.length; }

function _ceremonyDrawSidebar(data) {
  document.getElementById('ceremonySidebar').innerHTML =
    `<div class="ceremony-sidebar-title">${_ceremonyYear} My Grammys</div>` +
    _ceremonyCats.map((cat, i) => {
      const hasWinner = !!data.categories[cat.id]?.winner;
      // The trophy only appears once the envelope has actually been opened —
      // the sidebar shouldn't spoil a category the user hasn't reached yet.
      const opened = hasWinner && _ceremonyRevealed.has(cat.id);
      return `<div class="ceremony-sidebar-row${i === _ceremonyIdx ? ' active' : ''}${opened ? ' done' : ''}" onclick="ceremonyGoTo(${i})">
        <span class="ceremony-sidebar-dot">${opened ? '🏆' : (hasWinner ? '✉' : '○')}</span> ${esc(t('awards_cat_' + cat.id))}
      </div>`;
    }).join('') +
    `<div class="ceremony-sidebar-row ceremony-sidebar-finale${_ceremonyIsFinale() ? ' active' : ''}" onclick="ceremonyGoTo(${_ceremonyCats.length})">
      <span class="ceremony-sidebar-dot">🎬</span> All winners
    </div>`;
}

/* ── Artwork ──────────────────────────────────────────────────────────────── */

// Describe an award item the way fetchAndInjectImage() wants it, reusing the same
// prefKey convention as the charts so a picture pinned there shows up here too.
function _cerImgItem(item, type, imgId) {
  const artist = item.artist || '';
  if (type === 'artist') {
    return { imgId, name: artist, artist, prefKey: 'artist:' + artist.toLowerCase() };
  }
  if (type === 'album') {
    const album = item.album || '';
    return { imgId, name: album, album, artist, prefKey: 'album:' + artist.toLowerCase() + '|||' + album.toLowerCase() };
  }
  const title = item.title || '';
  return { imgId, name: title, title, artist, album: item.album || '', prefKey: 'song:' + artist.toLowerCase() + '|||' + title.toLowerCase() };
}

function _cerArtHtml(item, type, imgId, cls) {
  const label = item.title || item.album || item.artist || '';
  return `<div class="cer-art ${cls}"><div id="${imgId}"><div class="thumb-initials">${esc(initials(label))}</div></div></div>`;
}

// Load the queued artwork one at a time — fetchAndInjectImage already paces the
// Deezer proxy, and it drops anything whose container left the DOM, so switching
// slides mid-load resolves itself.
async function _ceremonyLoadArt(queue, seq) {
  for (const job of queue) {
    if (seq !== _ceremonyRenderSeq) return;
    const el = document.getElementById(job.imgId);
    if (!el) continue;
    try { await fetchAndInjectImage(el, _cerImgItem(job.item, job.type, job.imgId), job.type); } catch (e) {}
  }
}

/* ── Slides ───────────────────────────────────────────────────────────────── */

function _ceremonyRender() {
  const data = _awardsYearData[_ceremonyYear];
  if (!data) return;
  cerShowStop(true);
  _ceremonyStopAudio();
  const seq = ++_ceremonyRenderSeq;
  const slide = document.getElementById('ceremonySlide');
  const badge = document.getElementById('ceremonyYearBadge');
  const name  = document.getElementById('ceremonyCatName');
  const prog  = document.getElementById('ceremonyProgress');
  const nextBtn = document.getElementById('ceremonyNextBtn');
  const prevBtn = document.getElementById('ceremonyPrevBtn');
  badge.textContent = `${_ceremonyYear} My Grammys`;

  const queue = [];
  if (_ceremonyIsFinale()) {
    name.textContent = 'The Winners';
    prog.textContent = '🎬 Roll call';
    slide.className = 'ceremony-slide is-finale';
    slide.innerHTML = _ceremonyFinaleHtml(data, queue);
  } else {
    const cat     = _ceremonyCats[_ceremonyIdx];
    const catData = data.categories[cat.id] || { nominees: [], winner: null };
    name.textContent = t('awards_cat_' + cat.id);
    prog.textContent = `${_ceremonyIdx + 1} / ${_ceremonyCats.length}`;
    const opened = _ceremonyRevealed.has(cat.id) && catData.winner;
    slide.className = 'ceremony-slide' + (opened ? ' is-revealed' : '');
    slide.innerHTML = _ceremonyCatSlideHtml(cat, catData, queue);
    if (opened) _ceremonyMarkWinnerCard(catData.winner);
  }

  prevBtn.disabled = _ceremonyIdx === 0;
  nextBtn.textContent = _ceremonyIdx === _ceremonyCats.length - 1 ? '🏆 All winners' : t('awards_ceremony_next');
  nextBtn.style.visibility = _ceremonyIsFinale() ? 'hidden' : '';
  document.querySelectorAll('.ceremony-sidebar-row').forEach((el, i) => el.classList.toggle('active', i === _ceremonyIdx));
  document.getElementById('ceremonyStage').scrollTop = 0;
  _ceremonyLoadArt(queue, seq);
}

function _ceremonyCatSlideHtml(cat, catData, queue) {
  const nominees = catData.nominees || [];
  const winner   = catData.winner   || null;
  const type     = cat.type;
  const seq      = _ceremonyRenderSeq;

  if (!nominees.length && !winner) return `<div class="ceremony-no-nom">${t('awards_ceremony_no_nom')}</div>`;

  const cards = nominees.map((n, i) => {
    const imgId = `cerArt_${seq}_${i}`;
    queue.push({ imgId, item: n, type });
    const lbl = n.title || n.album || n.artist || '';
    const sub = (n.title || n.album) ? (n.artist || '') : '';
    return `<div class="cer-nom-card" data-nk="${esc(_awardItemKey(n))}">
      ${_cerArtHtml(n, type, imgId, 'cer-art-sm')}
      <div class="cer-nom-name">${esc(lbl)}</div>
      ${sub ? `<div class="cer-nom-sub">${esc(sub)}</div>` : ''}
      <span class="cer-nom-trophy">🏆</span>
    </div>`;
  }).join('');

  // Winner artwork is queued first so the reveal never lands on an empty square
  let winnerHtml = '';
  if (winner) {
    const wImgId = `cerWin_${seq}`;
    queue.unshift({ imgId: wImgId, item: winner, type });
    const lbl = winner.title || winner.album || winner.artist || '';
    const sub = (winner.title || winner.album) ? (winner.artist || '') : '';
    winnerHtml = `<div class="cer-winner">
      <div class="cer-winner-art-wrap">
        ${_cerArtHtml(winner, type, wImgId, 'cer-art-lg')}
        <span class="cer-winner-badge">🏆</span>
      </div>
      <div class="cer-winner-label">${t('awards_winner')}</div>
      <div class="cer-winner-name">${esc(lbl)}</div>
      ${sub ? `<div class="cer-winner-sub">${esc(sub)}</div>` : ''}
      <div class="cer-player" id="ceremonyPlayer">
        <button class="cer-play-btn" id="ceremonyPlayBtn" onclick="ceremonyTogglePlay()" title="30-second preview">▶</button>
        <div class="cer-player-bar"><div class="cer-player-fill" id="ceremonyPlayFill"></div></div>
        <span class="cer-player-note" id="ceremonyPlayNote">preview</span>
      </div>
    </div>`;
  }

  // Auto categories hold a single nominee that *is* the winner, so showcasing it
  // would give the game away — only offer the walk-through for a real field.
  const showcaseBtn = (!cat.auto && nominees.length > 1)
    ? `<button class="ceremony-nominees-btn" onclick="cerShowStart()">▶ Meet the nominees</button>`
    : '';

  const envelope = winner
    ? `<div class="cer-envelope-wrap">
         <div class="cer-envelope" onclick="ceremonyReveal()" role="button" tabindex="0" title="Open the envelope">
           <div class="cer-env-back"></div>
           <div class="cer-env-card"><span class="cer-env-card-star">🏆</span></div>
           <div class="cer-env-front"></div>
           <div class="cer-env-flap"></div>
           <div class="cer-env-seal">★</div>
         </div>
         <div class="cer-cta-row">
           ${showcaseBtn}
           <button class="ceremony-reveal-btn" onclick="ceremonyReveal()">✉ ${t('awards_open_envelope')}</button>
         </div>
       </div>`
    : `<div class="cer-no-winner">No winner crowned in this category yet — close the ceremony and click a nominee to crown one.</div>`;

  return `<div class="cer-nominees">${cards}</div>${envelope}${winnerHtml}`;
}

function _ceremonyFinaleHtml(data, queue) {
  const seq = _ceremonyRenderSeq;
  const rows = _ceremonyCats.map((cat, i) => {
    const w = data.categories[cat.id]?.winner;
    if (!w) return '';
    const imgId = `cerFin_${seq}_${i}`;
    queue.push({ imgId, item: w, type: cat.type });
    const lbl = w.title || w.album || w.artist || '';
    const sub = (w.title || w.album) ? (w.artist || '') : '';
    return `<div class="cer-fin-card" onclick="ceremonyGoTo(${i})" title="${esc(t('awards_cat_' + cat.id))}">
      ${_cerArtHtml(w, cat.type, imgId, 'cer-art-md')}
      <div class="cer-fin-cat">${esc(t('awards_cat_' + cat.id))}</div>
      <div class="cer-fin-name">${esc(lbl)}</div>
      ${sub ? `<div class="cer-fin-sub">${esc(sub)}</div>` : ''}
    </div>`;
  }).join('');
  if (!rows) return `<div class="ceremony-no-nom">No winners crowned yet.</div>`;
  return `<div class="cer-finale-grid">${rows}</div>`;
}

/* ── The reveal ───────────────────────────────────────────────────────────── */

function ceremonyReveal() {
  if (_ceremonyIsFinale()) return;
  const cat  = _ceremonyCats[_ceremonyIdx];
  const data = _awardsYearData[_ceremonyYear];
  const winner = data?.categories?.[cat?.id]?.winner;
  if (!cat || !winner || _ceremonyRevealed.has(cat.id)) return;
  const slide = document.getElementById('ceremonySlide');
  if (!slide || slide.classList.contains('is-opening')) return;

  cerShowStop(true);                           // opening the envelope ends the walk-through
  _ceremonyRevealed.add(cat.id);
  slide.classList.add('is-opening');           // flap lifts, the card rides up out of it
  setTimeout(() => {
    slide.classList.remove('is-opening');
    slide.classList.add('is-revealed');
    _ceremonyMarkWinnerCard(winner);
    // Ride down to the very bottom: the winner is the last thing on the slide, and at
    // full scroll the sticky nav sits in its natural place instead of over the player.
    const stage = document.getElementById('ceremonyStage');
    if (stage) stage.scrollTo({ top: stage.scrollHeight, behavior: 'smooth' });
    _triggerConfetti();
    _ceremonyDrawSidebar(data);
    _ceremonyStartPreview(winner, cat.type);   // still inside the click's activation, so autoplay is allowed
  }, 1150);
}

// Ring the winning nominee in gold and fade the rest of the field
function _ceremonyMarkWinnerCard(winner) {
  const wk = _awardItemKey(winner);
  document.querySelectorAll('.cer-nom-card').forEach(card => {
    card.classList.toggle('is-winner', card.dataset.nk === wk);
    card.classList.toggle('is-dimmed', card.dataset.nk !== wk);
  });
}

function ceremonyNav(delta) {
  const data = _awardsYearData[_ceremonyYear];
  if (!data) return;
  const idx = Math.max(0, Math.min(_ceremonyCats.length, _ceremonyIdx + delta));
  if (idx === _ceremonyIdx) return;
  _ceremonyIdx = idx;
  _ceremonyDrawSidebar(data);
  _ceremonyRender();
}

function ceremonyGoTo(idx) {
  const data = _awardsYearData[_ceremonyYear];
  if (!data) return;
  _ceremonyIdx = Math.max(0, Math.min(_ceremonyCats.length, idx));
  _ceremonyDrawSidebar(data);
  _ceremonyRender();
}

/* ── Song previews ────────────────────────────────────────────────────────── */

// 30-second clip for the winner: iTunes first (no proxy, wide catalogue), Deezer second.
async function _ceremonyPreviewUrl(item, type) {
  const artist = item.artist || '';
  const name   = type === 'album' ? (item.album || '') : type === 'artist' ? '' : (item.title || '');
  const key    = `${type}:${artist.toLowerCase()}|||${name.toLowerCase()}`;
  if (key in _ceremonyPreviewCache) return _ceremonyPreviewCache[key];

  const term = `${artist} ${name}`.trim();
  let url = null;
  try {
    const r = await fetch(`https://itunes.apple.com/search?term=${encodeURIComponent(term)}&entity=song&limit=5`);
    const d = await r.json();
    url = (d?.results || []).find(x => x.previewUrl)?.previewUrl || null;
  } catch (e) {}
  if (!url) {
    try {
      const d = await deezerFetch(`search/track?q=${encodeURIComponent(term)}&limit=5`);
      url = (d?.data || []).find(x => x.preview)?.preview || null;
    } catch (e) {}
  }
  _ceremonyPreviewCache[key] = url;
  return url;
}

function _ceremonyPaintPlayer(state, note) {
  const btn  = document.getElementById('ceremonyPlayBtn');
  const noteEl = document.getElementById('ceremonyPlayNote');
  if (btn)  btn.textContent = state;
  if (noteEl && note !== undefined) noteEl.textContent = note;
}

// Shared clip player. `paint(state, note)` lets the winner panel and the nominee
// showcase report progress in their own UI. Resolves with the playing audio, or
// null when there was nothing to play.
async function _ceremonyPlayClip(item, type, opts) {
  opts = opts || {};
  const paint = opts.paint || (() => {});
  _ceremonyStopAudio();
  if (!_ceremonySound) { paint('▶', 'previews muted'); return null; }
  const token = ++_ceremonyAudioToken;
  paint('◌', 'finding preview…');

  const url = await _ceremonyPreviewUrl(item, type);
  if (token !== _ceremonyAudioToken) return null;
  if (!url) { paint('▶', 'no preview found'); return null; }

  const audio = _ceremonyAudio = new Audio(url);
  audio.volume = 0;
  if (opts.fillId) {
    audio.addEventListener('timeupdate', () => {
      const fill = document.getElementById(opts.fillId);
      if (fill && audio.duration) fill.style.width = (audio.currentTime / audio.duration * 100) + '%';
    });
  }
  audio.addEventListener('ended', () => paint('▶', opts.endNote || 'replay preview'));
  try {
    await audio.play();
    if (token !== _ceremonyAudioToken) { audio.pause(); return null; }
    paint('❚❚', opts.playingNote || '30-second preview');
    _ceremonyFadeIn(audio);
    return audio;
  } catch (e) {
    // Autoplay refused (no user gesture credited) — leave it under the play button
    paint('▶', 'tap to hear it');
    audio.volume = 0.7;
    return null;
  }
}

function _ceremonyStartPreview(item, type) {
  return _ceremonyPlayClip(item, type, {
    paint: _ceremonyPaintPlayer,
    fillId: 'ceremonyPlayFill',
    playingNote: '30-second preview',
  });
}

/* ── Nominee showcase ─────────────────────────────────────────────────────── */

function _ceremonyNominees() {
  const cat = _ceremonyCats[_ceremonyIdx];
  if (!cat) return [];
  return _awardsYearData[_ceremonyYear]?.categories?.[cat.id]?.nominees || [];
}

function cerShowStart() {
  if (_ceremonyIsFinale() || _cerShowIdx >= 0) return;
  const noms = _ceremonyNominees();
  const slide = document.getElementById('ceremonySlide');
  if (!noms.length || !slide || slide.classList.contains('is-revealed')) return;

  slide.classList.add('is-showcasing');
  const panel = document.createElement('div');
  panel.className = 'cer-showcase';
  panel.id = 'cerShowcase';
  panel.innerHTML = `
    <div class="cer-show-step" id="cerShowStep"></div>
    <div class="cer-art cer-art-lg" id="cerShowArt"></div>
    <div class="cer-show-name" id="cerShowName"></div>
    <div class="cer-show-sub" id="cerShowSub"></div>
    <div class="cer-show-bar"><div class="cer-show-fill" id="cerShowFill"></div></div>
    <div class="cer-show-note" id="cerShowNote"></div>
    <div class="cer-show-controls">
      <button onclick="cerShowPrev()" title="Previous nominee">◄</button>
      <button onclick="cerShowNext()" title="Next nominee">Skip ►</button>
      <button onclick="cerShowStop()" title="Back to the envelope">■ Stop</button>
    </div>`;
  slide.insertBefore(panel, slide.querySelector('.cer-envelope-wrap') || null);
  // Ride to the bottom so the showcase controls clear the sticky nav row
  const stage = document.getElementById('ceremonyStage');
  if (stage) requestAnimationFrame(() => stage.scrollTo({ top: stage.scrollHeight, behavior: 'smooth' }));
  _cerShowStep(0);
}

async function _cerShowStep(i) {
  clearTimeout(_cerShowTimer);
  const token = ++_cerShowToken;
  const noms  = _ceremonyNominees();
  const cat   = _ceremonyCats[_ceremonyIdx];
  if (!cat || !document.getElementById('cerShowcase')) return;
  if (i >= noms.length) { cerShowStop(); return; }     // the field is done — back to the envelope

  _cerShowIdx = i;
  const nom = noms[i];
  _cerShowPaint(i, nom, noms.length);

  const audio = await _ceremonyPlayClip(nom, cat.type, {
    paint: (state, note) => { const el = document.getElementById('cerShowNote'); if (el && note) el.textContent = note; },
    playingNote: 'now playing',
  });
  if (token !== _cerShowToken) return;

  const ms = audio ? CER_SHOW_MS : CER_SHOW_SILENT_MS;
  _cerShowRunBar(ms);
  _cerShowTimer = setTimeout(() => _cerShowStep(i + 1), ms);
}

function _cerShowPaint(i, nom, total) {
  const lbl = nom.title || nom.album || nom.artist || '';
  const sub = (nom.title || nom.album) ? (nom.artist || '') : '';
  const step = document.getElementById('cerShowStep');
  if (step) step.textContent = `Nominee ${i + 1} of ${total}`;
  const nameEl = document.getElementById('cerShowName');
  if (nameEl) nameEl.textContent = lbl;
  const subEl = document.getElementById('cerShowSub');
  if (subEl) subEl.textContent = sub;

  // Borrow the artwork the nominee strip already loaded rather than fetching it twice
  const art = document.getElementById('cerShowArt');
  if (art) {
    const src = document.querySelectorAll('.cer-nom-card')[i]?.querySelector('img.thumb')?.src;
    art.innerHTML = src
      ? `<img class="thumb" alt="" src="${esc(src)}">`
      : `<div class="thumb-initials">${esc(initials(lbl))}</div>`;
  }
  _cerShowSpotlight(i);
}

// Light up the nominee being played, fade the rest of the field
function _cerShowSpotlight(i) {
  document.querySelectorAll('.cer-nom-card').forEach((card, n) => {
    card.classList.toggle('is-spotlight', n === i);
    card.classList.toggle('is-dimmed', n !== i);
  });
}

// The bar is driven by the clock, not the audio, so it still counts down in silence
function _cerShowRunBar(ms) {
  const fill = document.getElementById('cerShowFill');
  if (!fill) return;
  fill.style.transition = 'none';
  fill.style.width = '0%';
  void fill.offsetWidth;
  fill.style.transition = `width ${ms}ms linear`;
  fill.style.width = '100%';
}

function cerShowNext() { if (_cerShowIdx >= 0) _cerShowStep(_cerShowIdx + 1); }
function cerShowPrev() { if (_cerShowIdx > 0)  _cerShowStep(_cerShowIdx - 1); }

function cerShowStop(quiet) {
  clearTimeout(_cerShowTimer);
  _cerShowTimer = null;
  _cerShowToken++;
  const wasRunning = _cerShowIdx >= 0;
  _cerShowIdx = -1;
  if (wasRunning) _ceremonyStopAudio();
  document.getElementById('cerShowcase')?.remove();
  const slide = document.getElementById('ceremonySlide');
  if (slide) slide.classList.remove('is-showcasing');
  document.querySelectorAll('.cer-nom-card').forEach(c => c.classList.remove('is-spotlight', 'is-dimmed'));
  if (wasRunning && !quiet) {
    // Hand the moment back to the envelope
    const env = document.querySelector('.cer-envelope');
    if (env) {
      env.classList.add('is-ready');
      env.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }
}

function _ceremonyFadeIn(audio) {
  clearInterval(_ceremonyFadeTimer);
  let v = 0;
  _ceremonyFadeTimer = setInterval(() => {
    v = Math.min(0.7, v + 0.07);
    if (audio === _ceremonyAudio) audio.volume = v;
    if (v >= 0.7) clearInterval(_ceremonyFadeTimer);
  }, 60);
}

function _ceremonyStopAudio() {
  _ceremonyAudioToken++;
  clearInterval(_ceremonyFadeTimer);
  if (_ceremonyAudio) { try { _ceremonyAudio.pause(); } catch (e) {} _ceremonyAudio = null; }
  const fill = document.getElementById('ceremonyPlayFill');
  if (fill) fill.style.width = '0%';
}

function ceremonyTogglePlay() {
  if (_ceremonyAudio) {
    if (_ceremonyAudio.paused) { _ceremonyAudio.play().then(() => _ceremonyPaintPlayer('❚❚', '30-second preview')).catch(() => {}); }
    else { _ceremonyAudio.pause(); _ceremonyPaintPlayer('▶', 'paused'); }
    return;
  }
  // No clip loaded yet (muted, autoplay refused, or a fresh visit) — fetch it now
  if (_ceremonyIsFinale()) return;
  const cat = _ceremonyCats[_ceremonyIdx];
  const winner = _awardsYearData[_ceremonyYear]?.categories?.[cat.id]?.winner;
  if (!winner) return;
  if (!_ceremonySound) { _ceremonySound = true; localStorage.setItem('dc_ceremony_sound', 'on'); _ceremonyPaintSoundBtn(); }
  _ceremonyStartPreview(winner, cat.type);
}

function ceremonyToggleSound() {
  _ceremonySound = !_ceremonySound;
  localStorage.setItem('dc_ceremony_sound', _ceremonySound ? 'on' : 'off');
  _ceremonyPaintSoundBtn();
  if (!_ceremonySound) { _ceremonyStopAudio(); _ceremonyPaintPlayer('▶', 'preview muted'); }
}

function _ceremonyPaintSoundBtn() {
  const btn = document.getElementById('ceremonySoundBtn');
  if (!btn) return;
  btn.textContent = _ceremonySound ? '🔊' : '🔇';
  btn.title = _ceremonySound ? 'Song previews on' : 'Song previews off';
}

function _triggerConfetti() {
  const el = document.getElementById('ceremonyConfetti');
  if (!el) return;
  el.innerHTML = '';
  const colors = ['#FFD700','#FFC04D','#FF69B4','#00CED1','#FF6347','#7B68EE','#32CD32','#FF8C00'];
  for (let i = 0; i < 90; i++) {
    const p = document.createElement('div');
    p.className = 'confetti-piece';
    p.style.cssText = `left:${Math.random()*100}%;background:${colors[i%colors.length]};animation-delay:${(Math.random()*0.9).toFixed(2)}s;animation-duration:${(1.6+Math.random()*1.4).toFixed(2)}s;width:${6+Math.random()*6|0}px;height:${6+Math.random()*6|0}px;border-radius:${Math.random()>.5?'50%':'3px'};`;
    el.appendChild(p);
  }
  setTimeout(() => { if (el) el.innerHTML = ''; }, 3600);
}

// ═══════════════════════════════════════════════════════════════
// ─── YOUR SOUNDTRACK ───────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════

let stPeriodType = 'year';
let stYear = tzNow().getFullYear();
let stMonth = tzNow().getMonth() + 1;
let _stCurrentPlays = [];
let _stReplayTimer = null;
let _stReplaySnapshots = [];
let _stReplayIdx = 0;
let _stReplayMax = 0;
let _stReplayPaused = false;
let _stReplaySpeedMs = 1200;
let _stCardMode = null;
let _stMilestonesCount = 0;
let _stBubbleTimer = null;
let _stBubbleSeeds = [];
let _stBubbleQueue = [];
let _stBubbleUid = 0;
let stReelMode = 'plays';    // which stat card is driving the reel below the stats strip
let _stPeakDayDate = null;   // Date of the busiest day in the current period (set by stRenderStats)
let _stReelLoaderId = 0;     // guards async reel image batches against stale renders
let _stReelEntries = [];     // what the reel is currently showing, for the ＋ Playlist button

function stGetPeriodPlays() {
  if (stPeriodType === 'alltime') return allPlays.slice();
  return allPlays.filter(p => {
    const d = tzDateOf(p);
    if (stPeriodType === 'year') return d.getFullYear() === stYear;
    return d.getFullYear() === stYear && (d.getMonth() + 1) === stMonth;
  });
}

// ── Reel data builders — one per stat-card mode, all chronological ───
// Caps every reel at ST_REEL_MAX evenly-spaced entries so an All-Time period
// with tens of thousands of plays can't blow up the ticker's DOM/image cost.
const ST_REEL_MAX = 400;

function stDecimate(arr, max) {
  if (arr.length <= max) return arr;
  const out = [];
  const step = arr.length / max;
  for (let i = 0; i < max; i++) out.push(arr[Math.floor(i * step)]);
  return out;
}

function stBuildReelPlays(plays) {
  const sorted = [...plays].sort((a, b) => a.date - b.date);
  return stDecimate(sorted, ST_REEL_MAX).map(p => ({
    type: 'song', title: p.title, artist: p.artist, album: p.album || '—', date: p.date
  }));
}

// Every artist in first-play-of-period order — each artist appears once, so
// the ticker loop cycles the full set before any artist can repeat.
function stBuildReelArtists(plays) {
  const sorted = [...plays].sort((a, b) => a.date - b.date);
  const seen = new Set();
  const out = [];
  for (const p of sorted) {
    const list = (p.artists && p.artists.length) ? p.artists : [p.artist];
    for (const ar of list) {
      if (seen.has(ar)) continue;
      seen.add(ar);
      out.push({ type: 'artist', artist: ar, date: p.date });
    }
  }
  return stDecimate(out, ST_REEL_MAX);
}

// Same first-seen logic as stRenderDiscoveries(), shaped for cards instead of bubbles.
function stBuildReelDiscoveries(plays) {
  const fsMap = stGetFirstSeenArtists();
  const seen = new Set();
  const out = [];
  for (const p of plays) {
    for (const artist of (p.artists || splitArtists(p.artist))) {
      if (seen.has(artist)) continue;
      seen.add(artist);
      const fd = fsMap[artist];
      if (!fd) continue;
      const ftz = tzDate(fd);
      const inPeriod = stPeriodType === 'alltime' ? true :
        stPeriodType === 'year' ? ftz.getFullYear() === stYear :
        ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
      if (inPeriod) out.push({ type: 'artist', artist, date: fd });
    }
  }
  out.sort((a, b) => a.date - b.date);
  return stDecimate(out, ST_REEL_MAX);
}

// One card per active day, carrying that day's play count and top track.
function stBuildReelDays(plays) {
  const days = {};
  for (const p of plays) {
    const d = tzDateOf(p);
    const dk = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    let day = days[dk];
    if (!day) day = days[dk] = { date: d, count: 0, songCounts: {} };
    day.count++;
    const sk = songKey(p);
    let s = day.songCounts[sk];
    if (!s) s = day.songCounts[sk] = { title: p.title, artist: p.artist, album: p.album || '—', count: 0 };
    s.count++;
  }
  const out = Object.values(days).map(day => {
    const top = Object.values(day.songCounts).sort((a, b) => b.count - a.count)[0];
    return { type: 'day', date: day.date, count: day.count, topTitle: top.title, topArtist: top.artist, topAlbum: top.album };
  });
  out.sort((a, b) => a.date - b.date);
  return stDecimate(out, ST_REEL_MAX);
}

// Every song played on the single busiest day (see _stPeakDayDate, set by stRenderStats).
function stBuildReelPeakDay(plays) {
  if (!_stPeakDayDate) return [];
  const pd = _stPeakDayDate;
  const dayPlays = plays.filter(p => {
    const d = tzDateOf(p);
    return d.getFullYear() === pd.getFullYear() && d.getMonth() === pd.getMonth() && d.getDate() === pd.getDate();
  }).sort((a, b) => a.date - b.date);
  return stDecimate(dayPlays.map(p => ({
    type: 'song', title: p.title, artist: p.artist, album: p.album || '—', date: p.date
  })), ST_REEL_MAX);
}

const ST_MONTH_KEYS = ['month_jan','month_feb','month_mar','month_apr','month_may_short','month_jun','month_jul','month_aug','month_sep','month_oct','month_nov','month_dec'];

function stGetPeriodLabel() {
  if (stPeriodType === 'alltime') return t('st_period_alltime');
  if (stPeriodType === 'year') return String(stYear);
  return t(ST_MONTH_KEYS[stMonth - 1]) + ' ' + stYear;
}

function stSetPeriod(type) {
  stPeriodType = type;
  document.querySelectorAll('.st-period-btn').forEach(b => b.classList.toggle('active', b.dataset.stPeriod === type));
  const navBar = document.getElementById('stNavBar');
  if (navBar) navBar.style.display = type === 'alltime' ? 'none' : '';
  if (type === 'year') { stYear = tzNow().getFullYear(); }
  if (type === 'month') { stYear = tzNow().getFullYear(); stMonth = tzNow().getMonth() + 1; }
  renderSoundtrack();
}

function stNavigate(dir) {
  if (stPeriodType === 'year') {
    const newYear = stYear + dir;
    if (newYear > tzNow().getFullYear()) return;
    stYear = newYear;
  } else if (stPeriodType === 'month') {
    let m = stMonth + dir, y = stYear;
    if (m < 1) { m = 12; y--; }
    if (m > 12) { m = 1; y++; }
    const now = tzNow();
    if (y > now.getFullYear() || (y === now.getFullYear() && m > now.getMonth() + 1)) return;
    stYear = y; stMonth = m;
  }
  renderSoundtrack();
}

// ── The Reel — ticker below the stats strip, driven by the active stat card ──
const ST_REEL_ACCENTS = { plays: 'var(--accent)', days: 'var(--teal)', artists: 'var(--green)', new: 'var(--gold1)', peak: 'var(--amber)' };
const ST_REEL_SUB_KEYS = { plays: 'st_reel_sub_plays', days: 'st_reel_sub_days', artists: 'st_reel_sub_artists', new: 'st_reel_sub_new', peak: 'st_reel_sub_peak' };

function stSetReelMode(mode) {
  stReelMode = mode;
  document.querySelectorAll('#stStatsStrip .st-stat').forEach(el => {
    el.classList.toggle('active', el.dataset.reelMode === mode);
  });
  stRenderReel(_stCurrentPlays);
}

// Mirrors buildCard() in renderTimeMachine() — same card anatomy/classes, one
// entry type at a time instead of a combined songs+artists+albums toggle.
function stBuildReelCard(entry, i, suffix, songItems, artistItems) {
  const imgId = 'stReelImg-' + suffix + '-' + i;
  // Copy B of the deck — hidden when the reel is short enough not to loop.
  const dupe = suffix === 'b' ? ' dcreel-dupe' : '';
  const dateStr = d => `${t(ST_MONTH_KEYS[d.getMonth()]).substring(0, 3)} ${d.getDate()}`;

  if (entry.type === 'artist') {
    const prefKey = 'artist:' + entry.artist.toLowerCase();
    artistItems.push({ imgId, name: entry.artist, artist: entry.artist, album: '', title: '', prefKey });
    return '<div class="tm-card tm-card-search' + dupe + '" data-type="artist" onclick="_tmShowArtistMenu(event,' + esc(JSON.stringify(entry.artist)) + ')">' +
      '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.artist)) + '</div></div>' +
      '<div class="tm-card-info">' +
      '<div class="tm-card-title">' + esc(entry.artist) + '</div>' +
      '<div class="tm-card-year">' + esc(dateStr(tzDate(entry.date))) + '</div>' +
      '</div></div>';
  }

  if (entry.type === 'day') {
    const prefKey = 'song:' + entry.topArtist.toLowerCase() + '|||' + entry.topTitle.toLowerCase();
    songItems.push({ imgId, title: entry.topTitle, artist: entry.topArtist, album: entry.topAlbum, name: entry.topTitle, prefKey });
    return '<div class="tm-card tm-card-song' + dupe + '" data-type="day" onclick="_tmShowSongMenu(event,' + esc(JSON.stringify(entry.topTitle)) + ',' + esc(JSON.stringify(entry.topArtist)) + ',' + esc(JSON.stringify(entry.topAlbum)) + ')">' +
      '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.topTitle)) + '</div></div>' +
      '<div class="tm-card-info">' +
      '<div class="tm-card-title">' + esc(dateStr(tzDate(entry.date))) + '</div>' +
      '<div class="tm-card-sub">' + esc(entry.topTitle + ' · ' + entry.topArtist) + '</div>' +
      '<div class="tm-card-year">' + entry.count.toLocaleString() + ' ' + esc(tUnit('plays', entry.count)) + '</div>' +
      '</div></div>';
  }

  // 'song' — Plays and Peak Day reels
  const sub = entry.artist + (entry.album && entry.album !== '—' ? ' · ' + entry.album : '');
  const prefKey = 'song:' + entry.artist.toLowerCase() + '|||' + entry.title.toLowerCase();
  songItems.push({ imgId, title: entry.title, artist: entry.artist, album: entry.album, name: entry.title, prefKey });
  return '<div class="tm-card tm-card-song' + dupe + '" data-type="song" onclick="_tmShowSongMenu(event,' + esc(JSON.stringify(entry.title)) + ',' + esc(JSON.stringify(entry.artist)) + ',' + esc(JSON.stringify(entry.album)) + ')">' +
    '<div class="tm-card-img" id="' + esc(imgId) + '"><div class="thumb-initials">' + esc(initials(entry.title)) + '</div></div>' +
    '<div class="tm-card-info">' +
    '<div class="tm-card-title">' + esc(entry.title) + '</div>' +
    '<div class="tm-card-sub">' + esc(sub) + '</div>' +
    '<div class="tm-card-year">' + esc(dateStr(tzDate(entry.date))) + '</div>' +
    '</div></div>';
}

// Mirrors loadTmBatch() in renderTimeMachine() — batches image fetches against
// the shared imgCache, mirroring the 'a' copy into the 'b' copy to halve calls.
async function stReelLoadBatch(pairs, type, loaderId) {
  const BATCH = 4;
  for (let i = 0; i < pairs.length; i += BATCH) {
    if (_stReelLoaderId !== loaderId) return;
    await Promise.all(pairs.slice(i, i + BATCH).map(async ([aItem, bItem]) => {
      if (_stReelLoaderId !== loaderId) return;
      const aEl = document.getElementById(aItem.imgId);
      if (!aEl) return;
      await fetchAndInjectImage(aEl, aItem, type);
      const bEl = bItem && document.getElementById(bItem.imgId);
      if (bEl) bEl.innerHTML = aEl.innerHTML;
    }));
  }
}

// The whole active reel into the picker. Each mode carries a different card
// shape: Plays and Peak Day are already songs, Days cards stand for that day's
// top track, and Artists/Discoveries cards resolve to one recent play each.
function stReelAddToPlaylist() {
  const tracks = [];
  for (const e of (_stReelEntries || [])) {
    if (e.type === 'song')      tracks.push({ title: e.title, artist: e.artist, album: e.album });
    else if (e.type === 'day')  tracks.push({ title: e.topTitle, artist: e.topArtist, album: e.topAlbum });
    else if (e.type === 'artist') { const s = _tmArtistLastSongs(e.artist, 1)[0]; if (s) tracks.push(s); }
  }
  const label = t(ST_REEL_SUB_KEYS[stReelMode]);
  dcOpenPlaylistPicker(tracks, label, `${stGetPeriodLabel()} · ${label}`);
}

function stRenderReel(plays) {
  const section = document.getElementById('stReelSection');
  const track = document.getElementById('stReelTickerTrack');
  const outer = document.getElementById('stReelTickerOuter');
  if (!section || !track) return;

  const sub = document.getElementById('stReelSub');
  if (sub) sub.textContent = t(ST_REEL_SUB_KEYS[stReelMode]) + ' · ' + t('tm_hint');
  section.style.setProperty('--sc', ST_REEL_ACCENTS[stReelMode]);

  let entries;
  switch (stReelMode) {
    case 'days':    entries = stBuildReelDays(plays); break;
    case 'artists': entries = stBuildReelArtists(plays); break;
    case 'new':     entries = stBuildReelDiscoveries(plays); break;
    case 'peak':    entries = stBuildReelPeakDay(plays); break;
    default:        entries = stBuildReelPlays(plays); break;
  }

  // Held for the header's "＋ Playlist" button — see stReelAddToPlaylist().
  _stReelEntries = entries;
  const plBtn = document.getElementById('stReelPlBtn');
  if (plBtn) plBtn.style.display = entries.length ? '' : 'none';

  if (!entries.length) {
    if (outer) outer.style.display = 'none';
    track.innerHTML = `<div class="tm-empty">${t('st_no_data')}</div>`;
    return;
  }
  if (outer) outer.style.display = '';

  const aSongItems = [], aArtistItems = [], bSongItems = [], bArtistItems = [];
  const firstCopy = entries.map((e, i) => stBuildReelCard(e, i, 'a', aSongItems, aArtistItems)).join('');
  const secondCopy = entries.map((e, i) => stBuildReelCard(e, i, 'b', bSongItems, bArtistItems)).join('');
  track.innerHTML = firstCopy + secondCopy;
  // Same reel engine as the Time Machine, so this one drags too. See dcMountReel().
  dcMountReel(outer, track, Math.max(20, entries.length * 4));

  const ldr = ++_stReelLoaderId;
  const songPairs = aSongItems.map((a, i) => [a, bSongItems[i]]);
  const artistPairs = aArtistItems.map((a, i) => [a, bArtistItems[i]]);
  stReelLoadBatch(songPairs, 'song', ldr).then(() => stReelLoadBatch(artistPairs, 'artist', ldr));
}

function renderSoundtrack() {
  if (!allPlays.length) {
    document.getElementById('stStatsStrip').innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
    return;
  }
  const plays = stGetPeriodPlays();
  _stCurrentPlays = plays;

  const navLabel = document.getElementById('stNavLabel');
  if (navLabel) navLabel.textContent = stGetPeriodLabel();

  const heroPeriod = document.getElementById('stHeroPeriod');
  if (heroPeriod) {
    const label = stGetPeriodLabel();
    heroPeriod.textContent = label;
    heroPeriod.setAttribute('data-text', label); // mirrored by the ::before stencil-echo effect
    heroPeriod.classList.toggle('st-hero-period--long', label.length > 7);
  }
  const heroSubtitle = document.getElementById('stHeroSubtitle');
  if (heroSubtitle) {
    heroSubtitle.textContent = stPeriodType === 'alltime' ? t('st_subtitle_alltime') :
      stPeriodType === 'month' ? t('st_subtitle_month') : t('st_subtitle_year');
  }

  stRenderStats(plays);
  stRenderReel(plays);
  stRenderTopCharts(plays);
  stRenderActivity(plays);
  stRenderLoyalty(plays);
  stRenderDiscoveries(plays);
  stRenderMilestones(plays);
  stRenderStreaks(plays);
  stRenderGrammys(plays);
  stRenderGem(plays);

  // Reset replay
  const replayCanvas = document.getElementById('stReplayCanvas');
  const replayBtn = document.getElementById('stReplayBtn');
  const replayStop = document.getElementById('stReplayStopBtn');
  if (replayCanvas) replayCanvas.style.display = 'none';
  if (replayBtn) replayBtn.style.display = '';
  if (replayStop) replayStop.style.display = 'none';
  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }

  // Close card preview
  const cardPreview = document.getElementById('stCardPreview');
  if (cardPreview) cardPreview.style.display = 'none';

  // Section visibility
  const isYear = stPeriodType === 'year';
  const isAlltime = stPeriodType === 'alltime';
  const loyaltySection = document.getElementById('stLoyaltySection');
  const activitySection = document.getElementById('stActivitySection');
  const replaySection = document.getElementById('stReplaySection');
  if (loyaltySection) loyaltySection.style.display = isYear ? '' : 'none';
  if (activitySection) activitySection.style.display = (isYear || isAlltime) ? '' : 'none';
  if (replaySection) replaySection.style.display = isYear ? '' : 'none';

  requestAnimationFrame(stSetupReveal);
}

function stSetupReveal() {
  if (!('IntersectionObserver' in window)) {
    document.querySelectorAll('#soundtrackView .st-reveal').forEach(el => el.classList.add('st-in'));
    return;
  }
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('st-in'); obs.unobserve(e.target); } });
  }, { threshold: 0.07, rootMargin: '0px 0px -20px 0px' });
  document.querySelectorAll('#soundtrackView .st-reveal').forEach(el => {
    el.classList.remove('st-in');
    obs.observe(el);
  });
}

// ── Animated count-up ─────────────────────────────────────────
function stCountUp(id, target) {
  const el = document.getElementById(id);
  if (!el) return;
  if (target === 0) { el.textContent = '0'; return; }
  const dur = 900;
  const start = Date.now();
  const tick = () => {
    const p = Math.min((Date.now() - start) / dur, 1);
    const ease = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(ease * target).toLocaleString();
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

// ── Stats strip ───────────────────────────────────────────────
function stRenderStats(plays) {
  const ids = ['stStatPlaysVal','stStatDaysVal','stStatArtistsVal','stStatNewVal'];
  if (!plays.length) {
    ids.forEach(id => { const el = document.getElementById(id); if (el) el.textContent = '0'; });
    const peakEl = document.getElementById('stStatPeakVal'); if (peakEl) peakEl.textContent = '—';
    const peakNoteEl = document.getElementById('stStatPeakNote'); if (peakNoteEl) peakNoteEl.textContent = '';
    _stPeakDayDate = null;
    return;
  }

  const dayCounts = {};
  for (const p of plays) {
    const d = tzDateOf(p);
    const dk = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    (dayCounts[dk] || (dayCounts[dk] = { count: 0, date: d })).count++;
  }
  const daySet = new Set(Object.keys(dayCounts));
  const artistSet = new Set(plays.map(p => p.artist.toLowerCase()));

  // New discoveries: each comma-split artist whose first-ever play falls in
  // this period, counted individually — same splitting rules (incl. hardwired
  // exceptions like "Tyler, The Creator") as the main charts use.
  const fsMap = stGetFirstSeenArtists();
  const splitArtistSet = new Set(plays.flatMap(p => p.artists || splitArtists(p.artist)));
  let newCount = 0;
  for (const a of splitArtistSet) {
    const fd = fsMap[a];
    if (!fd) continue;
    const ftz = tzDate(fd);
    const inPeriod = stPeriodType === 'alltime' ? true :
      stPeriodType === 'year' ? ftz.getFullYear() === stYear :
      ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
    if (inPeriod) newCount++;
  }

  // Peak day: the single busiest day within the period
  let peakDay = null;
  for (const dk of daySet) {
    if (!peakDay || dayCounts[dk].count > dayCounts[peakDay].count) peakDay = dk;
  }
  _stPeakDayDate = peakDay ? dayCounts[peakDay].date : null; // consumed by stBuildReelPeakDay

  stCountUp('stStatPlaysVal', plays.length);
  stCountUp('stStatDaysVal', daySet.size);
  stCountUp('stStatArtistsVal', artistSet.size);
  stCountUp('stStatNewVal', newCount);

  const peakEl = document.getElementById('stStatPeakVal');
  const peakNoteEl = document.getElementById('stStatPeakNote');
  if (peakEl && peakDay) {
    const pd = dayCounts[peakDay].date;
    peakEl.textContent = `${t(ST_MONTH_KEYS[pd.getMonth()]).substring(0, 3)} ${pd.getDate()}`;
    if (peakNoteEl) peakNoteEl.textContent = `${dayCounts[peakDay].count.toLocaleString()} ${tUnit('plays', dayCounts[peakDay].count)}`;
  }

  const noteEl = document.getElementById('stStatPlaysNote');
  if (noteEl) noteEl.textContent = daySet.size > 0 ? `~${Math.round(plays.length / daySet.size).toLocaleString()}/day` : '';
}

// Reuses the app's canonical first-seen map (built from each play's already
// comma-split .artists list, same as the New Entries/"NEW" badges on the
// main charts) so a discovery counts per individual artist, not per raw
// "Artist A, Artist B" credit string — with the same hardwired exceptions
// (e.g. "Tyler, The Creator") that splitArtists() respects everywhere else.
function stGetFirstSeenArtists() {
  if (!firstSeenMaps || !firstSeenMaps.artistFirst) firstSeenMaps = buildFirstSeenMaps();
  return firstSeenMaps.artistFirst;
}

// ── Top 50 Artists + Songs — iPod-style coverflow carousels ───
function stRenderTopCharts(plays) {
  // Each comma-split artist counts on its own (honoring the hardwired
  // exceptions in splitArtists, e.g. "Tyler, The Creator") — same rule
  // New Discoveries and the artist-modal rank use, so a "Artist A, Artist B"
  // credit doesn't get counted as one combined act.
  const artistCounts = {};
  for (const p of plays) {
    for (const a of (p.artists || splitArtists(p.artist))) artistCounts[a] = (artistCounts[a] || 0) + 1;
  }
  const topArtists = Object.entries(artistCounts).sort((a, b) => b[1] - a[1]).slice(0, 50);

  const songCounts = {};
  for (const p of plays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, artist: p.artist, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 50);

  const taEl = document.getElementById('stTopArtists');
  const tsEl = document.getElementById('stTopSongs');

  if (taEl) {
    if (topArtists.length) {
      stInitCoverflow(taEl, topArtists.map(([name, count]) => ({
        title: name, sub: '', count, imgType: 'artist', imgArgs: [name],
        onCenterTap: () => stOpenArtistModal(name)
      })), t('st_top_artists'));
    } else {
      taEl.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
    }
  }

  if (tsEl) {
    if (topSongs.length) {
      stInitCoverflow(tsEl, topSongs.map(s => ({
        title: s.title, sub: s.artist, count: s.count, imgType: 'track', imgArgs: [s.title, s.artist]
      })), t('st_top_songs'));
    } else {
      tsEl.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`;
    }
  }

  const featuredEl = document.getElementById('stFeaturedArtist');
  if (featuredEl) {
    if (topArtists.length) {
      featuredEl.style.display = '';
      stRenderFeaturedArtist(plays, topArtists[0][0], topArtists[0][1]);
    } else {
      featuredEl.style.display = 'none';
    }
  }
}

// ── Coverflow carousel engine ──────────────────────────────────
// Renders `items` (up to 50) as absolutely-positioned 3D cards inside
// `viewportEl` and wires up drag (mouse+touch via Pointer Events), wheel,
// and keyboard navigation. Images load lazily around whichever card is
// centered so a 50-entry list never fires 50 simultaneous image fetches.
function stInitCoverflow(viewportEl, items, label) {
  const n = items.length;
  const uid = viewportEl.id || 'cf' + Math.random().toString(36).slice(2);

  // Same prefKey convention as the chart tables, so a source cycled here (or there)
  // is remembered everywhere and shares the same image cache.
  items.forEach((it, i) => {
    it.imgId = `art-${uid}-${i}`;
    if (it.imgType === 'artist') {
      it.name = it.imgArgs[0];
      it.prefKey = 'artist:' + it.imgArgs[0].toLowerCase();
    } else {
      it.artist = it.imgArgs[1];
      it.prefKey = 'song:' + it.imgArgs[1].toLowerCase() + '|||' + it.imgArgs[0].toLowerCase();
    }
  });

  viewportEl.innerHTML = `
    <div class="st-cf-viewport" tabindex="0" role="listbox" aria-label="${esc(label || '')}">
      <button type="button" class="st-cf-nav st-cf-nav-prev" aria-label="Previous">&lsaquo;</button>
      <div class="st-cf-track">
        ${items.map((it, i) => `
          <div class="st-cf-card" id="idx-${uid}-${i}" data-idx="${i}" role="option">
            <div class="st-cf-art" id="${it.imgId}" title="Click to try the next image source"><div class="thumb-initials">${esc(initials(it.title))}</div></div>
            <span class="st-cf-rank${i < 3 ? ' st-cf-medal st-cf-medal-' + (i + 1) : ''}">${i + 1}</span>
          </div>`).join('')}
      </div>
      <button type="button" class="st-cf-nav st-cf-nav-next" aria-label="Next">&rsaquo;</button>
    </div>
    <div class="st-cf-meta">
      <div class="st-cf-name"></div>
      <div class="st-cf-sub"></div>
      <div class="st-cf-count"></div>
    </div>
    <div class="st-cf-progress"><div class="st-cf-progress-fill"></div></div>`;

  const viewport = viewportEl.querySelector('.st-cf-viewport');
  const track = viewportEl.querySelector('.st-cf-track');
  const cards = Array.from(viewportEl.querySelectorAll('.st-cf-card'));
  const nameEl = viewportEl.querySelector('.st-cf-name');
  const subEl = viewportEl.querySelector('.st-cf-sub');
  const countEl = viewportEl.querySelector('.st-cf-count');
  const progressFill = viewportEl.querySelector('.st-cf-progress-fill');
  const prevBtn = viewportEl.querySelector('.st-cf-nav-prev');
  const nextBtn = viewportEl.querySelector('.st-cf-nav-next');

  const state = { pos: 0, stepPx: 96, dragging: false, startX: 0, startPos: 0, lastX: 0, lastT: 0, velocity: 0 };
  const loaded = new Set();
  const RADIUS = 3;

  function computeStep() {
    const w = viewport.clientWidth || 320;
    state.stepPx = Math.max(84, Math.min(174, w / 3.6));
  }
  computeStep();

  function ensureImages(centerIdx) {
    for (let off = -RADIUS; off <= RADIUS; off++) {
      const idx = centerIdx + off;
      if (idx < 0 || idx >= n || loaded.has(idx)) continue;
      loaded.add(idx);
      const it = items[idx];
      const artEl = cards[idx]?.querySelector('.st-cf-art');
      // Shares the same deezer→itunes→lastfm→youtube fallback chain (and per-item
      // source preference) as the chart tables. Routed through the same global
      // imgQueue so requests are throttled one-at-a-time like the tables — firing
      // all ~7 lookups at once floods the Deezer proxy, triggers rate-limiting,
      // and silently downgrades to lower-res itunes/lastfm art.
      if (artEl) imgQueue = imgQueue.then(() => fetchAndInjectImage(artEl, it, it.imgType));
    }
  }

  function updateMeta() {
    const idx = Math.max(0, Math.min(n - 1, Math.round(state.pos)));
    const it = items[idx];
    if (!it) return;
    nameEl.textContent = it.title;
    subEl.textContent = it.sub || '';
    subEl.style.display = it.sub ? '' : 'none';
    countEl.textContent = `#${idx + 1} · ${it.count.toLocaleString()} ${tUnit('plays', it.count)}`;
    progressFill.style.width = n > 1 ? `${(idx / (n - 1)) * 100}%` : '100%';
    viewport.setAttribute('aria-activedescendant', `idx-${uid}-${idx}`);
  }

  function render() {
    const centerRounded = Math.round(state.pos);
    cards.forEach((card, i) => {
      const offset = i - state.pos;
      const abs = Math.abs(offset);
      if (abs > 9) {
        if (card.style.visibility !== 'hidden') card.style.visibility = 'hidden';
        return;
      }
      if (card.style.visibility === 'hidden') card.style.visibility = '';
      const angle = Math.max(-68, Math.min(68, -offset * 68));
      const scale = Math.max(0.5, 1 - Math.min(abs, 5) * 0.11);
      const tx = offset * state.stepPx;
      const tz = -Math.min(abs, 6) * 44;
      const op = Math.max(0, 1 - Math.min(abs, 6) * 0.17);
      card.style.transform = `translate(-50%,-50%) translateX(${tx}px) translateZ(${tz}px) rotateY(${angle}deg) scale(${scale})`;
      card.style.opacity = op;
      card.style.zIndex = String(1000 - Math.round(abs * 10));
      card.classList.toggle('is-center', i === centerRounded);
    });
    updateMeta();
  }

  function clampPos(p, elastic) {
    if (p < 0) return elastic ? p * 0.3 : 0;
    if (p > n - 1) return elastic ? (n - 1) + (p - (n - 1)) * 0.3 : n - 1;
    return p;
  }

  function goTo(idx, animate) {
    idx = Math.max(0, Math.min(n - 1, idx));
    track.classList.toggle('st-cf-animate', animate !== false);
    state.pos = idx;
    render();
    ensureImages(idx);
  }

  // ── Pointer drag (mouse + touch + pen, unified) ──────────────
  viewport.addEventListener('pointerdown', e => {
    if (e.target.closest('.st-cf-nav')) return;
    state.dragging = true;
    state.startX = e.clientX;
    state.startPos = state.pos;
    state.lastX = e.clientX;
    state.lastT = performance.now();
    state.velocity = 0;
    track.classList.remove('st-cf-animate');
    viewport.classList.add('is-dragging');
    viewport.setPointerCapture(e.pointerId);
  });

  viewport.addEventListener('pointermove', e => {
    if (!state.dragging) return;
    const deltaX = e.clientX - state.startX;
    const rawPos = state.startPos - deltaX / state.stepPx;
    state.pos = clampPos(rawPos, true);
    const now = performance.now();
    const dt = now - state.lastT;
    if (dt > 0) state.velocity = (e.clientX - state.lastX) / dt;
    state.lastX = e.clientX;
    state.lastT = now;
    render();
  });

  function endDrag(e) {
    if (!state.dragging) return;
    state.dragging = false;
    viewport.classList.remove('is-dragging');
    try { viewport.releasePointerCapture(e.pointerId); } catch (err) {}
    const moved = Math.abs(e.clientX - state.startX);
    if (moved < 4) {
      // treat as a click/tap rather than a drag
      // Pointer capture (set on pointerdown, above) retargets e.target to `viewport`
      // for pointerup, so a real hit-test at the pointer's coordinates is needed here.
      const hit = document.elementFromPoint(e.clientX, e.clientY);
      const card = hit && hit.closest('.st-cf-card');
      if (card) {
        const idx = Number(card.dataset.idx);
        const isCentered = idx === Math.round(state.pos);
        // Tapping the artwork of the already-centered card opens the image picker
        // instead of selecting it — the art is only hit-testable when centered (see CSS).
        if (isCentered && hit.closest('.st-cf-art')) {
          const it = items[idx];
          openImgPicker({
            imgid: it.imgId, type: it.imgType, prefkey: it.prefKey,
            name: it.imgType === 'artist' ? it.name : (it.title || it.name),
            artist: it.artist || '', album: it.album || ''
          });
          return;
        }
        if (isCentered && items[idx].onCenterTap) items[idx].onCenterTap();
        else goTo(idx, true);
        return;
      }
    }
    const flingSteps = -state.velocity * 140 / state.stepPx;
    goTo(Math.round(state.pos + flingSteps), true);
  }
  viewport.addEventListener('pointerup', endDrag);
  viewport.addEventListener('pointercancel', endDrag);

  // ── Wheel (mouse wheel + trackpad) — live scrub, settles on pause ──
  // Each event's contribution is capped to one card so a single physical
  // wheel notch (~100-120px in Chrome) can never overshoot past the next
  // entry — only sustained/continuous scrolling (trackpad) covers more ground.
  let wheelSettleTimer = null;
  viewport.addEventListener('wheel', e => {
    e.preventDefault();
    let delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    if (e.deltaMode === 1) delta *= 16;              // "line" mode (Firefox) → approx px
    else if (e.deltaMode === 2) delta *= viewport.clientHeight; // "page" mode
    track.classList.remove('st-cf-animate');
    const step = Math.sign(delta) * Math.min(Math.abs(delta) / 220, 1);
    state.pos = clampPos(state.pos + step, true);
    render();
    clearTimeout(wheelSettleTimer);
    wheelSettleTimer = setTimeout(() => goTo(Math.round(state.pos), true), 130);
  }, { passive: false });

  // ── Keyboard ───────────────────────────────────────────────
  viewport.addEventListener('keydown', e => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); goTo(Math.round(state.pos) + 1, true); }
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); goTo(Math.round(state.pos) - 1, true); }
    else if (e.key === 'PageDown') { e.preventDefault(); goTo(Math.round(state.pos) + 5, true); }
    else if (e.key === 'PageUp') { e.preventDefault(); goTo(Math.round(state.pos) - 5, true); }
    else if (e.key === 'Home') { e.preventDefault(); goTo(0, true); }
    else if (e.key === 'End') { e.preventDefault(); goTo(n - 1, true); }
  });

  prevBtn.addEventListener('click', () => goTo(Math.round(state.pos) - 1, true));
  nextBtn.addEventListener('click', () => goTo(Math.round(state.pos) + 1, true));

  window.addEventListener('resize', () => { computeStep(); render(); }, { passive: true });

  goTo(0, false);
}

// ── Featured #1 Artist — banner + accomplishment collage ──────
// Pulls a banner photo (same artist-image lookup used everywhere else, so it
// works regardless of data source) and computes a set of "wrapped"-style
// stats scoped to just this artist's plays within the active period.
function stRenderFeaturedArtist(periodPlays, artistName, totalCount) {
  const nameEl = document.getElementById('stFeaturedArtistName');
  const countEl = document.getElementById('stFeaturedArtistCount');
  if (nameEl) nameEl.textContent = artistName;
  if (countEl) countEl.textContent = `${totalCount.toLocaleString()} ${tUnit('plays', totalCount)}`;

  // Banner photo — cleared first so a stale image from the previous artist
  // never lingers while the new one loads.
  const bannerEl = document.getElementById('stFeaturedBanner');
  if (bannerEl) {
    bannerEl.style.backgroundImage = '';
    getArtistImage(artistName, 'deezer').then(url => {
      if (bannerEl.isConnected && document.getElementById('stFeaturedArtistName')?.textContent === artistName) {
        bannerEl.style.backgroundImage = url ? `url("${url}")` : '';
      }
    });
  }

  const aLower = artistName.toLowerCase();
  const isThisArtist = p => (p.artists || splitArtists(p.artist)).some(a => a.toLowerCase() === aLower);
  const artistPlays = periodPlays.filter(isThisArtist).slice().sort((a, b) => a.date - b.date);

  const pad2 = n => String(n).padStart(2, '0');
  const dayKey = d => { const tz = tzDate(d); return `${tz.getFullYear()}-${pad2(tz.getMonth() + 1)}-${pad2(tz.getDate())}`; };

  // Active days + the single day this artist was played most
  const dayCounts = {};
  for (const p of artistPlays) {
    const dk = dayKey(p.date);
    (dayCounts[dk] || (dayCounts[dk] = { count: 0, date: tzDateOf(p) })).count++;
  }
  const dayKeys = Object.keys(dayCounts).sort();
  let peakDayKey = null;
  for (const dk of dayKeys) { if (!peakDayKey || dayCounts[dk].count > dayCounts[peakDayKey].count) peakDayKey = dk; }

  // Longest run of consecutive calendar days with at least one play
  let longestDayStreak = dayKeys.length ? 1 : 0, curDayStreak = 1;
  for (let i = 1; i < dayKeys.length; i++) {
    const diff = Math.round((new Date(dayKeys[i]) - new Date(dayKeys[i - 1])) / 86400000);
    curDayStreak = diff === 1 ? curDayStreak + 1 : 1;
    if (curDayStreak > longestDayStreak) longestDayStreak = curDayStreak;
  }

  // Longest back-to-back run of plays by this artist within the full listening
  // timeline for the period (i.e. how many songs in a row before switching artist).
  // A collab track counts as a continuation as long as this artist is one of its
  // comma-separated credits.
  const allSorted = periodPlays.slice().sort((a, b) => a.date - b.date);
  let longestPlayStreak = 0, curPlayStreak = 0;
  for (const p of allSorted) {
    if (isThisArtist(p)) { curPlayStreak++; if (curPlayStreak > longestPlayStreak) longestPlayStreak = curPlayStreak; }
    else curPlayStreak = 0;
  }
  // Longest back-to-back run of plays matching a narrower predicate (e.g. "this
  // exact album" or "this exact song") — breaks on anything that doesn't match,
  // whether that's a different artist or this artist playing something else.
  const computeStreak = matchFn => {
    let longest = 0, cur = 0;
    for (const p of allSorted) { if (matchFn(p)) { cur++; if (cur > longest) longest = cur; } else cur = 0; }
    return longest;
  };
  // Longest run of consecutive calendar days present in a set of day keys
  const dayStreakFor = daySet => {
    const keys = Array.from(daySet).sort();
    let longest = keys.length ? 1 : 0, cur = 1;
    for (let i = 1; i < keys.length; i++) {
      const diff = Math.round((new Date(keys[i]) - new Date(keys[i - 1])) / 86400000);
      cur = diff === 1 ? cur + 1 : 1;
      if (cur > longest) longest = cur;
    }
    return longest;
  };

  // Distinct songs + albums (album may be blank for some data sources — skip those)
  const songSet = new Set(artistPlays.map(p => songKey(p)));
  const albumSet = new Set(artistPlays.filter(p => p.album && p.album !== '—').map(p => p.album));

  // Hour of day this artist gets played the most
  const hourCounts = new Array(24).fill(0);
  for (const p of artistPlays) hourCounts[tzDateOf(p).getHours()]++;
  let peakHour = 0;
  for (let h = 1; h < 24; h++) { if (hourCounts[h] > hourCounts[peakHour]) peakHour = h; }
  const fmtHour = h => { const per = h < 12 ? 'AM' : 'PM'; const h12 = h % 12 === 0 ? 12 : h % 12; return `${h12} ${per}`; };
  const fmtDate = d => `${t(ST_MONTH_KEYS[d.getMonth()]).substring(0, 3)} ${d.getDate()}`;

  // Favorite album: the one this artist was played from the most within the
  // period (by total plays, not by streak length), plus that specific album's
  // own play streak and day streak.
  const albumCounts = {};
  for (const p of artistPlays) {
    if (!p.album || p.album === '—') continue;
    const rec = albumCounts[p.album] || (albumCounts[p.album] = { count: 0, days: new Set() });
    rec.count++; rec.days.add(dayKey(p.date));
  }
  let topAlbum = null, topAlbumRec = null;
  for (const alb in albumCounts) { if (!topAlbum || albumCounts[alb].count > topAlbumRec.count) { topAlbum = alb; topAlbumRec = albumCounts[alb]; } }
  const albumPlayStreak = topAlbum ? computeStreak(p => isThisArtist(p) && p.album === topAlbum) : 0;
  const albumDayStreak = topAlbum ? dayStreakFor(topAlbumRec.days) : 0;

  // Favorite song: the one played the most within the period, plus its own
  // play streak and day streak.
  const songCounts = {};
  for (const p of artistPlays) {
    const sk = songKey(p);
    const rec = songCounts[sk] || (songCounts[sk] = { title: p.title, count: 0, days: new Set(), key: sk });
    rec.count++; rec.days.add(dayKey(p.date));
  }
  const topSong = Object.values(songCounts).sort((a, b) => b.count - a.count)[0] || null;
  const songPlayStreak = topSong ? computeStreak(p => isThisArtist(p) && songKey(p) === topSong.key) : 0;
  const songDayStreak = topSong ? dayStreakFor(topSong.days) : 0;

  const sharePct = periodPlays.length ? Math.round(totalCount / periodPlays.length * 100) : 0;
  const avgPerDay = dayKeys.length ? Math.round(totalCount / dayKeys.length * 10) / 10 : 0;

  // ── Bento collage ──────────────────────────────────────────────
  // One big "hero" tile for the standout number, two content tiles for the
  // text-heavy favorite album/song, and a cluster of small tiles for
  // everything else — mirrors a Wrapped-style collage rather than a plain grid.
  const heroTile = { icon: '⚡', label: t('st_feat_label_play_streak'), value: longestPlayStreak.toLocaleString(), note: t('st_feat_note_play_streak'), area: 'hero', role: 'hero' };
  const contentTiles = [
    { icon: '🏆', label: t('st_feat_label_favorite_album'), value: topAlbum || '—',
      note: topAlbum ? [
        t('st_feat_total_plays', { plays: tCount('plays', topAlbumRec.count) }),
        t('st_feat_note_play_streak_row', { n: albumPlayStreak }),
        t('st_feat_note_day_streak', { n: albumDayStreak }),
      ] : '', area: 'album', role: 'content' },
    { icon: '🎧', label: t('st_feat_label_favorite_song'), value: topSong ? topSong.title : '—',
      note: topSong ? [
        t('st_feat_total_plays', { plays: tCount('plays', topSong.count) }),
        t('st_feat_note_play_streak_row', { n: songPlayStreak }),
        t('st_feat_note_day_streak', { n: songDayStreak }),
      ] : '', area: 'song', role: 'content' },
  ];
  // Small tiles: ones with a secondary note get more room ("med", 2 cols)
  // than bare-number ones ("small", 1 col) — a mosaic rather than a uniform
  // grid of same-size squares.
  const smallTiles = [
    { icon: '🔥', label: t('st_feat_label_most_played_day'), value: peakDayKey ? fmtDate(dayCounts[peakDayKey].date) : '—',
      note: peakDayKey ? tCount('plays', dayCounts[peakDayKey].count) : '', area: 'dmp', role: 'med' },
    { icon: '📆', label: t('st_feat_label_day_streak'), value: longestDayStreak.toLocaleString(), note: t('st_feat_note_consecutive_days'), area: 'dst', role: 'med' },
    { icon: '📅', label: t('st_feat_label_days_played'), value: dayKeys.length.toLocaleString(), area: 'day', role: 'small' },
    { icon: '🎵', label: t('st_feat_label_songs_played'), value: songSet.size.toLocaleString(), area: 'sng', role: 'small' },
    { icon: '📊', label: t('st_feat_label_share_of_total'), value: `${sharePct}%`, area: 'shr', role: 'med' },
    { icon: '📈', label: t('st_feat_label_avg_per_day'), value: avgPerDay.toLocaleString(), area: 'avg', role: 'med' },
    { icon: '💿', label: t('st_feat_label_albums_played'), value: albumSet.size.toLocaleString(), area: 'alb', role: 'small' },
    { icon: '🕐', label: t('st_feat_label_peak_hour'), value: dayKeys.length ? fmtHour(peakHour) : '—', area: 'pkh', role: 'small' },
  ];

  const tiles = [heroTile, ...contentTiles, ...smallTiles];

  const gridEl = document.getElementById('stFeaturedStats');
  if (gridEl) {
    gridEl.innerHTML = tiles.map((s, i) => {
      // content tiles (album/song) also get an area-specific class so each
      // can carry its own accent color; hero/small/med tiles don't need one
      const areaClass = s.role === 'content' ? ` st-fstat-${s.area}` : '';
      return `
      <div class="st-fstat st-fstat-${s.role}${areaClass}" style="--i:${i};grid-area:${s.area}">
        <div class="st-fstat-value">${esc(String(s.value))}</div>
        <div class="st-fstat-label"><span class="st-fstat-icon">${s.icon}</span> ${esc(s.label)}</div>
        ${Array.isArray(s.note)
          ? s.note.filter(Boolean).map(n => `<div class="st-fstat-note">${esc(n)}</div>`).join('')
          : (s.note ? `<div class="st-fstat-note">${esc(s.note)}</div>` : '')}
      </div>`;
    }).join('');
  }
}

// ── Monthly Activity ──────────────────────────────────────────
function stRenderActivity(plays) {
  const el = document.getElementById('stActivityBars');
  if (!el) return;
  if (!plays.length) { el.innerHTML = ''; return; }

  const byMonth = {};        // 'YYYY-MM' -> play count
  const artistsByMonth = {}; // 'YYYY-MM' -> { artist: count }, powers the tap-to-inspect panel below
  for (const p of plays) {
    const d = tzDateOf(p);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    byMonth[key] = (byMonth[key] || 0) + 1;
    const am = artistsByMonth[key] || (artistsByMonth[key] = {});
    am[p.artist] = (am[p.artist] || 0) + 1;
  }
  const months = Object.keys(byMonth).sort();
  if (!months.length) { el.innerHTML = ''; return; }

  const total = plays.length;
  const max = Math.max(...Object.values(byMonth));
  const peakKey = months.reduce((a, b) => byMonth[a] >= byMonth[b] ? a : b);
  const lowKey = months.length > 1 ? months.reduce((a, b) => byMonth[a] <= byMonth[b] ? a : b) : null;

  const monthLabel = (mk, withYear) => {
    const [y, m] = mk.split('-');
    const name = t(ST_MONTH_KEYS[parseInt(m) - 1]);
    return withYear && y !== String(stYear) ? `${name} ${y}` : name;
  };
  // most-played artist for a given month, surfaced in the detail panel on tap
  const topArtistOf = key => {
    const counts = artistsByMonth[key] || {};
    let best = null, bestN = 0;
    for (const a in counts) { if (counts[a] > bestN) { best = a; bestN = counts[a]; } }
    return best ? { name: best, count: bestN } : null;
  };

  const barsHTML = months.map((mk, i) => {
    const [y, m] = mk.split('-');
    const label = t(ST_MONTH_KEYS[parseInt(m) - 1]).substring(0, 3);
    const count = byMonth[mk];
    const pct = Math.round(count / max * 100);
    const isPeak = mk === peakKey;
    const cls = (isPeak ? ' st-peak' : mk === lowKey ? ' st-low' : '') + (isPeak ? ' is-selected' : '');

    // month-over-month change vs the previous bar, shown as a mini arrow + in the detail panel.
    // For the first bar in the period (e.g. January of a year view), the previous month lives
    // outside the filtered `plays` array — reach into allPlays for that one calendar month instead.
    let prevMk = i > 0 ? months[i - 1] : null;
    let prevCount = prevMk ? byMonth[prevMk] : null;
    if (!prevMk) {
      const [y0, m0] = mk.split('-').map(Number);
      const prevDate = new Date(y0, m0 - 2, 1);
      const lookbackKey = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
      const lookbackCount = allPlays.reduce((n, p) => {
        const d = tzDateOf(p);
        return n + (`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}` === lookbackKey ? 1 : 0);
      }, 0);
      // No plays at all in that prior month (e.g. it predates the listening history) — treat as
      // flat 0% rather than leaving the chip blank, so every bar keeps the same layout.
      prevMk = lookbackKey;
      prevCount = lookbackCount || null;
    }
    const deltaPct = prevMk ? (prevCount ? Math.round((count - prevCount) / prevCount * 100) : 0) : null;
    const deltaDir = deltaPct === null ? '' : deltaPct > 0 ? 'up' : deltaPct < 0 ? 'down' : 'flat';
    const deltaChip = deltaPct !== null
      ? `<span class="st-activity-delta st-${deltaDir}">${deltaDir === 'up' ? '▲' : deltaDir === 'down' ? '▼' : '•'}${Math.abs(deltaPct)}%</span>`
      : '';

    const sharePct = Math.round(count / total * 100);
    const top = topArtistOf(mk);

    return `<button type="button" class="st-activity-col${cls}" style="--i:${i}"
      data-label="${esc(monthLabel(mk, true))}"
      data-count="${count}"
      data-share="${sharePct}"
      data-delta="${deltaPct === null ? '' : Math.abs(deltaPct)}"
      data-delta-dir="${deltaDir}"
      data-prev-label="${prevMk ? esc(monthLabel(prevMk, true)) : ''}"
      data-artist="${top ? esc(top.name) : ''}"
      data-artist-count="${top ? top.count : ''}"
      onclick="stActivitySelectMonth(this)">
      <div class="st-activity-bar-wrap"><div class="st-activity-bar" style="height:${Math.max(pct,2)}%"></div></div>
      ${deltaChip}
      <div class="st-activity-label">${label}${months.length > 12 ? '<br><span class="st-activity-year">' + y + '</span>' : ''}</div>
      <div class="st-activity-count">${count.toLocaleString()}</div>
    </button>`;
  }).join('');

  // momentum: back half of the period vs the front half, ±10% before it's worth calling out
  let momentum = null;
  if (months.length > 2) {
    const mid = Math.ceil(months.length / 2);
    const avg = keys => keys.reduce((s, k) => s + byMonth[k], 0) / keys.length;
    const change = (avg(months.slice(mid)) - avg(months.slice(0, mid))) / avg(months.slice(0, mid));
    momentum = change > 0.1 ? 'up' : change < -0.1 ? 'down' : 'flat';
  }

  let caption = '';
  if (months.length > 1) {
    const peakName = monthLabel(peakKey, true);
    const lowName = monthLabel(lowKey, true);
    const momentumHTML = momentum ? `<span class="st-momentum-label st-${momentum}">${momentum === 'up' ? '📈' : momentum === 'down' ? '📉' : '➡️'} ${t('st_activity_momentum')}: <strong>${t('st_activity_momentum_' + momentum)}</strong></span>` : '';
    caption = `<div class="st-activity-caption">
      <span class="st-peak-label">🏆 ${t('st_activity_peak')}: <strong>${peakName}</strong> (${byMonth[peakKey].toLocaleString()} ${tUnit('plays', byMonth[peakKey])})</span>
      <span class="st-low-label">💤 ${t('st_activity_low')}: <strong>${lowName}</strong> (${byMonth[lowKey].toLocaleString()} ${tUnit('plays', byMonth[lowKey])})</span>
      ${momentumHTML}
    </div>`;
  }

  el.innerHTML = `<div class="st-activity-chart">${barsHTML}</div>${caption}<div class="st-activity-detail"></div>`;

  // pre-fill the detail panel with the peak month so the tap interaction is discoverable, not empty
  const defaultBtn = el.querySelector('.st-activity-col.is-selected') || el.querySelector('.st-activity-col');
  if (defaultBtn) stActivitySelectMonth(defaultBtn);
}

// Populates the Monthly Activity detail panel when a bar is tapped/clicked;
// reads the data-* attributes stamped onto each button in stRenderActivity
// rather than recomputing, so this stays a cheap DOM-only update.
function stActivitySelectMonth(btn) {
  const root = btn.closest('#stActivityBars');
  if (!root) return;
  root.querySelectorAll('.st-activity-col.is-selected').forEach(c => c.classList.remove('is-selected'));
  btn.classList.add('is-selected');
  const panel = root.querySelector('.st-activity-detail');
  if (!panel) return;
  const d = btn.dataset;

  const deltaHTML = d.delta
    ? `<span class="st-activity-detail-delta st-${d.deltaDir}">${d.deltaDir === 'up' ? '▲' : d.deltaDir === 'down' ? '▼' : '•'} ${d.delta}% ${t('st_activity_vs_prev', { month: d.prevLabel })}</span>`
    : '';
  const artistHTML = d.artist
    ? `<div class="st-activity-detail-artist">🎤 ${t('st_activity_top_artist')}: <strong>${esc(d.artist)}</strong> · ${tCount('plays', parseInt(d.artistCount))}</div>`
    : '';

  panel.innerHTML = `
    <div class="st-activity-detail-head">
      <div class="st-activity-detail-month">${esc(d.label)}</div>
      <div class="st-activity-detail-nums">
        <span class="st-activity-detail-count">${tCount('plays', parseInt(d.count))}</span>
        <span class="st-activity-detail-share">${d.share}% ${t('st_activity_share_of_total')}</span>
        ${deltaHTML}
      </div>
    </div>
    ${artistHTML}
  `;
}

// ── Loyalty Score ─────────────────────────────────────────────
function stRenderLoyalty(plays) {
  const el = document.getElementById('stLoyaltyBody');
  if (!el) return;
  const prevYear = stYear - 1;
  const prevPlays = allPlays.filter(p => tzDateOf(p).getFullYear() === prevYear);

  if (!prevPlays.length || !plays.length) {
    el.innerHTML = `<div class="st-empty">${t('st_loyalty_no_prev', { year: prevYear })}</div>`;
    return;
  }

  const topCounts = ps => {
    const counts = {};
    for (const p of ps) counts[p.artist.toLowerCase()] = (counts[p.artist.toLowerCase()] || 0) + 1;
    return counts;
  };
  const topSet = counts => new Set(Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([a]) => a));

  const prevCounts = topCounts(prevPlays);
  const curCounts = topCounts(plays);
  const prevTop = topSet(prevCounts);
  const curTop = topSet(curCounts);
  const returningKeys = [...curTop].filter(a => prevTop.has(a));
  const returning = returningKeys.length;

  const total = Math.min(curTop.size, 10);
  const score = total ? Math.round(returning / total * 100) : 0;
  const label = score >= 80 ? t('st_loyalty_die_hard') : score >= 60 ? t('st_loyalty_loyal') : score >= 40 ? t('st_loyalty_mixed') : t('st_loyalty_explorer');

  // Original-cased display name for each lowercased artist key
  const nameByKey = {};
  for (const p of plays) { const ak = p.artist.toLowerCase(); if (!nameByKey[ak]) nameByKey[ak] = p.artist; }

  // For each returning artist: this period's top 5 songs with play counts
  const returningArtists = returningKeys
    .sort((a, b) => curCounts[b] - curCounts[a])
    .map(ak => {
      const name = nameByKey[ak] || ak;
      const songCounts = {};
      for (const p of plays) {
        if (p.artist.toLowerCase() !== ak) continue;
        const sk = songKey(p);
        if (!songCounts[sk]) songCounts[sk] = { title: p.title, count: 0 };
        songCounts[sk].count++;
      }
      const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 5);
      return { name, plays: curCounts[ak], topSongs };
    });

  el.innerHTML = `
    <div class="st-loyalty-score">
      <div class="st-loyalty-ring" style="--pct:${score}">
        <div class="st-loyalty-pct">${score}<span class="st-loyalty-pct-sign">%</span></div>
      </div>
      <div class="st-loyalty-text">
        <div class="st-loyalty-verdict">${label}</div>
        <div class="st-loyalty-sub">${t('st_loyalty_sub', { n: returning, year: prevYear })}</div>
        <div class="st-loyalty-tally" aria-hidden="true">
          ${Array.from({ length: total }, (_, i) => `<span class="st-loyalty-dot${i < returning ? ' is-on' : ''}"></span>`).join('')}
        </div>
      </div>
    </div>
    ${returningArtists.length ? `
    <div class="st-loyalty-artists-title">${t('st_loyalty_artists_title')}</div>
    <div class="st-loyalty-artists">
      ${returningArtists.map((a, i) => `
        <div class="st-loyalty-artist" style="--i:${i}">
          <div class="st-loyalty-artist-badge" aria-hidden="true">↻</div>
          <div class="st-loyalty-artist-head">
            <div class="st-loyalty-artist-avatar" id="stLoyaltyImg${i}"></div>
            <div class="st-loyalty-artist-meta">
              <div class="st-loyalty-artist-name">${esc(a.name)}</div>
              <div class="st-loyalty-artist-plays">${a.plays.toLocaleString()} ${tUnit('plays', a.plays)}</div>
            </div>
          </div>
          <div class="st-loyalty-artist-songs">
            ${a.topSongs.map((s, j) => `<div class="st-loyalty-song"><span class="st-loyalty-song-idx">${j + 1}</span><span class="st-loyalty-song-title">${esc(s.title)}</span><span class="st-loyalty-song-count">${s.count.toLocaleString()}</span></div>`).join('')}
          </div>
        </div>`).join('')}
    </div>` : ''}`;

  // Queued through the shared imgQueue (same one the chart tables and coverflow
  // use) instead of firing all requests at once — a synchronous burst against
  // the Deezer proxy gets rate-limited, silently downgrading art to lower-res
  // itunes/lastfm fallbacks.
  returningArtists.forEach((a, i) => {
    imgQueue = imgQueue.then(() => getArtistImage(a.name, 'deezer').then(url => {
      const imgEl = document.getElementById('stLoyaltyImg' + i);
      if (imgEl) imgEl.innerHTML = thumbHtml(url, a.name, false);
    }));
  });
}

// ── New Discoveries ───────────────────────────────────────────
function stRenderDiscoveries(plays) {
  const el = document.getElementById('stDiscoveriesBody');
  if (!el) return;
  const fsMap = stGetFirstSeenArtists();
  const discovered = [];
  const seen = new Set();

  // Each comma-split artist is its own discovery (honoring the hardwired
  // exceptions in splitArtists), not the raw "Artist A, Artist B" credit.
  for (const p of plays) {
    for (const artist of (p.artists || splitArtists(p.artist))) {
      if (seen.has(artist)) continue;
      seen.add(artist);
      const fd = fsMap[artist];
      if (!fd) continue;
      const ftz = tzDate(fd);
      const inPeriod = stPeriodType === 'alltime' ? true :
        stPeriodType === 'year' ? ftz.getFullYear() === stYear :
        ftz.getFullYear() === stYear && (ftz.getMonth() + 1) === stMonth;
      if (inPeriod) discovered.push({ artist, date: fd });
    }
  }

  discovered.sort((a, b) => a.date - b.date);

  if (!discovered.length) {
    el.innerHTML = `<div class="st-empty">${t('st_discoveries_none')}</div>`;
    return;
  }

  // Weight the top 20% of discoveries by this period's play count so their
  // bubbles reappear more often in the animated loop than the rest.
  const playCountByArtist = {};
  for (const p of plays) {
    for (const artist of (p.artists || splitArtists(p.artist))) {
      playCountByArtist[artist] = (playCountByArtist[artist] || 0) + 1;
    }
  }
  discovered.forEach(d => { d.count = playCountByArtist[d.artist] || 0; });
  const topCutoff = Math.max(1, Math.round(discovered.length * 0.2));
  const featuredSet = new Set([...discovered].sort((a, b) => b.count - a.count).slice(0, topCutoff).map(d => d.artist));
  discovered.forEach(d => { d.weight = featuredSet.has(d.artist) ? 3 : 1; });

  el.innerHTML = `
    <div class="st-discoveries-count">${t('st_discoveries_count', { n: discovered.length })}</div>
    <div class="st-bubbles" id="stDiscoveriesBubbles"></div>`;

  stStartBubbles(discovered);
}

// ── Discoveries "bubble tank" — floating artist portraits that rise,
// fade out at the top, and get recycled so the whole discovered list
// (not just the first dozen) keeps cycling through for as long as the
// section stays on screen. ──────────────────────────────────────────
function stShuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Repeats each item `weight` times (default 1) before shuffling, so a
// weighted item comes up proportionally more often over one full cycle
// of the deck — used to make top-played discoveries reappear more.
function stBuildWeightedDeck(items) {
  const deck = [];
  for (const item of items) {
    const w = item.weight || 1;
    for (let i = 0; i < w; i++) deck.push(item);
  }
  return stShuffle(deck);
}

function stSpawnBubble(container, artist, isStatic) {
  const uid = 'stBubble' + (_stBubbleUid++);
  const size = 64 + Math.floor(Math.random() * 40);   // 64–104px, for a bit of depth variety
  const dur = (13 + Math.random() * 6).toFixed(1);     // 13–19s rise
  const drift = Math.round(Math.random() * 50 - 25);   // -25..25px sideways sway
  const x = (5 + Math.random() * 90).toFixed(1);       // keep clear of the edges

  const bubble = document.createElement('div');
  bubble.className = 'st-bubble';
  bubble.style.setProperty('--size', size + 'px');
  bubble.style.setProperty('--x', x + '%');
  bubble.style.setProperty('--drift', drift + 'px');
  bubble.style.setProperty('--dur', dur + 's');
  bubble.setAttribute('role', 'button');
  bubble.setAttribute('tabindex', '0');
  bubble.setAttribute('aria-label', artist);
  bubble.innerHTML = `<div class="st-bubble-avatar" id="${uid}"></div><div class="st-bubble-name">${esc(artist)}</div>`;
  container.appendChild(bubble);

  if (!isStatic) bubble.addEventListener('animationend', () => bubble.remove());

  bubble.addEventListener('click', () => stPopBubble(bubble, artist));
  bubble.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); stPopBubble(bubble, artist); }
  });

  // Queued through the shared imgQueue (see stLoyaltyImg above) — under
  // prefers-reduced-motion the initial static batch spawns up to 10 bubbles
  // in one synchronous forEach, which would otherwise fire 10 concurrent
  // Deezer lookups at once.
  imgQueue = imgQueue.then(() => getArtistImage(artist, 'deezer').then(url => {
    const avatarEl = document.getElementById(uid);
    if (avatarEl) avatarEl.innerHTML = thumbHtml(url, artist, false);
  }));
}

// Tapping/clicking a bubble "pops" it (a quick scale-and-ring burst, skipped
// under prefers-reduced-motion) and opens the artist detail modal, scoped to
// whatever period is currently rendered (_stCurrentPlays) — a discovery and
// its stats should describe the same window.
function stPopBubble(bubble, artist) {
  if (bubble.dataset.popped) return;
  bubble.dataset.popped = '1';
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion) {
    bubble.remove();
    stOpenArtistModal(artist);
    return;
  }
  bubble.classList.add('st-bubble-pop');
  setTimeout(() => bubble.remove(), 450);
  setTimeout(() => stOpenArtistModal(artist), 200);
}

function stOpenArtistModal(artist) {
  const modal = document.getElementById('stArtistModal');
  if (!modal) return;

  const artistPlays = _stCurrentPlays.filter(p => (p.artists || splitArtists(p.artist)).includes(artist));
  const totalPlays = artistPlays.length;

  const songCounts = {};
  for (const p of artistPlays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 10);

  const albumCounts = {};
  for (const p of artistPlays) {
    if (!p.album || p.album === '—') continue;
    if (!albumCounts[p.album]) albumCounts[p.album] = { album: p.album, count: 0 };
    albumCounts[p.album].count++;
  }
  const topAlbums = Object.values(albumCounts).sort((a, b) => b.count - a.count);

  const dayCounts = {};
  for (const p of artistPlays) {
    const dk = dayStrOf(p);
    dayCounts[dk] = (dayCounts[dk] || 0) + 1;
  }
  const days = Object.keys(dayCounts).sort();
  const activeDays = days.length;
  let longestStreak = days.length ? 1 : 0, curStreak = 1;
  for (let i = 1; i < days.length; i++) {
    const diff = Math.round((new Date(days[i]) - new Date(days[i - 1])) / 86400000);
    curStreak = diff === 1 ? curStreak + 1 : 1;
    if (curStreak > longestStreak) longestStreak = curStreak;
  }
  let peakDay = null;
  for (const dk of days) { if (!peakDay || dayCounts[dk] > dayCounts[peakDay]) peakDay = dk; }

  const discoveredDs = artistPlays.length ? localDateStr(tzDate(new Date(Math.min(...artistPlays.map(p => +p.date))))) : null;

  // Rank among all artists this period (individual, comma-split — same rule New Discoveries uses)
  const periodArtistCounts = {};
  for (const p of _stCurrentPlays) {
    for (const a of (p.artists || splitArtists(p.artist))) periodArtistCounts[a] = (periodArtistCounts[a] || 0) + 1;
  }
  const rank = Object.entries(periodArtistCounts).sort((a, b) => b[1] - a[1]).findIndex(([a]) => a === artist) + 1;

  document.getElementById('stArtistModalName').textContent = artist;
  document.getElementById('stArtistModalSub').textContent = `${t('st_discoveries_title')} · ${stGetPeriodLabel()}`;

  const avatarEl = document.getElementById('stArtistModalAvatar');
  const cachedImg = imgCache['artist:' + artist.toLowerCase() + ':deezer'];
  avatarEl.innerHTML = cachedImg ? thumbHtml(cachedImg, artist, false) : `<div class="thumb-initials">${esc(initials(artist))}</div>`;
  if (!cachedImg) {
    getArtistImage(artist, 'deezer').then(url => {
      if (document.getElementById('stArtistModalName')?.textContent === artist) avatarEl.innerHTML = thumbHtml(url, artist, false);
    });
  }

  const fmtDay = ds => new Date(ds + 'T12:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric' });

  const body = document.getElementById('stArtistModalBody');
  body.innerHTML = `
    <div class="modal-stats-strip">
      <div class="modal-stat"><div class="se">▶</div><div class="sv" data-countup="${totalPlays}">${totalPlays.toLocaleString()}</div><div class="sl">${t('stat_total_plays')}</div></div>
      <div class="modal-stat"><div class="se">🔥</div><div class="sv" data-countup="${longestStreak}">${longestStreak}</div><div class="sl">${t('modal_listening_days_streak')}</div></div>
      <div class="modal-stat"><div class="se">📅</div><div class="sv" data-countup="${activeDays}">${activeDays}</div><div class="sl">${t('modal_calendar_days_played')}</div></div>
      <div class="modal-stat"><div class="se">💿</div><div class="sv" data-countup="${topAlbums.length}">${topAlbums.length}</div><div class="sl">${t('st_bubble_albums_title')}</div></div>
      <div class="modal-stat"><div class="se">🏔️</div><div class="sv" style="font-size:1.05rem">${peakDay ? fmtDay(peakDay) : '—'}</div><div class="sl">${t('st_stat_peak_day')}</div></div>
      <div class="modal-stat"><div class="se">✨</div><div class="sv" style="font-size:1.05rem">${discoveredDs ? fmtDay(discoveredDs) : '—'}</div><div class="sl">${t('st_bubble_discovered')}</div></div>
      ${rank > 0 ? `<div class="modal-stat${rank <= 3 ? ' modal-stat--gold' : ''}"><div class="se">🏆</div><div class="sv${rank <= 3 ? ' sv--gold' : ''}">#${rank}</div><div class="sl">${t('st_bubble_rank')}</div></div>` : ''}
    </div>

    <div class="modal-section-title">${t('st_top_songs')}</div>
    <div class="st-bmodal-list">
      ${topSongs.map((s, i) => `<div class="st-bmodal-row"><span class="st-bmodal-rank">${i + 1}</span><span class="st-bmodal-title">${esc(s.title)}</span><span class="st-bmodal-count">${s.count.toLocaleString()}</span></div>`).join('')}
    </div>

    ${topAlbums.length ? `
    <div class="modal-section-title">${t('st_bubble_albums_title')}</div>
    <div class="st-bmodal-list">
      ${topAlbums.map(a => `<div class="st-bmodal-row"><span class="st-bmodal-title">${esc(a.album)}</span><span class="st-bmodal-count">${a.count.toLocaleString()} ${tUnit('plays', a.count)}</span></div>`).join('')}
    </div>` : ''}`;

  animateModalCountup(body);
  modal.classList.add('open');
}

function stCloseArtistModal() {
  document.getElementById('stArtistModal')?.classList.remove('open');
}

function stStartBubbles(discovered) {
  if (_stBubbleTimer) { clearInterval(_stBubbleTimer); _stBubbleTimer = null; }
  _stBubbleSeeds.forEach(clearTimeout);
  _stBubbleSeeds = [];
  _stBubbleQueue = [];
  if (!discovered.length) return;

  const container = document.getElementById('stDiscoveriesBubbles');
  if (!container) return;

  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion) {
    container.classList.add('st-bubbles-static');
    stShuffle(discovered).slice(0, 10).forEach(item => stSpawnBubble(container, item.artist, true));
    return;
  }
  container.classList.remove('st-bubbles-static');

  const spawn = () => {
    if (currentPeriod !== 'soundtrack') { clearInterval(_stBubbleTimer); _stBubbleTimer = null; return; }
    const live = document.getElementById('stDiscoveriesBubbles');
    if (!live) { clearInterval(_stBubbleTimer); _stBubbleTimer = null; return; }
    if (!_stBubbleQueue.length) _stBubbleQueue = stBuildWeightedDeck(discovered);
    const item = _stBubbleQueue.pop();
    stSpawnBubble(live, item.artist);
  };

  for (let i = 0; i < 5; i++) _stBubbleSeeds.push(setTimeout(spawn, i * 400));
  _stBubbleTimer = setInterval(spawn, 1400);
}

// ── Milestones ────────────────────────────────────────────────
// Two independent kinds live here and are kept in separate sections
// so they never read as one connected timeline: "overall" tracks the
// listener's own cumulative play count, while "artist" tracks each
// artist's play count independently — an artist milestone can land
// on any date and has nothing to do with the listener's own totals.
function stRenderMilestones(plays) {
  const elOverall = document.getElementById('stMilestonesBody');
  const elArtist = document.getElementById('stArtistMilestonesBody');
  if (!elOverall && !elArtist) return;

  const OVERALL_MS = [100,500,1000,2500,5000,10000, ...Array.from({ length: 40 }, (_, i) => 25000 * (i + 1))];
  const ARTIST_MS  = [100, ...Array.from({ length: 1000 }, (_, i) => 500 * (i + 1))];
  const ARTIST_MS_SET = new Set(ARTIST_MS);
  const MS_NUM_TOKEN = '##N##'; // stands in for {{n}} — swapped for a live-counting <span> at render time

  const chron = [...allPlays].sort((a, b) => a.date - b.date);
  const overallMs = [];
  const artistMs = [];
  let total = 0, nextIdx = 0;
  const artistCounts = {};

  for (const p of chron) {
    total++;
    const d = tzDateOf(p);
    const inPeriod = stPeriodType === 'alltime' ? true :
      stPeriodType === 'year' ? d.getFullYear() === stYear :
      d.getFullYear() === stYear && (d.getMonth() + 1) === stMonth;

    // Overall milestones — the listener's own cumulative play count
    while (nextIdx < OVERALL_MS.length && total >= OVERALL_MS[nextIdx]) {
      if (inPeriod) overallMs.push({ icon:'🎵', text: t('st_milestone_overall', { n: MS_NUM_TOKEN }), sub: t('st_milestone_overall_sub', { title: esc(p.title), artist: esc(p.artist) }), date: p.date, rawTitle: p.title, rawArtist: p.artist, nTarget: OVERALL_MS[nextIdx] });
      nextIdx++;
    }

    // Per-artist milestones — independent of the totals above. Each
    // comma-split credited artist counts on its own (honoring the
    // hardwired exceptions in splitArtists, e.g. "Tyler, The Creator"),
    // same rule as New Discoveries and the Top Artists coverflow.
    for (const a of (p.artists || splitArtists(p.artist))) {
      const ak = a.toLowerCase();
      artistCounts[ak] = (artistCounts[ak] || 0) + 1;
      if (inPeriod && ARTIST_MS_SET.has(artistCounts[ak])) {
        artistMs.push({ icon:'🎤', sub: t('st_milestone_artist_sub', { title: esc(p.title) }), text: t('st_milestone_artist', { n: MS_NUM_TOKEN, artist: esc(a) }), date: p.date, rawTitle: p.title, rawArtist: a, nTarget: artistCounts[ak] });
      }
    }
  }

  overallMs.sort((a, b) => a.date - b.date);
  artistMs.sort((a, b) => a.date - b.date);

  _stMilestonesVisible.overall = ST_MS_PAGE;
  _stMilestonesVisible.artist = ST_MS_PAGE;
  stRenderMilestoneList(overallMs, 'stMilestonesBody', 'stMilestonesWrap', 'stMilestonesToggle', 'overall');
  stRenderMilestoneList(artistMs, 'stArtistMilestonesBody', 'stArtistMilestonesWrap', 'stArtistMilestonesToggle', 'artist');
}

const _stMilestonesCounts = { overall: 0, artist: 0 };
const _stMilestonesItems = { overall: [], artist: [] };
const ST_MS_PAGE = 25;
const _stMilestonesVisible = { overall: ST_MS_PAGE, artist: ST_MS_PAGE };

function stRenderMilestoneList(items, bodyId, wrapId, toggleId, kind) {
  const el = document.getElementById(bodyId);
  const wrap = document.getElementById(wrapId);
  const toggle = document.getElementById(toggleId);
  if (!el) return;

  _stMilestonesItems[kind] = items;
  _stMilestonesCounts[kind] = items.length;

  if (!items.length) {
    el.innerHTML = `<div class="st-empty">${t('st_milestones_none')}</div>`;
    if (toggle) toggle.style.display = 'none';
    if (wrap) wrap.classList.remove('st-scrollable', 'st-has-more');
    return;
  }

  const visibleCount = Math.min(_stMilestonesVisible[kind], items.length);
  const visibleItems = items.slice(0, visibleCount);

  el.innerHTML = visibleItems.map((m, i) => {
    const d = tzDate(m.date);
    const ds = `${d.getDate()}/${d.getMonth()+1}/${d.getFullYear()}`;
    const typeClass = kind === 'overall' ? ' st-milestone-overall' : ' st-milestone-artist';
    const numId = `ms-num-${kind}-${i}`;
    const numSpan = `<span class="st-milestone-num" id="${numId}" data-target="${m.nTarget}">0</span>`;
    const text = m.text.replace('##N##', numSpan);
    return `<div class="st-milestone${typeClass}" data-idx="${i}" style="--i:${i}">
      <span class="st-milestone-icon">${m.icon}</span>
      <span class="st-milestone-art-wrap" data-idx="${i}"></span>
      <div class="st-milestone-info">
        <div class="st-milestone-text">${text}</div>
        <div class="st-milestone-sub">${m.sub}</div>
      </div>
      <div class="st-milestone-date">${ds}</div>
    </div>`;
  }).join('');

  visibleItems.forEach((m, i) => {
    const rowEl = el.querySelector(`.st-milestone[data-idx="${i}"]`);
    if (!rowEl) return;

    // Fill in the row's art thumbnail with the triggering track's cover
    // art, once fetched — stays hidden (icon badge only) if art fails.
    // Queued (see stLoyaltyImg above) so a page of milestones doesn't fire
    // all its lookups in the same instant. Deezer alone misses plenty of
    // tracks, so walk the same itunes/lastfm/youtube fallback chain the
    // coverflow uses instead of giving up after one source.
    if (m.rawTitle) {
      const MS_ART_SOURCES = ['deezer', 'itunes', 'lastfm', 'youtube'];
      imgQueue = imgQueue.then(async () => {
        let url = null;
        for (const source of MS_ART_SOURCES) {
          try { url = await getTrackImage(m.rawTitle, m.rawArtist, source); } catch (e) { url = null; }
          if (url) break;
        }
        if (!url) return;
        const artWrapEl = rowEl.querySelector('.st-milestone-art-wrap');
        if (artWrapEl && !artWrapEl.querySelector('.st-milestone-art')) {
          artWrapEl.classList.add('st-has-art');
          artWrapEl.insertAdjacentHTML('beforeend', `<img class="st-milestone-art" src="${esc(url)}" alt="" loading="lazy" onerror="this.parentElement.classList.remove('st-has-art');this.remove()">`);
        }
      });
    }

    // Tap a row to open the same mini-card the Top Artists/Songs
    // coverflow opens on center-tap — the artist card for artist
    // milestones, the song card for overall (track-triggered) ones.
    rowEl.classList.add('st-milestone-tappable');
    rowEl.addEventListener('click', () => {
      if (kind === 'artist') stOpenArtistModal(m.rawArtist);
      else if (m.rawTitle) openSongModal(songKey({ title: m.rawTitle, artist: m.rawArtist }));
    });
  });

  // Count up each row's play-count number with a little pop the first
  // time it scrolls into view, instead of just appearing pre-filled.
  const numEls = Array.from(el.querySelectorAll('.st-milestone-num'));
  if (!('IntersectionObserver' in window)) {
    numEls.forEach(n => { n.textContent = (+n.dataset.target).toLocaleString(); });
  } else {
    const numObs = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        if (!e.isIntersecting) return;
        numObs.unobserve(e.target);
        e.target.classList.add('st-pop');
        stCountUp(e.target.id, +e.target.dataset.target);
      });
    }, { threshold: 0.4 });
    numEls.forEach(n => numObs.observe(n));
  }

  // Long lists live in a fixed-height scroll box so the page doesn't
  // open with a wall of rows, and only a page of ST_MS_PAGE items is
  // ever in the DOM at once; a button below loads the next page in.
  const needsScroll = items.length > 8;
  const remaining = items.length - visibleCount;
  if (wrap) {
    wrap.classList.toggle('st-scrollable', needsScroll);
    wrap.classList.toggle('st-has-more', needsScroll && remaining > 0);
  }
  if (toggle) {
    if (remaining > 0) {
      toggle.style.display = '';
      toggle.textContent = t('st_milestones_show_more', { n: Math.min(ST_MS_PAGE, remaining), total: items.length });
    } else if (items.length > ST_MS_PAGE) {
      toggle.style.display = '';
      toggle.textContent = t('st_milestones_show_less');
    } else {
      toggle.style.display = 'none';
    }
  }
}

function stToggleMilestones(kind) {
  kind = kind || 'overall';
  const bodyId = kind === 'artist' ? 'stArtistMilestonesBody' : 'stMilestonesBody';
  const wrapId = kind === 'artist' ? 'stArtistMilestonesWrap' : 'stMilestonesWrap';
  const toggleId = kind === 'artist' ? 'stArtistMilestonesToggle' : 'stMilestonesToggle';
  const items = _stMilestonesItems[kind] || [];
  const total = items.length;
  if (!total) return;

  const collapsing = _stMilestonesVisible[kind] >= total;
  _stMilestonesVisible[kind] = collapsing ? ST_MS_PAGE : Math.min(_stMilestonesVisible[kind] + ST_MS_PAGE, total);
  stRenderMilestoneList(items, bodyId, wrapId, toggleId, kind);

  const wrap = document.getElementById(wrapId);
  if (wrap && collapsing) { wrap.scrollTop = 0; wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
}

// ── Streaks ───────────────────────────────────────────────────
function stRenderStreaks(plays) {
  const el = document.getElementById('stStreaksBody');
  if (!el) return;
  if (!plays.length) { el.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`; return; }

  const pad2 = n => String(n).padStart(2, '0');
  const dayKey = d => { const tz = tzDate(d); return `${tz.getFullYear()}-${pad2(tz.getMonth()+1)}-${pad2(tz.getDate())}`; };
  const fmtDay = ds => { const d = new Date(ds); return `${d.getDate()}/${d.getMonth()+1}/${d.getFullYear()}`; };
  // Pure UTC decrement on the calendar string — avoids mixing a UTC-parsed
  // Date with local setDate()/getDate(), which silently skips a day in
  // negative-UTC-offset timezones and undercounts the walk below.
  const prevDayKey = ds => { const d = new Date(ds + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() - 1); return d.toISOString().slice(0, 10); };

  const allDaySet = new Set(allPlays.map(p => dayKey(p.date)));
  const allDays = [...allDaySet].sort();

  // Longest all-time streak
  let longestAll = allDays.length ? 1 : 0, curAll = 1, longestStart = allDays[0] || '', longestEnd = allDays[0] || '', curStart = allDays[0] || '';
  for (let i = 1; i < allDays.length; i++) {
    const diff = Math.round((new Date(allDays[i]) - new Date(allDays[i-1])) / 86400000);
    if (diff === 1) {
      curAll++;
    } else {
      if (curAll > longestAll) { longestAll = curAll; longestStart = curStart; longestEnd = allDays[i-1]; }
      curAll = 1; curStart = allDays[i];
    }
  }
  if (curAll > longestAll) { longestAll = curAll; longestStart = curStart; longestEnd = allDays[allDays.length-1]; }

  // Current streak (today or yesterday)
  const now = tzNow();
  const todayKey = `${now.getFullYear()}-${pad2(now.getMonth()+1)}-${pad2(now.getDate())}`;
  const yd = new Date(now); yd.setDate(yd.getDate() - 1);
  const yestKey = `${yd.getFullYear()}-${pad2(yd.getMonth()+1)}-${pad2(yd.getDate())}`;
  let currentStreak = 0, currentStreakStart = '';
  const anchorDay = allDaySet.has(todayKey) ? todayKey : (allDaySet.has(yestKey) ? yestKey : null);
  if (anchorDay) {
    let day = anchorDay;
    while (allDaySet.has(day)) {
      currentStreak++;
      currentStreakStart = day;
      day = prevDayKey(day);
    }
  }

  // A live streak that has reached or passed the historical best IS the new
  // record — fold it in rather than showing two contradictory numbers.
  const isNewRecord = currentStreak > 0 && currentStreak >= longestAll;
  if (isNewRecord) { longestAll = currentStreak; longestStart = currentStreakStart; longestEnd = anchorDay; }

  // Longest streak in period
  const periodDays = [...new Set(plays.map(p => dayKey(p.date)))].sort();
  let longestPeriod = periodDays.length ? 1 : 0, curPeriod = 1, periodStart = periodDays[0] || '', periodEnd = periodDays[0] || '', curPeriodStart = periodDays[0] || '';
  for (let i = 1; i < periodDays.length; i++) {
    const diff = Math.round((new Date(periodDays[i]) - new Date(periodDays[i-1])) / 86400000);
    if (diff === 1) {
      curPeriod++;
    } else {
      if (curPeriod > longestPeriod) { longestPeriod = curPeriod; periodStart = curPeriodStart; periodEnd = periodDays[i-1]; }
      curPeriod = 1; curPeriodStart = periodDays[i];
    }
  }
  if (curPeriod > longestPeriod) { longestPeriod = curPeriod; periodStart = curPeriodStart; periodEnd = periodDays[periodDays.length-1]; }

  // Active days coverage — recap-oriented replacement for the live "current
  // streak" counter, which doesn't belong in a retrospective summary. Denominator
  // is days elapsed so far for the current year/month, or the full length once past.
  const isCurrentYear = stPeriodType === 'year' && stYear === now.getFullYear();
  const isCurrentMonth = stPeriodType === 'month' && stYear === now.getFullYear() && stMonth === now.getMonth() + 1;
  let totalDaysInPeriod;
  if (stPeriodType === 'alltime') {
    totalDaysInPeriod = periodDays.length
      ? Math.round((new Date(periodDays[periodDays.length - 1]) - new Date(periodDays[0])) / 86400000) + 1
      : 0;
  } else if (stPeriodType === 'year') {
    totalDaysInPeriod = isCurrentYear
      ? Math.round((now - new Date(stYear, 0, 1)) / 86400000) + 1
      : (new Date(stYear, 1, 29).getMonth() === 1 ? 366 : 365);
  } else {
    totalDaysInPeriod = isCurrentMonth ? now.getDate() : new Date(stYear, stMonth, 0).getDate();
  }
  const activeDays = periodDays.length;
  const activeDaysPct = totalDaysInPeriod ? Math.round((activeDays / totalDaysInPeriod) * 100) : 0;

  // Longest streak reached by a single artist / album / song within the
  // current view (year, month, or all-time — whatever `plays` is scoped to).
  function bestEntityStreak(entryFn) {
    const map = {};
    for (const p of plays) {
      const dk = dayKey(p.date);
      for (const e of entryFn(p)) {
        let rec = map[e.key];
        if (!rec) rec = map[e.key] = { label: e.label, sub: e.sub, album: e.album, days: new Set() };
        rec.days.add(dk);
      }
    }
    let best = null;
    for (const rec of Object.values(map)) {
      const sorted = [...rec.days].sort();
      let mx = 1, cur = 1, mxStart = sorted[0], mxEnd = sorted[0], curStart2 = sorted[0];
      for (let i = 1; i < sorted.length; i++) {
        const diff = Math.round((new Date(sorted[i]) - new Date(sorted[i-1])) / 86400000);
        if (diff === 1) { cur++; } else { if (cur > mx) { mx = cur; mxStart = curStart2; mxEnd = sorted[i-1]; } cur = 1; curStart2 = sorted[i]; }
      }
      if (cur > mx) { mx = cur; mxStart = curStart2; mxEnd = sorted[sorted.length - 1]; }
      if (mx >= 2 && (!best || mx > best.count)) best = { label: rec.label, sub: rec.sub, album: rec.album, count: mx, start: mxStart, end: mxEnd };
    }
    return best;
  }

  const bestArtist = bestEntityStreak(p => {
    const arts = (p.artists && p.artists.length) ? p.artists : [p.artist];
    return arts.map(a => ({ key: 'a:' + a, label: a }));
  });
  const bestAlbum = bestEntityStreak(p => {
    if (!p.album || p.album === '—') return [];
    const ar = albumArtist(p);
    return [{ key: 'al:' + ar + '|||' + p.album, label: p.album, sub: ar }];
  });
  const bestSong = bestEntityStreak(p => ([{
    key: songKey(p), label: p.title, sub: p.artist,
    album: (p.album && p.album !== '—') ? p.album : null,
  }]));

  // Art-backed entity cards — an <img> layer fades in over an icon/initials
  // fallback once the async lookup below resolves, matching the lazy-art
  // pattern used by the main streak banner (_fetchStreakArt/_fetchPlayArt).
  const entityCard = (kind, icon, labelKey, best) => {
    if (!best) return '';
    const subject = best.sub ? `${esc(best.label)} · ${esc(best.sub)}` : esc(best.label);
    const fallback = initials(best.label);
    return `<div class="st-streak-card st-streak-card--entity">
        <img id="stStreakArt_${kind}" class="st-streak-entity-bg" src="" alt=""
             onload="this.classList.add('loaded')">
        <div class="st-streak-entity-fallback">${esc(fallback)}</div>
        <div class="st-streak-entity-overlay">
          <div class="st-streak-num-row">
            <span class="st-streak-num">${best.count}</span>
            <span class="st-streak-entity-unit">${t('st_streak_days_unit')} 🔥</span>
          </div>
          <div class="st-streak-subject" title="${subject}">${icon} ${subject}</div>
          <div class="st-streak-lbl">${t(labelKey)}</div>
          <div class="st-streak-dates">${fmtDay(best.start)} – ${fmtDay(best.end)}</div>
        </div>
      </div>`;
  };
  const entityCardsHtml = entityCard('artist', '🎤', 'st_streak_artist', bestArtist)
    + entityCard('album', '💿', 'st_streak_album', bestAlbum)
    + entityCard('song', '🔂', 'st_streak_song', bestSong);

  el.innerHTML = `
    <div class="st-streaks-grid">
      <div class="st-streak-card">
        <div class="st-streak-num-stack">
          <span class="st-streak-num">${activeDays}</span>
          <span class="st-streak-unit">${t('st_streak_days_streamed_unit')}</span>
        </div>
        <div class="st-streak-lbl">${t('st_streak_active_days')}</div>
        <div class="st-streak-dates">${t('st_streak_active_days_sub', { pct: activeDaysPct, total: totalDaysInPeriod })}</div>
      </div>
      <div class="st-streak-card${isNewRecord ? ' st-streak-card--record' : ''}">
        <div class="st-streak-num-stack">
          <span class="st-streak-num">${longestAll}</span>
          <span class="st-streak-unit">${t('st_streak_days_unit')} 🔥</span>
        </div>
        <div class="st-streak-lbl">${t('st_streak_longest')}</div>
        ${longestStart ? `<div class="st-streak-dates">${fmtDay(longestStart)} – ${fmtDay(longestEnd)}</div>` : ''}
        ${isNewRecord ? `<div class="st-streak-badge">${t('st_streak_new_record')}</div>` : ''}
      </div>
      ${stPeriodType !== 'alltime' ? `<div class="st-streak-card">
        <div class="st-streak-num-stack">
          <span class="st-streak-num">${longestPeriod}</span>
          <span class="st-streak-unit">${t('st_streak_days_unit')} 🔥</span>
        </div>
        <div class="st-streak-lbl">${t('st_streak_in_period', { period: stGetPeriodLabel() })}</div>
        ${periodStart ? `<div class="st-streak-dates">${fmtDay(periodStart)} – ${fmtDay(periodEnd)}</div>` : ''}
      </div>` : ''}
    </div>
    ${entityCardsHtml ? `
    <div class="st-streak-subhead">${t('st_streak_category_title', { period: stGetPeriodLabel() })}</div>
    <div class="st-streaks-grid st-streaks-grid--entity">${entityCardsHtml}</div>` : ''}`;

  [['artist', bestArtist], ['album', bestAlbum], ['song', bestSong]].forEach(([kind, best]) => {
    if (!best) return;
    _fetchEntityStreakArt(kind, best).then(url => {
      if (!url) return;
      const img = document.getElementById('stStreakArt_' + kind);
      if (img) img.src = url;
    });
  });
}

async function _fetchEntityStreakArt(kind, best) {
  try {
    if (kind === 'artist') return await getArtistImage(best.label);
    if (kind === 'album')  return await getAlbumImage(best.label, best.sub);
    if (kind === 'song')   return best.album ? await getAlbumImage(best.album, best.sub) : await getTrackImage(best.label, best.sub);
  } catch (e) { return null; }
}

// ── Grammy Overlay ────────────────────────────────────────────
function stRenderGrammys(plays) {
  const el = document.getElementById('stGrammysBody');
  if (!el) return;
  if (!plays.length) { el.innerHTML = ''; return; }

  const artistCounts = {};
  for (const p of plays) artistCounts[p.artist.toLowerCase()] = (artistCounts[p.artist.toLowerCase()] || 0) + 1;
  const topArtistKeys = Object.entries(artistCounts).sort((a, b) => b[1] - a[1]).slice(0, 20).map(([a]) => a);

  // Build Grammy map from _awardsYearData (user's own My Grammys picks across all loaded years)
  const grammyMap = {};
  if (typeof _awardsYearData !== 'undefined') {
    for (const [yr, data] of Object.entries(_awardsYearData)) {
      if (!data || !data.categories) continue;
      for (const [catId, cat] of Object.entries(data.categories)) {
        if (!cat.winner || !cat.winner.artist) continue;
        const ak = cat.winner.artist.toLowerCase();
        if (!grammyMap[ak]) grammyMap[ak] = [];
        grammyMap[ak].push({ year: yr, category: AWARD_CATEGORIES.find(c => c.id === catId)?.label || catId, isWin: true });
      }
    }
  }

  const withAwards = topArtistKeys
    .filter(ak => grammyMap[ak] && grammyMap[ak].length > 0)
    .map(ak => ({
      artist: plays.find(p => p.artist.toLowerCase() === ak)?.artist || ak,
      plays: artistCounts[ak],
      entries: grammyMap[ak]
    }));

  if (!withAwards.length) {
    el.innerHTML = `<div class="st-empty">${t('st_grammys_none')}</div>`;
    return;
  }

  const shown = withAwards.slice(0, 8);
  el.innerHTML = `<div class="st-grammy-grid">${shown.map((item, i) => {
    const wins = item.entries.filter(e => e.isWin).length;
    const sorted = [...item.entries].sort((a, b) => b.year - a.year);
    return `<div class="st-grammy-card" style="--i:${i}" onclick="stToggleGrammyCard(this)">
      <div class="st-grammy-card-photo">
        <img id="stGrammyArt_${i}" class="st-grammy-card-bg" src="" alt="" onload="this.classList.add('loaded')">
        <div class="st-grammy-card-fallback">${esc(initials(item.artist))}</div>
        <div class="st-grammy-ribbon">🏆 ${wins} ${wins === 1 ? t('st_grammy_win') : t('st_grammy_wins')}</div>
        <div class="st-grammy-card-overlay">
          <div class="st-grammy-card-artist" title="${esc(item.artist)}">${esc(item.artist)}</div>
          <div class="st-grammy-card-plays">${item.plays.toLocaleString()} ${tUnit('plays', item.plays)}</div>
        </div>
        <div class="st-grammy-card-chevron">▾</div>
      </div>
      <div class="st-grammy-detail">${sorted.map(e => `<div class="st-grammy-detail-row">
        <span class="st-grammy-detail-year">${esc(String(e.year))}</span>
        <span class="st-grammy-detail-cat">${esc(e.category)}</span>
      </div>`).join('')}</div>
    </div>`;
  }).join('')}</div>`;

  // Queued through the shared imgQueue (see stLoyaltyImg above) instead of
  // firing every card's lookup at once.
  shown.forEach((item, i) => {
    imgQueue = imgQueue.then(() => getArtistImage(item.artist).then(url => {
      if (!url) return;
      const img = document.getElementById('stGrammyArt_' + i);
      if (img) img.src = url;
    }));
  });
}

function stToggleGrammyCard(card) {
  const wasOpen = card.classList.contains('st-grammy-card--open');
  card.parentElement.querySelectorAll('.st-grammy-card--open').forEach(c => { if (c !== card) c.classList.remove('st-grammy-card--open'); });
  card.classList.toggle('st-grammy-card--open', !wasOpen);
}

// ── Underrated Gem (Last.fm only) ─────────────────────────────
function stRenderGem(plays) {
  const gemSection = document.getElementById('stGemSection');
  if (!gemSection) return;
  const source = localStorage.getItem('dc_source') || '';
  if (source !== 'lastfm') { gemSection.style.display = 'none'; return; }
  gemSection.style.display = '';
  const el = document.getElementById('stGemBody');
  if (!plays.length) { el.innerHTML = ''; return; }

  const apiKey = localStorage.getItem('dc_lfm_api_key') || '';
  if (!apiKey) { gemSection.style.display = 'none'; return; }

  const songCounts = {};
  for (const p of plays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, artist: p.artist, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 8);

  el.innerHTML = `<div class="st-gem-loading">${t('st_gem_loading')}</div>`;

  const fetches = topSongs.slice(0, 5).map(s =>
    fetch(`https://ws.audioscrobbler.com/2.0/?method=track.getInfo&api_key=${encodeURIComponent(apiKey)}&artist=${encodeURIComponent(s.artist)}&track=${encodeURIComponent(s.title)}&format=json`)
      .then(r => r.json())
      .then(d => ({ ...s, listeners: parseInt(d?.track?.listeners || '0') || 0 }))
      .catch(() => ({ ...s, listeners: 0 }))
  );

  Promise.all(fetches).then(results => {
    const valid = results.filter(s => s.listeners > 100);
    if (!valid.length) { gemSection.style.display = 'none'; return; }
    valid.sort((a, b) => (b.count / Math.log(b.listeners + 1)) - (a.count / Math.log(a.listeners + 1)));
    const gem = valid[0];
    el.innerHTML = `
      <div class="st-gem-card">
        <div class="st-gem-icon">💎</div>
        <div class="st-gem-info">
          <div class="st-gem-title">${esc(gem.title)}</div>
          <div class="st-gem-artist">${esc(gem.artist)}</div>
          <div class="st-gem-stats">
            <span>${t('st_gem_your_plays', { n: gem.count.toLocaleString() })}</span>
            <span class="st-gem-sep">·</span>
            <span>${t('st_gem_listeners', { n: gem.listeners.toLocaleString() })}</span>
          </div>
          <div class="st-gem-sub">${t('st_gem_sub')}</div>
        </div>
      </div>`;
  });
}

// ── Chart History Replay — "on-air countdown" broadcast ─────────
// Spells out the month like "July 19th" instead of "19/7" — English gets an
// ordinal suffix (native convention); other locales use Intl's own month/day
// ordering ("19 de julio") since ordinal date suffixes aren't idiomatic there.
function stReplayFormatWeekDate(dateObj) {
  const locale = currentLang === 'en' ? 'en-US' : currentLang;
  if (locale.startsWith('en')) {
    const month = dateObj.toLocaleDateString(locale, { month: 'long' });
    const day = dateObj.getDate();
    const suffix = (day % 10 === 1 && day !== 11) ? 'st'
      : (day % 10 === 2 && day !== 12) ? 'nd'
      : (day % 10 === 3 && day !== 13) ? 'rd' : 'th';
    return `${month} ${day}${suffix}`;
  }
  return dateObj.toLocaleDateString(locale, { month: 'long', day: 'numeric' });
}

// Movement badges compare each week's cumulative top5 against the previous
// week's so the replay reads like a real countdown-show rundown (▲/▼/NEW/—).
function stReplayMovementInfo(name, i, prevTop5) {
  if (!prevTop5) return { cls: '', text: '' };
  const prevIdx = prevTop5.findIndex(([n]) => n === name);
  if (prevIdx === -1) return { cls: 'st-replay-move-new', text: t('st_replay_new') };
  if (prevIdx === i) return { cls: 'st-replay-move-same', text: '—' };
  const diff = Math.abs(prevIdx - i);
  return prevIdx > i ? { cls: 'st-replay-move-up', text: '▲' + diff } : { cls: 'st-replay-move-down', text: '▼' + diff };
}

// FLIP-reorders the row elements from the previous week's positions to this
// week's, same technique as the main chart's sliding-window bar-race animation
// (runSlideWindowAnim above) — rows are kept and moved/resized rather than
// wiped and redrawn, so entries visibly slide/grow instead of flashing.
function stReplayRenderRows(rowsEl, snap, prevTop5) {
  const newTop5 = snap.top5;
  const newKeys = new Set(newTop5.map(([name]) => name));
  const existingMap = new Map();
  for (const child of Array.from(rowsEl.children)) existingMap.set(child.dataset.artist, child);

  // FLIP read-1: freeze transitions, measure current positions of rows that survive
  const firstTops = new Map();
  for (const [key, el] of existingMap) {
    if (newKeys.has(key)) {
      el.style.transition = 'none';
      el.style.transform = '';
      firstTops.set(el, el.getBoundingClientRect().top);
    }
  }

  // Rows that fell out of the top5 fade out and get removed
  for (const [key, el] of existingMap) {
    if (!newKeys.has(key)) {
      el.style.transition = 'opacity 250ms ease, transform 250ms ease';
      el.style.transform = 'translateY(6px)';
      el.style.opacity = '0';
      el._removeTimer = setTimeout(() => el.remove(), 260);
    }
  }

  const newlyCreated = [];
  newTop5.forEach(([name, count], i) => {
    let el = existingMap.get(name);
    const isNew = !el;
    if (!isNew && el._removeTimer) { clearTimeout(el._removeTimer); el._removeTimer = null; el.style.opacity = '1'; } // rejoined before fade-out finished
    if (isNew) {
      el = document.createElement('div');
      el.dataset.artist = name;
      el.style.opacity = '0';
      el.innerHTML = `
        <span class="st-replay-rank"></span>
        <div class="st-replay-avatar">${thumbHtml(imgCache['artist:' + name.toLowerCase() + ':deezer'], name, false)}</div>
        <div class="st-replay-bar-wrap">
          <div class="st-replay-bar" style="width:0%"></div>
          <span class="st-replay-name">${esc(name)}</span>
        </div>
        <span class="st-replay-move"></span>
        <span class="st-replay-count"></span>`;
      // Queued through the shared imgQueue (see stLoyaltyImg above) — playback
      // can introduce several new artists per step, and fast stepping through
      // history shouldn't burst the Deezer proxy.
      imgQueue = imgQueue.then(() => getArtistImage(name, 'deezer').then(url => {
        if (!el.isConnected || !url) return;
        el.querySelector('.st-replay-avatar').innerHTML = thumbHtml(url, name, false);
      }));
      newlyCreated.push(el);
    }
    el.className = 'st-replay-row' + (i === 0 ? ' st-replay-row-top' : '');
    el.querySelector('.st-replay-rank').textContent = i + 1;
    el.querySelector('.st-replay-bar').style.width = Math.round(count / _stReplayMax * 100) + '%';
    el.querySelector('.st-replay-count').textContent = count.toLocaleString();
    const info = stReplayMovementInfo(name, i, prevTop5);
    const moveEl = el.querySelector('.st-replay-move');
    moveEl.className = 'st-replay-move ' + info.cls;
    moveEl.textContent = info.text;
    rowsEl.appendChild(el); // moves existing nodes into rank order, appends new ones at the end
  });

  // FLIP read-2 + play: measure the post-reorder position, apply the inverse
  // transform so rows appear unmoved, then release it into the CSS transition.
  requestAnimationFrame(() => {
    for (const [el, top] of firstTops) {
      if (!el.isConnected) continue;
      const dy = top - el.getBoundingClientRect().top;
      if (Math.abs(dy) > 0.5) el.style.transform = `translateY(${dy}px)`;
    }
    requestAnimationFrame(() => {
      for (const [el] of firstTops) {
        if (!el.isConnected) continue;
        el.style.transition = '';
        el.style.transform = '';
      }
      for (const el of newlyCreated) { el.style.transition = ''; el.style.opacity = '1'; }
    });
  });
}

// Builds the static shell (controls + scrubber) once so the interval never
// destroys the buttons the user is trying to click — only stReplayRender's
// text/rows patch after this. Rebuilding the whole canvas every tick was the
// original bug: a click's mouseup could land on an already-detached button.
function stReplayBuildShell(canvas) {
  canvas.innerHTML = `
    <div class="st-replay-header">
      <div class="st-replay-week-label" id="stReplayWeekLabel"></div>
      <div class="st-replay-controls">
        <button class="st-replay-speed-btn" id="stReplaySpeedBtn" onclick="stReplayCycleSpeed()" title="${t('st_replay_speed_title')}"></button>
        <button class="st-replay-pause-btn" id="stReplayPauseBtn" onclick="stReplayTogglePause()" title="${t('st_replay_pause_title')}"></button>
      </div>
    </div>
    <div class="st-replay-progress" id="stReplayProgress"></div>
    <input type="range" class="st-replay-scrubber" id="stReplayScrubber" min="0" max="${_stReplaySnapshots.length - 1}" value="0"
      oninput="stReplayScrub(this.value)" aria-label="${t('st_replay_scrub_label')}">
    <div class="st-replay-rows" id="stReplayRows"></div>`;
}

function stReplayRender() {
  const canvas = document.getElementById('stReplayCanvas');
  if (!canvas || !_stReplaySnapshots.length) return;
  if (!document.getElementById('stReplayRows')) stReplayBuildShell(canvas);
  if (_stReplayIdx >= _stReplaySnapshots.length) { _stReplayIdx = _stReplaySnapshots.length - 1; }
  const snap = _stReplaySnapshots[_stReplayIdx];
  const prevTop5 = _stReplaySnapshots[_stReplayIdx - 1]?.top5 || null;
  const atEnd = _stReplayIdx === _stReplaySnapshots.length - 1;

  document.getElementById('stReplayWeekLabel').textContent = t('st_replay_week_of', { date: stReplayFormatWeekDate(snap.date), year: stYear });
  document.getElementById('stReplayProgress').textContent = t('st_replay_progress', { n: _stReplayIdx + 1, total: _stReplaySnapshots.length });
  document.getElementById('stReplaySpeedBtn').textContent = ({300:'2',600:'1',1200:'0.5'})[_stReplaySpeedMs] + '×';
  document.getElementById('stReplayPauseBtn').textContent = _stReplayPaused ? (atEnd ? '↻' : '▶') : '⏸';
  stReplayRenderRows(document.getElementById('stReplayRows'), snap, prevTop5);
  const scrubberEl = document.getElementById('stReplayScrubber');
  if (scrubberEl && document.activeElement !== scrubberEl) scrubberEl.value = _stReplayIdx;
}

function stReplayAdvance() {
  _stReplayIdx++;
  if (_stReplayIdx >= _stReplaySnapshots.length) { stReplayTogglePause(true); _stReplayIdx = _stReplaySnapshots.length - 1; return; }
  stReplayRender();
}

function stReplayStartTimer() {
  if (_stReplayTimer) clearInterval(_stReplayTimer);
  _stReplayTimer = setInterval(stReplayAdvance, _stReplaySpeedMs);
}

function stReplayTogglePause(forcePause) {
  _stReplayPaused = forcePause === true ? true : !_stReplayPaused;
  if (_stReplayPaused) {
    if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }
  } else {
    // Resuming after the countdown finished starts it over from week 1.
    if (_stReplayIdx >= _stReplaySnapshots.length - 1) _stReplayIdx = 0;
    stReplayStartTimer();
  }
  stReplayRender();
}

function stReplayCycleSpeed() {
  // Cycle 1x → 2x → 0.5x, restarting the timer at the new cadence if playing.
  _stReplaySpeedMs = _stReplaySpeedMs === 600 ? 300 : _stReplaySpeedMs === 300 ? 1200 : 600;
  if (!_stReplayPaused) stReplayStartTimer();
  stReplayRender();
}

function stReplayScrub(val) {
  // Manual scrubbing pauses auto-advance so the user can inspect any week.
  _stReplayPaused = true;
  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }
  _stReplayIdx = Math.max(0, Math.min(_stReplaySnapshots.length - 1, parseInt(val, 10) || 0));
  stReplayRender();
}

function stStartReplay() {
  if (stPeriodType !== 'year' || !allPlays.length) return;
  const replayBtn = document.getElementById('stReplayBtn');
  const replayStop = document.getElementById('stReplayStopBtn');
  const canvas = document.getElementById('stReplayCanvas');
  if (!canvas) return;

  replayBtn.style.display = 'none';
  replayStop.style.display = '';
  canvas.style.display = '';
  canvas.innerHTML = `<div class="st-replay-loading">${t('st_replay_loading')}</div>`;

  // Build weekly snapshots for the selected year
  const yearPlays = allPlays.filter(p => tzDateOf(p).getFullYear() === stYear);
  if (!yearPlays.length) { canvas.innerHTML = `<div class="st-empty">${t('st_no_data')}</div>`; return; }

  // Group by week
  const weekMap = {};
  for (const p of yearPlays) {
    const wk = playWeekKeyOf(p);
    (weekMap[wk] || (weekMap[wk] = [])).push(p);
  }
  const weeks = Object.keys(weekMap).sort();

  // Build cumulative top artist per week snapshot
  const snapshots = [];
  const runningCounts = {};
  for (const wk of weeks) {
    for (const p of weekMap[wk]) {
      runningCounts[p.artist] = (runningCounts[p.artist] || 0) + 1;
    }
    const top5 = Object.entries(runningCounts).sort((a, b) => b[1] - a[1]).slice(0, 5);
    const [wy, wm, wd] = wk.split('-').map(Number);
    snapshots.push({ week: wk, date: new Date(wy, wm - 1, wd), top5 });
  }

  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }

  _stReplaySnapshots = snapshots;
  _stReplayIdx = 0;
  _stReplayPaused = false;
  _stReplaySpeedMs = 1200;
  _stReplayMax = Math.max(...snapshots.map(s => s.top5[0]?.[1] || 0));

  stReplayRender();
  stReplayStartTimer();
}

function stStopReplay() {
  if (_stReplayTimer) { clearInterval(_stReplayTimer); _stReplayTimer = null; }
  _stReplaySnapshots = [];
  _stReplayPaused = false;
  const replayBtn = document.getElementById('stReplayBtn');
  const replayStop = document.getElementById('stReplayStopBtn');
  if (replayBtn) replayBtn.style.display = '';
  if (replayStop) replayStop.style.display = 'none';
}

// ── Shareable Card ────────────────────────────────────────────
function stOpenCard(mode) {
  _stCardMode = mode;
  const preview = document.getElementById('stCardPreview');
  const canvas = document.getElementById('stCardCanvas');
  if (!preview || !canvas) return;

  const isStory = mode === 'story';
  const w = isStory ? 360 : 360;
  const h = isStory ? 640 : 360;

  canvas.innerHTML = stBuildCardHTML(mode);
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';
  preview.style.display = '';
  preview.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function stCloseCard() {
  const preview = document.getElementById('stCardPreview');
  if (preview) preview.style.display = 'none';
  _stCardMode = null;
}

function stBuildCardHTML(mode) {
  const plays = _stCurrentPlays;
  const isStory = mode === 'story';
  const label = stGetPeriodLabel();

  const artistCounts = {};
  for (const p of plays) artistCounts[p.artist] = (artistCounts[p.artist] || 0) + 1;
  const topArtists = Object.entries(artistCounts).sort((a, b) => b[1] - a[1]).slice(0, 5);

  const songCounts = {};
  for (const p of plays) {
    const sk = songKey(p);
    if (!songCounts[sk]) songCounts[sk] = { title: p.title, artist: p.artist, count: 0 };
    songCounts[sk].count++;
  }
  const topSongs = Object.values(songCounts).sort((a, b) => b.count - a.count).slice(0, 5);

  const artistsHTML = topArtists.map(([name, count], i) =>
    `<div class="stc-row"><span class="stc-rank">${i+1}</span><span class="stc-name">${esc(name)}</span><span class="stc-ct">${count.toLocaleString()}</span></div>`
  ).join('');
  const songsHTML = topSongs.map((s, i) =>
    `<div class="stc-row"><span class="stc-rank">${i+1}</span><div class="stc-name-wrap"><span class="stc-name">${esc(s.title)}</span><span class="stc-sub">${esc(s.artist)}</span></div><span class="stc-ct">${s.count.toLocaleString()}</span></div>`
  ).join('');

  const totalPlays = plays.length;
  const daySet = new Set(plays.map(p => { const d = tzDateOf(p); return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`; }));
  const artistSet = new Set(plays.map(p => p.artist.toLowerCase()));

  const layout = isStory ? 'flex-direction:column;' : 'flex-direction:column;';
  const cardH = isStory ? '640px' : '360px';
  const cardW = '360px';
  const topColDir = isStory ? 'column' : 'row';

  return `<div class="stc-root" style="width:${cardW};height:${cardH};background:linear-gradient(135deg,#0d1117 0%,#1a1f2e 50%,#0d1117 100%);padding:20px;box-sizing:border-box;display:flex;flex-direction:column;font-family:var(--font-mono);color:#e2e8f0;position:relative;overflow:hidden;">
    <div style="position:absolute;top:-40px;right:-40px;width:200px;height:200px;background:radial-gradient(circle,rgba(99,102,241,0.15) 0%,transparent 70%);pointer-events:none;"></div>
    <div class="stc-header" style="margin-bottom:${isStory?'16px':'10px'};">
      <div style="font-size:0.6rem;letter-spacing:0.15em;color:#6366f1;text-transform:uppercase;margin-bottom:2px;">dankcharts.fm</div>
      <div style="font-size:${isStory?'1.4rem':'1.1rem'};font-weight:700;color:#f8fafc;line-height:1.1;">${t('nav_soundtrack')}</div>
      <div style="font-size:0.75rem;color:#94a3b8;">${label}</div>
    </div>
    <div class="stc-stats" style="display:flex;gap:12px;margin-bottom:${isStory?'14px':'10px'};">
      <div style="text-align:center;flex:1;background:rgba(99,102,241,0.12);border-radius:8px;padding:8px 4px;">
        <div style="font-size:1.1rem;font-weight:700;color:#818cf8;">${totalPlays.toLocaleString()}</div>
        <div style="font-size:0.5rem;color:#94a3b8;letter-spacing:0.08em;text-transform:uppercase;">${tUnit('plays', totalPlays)}</div>
      </div>
      <div style="text-align:center;flex:1;background:rgba(99,102,241,0.12);border-radius:8px;padding:8px 4px;">
        <div style="font-size:1.1rem;font-weight:700;color:#818cf8;">${daySet.size.toLocaleString()}</div>
        <div style="font-size:0.5rem;color:#94a3b8;letter-spacing:0.08em;text-transform:uppercase;">${t('st_stat_days')}</div>
      </div>
      <div style="text-align:center;flex:1;background:rgba(99,102,241,0.12);border-radius:8px;padding:8px 4px;">
        <div style="font-size:1.1rem;font-weight:700;color:#818cf8;">${artistSet.size.toLocaleString()}</div>
        <div style="font-size:0.5rem;color:#94a3b8;letter-spacing:0.08em;text-transform:uppercase;">${t('st_stat_artists')}</div>
      </div>
    </div>
    <div style="display:flex;gap:10px;flex:1;flex-direction:${topColDir};">
      <div style="flex:1;">
        <div style="font-size:0.55rem;letter-spacing:0.12em;color:#6366f1;text-transform:uppercase;margin-bottom:6px;">${t('st_top_artists')}</div>
        ${artistsHTML}
      </div>
      <div style="flex:1;${isStory?'margin-top:10px;':''}">
        <div style="font-size:0.55rem;letter-spacing:0.12em;color:#6366f1;text-transform:uppercase;margin-bottom:6px;">${t('st_top_songs')}</div>
        ${songsHTML}
      </div>
    </div>
    <div style="margin-top:auto;padding-top:8px;text-align:center;font-size:0.5rem;color:#475569;letter-spacing:0.1em;">dankcharts.fm · ${t('nav_soundtrack')}</div>
  </div>
  <style>
    .stc-row{display:flex;align-items:center;gap:6px;margin-bottom:4px;font-size:0.65rem;}
    .stc-rank{color:#6366f1;font-weight:700;min-width:12px;}
    .stc-name{color:#e2e8f0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
    .stc-sub{display:block;font-size:0.5rem;color:#94a3b8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
    .stc-name-wrap{flex:1;min-width:0;}
    .stc-ct{color:#818cf8;font-size:0.6rem;white-space:nowrap;}
  </style>`;
}

async function stDownloadCard() {
  const canvas = document.getElementById('stCardCanvas');
  if (!canvas || !_stCardMode) return;
  const isStory = _stCardMode === 'story';
  const w = isStory ? 720 : 720;
  const h = isStory ? 1280 : 720;
  try {
    const cvs = await html2canvas(canvas, { scale: 2, useCORS: false, allowTaint: true, backgroundColor: null, logging: false, width: 360, height: isStory ? 640 : 360 });
    const link = document.createElement('a');
    link.download = `your-soundtrack-${stGetPeriodLabel().replace(/\s+/g,'-').toLowerCase()}-${_stCardMode}.png`;
    link.href = cvs.toDataURL('image/png');
    link.click();
  } catch (e) { console.error('Card download failed', e); }
}

// ─── CURRENT STREAK BANNER ──────────────────────────────────
function computeCurrentStreak(plays) {
  if (!plays || plays.length < 3) return null;
  const p0 = plays[0];
  const sk0 = songKey(p0);

  // 1. Song Streak — same song 3+ consecutive (highest precedence)
  let songCount = 0;
  for (const p of plays) {
    if (songKey(p) === sk0) songCount++;
    else break;
  }
  if (songCount >= 3) return { type: 'song', count: songCount, title: p0.title, artist: p0.artist, album: p0.album };

  // 2. Album Streak — same album+artist 3+ consecutive
  if (p0.album && p0.album !== '—') {
    const primaryArtist0 = albumArtist(p0);
    const aa0 = p0.album.toLowerCase().trim() + '\x00' + primaryArtist0.toLowerCase().trim();
    let albumCount = 0;
    for (const p of plays) {
      if (p.album && p.album !== '—' &&
          p.album.toLowerCase().trim() + '\x00' + albumArtist(p).toLowerCase().trim() === aa0)
        albumCount++;
      else break;
    }
    if (albumCount >= 3) {
      const result = { type: 'album', count: albumCount, album: p0.album, artist: primaryArtist0 };
      // If the same artist's run extends past this album's boundary (e.g. a
      // full-discography binge), attach it so the banner can show both streaks.
      const a0lc = primaryArtist0.toLowerCase().trim();
      let artistCount = 0;
      for (const p of plays) {
        const pArtists = (p.artists || splitArtists(p.artist)).map(a => a.toLowerCase().trim());
        if (pArtists.includes(a0lc)) artistCount++;
        else break;
      }
      if (artistCount > albumCount) result.artistStreak = { count: artistCount, artist: primaryArtist0 };
      return result;
    }
  }

  // 3. Artist Streak — same artist (respecting comma-split rule) 3+ consecutive plays
  const artists0 = splitArtists(p0.artist);
  let bestStreakArtist = null, bestStreakCount = 0;
  for (const a0 of artists0) {
    const a0lc = a0.toLowerCase().trim();
    let cnt = 0;
    for (const p of plays) {
      const pArtists = (p.artists || splitArtists(p.artist)).map(a => a.toLowerCase().trim());
      if (pArtists.includes(a0lc)) cnt++;
      else break;
    }
    if (cnt > bestStreakCount) { bestStreakCount = cnt; bestStreakArtist = a0; }
  }
  if (bestStreakCount >= 3) return { type: 'artist', count: bestStreakCount, artist: bestStreakArtist };

  // 4. Shuffle Streak — 5+ plays with no artist appearing 3+ times in a row
  let shuffleCount = 1;
  let runArtist = plays[0].artist.toLowerCase().trim();
  let runLen = 1;
  for (let i = 1; i < plays.length; i++) {
    const a = plays[i].artist.toLowerCase().trim();
    if (a === runArtist) {
      runLen++;
      if (runLen > 2) break;
    } else {
      runArtist = a;
      runLen = 1;
    }
    shuffleCount++;
  }
  if (shuffleCount >= 5) return { type: 'shuffle', count: shuffleCount };

  return null;
}

function renderStreakBanner() {
  const el = document.getElementById('streakBanner');
  if (!el) return;
  if (!allPlays.length) { el.style.display = 'none'; return; }

  const streak = computeCurrentStreak(allPlays);
  if (!streak) { el.style.display = 'none'; return; }

  const icons  = { song: '🔂', album: '💿', artist: '🎤', shuffle: '🔀' };
  const labels = { song: 'SONG STREAK', album: 'ALBUM STREAK', artist: 'ARTIST STREAK', shuffle: 'SHUFFLE STREAK' };

  // When an album streak is nested inside a longer same-artist run (e.g. a
  // discography binge), the artist run is the real streak — it leads with
  // the icon/color/fire count, and the album becomes an inset "currently on"
  // chip rather than a competing stat.
  const nested = streak.type === 'album' && streak.artistStreak;
  const displayType  = nested ? 'artist' : streak.type;
  const displayCount = nested ? streak.artistStreak.count : streak.count;

  let subject = '';
  if (streak.type === 'song')   subject = `<em>"${esc(streak.title)}"</em> · ${esc(streak.artist)}`;
  else if (nested)                   subject = esc(streak.artistStreak.artist);
  else if (streak.type === 'album')  subject = `<em>${esc(streak.album)}</em> · ${esc(streak.artist)}`;
  else if (streak.type === 'artist') subject = esc(streak.artist);

  const nestedChip = nested
    ? `<span class="streak-banner-nested-chip">↳ 💿 <em>${esc(streak.album)}</em> · ${streak.count} straight</span>`
    : '';

  const thumbCount = displayCount;

  let artFallback = '';
  if (streak.type === 'artist') artFallback = initials(streak.artist);
  else if (streak.type === 'album') artFallback = initials(streak.album);
  else if (streak.type === 'song') artFallback = initials(streak.album && streak.album !== '—' ? streak.album : streak.title);
  else artFallback = initials(allPlays[0].artist);

  const thumbs = Array.from({ length: thumbCount }, (_, i) => {
    const p = allPlays[i];
    return `<div class="streak-mini-thumb" style="--i:${i}" title="${esc(p.title)} · ${esc(p.artist)}"><div class="streak-mini-init">${esc(artFallback)}</div></div>`;
  }).join('');

  el.className = `streak-banner streak-banner-${displayType}`;
  el.innerHTML = `
    <div class="streak-art-wrap">
      <img id="streakArtImg" class="streak-art" src="" alt="" style="display:none;"
           onerror="this.style.display='none';document.getElementById('streakArtInit').style.display='flex'">
      <div id="streakArtInit" class="streak-art-init">${esc(artFallback)}</div>
    </div>
    <div class="streak-banner-left">
      <span class="streak-banner-icon">${icons[displayType]}</span>
      <div class="streak-banner-meta">
        <span class="streak-banner-type">${labels[displayType]}</span>
        ${subject ? `<span class="streak-banner-subject">${subject}</span>` : ''}
        ${nestedChip}
      </div>
    </div>
    <div class="streak-banner-mid">${thumbs}</div>
    <div class="streak-banner-right">
      <span class="streak-fire-icon">🔥</span>
      <div class="streak-banner-count-col">
        <span class="streak-banner-num">${displayCount}</span>
        <span class="streak-banner-unit">in a row</span>
      </div>
    </div>
  `;
  el.style.display = '';

  _fetchStreakArt(streak).then(url => {
    const img = document.getElementById('streakArtImg');
    const init = document.getElementById('streakArtInit');
    if (img && init && url) {
      img.src = url;
      img.style.display = '';
      init.style.display = 'none';
    }
    // Fetch per-play art for each mini thumb individually, queued through the
    // shared imgQueue (see stLoyaltyImg above) instead of firing every thumb's
    // lookup at once.
    el.querySelectorAll('.streak-mini-thumb').forEach((thumb, i) => {
      const p = allPlays[i];
      if (!p) return;
      imgQueue = imgQueue.then(() => _fetchPlayArt(p).then(thumbUrl => {
        const src = thumbUrl || url;
        if (!src) return;
        const tImg = document.createElement('img');
        tImg.className = 'streak-mini-img';
        tImg.src = src;
        tImg.alt = '';
        tImg.onerror = () => tImg.remove();
        thumb.innerHTML = '';
        thumb.appendChild(tImg);
      }));
    });
  });
}

async function _fetchPlayArt(p) {
  try {
    const primaryArtist = albumArtist(p);
    if (p.album && p.album !== '—') {
      const prefKey = 'album:' + primaryArtist.toLowerCase() + '|||' + p.album.toLowerCase();
      const source = itemSourcePrefs[prefKey] || 'deezer';
      return await getAlbumImage(p.album, primaryArtist, source);
    }
    const prefKey = 'song:' + p.artist.toLowerCase() + '|||' + p.title.toLowerCase();
    const source = itemSourcePrefs[prefKey] || 'deezer';
    return await getTrackImage(p.title, primaryArtist, source);
  } catch (e) { return null; }
}

async function _fetchStreakArt(streak) {
  try {
    if (streak.type === 'song') {
      return (streak.album && streak.album !== '—')
        ? await getAlbumImage(streak.album, streak.artist)
        : await getTrackImage(streak.title, streak.artist);
    }
    if (streak.type === 'album')  return await getAlbumImage(streak.album, streak.artist);
    if (streak.type === 'artist') return await getArtistImage(streak.artist);
    // Shuffle: most recent play's album art
    const p = allPlays[0];
    return (p.album && p.album !== '—')
      ? await getAlbumImage(p.album, p.artist)
      : await getArtistImage(p.artist);
  } catch (e) { return null; }
}

// Proactively wake the Render backend on page load so it's ready before the first play button click
_ytPrewarmBackend();

// ─── CHARTS GUIDE VIEW ─────────────────────────────────────────
/* ═══════════════════════════════════════════════════════════════════
   FIRST-RUN WELCOME GATE
   The Charts Guide only works as an onboarding surface if people
   actually reach it, and nothing on a freshly loaded Weekly chart
   suggests it exists. So the first visit is gated: a blocking overlay
   that offers the tour or the guide, and records that it was shown.

   dc_guide_seen stores the guide version the user was last introduced
   to, not a boolean — bumping CG_GUIDE_VERSION re-introduces everyone
   once after a substantial rewrite, then never again.
   ═══════════════════════════════════════════════════════════════════ */
const CG_GUIDE_VERSION = 2;

function dcGuideSeenVersion() {
  try { return parseInt(localStorage.getItem('dc_guide_seen') || '0', 10) || 0; } catch (e) { return 0; }
}

function dcMaybeShowWelcomeGate() {
  if (dcGuideSeenVersion() >= CG_GUIDE_VERSION) return;
  const gate = document.getElementById('cgWelcomeGate');
  if (!gate) return;

  /* Step 1 reflects live setup state — someone who just picked a source on the
     landing screen shouldn't be told to go and pick one. */
  const configured = !needsOnboarding();
  const srcLabel   = { lastfm: 'Last.fm', sheets: 'Google Sheets', file: 'CSV upload' }[getDataSource()] || 'Your source';
  const noteEl     = document.getElementById('cgGateSrcNote');
  const stateEl    = document.getElementById('cgGateSrcState');
  const stepEl     = document.getElementById('cgGateStep1');
  if (configured) {
    if (noteEl)  noteEl.textContent  = srcLabel + ' is connected — your plays are loading now.';
    if (stateEl) stateEl.textContent = '✓';
    if (stepEl)  stepEl.classList.add('done');
  } else {
    if (noteEl)  noteEl.textContent  = 'Last.fm, a Google Sheet, or a CSV upload — your data, your choice.';
    if (stateEl) stateEl.textContent = '';
    if (stepEl)  stepEl.classList.remove('done');
  }

  gate.style.display = 'flex';
  document.body.classList.add('cg-gate-open');
  setTimeout(() => gate.querySelector('.cg-gate-btn-primary')?.focus(), 80);
}

/* The only three exits from the gate. Each one records the visit, so the
   overlay never blocks a second load regardless of which was chosen. */
function dcGateChoose(mode) {
  try { localStorage.setItem('dc_guide_seen', String(CG_GUIDE_VERSION)); } catch (e) {}
  const gate = document.getElementById('cgWelcomeGate');
  if (gate) gate.style.display = 'none';
  document.body.classList.remove('cg-gate-open');
  if (mode === 'skip') return;

  document.querySelector('#periodNav button[data-period="chartsguide"]')?.click();
  // Let the guide paint before the tour starts driving the nav around
  if (mode === 'tour') setTimeout(() => dcStartChartsGuideTour(), 450);
}

/* Re-open the gate on demand (from the guide hero) — does not touch dc_guide_seen. */
function dcReplayWelcomeGate() {
  const gate = document.getElementById('cgWelcomeGate');
  if (!gate) return;
  gate.style.display = 'flex';
  document.body.classList.add('cg-gate-open');
}

